                    ),
                    systemImage: "person.crop.rectangle.stack",
                    selection: $idolRecognitionMode,
                    identifier: "chekinana.scan.idol-recognition"
                )

                if idolRecognitionMode == .specified {
                    Divider().padding(.leading, 46)
                    ChekinanaNativeIdolSelectionGrid(
                        idols: ChekinanaVisibilityPolicy.visibleIdols(
                            idols,
                            hiddenIDs: hiddenIdols.hiddenIDs
                        ),
                        selectedIDs: $specifiedIdolIDs,
                        identifierPrefix: "chekinana.scan.specified-idol",
                        allowsMultipleSelection: true,
                        includesUnassigned: false,
                        showsOptionBackground: false
                    )
                    .padding(.horizontal, 12)
                    .padding(.vertical, 14)

                } else if idolRecognitionMode == .enabled {
                    Divider().padding(.leading, 46)
                    VStack(alignment: .leading, spacing: 12) {
                        Text(ChekinanaProductCopy.text(
                            "scan.candidates.unassigned_hint",
                            "If the Idol may be outside the selected range, select Unassigned."
                        ))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                        ChekinanaNativeIdolSelectionGrid(
                            idols: patternIdols,
                            selectedIDs: $candidateSelection.selectedIDs,
                            identifierPrefix: "chekinana.scan.candidate",
                            allowsMultipleSelection: true,
                            includesUnassigned: false,
                            showsOptionBackground: false,
                            candidateUnassigned: $includesUnassigned
                        )
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 14)
                    .accessibilityIdentifier("chekinana.scan.candidates")
                }
                if showsSleevesOption {
                    Divider().padding(.leading, 46)
