    private func scanProgressRow(
        title: String,
        completed: Int,
        total: Int,
        totalIsFinal: Bool = true
    ) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack {
                Text(title).font(.subheadline)
                Spacer()
                Text("\(completed)/\(total)")
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
            }
            GeometryReader { geometry in
                ZStack(alignment: .leading) {
                    Rectangle().fill(Color.secondary.opacity(0.2))
                    Rectangle()
                        .fill(ChekinanaProductTheme.accent)
                        .frame(width: geometry.size.width * progressFraction(
                            completed: completed,
                            total: total,
                            totalIsFinal: totalIsFinal
                        ))
                }
            }
            .frame(height: 3)
            .clipShape(Capsule())
        }
    }

    private func progressFraction(completed: Int, total: Int, totalIsFinal: Bool = true) -> CGFloat {
        guard total > 0 else { return 0 }
        return min(max(CGFloat(completed) / CGFloat(total), 0), totalIsFinal ? 1 : 0.99)
    }

    @MainActor
    private func beginNativeScan() {
        guard processingTask == nil,
              !isProcessing,
              !hasReviewSession,
              !inputRotationRegistry.hasInFlightRotations else { return }
        let generation = UUID()
        processingGeneration = generation
        isProcessing = true
        recognitionSkipControl = ChekinanaScanRecognitionSkipControl()
        didSkipRecognition = false
        cancellationMessage = nil
        activeScannerTaskIDs.removeAll()
        reviewCards = []
        activeScanResultTracker.removeAll()
        reviewWarningCount = 0
        taskProgress = ChekinanaScanSessionProgress(
            directInputs: nativeFixtureEnabled ? [false] : scanInputs.map(\.isDirect)
        ).value
        processingTask = Task { @MainActor in
            await startNativeScan(generation: generation)
        }
    }

    @MainActor
    private func cancelNativeScan() {
        guard isProcessing else { return }
        let completedCards = ChekinanaScanReviewCardReconciler.existing(
            activeScanResultTracker.cards,
            containsTemporaryCheki: confirmationLedger.containsTemporaryCheki
        )
        processingGeneration = UUID()
        processingTask?.cancel()
        processingTask = nil
        recognitionSkipControl = nil
        activeScannerTaskIDs.removeAll()
        isProcessing = false
        // The cancelled pipeline owns cleanup after its file readers drain.
        activeImportStagingDirectory = nil
        cancellationMessage = ChekinanaProductCopy.text("scan.canceled", "Canceled")
        reviewCards = completedCards
        if handOffCurrentCardsToReview(
            candidateSources: reviewSourceRegistry.sources
        ) {
            hasReviewSession = true
            isReviewPresented = true
        } else {
            reviewSourceRegistry = ChekinanaScanReviewSourceRegistry()
        }
        activeScanResultTracker.removeAll()
    }

    @MainActor
    private func skipRemainingRecognition() {
        guard isProcessing, !didSkipRecognition,
              dateRecognitionMode == .enabled || idolRecognitionMode == .enabled,
              taskProgress.imageTotal > 0,
              taskProgress.imageCompleted >= taskProgress.imageTotal,
              let recognitionSkipControl else { return }
        didSkipRecognition = true
        recognitionSkipControl.skipRemainingRecognition()
    }

    @MainActor
    private func startNativeScan(generation: UUID) async {
        defer {
            if processingGeneration == generation {
                isProcessing = false
                processingTask = nil
                recognitionSkipControl = nil
                activeScannerTaskIDs.removeAll()
            }
        }
        let tightBoundaries = UserDefaults.standard.bool(forKey: ChekinanaScanBoundaryPreference.defaultsKey)
        let dateBounds = scannerDateBounds
        guard dateRecognitionMode == .disabled || dateBounds != nil else {
            errorMessage = ChekinanaProductCopy.text(
                "scan.date_configuration_invalid",
                "The date configuration is invalid. Please choose again."
            )
            return
        }
        let validIDs = idolRecognitionMode == .enabled
            ? patternIdols.map(\.id).filter(candidateSelection.selectedIDs.contains)
            : []
        func preparedCommand(direct: Bool) -> String? {
            let preparation = ChekinanaScannerConfiguration.prepareTypedCommands(
                ["scancheki"],
                baseURLResolution: nativeFixtureEnabled
                    ? .resolved(ChekinanaScannerConfiguration.productionBaseURL)
                    : ChekinanaScannerConfiguration.configuredBaseURL(),
                dateRecognitionEnabled: dateRecognitionMode != .disabled,
                dateBounds: dateBounds,
                idolRecognitionEnabled: ChekinanaScanIdolModePolicy
                    .requestsAutomaticRecognition(mode: idolRecognitionMode),
                idolCandidateIDs: validIDs,
                includeUnassignedCandidate: idolRecognitionMode == .enabled && includesUnassigned,
                sleevesEnabled: sleevesEnabled,
                directInputEnabled: direct
            )
            guard case .ready(let commands) = preparation else {
                if case .rejected(let failure) = preparation {
                    errorMessage = failure.userMessage
                }
                return nil
            }
            return commands.first
        }
        guard let standardCommand = preparedCommand(direct: false),
              let directCommand = preparedCommand(direct: true) else { return }

        var sessionTemporaryIDs = Set<UUID>()
        do {
            let sessionInputs = scanInputs
            let sessionSources = sessionInputs.map(\.descriptor)
            var sessionProgress = ChekinanaScanSessionProgress(directInputs: sessionInputs.map(\.isDirect))
            let sessionRecognitionGate = ChekinanaDirectRecognitionGate()
            let sessionDateRequestGate = ChekinanaDirectDateRequestGate(limit: 16)
            let sessionBodyPoseLimiter = ChekinanaBodyPoseLimiter()
            reviewSourceRegistry = ChekinanaScanReviewSourceRegistry(sources: sessionSources)
            try Task.checkCancellation()
            guard processingGeneration == generation else { throw CancellationError() }
            var aggregatedCards: [ChekinanaChekiCard] = []
            var aggregateWarningCount = 0
            var lastFailureMessage: String?

            func protectReviewCards(
                in output: ChekinanaCommandResponse,
                inputIndex: Int
            ) -> ChekinanaCommandResponse {
                guard case .chekiScannedCards(_, let warningCount, let cards) = output else {
                    return output
                }
                let forcedIdols = specifiedIdols
                let resolvedCards = cards.map { card in
                    guard !forcedIdols.isEmpty,
                          confirmationLedger.replaceTemporaryChekiIdols(
                            id: card.id,
                            idolIDs: forcedIdols.map(\.id)
                          ) else { return card }
                    return card.replacingIdolNames(forcedIdols.map(\.name))
                }
                let hiddenCardIDs = ChekinanaHiddenTemporaryReviewPolicy.hiddenCardIDs(
                    resolvedCards,
                    hiddenIdolIDs: hiddenIdols.hiddenIDs,
                    idolIDs: { confirmationLedger.temporaryCheki($0)?.idolIDs }
                )
                for id in hiddenCardIDs {
                    _ = confirmationLedger.discardTemporaryCheki(id: id)
                }
                let visibleCards = resolvedCards.filter { !hiddenCardIDs.contains($0.id) }
                let ids = visibleCards.map(\.id)
                guard processingGeneration == generation, !Task.isCancelled else {
                    // The executor may finish ledger insertion after Cancel.
                    // Those late objects were never visible to the user and
                    // must not become protected, retained temporary results.
                    for id in ids {
                        _ = confirmationLedger.discardTemporaryCheki(id: id)
                    }
                    return .text("error: canceled")
                }
                confirmationLedger.protectTemporaryChekisForReview(ids)
                sessionTemporaryIDs.formUnion(ids)
                // Ledger protection and partial-Review tracking share this
                // MainActor turn, so Cancel cannot strand an invisible,
                // permanently protected temporary result.
                activeScanResultTracker.record(visibleCards, at: inputIndex)
                return .chekiScannedCards(
                    visibleCards.count,
                    warningCount: warningCount,
                    visibleCards
                )
            }

            func discardSessionTemporaries() {
                for id in sessionTemporaryIDs {
                    _ = confirmationLedger.discardTemporaryCheki(id: id)
                }
                sessionTemporaryIDs.removeAll()
            }

            func accumulate(_ output: ChekinanaCommandResponse, attemptedSources: Int) {
                switch output {
                case .chekiScannedCards(_, let warningCount, let cards):
                    let hiddenCardIDs = ChekinanaHiddenTemporaryReviewPolicy.hiddenCardIDs(
                        cards,
                        hiddenIdolIDs: hiddenIdols.hiddenIDs,
                        idolIDs: { confirmationLedger.temporaryCheki($0)?.idolIDs }
                    )
                    for id in hiddenCardIDs {
                        _ = confirmationLedger.discardTemporaryCheki(id: id)
                    }
                    aggregatedCards.append(contentsOf: cards.filter {
                        !hiddenCardIDs.contains($0.id)
                    })
                    aggregateWarningCount += warningCount
                    guard processingGeneration == generation else { return }
                    reviewCards = aggregatedCards
                    reviewWarningCount = aggregateWarningCount
                case .text(let text):
                    aggregateWarningCount += max(1, attemptedSources)
                    lastFailureMessage = text.replacingOccurrences(of: "error: ", with: "")
                default:
                    aggregateWarningCount += max(1, attemptedSources)
                    lastFailureMessage = ChekinanaProductCopy.text(
                        "scan.error.unexpected_result",
                        "The scanner returned an unexpected result."
                    )
                }
            }

            func runDirectImportPipeline() async throws {
                let stagingDirectory = try ChekinanaImportStaging.createSessionDirectory()
                activeImportStagingDirectory = stagingDirectory
                defer {
                    ChekinanaImportStaging.removeSessionDirectory(stagingDirectory)
                    if activeImportStagingDirectory == stagingDirectory {
                        activeImportStagingDirectory = nil
                    }
                }
                let coordinator = ChekinanaImportPipelineCoordinator()
                let commitGate = ChekinanaDirectCommitGate()
                let tasks = sessionInputs.enumerated().map { index, input in
                    Task { @MainActor in
                        defer {
                            Task {
                                await commitGate.skip(index: index)
                                await coordinator.markRecognized(index)
                            }
                        }
                        do {
                            try Task.checkCancellation()
                            let staged = try await stageImportInput(
                                input,
                                in: stagingDirectory
                            )
                            try Task.checkCancellation()
                            guard processingGeneration == generation else { throw CancellationError() }
                            let executor = nativeScanExecutor(
                                tightBoundaries: tightBoundaries,
                                generation: generation,
                                directRecognitionGate: sessionRecognitionGate,
                                directDateRequestGate: sessionDateRequestGate,
                                bodyPoseLimiter: sessionBodyPoseLimiter,
                                directCommitGate: commitGate,
                                directCommitIndex: index,
                                scannerProcess: { _, _ in
                                    ChekinanaScannerProcessResult(
                                        images: [ChekinanaScannerResultImage(
                                            data: Data(),
                                            stagedFileURL: staged.fileURL,
                                            imagePixelWidth: staged.pixelWidth,
                                            imagePixelHeight: staged.pixelHeight,
                                            filenameExtension: "jpg",
                                            refitOriginalSource: staged.refitOriginalSource,
                                            inferredChekiSize: staged.inferredSize
                                        )],
                                        warningCount: 0
                                    )
                                }
                            ) { progress in
                                guard processingGeneration == generation,
                                      !Task.isCancelled else { return }
                                sessionProgress.receive(progress, at: index)
                                taskProgress = sessionProgress.value
                            }
                            let output = protectReviewCards(in: await executeNativeScan(
                                using: executor,
                                directCommand,
                                pendingChekiImages: [ChekinanaPendingChekiImage(
                                    data: Data(),
                                    filenameExtension: "jpg",
                                    sourceID: staged.sourceID,
                                    sourceOrigin: staged.sourceOrigin
                                )],
                                direct: true
                            ), inputIndex: index)
                            try Task.checkCancellation()
                            guard processingGeneration == generation else {
                                throw CancellationError()
                            }
                            sessionProgress.finishImage(at: index)
                            taskProgress = sessionProgress.value
                            try await coordinator.waitUntilResultCanPublish(at: index)
                            accumulate(output, attemptedSources: 1)
                        } catch is CancellationError {
                            return
                        } catch {
                            guard processingGeneration == generation, !Task.isCancelled else { return }
                            sessionProgress.finishImage(at: index)
                            taskProgress = sessionProgress.value
                            aggregateWarningCount += 1
                            lastFailureMessage = error.localizedDescription
                        }
                    }
                }
                await withTaskCancellationHandler {
                    for task in tasks { await task.value }
                } onCancel: {
                    tasks.forEach { $0.cancel() }
                }
                try Task.checkCancellation()
            }

            func runMixedInputPipeline() async throws {
                let stagingDirectory = try ChekinanaImportStaging.createSessionDirectory()
                activeImportStagingDirectory = stagingDirectory
                defer {
                    ChekinanaImportStaging.removeSessionDirectory(stagingDirectory)
                    if activeImportStagingDirectory == stagingDirectory {
                        activeImportStagingDirectory = nil
                    }
                }
                let coordinator = ChekinanaImportPipelineCoordinator()
                let commitGate = ChekinanaDirectCommitGate()
                await ChekinanaStreamingScanScheduler.runOverlappingRecognition(
                    sourceCount: sessionInputs.count
                ) { [self] index, finishImagePhase in
                    let input = sessionInputs[index]
                    defer {
                        Task {
                            await commitGate.skip(index: index)
                            await coordinator.markRecognized(index)
                        }
                    }
                    var acceptsProgress = true
                    defer { acceptsProgress = false }
                    let observe: ChekinanaCommandExecutor.ScanProgressObserver = { [self] progress in
                        guard acceptsProgress, processingGeneration == generation, !Task.isCancelled else { return }
                        sessionProgress.receive(progress, at: index)
                        taskProgress = sessionProgress.value
                        if progress.imageProcessTotal > 0,
                           progress.imageProcessedCount >= progress.imageProcessTotal {
                            finishImagePhase()
                        }
                    }
                    do {
                        try Task.checkCancellation()
                        guard processingGeneration == generation else { throw CancellationError() }
                        let output: ChekinanaCommandResponse
                        if input.isDirect {
                            let staged = try await stageImportInput(input, in: stagingDirectory)
                            defer { try? FileManager.default.removeItem(at: staged.fileURL) }
                            try Task.checkCancellation()
                            let executor = nativeScanExecutor(
                                tightBoundaries: tightBoundaries,
                                generation: generation,
                                directRecognitionGate: sessionRecognitionGate,
                                directDateRequestGate: sessionDateRequestGate,
                                bodyPoseLimiter: sessionBodyPoseLimiter,
                                directCommitGate: commitGate,
                                directCommitIndex: index,
                                scannerProcess: { _, _ in
                                    ChekinanaScannerProcessResult(images: [ChekinanaScannerResultImage(
                                        data: Data(), stagedFileURL: staged.fileURL,
                                        imagePixelWidth: staged.pixelWidth, imagePixelHeight: staged.pixelHeight,
                                        filenameExtension: "jpg", refitOriginalSource: staged.refitOriginalSource,
                                        inferredChekiSize: staged.inferredSize
                                    )], warningCount: 0)
                                },
                                progressObserver: observe
                            )
                            output = await executeNativeScan(
                                using: executor, directCommand,
                                pendingChekiImages: [ChekinanaPendingChekiImage(
                                    data: Data(), filenameExtension: "jpg",
                                    sourceID: staged.sourceID, sourceOrigin: staged.sourceOrigin
                                )], direct: true
                            )
                        } else {
                            let executor = nativeScanExecutor(
                                tightBoundaries: tightBoundaries,
                                generation: generation,
                                directRecognitionGate: sessionRecognitionGate,
                                directDateRequestGate: sessionDateRequestGate,
                                bodyPoseLimiter: sessionBodyPoseLimiter,
                                directCommitGate: commitGate,
                                directCommitIndex: index,
                                progressObserver: observe
                            )
                            output = await executeStreamingNativeScan(
                                using: executor, standardCommand, inputs: [input]
                            )
                        }
                        finishImagePhase()
                        let protected = protectReviewCards(in: output, inputIndex: index)
                        try Task.checkCancellation()
                        guard processingGeneration == generation else { throw CancellationError() }
                        sessionProgress.finishImage(at: index)
                        taskProgress = sessionProgress.value
                        try await coordinator.waitUntilResultCanPublish(at: index)
                        try Task.checkCancellation()
                        guard processingGeneration == generation else { throw CancellationError() }
                        accumulate(protected, attemptedSources: 1)
                    } catch is CancellationError {
                        return
                    } catch {
                        guard processingGeneration == generation, !Task.isCancelled else {
                            return
                        }
                        // A failed load has no executor progress callback.
                        sessionProgress.finishImage(at: index)
                        taskProgress = sessionProgress.value
                        finishImagePhase()
                        do { try await coordinator.waitUntilResultCanPublish(at: index) }
                        catch { return }
                        guard processingGeneration == generation, !Task.isCancelled else { return }
                        aggregateWarningCount += 1
                        lastFailureMessage = error.localizedDescription
                    }
                }
                try Task.checkCancellation()
            }

#if DEBUG
            if sessionInputs.allSatisfy(\.isDirect) && !nativeFixtureEnabled {
                try await runDirectImportPipeline()
            } else if ProcessInfo.processInfo.environment["CHEKINANA_NATIVE_SCAN_UI_STUB"] == "fixture" {
                let pending = ChekinanaMediaUITestFixture.pendingChekiImages()
                let executor = nativeScanExecutor(
                                tightBoundaries: tightBoundaries,
                    generation: generation,
                    directRecognitionGate: sessionRecognitionGate,
                    directDateRequestGate: sessionDateRequestGate,
                    bodyPoseLimiter: sessionBodyPoseLimiter
                ) { progress in
                    updateTaskProgress(progress, generation: generation)
                }
                accumulate(
                    protectReviewCards(in: await executeNativeScan(
                        using: executor,
                        standardCommand,
                        pendingChekiImages: pending,
                        direct: false
                    ), inputIndex: 0),
                    attemptedSources: pending.count
                )
            } else {
                try await runMixedInputPipeline()
            }
#else
            if sessionInputs.allSatisfy(\.isDirect) {
                try await runDirectImportPipeline()
            } else {
                try await runMixedInputPipeline()
            }
#endif

            aggregatedCards = ChekinanaScanReviewCardReconciler.existing(
                aggregatedCards,
                containsTemporaryCheki: confirmationLedger.containsTemporaryCheki
            )
            try Task.checkCancellation()
            guard processingGeneration == generation else { throw CancellationError() }
            if !aggregatedCards.isEmpty {
                reviewCards = aggregatedCards
                _ = handOffCurrentCardsToReview(candidateSources: sessionSources)
                hasReviewSession = true
                reviewWarningCount = aggregateWarningCount
                isReviewPresented = true
                activeScanResultTracker.removeAll()
            } else {
                discardSessionTemporaries()
                activeScanResultTracker.removeAll()
                reviewSourceRegistry = ChekinanaScanReviewSourceRegistry()
                errorMessage = lastFailureMessage
                    ?? ChekinanaProductMediaError.unreadableImage.localizedDescription
            }
        } catch is CancellationError {
            // Cancel keeps results already inserted into the ledger. The
            // button itself decides whether those completed cards enter Review.
        } catch {
            for id in sessionTemporaryIDs {
                _ = confirmationLedger.discardTemporaryCheki(id: id)
            }
            if processingGeneration == generation {
                activeScanResultTracker.removeAll()
                reviewSourceRegistry = ChekinanaScanReviewSourceRegistry()
                errorMessage = error.localizedDescription
            }
        }
    }

    @MainActor
    private func stageImportInput(
        _ input: ChekinanaNativeScanInput,
        in directory: URL
    ) async throws -> ChekinanaStagedImport {
        let loaded = try await ChekinanaProductMediaLoader.load(input)
        try Task.checkCancellation()
        let normalized = try await ChekinanaLocalImportChekiProcessor.normalize(
            loaded.data,
            appliesWhiteBalance: true
        )
        try Task.checkCancellation()
        let fileURL = try ChekinanaImportStaging.writeJPEG(
            normalized.data,
            in: directory
        )
        return ChekinanaStagedImport(
            refitOriginalSource: ChekinanaLocalImportChekiProcessor.makeRefitOriginalSource(loaded.data),
            fileURL: fileURL,
            sourceID: loaded.sourceID,
            sourceOrigin: loaded.sourceOrigin,
            inferredSize: normalized.inferredSize,
            pixelWidth: normalized.width,
            pixelHeight: normalized.height
        )
    }

    @MainActor
    private func executeNativeScan(
        using executor: ChekinanaCommandExecutor,
        _ command: String,
        pendingChekiImages: [ChekinanaPendingChekiImage],
        direct: Bool
    ) async -> ChekinanaCommandResponse {
        let output = await executor.execute(
            command,
            pendingChekiImages: pendingChekiImages
        )
        return output
    }

    @MainActor
    private func executeStreamingNativeScan(
        using executor: ChekinanaCommandExecutor,
        _ command: String,
        inputs: [ChekinanaNativeScanInput]
    ) async -> ChekinanaCommandResponse {
        let output = await executor.executeStreamingScan(
            command,
            sourceCount: inputs.count
        ) { originalIndex in
            try await ChekinanaProductMediaLoader.load(inputs[originalIndex])
        }
        return output
    }

    @MainActor
    private func nativeScanExecutor(
        tightBoundaries: Bool,
        generation: UUID,
        directRecognitionGate: ChekinanaDirectRecognitionGate? = nil,
        directDateRequestGate: ChekinanaDirectDateRequestGate? = nil,
        bodyPoseLimiter: ChekinanaBodyPoseLimiter,
        directCommitGate: ChekinanaDirectCommitGate? = nil,
        directCommitIndex: Int? = nil,
        scannerProcess: ChekinanaCommandExecutor.ScannerProcess? = nil,
        progressObserver: @escaping ChekinanaCommandExecutor.ScanProgressObserver
    ) -> ChekinanaCommandExecutor {
#if DEBUG
        if scannerProcess == nil,
           ProcessInfo.processInfo.environment["CHEKINANA_NATIVE_SCAN_UI_STUB"] == "fixture" {
            let fallbackPattern = patternIdols.first?.recognitionPatterns.first
                ?? ChekinanaPatternDebugFixture.unitVector(0)
            return ChekinanaCommandExecutor(
                modelContext: modelContext,
                confirmationLedger: confirmationLedger,
                scannerProcess: { image, options in
                    let annotation: ChekinanaChekiDateAnnotationState
                    if options.requestsDateAnnotation,
                       let box = ChekinanaChekiDateBoundingBox(x1: 120, y1: 720, x2: 880, y2: 900),
                       let value = ChekinanaChekiDateAnnotation(
                        text: "2026.08.02",
                        precision: .fullDate,
                        boundingBox: box
                       ) {
                        annotation = .detected(value)
                    } else {
                        annotation = .notRequested
                    }
                    return ChekinanaScannerProcessResult(images: [
                        ChekinanaScannerResultImage(
                            data: image.data,
                            dateAnnotationState: annotation
                        ),
                    ], warningCount: 1)
                },
                patternEncode: { _ in fallbackPattern },
                userAppearsDetect: { _ in false },
                bodyPoseLimiter: bodyPoseLimiter,
                scanProgressObserver: progressObserver,
                recognitionSkipControl: recognitionSkipControl,
                scannerTaskObserver: { taskID, isActive in
                    guard processingGeneration == generation else { return }
                    if isActive {
                        activeScannerTaskIDs.insert(taskID)
                    } else {
                        activeScannerTaskIDs.remove(taskID)
                    }
                },
                directRecognitionGate: directRecognitionGate,
                directDateRequestGate: directDateRequestGate,
                directCommitGate: directCommitGate,
                directCommitIndex: directCommitIndex,
                scanTightBoundaries: tightBoundaries
            )
        }
#endif
        return ChekinanaCommandExecutor(
            modelContext: modelContext,
            confirmationLedger: confirmationLedger,
            scannerProcess: scannerProcess,
            bodyPoseLimiter: bodyPoseLimiter,
            scanProgressObserver: progressObserver,
            recognitionSkipControl: recognitionSkipControl,
            scannerTaskObserver: { taskID, isActive in
                guard processingGeneration == generation else { return }
                if isActive {
                    activeScannerTaskIDs.insert(taskID)
                } else {
                    activeScannerTaskIDs.remove(taskID)
                }
            },
            directRecognitionGate: directRecognitionGate,
            directDateRequestGate: directDateRequestGate,
            directCommitGate: directCommitGate,
            directCommitIndex: directCommitIndex,
            usesLocalDirectProcessing: true,
            usesRemoteScanner: false,
            scanTightBoundaries: tightBoundaries
        )
    }

    @MainActor
    private func updateTaskProgress(
        _ progress: ChekinanaScanProgress,
        generation: UUID
    ) {
        guard processingGeneration == generation, !Task.isCancelled else { return }
        taskProgress = ChekinanaScanTaskProgress(
            imageCompleted: min(progress.imageProcessedCount, progress.imageProcessTotal),
            imageTotal: progress.imageProcessTotal,
            dateCompleted: min(progress.dateCompletedCount, progress.dateTotalCount),
            dateTotal: progress.dateTotalCount,
            idolCompleted: min(progress.idolCompletedCount, progress.idolTotalCount),
            idolTotal: progress.idolTotalCount
        )
    }

    private func scanProgressText(
        _ progress: ChekinanaScanProgress,
        directInputEnabled: Bool
    ) -> String {
        let source = ChekinanaProductCopy.format(
            "scan.progress.source",
            "Source %1$lld/%2$lld",
            Int64(progress.sourceIndex),
            Int64(progress.sourceCount)
        )
        let totals = ChekinanaProductCopy.format(
            "scan.progress.totals",
            "Total acquired %1$lld · prepared %2$lld",
            Int64(progress.downloadedResultCount),
            Int64(progress.preparedResultCount)
        )
        switch progress.stage {
        case .backend(let phase, let published, let downloaded, let expected):
            let phaseText = scannerPhaseText(
                phase,
                directInputEnabled: directInputEnabled
            )
            let publishedText = expected.map {
                ChekinanaProductCopy.format(
                    "scan.progress.published_expected",
                    "Published %1$lld/%2$lld",
                    Int64(published),
                    Int64($0)
                )
            } ?? ChekinanaProductCopy.format(
                "scan.progress.published",
                "Published %lld",
                Int64(published)
            )
            let downloadedText = ChekinanaProductCopy.format(
                "scan.progress.downloaded",
                "Downloaded %lld",
                Int64(downloaded)
            )
            return "\(source) · \(phaseText)\n\(publishedText) · \(downloadedText) · \(totals)"
        case .preparingResult(let index, let count, let recognizesIdol):
            let action = recognizesIdol
                ? ChekinanaProductCopy.format(
                    "scan.progress.recognizing_idol",
                    "Recognizing Idols on device %1$lld/%2$lld",
                    Int64(index),
                    Int64(count)
                )
                : directInputEnabled
                    ? ChekinanaProductCopy.format(
                        "scan.progress.preparing_direct",
                        "Preparing Cheki %1$lld/%2$lld",
                        Int64(index),
                        Int64(count)
                    )
                    : ChekinanaProductCopy.format(
                        "scan.progress.preparing_cheki",
                        "Preparing extracted Cheki %1$lld/%2$lld",
                        Int64(index),
                        Int64(count)
                    )
            return "\(source) · \(action)\n\(totals)"
        case .generatingPreview:
            return "\(source) · \(ChekinanaProductCopy.text("scan.progress.generating_preview", "Generating preview"))\n\(totals)"
        }
    }

    private func scannerPhaseText(
        _ phase: String?,
        directInputEnabled: Bool
    ) -> String {
        ChekinanaScannerPhasePresentation.text(
            phase,
            directInputEnabled: directInputEnabled
        )
    }
}

enum ChekinanaScannerPhasePresentation {
    static func text(
        _ phase: String?,
        directInputEnabled: Bool
    ) -> String {
        let normalized = phase?.lowercased() ?? ""
        if normalized == "runtime_offline" {
            return ChekinanaProductCopy.text("scan.phase.runtime_offline", "Starting backend")
        }
        if normalized == "runtime_starting" {
            return ChekinanaProductCopy.text("scan.phase.runtime_starting", "Backend is starting")
        }
        if normalized == "runtime_ready" {
            return ChekinanaProductCopy.text("scan.phase.runtime_ready", "Backend ready")
        }
        if normalized == "runtime_failed" {
            return ChekinanaProductCopy.text("scan.phase.runtime_failed", "Backend failed to start")
        }
        if normalized == "waiting" || normalized == "queued" {
            return ChekinanaProductCopy.text("scan.phase.waiting", "Waiting in backend queue")
        }
        if normalized == "loading" {
            return ChekinanaProductCopy.text("scan.phase.loading", "Backend is reading the source image")
        }
        if normalized == "direct_processing" {
            return ChekinanaProductCopy.text("scan.phase.direct_processing", "Normalizing the full Cheki")
        }
        if normalized == "detecting" {
            return directInputEnabled
                ? ChekinanaProductCopy.text("scan.phase.direct_processing", "Normalizing the full Cheki")
                : ChekinanaProductCopy.text("scan.phase.detecting", "Detecting Cheki")
        }
        if normalized == "extracting" {
            return directInputEnabled
                ? ChekinanaProductCopy.text("scan.phase.processing_direct", "Processing the full Cheki")
                : ChekinanaProductCopy.text("scan.phase.extracting", "Extracting each Cheki")
        }
        if normalized == "retrieving_results_with_date" {
            return ChekinanaProductCopy.text("scan.phase.retrieving_with_date", "Retrieving results and recognizing dates")
        }
        if normalized == "retrieving_results" {
            return ChekinanaProductCopy.text("scan.phase.retrieving", "Retrieving results")
        }
        if normalized.contains("download") || normalized.contains("result") {
            return ChekinanaProductCopy.text("scan.phase.retrieving", "Retrieving results")
        }
        if normalized.contains("extract")
            || normalized.contains("segment")
            || normalized.contains("sam") {
            return ChekinanaProductCopy.text("scan.phase.extracting", "Extracting each Cheki")
        }
        if ["completed", "complete", "done", "success", "finished"]
            .contains(normalized) {
            return ChekinanaProductCopy.text("scan.phase.completed", "Extraction complete")
        }
        return ChekinanaProductCopy.text("scan.phase.processing", "Backend processing")
    }
}

struct ChekinanaCapturedPhoto: Equatable, Sendable {
    let fileURL: URL
    let filenameExtension: String
}

struct ChekinanaNativeScanInput: Identifiable {
    enum Payload {
        case library(PhotosPickerItem)
        case camera(ChekinanaCapturedPhoto)
    }

    let id: UUID
    private(set) var payload: Payload
    let isDirect: Bool
    var rotationQuarterTurns: Int
    private(set) var libraryLoadRevision: UInt64 = 0

    struct PreviewLoadIdentity: Equatable {
        let sourceID: UUID
        let libraryRevision: UInt64
    }

    var previewLoadIdentity: PreviewLoadIdentity {
        .init(sourceID: id, libraryRevision: libraryLoadRevision)
    }

    mutating func refreshUnavailableLibraryItem(_ item: PhotosPickerItem) {
        // Preselected results can carry empty providers. Keep a usable prior
        // provider, but allow a newly readable result to repair an empty one.
        guard case .library(let previous) = payload,
              previous.supportedContentTypes.isEmpty,
              !item.supportedContentTypes.isEmpty else { return }
        payload = .library(item)
        libraryLoadRevision &+= 1
    }

    init(
        id: UUID,
        payload: Payload,
        isDirect: Bool = false,
        rotationQuarterTurns: Int = 0
    ) {
        self.id = id
        self.payload = payload
        self.isDirect = isDirect
        self.rotationQuarterTurns = Self.normalizedQuarterTurns(rotationQuarterTurns)
    }

    static func normalizedQuarterTurns(_ value: Int) -> Int {
        let remainder = value % 4
        return remainder >= 0 ? remainder : remainder + 4
    }

    var nextCounterclockwiseRotationQuarterTurns: Int {
        Self.normalizedQuarterTurns(rotationQuarterTurns + 1)
    }

    var descriptor: ChekinanaScanSourceDescriptor {
        ChekinanaScanSourceDescriptor(
            id: id,
            origin: origin
        )
    }

    var origin: ChekinanaScanSourceOrigin {
        switch payload {
        case .library: .library
        case .camera: .camera
        }
    }

    var libraryItem: PhotosPickerItem? {
        guard case .library(let item) = payload else { return nil }
        return item
    }

    var capturedPhoto: ChekinanaCapturedPhoto? {
        guard case .camera(let photo) = payload else { return nil }
        return photo
    }
}

struct ChekinanaNativeScanInputRotationRegistry: Equatable, Sendable {
    struct Entry: Equatable, Sendable {
        let token: UUID
        let expectedQuarterTurns: Int
    }

    private(set) var entries: [UUID: Entry] = [:]

    var hasInFlightRotations: Bool { !entries.isEmpty }

    func isRotating(sourceID: UUID) -> Bool {
        entries[sourceID] != nil
    }

    func allowsInputMutation(
        isProcessing: Bool,
        hasReviewSession: Bool
    ) -> Bool {
        !isProcessing && !hasReviewSession && !hasInFlightRotations
    }

    func allowsInputRemoval(
        sourceID: UUID,
        isProcessing: Bool,
        hasReviewSession: Bool
    ) -> Bool {
        !isProcessing && !hasReviewSession && !isRotating(sourceID: sourceID)
    }

    mutating func begin(
        sourceID: UUID,
        expectedQuarterTurns: Int,
        token: UUID = UUID()
    ) -> UUID? {
        guard entries[sourceID] == nil else { return nil }
        entries[sourceID] = Entry(
            token: token,
            expectedQuarterTurns: ChekinanaNativeScanInput
                .normalizedQuarterTurns(expectedQuarterTurns)
        )
        return token
    }

    mutating func commit(
        sourceID: UUID,
        token: UUID,
        currentQuarterTurns: Int,
        newQuarterTurns: Int
    ) -> Bool {
        guard let entry = entries[sourceID],
              entry.token == token,
              entry.expectedQuarterTurns
                == ChekinanaNativeScanInput.normalizedQuarterTurns(currentQuarterTurns),
              ChekinanaNativeScanInput.normalizedQuarterTurns(newQuarterTurns)
                == ChekinanaNativeScanInput.normalizedQuarterTurns(currentQuarterTurns + 1)
        else { return false }
        entries[sourceID] = nil
        return true
    }

    mutating func fail(sourceID: UUID, token: UUID) -> Bool {
        guard entries[sourceID]?.token == token else { return false }
        entries[sourceID] = nil
        return true
    }
}

enum ChekinanaCapturedPhotoStore {
    static var directory: URL {
        FileManager.default.temporaryDirectory
            .appendingPathComponent("ChekinanaCapturedScanSources", isDirectory: true)
    }

    static func save(
        _ data: Data,
        filenameExtension: String,
        id: UUID,
        directory: URL = directory
    ) throws -> ChekinanaCapturedPhoto {
        guard !data.isEmpty else { throw ChekinanaProductMediaError.unreadableImage }
        let ext = normalizedExtension(filenameExtension)
        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )
        let fileURL = directory.appendingPathComponent(
            "scan-camera-\(id.uuidString.lowercased()).\(ext)",
            isDirectory: false
        )
        guard fileURL.deletingLastPathComponent().standardizedFileURL
            == directory.standardizedFileURL else {
            throw ChekinanaProductMediaError.unreadableImage
        }
        try data.write(to: fileURL, options: [.atomic])
        return ChekinanaCapturedPhoto(
            fileURL: fileURL,
            filenameExtension: ext
        )
    }

    static func load(
        _ photo: ChekinanaCapturedPhoto,
        directory: URL = directory
    ) throws -> Data {
        guard isManaged(photo.fileURL, directory: directory) else {
            throw ChekinanaProductMediaError.unreadableImage
        }
        let values = try photo.fileURL.resourceValues(forKeys: [
            .isRegularFileKey,
            .isSymbolicLinkKey,
        ])
        guard values.isRegularFile == true,
              values.isSymbolicLink != true else {
            throw ChekinanaProductMediaError.unreadableImage
        }
        let data = try Data(contentsOf: photo.fileURL, options: [.mappedIfSafe])
        guard !data.isEmpty else { throw ChekinanaProductMediaError.unreadableImage }
        return data
    }

    static func isLoadable(
        _ photo: ChekinanaCapturedPhoto,
        directory: URL = directory
    ) -> Bool {
        guard isManaged(photo.fileURL, directory: directory),
              FileManager.default.isReadableFile(atPath: photo.fileURL.path),
              let values = try? photo.fileURL.resourceValues(forKeys: [
                  .isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey,
              ]) else { return false }
        return values.isRegularFile == true && values.isSymbolicLink != true
            && (values.fileSize ?? 0) > 0
    }

    static func remove(
        _ photo: ChekinanaCapturedPhoto,
        directory: URL = directory
    ) {
        guard isManaged(photo.fileURL, directory: directory) else { return }
        try? FileManager.default.removeItem(at: photo.fileURL)
    }

    static func cleanupStaleFiles(directory: URL = directory) {
        guard let urls = try? FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
            options: [.skipsSubdirectoryDescendants]
        ) else { return }
        for url in urls where isManaged(url, directory: directory) {
            let values = try? url.resourceValues(forKeys: [
                .isRegularFileKey,
                .isSymbolicLinkKey,
            ])
            guard values?.isRegularFile == true,
                  values?.isSymbolicLink != true else { continue }
            try? FileManager.default.removeItem(at: url)
        }
    }

    private static func normalizedExtension(_ value: String) -> String {
        switch value.lowercased() {
        case "heic", "heif": "heic"
        case "png": "png"
        default: "jpg"
        }
    }

    private static func isManaged(_ url: URL, directory: URL) -> Bool {
        let standardized = url.standardizedFileURL
        guard standardized.deletingLastPathComponent() == directory.standardizedFileURL,
              standardized.lastPathComponent.range(
                of: #"^scan-camera-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(heic|jpg|png)$"#,
                options: [.regularExpression, .caseInsensitive]
              ) != nil else {
            return false
        }
        return true
    }
}

enum ChekinanaNativeScanInputReconciler {
    static func retainedInputs(
        existing: [ChekinanaNativeScanInput],
        retainedIDs: Set<UUID>,
        origin: ChekinanaScanSourceOrigin,
        isDirect: Bool
    ) -> [ChekinanaNativeScanInput] {
        existing.filter { input in
            input.origin != origin
                || input.isDirect != isDirect
                || retainedIDs.contains(input.id)
        }
    }
}

enum ChekinanaProductMediaLoader {
    static func load(
        _ input: ChekinanaNativeScanInput
    ) async throws -> ChekinanaPendingChekiImage {
        let original = try await loadUnrotated(input)
        return try await applyingCounterclockwiseRotation(
            to: original,
            quarterTurns: input.rotationQuarterTurns
        )
    }

    static func loadUnrotated(
        _ input: ChekinanaNativeScanInput
    ) async throws -> ChekinanaPendingChekiImage {
        let original: ChekinanaPendingChekiImage
        switch input.payload {
        case .library(let item):
            original = try await load(item, sourceID: input.id)
        case .camera(let photo):
            let data = try await Task.detached(priority: .userInitiated) {
                try ChekinanaCapturedPhotoStore.load(photo)
            }.value
            original = ChekinanaPendingChekiImage(
                data: data,
                filenameExtension: photo.filenameExtension,
                sourceID: input.id,
                sourceOrigin: .camera
            )
        }
        return original
    }

    static func applyingCounterclockwiseRotation(
        to image: ChekinanaPendingChekiImage,
        quarterTurns: Int
    ) async throws -> ChekinanaPendingChekiImage {
        var rotated = image
        for _ in 0..<ChekinanaNativeScanInput.normalizedQuarterTurns(quarterTurns) {
            try Task.checkCancellation()
            rotated = try await ChekinanaScanCleanImageRotation.counterclockwise(rotated)
        }
        return rotated
    }

    static func rotatePreviewCounterclockwise(
        _ image: ChekinanaRenderedImage
    ) async throws -> ChekinanaRenderedImage {
        let task = Task.detached(priority: .userInitiated) {
            try Task.checkCancellation()
            guard let rotated = ChekinanaImageWorker.normalizedThumbnailOrientation(
                image.cgImage,
                exifOrientation: 8,
                maxDimension: max(image.cgImage.width, image.cgImage.height)
            ) else {
                throw ChekinanaProductMediaError.unreadableImage
            }
            try Task.checkCancellation()
            return ChekinanaRenderedImage(cgImage: rotated)
        }
        return try await withTaskCancellationHandler {
            try await task.value
        } onCancel: {
            task.cancel()
        }
    }

    static func load(
        _ item: PhotosPickerItem,
        sourceID: UUID? = nil
    ) async throws -> ChekinanaPendingChekiImage {
        let fileExtension = item.supportedContentTypes
            .compactMap(\.preferredFilenameExtension)
            .first ?? "jpg"
        if let image = try? await item.loadTransferable(type: ChekinanaTransferableImageData.self),
           !image.data.isEmpty {
            return ChekinanaPendingChekiImage(
                data: image.data,
                filenameExtension: fileExtension,
                sourceID: sourceID,
                sourceOrigin: .library
            )
        }
        if let data = try? await item.loadTransferable(type: Data.self), !data.isEmpty {
            return ChekinanaPendingChekiImage(
                data: data,
                filenameExtension: fileExtension,
                sourceID: sourceID,
                sourceOrigin: .library
            )
        }
        if let fallback = try? await item.loadTransferable(type: ChekinanaTransferableFallbackImageData.self),
           let jpeg = await ChekinanaImageWorker.reencodedJPEGData(from: fallback.data),
           !jpeg.isEmpty {
            return ChekinanaPendingChekiImage(
                data: jpeg,
                filenameExtension: "jpg",
                sourceID: sourceID,
                sourceOrigin: .library
            )
        }
        throw ChekinanaProductMediaError.unreadableImage
    }
}

enum ChekinanaProductMediaError: LocalizedError {
    case unreadableImage

    var errorDescription: String? {
        ChekinanaProductCopy.text(
            "scan.error.read_photo",
            "Unable to read the selected photo."
        )
    }
}

enum ChekinanaCameraPermission: Equatable, Sendable {
    case notDetermined
    case authorized
    case denied
    case restricted

    init(_ status: AVAuthorizationStatus) {
        switch status {
        case .notDetermined: self = .notDetermined
        case .authorized: self = .authorized
        case .denied: self = .denied
        case .restricted: self = .restricted
        @unknown default: self = .restricted
        }
    }
}

enum ChekinanaCameraState: Equatable, Sendable {
    case idle
    case requestingPermission
    case configuring
    case ready
    case capturing
    case interrupted(String)
    case unavailable(String)
    case failed(String)
}

enum ChekinanaCameraStateResolver {
    static func initial(
        permission: ChekinanaCameraPermission,
        hasBackCamera: Bool
    ) -> ChekinanaCameraState {
        switch permission {
        case .notDetermined:
            return .requestingPermission
        case .denied:
            return .unavailable(ChekinanaProductCopy.text(
                "scan.camera.access_denied",
                "Camera access is denied. Enable it in Settings to take photos."
            ))
        case .restricted:
            return .unavailable(ChekinanaProductCopy.text(
                "scan.camera.access_restricted",
                "Camera access is restricted on this device."
            ))
        case .authorized:
            return hasBackCamera
                ? .configuring
                : .unavailable(ChekinanaProductCopy.text(
                    "scan.camera.no_rear_camera",
                    "No rear camera is available on this device."
                ))
        }
    }

    static func captureResult(
        hasData: Bool,
        errorDescription: String? = nil
    ) -> ChekinanaCameraState {
        guard errorDescription == nil, hasData else {
            return .failed(errorDescription ?? ChekinanaProductCopy.text(
                "scan.camera.no_photo_data",
                "The camera did not return photo data."
            ))
        }
        return .ready
    }

    static func interruption(reason: Int?) -> ChekinanaCameraState {
        let message: String
        switch reason {
        case AVCaptureSession.InterruptionReason.audioDeviceInUseByAnotherClient.rawValue:
            message = ChekinanaProductCopy.text(
                "scan.camera.interruption.audio_in_use",
                "Camera audio is in use by another app."
            )
        case AVCaptureSession.InterruptionReason.videoDeviceInUseByAnotherClient.rawValue:
            message = ChekinanaProductCopy.text(
                "scan.camera.interruption.camera_in_use",
                "The camera is in use by another app."
            )
        case AVCaptureSession.InterruptionReason.videoDeviceNotAvailableWithMultipleForegroundApps.rawValue:
            message = ChekinanaProductCopy.text(
                "scan.camera.interruption.multiple_apps",
                "The camera is unavailable while multiple apps are in the foreground."
            )
        case AVCaptureSession.InterruptionReason.videoDeviceNotAvailableDueToSystemPressure.rawValue:
            message = ChekinanaProductCopy.text(
                "scan.camera.interruption.system_pressure",
                "The camera paused because of system pressure."
            )
        default:
            message = ChekinanaProductCopy.text(
                "scan.camera.interruption.generic",
                "The camera session was interrupted."
            )
        }
        return .interrupted(message)
    }

    static func runtimeError(code: Int, message: String) -> ChekinanaCameraState {
        if code == AVError.Code.mediaServicesWereReset.rawValue {
            return .configuring
        }
        return .failed(ChekinanaProductCopy.format(
            "scan.camera.runtime_error",
            "Camera runtime error: %@",
            message
        ))
    }
}

enum ChekinanaCameraVideoRotation {
    static func angle(for orientation: UIInterfaceOrientation) -> CGFloat? {
        switch orientation {
        case .portrait: 90
        case .portraitUpsideDown: 270
        case .landscapeLeft: 180
        case .landscapeRight: 0
        case .unknown: nil
        @unknown default: nil
        }
    }
}

enum ChekinanaCameraCaptureControls {
    static func canDismiss(isCaptureInFlight: Bool) -> Bool {
        !isCaptureInFlight
    }

    static func canCapture(
        state: ChekinanaCameraState,
        isCaptureInFlight: Bool
    ) -> Bool {
        state == .ready && !isCaptureInFlight
    }
}

struct ChekinanaCameraCaptureLifecycle: Sendable {
    typealias SystemCaptureID = Int64

    enum Capability: Equatable, Sendable {
        case idle
        case requestingPermission
        case configuring
        case running
        case interrupted(String)
        case unavailable(String)
        case failed(String)
    }

    struct Request: Equatable, Sendable {
        let systemID: SystemCaptureID
        let captureID: UUID
        let filenameExtension: String
        let generation: UInt64
        var isValid = true
        var processingCallbackReceived = false
        var processingSucceeded = false
        var finalCallbackReceived = false
    }

    struct Delivery: Equatable, Sendable {
        let systemID: SystemCaptureID
        let captureID: UUID
        let generation: UInt64
    }

    struct CaptureFailure: Equatable, Sendable {
        let captureID: UUID
        let generation: UInt64
        let message: String
    }

    struct Snapshot: Equatable, Sendable {
        let generation: UInt64
        let revision: UInt64
        let state: ChekinanaCameraState
        let isCaptureLocked: Bool
        let delivery: Delivery?
    }

    enum ProcessingSuccessResult: Equatable, Sendable {
        case ignored
        case awaitingFinal
        case delivery(Delivery)
    }

    enum FinalCallbackResult: Equatable, Sendable {
        case ignored
        case completed
        case delivery(Delivery)
        case failed(discardCaptureID: UUID)
    }

    private(set) var generation: UInt64 = 0
    private(set) var revision: UInt64 = 0
    private(set) var capability: Capability = .idle
    private(set) var requests: [SystemCaptureID: Request] = [:]
    private(set) var activeSystemID: SystemCaptureID?
    private(set) var delivery: Delivery?
    private(set) var captureFailure: CaptureFailure?

    var isCaptureLocked: Bool {
        activeSystemID != nil || delivery != nil
    }

    var canBeginCapture: Bool {
        capability == .running && !isCaptureLocked && captureFailure == nil
    }

    var state: ChekinanaCameraState {
        switch capability {
        case .idle:
            return .idle
        case .requestingPermission:
            return .requestingPermission
        case .configuring:
            return .configuring
        case .interrupted(let message):
            return .interrupted(message)
        case .unavailable(let message):
            return .unavailable(message)
        case .failed(let message):
            return .failed(message)
        case .running:
            if isCaptureLocked { return .capturing }
            if let captureFailure { return .failed(captureFailure.message) }
            return .ready
        }
    }

    var snapshot: Snapshot {
        Snapshot(
            generation: generation,
            revision: revision,
            state: state,
            isCaptureLocked: isCaptureLocked,
            delivery: delivery
        )
    }

    var ownedCaptureIDs: Set<UUID> {
        var result = Set(requests.values.lazy
            .filter(\.processingSucceeded)
            .map(\.captureID))
        if let delivery { result.insert(delivery.captureID) }
        return result
    }

    @discardableResult
    mutating func beginNewSession() -> Set<UUID> {
        let discardedCaptureIDs = ownedCaptureIDs
        advanceGeneration()
        for systemID in Array(requests.keys) {
            requests[systemID]?.isValid = false
        }
        activeSystemID = nil
        delivery = nil
        captureFailure = nil
        capability = .configuring
        pruneOldInvalidRequests()
        advanceRevision()
        return discardedCaptureIDs
    }

    @discardableResult
    mutating func tearDown() -> Set<UUID> {
        let discardedCaptureIDs = ownedCaptureIDs
        advanceGeneration()
        requests.removeAll(keepingCapacity: false)
        activeSystemID = nil
        delivery = nil
        captureFailure = nil
        capability = .idle
        advanceRevision()
        return discardedCaptureIDs
    }

    mutating func setCapability(_ value: Capability) {
        capability = value
        advanceRevision()
    }

    mutating func clearCaptureFailure() {
        guard captureFailure != nil else { return }
        captureFailure = nil
        advanceRevision()
    }

    mutating func register(
        systemID: SystemCaptureID,
        captureID: UUID,
        filenameExtension: String
    ) -> Bool {
        guard canBeginCapture, requests[systemID] == nil else { return false }
        requests[systemID] = Request(
            systemID: systemID,
            captureID: captureID,
            filenameExtension: filenameExtension,
            generation: generation
        )
        activeSystemID = systemID
        advanceRevision()
        return true
    }

    mutating func beginProcessing(systemID: SystemCaptureID) -> Request? {
        guard var request = requests[systemID],
              !request.processingCallbackReceived else { return nil }
        request.processingCallbackReceived = true
        requests[systemID] = request
        guard request.isValid,
              request.generation == generation,
              activeSystemID == systemID else {
            removeIfExhausted(systemID: systemID)
            return nil
        }
        return request
    }

    mutating func completeProcessingWithDelivery(
        systemID: SystemCaptureID
    ) -> ProcessingSuccessResult {
        guard var request = requests[systemID],
              request.processingCallbackReceived,
              request.isValid,
              request.generation == generation,
              activeSystemID == systemID,
              delivery == nil else { return .ignored }
        request.processingSucceeded = true
        requests[systemID] = request
        guard request.finalCallbackReceived else {
            advanceRevision()
            return .awaitingFinal
        }
        let value = publishDelivery(for: request)
        requests[systemID] = nil
        return .delivery(value)
    }

    private mutating func publishDelivery(for request: Request) -> Delivery {
        activeSystemID = nil
        let value = Delivery(
            systemID: request.systemID,
            captureID: request.captureID,
            generation: request.generation
        )
        delivery = value
        advanceRevision()
        return value
    }

    mutating func completeProcessingWithFailure(
        systemID: SystemCaptureID,
        errorDescription: String? = nil
    ) -> Bool {
        guard let request = requests[systemID],
              request.processingCallbackReceived,
              request.isValid,
              request.generation == generation,
              activeSystemID == systemID else {
            removeIfExhausted(systemID: systemID)
            return false
        }
        if let errorDescription {
            captureFailure = CaptureFailure(
                captureID: request.captureID,
                generation: request.generation,
                message: errorDescription
            )
        }
        activeSystemID = nil
        removeIfExhausted(systemID: systemID)
        advanceRevision()
        return true
    }

    mutating func finishCapture(
        systemID: SystemCaptureID,
        hasError: Bool,
        errorDescription: String? = nil
    ) -> FinalCallbackResult {
        guard var request = requests[systemID],
              !request.finalCallbackReceived else { return .ignored }
        request.finalCallbackReceived = true
        requests[systemID] = request

        guard request.isValid, request.generation == generation else {
            requests[systemID] = nil
            return .ignored
        }

        guard hasError else {
            guard request.processingCallbackReceived else { return .completed }
            guard request.processingSucceeded else {
                requests[systemID] = nil
                return .completed
            }
            let value = publishDelivery(for: request)
            requests[systemID] = nil
            return .delivery(value)
        }

        // Only a request that still owns a lock may publish its failure.
        // An earlier processing failure may already have been retried.
        if (activeSystemID == systemID || delivery?.systemID == systemID),
           let errorDescription {
            captureFailure = CaptureFailure(
                captureID: request.captureID,
                generation: request.generation,
                message: errorDescription
            )
        }
        if activeSystemID == systemID { activeSystemID = nil }
        if delivery?.systemID == systemID {
            delivery = nil
        }
        requests[systemID] = nil
        advanceRevision()
        return .failed(discardCaptureID: request.captureID)
    }

    mutating func consume(captureID: UUID, generation expectedGeneration: UInt64) -> Bool {
        guard let delivery,
              delivery.captureID == captureID,
              delivery.generation == expectedGeneration,
              expectedGeneration == generation else { return false }
        self.delivery = nil
        advanceRevision()
        return true
    }

    private mutating func removeIfExhausted(systemID: SystemCaptureID) {
        guard let request = requests[systemID],
              request.processingCallbackReceived,
              request.finalCallbackReceived else { return }
        requests[systemID] = nil
    }

    private mutating func advanceGeneration() {
        if generation == .max {
            generation = 1
            requests.removeAll(keepingCapacity: false)
        } else {
            generation += 1
        }
    }

    private mutating func advanceRevision() {
        revision = revision == .max ? 0 : revision + 1
    }

    private mutating func pruneOldInvalidRequests() {
        guard generation > 1 else { return }
        let oldestRetainedGeneration = generation - 1
        requests = requests.filter { _, request in
            request.isValid || request.generation >= oldestRetainedGeneration
        }
    }
}

enum ChekinanaScanReviewLifecycle {
    static func shouldDiscardAfterDeletion(
        cardsAreEmpty: Bool,
        hasCapturedPhoto: Bool
    ) -> Bool {
        cardsAreEmpty && !hasCapturedPhoto
    }

    static func closeDiscardsReview(cardsAreEmpty: Bool) -> Bool {
        cardsAreEmpty
    }
}

enum ChekinanaScanReviewInteractionPolicy {
    static func allowsCardInteraction(
        isSaving: Bool,
        isSavingToPhotos: Bool = false,
        isRotating: Bool,
        isDownloading: Bool
    ) -> Bool {
        !isSaving && !isSavingToPhotos && !isRotating && !isDownloading
    }

    static func allowsConfirmAll(
        isSaving: Bool,
        hasRotations: Bool,
        hasSizePreviews: Bool,
        hasDownloads: Bool
    ) -> Bool {
        !isSaving && !hasRotations && !hasSizePreviews && !hasDownloads
    }
}

enum ChekinanaScanReviewPhotoSavePolicy {
    static func orderedImageData(
        cardIDs: [UUID],
        imageData: (UUID) -> Data?
    ) -> [Data]? {
        var result: [Data] = []
        result.reserveCapacity(cardIDs.count)
        for cardID in cardIDs {
            guard let data = imageData(cardID), !data.isEmpty else { return nil }
            result.append(data)
        }
        return result
    }
}

struct ChekinanaCameraFocusCapabilities: Equatable {
    let supportsFocusPoint: Bool
    let supportsAutoFocus: Bool
    let supportsContinuousAutoFocus: Bool
    let supportsExposurePoint: Bool
    let supportsAutoExposure: Bool
    let supportsContinuousAutoExposure: Bool
}

struct ChekinanaCameraFocusPlan: Equatable {
    let point: CGPoint
    let focusMode: AVCaptureDevice.FocusMode?
    let exposureMode: AVCaptureDevice.ExposureMode?
}

enum ChekinanaCameraFocusPlanner {
    static func plan(
        point: CGPoint,
        capabilities: ChekinanaCameraFocusCapabilities
    ) -> ChekinanaCameraFocusPlan {
        let normalizedPoint = CGPoint(
            x: min(max(point.x, 0), 1),
            y: min(max(point.y, 0), 1)
        )
        let focusMode: AVCaptureDevice.FocusMode? = capabilities.supportsFocusPoint
            ? capabilities.supportsAutoFocus
                ? .autoFocus
                : capabilities.supportsContinuousAutoFocus ? .continuousAutoFocus : nil
            : nil
        let exposureMode: AVCaptureDevice.ExposureMode? = capabilities.supportsExposurePoint
            ? capabilities.supportsAutoExposure
                ? .autoExpose
                : capabilities.supportsContinuousAutoExposure ? .continuousAutoExposure : nil
            : nil
        return ChekinanaCameraFocusPlan(
            point: normalizedPoint,
            focusMode: focusMode,
            exposureMode: exposureMode
        )
    }
}

enum ChekinanaCameraPhotoQuality {
    static func largestDimensions(
        _ values: [CMVideoDimensions]
    ) -> CMVideoDimensions? {
        values
            .filter { $0.width > 0 && $0.height > 0 }
            .max { lhs, rhs in
                Int64(lhs.width) * Int64(lhs.height)
                    < Int64(rhs.width) * Int64(rhs.height)
            }
    }
}

