final class ChekinanaCameraController: NSObject, ObservableObject,
    AVCapturePhotoCaptureDelegate, @unchecked Sendable {
    struct CapturedSource: Identifiable, Equatable, Sendable {
        let id: UUID
        let photo: ChekinanaCapturedPhoto
        fileprivate let sessionGeneration: UInt64
    }

    /// A claim leaves Controller ownership on sessionQueue before Main sees it.
    /// The receiving Scan input must accept it exactly once. Unaccepted claims
    /// clean up their own file even when their UI owner has disappeared.
    final class CapturedClaim: @unchecked Sendable {
        let ownerID: UUID
        private let source: CapturedSource
        private let lock = NSLock()
        private var isPending = true

        fileprivate init(source: CapturedSource, ownerID: UUID) {
            self.source = source
            self.ownerID = ownerID
        }

        func accept() -> CapturedSource? {
            lock.lock()
            defer { lock.unlock() }
            guard isPending, ChekinanaCapturedPhotoStore.isLoadable(source.photo) else {
                return nil
            }
            isPending = false
            return source
        }

        func discard() {
            lock.lock()
            let shouldRemove = isPending
            isPending = false
            lock.unlock()
            if shouldRemove { ChekinanaCapturedPhotoStore.remove(source.photo) }
        }

        deinit { discard() }
    }

    @Published private(set) var state: ChekinanaCameraState = .idle
    @Published private(set) var latestCapture: CapturedSource?
    @Published private(set) var isCaptureInFlight = false

    let session = AVCaptureSession()

    private let sessionQueue = DispatchQueue(
        label: "top.chekinana.camera.session",
        qos: .userInitiated
    )
    private let photoOutput = AVCapturePhotoOutput()
    private var cameraDevice: AVCaptureDevice?
    private var maximumDimensions: CMVideoDimensions?
    private var configured = false
    private var lifecycle = ChekinanaCameraCaptureLifecycle()
    private var storedDeliveries: [UUID: ChekinanaCapturedPhoto] = [:]
    private var runIntent: UUID?
    private var publishedGeneration: UInt64 = 0
    private var publishedRevision: UInt64 = 0
    private var videoRotationAngle: CGFloat?
    private var notificationTokens: [NSObjectProtocol] = []

    override init() {
        super.init()
        let center = NotificationCenter.default
        notificationTokens = [
            center.addObserver(
                forName: AVCaptureSession.wasInterruptedNotification,
                object: session,
                queue: nil
            ) { [weak self] notification in
                self?.handleInterruption(notification)
            },
            center.addObserver(
                forName: AVCaptureSession.interruptionEndedNotification,
                object: session,
                queue: nil
            ) { [weak self] _ in
                self?.handleInterruptionEnded()
            },
            center.addObserver(
                forName: AVCaptureSession.runtimeErrorNotification,
                object: session,
                queue: nil
            ) { [weak self] notification in
                self?.handleRuntimeError(notification)
            },
        ]
    }

    deinit {
        for token in notificationTokens {
            NotificationCenter.default.removeObserver(token)
        }
        for photo in storedDeliveries.values {
            ChekinanaCapturedPhotoStore.remove(photo)
        }
    }

    func prepare() {
        let permission = ChekinanaCameraPermission(
            AVCaptureDevice.authorizationStatus(for: .video)
        )
        let intent = UUID()
        sessionQueue.async { [weak self] in
            guard let self else { return }
            self.runIntent = intent
            self.prepareOnSessionQueue(permission: permission, intent: intent)
        }
    }

    func resume() {
        let permission = ChekinanaCameraPermission(
            AVCaptureDevice.authorizationStatus(for: .video)
        )
        let intent = UUID()
        sessionQueue.async { [weak self] in
            guard let self else { return }
            self.runIntent = intent
            guard self.configured else {
                self.prepareOnSessionQueue(permission: permission, intent: intent)
                return
            }
            if case .interrupted = self.lifecycle.capability {
                self.publishSnapshot()
                return
            }
            guard !self.session.isRunning else {
                self.lifecycle.clearCaptureFailure()
                self.setCapability(.running)
                return
            }
            self.beginNewSession()
            self.session.startRunning()
            self.setCapability(
                self.session.isRunning
                    ? .running
                    : .failed(ChekinanaProductCopy.text(
                        "scan.camera.session_resume_failed",
                        "The camera session could not resume."
                    ))
            )
        }
    }

    func stop() {
        sessionQueue.async { [weak self] in
            guard let self else { return }
            self.runIntent = nil
            if self.session.isRunning { self.session.stopRunning() }
            self.discardStoredDeliveries(
                captureIDs: self.lifecycle.tearDown()
            )
            self.publishSnapshot()
        }
    }

    func capturePhoto() {
        sessionQueue.async { [weak self] in
            guard let self,
                  self.runIntent != nil,
                  self.configured,
                  self.session.isRunning,
                  self.lifecycle.canBeginCapture else { return }
            let settings: AVCapturePhotoSettings
            let captureExtension: String
            if self.photoOutput.availablePhotoCodecTypes.contains(.hevc) {
                settings = AVCapturePhotoSettings(format: [
                    AVVideoCodecKey: AVVideoCodecType.hevc,
                ])
                captureExtension = "heic"
            } else {
                settings = AVCapturePhotoSettings()
                captureExtension = "jpg"
            }
            settings.photoQualityPrioritization = .quality
            if let maximumDimensions = self.maximumDimensions {
                settings.maxPhotoDimensions = maximumDimensions
            }
            guard self.lifecycle.register(
                systemID: settings.uniqueID,
                captureID: UUID(),
                filenameExtension: captureExtension
            ) else { return }
            self.publishSnapshot()
            self.applyPhotoRotationIfSupported()
            self.photoOutput.capturePhoto(with: settings, delegate: self)
        }
    }

    func setVideoRotationAngle(_ angle: CGFloat?) {
        sessionQueue.async { [weak self] in
            guard let self else { return }
            self.videoRotationAngle = angle
            guard !self.lifecycle.isCaptureLocked else { return }
            self.applyPhotoRotationIfSupported()
        }
    }

    func focus(at devicePoint: CGPoint) {
        sessionQueue.async { [weak self] in
            guard let device = self?.cameraDevice else { return }
            let capabilities = ChekinanaCameraFocusCapabilities(
                supportsFocusPoint: device.isFocusPointOfInterestSupported,
                supportsAutoFocus: device.isFocusModeSupported(.autoFocus),
                supportsContinuousAutoFocus: device.isFocusModeSupported(.continuousAutoFocus),
                supportsExposurePoint: device.isExposurePointOfInterestSupported,
                supportsAutoExposure: device.isExposureModeSupported(.autoExpose),
                supportsContinuousAutoExposure: device.isExposureModeSupported(.continuousAutoExposure)
            )
            let plan = ChekinanaCameraFocusPlanner.plan(
                point: devicePoint,
                capabilities: capabilities
            )
            guard plan.focusMode != nil || plan.exposureMode != nil else { return }
            do {
                try device.lockForConfiguration()
                defer { device.unlockForConfiguration() }
                if let focusMode = plan.focusMode {
                    device.focusPointOfInterest = plan.point
                    device.focusMode = focusMode
                }
                if let exposureMode = plan.exposureMode {
                    device.exposurePointOfInterest = plan.point
                    device.exposureMode = exposureMode
                }
            } catch {
                self?.setCapability(.failed(ChekinanaProductCopy.format(
                    "scan.camera.focus_failed",
                    "Unable to focus the camera: %@",
                    error.localizedDescription
                )))
            }
        }
    }

    func claimLatestCapture(
        _ capture: CapturedSource,
        ownerID: UUID,
        completion: @escaping @MainActor @Sendable (CapturedClaim?) -> Void
    ) {
        sessionQueue.async { [weak self] in
            let claim = self?.claimOnSessionQueue(capture, ownerID: ownerID)
            DispatchQueue.main.async { completion(claim) }
        }
    }

    private func claimOnSessionQueue(
        _ capture: CapturedSource,
        ownerID: UUID
    ) -> CapturedClaim? {
        guard let delivery = lifecycle.delivery,
              delivery.captureID == capture.id,
              delivery.generation == capture.sessionGeneration,
              storedDeliveries[capture.id] == capture.photo,
              lifecycle.consume(
                  captureID: capture.id,
                  generation: capture.sessionGeneration
              ) else { return nil }
        // No queue hop separates consume from the file ownership transfer.
        storedDeliveries[capture.id] = nil
        let claim = CapturedClaim(source: capture, ownerID: ownerID)
        publishSnapshot()
        return claim
    }

    func photoOutput(
        _ output: AVCapturePhotoOutput,
        didFinishProcessingPhoto photo: AVCapturePhoto,
        error: (any Error)?
    ) {
        let systemID = photo.resolvedSettings.uniqueID
        let data = error == nil ? photo.fileDataRepresentation() : nil
        let errorDescription = error?.localizedDescription
        sessionQueue.async { [weak self] in
            guard let self else { return }
            guard let request = self.lifecycle.beginProcessing(systemID: systemID) else {
                return
            }
            let nextState = ChekinanaCameraStateResolver.captureResult(
                hasData: data?.isEmpty == false,
                errorDescription: errorDescription
            )
            guard nextState == .ready, let data else {
                if case .failed(let message) = nextState,
                   self.lifecycle.completeProcessingWithFailure(
                       systemID: systemID,
                       errorDescription: message
                   ) {
                    self.publishSnapshot()
                }
                return
            }
            do {
                let stored = try ChekinanaCapturedPhotoStore.save(
                    data,
                    filenameExtension: request.filenameExtension,
                    id: request.captureID
                )
                self.storedDeliveries[request.captureID] = stored
                switch self.lifecycle.completeProcessingWithDelivery(systemID: systemID) {
                case .ignored:
                    self.discardStoredDelivery(captureID: request.captureID)
                case .awaitingFinal, .delivery:
                    self.publishSnapshot()
                }
            } catch {
                if self.lifecycle.completeProcessingWithFailure(
                    systemID: systemID,
                    errorDescription: ChekinanaProductCopy.format(
                        "scan.camera.keep_photo_failed",
                        "Unable to keep the captured photo: %@",
                        error.localizedDescription
                    )
                ) {
                    self.publishSnapshot()
                }
            }
        }
    }

    func photoOutput(
        _ output: AVCapturePhotoOutput,
        didFinishCaptureFor resolvedSettings: AVCaptureResolvedPhotoSettings,
        error: (any Error)?
    ) {
        let systemID = resolvedSettings.uniqueID
        let errorDescription = error?.localizedDescription
        sessionQueue.async { [weak self] in
            guard let self else { return }
            switch self.lifecycle.finishCapture(
                systemID: systemID,
                hasError: error != nil,
                errorDescription: errorDescription ?? ChekinanaProductCopy.text(
                    "scan.camera.no_photo_data",
                    "The camera did not return photo data."
                )
            ) {
            case .ignored, .completed:
                break
            case .delivery:
                self.publishSnapshot()
            case .failed(let discardCaptureID):
                self.discardStoredDelivery(captureID: discardCaptureID)
                self.publishSnapshot()
            }
        }
    }

    private func prepareOnSessionQueue(
        permission: ChekinanaCameraPermission,
        intent: UUID
    ) {
        guard runIntent == intent else { return }
        switch permission {
        case .notDetermined:
            setCapability(.requestingPermission)
            AVCaptureDevice.requestAccess(for: .video) { [weak self] granted in
                guard let self else { return }
                self.sessionQueue.async { [weak self] in
                    guard let self, self.runIntent == intent else { return }
                    if granted {
                        self.configureAndStart(expectedIntent: intent)
                    } else {
                        self.setState(ChekinanaCameraStateResolver.initial(
                            permission: .denied,
                            hasBackCamera: false
                        ))
                    }
                }
            }
        case .authorized:
            configureAndStart(expectedIntent: intent)
        case .denied, .restricted:
            setState(ChekinanaCameraStateResolver.initial(
                permission: permission,
                hasBackCamera: false
            ))
        }
    }

    private func configureAndStart(expectedIntent: UUID) {
        guard runIntent == expectedIntent else { return }
        if configured {
            if case .interrupted = lifecycle.capability {
                publishSnapshot()
                return
            }
            if session.isRunning {
                lifecycle.clearCaptureFailure()
                setCapability(.running)
                return
            }
            beginNewSession()
            session.startRunning()
            guard runIntent == expectedIntent else {
                if session.isRunning { session.stopRunning() }
                return
            }
            setCapability(
                session.isRunning
                    ? .running
                    : .failed(ChekinanaProductCopy.text(
                        "scan.camera.session_start_failed",
                        "The camera session could not start."
                    ))
            )
            return
        }
        let device = AVCaptureDevice.default(
            .builtInWideAngleCamera,
            for: .video,
            position: .back
        )
        let initialState = ChekinanaCameraStateResolver.initial(
            permission: .authorized,
            hasBackCamera: device != nil
        )
        guard let device else {
            setState(initialState)
            return
        }
        beginNewSession()
        do {
            let input = try AVCaptureDeviceInput(device: device)
            session.beginConfiguration()
            session.sessionPreset = .photo
            guard session.canAddInput(input),
                  session.canAddOutput(photoOutput) else {
                session.commitConfiguration()
                setCapability(.unavailable(ChekinanaProductCopy.text(
                    "scan.camera.configuration_unavailable",
                    "The rear camera cannot be configured for photos."
                )))
                return
            }
            session.addInput(input)
            session.addOutput(photoOutput)
            photoOutput.maxPhotoQualityPrioritization = .quality
            let dimensions = ChekinanaCameraPhotoQuality.largestDimensions(
                device.activeFormat.supportedMaxPhotoDimensions
            )
            if let dimensions {
                photoOutput.maxPhotoDimensions = dimensions
            }
            session.commitConfiguration()
            guard runIntent == expectedIntent else {
                return
            }
            cameraDevice = device
            maximumDimensions = dimensions
            configured = true
            session.startRunning()
            guard runIntent == expectedIntent else {
                if session.isRunning { session.stopRunning() }
                return
            }
            setCapability(
                session.isRunning
                    ? .running
                    : .failed(ChekinanaProductCopy.text(
                        "scan.camera.session_start_failed",
                        "The camera session could not start."
                    ))
            )
        } catch {
            if session.isRunning { session.stopRunning() }
            setCapability(.failed(ChekinanaProductCopy.format(
                "scan.camera.configuration_failed",
                "Unable to configure the camera: %@",
                error.localizedDescription
            )))
        }
    }

    private func beginNewSession() {
        discardStoredDeliveries(captureIDs: lifecycle.beginNewSession())
        publishSnapshot()
    }

    private func setCapability(_ capability: ChekinanaCameraCaptureLifecycle.Capability) {
        lifecycle.setCapability(capability)
        publishSnapshot()
    }

    private func setState(_ state: ChekinanaCameraState) {
        let capability: ChekinanaCameraCaptureLifecycle.Capability
        switch state {
        case .idle: capability = .idle
        case .requestingPermission: capability = .requestingPermission
        case .configuring: capability = .configuring
        case .ready, .capturing: capability = .running
        case .interrupted(let message): capability = .interrupted(message)
        case .unavailable(let message): capability = .unavailable(message)
        case .failed(let message): capability = .failed(message)
        }
        setCapability(capability)
    }

    private func publishSnapshot() {
        let snapshot = lifecycle.snapshot
        let source = snapshot.delivery.flatMap { delivery in
            storedDeliveries[delivery.captureID].map {
                CapturedSource(
                    id: delivery.captureID,
                    photo: $0,
                    sessionGeneration: delivery.generation
                )
            }
        }
        DispatchQueue.main.async { [weak self] in
            guard let self else { return }
            guard snapshot.generation > self.publishedGeneration
                    || (snapshot.generation == self.publishedGeneration
                        && snapshot.revision >= self.publishedRevision) else { return }
            self.publishedGeneration = snapshot.generation
            self.publishedRevision = snapshot.revision
            self.state = snapshot.state
            self.isCaptureInFlight = snapshot.isCaptureLocked
            self.latestCapture = source
        }
    }

    private func discardStoredDelivery(captureID: UUID) {
        guard let photo = storedDeliveries.removeValue(forKey: captureID) else { return }
        ChekinanaCapturedPhotoStore.remove(photo)
    }

    private func discardStoredDeliveries(captureIDs: Set<UUID>) {
        for captureID in captureIDs {
            discardStoredDelivery(captureID: captureID)
        }
    }

    private func applyPhotoRotationIfSupported() {
        guard let angle = videoRotationAngle,
              let connection = photoOutput.connection(with: .video),
              connection.isVideoRotationAngleSupported(angle) else { return }
        connection.videoRotationAngle = angle
    }

    private func handleInterruption(_ notification: Notification) {
        let reason = (notification.userInfo?[AVCaptureSessionInterruptionReasonKey] as? NSNumber)?.intValue
        sessionQueue.async { [weak self] in
            guard let self, self.runIntent != nil else { return }
            let state = ChekinanaCameraStateResolver.interruption(reason: reason)
            self.setState(state)
        }
    }

    private func handleInterruptionEnded() {
        sessionQueue.async { [weak self] in
            guard let self, self.runIntent != nil else { return }
            guard case .interrupted = self.lifecycle.capability else { return }
            guard self.configured, !self.session.isInterrupted else { return }
            self.setCapability(.configuring)
            if !self.session.isRunning { self.session.startRunning() }
            if self.session.isRunning { self.lifecycle.clearCaptureFailure() }
            self.setCapability(
                self.session.isRunning
                    ? .running
                    : .failed(ChekinanaProductCopy.text(
                        "scan.camera.interruption_resume_failed",
                        "The camera remained unavailable after the interruption ended."
                    ))
            )
        }
    }

    private func handleRuntimeError(_ notification: Notification) {
        let error = notification.userInfo?[AVCaptureSessionErrorKey] as? NSError
        let code = error?.code ?? -1
        let message = error?.localizedDescription ?? ChekinanaProductCopy.text(
            "scan.camera.runtime_error_unknown",
            "Unknown runtime error"
        )
        sessionQueue.async { [weak self] in
            guard let self, self.runIntent != nil else { return }
            let state = ChekinanaCameraStateResolver.runtimeError(
                code: code,
                message: message
            )
            guard state == .configuring else {
                self.discardStoredDeliveries(
                    captureIDs: self.lifecycle.tearDown()
                )
                self.setState(state)
                return
            }
            self.beginNewSession()
            if !self.session.isRunning { self.session.startRunning() }
            self.setCapability(
                self.session.isRunning
                    ? .running
                    : .failed(ChekinanaProductCopy.text(
                        "scan.camera.media_services_restart_failed",
                        "Camera media services reset and could not restart."
                    ))
            )
        }
    }
}

private final class ChekinanaCameraPreviewUIView: UIView {
    var onFocus: ((CGPoint) -> Void)?
    var onRotationAngle: ((CGFloat?) -> Void)?
    private var lastRotationAngle: CGFloat?

    override class var layerClass: AnyClass { AVCaptureVideoPreviewLayer.self }

    private var previewLayer: AVCaptureVideoPreviewLayer {
        layer as! AVCaptureVideoPreviewLayer
    }

    override init(frame: CGRect) {
        super.init(frame: frame)
        let recognizer = UITapGestureRecognizer(target: self, action: #selector(handleTap(_:)))
        addGestureRecognizer(recognizer)
        isUserInteractionEnabled = true
        previewLayer.videoGravity = .resizeAspectFill
    }

    required init?(coder: NSCoder) {
        nil
    }

    func setSession(_ session: AVCaptureSession) {
        if previewLayer.session !== session { previewLayer.session = session }
        updateRotation()
    }

    override func layoutSubviews() {
        super.layoutSubviews()
        updateRotation()
    }

    @objc private func handleTap(_ recognizer: UITapGestureRecognizer) {
        let location = recognizer.location(in: self)
        let devicePoint = previewLayer.captureDevicePointConverted(fromLayerPoint: location)
        showFocusFrame(at: location)
        onFocus?(devicePoint)
    }

    private func showFocusFrame(at point: CGPoint) {
        let frameView = UIView(frame: CGRect(x: 0, y: 0, width: 74, height: 74))
        frameView.center = point
        frameView.layer.borderColor = UIColor.systemYellow.cgColor
        frameView.layer.borderWidth = 2
        frameView.layer.cornerRadius = 8
        frameView.alpha = 0
        frameView.transform = CGAffineTransform(scaleX: 1.25, y: 1.25)
        addSubview(frameView)
        UIView.animate(withDuration: 0.16, animations: {
            frameView.alpha = 1
            frameView.transform = .identity
        }) { _ in
            UIView.animate(
                withDuration: 0.28,
                delay: 0.65,
                options: [.curveEaseOut]
            ) {
                frameView.alpha = 0
            } completion: { _ in
                frameView.removeFromSuperview()
            }
        }
    }

    private func updateRotation() {
        guard let orientation = window?.windowScene?.interfaceOrientation,
              let angle = ChekinanaCameraVideoRotation.angle(for: orientation) else {
            return
        }
        if let connection = previewLayer.connection,
           connection.isVideoRotationAngleSupported(angle) {
            connection.videoRotationAngle = angle
        }
        guard lastRotationAngle != angle else { return }
        lastRotationAngle = angle
        onRotationAngle?(angle)
    }
}

private struct ChekinanaCameraPreview: UIViewRepresentable {
    let session: AVCaptureSession
    let onFocus: (CGPoint) -> Void
    let onRotationAngle: (CGFloat?) -> Void

    func makeUIView(context: Context) -> ChekinanaCameraPreviewUIView {
        let view = ChekinanaCameraPreviewUIView()
        view.onFocus = onFocus
        view.onRotationAngle = onRotationAngle
        view.setSession(session)
        return view
    }

    func updateUIView(_ uiView: ChekinanaCameraPreviewUIView, context: Context) {
        uiView.onFocus = onFocus
        uiView.onRotationAngle = onRotationAngle
        uiView.setSession(session)
    }
}

private struct ChekinanaCameraCaptureView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.scenePhase) private var scenePhase
    @StateObject private var controller = ChekinanaCameraController()
    @State private var deliveryOwnerID: UUID?
    let onCaptured: (ChekinanaCameraController.CapturedClaim) -> Void

    var body: some View {
        ZStack {
            Color.black.ignoresSafeArea()
            ChekinanaCameraPreview(
                session: controller.session,
                onFocus: controller.focus,
                onRotationAngle: controller.setVideoRotationAngle
            )
            .ignoresSafeArea()

            VStack {
                HStack {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) { dismiss() }
                        .font(.headline)
                        .foregroundStyle(.white)
                        .padding(.horizontal, 16)
                        .frame(minHeight: 44)
                        .background(.black.opacity(0.48))
                        .clipShape(Capsule())
                        .disabled(!ChekinanaCameraCaptureControls.canDismiss(
                            isCaptureInFlight: controller.isCaptureInFlight
                        ))
                        .opacity(controller.isCaptureInFlight ? 0.45 : 1)
                        .accessibilityIdentifier("chekinana.camera.done")
                    Spacer()
                }
                .padding()
                Spacer()
                cameraStatus
                Button(action: controller.capturePhoto) {
                    ZStack {
                        Circle().fill(.white).frame(width: 76, height: 76)
                        Circle().stroke(.black.opacity(0.72), lineWidth: 2).frame(width: 66, height: 66)
                    }
                }
                .disabled(!ChekinanaCameraCaptureControls.canCapture(
                    state: controller.state,
                    isCaptureInFlight: controller.isCaptureInFlight
                ))
                .opacity(ChekinanaCameraCaptureControls.canCapture(
                    state: controller.state,
                    isCaptureInFlight: controller.isCaptureInFlight
                ) ? 1 : 0.55)
                .padding(.bottom, 28)
                .accessibilityLabel(ChekinanaProductCopy.text("scan.camera.subtitle", "Take a photo"))
                .accessibilityIdentifier("chekinana.camera.shutter")
            }
        }
        .onAppear {
            deliveryOwnerID = UUID()
            controller.prepare()
        }
        .onDisappear {
            deliveryOwnerID = nil
            controller.stop()
        }
        .onChange(of: scenePhase) { _, phase in
            if phase == .active {
                deliveryOwnerID = UUID()
                controller.resume()
            } else {
                deliveryOwnerID = nil
                controller.stop()
            }
        }
        .onChange(of: controller.latestCapture) { _, capture in
            guard let capture, let ownerID = deliveryOwnerID else { return }
            controller.claimLatestCapture(capture, ownerID: ownerID) { claim in
                guard let claim else { return }
                defer { claim.discard() }
                guard deliveryOwnerID == claim.ownerID else { return }
                onCaptured(claim)
            }
        }
        .accessibilityIdentifier("chekinana.camera.page")
    }

    @ViewBuilder
    private var cameraStatus: some View {
        switch controller.state {
        case .requestingPermission, .configuring:
            ProgressView()
                .tint(.white)
                .padding(12)
                .background(.black.opacity(0.48))
                .clipShape(Circle())
                .padding(.bottom, 16)
        case .capturing:
            Text(ChekinanaProductCopy.text("scan.camera.capturing", "Capturing full-resolution photo…"))
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(.white)
                .padding(12)
                .background(.black.opacity(0.48))
                .clipShape(Capsule())
                .padding(.bottom, 16)
        case .interrupted(let message):
            Text(message)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(.white)
                .multilineTextAlignment(.center)
                .padding(14)
                .background(.black.opacity(0.62))
                .clipShape(RoundedRectangle(cornerRadius: 14))
                .padding(.horizontal, 24)
                .padding(.bottom, 16)
        case .unavailable(let message):
            VStack(spacing: 10) {
                Text(message)
                    .font(.subheadline)
                    .multilineTextAlignment(.center)
                Button(ChekinanaProductCopy.text("scan.camera.open_settings", "Open Settings")) {
                    guard let url = URL(string: UIApplication.openSettingsURLString) else { return }
                    UIApplication.shared.open(url)
                }
                .buttonStyle(.borderedProminent)
            }
            .foregroundStyle(.white)
            .padding(16)
            .background(.black.opacity(0.62))
            .clipShape(RoundedRectangle(cornerRadius: 14))
            .padding(.horizontal, 24)
            .padding(.bottom, 16)
        case .failed(let message):
            VStack(spacing: 10) {
                Text(message)
                    .font(.subheadline)
                    .multilineTextAlignment(.center)
                Button(ChekinanaProductCopy.text("common.retry", "Retry")) { controller.resume() }
                    .buttonStyle(.borderedProminent)
            }
            .foregroundStyle(.white)
            .padding(16)
            .background(.black.opacity(0.62))
            .clipShape(RoundedRectangle(cornerRadius: 14))
            .padding(.horizontal, 24)
            .padding(.bottom, 16)
        case .idle, .ready:
            EmptyView()
        }
    }
}

private struct ChekinanaNativeTemporaryDraft: Identifiable {
    let id = UUID()
    let temporaryID: UUID
    var idolIDs: Set<UUID>
    var hasDate: Bool
    var date: Date
    var eventID: UUID?
    var eventWasExplicitlyEdited: Bool
    var existingChekiID: UUID?
    var existingSelectionIsManual: Bool
    var userAppears: Bool?
    var size: ChekiSize?
    var isFavorite: Bool
    var hasPostedToSNS: Bool
    var note: String
}

private struct ChekinanaNativeIdolSelectionDraft: Identifiable {
