enum ChekinanaExistingChekiMatchPolicy {
    /// Sibling cards in one Scan review batch may consume the same no-media
    /// record. Cross-batch exclusion remains owned by the ledger reservation.
    static func availableCandidateIDs(
        allCandidateIDs: [UUID],
        reservedBySiblingCards _: Set<UUID>
    ) -> [UUID] {
        allCandidateIDs
    }

    static func automaticTargetID(
        allCandidateIDs: [UUID],
        availableCandidateIDs: [UUID]
    ) -> UUID? {
        guard allCandidateIDs.count == 1,
              availableCandidateIDs.count == 1,
              allCandidateIDs[0] == availableCandidateIDs[0] else {
            return nil
        }
        return availableCandidateIDs[0]
    }
}

enum ChekinanaNativeTemporaryEditorEventPolicy {
    static func dateChanged(
        currentEventID: UUID?,
        eventWasExplicitlyEdited: Bool,
        date: Date?,
        events: [(id: UUID, date: Date?)],
        calendar: Calendar = .current
    ) -> ChekinanaNativeTemporaryEditorEventState {
        if eventWasExplicitlyEdited {
            return .init(
                eventID: currentEventID.flatMap { id in
                    events.contains(where: { $0.id == id }) ? id : nil
                },
                eventWasExplicitlyEdited: true
            )
        }
        return .init(
            eventID: ChekinanaChekiEventAutoAssociation.uniqueEventID(
                for: date,
                events: events,
                calendar: calendar
            ),
            eventWasExplicitlyEdited: false
        )
    }
}

enum ChekinanaScanReviewRecordMatchPolicy {
    static func matches(
        _ candidate: ChekinanaChekiRecordAllocationPolicy.Candidate,
        media: ChekinanaChekiRecordAllocationPolicy.MediaContext,
        calendar: Calendar = .current
    ) -> Bool {
        guard let candidateDate = candidate.date.flatMap(ChekinanaDateOnly.canonicalized),
              let mediaDate = media.date.flatMap(ChekinanaDateOnly.canonicalized) else { return false }
        return calendar.isDate(candidateDate, inSameDayAs: mediaDate)
            && Set(candidate.idolIDs) == Set(media.idolIDs)
            && (candidate.size ?? .mini) == media.size
    }

    static func targetID(
        candidates: [ChekinanaChekiRecordAllocationPolicy.Candidate],
        media: ChekinanaChekiRecordAllocationPolicy.MediaContext,
        calendar: Calendar = .current
    ) -> UUID? {
        candidates.filter { matches($0, media: media, calendar: calendar) }
            .sorted {
                if $0.count != $1.count { return $0.count > $1.count }
                return $0.id.uuidString < $1.id.uuidString
            }.first?.id
    }
}

enum ChekinanaScanReviewDatePolicy {
    static func isFuture(
        _ canonicalDate: Date?,
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> Bool {
        guard let canonicalDate,
              let displayedDate = ChekinanaDateOnly.displayDate(
                from: canonicalDate, calendar: calendar
              ) else { return false }
        return calendar.compare(displayedDate, to: now, toGranularity: .day)
            == .orderedDescending
    }
}

private struct ChekinanaReviewRecordIndex {
    private struct Key: Hashable {
        let idolIDs: Set<UUID>
        let day: Date
    }
    private let hintCalendar: Calendar
    private var selection: [Key: [ChekiRecord]] = [:]
    private var hints: [Key: [ChekiRecord]] = [:]

    init(records: [ChekiRecord], hintCalendar: Calendar = .current) {
        self.hintCalendar = hintCalendar
        for record in records {
            guard let date = record.date else { continue }
            let ids = Set(record.idolIDs)
            selection[Key(idolIDs: ids, day: ChekinanaProductDate.calendar.startOfDay(for: date)), default: []].append(record)
            hints[Key(idolIDs: ids, day: hintCalendar.startOfDay(for: date)), default: []].append(record)
        }
        for key in selection.keys {
            selection[key]?.sort {
                if $0.count != $1.count { return $0.count > $1.count }
                return $0.id.uuidString < $1.id.uuidString
            }
        }
    }

    func matching(idolIDs: Set<UUID>, date: Date?, size: ChekiSize) -> [ChekiRecord] {
        guard let date else { return [] }
        return (selection[Key(idolIDs: idolIDs, day: ChekinanaProductDate.calendar.startOfDay(for: date))] ?? []).filter { ($0.size ?? .mini) == size }
    }

    func matchesHint(
        _ temporary: ChekinanaConfirmationLedger.TemporaryCheki,
        eventID: UUID?, size: ChekiSize
    ) -> Bool {
        guard let date = temporary.date.flatMap(ChekinanaDateOnly.canonicalized) else { return false }
        let key = Key(idolIDs: Set(temporary.idolIDs), day: hintCalendar.startOfDay(for: date))
        return (hints[key] ?? []).contains { record in
            ChekinanaScanReviewRecordMatchPolicy.matches(
                .init(id: record.id, date: record.date, idolIDs: record.idolIDs,
                      eventID: record.eventID, size: record.size, count: record.count),
                media: .init(date: temporary.date, idolIDs: temporary.idolIDs, eventID: eventID, size: size),
                calendar: hintCalendar
            )
        }
    }
}

@MainActor
private final class ChekinanaReviewRecordIndexCache: ObservableObject {
    private var members: [ObjectIdentifier] = []
    private var hintCalendar: Calendar?
    private var selectionCalendar: Calendar?
    private var invalidation = ChekinanaCalendarMetricInvalidation()
    private var cached: ChekinanaReviewRecordIndex?

    func index(records: [ChekiRecord]) -> ChekinanaReviewRecordIndex {
        let nextMembers = records.map(ObjectIdentifier.init)
        let currentHintCalendar = Calendar.current
        let currentSelectionCalendar = ChekinanaProductDate.calendar
        if members == nextMembers, hintCalendar == currentHintCalendar,
           selectionCalendar == currentSelectionCalendar,
           !invalidation.isInvalidated, let cached { return cached }
        let token = ChekinanaCalendarMetricInvalidation()
        let value = withObservationTracking {
            ChekinanaReviewRecordIndex(records: records, hintCalendar: currentHintCalendar)
        } onChange: { [weak self, token] in
            token.invalidate()
            Task { @MainActor [weak self] in self?.objectWillChange.send() }
        }
        members = nextMembers
        hintCalendar = currentHintCalendar
        selectionCalendar = currentSelectionCalendar
        invalidation = token
        cached = value
        return value
    }
}

private final class ChekinanaReviewAspectRatioCache {
    private struct Value { let revision: String; let ratio: CGFloat }
    private var values: [UUID: Value] = [:]

    func retain(_ ids: Set<UUID>) { values = values.filter { ids.contains($0.key) } }

    func ratio(id: UUID, revision: String, data: Data) -> CGFloat {
        if let cached = values[id], cached.revision == revision { return cached.ratio }
        let ratio = ChekinanaImagePixelGeometry.aspectRatio(in: data)
            ?? ChekinanaChekiDisplayFramePolicy.aspectRatio
        values[id] = Value(revision: revision, ratio: ratio)
        return ratio
    }
}

private struct ChekinanaReviewIdolAvatar: View {
    let idol: Idol
    let sessionID: UUID
    @ObservedObject private var revisions = ChekinanaThumbnailRevisionStore.shared
    @State private var image: ChekinanaRenderedImage?
    @State private var loadedIdentity: ChekinanaThumbnailLoadIdentity?

    private var identity: ChekinanaThumbnailLoadIdentity {
        revisions.identity(imageRef: idol.avatarImageRef, sourceKey: "review-\(sessionID)-idol-\(idol.id)")
    }

    var body: some View {
        let currentIdentity = identity
        ChekinanaIdolAvatarImage(
            name: idol.name, color: idol.color, imageRef: nil,
            cacheKey: "review-\(sessionID)-idol-\(idol.id)", size: 32,
            preparedImage: loadedIdentity == currentIdentity ? image : nil
        )
        .task(id: currentIdentity) {
            image = nil
            loadedIdentity = nil
            let ref = idol.avatarImageRef
            let idolID = idol.id
            let valid = await Task.detached(priority: .userInitiated) {
                (try? ChekinanaIdolReferenceStore.managedAvatarURL(for: ref, idolID: idolID)) != nil
            }.value
            guard valid, !Task.isCancelled else { return }
            let loaded = await ChekinanaThumbnailCache.shared.thumbnailImage(
                forManagedImageRef: ref,
                key: "\(currentIdentity.sourceKey)-\(currentIdentity.revision)", maxDimension: 512
            )
            guard !Task.isCancelled, currentIdentity == identity else { return }
            image = loaded
            loadedIdentity = currentIdentity
        }
    }
}

private struct ChekinanaNativeScanReview: View {
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query(sort: \Idol.name) private var idols: [Idol]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query private var chekiRecords: [ChekiRecord]
    @Query private var customChekiSizes: [CustomChekiSize]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    @Binding var cards: [ChekinanaChekiCard]
    @Binding var sourceRegistry: ChekinanaScanReviewSourceRegistry
    let warningCount: Int
    let ledger: ChekinanaConfirmationLedger
    let onDeleteSource: (UUID) -> Void
    let onSaved: ([UUID]) -> Void
    let onDiscarded: ([UUID]) -> Void

    private struct RenderSnapshot {
        let temporaries: [UUID: ChekinanaConfirmationLedger.TemporaryCheki]
        let idols: [Idol]
        let events: [UUID: Event]
        let records: ChekinanaReviewRecordIndex
    }
    @StateObject private var recordIndexCache = ChekinanaReviewRecordIndexCache()
    @State private var aspectRatios = ChekinanaReviewAspectRatioCache()
    @State private var avatarCacheSession = UUID()
    @State private var editorDraft: ChekinanaNativeTemporaryDraft?
    @State private var idolSelectionDraft: ChekinanaNativeIdolSelectionDraft?
    @State private var dateSelectionDraft: ChekinanaNativeDateSelectionDraft?
    @State private var eventSelectionDraft: ChekinanaNativeEventSelectionDraft?
    @State private var isSaving = false
    @State private var batchSaveProgress: ChekinanaTemporaryChekiBatchProgress?
    @State private var statusMessage: String?
    @State private var annotationVisibleIDs = Set<UUID>()
    @State private var annotationPreviewData: [UUID: Data] = [:]
    @State private var annotationLoadingIDs = Set<UUID>()
    @State private var annotationTasks: [UUID: Task<Void, Never>] = [:]
    @State private var transformingIDs = Set<UUID>()
    @State private var refittingIDs = Set<UUID>()
    @State private var cardPresentationRevisions: [UUID: UInt64] = [:]
    @State private var activeTransformIntents: [
        UUID: ChekinanaConfirmationLedger.TemporaryChekiTransformIntent
    ] = [:]
    @State private var transformTasks: [UUID: Task<Void, Never>] = [:]
    @State private var downloadingIDs = Set<UUID>()
    @State private var isSavingAllToPhotos = false
    @State private var saveAllToPhotosTask: Task<Void, Never>?
    @State private var isDiscardAlertPresented = false
    @ScaledMetric(relativeTo: .caption2) private var actionTextRegionHeight =
        ChekinanaScanReviewLayout.actionTextRegionBaseHeight
    @ScaledMetric(relativeTo: .callout) private var actionIconRegionHeight =
        ChekinanaScanReviewLayout.actionIconRegionBaseHeight

    var body: some View {
        let snapshot = RenderSnapshot(
            temporaries: ledger.temporaryChekiSnapshot(cards.map(\.id)),
            idols: visibleIdols,
            events: Dictionary(uniqueKeysWithValues: events.map { ($0.id, $0) }),
            records: recordIndexCache.index(records: chekiRecords)
        )
        let _ = aspectRatios.retain(Set(cards.map(\.id)))
        NavigationStack {
            Group {
                if cards.isEmpty {
                    ChekinanaEmptyState(
                        title: ChekinanaProductCopy.text("scan.review.empty", "No temporary Cheki"),
                        message: ChekinanaProductCopy.text(
                            "scan.review.empty_message",
                            "All temporary results were removed; nothing was saved."
                        ),
                        systemImage: "trash"
                    )
                } else {
                    ScrollView {
                        VStack(spacing: 14) {
                            if warningCount > 0 {
                                Label(
                                    ChekinanaProductCopy.format(
                                        "scan.review.warning_count",
                                        "Valid results were kept; %lld items were incomplete. Check automatic recognition fields.",
                                        Int64(warningCount)
                                    ),
                                    systemImage: "exclamationmark.triangle.fill"
                                )
                                .font(.subheadline)
                                .foregroundStyle(.orange)
                                .padding(14)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .background(Color.orange.opacity(0.10))
                                .clipShape(RoundedRectangle(cornerRadius: 14))
                                .accessibilityIdentifier("chekinana.scan.review.warning")
                            }
                            LazyVGrid(
                                columns: reviewGridColumns,
                                alignment: .leading,
                                spacing: 12
                            ) {
                                ForEach(Array(cards.enumerated()), id: \.element.id) { index, card in
                                    temporaryCard(card, position: index + 1, snapshot: snapshot)
                                }
                            }
                        }
                        .padding(12)
                        .padding(.bottom, 90)
                    }
                }
            }
            .background(ChekinanaProductTheme.pageBackground)
            .navigationTitle(
                ChekinanaProductCopy.format(
                    "scan.review.title",
                    "Review %lld Cheki",
                    Int64(cards.count)
                )
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.back", "Back")) { isDiscardAlertPresented = true }
                        .disabled(
                            isSaving
                                || isSavingAllToPhotos
                                || !transformingIDs.isEmpty
                                || !downloadingIDs.isEmpty
                        )
                        .accessibilityIdentifier("chekinana.scan.review.back")
                }
            }
            .safeAreaInset(edge: .bottom) {
                if !cards.isEmpty || !sourceRegistry.sources.isEmpty {
                    VStack(spacing: 8) {
                        if !cards.isEmpty {
                            Button {
                                saveAllToPhotosTask?.cancel()
                                saveAllToPhotosTask = Task { await saveAllToPhotos() }
                            } label: {
                                Label(
                                    ChekinanaProductCopy.text(
                                        "scan.review.save_all_to_photos",
                                        "Save all to Photos"
                                    ),
                                    systemImage: "square.and.arrow.down"
                                )
                                .font(.headline)
                                .frame(maxWidth: .infinity, minHeight: 44)
                            }
                            .buttonStyle(.bordered)
                            .disabled(
                                isSavingAllToPhotos
                                    || isSaving
                                    || !transformingIDs.isEmpty
                                    || !downloadingIDs.isEmpty
                                    || !ledger.areTemporaryChekiTransformsSettled(cards.map(\.id))
                            )
                            .accessibilityIdentifier(
                                "chekinana.scan.review.save-all-to-photos"
                            )

                            Button {
                                Task { await confirmAll() }
                            } label: {
                                if isSaving {
                                    VStack(spacing: 5) {
                                        Text(batchSaveProgress?.stage.title ?? ChekinanaProductCopy.text(
                                            "scan.review.preparing_images",
                                            "Preparing images"
                                        ))
                                        .font(.headline)
                                        if let progress = batchSaveProgress {
                                            ProgressView(
                                                value: Double(progress.completed),
                                                total: Double(max(1, progress.total))
                                            )
                                            .tint(.white)
                                            Text("\(progress.completed)/\(progress.total)")
                                                .font(.caption.monospacedDigit())
                                        }
                                    }
                                    .frame(maxWidth: .infinity, minHeight: 52)
                                } else {
                                    Label(
                                        ChekinanaProductCopy.text("scan.review.save_all", "Save all Cheki"),
                                        systemImage: "checkmark.circle"
                                    )
                                    .font(.headline)
                                    .frame(maxWidth: .infinity, minHeight: 52)
                                }
                            }
                            .buttonStyle(.borderedProminent)
                            .tint(ChekinanaProductTheme.accent)
                            .disabled(
                                !ChekinanaScanReviewInteractionPolicy.allowsConfirmAll(
                                    isSaving: isSaving || isSavingAllToPhotos,
                                    hasRotations: !transformingIDs.isEmpty,
                                    hasSizePreviews: false,
                                    hasDownloads: !downloadingIDs.isEmpty
                                ) || !ledger.areTemporaryChekiTransformsSettled(cards.map(\.id))
                            )
                            .accessibilityIdentifier("chekinana.scan.review.confirm")
                        }
                        if cards.isEmpty, !sourceRegistry.sources.isEmpty {
                            Button(
                                ChekinanaProductCopy.text("scan.review.discard", "Discard review"),
                                role: .destructive
                            ) {
                                discardEmptyReview()
                            }
                            .buttonStyle(.bordered)
                            .disabled(isSaving)
                            .frame(maxWidth: .infinity, minHeight: 44)
                            .accessibilityIdentifier("chekinana.scan.review.discard")
                        }
                    }
                    .padding(.horizontal, 16)
                    .padding(.vertical, 10)
                    .background(.ultraThinMaterial)
                }
            }
            .sheet(item: editorPresentation) { presentedDraft in
                ChekinanaNativeTemporaryEditor(
                    initialDraft: presentedDraft,
                    idols: visibleIdols,
                    events: events,
                    existingCandidatesProvider: { idolIDs, date, size, temporaryID in
                        availableExistingChekis(
                            idolIDs: idolIDs,
                            date: date,
                            size: size,
                            excludingTemporaryID: temporaryID,
                            matchingCandidates: snapshot.records.matching(idolIDs: idolIDs, date: date, size: size)
                        )
                    },
                    allowsSizeEditing: ledger.temporaryCheki(presentedDraft.temporaryID)?.isRefitFailed != true,
                    onSave: { updatedDraft in
                        guard editorDraft?.id == presentedDraft.id,
                              updatedDraft.id == presentedDraft.id,
                              updatedDraft.temporaryID == presentedDraft.temporaryID else { return }
                        editorDraft = updatedDraft
                        saveEditor()
                    },
                    onCancel: {
                        guard editorDraft?.id == presentedDraft.id else { return }
                        editorDraft = nil
                    },
                    onDelete: {
                        guard editorDraft?.id == presentedDraft.id else { return }
                        deleteTemporary(id: presentedDraft.temporaryID)
                        editorDraft = nil
                    }
                )
                .id(presentedDraft.id)
            }
            .sheet(item: $idolSelectionDraft) { draft in
                ChekinanaNativeIdolSelectionView(
                    idols: visibleIdols,
                    initialSelectedIDs: draft.selectedIDs,
                    onSave: { selectedIDs in
                        let saved = saveIdolSelection(
                            id: draft.id,
                            selectedIDs: selectedIDs
                        )
                        if saved { idolSelectionDraft = nil }
                        return saved
                    }
                )
            }
            .sheet(item: $dateSelectionDraft) { draft in
                ChekinanaNativeDateSelectionView(
                    initialDate: draft.date,
                    onSave: { date in
                        let saved = saveDateSelection(id: draft.id, date: date)
                        if saved { dateSelectionDraft = nil }
                        return saved
                    }
                )
            }
            .sheet(item: $eventSelectionDraft) { draft in
                ChekinanaNativeEventSelectionView(
                    dayEvents: ChekinanaChekiEventSelectionPolicy.eventsOnExactDate(
                        events,
                        schedules: eventSchedules,
                        for: draft.date
                    ),
                    allEvents: events,
                    schedules: eventSchedules,
                    initialEventID: draft.eventID,
                    onSave: { eventID in
                        let saved = saveEventSelection(id: draft.id, eventID: eventID)
                        if saved { eventSelectionDraft = nil }
                        return saved
                    }
                )
            }
            .alert(ChekinanaProductCopy.text("scan.review.alert_title", "Scan review"), isPresented: Binding(
                get: { statusMessage != nil },
                set: { if !$0 { statusMessage = nil } }
            )) {
                Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) { statusMessage = nil }
            } message: {
                Text(statusMessage ?? "")
            }
            .alert(ChekinanaProductCopy.text("scan.review.discard_title", "Discard unsaved results?"), isPresented: $isDiscardAlertPresented) {
                Button(ChekinanaProductCopy.text("common.cancel", "Cancel"), role: .cancel) {}
                Button(ChekinanaProductCopy.text("scan.review.discard_action", "Discard"), role: .destructive) {
                    discardEntireReview()
                }
            } message: {
                Text(ChekinanaProductCopy.text(
                    "scan.review.discard_message",
                    "This discards the unsaved Review results and returns to Scan. Inputs that produced no Cheki are kept so you can retry them."
                ))
            }
            .onChange(of: chekiRecords.map(ChekinanaChekiRecordSnapshot.init), initial: true) { _, _ in
                guard !isSaving else { return }
                for card in cards { _ = reconcileThenRefresh(card.id) }
            }
            .onChange(of: hiddenIdols.hiddenIDs) { _, _ in
                retireHiddenTemporaryCards()
            }
            .onDisappear {
                saveAllToPhotosTask?.cancel()
                saveAllToPhotosTask = nil
                invalidateAllTransforms()
                releaseAllSourceAnnotations()
            }
        }
        .chekinanaScreenMarker("chekinana.scan.review")
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    private var reviewGridColumns: [GridItem] {
        [
            GridItem(.flexible(minimum: 0), spacing: 12, alignment: .top),
            GridItem(.flexible(minimum: 0), spacing: 12, alignment: .top),
        ]
    }

    private var editorPresentation: Binding<ChekinanaNativeTemporaryDraft?> {
        let presentationID = editorDraft?.id
        return Binding(
            get: { editorDraft?.id == presentationID ? editorDraft : nil },
            set: { updatedDraft in
                guard editorDraft?.id == presentationID,
                      updatedDraft == nil || updatedDraft?.id == presentationID else { return }
                editorDraft = updatedDraft
            }
        )
    }

    private func matchingExistingChekis(
        idolIDs: Set<UUID>, date: Date?, size: ChekiSize
    ) -> [ChekiRecord] {
        recordIndexCache.index(records: chekiRecords).matching(idolIDs: idolIDs, date: date, size: size)
    }

    private func availableExistingChekis(
        idolIDs: Set<UUID>,
        date: Date?,
        size: ChekiSize,
        excludingTemporaryID: UUID,
        matchingCandidates: [ChekiRecord]? = nil
    ) -> [ChekiRecord] {
        let matching = matchingCandidates ?? matchingExistingChekis(idolIDs: idolIDs, date: date, size: size)
        let availableIDs = Set(ChekinanaExistingChekiMatchPolicy.availableCandidateIDs(
            allCandidateIDs: matching.map(\.id),
            reservedBySiblingCards: []
        ))
        return matching.filter { availableIDs.contains($0.id) }
    }

    @ViewBuilder
    private func temporaryCard(
        _ card: ChekinanaChekiCard,
        position: Int,
        snapshot: RenderSnapshot
    ) -> some View {
        if let temporary = snapshot.temporaries[card.id] {
            let presentationRevision = cardPresentationRevisions[card.id, default: 0]
            let imageRevision = "\(presentationRevision)-\(temporary.transformSourceVersion)-\(temporary.transformGeneration)-\(temporary.imageRotationQuarterTurns)-\(temporary.size?.rawValue ?? "unknown")"
            VStack(alignment: .leading, spacing: 8) {
                ZStack(alignment: .topLeading) {
                    Button { beginEditing(temporary) } label: {
                        Group {
                            if temporary.isRefitFailed {
                                Text(ChekinanaProductCopy.text(
                                    "scan.review.refit_failed_restore",
                                    "Refit failed. Undo to restore the original image before saving."
                                ))
                                .font(.callout.weight(.semibold))
                                .multilineTextAlignment(.center)
                                .foregroundStyle(.secondary)
                                .padding(20)
                                .frame(maxWidth: .infinity, maxHeight: .infinity)
                                .background(ChekinanaProductTheme.pageBackground)
                                .accessibilityIdentifier("chekinana.scan.review.refit-failed.\(temporary.id.uuidString.lowercased())")
                            } else {
                                ChekinanaTemporaryImagePreview(
                            imageData: temporary.image.data,
                            annotationState: temporary.dateAnnotationState,
                            annotationPreviewData: annotationPreviewData[temporary.id],
                            showsSourceAnnotation: annotationVisibleIDs.contains(temporary.id),
                            cacheKey: "native-review-\(temporary.id.uuidString)-\(imageRevision)"
                                )
                            }
                        }
                        .aspectRatio(
                            aspectRatios.ratio(id: temporary.id, revision: imageRevision, data: temporary.image.data),
                            contentMode: .fit
                        )
                        .frame(maxWidth: .infinity)
                        .contentShape(Rectangle())
                        .overlay {
                            if transformingIDs.contains(temporary.id) {
                                ProgressView()
                                    .tint(.white)
                                    .padding(10)
                                    .background(.black.opacity(0.58))
                                    .clipShape(Circle())
                                    .accessibilityLabel(ChekinanaProductCopy.text(
                                        "scan.review.preparing_images",
                                        "Preparing images"
                                    ))
                            } else if annotationLoadingIDs.contains(temporary.id) {
                                ProgressView()
                                    .tint(.white)
                                    .padding(10)
                                    .background(.black.opacity(0.58))
                                    .clipShape(Circle())
                                    .accessibilityLabel(ChekinanaProductCopy.text(
                                        "scan.review.preparing_annotation",
                                        "Preparing detection box"
                                    ))
                            }
                        }
                    }
                    .buttonStyle(.plain)
                    .disabled(!allowsCardInteraction(temporary.id))
                    .accessibilityLabel(ChekinanaProductCopy.text("scan.review.edit", "Edit temporary Cheki"))
                    .accessibilityIdentifier(
                        "chekinana.scan.review.image.\(temporary.id.uuidString.lowercased())"
                    )

                    Button {
                        toggleFavorite(temporary.id)
                    } label: {
                        Image(systemName: temporary.isFavorite ? "star.fill" : "star")
                            .font(.callout.weight(.semibold))
                            .frame(width: 36, height: 36)
                            .foregroundStyle(
                                temporary.isFavorite
                                    ? ChekinanaProductTheme.accent
                                    : Color.white
                            )
                            .background(.black.opacity(0.72))
                            .clipShape(Circle())
                            .frame(
                                width: ChekinanaAccessibilityMetrics.minimumTouchTarget,
                                height: ChekinanaAccessibilityMetrics.minimumTouchTarget
                            )
                            .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .disabled(!allowsCardInteraction(temporary.id))
                    .accessibilityLabel(ChekinanaProductCopy.text(
                        "common.favorite",
                        "Favorite"
                    ))
                    .accessibilityValue(ChekinanaProductCopy.text(
                        temporary.isFavorite
                            ? "common.selected"
                            : "common.not_selected",
                        temporary.isFavorite ? "Selected" : "Not selected"
                    ))
                    .accessibilityIdentifier(
                        "chekinana.scan.review.favorite.\(temporary.id.uuidString.lowercased())"
                    )
                    .padding(4)

                    if let userAppears = temporary.userAppears {
                        VStack(spacing: 0) {
                            Spacer(minLength: 0)
                            HStack(spacing: 0) {
                                Button {
                                    toggleUserAppears(temporary.id)
                                } label: {
                                    Text(ChekinanaProductCopy.text(
                                        userAppears
                                            ? "gallery.shot_filter.two_shot"
                                            : "gallery.shot_filter.solo",
                                        userAppears ? "2-shot" : "solo"
                                    ))
                                        .font(.caption2.weight(.bold))
                                        .foregroundStyle(userAppears ? Color.black : Color.white)
                                        .padding(.horizontal, 7)
                                        .padding(.vertical, 4)
                                        .background(
                                            userAppears
                                                ? Color.white
                                                : Color.black.opacity(0.72)
                                        )
                                        .clipShape(Capsule())
                                        .frame(
                                            minWidth: 44,
                                            minHeight: 44,
                                            alignment: .topLeading
                                        )
                                        .contentShape(Rectangle())
                                }
                                .buttonStyle(.plain)
                                .disabled(!allowsCardInteraction(temporary.id))
                                .accessibilityLabel(ChekinanaProductCopy.text(
                                    "scan.shot_type",
                                    "Shot type"
                                ))
                                .accessibilityValue(ChekinanaProductCopy.text(
                                    userAppears
                                        ? "gallery.shot_filter.two_shot"
                                        : "gallery.shot_filter.solo",
                                    userAppears ? "2-shot" : "solo"
                                ))
                                .accessibilityHint(ChekinanaProductCopy.text(
                                    "scan.shot_type.toggle_hint",
                                    "Double-tap to switch between solo and 2-shot."
                                ))
                                .accessibilityIdentifier(
                                    "chekinana.scan.review.user-appears.\(temporary.id.uuidString.lowercased())"
                                )
                                Spacer(minLength: 0)
                            }
                        }
                        .padding(4)
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                    }

                    Button {
                        rotate(temporary.id)
                    } label: {
                        Image(systemName: "rotate.left")
                            .font(.callout.weight(.semibold))
                            .frame(width: 36, height: 36)
                            .foregroundStyle(.white)
                            .background(.black.opacity(0.72))
                            .clipShape(Circle())
                            .frame(
                                width: ChekinanaAccessibilityMetrics.minimumTouchTarget,
                                height: ChekinanaAccessibilityMetrics.minimumTouchTarget
                            )
                            .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .disabled(!allowsTransformRequest(temporary.id, isRefitFailed: temporary.isRefitFailed))
                    .accessibilityLabel(
                        transformingIDs.contains(temporary.id)
                            ? ChekinanaProductCopy.text("scan.rotating", "Rotating…")
                            : ChekinanaProductCopy.text(
                                "scan.rotate_counterclockwise",
                                "Rotate counterclockwise"
                            )
                    )
                    .accessibilityValue(ChekinanaProductCopy.format(
                        "scan.rotate_state",
                        "Counterclockwise turn %lld of 4",
                        Int64(
                            activeTransformIntents[temporary.id]?
                                .rotationQuarterTurns
                                ?? temporary.imageRotationQuarterTurns
                        )
                    ))
                    .accessibilityIdentifier(
                        "chekinana.scan.review.rotate.\(temporary.id.uuidString.lowercased())"
                    )
                    .frame(maxWidth: .infinity, alignment: .topTrailing)
                    .padding(4)

                    Button { refitOrUndo(temporary.id) } label: {
                        Text(
                            !temporary.hasRefitUndo
                                ? ChekinanaProductCopy.text("scan.review.refit", "Refit")
                                : ChekinanaProductCopy.text("scan.review.undo_refit", "Undo")
                        )
                        .font(.caption2.weight(.bold))
                        .lineLimit(1)
                        .padding(.horizontal, 7)
                        .padding(.vertical, 4)
                        .foregroundStyle(.white)
                        .background(.black.opacity(0.72))
                        .clipShape(Capsule())
                        .frame(minWidth: 44, minHeight: 44, alignment: .topTrailing)
                        .contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .disabled(
                        !allowsCardInteraction(temporary.id)
                            || annotationVisibleIDs.contains(temporary.id)
                            || annotationLoadingIDs.contains(temporary.id)
                    )
                    .accessibilityIdentifier(
                        "chekinana.scan.review.refit.\(temporary.id.uuidString.lowercased())"
                    )
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomTrailing)
                    .padding(4)
                }

                temporaryMetadataGrid(temporary, position: position, snapshot: snapshot)
                temporaryActionRow(card, temporary: temporary)
            }
            .padding(8)
            .overlay {
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .stroke(ChekinanaProductTheme.border, lineWidth: 0.75)
            }
            .accessibilityElement(children: .contain)
            .accessibilityIdentifier("chekinana.scan.review.card.\(position)")
        }
    }

    private func temporaryMetadataGrid(
        _ temporary: ChekinanaConfirmationLedger.TemporaryCheki,
        position: Int,
        snapshot: RenderSnapshot
    ) -> some View {
        let selectedIdols = snapshot.idols.filter { temporary.idolIDs.contains($0.id) }
        let idolValue = selectedIdols.map(\.name).joined(separator: ", ").nonEmpty
            ?? ChekinanaProductCopy.text("common.unassigned", "Unassigned")
        let dateValue = temporary.date.map(ChekinanaProductDate.displayString)
            ?? ChekinanaProductCopy.text(
                "scan.review.date_not_recognized",
                "Date not recognized"
            )
        let eventValue = temporary.eventID.flatMap { id in
            snapshot.events[id]?.name
        } ?? ChekinanaProductCopy.text("scan.review.no_event", "No Event")
        let displayedSize = activeTransformIntents[temporary.id]?.size
            ?? temporary.desiredTransformSize
        let matchesExistingRecord = snapshot.records.matchesHint(
            temporary,
            eventID: temporary.eventID.flatMap { snapshot.events[$0]?.id },
            size: displayedSize
        )
        let columns = [
            GridItem(.flexible(minimum: 0), spacing: 8),
            GridItem(.flexible(minimum: 0), spacing: 8),
        ]
        return LazyVGrid(columns: columns, alignment: .leading, spacing: 6) {
            Button { beginSelectingIdols(temporary) } label: {
                compactAvatarStack(selectedIdols, position: position)
                    .frame(maxWidth: .infinity, minHeight: 34, alignment: .leading)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .buttonStyle(.plain)
            .disabled(!allowsCardInteraction(temporary.id))
            .accessibilityLabel(
                ChekinanaProductCopy.text("common.idol", "Idol")
            )
            .accessibilityValue(idolValue)
            .accessibilityIdentifier("chekinana.scan.review.idol.\(position)")

            Button { beginSelectingDate(temporary) } label: {
                Text(dateValue)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(
                        ChekinanaScanReviewDatePolicy.isFuture(temporary.date)
                            ? Color.red
                            : (temporary.date == nil ? Color.secondary : Color.primary)
                    )
                    .lineLimit(1)
                    .minimumScaleFactor(0.68)
                    .frame(maxWidth: .infinity, minHeight: 34, alignment: .trailing)
            }
            .frame(maxWidth: .infinity, alignment: .trailing)
            .buttonStyle(.plain)
            .disabled(!allowsCardInteraction(temporary.id))
            .accessibilityLabel(ChekinanaProductCopy.text("common.date", "Date"))
            .accessibilityValue(dateValue)
            .accessibilityIdentifier("chekinana.scan.review.date.\(position)")

            Menu {
                ForEach(ChekinanaChekiSizeCatalog.options(customSizes: customChekiSizes)) { option in
                    Button {
                        saveSizeSelection(id: temporary.id, size: option.size)
                    } label: {
                        if displayedSize == option.size {
                            Label(option.title, systemImage: "checkmark")
                        } else {
                            Text(option.title)
                        }
                    }
                }
            } label: {
                Label(
                    Optional(displayedSize).map {
                        ChekinanaChekiSizeCatalog.title(
                            for: $0,
                            customSizes: customChekiSizes
                        )
                    } ?? ChekinanaProductCopy.text(
                        "common.unknown",
                        "Unknown"
                    ),
                    systemImage: "aspectratio"
                )
                .font(.caption.weight(.semibold))
                .foregroundStyle(.primary)
                .lineLimit(1)
                .frame(maxWidth: .infinity, minHeight: 34, alignment: .leading)
            }
            .buttonStyle(.plain)
            .disabled(!allowsTransformRequest(temporary.id, isRefitFailed: temporary.isRefitFailed))
            .accessibilityLabel(ChekinanaProductCopy.text("common.size", "Size"))
            .accessibilityValue(
                Optional(displayedSize).map {
                    ChekinanaChekiSizeCatalog.title(
                        for: $0,
                        customSizes: customChekiSizes
                    )
                }
                    ?? ChekinanaProductCopy.text("common.unknown", "Unknown")
            )
            .accessibilityIdentifier("chekinana.scan.review.size.\(position)")

            Button { beginSelectingEvent(temporary) } label: {
                Text(eventValue)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(temporary.eventID == nil ? .secondary : .primary)
                    .lineLimit(1)
                    .truncationMode(.tail)
                    .frame(maxWidth: .infinity, minHeight: 34, alignment: .trailing)
            }
                .buttonStyle(.plain)
                .disabled(!allowsCardInteraction(temporary.id))
                .accessibilityLabel(ChekinanaProductCopy.text("events.event", "Event"))
                .accessibilityValue(eventValue)
                .accessibilityIdentifier("chekinana.scan.review.event.\(position)")
        }
        .overlay {
            if matchesExistingRecord {
                GeometryReader { geometry in
                    let columnWidth = max(0, (geometry.size.width - 8) / 2)
                    Text(ChekinanaProductCopy.text(
                        "scan.review.matches_existing_record",
                        "Matches an existing record"
                    ))
                        .font(.caption2)
                        .lineLimit(1)
                        .minimumScaleFactor(0.6)
                        .foregroundStyle(.secondary)
                        .frame(width: columnWidth, alignment: .trailing)
                        .multilineTextAlignment(.trailing)
                        .position(
                            x: geometry.size.width - columnWidth / 2,
                            y: geometry.size.height / 2
                        )
                        .accessibilityIdentifier("chekinana.scan.review.record-match.\(position)")
                }
                .allowsHitTesting(false)
            }
        }
        .overlay(alignment: .topLeading) {
            if selectedIdols.count > 1 {
                ChekinanaAccessibilityValueMarker(
                    identifier: "chekinana.scan.review.avatar-count.\(position)",
                    label: ChekinanaProductCopy.text(
                        "scan.selected_idol_avatar_count",
                        "Selected Idol avatar count"
                    ),
                    value: selectedIdols.count.formatted(.number.locale(ChekinanaLanguagePreference.displayLocale()))
                )
            }
        }
    }

    @ViewBuilder
    private func compactAvatarStack(_ selectedIdols: [Idol], position: Int) -> some View {
        if selectedIdols.isEmpty {
            ChekinanaNeutralIdolAvatar(size: 32)
        } else {
            ChekinanaFittingAvatarStrip {
                HStack(spacing: 5) {
                    ForEach(selectedIdols) { idol in
                        ChekinanaReviewIdolAvatar(idol: idol, sessionID: avatarCacheSession)
                    }
                }
            }
            .accessibilityIdentifier("chekinana.scan.review.avatar-strip.\(position)")
            .accessibilityValue(selectedIdols.count.formatted(.number.locale(ChekinanaLanguagePreference.displayLocale())))
        }
    }

    private func temporaryActionRow(
        _ card: ChekinanaChekiCard,
        temporary: ChekinanaConfirmationLedger.TemporaryCheki
    ) -> some View {
        HStack(alignment: .center, spacing: 4) {
            temporaryActionButton(
                ChekinanaProductCopy.text("scan.review.download", "Download"),
                systemImage: "square.and.arrow.down",
                identifier: "chekinana.scan.review.download.\(card.id.uuidString.lowercased())"
            ) { download(card) }
            .disabled(
                !allowsCardInteraction(card.id)
                    || temporary.isRefitFailed
            )
            temporaryActionButton(
                annotationVisibleIDs.contains(card.id)
                    ? ChekinanaProductCopy.text("scan.review.view_clean", "View clean")
                    : ChekinanaProductCopy.text(
                        "scan.review.view_annotation",
                        "View detection box"
                    ),
                systemImage: annotationVisibleIDs.contains(card.id)
                    ? "photo" : "viewfinder",
                identifier: "chekinana.scan.review.annotation.\(card.id.uuidString.lowercased())"
            ) {
                toggleSourceAnnotation(
                    card.id,
                    source: temporary.reviewRectificationSource
                )
            }
            .disabled(
                temporary.reviewRectificationSource == nil
                    || annotationLoadingIDs.contains(card.id)
                    || refittingIDs.contains(card.id)
                    || temporary.isRefitFailed
                    || isSaving
            )
        }
    }

    private func temporaryActionButton(
        _ title: String,
        systemImage: String,
        identifier: String,
        value: String? = nil,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            VStack(spacing: 3) {
                Image(systemName: systemImage)
                    .font(.callout.weight(.semibold))
                    .frame(height: actionIconRegionHeight, alignment: .center)
                Text(title)
                    .font(.caption2.weight(.semibold))
                    .lineLimit(2, reservesSpace: true)
                    .multilineTextAlignment(.center)
                    .frame(
                        maxWidth: .infinity,
                        minHeight: actionTextRegionHeight,
                        maxHeight: actionTextRegionHeight,
                        alignment: .top
                    )
            }
            .frame(maxWidth: .infinity)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel(title)
        .accessibilityValue(value ?? "")
        .accessibilityIdentifier(identifier)
    }

    private var orderedIdols: [Idol] {
        idolOrdering.ordered(idols)
    }

    private func allowsCardInteraction(_ id: UUID) -> Bool {
        ChekinanaScanReviewInteractionPolicy.allowsCardInteraction(
            isSaving: isSaving,
            isSavingToPhotos: isSavingAllToPhotos,
            isRotating: transformingIDs.contains(id),
            isDownloading: downloadingIDs.contains(id)
        )
    }

    private func allowsTransformRequest(_ id: UUID, isRefitFailed: Bool? = nil) -> Bool {
        !isSaving && !isSavingAllToPhotos && !downloadingIDs.contains(id)
            && !refittingIDs.contains(id)
            && (isRefitFailed ?? ledger.temporaryCheki(id)?.isRefitFailed) == false
    }

    private func beginSelectingIdols(
        _ temporary: ChekinanaConfirmationLedger.TemporaryCheki
    ) {
        guard allowsCardInteraction(temporary.id) else { return }
        idolSelectionDraft = .init(
            id: temporary.id,
            selectedIDs: Set(temporary.idolIDs)
        )
    }

    private func saveIdolSelection(id: UUID, selectedIDs: Set<UUID>) -> Bool {
        guard let temporary = ledger.temporaryCheki(id) else { return false }
        let selectedIDs = selectedIDs.union(Set(temporary.idolIDs).intersection(hiddenIdols.hiddenIDs))
        guard allowsCardInteraction(id),
              ledger.replaceTemporaryChekiIdols(
            id: id,
            idolIDs: orderedIdols.filter { selectedIDs.contains($0.id) }.map(\.id)
        ) else {
            return false
        }
        let updated = reconcileThenRefresh(id)
        if updated { retireHiddenTemporaryCards() }
        return updated
    }

    private func beginSelectingDate(
        _ temporary: ChekinanaConfirmationLedger.TemporaryCheki
    ) {
        guard allowsCardInteraction(temporary.id) else { return }
        dateSelectionDraft = .init(id: temporary.id, date: temporary.date)
    }

    private func saveDateSelection(id: UUID, date: Date?) -> Bool {
        guard allowsCardInteraction(id),
              let temporary = ledger.temporaryCheki(id) else {
            return false
        }
        let automaticEventID = temporary.explicitlyEditedFields.contains(.event)
            ? ChekinanaChekiEventSelectionPolicy.validatedEventID(
                temporary.eventID,
                recordDate: date,
                events: events
            )
            : ChekinanaChekiEventAutoAssociation.uniqueEventID(
                for: date,
                events: events.map { ($0.id, $0.date) }
            )
        guard ledger.updateTemporaryChekiDate(
            id: id,
            date: date,
            automaticEventID: automaticEventID
        ) else {
            return false
        }
        return reconcileThenRefresh(id)
    }

    private func beginSelectingEvent(
        _ temporary: ChekinanaConfirmationLedger.TemporaryCheki
    ) {
        guard allowsCardInteraction(temporary.id) else { return }
        eventSelectionDraft = .init(
            id: temporary.id,
            date: temporary.date,
            eventID: temporary.eventID
        )
    }

    private func saveEventSelection(id: UUID, eventID: UUID?) -> Bool {
        guard allowsCardInteraction(id),
              let affectedIDs = ledger.updateTemporaryChekiEventAndMatchingBlanks(
                id: id,
                eventID: eventID,
                allowedIDs: Set(
                    cards.map(\.id).filter { allowsCardInteraction($0) }
                )
              ) else { return false }
        return affectedIDs.reduce(true) { result, affectedID in
            reconcileThenRefresh(affectedID) && result
        }
    }

    private func saveSizeSelection(id: UUID, size: ChekiSize?) {
        guard let size,
              allowsTransformRequest(id),
              let temporary = ledger.temporaryCheki(id) else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.review.temporary_size_update_unavailable",
                "This temporary Cheki is no longer editable."
            )
            return
        }
        let desiredSize = activeTransformIntents[id]?.size
            ?? temporary.desiredTransformSize
        guard desiredSize != size else { return }
        requestTransform(id: id, desiredSize: size, rotationDelta: 0)
    }

    private func requestTransform(
        id: UUID,
        desiredSize: ChekiSize?,
        rotationDelta: Int
    ) {
        guard let snapshot = ledger.beginTemporaryChekiTransform(
            id: id,
            desiredSize: desiredSize,
            counterclockwiseQuarterTurns: rotationDelta
        ) else { return }
        transformTasks[id]?.cancel()
        activeTransformIntents[id] = snapshot.intent
        transformingIDs.insert(id)
        let task = Task { @MainActor in
            do {
                let output = try await ChekinanaReviewChekiTransformRenderer.render(
                    sourceImage: snapshot.sourceImage,
                    reviewSource: snapshot.reviewRectificationSource,
                    intent: snapshot.intent
                )
                try Task.checkCancellation()
                let image = ChekinanaPendingChekiImage(
                    data: output.data,
                    filenameExtension: "jpg",
                    sourceID: snapshot.sourceImage.sourceID,
                    sourceOrigin: snapshot.sourceImage.sourceOrigin
                )
                let thumbnail = await ChekinanaImageWorker.thumbnailData(
                    from: output.data
                )
                try Task.checkCancellation()
                let publication = ledger.publishTemporaryChekiTransform(
                    id: id,
                    intent: snapshot.intent,
                    image: image,
                    thumbnailImageData: thumbnail,
                    dateAnnotationState: ChekinanaReviewChekiTransformRenderer
                        .dateAnnotation(
                            snapshot.sourceDateAnnotationState,
                            rotationQuarterTurns: snapshot.intent.rotationQuarterTurns
                        )
                )
                switch publication {
                case .published:
                    _ = reconcileThenRefresh(id)
                case .capacityExceeded:
                    statusMessage = ChekinanaProductCopy.text(
                        "scan.review.prepare_save_failed",
                        "Unable to prepare the temporary Cheki for saving."
                    )
                case .unavailable:
                    statusMessage = ChekinanaProductCopy.text(
                        "scan.review.temporary_size_update_unavailable",
                        "This temporary Cheki is no longer editable."
                    )
                case .stale:
                    break
                }
            } catch is CancellationError {
                // A superseded generation cannot publish.
            } catch {
                if ledger.failTemporaryChekiTransform(id: id, intent: snapshot.intent) {
                    statusMessage = ChekinanaProductCopy.text(
                        "scan.review.prepare_save_failed",
                        "Unable to prepare the temporary Cheki for saving."
                    )
                }
            }
            if activeTransformIntents[id] == snapshot.intent {
                transformTasks[id] = nil
                activeTransformIntents[id] = nil
                transformingIDs.remove(id)
            }
        }
        transformTasks[id] = task
    }

    private func refitOrUndo(_ id: UUID) {
        guard allowsCardInteraction(id),
              !annotationVisibleIDs.contains(id),
              !annotationLoadingIDs.contains(id),
              let temporary = ledger.temporaryCheki(id) else { return }
        if temporary.hasRefitUndo {
            releaseSourceAnnotation(id)
            if ledger.undoTemporaryChekiRefit(id: id) {
                // Card equality omits pixels/refit state. Publish Undo even
                // when its restored metadata compares equal to the current card.
                cardPresentationRevisions[id, default: 0] &+= 1
                refreshCard(id)
            }
            return
        }
        guard let snapshot = ledger.beginTemporaryChekiRefit(id: id) else { return }
        guard snapshot.reviewRectificationSource?.isValid == true else {
            if ledger.publishTemporaryChekiRefitFailure(id: id, intent: snapshot.intent) == .published {
                releaseSourceAnnotation(id)
                refreshCard(id)
            }
            return
        }
        releaseSourceAnnotation(id)
        activeTransformIntents[id] = snapshot.intent
        transformingIDs.insert(id)
        refittingIDs.insert(id)
        transformTasks[id] = Task { @MainActor in
            do {
                let result = try await ChekinanaOnDeviceScannerClient().refit(
                    snapshot.sourceImage,
                    size: snapshot.intent.size,
                    originalSource: snapshot.reviewRectificationSource,
                    rotationQuarterTurns: snapshot.intent.rotationQuarterTurns
                )
                try Task.checkCancellation()
                switch result {
                case .detectionCount:
                    if ledger.publishTemporaryChekiRefitFailure(
                        id: id, intent: snapshot.intent
                    ) == .published {
                        releaseSourceAnnotation(id)
                        refreshCard(id)
                    }
                case .image(let output):
                    guard let reviewSource = output.reviewRectificationSource else {
                        throw ChekinanaOnDeviceScannerError.rectificationFailed
                    }
                    let thumbnail = await ChekinanaImageWorker.thumbnailData(from: output.data)
                    try Task.checkCancellation()
                    let publication = ledger.publishTemporaryChekiRefit(
                        id: id,
                        intent: snapshot.intent,
                        image: ChekinanaPendingChekiImage(
                            data: output.data,
                            filenameExtension: output.filenameExtension,
                            sourceID: snapshot.sourceImage.sourceID,
                            sourceOrigin: snapshot.sourceImage.sourceOrigin
                        ),
                        thumbnailImageData: thumbnail,
                        reviewSource: reviewSource,
                        sourceAnnotation: output.sourceAnnotation,
                        rotationQuarterTurns: snapshot.intent.rotationQuarterTurns
                    )
                    switch publication {
                    case .published:
                        releaseSourceAnnotation(id)
                        refreshCard(id)
                    case .capacityExceeded, .unavailable:
                        statusMessage = ChekinanaProductCopy.text(
                            "scan.review.refit_failed", "Unable to refit this Cheki. The image was kept."
                        )
                    case .stale:
                        break
                    }
                }
            } catch ChekinanaRefitCornerPolicy.Failure.ambiguousCorrespondence {
                if ledger.publishTemporaryChekiRefitFailure(
                    id: id, intent: snapshot.intent
                ) == .published {
                    releaseSourceAnnotation(id)
                    refreshCard(id)
                }
            } catch is CancellationError {
                _ = ledger.failTemporaryChekiTransform(id: id, intent: snapshot.intent)
            } catch {
                if ledger.failTemporaryChekiTransform(id: id, intent: snapshot.intent) {
                    statusMessage = ChekinanaProductCopy.text(
                        "scan.review.refit_failed", "Unable to refit this Cheki. The image was kept."
                    )
                }
            }
            if activeTransformIntents[id] == snapshot.intent {
                transformTasks[id] = nil
                activeTransformIntents[id] = nil
                transformingIDs.remove(id)
                refittingIDs.remove(id)
            }
        }
    }

    private func invalidateTransform(_ id: UUID) {
        transformTasks[id]?.cancel()
        transformTasks[id] = nil
        activeTransformIntents[id] = nil
        transformingIDs.remove(id)
        refittingIDs.remove(id)
        _ = ledger.invalidateTemporaryChekiTransform(id: id)
    }

    private func invalidateAllTransforms() {
        let ids = Set(transformTasks.keys)
            .union(activeTransformIntents.keys)
            .union(transformingIDs)
            .union(refittingIDs)
        for id in ids {
            invalidateTransform(id)
        }
    }

    private func toggleFavorite(_ id: UUID) {
        guard ledger.toggleTemporaryChekiFavorite(id: id) != nil else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.temporary_unavailable",
                "This temporary Cheki is no longer available."
            )
            return
        }
        refreshCard(id)
    }

    private func toggleUserAppears(_ id: UUID) {
        guard allowsCardInteraction(id),
              ledger.toggleTemporaryChekiUserAppears(id: id) != nil else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.temporary_unavailable",
                "This temporary Cheki is no longer available."
            )
            return
        }
        refreshCard(id)
    }

    private func toggleSourceAnnotation(
        _ id: UUID,
        source: ChekinanaReviewRectificationSource?
    ) {
        guard !isSaving, !refittingIDs.contains(id),
              ledger.temporaryCheki(id)?.isRefitFailed == false else { return }
        if annotationVisibleIDs.contains(id) {
            releaseSourceAnnotation(id)
            return
        }
        guard let source, source.isValid else {
            releaseSourceAnnotation(id)
            return
        }
        annotationTasks[id]?.cancel()
        annotationLoadingIDs.insert(id)
        let task = Task { @MainActor in
            let outcome = await ChekinanaScannerAnnotationPreviewRenderer
                .renderFromSource(source)
            guard !Task.isCancelled,
                  ledger.temporaryCheki(id)?.reviewRectificationSource?.sourceIdentity
                    == source.sourceIdentity,
                  annotationTasks[id]?.isCancelled == false else { return }
            annotationLoadingIDs.remove(id)
            annotationTasks[id] = nil
            if let data = outcome.data, !data.isEmpty {
                annotationPreviewData[id] = data
                annotationVisibleIDs.insert(id)
            } else {
                statusMessage = ChekinanaProductCopy.text(
                    "scan.review.annotation_failed",
                    "Unable to prepare the detection box."
                )
            }
        }
        annotationTasks[id] = task
    }

    private func releaseSourceAnnotation(_ id: UUID) {
        annotationTasks[id]?.cancel()
        annotationTasks[id] = nil
        annotationLoadingIDs.remove(id)
        annotationVisibleIDs.remove(id)
        annotationPreviewData[id] = nil
    }

    private func releaseAllSourceAnnotations() {
        annotationTasks.values.forEach { $0.cancel() }
        annotationTasks.removeAll()
        annotationLoadingIDs.removeAll()
        annotationVisibleIDs.removeAll()
        annotationPreviewData.removeAll()
    }

    private func rotate(_ id: UUID) {
        guard allowsTransformRequest(id) else { return }
        requestTransform(id: id, desiredSize: nil, rotationDelta: 1)
    }

    private func beginEditing(_ temporary: ChekinanaConfirmationLedger.TemporaryCheki) {
        guard allowsCardInteraction(temporary.id) else { return }
        reconcileExistingMatch(for: temporary.id)
        guard let temporary = ledger.temporaryCheki(temporary.id) else { return }
        editorDraft = .init(
            temporaryID: temporary.id,
            idolIDs: Set(temporary.idolIDs),
            hasDate: temporary.date != nil,
            date: temporary.date.flatMap {
                ChekinanaDateOnly.displayDate(from: $0, calendar: .current)
            } ?? Date(),
            eventID: temporary.eventID,
            eventWasExplicitlyEdited: temporary.explicitlyEditedFields.contains(.event),
            existingChekiID: temporary.existingChekiID,
            existingSelectionIsManual: temporary.existingSelectionIsManual,
            userAppears: temporary.userAppears,
            size: temporary.size ?? .mini,
            isFavorite: temporary.isFavorite,
            hasPostedToSNS: temporary.hasPostedToSNS,
            note: temporary.note
        )
    }

    private func saveEditor() {
        guard let draft = editorDraft,
              allowsCardInteraction(draft.temporaryID),
              let currentTemporary = ledger.temporaryCheki(draft.temporaryID) else { return }
        let date: Date?
        if draft.hasDate {
            guard let canonical = ChekinanaDateOnly.canonicalDate(
                from: draft.date,
                displayedIn: .current
            ) else {
                statusMessage = ChekinanaProductCopy.text(
                    "error.normalize_date",
                    "Unable to normalize the selected date."
                )
                return
            }
            date = canonical
        } else {
            date = nil
        }
        let resolvedEventID: UUID?
        let eventWasAutoMatched: Bool
        if draft.eventWasExplicitlyEdited {
            resolvedEventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
                draft.eventID,
                recordDate: date,
                events: events
            )
            eventWasAutoMatched = false
        } else {
            resolvedEventID = ChekinanaChekiEventAutoAssociation.uniqueEventID(
                for: date,
                events: events.map { ($0.id, $0.date) }
            )
            eventWasAutoMatched = resolvedEventID != nil
        }
        let currentSize = currentTemporary.size ?? .mini
        let requestedSize = currentTemporary.isRefitFailed ? currentSize : (draft.size ?? .mini)
        let rebuildsSizePreview = requestedSize != currentSize
        guard ledger.updateTemporaryCheki(
            id: draft.temporaryID,
            idolIDs: Array(draft.idolIDs),
            date: date,
            eventID: resolvedEventID,
            userAppears: draft.userAppears ?? false,
            size: rebuildsSizePreview ? currentTemporary.size : requestedSize,
            isFavorite: draft.isFavorite,
            hasPostedToSNS: draft.hasPostedToSNS,
            note: draft.note,
            idx: nil,
            idxWasManuallyEdited: false,
            existingChekiID: draft.existingChekiID,
            existingSelectionIsManual: draft.existingSelectionIsManual,
            eventWasExplicitlyEdited: draft.eventWasExplicitlyEdited,
            eventWasAutoMatched: eventWasAutoMatched
        ) else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.temporary_unavailable",
                "This temporary Cheki is no longer available."
            )
            editorDraft = nil
            return
        }
        // The editor and Save all both read the ledger as their source of
        // truth. Rebuild the visible card unconditionally; existing-match
        // reconciliation may legitimately be a no-op and must not suppress UI.
        guard reconcileThenRefresh(draft.temporaryID) else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.temporary_unavailable",
                "This temporary Cheki is no longer available."
            )
            editorDraft = nil
            return
        }
        retireHiddenTemporaryCards()
        if rebuildsSizePreview, ledger.temporaryCheki(draft.temporaryID) != nil {
            requestTransform(
                id: draft.temporaryID,
                desiredSize: requestedSize,
                rotationDelta: 0
            )
        }
        editorDraft = nil
    }

    @discardableResult
    private func reconcileExistingMatch(
        for id: UUID, recordIndex: ChekinanaReviewRecordIndex? = nil
    ) -> Bool {
        guard let temporary = ledger.temporaryCheki(id) else { return false }
        let candidates = recordIndex?.matching(
            idolIDs: Set(temporary.idolIDs), date: temporary.date, size: temporary.size ?? .mini
        ) ?? matchingExistingChekis(
            idolIDs: Set(temporary.idolIDs), date: temporary.date, size: temporary.size ?? .mini
        )
        let targetID = ChekinanaScanReviewRecordMatchPolicy.targetID(
            candidates: candidates.map {
                .init(id: $0.id, date: $0.date, idolIDs: $0.idolIDs,
                      eventID: $0.eventID, size: $0.size, count: $0.count)
            },
            media: .init(date: temporary.date, idolIDs: temporary.idolIDs,
                         eventID: temporary.eventID, size: temporary.size ?? .mini)
        )
        let target = candidates.first { $0.id == targetID }
        guard ledger.reconcileScanReviewRecord(
            id: id, recordID: target?.id, eventID: target?.eventID, note: target?.note,
            snapshot: target.map(ChekinanaChekiRecordSnapshot.init)
        ) else { return false }
        if let updated = ledger.temporaryCheki(id),
           updated.existingChekiID == temporary.existingChekiID,
           updated.existingSelectionIsManual == temporary.existingSelectionIsManual,
           updated.eventID == temporary.eventID, updated.note == temporary.note {
            return true
        }
        refreshCard(id)
        return true
    }

    private func reconcileThenRefresh(_ id: UUID) -> Bool {
        ChekinanaScanReviewReconciliationPolicy.reconcileThenRefresh(
            reconcile: { reconcileExistingMatch(for: id) },
            refresh: { refreshCard(id) }
        )
    }

    @discardableResult
    private func refreshCard(_ id: UUID) -> Bool {
        guard let temporary = ledger.temporaryCheki(id),
              let index = cards.firstIndex(where: { $0.id == id }) else { return false }
        cards[index] = ChekinanaChekiCard(
            id: temporary.id,
            imageRef: nil,
            createdAt: temporary.createdAt,
            confirmationCode: nil,
            thumbnailImageData: temporary.thumbnailImageData,
            idolNames: temporary.idolIDs.compactMap { id in
                guard !hiddenIdols.hiddenIDs.contains(id) else { return nil }
                return idols.first { $0.id == id }?.name
            },
            eventName: temporary.eventID.flatMap { id in
                events.first { $0.id == id }?.name
            },
            eventDateText: temporary.date.map(ChekinanaProductDate.displayString),
            userAppears: temporary.userAppears,
            size: temporary.size,
            isFavorite: temporary.isFavorite,
            hasPostedToSNS: temporary.hasPostedToSNS,
            note: temporary.note,
            dateAnnotationState: temporary.dateAnnotationState
        )
        return true
    }

    private func delete(_ card: ChekinanaChekiCard) {
        deleteTemporary(id: card.id)
    }

    private func retireHiddenTemporaryCards() {
        let hiddenCardIDs = ChekinanaHiddenTemporaryReviewPolicy.hiddenCardIDs(
            cards,
            hiddenIdolIDs: hiddenIdols.hiddenIDs,
            idolIDs: { ledger.temporaryCheki($0)?.idolIDs }
        )
        guard !hiddenCardIDs.isEmpty else { return }
        if let id = editorDraft?.temporaryID, hiddenCardIDs.contains(id) { editorDraft = nil }
        if let id = idolSelectionDraft?.id, hiddenCardIDs.contains(id) {
            idolSelectionDraft = nil
        }
        if let id = dateSelectionDraft?.id, hiddenCardIDs.contains(id) {
            dateSelectionDraft = nil
        }
        hiddenCardIDs.forEach(releaseSourceAnnotation)
        for id in hiddenCardIDs {
            invalidateTransform(id)
            _ = ledger.discardTemporaryCheki(id: id)
        }
        cards.removeAll { hiddenCardIDs.contains($0.id) }
    }

    private func deleteTemporary(id: UUID) {
        guard allowsCardInteraction(id),
              ledger.discardTemporaryCheki(id: id) else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.review.delete_failed",
                "Unable to delete this temporary Cheki."
            )
            return
        }
        releaseSourceAnnotation(id)
        invalidateTransform(id)
        cards.removeAll { $0.id == id }
        if ChekinanaScanReviewLifecycle.shouldDiscardAfterDeletion(
            cardsAreEmpty: cards.isEmpty,
            hasCapturedPhoto: sourceRegistry.hasCapturedPhoto
        ) {
            discardEmptyReview()
        }
    }

    private func discardEntireReview() {
        guard ChekinanaScanReviewInteractionPolicy.allowsConfirmAll(
            isSaving: isSaving || isSavingAllToPhotos,
            hasRotations: !transformingIDs.isEmpty,
            hasSizePreviews: false,
            hasDownloads: !downloadingIDs.isEmpty
        ) else { return }
        invalidateAllTransforms()
        let sourceIDs = sourceRegistry.sourceIDs
        for sourceID in sourceIDs {
            _ = ledger.discardTemporaryChekis(sourceID: sourceID)
        }
        for card in cards {
            _ = ledger.discardTemporaryCheki(id: card.id)
        }
        releaseAllSourceAnnotations()
        downloadingIDs.removeAll()
        cards = []
        sourceRegistry.removeSources(ids: Set(sourceIDs))
        onDiscarded(sourceIDs)
    }

    private func discardEmptyReview() {
        guard cards.isEmpty else { return }
        let sourceIDs = sourceRegistry.sourceIDs
        sourceRegistry.removeSources(ids: Set(sourceIDs))
        onDiscarded(sourceIDs)
    }

    private func download(_ card: ChekinanaChekiCard) {
        guard allowsCardInteraction(card.id),
              ledger.areTemporaryChekiTransformsSettled([card.id]) else { return }
        downloadingIDs.insert(card.id)
        Task {
            defer { downloadingIDs.remove(card.id) }
            let executor = ChekinanaCommandExecutor(
                modelContext: modelContext,
                confirmationLedger: ledger
            )
            let response = await executor.execute(
                "downloadtemporarycheki \(card.id.uuidString.lowercased())"
            )
            if case .text(let text) = response,
               text.hasPrefix("error: ") {
                statusMessage = ChekinanaCommandCopy.displayText(text)
            }
        }
    }

    @MainActor
    private func saveAllToPhotos() async {
        guard ChekinanaScanReviewInteractionPolicy.allowsConfirmAll(
            isSaving: isSaving || isSavingAllToPhotos,
            hasRotations: !transformingIDs.isEmpty,
            hasSizePreviews: false,
            hasDownloads: !downloadingIDs.isEmpty
        ), ledger.areTemporaryChekiTransformsSettled(cards.map(\.id)),
        let imageData = ChekinanaScanReviewPhotoSavePolicy.orderedImageData(
            cardIDs: cards.map(\.id),
            imageData: { ledger.temporaryCheki($0)?.image.data }
        ) else {
            if !isSavingAllToPhotos {
                statusMessage = ChekinanaProductCopy.text(
                    "scan.review.save_all_to_photos_failed",
                    "The Review images could not be saved to Photos."
                )
            }
            return
        }

        isSavingAllToPhotos = true
        defer {
            isSavingAllToPhotos = false
            saveAllToPhotosTask = nil
        }
        do {
            try await ChekinanaProductPhotoSaver.saveImages(imageData)
        } catch is CancellationError {
            return
        } catch {
            guard !Task.isCancelled else { return }
            statusMessage = ChekinanaProductCopy.text(
                "scan.review.save_all_to_photos_failed",
                "The Review images could not be saved to Photos."
            )
        }
    }

    @MainActor
    private func confirmAll() async {
        guard ChekinanaScanReviewInteractionPolicy.allowsConfirmAll(
            isSaving: isSaving || isSavingAllToPhotos,
            hasRotations: !transformingIDs.isEmpty,
            hasSizePreviews: false,
            hasDownloads: !downloadingIDs.isEmpty
        ), ledger.areTemporaryChekiTransformsSettled(cards.map(\.id)) else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.review.wait_for_actions",
                "Wait for rotation or download to finish before saving."
            )
            return
        }
        isSaving = true
        batchSaveProgress = nil
        defer {
            batchSaveProgress = nil
            isSaving = false
        }
        let executor = ChekinanaCommandExecutor(
            modelContext: modelContext,
            confirmationLedger: ledger,
            batchSaveProgressObserver: { progress in
                batchSaveProgress = progress
            }
        )
        guard let selection = ChekinanaScanReviewSavePlan.selection(
            cardIDs: cards.map(\.id),
            containsTemporaryCheki: ledger.containsTemporaryCheki
        ) else {
            reconcileCardsWithLedger()
            statusMessage = ChekinanaProductCopy.text(
                "scan.review.stale_refreshed",
                "Some temporary Cheki became unavailable. The list was refreshed; review it and try again."
            )
            return
        }
        let prepared = executor.prepareScanReviewConfirmation(selection: selection)
        guard case .pendingChekiCards(_, let pendingCards, _) = prepared else {
            statusMessage = ChekinanaConfirmationResponseValidator.failureDescription(
                for: prepared,
                fallback: ChekinanaProductCopy.text(
                    "scan.review.prepare_save_failed",
                    "Unable to prepare the temporary Cheki for saving."
                )
            )
            return
        }
        let confirmationCodes = pendingCards.compactMap(\.confirmationCode)
        guard confirmationCodes.count == pendingCards.count else {
            ledger.cancelTemporaryChekiConfirmations(confirmationCodes)
            reconcileCardsWithLedger()
            statusMessage = ChekinanaProductCopy.text(
                "scan.review.confirmation_incomplete",
                "Save confirmation information is incomplete. Temporary Cheki were unlocked; edit them and try again."
            )
            return
        }
        let result = await executor.confirmTemporaryChekiBatch(
            confirmationCodes: confirmationCodes
        )
        let expectedIDs = pendingCards.map(\.id)
        guard case .chekiCards(let savedCards) = result,
              savedCards.map(\.id) == expectedIDs else {
            ledger.cancelTemporaryChekiConfirmations(confirmationCodes)
            reconcileCardsWithLedger()
            statusMessage = ChekinanaConfirmationResponseValidator.failureDescription(
                for: result,
                fallback: ChekinanaProductCopy.text(
                    "scan.review.batch_unverified",
                    "Batch save did not return a complete verifiable result. Temporary Cheki were kept."
                )
            )
            return
        }
        reconcileCardsWithLedger()
        guard cards.isEmpty else {
            statusMessage = ChekinanaProductCopy.text(
                "scan.review.state_changed",
                "Some temporary Cheki changed state. Unsaved items can still be retried."
            )
            return
        }
        onSaved(sourceRegistry.sourceIDs)
    }

    private func reconcileCardsWithLedger() {
        cards.removeAll { !ledger.containsTemporaryCheki($0.id) }
        for id in cards.map(\.id) {
            refreshCard(id)
        }
    }
}

private struct ChekinanaTemporaryImagePreview: View {
    let imageData: Data
    let annotationState: ChekinanaChekiDateAnnotationState
    let annotationPreviewData: Data?
    let showsSourceAnnotation: Bool
    let cacheKey: String
    @State private var cleanImage: ChekinanaRenderedImage?
    @State private var annotationImage: ChekinanaRenderedImage?
    @State private var requestedToken: String?

    private var usesSourceAnnotation: Bool {
        showsSourceAnnotation && annotationPreviewData?.isEmpty == false
    }

    private var loadRoute: ChekinanaScanPreviewLoadPublicationPolicy.Route {
        ChekinanaScanPreviewLoadPublicationPolicy.route(
            usesSourceAnnotation: usesSourceAnnotation
        )
    }

    private var displayToken: String {
        "\(cacheKey)-\(usesSourceAnnotation ? "source" : "clean")"
    }

    private var displayedImage: ChekinanaRenderedImage? {
        usesSourceAnnotation ? annotationImage : cleanImage
    }

    var body: some View {
        GeometryReader { geometry in
            if let image = displayedImage {
                let imageSize = CGSize(width: image.cgImage.width, height: image.cgImage.height)
                let fitted = aspectFitRect(imageSize: imageSize, in: geometry.size)
                ZStack(alignment: .topLeading) {
                    Image(decorative: image.cgImage, scale: 1)
                        .resizable()
                        .scaledToFit()
                        .frame(width: geometry.size.width, height: geometry.size.height)
                    if !usesSourceAnnotation,
                       case .detected(let annotation) = annotationState {
                        let box = annotation.boundingBox
                        RoundedRectangle(cornerRadius: 4)
                            .stroke(Color.orange, lineWidth: 3)
                            .background(Color.orange.opacity(0.10))
                            .frame(
                                width: fitted.width * CGFloat(box.x2 - box.x1) / 1_000,
                                height: fitted.height * CGFloat(box.y2 - box.y1) / 1_000
                            )
                            .offset(
                                x: fitted.minX + fitted.width * CGFloat(box.x1) / 1_000,
                                y: fitted.minY + fitted.height * CGFloat(box.y1) / 1_000
                            )
                            .accessibilityHidden(true)
                    }
                }
            } else {
                Color.clear
            }
        }
        .task(id: displayToken) {
            let token = displayToken
            let route = loadRoute
            requestedToken = token
            annotationImage = nil
            let loaded: ChekinanaRenderedImage?
            switch route {
            case .sharedCleanCache:
                loaded = await ChekinanaThumbnailCache.shared.thumbnailImage(
                    from: imageData,
                    key: token,
                    maxDimension: 1_200
                )
            case .transientAnnotation:
                guard let annotationPreviewData,
                      !annotationPreviewData.isEmpty else { return }
                // Annotation pixels are session-only. Decode through the
                // bounded, cancellation-aware ImageIO worker, but never put
                // either the bytes or CGImage in the global thumbnail cache.
                loaded = await ChekinanaImageWorker.previewImage(
                    from: annotationPreviewData,
                    maxDimension: 1_200
                )
            }
            guard ChekinanaScanPreviewLoadPublicationPolicy.canPublish(
                completedToken: token,
                requestedToken: requestedToken,
                completedRoute: route,
                currentRoute: loadRoute,
                isCancelled: Task.isCancelled
            ) else { return }
            switch route {
            case .sharedCleanCache:
                cleanImage = loaded
            case .transientAnnotation:
                annotationImage = loaded
            }
        }
        .onChange(of: displayToken) { _, token in
            // Invalidate publication before SwiftUI schedules the replacement
            // task. This also drops the session-only decoded annotation as
            // soon as the user switches back to the clean image.
            requestedToken = token
            annotationImage = nil
        }
        .onDisappear {
            // The `.task` above is structurally cancelled by SwiftUI. Clearing
            // its token prevents a synchronous late completion from
            // publishing, and releases the only View-owned annotation CGImage.
            requestedToken = nil
            annotationImage = nil
        }
    }

    private func aspectFitRect(imageSize: CGSize, in container: CGSize) -> CGRect {
        guard imageSize.width > 0, imageSize.height > 0 else { return .zero }
        let scale = min(container.width / imageSize.width, container.height / imageSize.height)
        let size = CGSize(width: imageSize.width * scale, height: imageSize.height * scale)
        return CGRect(
            x: (container.width - size.width) / 2,
            y: (container.height - size.height) / 2,
            width: size.width,
            height: size.height
        )
    }
}

private struct ChekinanaNeutralIdolAvatar: View {
    let size: CGFloat

    var body: some View {
        ZStack {
            Circle().fill(Color(uiColor: .tertiarySystemGroupedBackground))
            Image(systemName: "person.crop.circle")
                .font(.system(size: size * 0.58, weight: .regular))
                .foregroundStyle(.secondary)
        }
        .frame(width: size, height: size)
        .clipShape(Circle())
        .overlay {
            Circle().strokeBorder(Color.secondary.opacity(0.28), lineWidth: 1)
