}

private struct ChekinanaNativeDateSelectionView: View {
    @Environment(\.dismiss) private var dismiss
    let onSave: (Date?) -> Bool
    @State private var hasDate: Bool
    @State private var date: Date
    @State private var errorMessage: String?

    init(initialDate: Date?, onSave: @escaping (Date?) -> Bool) {
        self.onSave = onSave
        _hasDate = State(initialValue: initialDate != nil)
        _date = State(initialValue: initialDate.flatMap {
            ChekinanaDateOnly.displayDate(from: $0, calendar: .current)
        } ?? Date())
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    Toggle(ChekinanaProductCopy.text(
                        "scan.review.date_picker.use_date",
                        "Use selected date"
                    ), isOn: $hasDate)
                        .accessibilityIdentifier("chekinana.scan.review.date-picker.use-date")
                    if hasDate {
                        ChekinanaExpandableDateWheel(
                            ChekinanaProductCopy.text("common.date", "Date"),
                            selection: $date,
                            accessibilityIdentifier: "chekinana.scan.review.date-picker.value"
                        )
                    } else {
                        Text(ChekinanaProductCopy.text(
                            "scan.review.date_not_recognized",
                            "Date not recognized"
                        ))
                            .foregroundStyle(.secondary)
                    }
                    Button(ChekinanaProductCopy.text(
                        "scan.review.date_picker.clear",
                        "Clear date"
                    ), role: .destructive) {
                        hasDate = false
                    }
                    .accessibilityIdentifier("chekinana.scan.review.date-picker.clear")
                } header: {
                    Text(ChekinanaProductCopy.text("common.date", "Date"))
                } footer: {
                    Text(ChekinanaProductCopy.text(
                        "scan.review.date_picker.footer",
                        "Changing the date keeps an existing selected Event when possible. Clearing the date does not remove the original image."
                    ))
                }
            }
            .navigationTitle(ChekinanaProductCopy.text(
                "scan.review.date_picker.title",
                "Select Date"
            ))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) { dismiss() }
                        .accessibilityIdentifier("chekinana.scan.review.date-picker.cancel")
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done"), action: save)
                        .accessibilityIdentifier("chekinana.scan.review.date-picker.done")
                }
            }
            .alert(ChekinanaProductCopy.text(
                "scan.review.date_picker.update_failed",
                "Unable to update date"
            ), isPresented: Binding(
                get: { errorMessage != nil },
                set: { if !$0 { errorMessage = nil } }
            )) {
                Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) { errorMessage = nil }
            } message: {
                Text(errorMessage ?? "")
            }
        }
        .accessibilityIdentifier("chekinana.scan.review.date-picker")
        .chekinanaSheetDraftDismiss(
            snapshot: { [AnyHashable(hasDate), AnyHashable(hasDate ? date : nil)] }
        )
    }

    private func save() {
        let normalizedDate: Date?
        if hasDate {
            guard let normalized = ChekinanaPersistedContentDatePolicy
                .canonicalDate(from: date) else {
                errorMessage = ChekinanaProductCopy.text(
                    "error.normalize_date",
                    "Unable to normalize the selected date."
                )
                return
            }
            normalizedDate = normalized
        } else {
            normalizedDate = nil
        }
        guard onSave(normalizedDate) else {
            errorMessage = ChekinanaProductCopy.text(
                "scan.review.temporary_date_update_unavailable",
                "This temporary Cheki is no longer editable or is awaiting confirmation. The current date was kept."
            )
            return
        }
        dismiss()
    }
}

