struct ChekinanaLongPressReorderState: Equatable {
    private(set) var draggingID: UUID?
    private(set) var startOrderIDs: [UUID] = []
    private(set) var previewOrderIDs: [UUID] = []
    private(set) var residualOffsetY: CGFloat = 0

    mutating func begin(id: UUID, orderedIDs: [UUID]) {
        guard draggingID == nil, orderedIDs.contains(id) else { return }
        draggingID = id
        startOrderIDs = orderedIDs
        previewOrderIDs = orderedIDs
        residualOffsetY = 0
    }

    mutating func update(
        translationY: CGFloat,
        rowStride: CGFloat,
        partitionByID: [UUID: Bool]
    ) {
        guard rowStride > 0,
              let sourceID = draggingID,
              let sourcePartition = partitionByID[sourceID],
              let sourceIndex = startOrderIDs.firstIndex(of: sourceID) else {
            return
        }
        let partitionIDs = startOrderIDs.filter {
            partitionByID[$0] == sourcePartition
        }
        guard let sourcePartitionIndex = partitionIDs.firstIndex(of: sourceID) else {
            return
        }
        let rowDelta = Int((translationY / rowStride).rounded())
        let targetPartitionIndex = min(
            max(sourcePartitionIndex + rowDelta, 0),
            partitionIDs.count - 1
        )
        let updated = ChekinanaReorderPreview.move(
            sourceID,
            onto: partitionIDs[targetPartitionIndex],
            in: startOrderIDs
        )
        let previewIndex = updated.firstIndex(of: sourceID) ?? sourceIndex
        let previewLayoutShift = CGFloat(previewIndex - sourceIndex) * rowStride
        let residual = translationY - previewLayoutShift
        if updated != previewOrderIDs {
            withAnimation(.snappy(duration: 0.16)) {
                previewOrderIDs = updated
                residualOffsetY = residual
            }
        } else {
            residualOffsetY = residual
        }
    }

    mutating func clear(animated: Bool = false) {
        if animated {
            withAnimation(.snappy(duration: 0.16)) {
                draggingID = nil
                startOrderIDs = []
                previewOrderIDs = []
                residualOffsetY = 0
            }
        } else {
            draggingID = nil
            startOrderIDs = []
            previewOrderIDs = []
            residualOffsetY = 0
        }
    }
}

private struct ChekinanaLongPressReorderHandle<Label: View>: View {
    let isEnabled: Bool
    let begin: () -> Void
    let update: (CGFloat) -> Void
    let commit: () -> Void
    let cancel: () -> Void
    let label: Label

    init(
        isEnabled: Bool,
        begin: @escaping () -> Void,
        update: @escaping (CGFloat) -> Void,
        commit: @escaping () -> Void,
        cancel: @escaping () -> Void,
        @ViewBuilder label: () -> Label
    ) {
        self.isEnabled = isEnabled
        self.begin = begin
        self.update = update
        self.commit = commit
        self.cancel = cancel
        self.label = label()
    }

    var body: some View {
        if isEnabled {
            label
                .highPriorityGesture(dragGesture)
        }
    }

    private var dragGesture: some Gesture {
        LongPressGesture(minimumDuration: 0.25, maximumDistance: 18)
            .sequenced(
                before: DragGesture(
                    minimumDistance: 0,
                    coordinateSpace: .global
                )
            )
            .onChanged { value in
                switch value {
                case .first(true):
                    begin()
                case .second(true, let drag):
                    begin()
                    if let drag { update(drag.translation.height) }
                default:
                    break
                }
            }
            .onEnded { value in
                if case .second(true, let drag) = value, let drag {
                    update(drag.translation.height)
                    commit()
                } else {
                    cancel()
                }
            }
    }
}

/// Memoize values only; current Query models remain the source for row content.
@MainActor
final class ChekinanaIdolListDerivedCache {
    struct MediaKey: Equatable {
        let idolIDs: Set<UUID>
        let hasImage: Bool
    }

    struct RecordKey: Equatable {
        let idolIDs: Set<UUID>
        let count: Int
    }

    struct CountKey: Equatable {
        let media: [UUID: MediaKey]
        let records: [UUID: RecordKey]
        let knownIdolIDs: Set<UUID>
        let hiddenIDs: Set<UUID>
    }

    struct IdolKey: Equatable {
        let favorite: Bool
        let count: Int
        let group: String
        let sortOrder: Double?
        let createdAt: Date
        let name: String
    }

    struct OrderKey: Equatable {
        var preferredID: UUID? = ChekinanaSingleOshiPreference.selectedID
        let idols: [UUID: IdolKey]
        let localeIdentifier: String
        let displayLocaleIdentifier: String
    }

    private var countKey: CountKey?
    private var cachedCounts: [UUID: Int] = [:]
    private var orderKey: OrderKey?
    private var cachedOrder: [UUID] = []

    func counts(for key: CountKey, compute: () -> [UUID: Int]) -> [UUID: Int] {
        if countKey != key {
            cachedCounts = compute()
            countKey = key
        }
        return cachedCounts
    }

    func order(for key: OrderKey, compute: () -> [UUID]) -> [UUID] {
        if orderKey != key {
            cachedOrder = compute()
            orderKey = key
        }
        return cachedOrder
    }

    static func presentedOrder(canonical: [UUID], preview: [UUID]) -> [UUID] {
        guard !preview.isEmpty else { return canonical }
        let known = Set(canonical)
        let retained = preview.filter { known.contains($0) }
        return retained.count == canonical.count ? retained : canonical
    }
}

private struct ChekinanaIdolsView: View {
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    private static let dragRowStride: CGFloat = 98

    @Environment(\.chekinanaSharedIdolCounts) private var sharedCounts

    @Environment(\.modelContext) private var modelContext
    @Environment(\.locale) private var listLocale
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.chekinanaThemeRevision) private var themeRevision
    @Query private var idols: [Idol]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query private var chekiRecords: [ChekiRecord]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let openMenu: () -> Void

    @State private var query = ""
    @FocusState private var isSearchFocused: Bool
    @State private var selectedIdol: Idol?
    @State private var isAddPresented = false
    @State private var reorderState = ChekinanaLongPressReorderState()
    @State private var derivedCache = ChekinanaIdolListDerivedCache()
    @State private var pendingMergedAvatarCleanup: ChekinanaIdolAvatarCleanupTarget?
    @State private var mergeCleanupMessage: String?

    private struct ListSnapshot {
        let counts: [UUID: Int]
        let orderedIdols: [Idol]
    }

    private var listSnapshot: ListSnapshot {
        let hiddenIDs = hiddenIdols.hiddenIDs
        let knownIdolIDs = Set(idols.map(\.id))
        let countKey = ChekinanaIdolListDerivedCache.CountKey(
            media: Dictionary(uniqueKeysWithValues: chekis.map {
                ($0.id, .init(idolIDs: ChekinanaIdolCardChekiCount.resolvedIdolIDs(
                    for: $0, knownIdolIDs: knownIdolIDs, authoritativeContext: modelContext
                ), hasImage: $0.imageRef?.nonEmpty != nil))
            }),
            records: Dictionary(uniqueKeysWithValues: chekiRecords.map {
                ($0.id, .init(idolIDs: Set($0.idolIDs), count: $0.count))
            }),
            knownIdolIDs: knownIdolIDs,
            hiddenIDs: hiddenIDs
        )
        let counts = derivedCache.counts(for: countKey) {
            if let reused = sharedCounts?.reusableFourPageCounts(
                source: ObjectIdentifier(modelContext.container), snapshot: countKey
            ) {
                return reused
            }
            if let sharedCounts {
                return sharedCounts.updateCounts(
                    source: ObjectIdentifier(modelContext.container), snapshot: countKey
                ).fourPage
            }
            return ChekinanaIdolCardChekiCount.countsByIdolID(
                snapshot: countKey, includesSharedHiddenRecords: true
            )
        }
        let visible = ChekinanaVisibilityPolicy.visibleIdols(idols, hiddenIDs: hiddenIDs)
        let canonical = derivedCache.order(for: .init(
            preferredID: idolOrdering.preferredID,
            idols: Dictionary(uniqueKeysWithValues: visible.map { idol in
                (idol.id, .init(
                    favorite: idol.isFavorite, count: counts[idol.id] ?? 0,
                    group: idol.group ?? "",
                    sortOrder: idol.sortOrder.flatMap { $0.isFinite ? $0 : nil },
                    createdAt: idol.createdAt, name: idol.name
                ))
            }),
            localeIdentifier: Locale.current.identifier,
            displayLocaleIdentifier: listLocale.identifier
                + "|" + ChekinanaLanguagePreference.displayLocale().identifier
        )) {
            ChekinanaIdolOrdering.orderedForList(visible, chekiCountsByIdolID: counts).map(\.id)
        }
        let order = ChekinanaIdolListDerivedCache.presentedOrder(
            canonical: canonical, preview: reorderState.previewOrderIDs
        )
        let byID = Dictionary(uniqueKeysWithValues: visible.map { ($0.id, $0) })
        return ListSnapshot(counts: counts, orderedIdols: order.compactMap { byID[$0] })
    }

    private var draggingIdolID: UUID? { reorderState.draggingID }
    private var dragResidualOffsetY: CGFloat { reorderState.residualOffsetY }

    var body: some View {
        let _ = languageRevision
        let _ = themeRevision
        let snapshot = listSnapshot
        NavigationStack {
            VStack(spacing: ChekinanaMainPageLayout.galleryHeaderToSegmentSpacing) {
                ChekinanaPinnedPageTitle(
                    title: ChekinanaProductTab.idols.title,
                    identifier: "chekinana.idols.fixed-title"
                )
                if snapshot.orderedIdols.isEmpty {
                    ChekinanaEmptyState(
                        title: ChekinanaProductCopy.text(
                            "idols.empty.title",
                            "No Idols yet"
                        ),
                        message: ChekinanaProductCopy.text(
                            "idols.empty.detail",
                            "Add an Idol to link Cheki and enable on-device recognition after storing patterns."
                        ),
                        systemImage: "person.2",
                        actionTitle: ChekinanaProductCopy.text(
                            "idols.add",
                            "Add Idol"
                        ),
                        action: { isAddPresented = true }
                    )
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .chekinanaScreenMarker("chekinana.idols.empty")
                } else {
                    idolsContent(
                        orderedIdols: snapshot.orderedIdols,
                        chekiCountsByIdolID: snapshot.counts
                    )
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(ChekinanaProductTheme.pageBackground)
            .navigationTitle("")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ChekinanaPageToolbar(pageID: "idols", openMenu: openMenu)
                ToolbarItem(placement: .topBarTrailing) {
                    Button { isAddPresented = true } label: {
                        Image(systemName: "plus")
                            .frame(width: 44, height: 44)
                    }
                    .accessibilityLabel(
                        ChekinanaProductCopy.text("idols.add", "Add Idol")
                    )
                    .accessibilityIdentifier("chekinana.idols.add")
                    .frame(width: 88, alignment: .trailing)
                }
            }
            .sheet(isPresented: $isAddPresented) {
                ChekinanaIdolEditorView(idol: nil)
            }
            .sheet(item: $selectedIdol) { idol in
                ChekinanaIdolDetailView(
                    idol: idol,
                    preparedAvatarImage: nil,
                    onMerged: { cleanup in
                        selectedIdol = nil
                        guard let cleanup else { return }
                        pendingMergedAvatarCleanup = cleanup
                        mergeCleanupMessage = ChekinanaProductCopy.text(
                            "idols.merge.avatar_cleanup_failed",
                            "The Idols were merged, but the deleted Idol's managed avatar could not be removed. Retry cleanup or close and leave the harmless orphaned file."
                        )
                    },
                    onDeleted: { cleanup in
                        selectedIdol = nil
                        guard let cleanup else { return }
                        pendingMergedAvatarCleanup = cleanup
                        mergeCleanupMessage = ChekinanaProductCopy.text(
                            "idols.delete.avatar_cleanup_failed",
                            "The Idol was deleted, but its managed avatar could not be removed. Retry cleanup or close and leave the harmless orphaned file."
                        )
                    }
                )
            }
            .alert(
                ChekinanaProductCopy.text(
                    "idols.avatar_cleanup_required",
                    "Avatar Cleanup Needed"
                ),
                isPresented: Binding(
                    get: { mergeCleanupMessage != nil },
                    set: { if !$0 { mergeCleanupMessage = nil } }
                )
            ) {
                if pendingMergedAvatarCleanup != nil {
                    Button(ChekinanaProductCopy.text("common.retry", "Retry")) {
                        retryMergedAvatarCleanup()
                    }
                    Button(ChekinanaProductCopy.text("common.close", "Close"), role: .cancel) {
                        pendingMergedAvatarCleanup = nil
                        mergeCleanupMessage = nil
                    }
                }
            } message: {
                Text(mergeCleanupMessage ?? "")
            }
        }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("chekinana.idols.page")
        .chekinanaScreenMarker("chekinana.idols.page")
        .environment(\.chekinanaDisplayHiddenIdolIDs, hiddenIdols.hiddenIDs)
    }

    private func retryMergedAvatarCleanup() {
        guard let cleanup = pendingMergedAvatarCleanup else { return }
        do {
            _ = try ChekinanaIdolReferenceStore.removeManagedAvatar(
                cleanup.imageRef,
                idolID: cleanup.idolID,
                directory: cleanup.directory
            )
            pendingMergedAvatarCleanup = nil
            mergeCleanupMessage = nil
        } catch {
            mergeCleanupMessage = ChekinanaProductCopy.format(
                "idols.merge.avatar_cleanup_retry_failed",
                "The Idols are merged, but avatar cleanup still failed: %@",
                error.localizedDescription
            )
        }
    }

    private func idolsContent(
        orderedIdols: [Idol],
        chekiCountsByIdolID: [UUID: Int]
    ) -> some View {
        let term = query.trimmingCharacters(in: .whitespacesAndNewlines)
        let filteredIdols = term.isEmpty ? orderedIdols : orderedIdols.filter {
            $0.name.localizedStandardContains(term)
                || ($0.group?.localizedStandardContains(term) ?? false)
                || $0.note.localizedStandardContains(term)
        }
        return ScrollView {
            LazyVStack(spacing: 12) {
                HStack(spacing: 10) {
                    Image(systemName: "magnifyingglass")
                        .foregroundStyle(.secondary)
                    TextField(
                        ChekinanaProductCopy.text(
                            "common.search_idols",
                            "Search Idols"
                        ),
                        text: $query
                    )
                        .textInputAutocapitalization(.never)
                        .autocorrectionDisabled()
                        .submitLabel(.search)
                        .focused($isSearchFocused)
                        .onSubmit { isSearchFocused = false }
                        .accessibilityLabel(ChekinanaProductCopy.text(
                            "common.search_idols",
                            "Search Idols"
                        ))
                        .accessibilityIdentifier("chekinana.idols.search")
                    if !query.isEmpty {
                        Button {
                            query = ""
                        } label: {
                            Image(systemName: "xmark.circle.fill")
                                .foregroundStyle(.secondary)
                                .frame(width: 32, height: 32)
                        }
                        .buttonStyle(.plain)
                        .chekinanaMinimumTouchTarget()
                        .accessibilityLabel(ChekinanaL10n.message("Clear search"))
                        .accessibilityIdentifier("chekinana.idols.search.clear")
                    }
                }
                .padding(.horizontal, 13)
                .frame(minHeight: 46)
                .background(Color(uiColor: .secondarySystemGroupedBackground))
                .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
                .overlay {
                    RoundedRectangle(cornerRadius: 13, style: .continuous)
                        .stroke(ChekinanaProductTheme.border, lineWidth: 0.5)
                }

                if filteredIdols.isEmpty {
                    ChekinanaEmptyState(
                        title: ChekinanaL10n.message("No matches"),
                        message: ChekinanaL10n.message("Try another name, group, or note."),
                        systemImage: "magnifyingglass"
                    )
                    .frame(maxWidth: .infinity, minHeight: 420)
                } else {
                    ForEach(filteredIdols) { idol in
                        idolRow(
                            idol,
                            chekiCountsByIdolID: chekiCountsByIdolID
                        )
                    }
                }
            }
            .padding(.horizontal, 16)
            .padding(.bottom, 110)
        }
    }

    private func reorderableIdolStack(
        orderedIdols: [Idol],
        chekiCountsByIdolID: [UUID: Int]
    ) -> some View {
        ZStack(alignment: .top) {
            ForEach(Array(orderedIdols.enumerated()), id: \.element.id) { index, idol in
                idolRow(
                    idol,
                    chekiCountsByIdolID: chekiCountsByIdolID
                )
                    .offset(y: CGFloat(index) * Self.dragRowStride)
                    .zIndex(draggingIdolID == idol.id ? 100_000 : 0)
                    .animation(
                        draggingIdolID == idol.id ? nil : .snappy(duration: 0.18),
                        value: index
                    )
            }
        }
        .frame(
            height: max(
                0,
                CGFloat(orderedIdols.count) * Self.dragRowStride - 12
            ),
            alignment: .top
        )
        .zIndex(draggingIdolID == nil ? 0 : 100_000)
    }

    @ViewBuilder
    private func idolRow(
        _ idol: Idol,
        chekiCountsByIdolID: [UUID: Int]
    ) -> some View {
        ChekinanaIdolRow(
            idol: idol,
            preparedAvatarImage: nil,
            chekiCount: chekiCountsByIdolID[idol.id] ?? 0,
            reorderEnabled: false,
            open: { selectedIdol = idol },
            toggleFavorite: { toggleFavorite(idol) },
            isBeingDragged: draggingIdolID == idol.id,
            dragOffsetY: draggingIdolID == idol.id ? dragResidualOffsetY : 0,
            beginDrag: {
                beginDrag(idol.id)
            },
            updateDrag: { translationY in
                updateDrag(translationY: translationY)
            },
            commitDrag: {
                commitDrag()
            },
            cancelDrag: {
                cancelDrag()
            }
        )
        .zIndex(draggingIdolID == idol.id ? 10_000 : 0)
    }

    private func toggleFavorite(_ idol: Idol) {
        idol.isFavorite.toggle()
        idol.updatedAt = Date()
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
        }
    }

    private func beginDrag(_ idolID: UUID) {
        guard reorderState.draggingID == nil else { return }
        guard idols.contains(where: { $0.id == idolID }) else { return }
        let order = ChekinanaIdolOrdering.orderedForList(
            idols,
            chekiCountsByIdolID: listSnapshot.counts
        ).map(\.id)
        reorderState.begin(id: idolID, orderedIDs: order)
    }

    private func updateDrag(translationY: CGFloat) {
        reorderState.update(
            translationY: translationY,
            rowStride: Self.dragRowStride,
            partitionByID: Dictionary(
                uniqueKeysWithValues: idols.map { ($0.id, $0.isFavorite) }
            )
        )
    }

    private func commitDrag() {
        defer { clearDragState() }
        guard let sourceID = reorderState.draggingID,
              reorderState.previewOrderIDs != reorderState.startOrderIDs,
              let source = idols.first(where: { $0.id == sourceID }),
              ChekinanaIdolOrdering.applyPreviewOrder(
                reorderState.previewOrderIDs,
                favorite: source.isFavorite,
                in: idols
              ) else {
            return
        }
        saveOrdering()
    }

    private func cancelDrag() {
        reorderState.clear(animated: true)
    }

    private func clearDragState() {
        reorderState.clear()
    }

    private func saveOrdering() {
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
        }
    }
}

enum ChekinanaIdolCardChekiCount {
    /// Callers supply a complete Idol snapshot from this exact context. Other
    /// contexts and detached objects retain their existing relationship getter.
    static func resolvedIdolIDs(
        for media: MediaItem, knownIdolIDs: Set<UUID>,
        authoritativeContext: ModelContext?
    ) -> Set<UUID> {
        if let authoritativeContext, media.modelContext === authoritativeContext {
            return Set(media.idolIDs).intersection(knownIdolIDs)
        }
        return Set(media.idols.map(\.id))
    }

    static func countsByIdolID(
        snapshot: ChekinanaIdolListDerivedCache.CountKey,
        includesSharedHiddenRecords: Bool = false
    ) -> [UUID: Int] {
        var result: [UUID: Int] = [:]
        for media in snapshot.media.values where media.hasImage {
            guard includesSharedHiddenRecords
                || media.idolIDs.isDisjoint(with: snapshot.hiddenIDs) else { continue }
            for id in media.idolIDs where !includesSharedHiddenRecords || !snapshot.hiddenIDs.contains(id) {
                result[id] = ChekinanaDisplayCount.adding(result[id] ?? 0, 1)
            }
        }
        for record in snapshot.records.values {
            guard includesSharedHiddenRecords
                || record.idolIDs.isDisjoint(with: snapshot.hiddenIDs) else { continue }
            let quantity = ChekinanaDisplayCount.normalized(record.count)
            for id in record.idolIDs where !includesSharedHiddenRecords || !snapshot.hiddenIDs.contains(id) {
                result[id] = ChekinanaDisplayCount.adding(result[id] ?? 0, quantity)
            }
        }
        return result
    }

    static func countsByIdolID(
        mediaChekis: some Sequence<MediaItem>,
        simpleRecords: some Sequence<ChekiRecord>,
        hiddenIDs: Set<UUID>,
        includesSharedHiddenRecords: Bool = false
    ) -> [UUID: Int] {
        if includesSharedHiddenRecords {
            // Shared visible content contributes only to visible Idol cards.
            return countsByIdolID(mediaChekis: mediaChekis, simpleRecords: simpleRecords,
                                 hiddenIDs: []).filter { !hiddenIDs.contains($0.key) }
        }
        var result: [UUID: Int] = [:]
        for cheki in mediaChekis
        where cheki.imageRef?.nonEmpty != nil
            && ChekinanaVisibilityPolicy.includesRecord(
                idols: cheki.idols,
                hiddenIDs: hiddenIDs
            ) {
            for idolID in Set(cheki.idols.map(\.id)) {
                result[idolID] = ChekinanaDisplayCount.adding(
                    result[idolID] ?? 0,
                    1
                )
            }
        }
        for record in simpleRecords where ChekinanaChekiRecordReadPolicy.isVisible(
            record,
            hiddenIDs: hiddenIDs
        ) {
            let quantity = ChekinanaDisplayCount.normalized(record.count)
            for idolID in Set(record.idolIDs) {
                result[idolID] = ChekinanaDisplayCount.adding(
                    result[idolID] ?? 0,
                    quantity
                )
            }
        }
        return result
    }
}

private enum ChekinanaIdolAvatarRepairError: LocalizedError {
    case missingCatalogueIdentity(String)

    var errorDescription: String? {
        switch self {
        case .missingCatalogueIdentity(let name):
            ChekinanaProductCopy.format(
                "idols.avatar_repair.missing_catalogue_identity",
                "%@ has no valid managed avatar and no catalogue identity. Edit this Idol and choose a local reference photo, then retry.",
                name
            )
        }
    }
}

