                .accessibilityLabel(ChekinanaL10n.message("Reorder \(idol.name)"))
                .accessibilityHint(ChekinanaL10n.text("Long press and drag to reorder within the favorite group.", fallback: "Long press and drag to reorder within the favorite group."))
                .accessibilityIdentifier(
                    "chekinana.idols.drag-handle.\(idol.id.uuidString.lowercased())"
                )
        }
    }

}

private struct ChekinanaIdolAvatar: View {
    @Environment(\.modelContext) private var modelContext
    let idol: Idol
    let size: CGFloat
    var preparedImage: ChekinanaRenderedImage? = nil
    var repairsMissingManagedAvatar = false
    var borderLineWidth: CGFloat = 2
    @State private var repairRequest = 0
    @State private var repairState = ChekinanaIdolAvatarRepairState.idle

    var body: some View {
        ZStack(alignment: .bottomTrailing) {
            ChekinanaIdolAvatarImage(
                name: idol.name,
                color: idol.color,
                imageRef: idol.avatarImageRef,
                cacheKey: "product-idol-\(idol.id.uuidString)",
                size: size,
                preparedImage: preparedImage,
                managedIdolID: idol.id,
                borderLineWidth: borderLineWidth
            )
            .id("\(idol.id.uuidString.lowercased())|\(idol.avatarImageRef ?? "none")")
            if repairsMissingManagedAvatar, repairState == .failed {
                Button {
                    repairRequest &+= 1
                } label: {
                    Image(systemName: "arrow.clockwise")
                        .font(.system(size: max(9, size * 0.16), weight: .bold))
                        .foregroundStyle(.white)
                        .frame(width: max(20, size * 0.34), height: max(20, size * 0.34))
                        .background(ChekinanaProductTheme.accent)
                        .clipShape(Circle())
                }
                .buttonStyle(.plain)
                .accessibilityLabel(ChekinanaProductCopy.format(
                    "idols.avatar.retry_for",
                    "Retry avatar for %@",
                    idol.name
                ))
                .accessibilityIdentifier(
                    "chekinana.idols.avatar-retry.\(idol.id.uuidString.lowercased())"
                )
            }
        }
        .task(id: repairRequest) {
            await repairMissingAvatarIfNeeded()
        }
    }

    @MainActor
    private func repairMissingAvatarIfNeeded() async {
        guard repairsMissingManagedAvatar,
              preparedImage == nil,
              repairState != .repairing else { return }
        guard idol.sourceId?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false else {
            repairState = .ready
            return
        }
        repairState = .repairing
        do {
            _ = try await ChekinanaIdolAvatarRepairCoordinator.repairIfNeeded(
                idol,
                in: modelContext
            )
            repairState = .ready
        } catch is CancellationError {
            repairState = .idle
        } catch {
            repairState = .failed
        }
    }
}

private enum ChekinanaIdolAvatarRepairState: Equatable {
    case idle
    case repairing
    case ready
    case failed
}

/// A view-owned source snapshot preserves immediate display while sharing the
/// same bytes with the existing asynchronous thumbnail validation.
@MainActor
private final class ChekinanaManagedAvatarSource {
    struct Snapshot {
        let identity: String
        let data: Data?
        let immediate: ChekinanaRenderedImage?
        var completedThumbnail = false
    }
    private var snapshot: Snapshot?

    func finish(identity: String, thumbnail: ChekinanaRenderedImage?) {
        guard let current = snapshot, current.identity == identity else { return }
        snapshot = Snapshot(
            identity: identity, data: nil,
            immediate: thumbnail ?? current.immediate, completedThumbnail: true
        )
    }

    func resolve(imageRef: String?, idolID: UUID) -> Snapshot {
        guard let url = try? ChekinanaIdolReferenceStore.managedAvatarURL(
            for: imageRef, idolID: idolID
        ) else {
            let empty = Snapshot(identity: "invalid|\(idolID)|\(imageRef ?? "")", data: nil, immediate: nil)
            snapshot = empty
            return empty
        }
        let attributes = try? FileManager.default.attributesOfItem(atPath: url.path)
        let modification = (attributes?[.modificationDate] as? Date)?.timeIntervalSince1970
        let creation = (attributes?[.creationDate] as? Date)?.timeIntervalSince1970
        let identity = "\(url.path)|\(attributes?[.systemFileNumber] ?? "missing")|\(attributes?[.size] ?? 0)|\(modification.map { String($0) } ?? "missing")|\(creation.map { String($0) } ?? "missing")"
        if let snapshot, snapshot.identity == identity, (snapshot.data != nil || snapshot.completedThumbnail) { return snapshot }
        let data = try? Data(contentsOf: url)
        let immediate = data.flatMap { UIImage(data: $0)?.cgImage }
            .map { ChekinanaRenderedImage(cgImage: $0) }
        let value = Snapshot(identity: identity, data: data, immediate: immediate)
        snapshot = value
        return value
    }
}

private struct ChekinanaIdolAvatarImage: View {
    let name: String
    let color: String?
    let imageRef: String?
    let cacheKey: String
    let size: CGFloat
    var preparedImage: ChekinanaRenderedImage? = nil
    var managedIdolID: UUID? = nil
    var borderLineWidth: CGFloat = 2
    @State private var localImage: ChekinanaRenderedImage?
    @State private var loadedSourceIdentity: String?
    @State private var managedSource = ChekinanaManagedAvatarSource()

    init(
        name: String,
        color: String?,
        imageRef: String?,
        cacheKey: String,
        size: CGFloat,
        preparedImage: ChekinanaRenderedImage? = nil,
        managedIdolID: UUID? = nil,
        borderLineWidth: CGFloat = 2
    ) {
        self.name = name
        self.color = color
        self.imageRef = imageRef
        self.cacheKey = cacheKey
        self.size = size
        self.preparedImage = preparedImage
        self.managedIdolID = managedIdolID
        self.borderLineWidth = borderLineWidth
    }

    var body: some View {
        let source = preparedImage == nil ? managedIdolID.map {
            managedSource.resolve(imageRef: imageRef, idolID: $0)
        } : nil
        let displayedLocalImage = source.map {
            loadedSourceIdentity == $0.identity ? (localImage ?? $0.immediate) : $0.immediate
        } ?? localImage
        ZStack {
            Circle().fill(
                preparedImage != nil || displayedLocalImage != nil
                    ? Color.white : ChekinanaProductColor.color(for: color).opacity(0.22)
            )
            if let preparedImage {
                Image(decorative: preparedImage.cgImage, scale: 1)
                    .resizable()
                    .scaledToFill()
                    .frame(width: size, height: size)
                    .clipShape(Circle())
            } else if let localImage = displayedLocalImage {
                Image(decorative: localImage.cgImage, scale: 1)
                    .resizable()
                    .scaledToFill()
                    .frame(width: size, height: size)
                    .clipShape(Circle())
            } else {
                placeholder
                    .frame(width: size, height: size)
                    .clipShape(Circle())
            }
        }
        .frame(width: size, height: size)
        .clipShape(Circle())
        .overlay {
            Circle().strokeBorder(
                ChekinanaProductColor.color(for: color),
                lineWidth: borderLineWidth
            )
        }
        .task(id: "\(localLoadTaskID)|\(source?.identity ?? "unbound")") {
            guard preparedImage == nil else { return }
            let loaded: ChekinanaRenderedImage?
            if managedIdolID != nil {
                if source?.completedThumbnail == true { return }
                if let data = source?.data {
                    loaded = await ChekinanaImageWorker.thumbnailImage(
                        from: data, maxDimension: 256
                    )
                } else {
                    loaded = nil
                }
            } else {
                loaded = await ChekinanaThumbnailCache.shared.thumbnailImage(
                    forManagedImageRef: imageRef,
                    key: localLoadID,
                    maxDimension: 256
                )
            }
            guard !Task.isCancelled else { return }
            if let source {
                managedSource.finish(identity: source.identity, thumbnail: loaded)
                localImage = loaded ?? source.immediate
                loadedSourceIdentity = source.identity
            } else if let loaded {
                localImage = loaded
            }
        }
    }

    private var localLoadID: String {
        "\(cacheKey)|\(managedIdolID?.uuidString.lowercased() ?? "unbound")|\(imageRef?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "<nil>")"
    }

    private var localLoadTaskID: String {
        "\(localLoadID)|prepared=\(preparedImage == nil ? 0 : 1)"
    }

    private var placeholder: some View {
        Color.clear
    }
}

private struct ChekinanaIdolDetailView: View {
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Query private var idols: [Idol]
    @Query private var events: [Event]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "shame" }) private var shames: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @Query private var memories: [Memory]
    @Query private var chekiRecords: [ChekiRecord]
    @Query private var eventSchedules: [EventSchedule]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let idol: Idol
    var preparedAvatarImage: ChekinanaRenderedImage? = nil
    let onMerged: (ChekinanaIdolAvatarCleanupTarget?) -> Void
    let onDeleted: (ChekinanaIdolAvatarCleanupTarget?) -> Void
    @State private var isEditing = false
    @State private var selectedCheki: MediaItem?
    @State private var showsLinkedEvents = false
    @State private var deleteMessage: String?
    @State private var pendingDeletedAvatarCleanup: ChekinanaIdolAvatarCleanupTarget?
    @State private var selectedMemory: Memory?
    @State private var showsMemories = false

    private var shameItems: [ChekinanaGalleryItem] { shames.filter { value in
        value.idols.contains { $0.id == idol.id }
            && ChekinanaFourPageVisibilityPolicy.includesRecord(idols: value.idols, hiddenIDs: hiddenIdols.hiddenIDs)
    }.map(ChekinanaGalleryItem.shame) }
    private var dougaItems: [ChekinanaGalleryItem] { dougas.filter { value in
        value.idols.contains { $0.id == idol.id }
            && ChekinanaFourPageVisibilityPolicy.includesRecord(idols: value.idols, hiddenIDs: hiddenIdols.hiddenIDs)
    }.map(ChekinanaGalleryItem.douga) }
    private var chekiItems: [ChekinanaGalleryItem] { chekis.filter {
        $0.idolIDs.contains(idol.id)
            && ChekinanaFourPageVisibilityPolicy.includesRecord(idolIDs: $0.idolIDs, hiddenIDs: hiddenIdols.hiddenIDs)
    }.map(ChekinanaGalleryItem.cheki) }
    private var linkedChekiRecords: [ChekiRecord] {
        chekiRecords.filter {
            ChekinanaChekiRecordReadPolicy.containsIdol($0, idolID: idol.id)
                && ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: $0.idolIDs,
                    hiddenIDs: hiddenIdols.hiddenIDs
                )
        }
    }
    private var linkedEvents: [Event] {
        ChekinanaIdolLinkedEventCount.linkedEvents(
            mediaChekis: chekis,
            simpleRecords: chekiRecords,
            relationshipIndex: ChekinanaChekiRecordRelationshipIndex(
                idols: idols,
                events: events
            ),
            idolID: idol.id,
            hiddenIDs: hiddenIdols.hiddenIDs,
            schedules: eventSchedules
        )
    }
    private var linkedMemories: [Memory] {
        memories.filter { $0.idolIDs.contains(idol.id) }
            .sorted { ($0.date ?? $0.createdAt) < ($1.date ?? $1.createdAt) }
    }

    @AppStorage(ChekinanaShotDisplayOrdering.defaultsKey) private var twoShotFirst = false

    var body: some View {
        let _ = twoShotFirst
        let _ = languageRevision
        let linkedEvents = self.linkedEvents
        NavigationStack {
            ScrollView {
                VStack(spacing: 10) {
                    HStack(spacing: 14) {
                        ChekinanaIdolAvatar(
                            idol: idol,
                            size: 76,
                            preparedImage: preparedAvatarImage
                        )
                        VStack(alignment: .leading, spacing: 4) {
                            Text(idol.name)
                                .font(.title2.weight(.bold))
                            if let group = idol.group?.nonEmpty {
                                Text(group)
                                    .font(.subheadline)
                                    .foregroundStyle(.secondary)
                            }
                        }
                        Spacer(minLength: 0)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    ChekinanaSectionCard {
                        if let birthday = ChekinanaBirthdayValue.localizedDisplay(
                            idol.birthday
                        ) {
                            detailRow(
                                ChekinanaProductCopy.text(
                                    "idols.birthday",
                                    "Birthday"
                                ),
                                value: birthday,
                                image: "gift"
                            )
                        }
                        mediaSummaryRow(
                            .cheki,
                            items: chekiItems,
                            count: ChekinanaDisplayCount.adding(
                                chekiItems.count,
                                ChekinanaChekiRecordStore.totalCount(
                                    linkedChekiRecords
                                )
                            )
                        )
                        mediaSummaryRow(.shame, items: shameItems)
                        mediaSummaryRow(.douga, items: dougaItems)
                        Button {
                            showsMemories = true
                        } label: {
                            detailRow(
                                ChekinanaProductCopy.text("gallery.memory", "Memory"),
                                value: linkedMemories.count.formatted(.number.locale(ChekinanaLanguagePreference.displayLocale())),
                                image: "text.book.closed"
                            )
                        }
                        .buttonStyle(.plain)
                        .disabled(linkedMemories.isEmpty)
                        Button {
                            showsLinkedEvents = true
                        } label: {
                            detailRow(
                                ChekinanaProductCopy.text(
                                    "events.title",
                                    "Events"
                                ),
                                value: linkedEvents.count.formatted(.number.locale(ChekinanaLanguagePreference.displayLocale())),
                                image: "music.note.house"
                            )
                        }
                        .buttonStyle(.plain)
                        .disabled(linkedEvents.isEmpty)
                        .accessibilityIdentifier("chekinana.idols.detail.events")
                    }
                    if !idol.note.isEmpty || idol.bio?.nonEmpty != nil {
                        ChekinanaSectionCard {
                            Text(idol.note.nonEmpty ?? idol.bio ?? "")
                                .font(.body)
                                .frame(maxWidth: .infinity, alignment: .leading)
                        }
                    }
                }
                .padding(18)
            }
            .background(ChekinanaProductTheme.pageBackground)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaL10n.message("Done")) { dismiss() }
                        .accessibilityIdentifier("chekinana.idols.detail.done")
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaL10n.message("Edit")) {
                        isEditing = true
                    }
                    .accessibilityIdentifier("chekinana.idols.detail.edit")
                }
            }
            .sheet(isPresented: $isEditing) {
                ChekinanaIdolEditorView(
                    idol: idol,
                    onMerged: { cleanup in
                        isEditing = false
                        onMerged(cleanup)
                        dismiss()
                    },
                    onHidden: {
                        isEditing = false
                        dismiss()
                    },
                    onDeleted: { cleanup in
                        isEditing = false
                        onDeleted(cleanup)
                        dismiss()
                    }
                )
            }
            .sheet(isPresented: $showsLinkedEvents) {
                ChekinanaIdolLinkedEventsView(
                    idolID: idol.id,
                    events: linkedEvents
                )
            }
            .sheet(item: $selectedMemory) { memory in
                ChekinanaMemoryDetailView(memory: memory)
            }
            .sheet(isPresented: $showsMemories) {
                ChekinanaMemoryListView(memories: linkedMemories, usesEventRows: true)
            }
            .navigationDestination(for: ChekinanaIdolMediaKind.self) { kind in
                ChekinanaIdolMediaDateView(idol: idol, kind: kind)
            }
            .alert(ChekinanaProductCopy.text("common.idol", "Idol"), isPresented: Binding(
                get: { deleteMessage != nil },
                set: { if !$0 { deleteMessage = nil } }
            )) {
                if pendingDeletedAvatarCleanup != nil {
                    Button(ChekinanaL10n.message("Retry cleanup")) { retryDeletedAvatarCleanup() }
                    Button(ChekinanaL10n.message("Close"), role: .cancel) { dismiss() }
                } else {
                    Button(ChekinanaL10n.message("OK"), role: .cancel) {}
                }
            } message: { Text(deleteMessage ?? "") }
                .chekinanaScreenMarker("chekinana.idols.detail")
                .fullScreenCover(item: $selectedCheki) { cheki in
                    ChekinanaGalleryDetailView(cheki: cheki)
                }
            }
            .environment(\.chekinanaDisplayHiddenIdolIDs, hiddenIdols.hiddenIDs)
    }

    private func deleteIdol() {
        let linkedCount = ChekinanaDisplayCount.adding(
            chekis.filter { $0.idolIDs.contains(idol.id) }.count,
            ChekinanaChekiRecordStore.totalCount(linkedChekiRecords)
        )
        guard linkedCount == 0 else {
            deleteMessage = ChekinanaProductCopy.format(
                "idols.delete.error.linked_records",
                "This Idol has %lld linked Cheki record(s). Reassign them before deleting.",
                Int64(linkedCount)
            )
            return
        }
        do {
            let result = try ChekinanaIdolPersistence.delete(idol, from: modelContext)
            hiddenIdols.removeDeleted(idol.id)
            if let cleanup = result.pendingAvatarCleanup {
                pendingDeletedAvatarCleanup = cleanup
                deleteMessage = ChekinanaProductCopy.text(
                    "idols.delete.avatar_cleanup_failed",
                    "The Idol was deleted, but its managed avatar could not be removed. Retry cleanup or close and leave the harmless orphaned file."
                )
                return
            }
            dismiss()
        } catch {
            deleteMessage = error.localizedDescription
        }
    }

    private func toggleFavorite() {
        do {
            try ChekinanaIdolFavoriteAction.toggle(
                idol,
                in: idols,
                modelContext: modelContext
            )
        } catch {
            deleteMessage = ChekinanaL10n.message("Favorite status could not be saved: \(error.localizedDescription)")
        }
    }

    private func retryDeletedAvatarCleanup() {
        guard let pendingDeletedAvatarCleanup else { return }
        do {
            _ = try ChekinanaIdolReferenceStore.removeManagedAvatar(
                pendingDeletedAvatarCleanup.imageRef,
                idolID: pendingDeletedAvatarCleanup.idolID,
                directory: pendingDeletedAvatarCleanup.directory
            )
            self.pendingDeletedAvatarCleanup = nil
            dismiss()
        } catch {
            deleteMessage = ChekinanaProductCopy.format(
                "idols.delete.avatar_cleanup_retry_failed",
                "The Idol is deleted, but avatar cleanup still failed: %@",
                error.localizedDescription
            )
        }
    }

    private func detailRow(_ title: String, value: String, image: String) -> some View {
        HStack(spacing: 12) {
            Group {
                if image == "text.book.closed" {
                    ChekinanaMemoryCategoryIcon()
                } else {
                    Image(systemName: image)
                }
            }.foregroundStyle(ChekinanaProductTheme.accent).frame(width: 26)
            Text(title)
            Spacer()
            Text(value).foregroundStyle(.secondary).multilineTextAlignment(.trailing)
        }
        .font(.body)
        .frame(minHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget)
        .contentShape(Rectangle())
    }

    @ViewBuilder private func mediaSummaryRow(
        _ kind: ChekinanaRecordKind,
        items: [ChekinanaGalleryItem],
        count: Int? = nil
    ) -> some View {
        let total = count ?? items.count
        NavigationLink(value: kind) {
            HStack(spacing: 12) {
                ChekinanaRecordCategoryIcon(kind: kind).frame(width: 26)
                Text(kind.title)
                Spacer()
                Text(total.formatted(.number.locale(ChekinanaLanguagePreference.displayLocale())))
                    .foregroundStyle(.secondary).multilineTextAlignment(.trailing)
            }
            .font(.body)
            .frame(minHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .disabled(total == 0)
        .accessibilityLabel(ChekinanaL10n.message("\(kind.title), \(kind.countLabel(total))"))
        .accessibilityIdentifier("chekinana.idols.detail.type.\(kind.rawValue)")
    }

    private func mediaItems(for kind: ChekinanaIdolMediaKind) -> [ChekinanaGalleryItem] {
        switch kind { case .cheki: chekiItems; case .shame: shameItems; case .douga: dougaItems }
    }
}

enum ChekinanaIdolLinkedEventCount {

    /// One scalar pass for all rows. Counting never needs the display ordering.
    static func countsByEventID(
        mediaChekis: [MediaItem], simpleRecords: [ChekiRecord],
        idolID: UUID, hiddenIDs: Set<UUID>
    ) -> [UUID: Int] {
        var counts: [UUID: Int] = [:]
        var seenMediaIDs: [UUID: Set<UUID>] = [:]
        for item in mediaChekis {
            guard item.kind == .cheki, item.imageRef?.nonEmpty != nil,
                  let eventID = item.eventID else { continue }
            let idolIDs = item.idolIDs
            guard idolIDs.contains(idolID),
                  ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: idolIDs, hiddenIDs: hiddenIDs
                  ), seenMediaIDs[eventID, default: []].insert(item.id).inserted
            else { continue }
            counts[eventID] = ChekinanaDisplayCount.adding(counts[eventID] ?? 0, 1)
        }
        for record in simpleRecords {
            guard let eventID = record.eventID else { continue }
            let idolIDs = record.idolIDs
            guard idolIDs.contains(idolID),
                  ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: idolIDs, hiddenIDs: hiddenIDs
                  ) else { continue }
            counts[eventID] = ChekinanaDisplayCount.adding(counts[eventID] ?? 0, record.count)
        }
        return counts
    }

    static func linkedEvents(
        mediaChekis: [MediaItem],
        simpleRecords: [ChekiRecord],
        relationshipIndex: ChekinanaChekiRecordRelationshipIndex,
        idolID: UUID,
        hiddenIDs: Set<UUID>,
        schedules: [EventSchedule] = []
    ) -> [Event] {
        var values: [UUID: Event] = [:]
        for cheki in mediaChekis where cheki.kind == .cheki
            && cheki.imageRef?.nonEmpty != nil
            && cheki.idolIDs.contains(idolID)
            && ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: cheki.idolIDs,
                hiddenIDs: hiddenIDs
            ) {
            if let event = relationshipIndex.event(for: cheki) {
                values[event.id] = event
            }
        }
        for record in simpleRecords
        where ChekinanaChekiRecordReadPolicy.containsIdol(record, idolID: idolID)
            && ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: record.idolIDs,
                hiddenIDs: hiddenIDs
            ) {
            if let event = relationshipIndex.event(for: record) {
                values[event.id] = event
            }
        }
        return ChekinanaEventOrdering.ordered(
            Array(values.values),
            schedules: schedules,
            dateAscending: true
        )
    }

    static func chekiCount(
        event: Event,
        mediaChekis: [MediaItem],
        simpleRecords: [ChekiRecord],
        idolID: UUID,
        hiddenIDs: Set<UUID>
    ) -> Int {
        let mediaCount = ChekinanaIdolEventChekiScope.mediaChekis(
            mediaChekis,
            eventID: event.id,
            idolID: idolID,
            hiddenIDs: hiddenIDs
        ).count
        let simpleCount = ChekinanaChekiRecordStore.totalCount(
            ChekinanaIdolEventChekiScope.simpleRecords(
                simpleRecords,
                eventID: event.id,
                idolID: idolID,
                hiddenIDs: hiddenIDs
            )
        )
        return ChekinanaDisplayCount.adding(mediaCount, simpleCount)
    }
}

enum ChekinanaIdolEventChekiScope {
    static func mediaChekis(
        _ mediaChekis: [MediaItem],
        eventID: UUID,
        idolID: UUID,
        hiddenIDs: Set<UUID>,
        chekiCountsByIdolID: [UUID: Int] = [:]
    ) -> [MediaItem] {
        ChekinanaEventChekiOrdering.ordered(
            mediaChekis.filter {
                $0.imageRef?.nonEmpty != nil
                    && $0.kind == .cheki
                    && $0.eventID == eventID
                    && $0.idolIDs.contains(idolID)
                    && ChekinanaFourPageVisibilityPolicy.includesRecord(
                        idolIDs: $0.idolIDs,
                        hiddenIDs: hiddenIDs
                    )
            },
            // The scoped filter above already applies the four-page shared
            // visibility rule. Do not apply Event's any-hidden exclusion again.
            hiddenIDs: [],
            chekiCountsByIdolID: chekiCountsByIdolID
        )
    }

    static func simpleRecords(
        _ records: [ChekiRecord],
        eventID: UUID,
        idolID: UUID,
        hiddenIDs: Set<UUID>
    ) -> [ChekiRecord] {
        records.filter {
            ChekinanaChekiRecordReadPolicy.isLinked($0, eventID: eventID)
                && ChekinanaChekiRecordReadPolicy.containsIdol($0, idolID: idolID)
                && ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: $0.idolIDs,
                    hiddenIDs: hiddenIDs
                )
        }.sorted { $0.id.uuidString < $1.id.uuidString }
    }
}

private struct ChekinanaIdolLinkedEventsView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Query(filter: #Predicate<CalendarGroupOrder> {
        $0.dateKey == "__chekinana_library_generation_v1__"
    }) private var libraryMarkers: [CalendarGroupOrder]
    @Query private var chekiRecords: [ChekiRecord]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let idolID: UUID
    let events: [Event]
    @State private var selectedEvent: Event?

    var body: some View {
        let counts = ChekinanaIdolLinkedEventCount.countsByEventID(
            mediaChekis: chekis, simpleRecords: chekiRecords,
            idolID: idolID, hiddenIDs: hiddenIdols.hiddenIDs
        )
        let visibleEvents = events.filter { (counts[$0.id] ?? 0) > 0 }
        let markers = libraryMarkers.map { "\($0.id)|\($0.groupKey)" }.sorted().joined(separator: ";")
        let avatarSourceKey = "\(ObjectIdentifier(modelContext.container))|\(markers)"
        NavigationStack {
            List(visibleEvents) { event in
                Button {
                    selectedEvent = event
                } label: {
                    HStack(spacing: 10) {
                        ChekinanaEventListAvatar(imageRef: event.avatarImageRef, sourceKey: avatarSourceKey, size: 36)
                        VStack(alignment: .leading, spacing: 2) {
                            Text(event.name)
                                .font(.subheadline.weight(.semibold))
                                .foregroundStyle(.primary)
                            Text(ChekinanaProductDate.displayString(event.date))
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                        Spacer(minLength: 8)
                        Text(
                            ChekinanaRecordKind.cheki.countLabel(
                                counts[event.id] ?? 0
                            )
                        )
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        Image(systemName: "chevron.right")
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(.tertiary)
                    }
                    .frame(minHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget)
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .accessibilityIdentifier(
                    "chekinana.idols.detail.event.\(event.id.uuidString.lowercased())"
                )
            }
            .listStyle(.plain)
            .navigationTitle(
                ChekinanaProductCopy.text("events.title", "Events")
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) {
                        dismiss()
                    }
                }
            }
            .sheet(item: $selectedEvent) {
                ChekinanaIdolEventChekiView(
                    event: $0,
                    idolID: idolID
                )
            }
        }
        .accessibilityIdentifier("chekinana.idols.detail.events.page")
    }
}

private struct ChekinanaIdolEventChekiView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Query(filter: #Predicate<CalendarGroupOrder> {
        $0.dateKey == "__chekinana_library_generation_v1__"
    }) private var libraryMarkers: [CalendarGroupOrder]
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query private var idols: [Idol]
    @Query private var chekiRecords: [ChekiRecord]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "shame" }) private var shames: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let event: Event
    let idolID: UUID
    @State private var selectedCheki: MediaItem?
    @State private var selectedOtherMedia: MediaItem?
    @State private var selectedRecord: ChekinanaChekiRecordSelection?

    private var scopedChekis: [MediaItem] {
        ChekinanaIdolEventChekiScope.mediaChekis(
            chekis,
            eventID: event.id,
            idolID: idolID,
            hiddenIDs: hiddenIdols.hiddenIDs,
            chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
        )
    }

    private var scopedRecords: [ChekiRecord] {
        ChekinanaIdolEventChekiScope.simpleRecords(
            chekiRecords,
            eventID: event.id,
            idolID: idolID,
            hiddenIDs: hiddenIdols.hiddenIDs
        )
    }

    private func scopedOtherMedia(_ values: [MediaItem]) -> [MediaItem] {
        values.filter {
            $0.eventID == event.id
                && ChekinanaIdolMediaScalarPolicy.includes(
                    idolIDs: $0.idolIDs,
                    targetIdolID: idolID,
                    hiddenIDs: hiddenIdols.hiddenIDs
                )
        }
    }

    private var groups: [ChekinanaCalendarIdolGroup] {
        ChekinanaCalendarIdolGroup.groups(
            for: scopedChekis,
            records: scopedRecords,
            relationshipIndex: ChekinanaChekiRecordRelationshipIndex(
                idols: idols
            ),
            groupsByExactIdolCombination: true,
            shames: scopedOtherMedia(shames),
            dougas: scopedOtherMedia(dougas),
            chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
        ).map { $0.displayingIdols(hiddenIDs: hiddenIdols.hiddenIDs) }
    }

    var body: some View {
        let groups = self.groups
        let markers = libraryMarkers.map { "\($0.id)|\($0.groupKey)" }.sorted().joined(separator: ";")
        let avatarSourceKey = "idol-event-\(ObjectIdentifier(modelContext.container))|\(markers)"
        NavigationStack {
            if groups.isEmpty {
                ContentUnavailableView(
                    ChekinanaProductCopy.text(
                        "calendar.no_records",
                        "No records"
                    ),
                    systemImage: "photo.on.rectangle.angled"
                )
                .navigationTitle(event.name)
                .navigationBarTitleDisplayMode(.inline)
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button(
                            ChekinanaL10n.text("action.back", fallback: "Back")
                        ) {
                            dismiss()
                        }
                        .accessibilityIdentifier(
                            "chekinana.idols.detail.event-cheki.empty.back"
                        )
                    }
                }
                .accessibilityIdentifier(
                    "chekinana.idols.detail.event-cheki.empty"
                )
            } else {
                ChekinanaUnifiedChekiGroupPage(
                    groups: groups,
                    title: event.name,
                    selectCheki: { selectedCheki = $0 },
                    selectRecord: {
                        selectedRecord = ChekinanaChekiRecordSelection(record: $0)
                    },
                    selectOtherMedia: { selectedOtherMedia = $0 },
                    asyncAvatarSourceKey: avatarSourceKey,
                    separatesMediaTypes: true,
                    onBack: { dismiss() }
                )
                .navigationTitle(event.name)
            }
        }
        .sheet(item: $selectedRecord) { selection in
            ChekinanaChekiRecordEditor(selection: selection)
        }
        .fullScreenCover(item: $selectedCheki) { cheki in
            ChekinanaGalleryDetailView(
                chekis: ChekinanaIdolChekiPagerScope.items(
                    from: scopedChekis,
                    matching: cheki
                ),
                initialID: cheki.id
            )
        }
        .fullScreenCover(item: $selectedOtherMedia) { media in
            ChekinanaGalleryMediaPagerView(
                items: scopedOtherMedia(media.kind == .shame ? shames : dougas),
                kind: media.kind,
                initialID: media.id
            )
        }
        .accessibilityIdentifier("chekinana.idols.detail.event-cheki.page")
    }
}

private typealias ChekinanaIdolMediaKind = ChekinanaRecordKind

private enum ChekinanaIdolMediaDateGroupKey: Hashable {
    case dated(Date)
    case undated

    var title: String {
        switch self {
        case .dated(let date):
            ChekinanaProductDate.displayString(date)
        case .undated:
            ChekinanaProductCopy.text("common.no_date", "No date")
        }
    }

    static func < (lhs: Self, rhs: Self) -> Bool {
        switch (lhs, rhs) {
        case (.dated(let left), .dated(let right)): left < right
        case (.dated, .undated): true
        case (.undated, .dated), (.undated, .undated): false
        }
    }
}

private struct ChekinanaIdolMediaStrip: View {
    let items: [ChekinanaGalleryItem]
    var onSelect: ((ChekinanaGalleryItem) -> Void)? = nil

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            LazyHStack(spacing: 8) {
                ForEach(items) { item in
                    if let onSelect {
                        Button { onSelect(item) } label: {
                            ChekinanaGalleryCard(
                                item: item,
                                showsIdolAvatars: false
                            ).frame(width: 82)
                        }
                        .buttonStyle(.plain)
                        .contentShape(Rectangle())
                        .accessibilityIdentifier("chekinana.idols.detail.media.\(item.id)")
                    } else {
                        ChekinanaGalleryCard(
                            item: item,
                            showsIdolAvatars: false
                        ).frame(width: 82)
                    }
                }
            }
        }
    }
}

private struct ChekinanaIdolMediaDateView: View {
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query private var chekiRecords: [ChekiRecord]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "shame" }) private var shames: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let idol: Idol
    let kind: ChekinanaIdolMediaKind
    private var items: [ChekinanaGalleryItem] {
        let idolID = idol.id
        let hiddenIDs = hiddenIdols.hiddenIDs
        switch kind {
        case .cheki:
            return chekis.filter {
                ChekinanaIdolMediaScalarPolicy.includes(
                    idolIDs: $0.idolIDs,
                    targetIdolID: idolID,
                    hiddenIDs: hiddenIDs
                )
            }.map(ChekinanaGalleryItem.cheki)
        case .shame:
            return shames.filter {
                ChekinanaIdolMediaScalarPolicy.includes(
                    idolIDs: $0.idolIDs,
                    targetIdolID: idolID,
                    hiddenIDs: hiddenIDs
                )
            }.map(ChekinanaGalleryItem.shame)
        case .douga:
            return dougas.filter {
                ChekinanaIdolMediaScalarPolicy.includes(
                    idolIDs: $0.idolIDs,
                    targetIdolID: idolID,
                    hiddenIDs: hiddenIDs
                )
            }.map(ChekinanaGalleryItem.douga)
        }
    }
    private var groups: [(key: ChekinanaIdolMediaDateGroupKey, count: Int)] {
        let idolID = idol.id
        let hiddenIDs = hiddenIdols.hiddenIDs
        var counts: [ChekinanaIdolMediaDateGroupKey: Int] = [:]
        for item in items {
            let dateKey = key(for: item.date)
            counts[dateKey] = ChekinanaDisplayCount.adding(
                counts[dateKey, default: 0],
                1
            )
        }
        if kind == .cheki {
            for record in chekiRecords where
                ChekinanaChekiRecordReadPolicy.containsIdol(record, idolID: idolID)
                    && ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: record.idolIDs,
                        hiddenIDs: hiddenIDs
                    ) {
                let dateKey = key(for: record.date)
                counts[dateKey] = ChekinanaDisplayCount.adding(
                    counts[dateKey, default: 0],
                    record.count
                )
            }
        }
        return counts.map { (key: $0.key, count: $0.value) }
            .sorted { $0.key < $1.key }
    }
    var body: some View {
        List {
            ForEach(groups, id: \.key) { group in
                NavigationLink {
                    ChekinanaIdolMediaDateGroupView(
                        idol: idol,
                        kind: kind,
                        groupKey: group.key
                    )
                } label: {
                    HStack(spacing: 10) {
                        Text(group.key.title)
                            .font(.subheadline.weight(.medium))
                        Spacer(minLength: 8)
                        Text(kind.countLabel(group.count))
                            .font(.caption.monospacedDigit())
                            .foregroundStyle(.secondary)
                    }
                    .frame(minHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget)
                    .contentShape(Rectangle())
                }
                .listRowInsets(
                    EdgeInsets(top: 1, leading: 16, bottom: 1, trailing: 16)
                )
                .accessibilityIdentifier(
                    "chekinana.idols.detail.date.\(kind.rawValue).\(group.key.stableID)"
                )
            }
        }
        .listStyle(.plain)
        .navigationTitle(kind.title)
        .navigationBarTitleDisplayMode(.inline)
        .accessibilityIdentifier("chekinana.idols.detail.date-page.\(kind.rawValue)")
    }

    private func key(for date: Date?) -> ChekinanaIdolMediaDateGroupKey {
        date.flatMap(ChekinanaDateOnly.canonicalized)
            .map(ChekinanaIdolMediaDateGroupKey.dated)
            ?? .undated
    }
}

enum ChekinanaIdolMediaScalarPolicy {
    static func includes(
        idolIDs: [UUID],
        targetIdolID: UUID,
        hiddenIDs: Set<UUID>
    ) -> Bool {
        idolIDs.contains(targetIdolID)
            && ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: idolIDs,
                hiddenIDs: hiddenIDs
            )
    }

    static func groupTitle(
        idolIDs: Set<UUID>,
        namesByID: [UUID: String],
        unassignedTitle: String
    ) -> String {
        idolIDs.compactMap { id in
            namesByID[id].map { (id: id, name: $0) }
        }
        .sorted { lhs, rhs in
            if lhs.name != rhs.name { return lhs.name < rhs.name }
            return lhs.id.uuidString < rhs.id.uuidString
        }
        .map { $0.name }
        .joined(separator: " · ")
        .nonEmpty
        ?? unassignedTitle
    }
}

private extension ChekinanaIdolMediaDateGroupKey {
    var stableID: String {
        switch self {
        case .dated(let date): ChekinanaDateOnly.string(date)
        case .undated: "undated"
        }
    }
}

struct ChekinanaIdolNoMediaChekiExactGroup: Hashable, Sendable {
    let idolIDs: Set<UUID>
    let canonicalDate: String?

    init(_ record: ChekiRecord) {
        idolIDs = Set(record.idolIDs)
        canonicalDate = record.date.map(ChekinanaDateOnly.string)
    }
}

struct ChekinanaIdolNoMediaChekiIdentity: Hashable, Sendable {
    let group: ChekinanaIdolNoMediaChekiExactGroup
    let note: String
    let eventID: UUID?
    let sizeRawValue: String?

    init(_ record: ChekiRecord) {
        group = ChekinanaIdolNoMediaChekiExactGroup(record)
        note = ChekinanaIdolNoMediaChekiGrouping.exactNoteKey(record.note)
        eventID = record.eventID
        sizeRawValue = record.sizeRawValue
    }
}

struct ChekinanaIdolNoMediaChekiFingerprint: Hashable, Sendable {
    let id: UUID
    let group: ChekinanaIdolNoMediaChekiExactGroup
    let note: String
    let eventID: UUID?
    let sizeRawValue: String?
    let count: Int

    init(_ record: ChekiRecord) {
        id = record.id
        group = ChekinanaIdolNoMediaChekiExactGroup(record)
        note = record.note
        eventID = record.eventID
        sizeRawValue = record.sizeRawValue
        count = max(1, record.count)
    }
}

struct ChekinanaIdolNoMediaChekiBatchDraft: Identifiable, Sendable {
    let selectedRecordIDs: [UUID]
    let identity: ChekinanaIdolNoMediaChekiIdentity
    let groupFingerprints: Set<ChekinanaIdolNoMediaChekiFingerprint>

    var id: String {
        selectedRecordIDs.map(\.uuidString).sorted().joined(separator: ",")
    }

    let quantity: Int
    var note: String { identity.note }
}

enum ChekinanaIdolNoMediaChekiBatchError: LocalizedError, Equatable {
    case invalidQuantity
    case changedRecords
    case missingRelationships

    var errorDescription: String? {
        switch self {
        case .invalidQuantity:
            ChekinanaProductRecordCreationError.invalidBatchQuantity.localizedDescription
        case .changedRecords:
            ChekinanaProductCopy.text(
                "idols.no_media_group.changed",
                "This Cheki record group changed. Reopen it and try again."
            )
        case .missingRelationships:
            ChekinanaProductRecordCreationError.modelContextMismatch.localizedDescription
        }
    }
}

@MainActor
enum ChekinanaIdolNoMediaChekiBatchWriter {
    static func draft(
        selectedRecordIDs: [UUID],
        allRecords: [ChekiRecord]
    ) throws -> ChekinanaIdolNoMediaChekiBatchDraft {
        let requestedIDs = Set(selectedRecordIDs)
        guard !requestedIDs.isEmpty,
              requestedIDs.count == selectedRecordIDs.count else {
            throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
        }
        let selected = allRecords.filter { requestedIDs.contains($0.id) }
        guard selected.count == requestedIDs.count,
              let first = selected.first else {
            throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
        }
        let identity = ChekinanaIdolNoMediaChekiIdentity(first)
        guard selected.allSatisfy({
            ChekinanaIdolNoMediaChekiIdentity($0) == identity
        }) else {
            throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
        }
        let matchingIDs = Set(allRecords.compactMap { record -> UUID? in
            ChekinanaIdolNoMediaChekiIdentity(record) == identity
                ? record.id : nil
        })
        guard matchingIDs == requestedIDs else {
            throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
        }
        let fingerprints = Set(allRecords.compactMap { record in
            ChekinanaIdolNoMediaChekiExactGroup(record) == identity.group
                ? ChekinanaIdolNoMediaChekiFingerprint(record)
                : nil
        })
        let quantity = try selected.reduce(0) { partialResult, record in
            try ChekinanaChekiRecordStore.checkedCountSum(
                partialResult,
                max(1, record.count)
            )
        }
        return .init(
            selectedRecordIDs: ordered(selected).map(\.id),
            identity: identity,
            groupFingerprints: fingerprints,
            quantity: quantity
        )
    }

    static func commit(
        _ draft: ChekinanaIdolNoMediaChekiBatchDraft,
        quantity: Int,
        note: String,
        in modelContext: ModelContext,
        saveContext: ChekinanaChekiRecordStore.SaveContext = { try $0.save() }
    ) throws -> [UUID] {
        guard quantity >= 0 else {
            throw ChekinanaIdolNoMediaChekiBatchError.invalidQuantity
        }
        var resultIDs: [UUID] = []
        do {
            try ChekinanaChekiRecordStore.withMutationLock {
                try modelContext.transaction {
                    let liveGroup = try candidateRecords(
                        for: draft.identity.group,
                        in: modelContext
                    ).filter {
                        ChekinanaIdolNoMediaChekiExactGroup($0)
                            == draft.identity.group
                    }
                    guard Set(liveGroup.map(
                        ChekinanaIdolNoMediaChekiFingerprint.init
                    )) == draft.groupFingerprints else {
                        throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
                    }
                    let liveByID = Dictionary(
                        uniqueKeysWithValues: liveGroup.map { ($0.id, $0) }
                    )
                    let selected = try draft.selectedRecordIDs.map {
                        id -> ChekiRecord in
                        guard let record = liveByID[id],
                              ChekinanaIdolNoMediaChekiIdentity(record)
                                == draft.identity else {
                            throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
                        }
                        return record
                    }

                    let requestedIdolIDs = draft.identity.group.idolIDs
                    let requestedIdolIDValues = Array(requestedIdolIDs)
                    var idolDescriptor = FetchDescriptor<Idol>(
                        predicate: #Predicate {
                            requestedIdolIDValues.contains($0.id)
                        }
                    )
                    idolDescriptor.fetchLimit = requestedIdolIDValues.count
                    let idols = try modelContext.fetch(idolDescriptor)
                    guard Set(idols.map(\.id)) == requestedIdolIDs,
                          idols.allSatisfy({ $0.modelContext === modelContext }) else {
                        throw ChekinanaIdolNoMediaChekiBatchError.missingRelationships
                    }
                    let recordDate = draft.identity.group.canonicalDate
                        .flatMap(ChekinanaDateOnly.parse)
                    let event: Event?
                    if let eventID = draft.identity.eventID {
                        var eventDescriptor = FetchDescriptor<Event>(
                            predicate: #Predicate { $0.id == eventID }
                        )
                        eventDescriptor.fetchLimit = 1
                        let matches = try modelContext.fetch(eventDescriptor)
                        guard matches.count == 1,
                              matches[0].modelContext === modelContext else {
                            throw ChekinanaIdolNoMediaChekiBatchError.missingRelationships
                        }
                        event = matches[0]
                    } else {
                        event = nil
                    }

                    guard let retained = ordered(selected).first else {
                        throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
                    }
                    ordered(selected).dropFirst().forEach(modelContext.delete)
                    guard quantity > 0 else {
                        modelContext.delete(retained)
                        resultIDs = []
                        return
                    }
                    let updated = try ChekinanaChekiRecordStore.update(
                        retained,
                        idols: ChekinanaIdolOrdering.ordered(idols),
                        event: event,
                        date: recordDate,
                        size: draft.identity.sizeRawValue
                            .flatMap(ChekiSize.init(rawValue:)),
                        note: note,
                        count: quantity,
                        in: modelContext,
                        // The enclosing transaction owns the one durable save;
                        // saving here used to persist once inside `update` and
                        // immediately save the same context a second time.
                        saveContext: { _ in }
                    )
                    resultIDs = updated.map { [$0.id] } ?? []
                }
                try saveContext(modelContext)
            }
            return resultIDs
        } catch {
            modelContext.rollback()
            throw error
        }
    }

    private static func ordered(
        _ values: [ChekiRecord]
    ) -> [ChekiRecord] {
        values.sorted { $0.id.uuidString < $1.id.uuidString }
    }

    private static func candidateRecords(
        for group: ChekinanaIdolNoMediaChekiExactGroup,
        in modelContext: ModelContext
    ) throws -> [ChekiRecord] {
        guard let canonicalDate = group.canonicalDate else {
            return try modelContext.fetch(FetchDescriptor<ChekiRecord>(
                predicate: #Predicate { $0.date == nil }
            ))
        }
        guard let day = ChekinanaDateOnly.parse(canonicalDate) else {
            throw ChekinanaIdolNoMediaChekiBatchError.changedRecords
        }
        let nextDay = day.addingTimeInterval(86_400)
        let missingDateSentinel = Date.distantPast
        return try modelContext.fetch(FetchDescriptor<ChekiRecord>(
            predicate: #Predicate {
                ($0.date ?? missingDateSentinel) >= day
                    && ($0.date ?? missingDateSentinel) < nextDay
            }
        ))
    }
}

enum ChekinanaIdolChekiPagerScope {
    static func items(
        from candidates: [MediaItem],
        matching selected: MediaItem
    ) -> [MediaItem] {
        let selectedIdolIDs = Set(selected.idolIDs)
        let selectedDate = selected.date.map(ChekinanaDateOnly.string)
        return candidates.filter { candidate in
            candidate.kind == .cheki
                && candidate.imageRef?.nonEmpty != nil
                && Set(candidate.idolIDs) == selectedIdolIDs
                && candidate.date.map(ChekinanaDateOnly.string) == selectedDate
        }
    }
}

private struct ChekinanaIdolMediaDateGroupView: View {
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query private var chekiRecords: [ChekiRecord]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "shame" }) private var shames: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @Query private var allIdols: [Idol]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let idol: Idol
    let kind: ChekinanaIdolMediaKind
    let groupKey: ChekinanaIdolMediaDateGroupKey
    @State private var selected: ChekinanaGalleryItem?
    @State private var selectedChekiRecord: ChekinanaChekiRecordSelection?
    @State private var selectedNoMediaRecord: ChekinanaCalendarNoMediaRecord?

    private var items: [ChekinanaGalleryItem] {
        let idolID = idol.id
        let hiddenIDs = hiddenIdols.hiddenIDs
        let candidates: [ChekinanaGalleryItem]
        switch kind {
        case .cheki:
            candidates = chekis
                .filter {
                    ChekinanaIdolMediaScalarPolicy.includes(
                        idolIDs: $0.idolIDs,
                        targetIdolID: idolID,
                        hiddenIDs: hiddenIDs
                    )
                }
                .map(ChekinanaGalleryItem.cheki)
        case .shame:
            candidates = shames
                .filter {
                    ChekinanaIdolMediaScalarPolicy.includes(
                        idolIDs: $0.idolIDs,
                        targetIdolID: idolID,
                        hiddenIDs: hiddenIDs
                    )
                }
                .map(ChekinanaGalleryItem.shame)
        case .douga:
            candidates = dougas
                .filter {
                    ChekinanaIdolMediaScalarPolicy.includes(
                        idolIDs: $0.idolIDs,
                        targetIdolID: idolID,
                        hiddenIDs: hiddenIDs
                    )
                }
                .map(ChekinanaGalleryItem.douga)
        }
        return ChekinanaRecordOrdering.ordered(
            candidates.filter { key(for: $0.date) == groupKey },
            ascending: true
        )
    }

    private var dateGroupMediaChekis: [MediaItem] {
        items.compactMap { item in
            guard case .cheki(let cheki) = item,
                  cheki.imageRef?.nonEmpty != nil else { return nil }
            return cheki
        }
    }

    private var dateGroupChekiRecords: [ChekiRecord] {
        let idolID = idol.id
        let hiddenIDs = hiddenIdols.hiddenIDs
        return chekiRecords.filter {
            ChekinanaChekiRecordReadPolicy.containsIdol($0, idolID: idolID)
                && key(for: $0.date) == groupKey
                && ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: $0.idolIDs,
                    hiddenIDs: hiddenIDs
                )
        }
        .sorted { $0.id.uuidString < $1.id.uuidString }
    }

    private var chekiGroups: [ChekinanaCalendarIdolGroup] {
        ChekinanaCalendarIdolGroup.groups(
            for: dateGroupMediaChekis,
            records: dateGroupChekiRecords,
            relationshipIndex: ChekinanaChekiRecordRelationshipIndex(
                idols: allIdols
            ),
            groupsByExactIdolCombination: true,
            chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
        ).map { $0.displayingIdols(hiddenIDs: hiddenIdols.hiddenIDs) }
    }

    var body: some View {
        Group {
            if kind == .cheki {
                ChekinanaUnifiedChekiGroupPage(
                    groups: chekiGroups,
                    title: groupKey.title,
                    selectCheki: { selected = .cheki($0) },
                    selectRecord: {
                        selectedChekiRecord =
                            ChekinanaChekiRecordSelection(record: $0)
                    },
                    onBack: nil
                )
            } else {
                let values = items.compactMap { item -> MediaItem? in
                    switch item {
                    case .cheki: return nil
                    case .shame(let media), .douga(let media): return media
                    }
                }
                let mediaGroups = ChekinanaCalendarIdolGroup.groups(
                    for: [], records: [],
                    relationshipIndex: ChekinanaChekiRecordRelationshipIndex(idols: allIdols),
                    groupsByExactIdolCombination: true,
                    shames: kind == .shame ? values : [],
                    dougas: kind == .douga ? values : [],
                    chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
                ).map { $0.displayingIdols(hiddenIDs: hiddenIdols.hiddenIDs) }
                ChekinanaUnifiedChekiGroupPage(
                    groups: mediaGroups, title: groupKey.title,
                    selectCheki: { selected = .cheki($0) },
                    selectRecord: { selectedChekiRecord = ChekinanaChekiRecordSelection(record: $0) },
                    selectOtherMedia: { media in
                        let item: ChekinanaGalleryItem = media.kind == .shame ? .shame(media) : .douga(media)
                        if item.hasMedia {
                            selected = item
                        } else {
                            selectedNoMediaRecord = noMediaRecord(for: item)
                        }
                    },
                    separatesMediaTypes: true,
                    onBack: nil
                )
            }
        }
        .fullScreenCover(item: $selected) { item in
            switch item {
            case .cheki(let value):
                ChekinanaGalleryDetailView(
                    chekis: ChekinanaIdolChekiPagerScope.items(
                        from: dateGroupMediaChekis,
                        matching: value
                    ),
                    initialID: value.id
                )
            case .shame(let value):
                ChekinanaGalleryMediaPagerView(
                    items: items.compactMap {
                        guard case .shame(let media) = $0 else { return nil }
                        return media
                    },
                    kind: .shame,
                    initialID: value.id
                )
            case .douga(let value):
                ChekinanaGalleryMediaPagerView(
                    items: items.compactMap {
                        guard case .douga(let media) = $0 else { return nil }
                        return media
                    },
                    kind: .douga,
                    initialID: value.id
                )
            }
        }
        .sheet(item: $selectedNoMediaRecord) { record in
            ChekinanaCalendarNoMediaRecordEditor(record: record)
        }
        .sheet(item: $selectedChekiRecord) { selection in
            ChekinanaChekiRecordEditor(selection: selection)
        }
        .accessibilityIdentifier(
            "chekinana.idols.detail.date-group.\(kind.rawValue).\(groupKey.stableID)"
        )
    }

    private func compactNoMediaRow(
        title: String,
        note: String,
        count: Int,
        kind: ChekinanaRecordKind
    ) -> some View {
        HStack(spacing: 10) {
            ChekinanaRecordCategoryIcon(kind: kind)
                .foregroundStyle(ChekinanaProductTheme.accent)
                .frame(width: 28)
            VStack(alignment: .leading, spacing: 1) {
                Text(title)
                    .font(.subheadline.weight(.semibold))
                Text(
                    note.nonEmpty
                        ?? ChekinanaProductCopy.text(
                            "common.no_media",
                            "No media"
                        )
                )
                .font(.caption)
                .foregroundStyle(.secondary)
                .lineLimit(1)
            }
            Spacer(minLength: 8)
            Text(ChekinanaRecordKind.cheki.countLabel(count))
                .font(.caption.monospacedDigit())
                .foregroundStyle(.secondary)
        }
        .frame(minHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget)
        .contentShape(Rectangle())
    }

    private func key(for date: Date?) -> ChekinanaIdolMediaDateGroupKey {
        date.flatMap(ChekinanaDateOnly.canonicalized)
            .map(ChekinanaIdolMediaDateGroupKey.dated)
            ?? .undated
    }

    private func noMediaRecord(
        for item: ChekinanaGalleryItem
    ) -> ChekinanaCalendarNoMediaRecord {
        switch item {
        case .cheki:
            preconditionFailure("Media Cheki cannot be opened in the no-media editor")
        case .shame(let value): .shame(value)
        case .douga(let value): .douga(value)
        }
    }
}

