        .accessibilityIdentifier("chekinana.idols.editor")
        .chekinanaSheetDraftDismiss(
            isBusy: { isSaving || isMerging || isDeleting || isPreparingCatalogueAvatar || isPreparingAvatarPreview || pendingAvatarCleanup != nil },
            snapshot: { [AnyHashable(sourceId), AnyHashable(name), AnyHashable(group), AnyHashable(color), AnyHashable(hasBirthday), AnyHashable(birthdayMode.rawValue), AnyHashable(hasBirthday ? birthdayDate : nil), AnyHashable(unknownBirthdayMonth), AnyHashable(unknownBirthdayDay), AnyHashable(fullBirthdayYearConfirmed), AnyHashable(birthdaySourceValue), AnyHashable(remoteAvatarRef), AnyHashable(isFavorite), AnyHashable(verification), AnyHashable(bio), AnyHashable(note), AnyHashable(patterns), AnyHashable(preparedLocalAvatar?.owner.selectionID), AnyHashable(removesAvatar)] },
            onDiscard: { initial in requestCancel() }
        )
    }

    private func refreshDuplicateIdentity() {
        guard idol == nil, focusedIdentityField == nil else { return }
        guard !ChekinanaNewIdolDuplicatePolicy.key(name).isEmpty,
              !ChekinanaNewIdolDuplicatePolicy.key(group).isEmpty else {
            hasDuplicateIdentity = false
            return
        }
        hasDuplicateIdentity = storedIdols.contains {
            ChekinanaNewIdolDuplicatePolicy.matches(
                name: name, group: group, existingName: $0.name, existingGroup: $0.group
            )
        }
    }

    private var indexedCandidates: [ChekinanaIndexedCatalogueIdolCandidate] {
        candidates.enumerated().map {
            ChekinanaIndexedCatalogueIdolCandidate(
                index: $0.offset,
                candidate: $0.element
            )
        }
    }

    private var isPreparingCatalogueAvatar: Bool {
        cataloguePreparation.isPreparing
    }

    private var isPreparingAvatarPreview: Bool {
        localAvatarPreparation.isPreparing
    }

    @MainActor
    private func updateAvatarPickerSelection(_ item: PhotosPickerItem?) {
        avatarPickerItem = item
        guard let item else {
            cancelLocalAvatarSelection(reason: .pickerBecameNil)
            return
        }
        beginLocalAvatarPreparation(item)
    }

    @MainActor
    private func beginLocalAvatarPreparation(_ item: PhotosPickerItem) {
        invalidateCataloguePreparation()
        invalidateLocalAvatarPreparation(reason: .selectionReplaced)
        avatarPickerItem = item
        avatarItem = item
        avatarPreview = nil
        let owner = localAvatarPreparation.begin(selectionID: UUID())
        avatarPreviewTask = Task { @MainActor in
            await prepareLocalAvatar(item, owner: owner)
        }
    }

    @MainActor
    private func prepareLocalAvatar(
        _ item: PhotosPickerItem,
        owner: ChekinanaLocalAvatarPreparationOwner
    ) async {
        defer { releaseLocalAvatarTask(ifOwnedBy: owner) }
        do {
            let image = try await ChekinanaProductMediaLoader.load(item)
            guard localAvatarPreparation.owns(owner), !Task.isCancelled else { return }
            guard let preview = await ChekinanaImageWorker.thumbnailImage(
                from: image.data,
                maxDimension: 256
            ) else {
                throw ChekinanaLocalAvatarPreparationError.previewUnavailable
            }
            guard !Task.isCancelled,
                  localAvatarPreparation.completeSuccess(ifOwnedBy: owner) else { return }
            preparedLocalAvatar = ChekinanaPreparedLocalAvatar(
                owner: owner,
                data: image.data,
                preview: preview
            )
            avatarPreview = preview
            removesAvatar = false
        } catch is CancellationError {
            return
        } catch {
            guard !Task.isCancelled else { return }
            let message = ChekinanaProductCopy.format(
                "idols.avatar.preparation_failed",
                "Avatar could not be prepared. Retry or cancel this selection: %@",
                error.localizedDescription
            )
            guard localAvatarPreparation.completeFailure(
                ifOwnedBy: owner,
                message: message
            ) else { return }
            preparedLocalAvatar = nil
            avatarPreview = nil
        }
    }

    @MainActor
    @discardableResult
    private func releaseLocalAvatarTask(
        ifOwnedBy owner: ChekinanaLocalAvatarPreparationOwner
    ) -> Bool {
        guard localAvatarPreparation.owns(owner) else { return false }
        avatarPreviewTask = nil
        return true
    }

    @MainActor
    private func invalidateLocalAvatarPreparation(
        reason: ChekinanaLocalAvatarInvalidationReason
    ) {
        let owner = localAvatarPreparation.owner
        let task = avatarPreviewTask
        guard localAvatarPreparation.invalidate(
            ifOwnedBy: owner,
            reason: reason
        ) else { return }
        avatarPreviewTask = nil
        preparedLocalAvatar = nil
        task?.cancel()
    }

    @MainActor
    private func retryLocalAvatarPreparation() {
        guard localAvatarPreparation.failureMessage != nil,
              let avatarItem else { return }
        beginLocalAvatarPreparation(avatarItem)
    }

    @MainActor
    private func cancelLocalAvatarSelection() {
        cancelLocalAvatarSelection(reason: .userCancelledSelection)
    }

    @MainActor
    private func cancelLocalAvatarSelection(
        reason: ChekinanaLocalAvatarInvalidationReason
    ) {
        invalidateLocalAvatarPreparation(reason: reason)
        avatarPickerItem = nil
        avatarItem = nil
        avatarPreview = removesAvatar
            ? nil
            : selectedCatalogueCandidate?.avatarThumbnailImage
    }

    private func validatedLocalAvatarForSave() throws -> ChekinanaPreparedLocalAvatar? {
        if avatarItem == nil {
            guard localAvatarPreparation.allowsSave(preparedOwner: nil),
                  preparedLocalAvatar == nil else {
                throw ChekinanaLocalAvatarPreparationError.selectionNotPrepared
            }
            return nil
        }
        guard let preparedLocalAvatar,
              localAvatarPreparation.allowsSave(
                preparedOwner: preparedLocalAvatar.owner
              ) else {
            throw ChekinanaLocalAvatarPreparationError.selectionNotPrepared
        }
        return preparedLocalAvatar
    }

    private var currentCatalogueCandidateIdentity: String? {
        selectedCatalogueCandidate.map {
            ChekinanaCatalogueIdolCardAvatarPresentation.identity(for: $0.candidate)
        }
    }

    private var colorValidationMessage: String? {
        ChekinanaIdolColorInputPolicy.validationMessage(color)
    }

    private var mergeTargets: [Idol] {
        guard let idol else { return [] }
        return ChekinanaIdolMergePolicy.targets(
            from: storedIdols,
            sourceID: idol.id,
            hiddenIDs: hiddenIdols.hiddenIDs,
            chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
        )
    }

    private var selectedMergeTarget: Idol? {
        guard let mergeTargetID else { return nil }
        return mergeTargets.first { $0.id == mergeTargetID }
    }

    private var mergeConfirmationMessage: String {
        guard let source = idol, let target = selectedMergeTarget else { return "" }
        return ChekinanaProductCopy.format(
            "idols.merge.confirm.message",
            "The target Idol “%1$@” keeps all of its profile and settings. The current Idol “%2$@” will be deleted after its records are moved.",
            target.name,
            source.name
        )
    }

    private func confirmPatternRemoval() {
        guard let index = pendingPatternRemovalIndex,
              patterns.indices.contains(index) else {
            pendingPatternRemovalIndex = nil
            return
        }
        patterns.remove(at: index)
        pendingPatternRemovalIndex = nil
    }

    private func hideIdol() {
        guard let idol, !isSaving, !isMerging, !isDeleting else { return }
        hiddenIdols.hide(idol.id)
        dismiss()
        onHidden()
    }

    @MainActor
    private func deleteIdol() {
        guard let idol,
              !isSaving,
              !isMerging,
              !isDeleting,
              pendingAvatarCleanup == nil else { return }
        isDeleting = true
        errorMessage = nil
        do {
            let result = try ChekinanaIdolPersistence.delete(
                idol,
                from: modelContext
            )
            hiddenIdols.removeDeleted(idol.id)
            dismiss()
            onDeleted(result.pendingAvatarCleanup)
        } catch {
            isDeleting = false
            errorMessage = error.localizedDescription
        }
    }

    @MainActor
    private func mergeIntoSelectedTarget() {
        guard !isSaving,
              !isMerging,
              !isPreparingCatalogueAvatar,
              !isPreparingAvatarPreview,
              pendingAvatarCleanup == nil,
              let source = idol,
              let target = selectedMergeTarget else { return }
        isMerging = true
        errorMessage = nil
        do {
            let result = try ChekinanaIdolPersistence.merge(
                sourceID: source.id,
                into: target.id,
                in: modelContext
            )
            hiddenIdols.removeDeleted(source.id)
            onMerged(result.pendingAvatarCleanup)
            dismiss()
        } catch {
            isMerging = false
            errorMessage = error.localizedDescription
        }
    }

    private func invalidateCatalogueSearch() {
        searchGeneration &+= 1
        searchTask?.cancel()
        searchTask = nil
        isSearching = false
        catalogueSearchWasEmpty = false
        candidates = []
        groupCandidateSourceIDs = []
    }

    @MainActor
    private func searchCatalogue() async {
        guard idol == nil else { return }
        let requestedQuery = query
        searchGeneration &+= 1
        let generation = searchGeneration
        isSearching = true
        catalogueSearchWasEmpty = false
        defer { if generation == searchGeneration { isSearching = false; searchTask = nil } }
        do {
            let result = try await ChekinanaIdolEnrichmentClient().searchForCreation(query: requestedQuery)
            guard !Task.isCancelled, generation == searchGeneration, query == requestedQuery else { return }
            var seenIdentities = Set<String>()
            candidates = result.items.filter {
                seenIdentities.insert(
                    ChekinanaCatalogueIdolCardAvatarPresentation.identity(for: $0)
                ).inserted
            }
            groupCandidateSourceIDs = result.usedGroupSearch ? Set(result.items.map(\.sourceId)) : []
            catalogueSearchWasEmpty = candidates.isEmpty
            errorMessage = nil
        } catch {
            guard !Task.isCancelled, generation == searchGeneration, query == requestedQuery else { return }
            candidates = []
            groupCandidateSourceIDs = []
            errorMessage = error.localizedDescription
        }
    }

    @MainActor
    private func select(_ rawCandidate: ChekinanaEnrichedIdol) {
        let candidate: ChekinanaEnrichedIdol
        do {
            candidate = try ChekinanaBirthdayValue.normalizedCatalogueCandidate(
                rawCandidate
            )
        } catch {
            errorMessage = error.localizedDescription
            return
        }
        invalidateCataloguePreparation()
        let generation = previewGeneration
        let candidateIdentity = ChekinanaCatalogueIdolCardAvatarPresentation
            .identity(for: candidate)
        let owner = ChekinanaCataloguePreparationOwner(
            generation: generation,
            candidateIdentity: candidateIdentity
        )
        sourceId = candidate.sourceId
        // Candidate metadata is already authoritative. Avatar bytes are
        // published later only if this generation remains current.
        selectedCatalogueCandidate = ChekinanaPreparedIdolCandidate(
            candidate: candidate,
            avatarThumbnailData: nil,
            avatarIdentity: nil
        )
        cataloguePreparation.begin(owner)
        remoteAvatarRef = nil
        if avatarItem == nil { avatarPreview = nil }
        cataloguePatternSelection.clear()
        patterns = []
        name = candidate.idolName
        group = candidate.groupName ?? ""
        color = candidate.color ?? ""
        birthdaySourceValue = candidate.birthday
        let birthdaySemantic = ChekinanaBirthdayValue.semantic(candidate.birthday)
        birthdaySession = ChekinanaBirthdayValue.editorSession(
            for: birthdaySemantic,
            systemCalendar: birthdaySession.userCalendar
        )
        if let semantic = birthdaySemantic,
           let parsedBirthday = ChekinanaBirthdayValue.draftDisplayDate(
               for: semantic,
               defaultYear: ChekinanaBirthdayEditorPolicy.unknownYearCarrier,
               timeZone: birthdayCalendar.timeZone
           ) {
            birthdayDate = parsedBirthday
            hasBirthday = true
            birthdayMode = ChekinanaBirthdayEditorPolicy.initialMode(for: semantic)
            let monthAndDay = semantic.monthAndDay
            unknownBirthdayMonth = monthAndDay.month
            unknownBirthdayDay = monthAndDay.day
            fullBirthdayYearConfirmed = semantic.hasKnownYear
        } else {
            hasBirthday = false
            birthdayMode = .fullDate
            fullBirthdayYearConfirmed = false
        }
        birthdayWasEdited = false
        verification = candidate.verification ?? ""
        bio = candidate.bio ?? ""
        isFavorite = false
        note = ""
        focusedIdentityField = nil
        refreshDuplicateIdentity()
        errorMessage = nil
        let needsPatternLookup = groupCandidateSourceIDs.contains(candidate.sourceId)
        cataloguePreparationTask = Task { @MainActor in
            await prepareCatalogueSelection(candidate, owner: owner, needsPatternLookup: needsPatternLookup)
        }
    }

    @MainActor
    private func prepareCatalogueSelection(
        _ candidate: ChekinanaEnrichedIdol,
        owner: ChekinanaCataloguePreparationOwner,
        needsPatternLookup: Bool
    ) async {
        defer { releaseCataloguePreparation(ifOwnedBy: owner) }
        var candidate = candidate
        do {
            if needsPatternLookup {
                let snapshot = try await ChekinanaRemotePatternResources.shared.snapshot()
                guard ownsCataloguePreparation(owner), !Task.isCancelled else { return }
                candidate = ChekinanaEnrichedIdol(
                    sourceId: candidate.sourceId, idolName: candidate.idolName,
                    groupName: candidate.groupName, color: candidate.color,
                    birthday: candidate.birthday, verification: candidate.verification,
                    bio: candidate.bio, avatarUrl: candidate.avatarUrl,
                    patternIds: snapshot.idolPatternIDs[candidate.sourceId] ?? []
                )
                selectedCatalogueCandidate = ChekinanaPreparedIdolCandidate(
                    candidate: candidate, avatarThumbnailData: nil, avatarIdentity: nil
                )
            }
            let resolvedPatterns = try await ChekinanaRemotePatternResources.shared
                .patterns(for: candidate.patternIds)
            guard ownsCataloguePreparation(owner), !Task.isCancelled else { return }
            cataloguePatternSelection.select(
                sourceId: candidate.sourceId,
                patternIds: candidate.patternIds,
                patterns: resolvedPatterns
            )
            patterns = resolvedPatterns
        } catch {
            guard ownsCataloguePreparation(owner), !Task.isCancelled else { return }
            errorMessage = error.localizedDescription
            return
        }
        do {
            let prepared = try await ChekinanaCatalogueIdolAvatarResolver.prepare(candidate)
            guard ownsCataloguePreparation(owner), !Task.isCancelled else { return }
            guard ChekinanaIdolAvatarSelectionPolicy.acceptsCataloguePreview(
                generation: owner.generation,
                currentGeneration: previewGeneration,
                candidateMatches: currentCatalogueCandidateIdentity == owner.candidateIdentity,
                removesAvatar: removesAvatar,
                hasLocalItem: avatarItem != nil
            ) else { return }
            selectedCatalogueCandidate = prepared
            avatarPreview = prepared.avatarThumbnailImage
        } catch {
            guard ownsCataloguePreparation(owner), !Task.isCancelled else { return }
            errorMessage = ChekinanaL10n.message("Catalogue avatar could not be prepared. Tap this result to retry: \(error.localizedDescription)")
        }
    }

    private func ownsCataloguePreparation(
        _ owner: ChekinanaCataloguePreparationOwner
    ) -> Bool {
        cataloguePreparation.owns(
            owner,
            currentGeneration: previewGeneration,
            currentCandidateIdentity: currentCatalogueCandidateIdentity
        )
    }

    @MainActor
    @discardableResult
    private func releaseCataloguePreparation(
        ifOwnedBy owner: ChekinanaCataloguePreparationOwner
    ) -> Bool {
        guard cataloguePreparation.release(
            ifOwnedBy: owner,
            currentGeneration: previewGeneration,
            currentCandidateIdentity: currentCatalogueCandidateIdentity
        ) else { return false }
        cataloguePreparationTask = nil
        return true
    }

    @MainActor
    private func invalidateCataloguePreparation() {
        let next = ChekinanaIdolAvatarSelectionPolicy
            .invalidatingCataloguePreparation(generation: previewGeneration)
        if let owner = cataloguePreparation.owner {
            let task = cataloguePreparationTask
            if releaseCataloguePreparation(ifOwnedBy: owner) {
                task?.cancel()
            }
        }
        previewGeneration = next.generation
    }

    @MainActor
    private func save(generation: Int) async {
        guard generation == saveGeneration, !Task.isCancelled else { return }
        var stagingTransaction: ChekinanaIdolAvatarStagingTransaction?
        defer {
            if let cleanup = stagingTransaction?.rollback() {
                pendingAvatarCleanup = cleanup
                pendingAvatarCleanupPurpose = .rollbackAfterFailedSave
                errorMessage = ChekinanaProductCopy.text(
                    "idols.avatar_cleanup_without_save",
                    "The Idol was not saved, but its staged avatar still needs cleanup. Retry cleanup before closing."
                )
            }
        }
        let localAvatarSnapshot: ChekinanaPreparedLocalAvatar?
        do {
            localAvatarSnapshot = try validatedLocalAvatarForSave()
        } catch {
            errorMessage = error.localizedDescription
            return
        }
        isSaving = true
        defer { if generation == saveGeneration { isSaving = false; saveTask = nil } }
        do {
            try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(in: modelContext)
            let normalizedName = try ChekinanaManualIdolInput.normalizedName(name)
            let savedGroup = group.nonEmpty
            if idol == nil {
                try ChekinanaNewIdolDuplicatePolicy.validate(
                    name: normalizedName, group: savedGroup ?? "", in: modelContext
                )
            }
            let normalizedColor = ChekinanaIdolEditorColorPolicy.storageValue(color)
            let storedBirthday = try ChekinanaBirthdayEditorPolicy.storageValue(
                hasBirthday: hasBirthday,
                mode: birthdayMode,
                fullDate: birthdayDate,
                unknownMonth: unknownBirthdayMonth,
                unknownDay: unknownBirthdayDay,
                fullYearConfirmed: fullBirthdayYearConfirmed,
                timeZone: birthdayCalendar.timeZone,
                wasEdited: birthdayWasEdited,
                originalValue: birthdaySourceValue
            )
            let isNewCatalogueSelection = idol == nil
                && mode == .catalogue
                && sourceId?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            let resolution: ChekinanaCatalogueIdolTarget
            if let idol {
                resolution = ChekinanaCatalogueIdolTarget(idol: idol, shouldInsert: false)
            } else {
                resolution = ChekinanaCatalogueIdolTarget(
                    idol: try ChekinanaManualIdolInput.makeNameOnlyIdol(
                        name: normalizedName
                    ),
                    shouldInsert: true
                )
            }
            let target = resolution.idol
            let transaction = try ChekinanaIdolAvatarStagingTransaction(
                in: modelContext
            )
            stagingTransaction = transaction
            let avatarSnapshot = try ChekinanaIdolEditorAvatarMutation.capture(
                target,
                inserting: resolution.shouldInsert,
                libraryGeneration: transaction.libraryGeneration,
                in: modelContext
            )
            let previousAvatarRef = avatarSnapshot.reference
            let explicitlyRemovingAvatar = removesAvatar
            var avatarRef = explicitlyRemovingAvatar ? nil : previousAvatarRef
            let resolvedTargetKind = ChekinanaIdolReferenceAvatarPolicy.targetKind(
                for: resolution
            )
            let targetHasManagedAvatar = ChekinanaIdolReferenceStore.hasManagedAvatarFile(
                imageRef: previousAvatarRef,
                idolID: target.id
            )
            let catalogueAvatarAction = ChekinanaIdolEditorAvatarMutation.catalogueAction(
                for: avatarSnapshot,
                explicitlySelectingCatalogue: isNewCatalogueSelection,
                hasManagedAvatar: targetHasManagedAvatar,
                referenceIsManaged: (try? ChekinanaIdolReferenceStore.managedAvatarURL(
                    for: previousAvatarRef,
                    idolID: target.id
                )) != nil
            )
            let existingPatternState = try ChekinanaIdolPatternPersistence.state(
                for: target.id,
                in: modelContext
            )
            var cataloguePatternIDs: [String]
            var cataloguePatterns: [[Float]]
            var customPatterns: [[Float]]
            if isNewCatalogueSelection, resolution.shouldInsert {
                guard let selectedCatalogueCandidate,
                      selectedCatalogueCandidate.candidate.sourceId == sourceId else {
                    throw ChekinanaPatternResourceError.invalidResponse
                }
                let candidate = selectedCatalogueCandidate.candidate
                // Explicit catalogue selection prepares remote resources before
                // this save acquires the library gate. Saving never fetches them.
                guard cataloguePatternSelection.isResolved,
                      cataloguePatternSelection.sourceId == candidate.sourceId,
                      cataloguePatternSelection.patternIds == candidate.patternIds else {
                    throw ChekinanaPatternResourceError.invalidResponse
                }
                let resolvedPatterns = cataloguePatternSelection.patterns
                var remaining = patterns.filter(
                    ChekinanaPatternClassifier.isValidEmbedding
                )
                cataloguePatternIDs = []
                cataloguePatterns = []
                for (patternID, prototype) in zip(
                    candidate.patternIds,
                    resolvedPatterns
                ) {
                    guard let index = remaining.firstIndex(of: prototype) else {
                        continue
                    }
                    cataloguePatternIDs.append(patternID)
                    cataloguePatterns.append(prototype)
                    remaining.remove(at: index)
                }
                customPatterns = remaining
            } else {
                // Existing current-version state is authoritative. This also
                // prevents selecting an already-added catalogue Idol from
                // restoring a cloud prototype the user previously removed.
                let editedPatterns = isNewCatalogueSelection
                    ? target.recognitionPatterns
                    : patterns
                let split = ChekinanaIdolPatternPersistence.splitEditedPatterns(
                    editedPatterns,
                    for: target,
                    state: existingPatternState
                )
                cataloguePatternIDs = split.cataloguePatternIDs
                cataloguePatterns = split.cataloguePatterns
                customPatterns = split.customPatterns
            }
            let referenceData: Data?
            if !explicitlyRemovingAvatar, let referenceItem {
                let image = try await ChekinanaProductMediaLoader.load(referenceItem)
                guard generation == saveGeneration, !Task.isCancelled else { return }
                referenceData = image.data
            } else {
                referenceData = nil
            }
            let avatarPreparation = try await ChekinanaIdolReferenceAvatarPreparation.prepare(
                referenceData: referenceData,
                explicitAvatarData: localAvatarSnapshot?.data,
                targetKind: resolvedTargetKind,
                targetHasManagedAvatar: targetHasManagedAvatar,
                explicitlyRemovingAvatar: explicitlyRemovingAvatar,
                encodeReference: { data in
                    try await ChekinanaPatternEncoder.shared.encode(data)
                },
                stageAvatar: { data in
                    try await transaction.stage(
                        data,
                        idolID: target.id
                    )
                }
            )
            if let encoded = avatarPreparation.encodedReferencePattern {
                customPatterns = ChekinanaPatternVectors.mergedPatterns([
                    customPatterns,
                    [encoded],
                ])
            }
            var stagedAvatar = avatarPreparation.stagedAvatar
            if let stagedAvatar {
                avatarRef = stagedAvatar.ref
            }
            guard generation == saveGeneration, !Task.isCancelled else {
                throw CancellationError()
            }
            var stagedCatalogueAvatar = false
            if let sourceId, stagedAvatar == nil, !explicitlyRemovingAvatar,
               catalogueAvatarAction != .none {
                guard catalogueAvatarAction == .selection,
                      let prepared = selectedCatalogueCandidate,
                      prepared.candidate.sourceId == sourceId else {
                    throw ChekinanaPatternResourceError.invalidResponse
                }
                guard generation == saveGeneration, !Task.isCancelled else { return }
                stagedAvatar = try await transaction.stage(
                    prepared,
                    idolID: target.id
                )
                avatarRef = stagedAvatar?.ref
                stagedCatalogueAvatar = true
            }
            guard generation == saveGeneration, !Task.isCancelled else {
                throw CancellationError()
            }
            let result = try ChekinanaPersistenceMutationCoordinator.withLock {
                var didSaveAvatarMutation = false
                defer {
                    if !didSaveAvatarMutation { modelContext.rollback() }
                }
                if idol == nil {
                    try ChekinanaNewIdolDuplicatePolicy.validate(
                        name: normalizedName, group: savedGroup ?? "", in: modelContext
                    )
                }
                try ChekinanaIdolEditorAvatarMutation.validate(
                    avatarSnapshot, target: target, in: modelContext
                )
                _ = try ChekinanaIdolPatternPersistence.replaceCataloguePatterns(
                    for: target,
                    patternIDs: cataloguePatternIDs,
                    prototypes: cataloguePatterns,
                    customPatterns: customPatterns,
                    in: modelContext
                )
                let avatarOperation: ChekinanaIdolEditorAvatarMutation.Operation
                if explicitlyRemovingAvatar {
                    avatarOperation = .remove
                } else if localAvatarSnapshot != nil
                            || avatarPreparation.initializedAvatarFromReference {
                    avatarOperation = .custom
                } else if stagedCatalogueAvatar {
                    avatarOperation = catalogueAvatarAction == .repair
                        ? .catalogueRepair : .catalogueSelection
                } else {
                    avatarOperation = .keep
                }
                try ChekinanaIdolEditorAvatarMutation.record(
                    avatarOperation,
                    snapshot: avatarSnapshot,
                    finalReference: avatarRef,
                    in: modelContext
                )
                let persistedResult = try ChekinanaIdolPersistence.save(
                    target,
                    inserting: resolution.shouldInsert,
                    previousAvatarRef: previousAvatarRef,
                    stagedAvatar: stagedAvatar,
                    in: modelContext,
                    libraryGeneration: transaction.libraryGeneration
                ) { target in
                    target.sourceId = isNewCatalogueSelection ? sourceId : idol?.sourceId
                    target.name = normalizedName
                    target.group = savedGroup
                    target.color = normalizedColor
                    // A catalogue response with no birthday is absence of new
                    // information, not an instruction to erase an existing value.
                    if resolution.shouldInsert || birthdayWasEdited || storedBirthday != nil {
                        target.birthday = storedBirthday
                    }
                    target.avatarImageRef = avatarRef
                    target.isFavorite = isFavorite
                    target.verification = verification.nonEmpty
                    target.bio = bio.nonEmpty
                    target.note = note
                    target.updatedAt = Date()
                }
                didSaveAvatarMutation = true
                return persistedResult
            }
            if let cleanup = transaction.commit(
                referencedImageRef: target.avatarImageRef
            ) {
                pendingAvatarCleanup = cleanup
                pendingAvatarCleanupPurpose = .afterSuccessfulSave
                errorMessage = ChekinanaProductCopy.text(
                    "idols.avatar_cleanup_without_save",
                    "The Idol was saved, but an unused staged avatar still needs cleanup. Retry cleanup before closing."
                )
                return
            }
            guard generation == saveGeneration, !Task.isCancelled else { return }
            referenceItem = nil
            invalidateLocalAvatarPreparation(reason: .saveCompleted)
            avatarPickerItem = nil
            avatarItem = nil
            remoteAvatarRef = target.avatarImageRef
            patterns = target.patterns
            if let cleanup = result.pendingAvatarCleanup {
                let stillPending = cleanup.operationID.map {
                    ChekinanaIdolAvatarCleanupQueue.contains(operationID: $0)
                } ?? true
                guard stillPending else {
                    dismiss()
                    return
                }
                pendingAvatarCleanup = cleanup
                pendingAvatarCleanupPurpose = .afterSuccessfulSave
                errorMessage = ChekinanaProductCopy.text(
                    "idols.avatar_cleanup_after_save",
                    "Idol was saved, but the previous managed avatar could not be removed. Retry cleanup before closing."
                )
                return
            }
            dismiss()
            }
        } catch {
            if error is CancellationError { return }
            if error is ChekinanaNewIdolDuplicatePolicy.DuplicateError {
                focusedIdentityField = nil
                hasDuplicateIdentity = true
                errorMessage = nil
                return
            }
            if let persistenceError = error as? ChekinanaIdolPersistenceError,
               let cleanup = persistenceError.pendingCleanupTarget {
                if stagingTransaction == nil {
                    pendingAvatarCleanup = cleanup
                    pendingAvatarCleanupPurpose = .rollbackAfterFailedSave
                    errorMessage = persistenceError.localizedDescription
                } else {
                    // The request transaction owns the same staged file and
                    // its defer decides whether cleanup is still pending.
                    errorMessage = ChekinanaProductCopy.text(
                        "idols.avatar_database_save_failed",
                        "The Idol was not saved. Review the form and try again."
                    )
                }
            } else if error is ChekinanaProductDateSelectionError
                        || error is ChekinanaManualIdolInputError
                        || error is ChekinanaIdolColorInputError
                        || error is ChekinanaLocalAvatarPreparationError {
                errorMessage = error.localizedDescription
            } else {
                errorMessage = ChekinanaL10n.message("Reference photo could not be encoded or saved: \(error.localizedDescription)")
            }
        }
    }

    private func retryAvatarCleanup() {
        guard let pendingAvatarCleanup else { return }
        if ChekinanaIdolAvatarCleanupQueue.retry(
            pendingAvatarCleanup,
            in: modelContext
        ) {
            self.pendingAvatarCleanup = nil
            let purpose = pendingAvatarCleanupPurpose
            pendingAvatarCleanupPurpose = nil
            if purpose == .afterSuccessfulSave {
                errorMessage = nil
                dismiss()
            } else {
                errorMessage = ChekinanaL10n.message("The staged avatar was cleaned up. The database changes were not saved; review the form and tap Save again, or Cancel.")
            }
        } else {
            if pendingAvatarCleanupPurpose == .rollbackAfterFailedSave {
                errorMessage = ChekinanaL10n.message("Database changes remain unsaved and the staged avatar still needs cleanup. Retry after the current file operation finishes.")
            } else {
                errorMessage = ChekinanaProductCopy.text(
                    "idols.avatar_cleanup_after_save",
                    "The Idol is saved, but old avatar cleanup is still pending. Retry after the current file operation finishes."
                )
            }
        }
    }

    private func requestCancel() {
        guard pendingAvatarCleanup == nil else {
            errorMessage = pendingAvatarCleanupPurpose == .rollbackAfterFailedSave
                ? ChekinanaProductCopy.text(
                    "idols.avatar_cleanup_without_save",
                    "The Idol was not saved, but its staged avatar still needs cleanup. Retry cleanup before closing."
                )
                : ChekinanaProductCopy.text(
                    "idols.avatar_cleanup_after_save",
                    "The Idol was saved, but its previous avatar still needs cleanup. Retry cleanup before closing."
                )
            return
        }
        dismiss()
    }
}

struct ChekinanaIdolAvatarCleanupTarget: Equatable {
    let imageRef: String
    let idolID: UUID
    let directory: URL?
    let operationID: UUID?

    init(
        imageRef: String,
        idolID: UUID,
        directory: URL?,
        operationID: UUID? = nil
    ) {
        self.imageRef = imageRef
        self.idolID = idolID
        self.directory = directory
        self.operationID = operationID
    }
}

enum ChekinanaIdolAvatarCleanupPurpose: String, Codable, Sendable {
    case uncommittedStagedAvatar
    case replacedCommittedAvatar
}

struct ChekinanaIdolAvatarCleanupEntry: Codable, Equatable, Sendable {
    let operationID: UUID
    let imageRef: String
    let idolID: UUID
    let libraryGeneration: UUID
    let identity: ChekinanaImportFileIdentity
    let purpose: ChekinanaIdolAvatarCleanupPurpose

    var isValid: Bool {
        identity.isValid
            && (try? ChekinanaIdolReferenceStore.managedAvatarURL(
                for: imageRef,
                idolID: idolID,
                directory: FileManager.default.temporaryDirectory
            )) != nil
    }
}

/// Durable cleanup intent for managed Idol avatars. The entry is installed
/// before a newly staged file is written and remains authoritative until the
/// database either references that exact filename or the exact bytes are
/// removed. UserDefaults keeps this journal outside the managed media
/// directory so backup replacement cannot mistake it for an application file.
@MainActor
enum ChekinanaIdolAvatarCleanupQueue {
    private static let queueKey = "ChekinanaIdolAvatarCleanupQueueV1"

    static func validate(defaults: UserDefaults = .standard) throws {
        _ = try entries(defaults: defaults)
    }

    @discardableResult
    static func register(
        _ avatar: ChekinanaIdolReferenceStore.StoredAvatar,
        idolID: UUID,
        libraryGeneration: UUID,
        purpose: ChekinanaIdolAvatarCleanupPurpose,
        defaults: UserDefaults = .standard
    ) throws -> ChekinanaIdolAvatarCleanupEntry {
        guard try ChekinanaIdolReferenceStore.managedAvatarURL(
            for: avatar.ref,
            idolID: idolID,
            directory: avatar.url.deletingLastPathComponent()
        )?.standardizedFileURL == avatar.url.standardizedFileURL else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        var values = try entries(defaults: defaults)
        let entry = ChekinanaIdolAvatarCleanupEntry(
            operationID: UUID(),
            imageRef: avatar.ref,
            idolID: idolID,
            libraryGeneration: libraryGeneration,
            identity: try avatar.identity
                ?? ChekinanaImportFileIdentity.inspect(avatar.url),
            purpose: purpose
        )
        guard entry.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        values.append(entry)
        try persist(values, defaults: defaults)
        return entry
    }

    @discardableResult
    static func registerExisting(
        imageRef: String,
        idolID: UUID,
        directory: URL,
        libraryGeneration: UUID,
        purpose: ChekinanaIdolAvatarCleanupPurpose,
        defaults: UserDefaults = .standard
    ) throws -> ChekinanaIdolAvatarCleanupEntry? {
        guard let url = try ChekinanaIdolReferenceStore.managedAvatarURL(
            for: imageRef,
            idolID: idolID,
            directory: directory
        ), FileManager.default.fileExists(atPath: url.path) else {
            return nil
        }
        return try register(
            .init(
                ref: imageRef,
                url: url,
                identity: try ChekinanaImportFileIdentity.inspect(url)
            ),
            idolID: idolID,
            libraryGeneration: libraryGeneration,
            purpose: purpose,
            defaults: defaults
        )
    }

    static func discard(
        operationID: UUID,
        defaults: UserDefaults = .standard
    ) throws {
        let remaining = try entries(defaults: defaults).filter {
            $0.operationID != operationID
        }
        try persist(remaining, defaults: defaults)
    }

    static func contains(
        operationID: UUID,
        defaults: UserDefaults = .standard
    ) -> Bool {
        (try? entries(defaults: defaults).contains {
            $0.operationID == operationID
        }) == true
    }

    static func pendingCount(defaults: UserDefaults = .standard) -> Int {
        (try? entries(defaults: defaults).count) ?? 0
    }

    static func retry(
        _ target: ChekinanaIdolAvatarCleanupTarget,
        in modelContext: ModelContext,
        defaults: UserDefaults = .standard
    ) -> Bool {
        do {
            return try ChekinanaLibraryMutationProtocol.withExclusiveOperationSync {
                try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                    in: modelContext, directory: target.directory
                )
                return retryExclusively(
                    target,
                    in: modelContext,
                    defaults: defaults
                )
            }
        } catch {
            return false
        }
    }

    private static func retryExclusively(
        _ target: ChekinanaIdolAvatarCleanupTarget,
        in modelContext: ModelContext,
        defaults: UserDefaults
    ) -> Bool {
        let directory: URL
        do {
            directory = try target.directory
                ?? ChekiImageRefResolver.chekiImagesDirectory()
        } catch {
            return false
        }
        let operationID: UUID?
        if let existing = target.operationID {
            operationID = existing
        } else {
            do {
                let generation = try ChekinanaPersistenceMutationCoordinator.withLock {
                    try ChekinanaLibraryGenerationStore.ensureCurrent(in: modelContext)
                }
                operationID = try registerExisting(
                    imageRef: target.imageRef,
                    idolID: target.idolID,
                    directory: directory,
                    libraryGeneration: generation,
                    purpose: .replacedCommittedAvatar,
                    defaults: defaults
                )?.operationID
            } catch {
                return false
            }
        }
        _ = cleanupNow(
            in: modelContext,
            directory: directory,
            defaults: defaults
        )
        guard let operationID else {
            return !FileManager.default.fileExists(
                atPath: directory.appendingPathComponent(target.imageRef).path
            )
        }
        return !contains(operationID: operationID, defaults: defaults)
    }

    /// The caller supplies deletion authorization that rechecks the current
    /// generation, DB references, path, file kind, and byte identity directly
    /// before unlink. A currently referenced file transfers ownership to that
    /// DB row and retires the stale cleanup intent without deletion.
    @discardableResult
    static func cleanupSafely(
        referencedFilenames: Set<String>,
        currentGeneration: UUID,
        directory: URL,
        defaults: UserDefaults = .standard,
        removeCandidate: (
            URL,
            ChekinanaIdolAvatarCleanupEntry
        ) -> Bool
    ) -> Int {
        let values: [ChekinanaIdolAvatarCleanupEntry]
        do {
            values = try entries(defaults: defaults)
        } catch {
            return 1
        }
        let canonicalDirectory = directory.standardizedFileURL
        var remaining: [ChekinanaIdolAvatarCleanupEntry] = []
        var deferred = 0
        for entry in values {
            if referencedFilenames.contains(entry.imageRef) {
                continue
            }
            guard !ChekinanaIdolAvatarFileLeaseRegistry.isLeased(
                imageRef: entry.imageRef,
                directory: canonicalDirectory
            ) else {
                remaining.append(entry)
                deferred += 1
                continue
            }
            let url = canonicalDirectory.appendingPathComponent(entry.imageRef)
            guard FileManager.default.fileExists(atPath: url.path) else {
                continue
            }
            // A library replacement may reuse a filename. Historical entries
            // therefore require an extra byte-identity check against the new
            // generation before they may even reach the final unlink guard.
            if entry.libraryGeneration != currentGeneration,
               (try? ChekinanaImportFileIdentity.inspect(url)) != entry.identity {
                remaining.append(entry)
                deferred += 1
                continue
            }
            guard removeCandidate(url, entry) else {
                remaining.append(entry)
                deferred += 1
                continue
            }
        }
        do {
            try persist(remaining, defaults: defaults)
        } catch {
            return max(1, deferred)
        }
        return deferred
    }

    @discardableResult
    static func cleanupNow(
        in modelContext: ModelContext,
        directory: URL,
        defaults: UserDefaults = .standard,
        discoverImportTransactions: (URL) throws -> [ChekinanaImportTransactionHandle] = {
            try ChekinanaImportTransactionHandle.discover(in: $0)
        },
        beforeCandidateValidation: () -> Void = {},
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        }
    ) -> Int {
        let canonicalDirectory = directory.standardizedFileURL
        // This low-level cleanup can also run from a staging teardown without
        // library-gate ownership. It must defer rather than re-enter import
        // recovery or delete a file whose import ownership is still active.
        do {
            guard try discoverImportTransactions(canonicalDirectory).isEmpty else {
                return 1
            }
        } catch {
            return 1
        }
        let initial: ChekinanaLibraryFileReferenceSnapshot
        do {
            initial = try ChekinanaLibraryFileReferenceSnapshot.capture(
                in: ModelContext(modelContext.container),
                directory: canonicalDirectory
            )
        } catch {
            return 1
        }
        return cleanupSafely(
            referencedFilenames: initial.referencedFilenames,
            currentGeneration: initial.generation,
            directory: canonicalDirectory,
            defaults: defaults,
            removeCandidate: { url, entry in
                do {
                    return try ChekinanaPersistenceMutationCoordinator.withLock {
                        beforeCandidateValidation()
                        let latest = try ChekinanaLibraryFileReferenceSnapshot.capture(
                            in: ModelContext(modelContext.container),
                            directory: canonicalDirectory
                        )
                        let values = try url.resourceValues(
                            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                        )
                        guard latest.generation == initial.generation,
                              !latest.referencedFilenames.contains(entry.imageRef),
                              !ChekinanaIdolAvatarFileLeaseRegistry.isLeased(
                                imageRef: entry.imageRef,
                                directory: canonicalDirectory
                              ),
                              url.standardizedFileURL.deletingLastPathComponent()
                                == canonicalDirectory,
                              values.isRegularFile == true,
                              values.isSymbolicLink != true,
                              try ChekinanaImportFileIdentity.inspect(url)
                                == entry.identity else {
                            return false
                        }
                        try removeItem(url)
                        return !FileManager.default.fileExists(atPath: url.path)
                    }
                } catch {
                    return false
                }
            }
        )
    }

    private static func entries(
        defaults: UserDefaults
    ) throws -> [ChekinanaIdolAvatarCleanupEntry] {
        guard defaults.object(forKey: queueKey) != nil else { return [] }
        guard let data = defaults.data(forKey: queueKey),
              let values = try? JSONDecoder().decode(
                [ChekinanaIdolAvatarCleanupEntry].self,
                from: data
              ),
              values.allSatisfy(\.isValid),
              Set(values.map(\.operationID)).count == values.count else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        return values
    }

    private static func persist(
        _ entries: [ChekinanaIdolAvatarCleanupEntry],
        defaults: UserDefaults
    ) throws {
        if entries.isEmpty {
            defaults.removeObject(forKey: queueKey)
        } else {
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.sortedKeys]
            defaults.set(try encoder.encode(entries), forKey: queueKey)
        }
        guard defaults.synchronize() else {
            throw ChekinanaImportTransactionError.incomplete
        }
    }
}

/// Access is synchronous so a transaction can release its leases from deinit
/// on any executor. Every access to the mutable registry is protected by lock.
private final class ChekinanaIdolAvatarFileLeaseRegistry: @unchecked Sendable {
    private static let shared = ChekinanaIdolAvatarFileLeaseRegistry()
    private let lock = NSLock()
    private var leaseIDsByFile: [String: Set<UUID>] = [:]

    static func acquire(
        _ leaseID: UUID,
        imageRef: String,
        directory: URL
    ) {
        shared.lock.lock()
        defer { shared.lock.unlock() }
        shared.leaseIDsByFile[key(imageRef: imageRef, directory: directory), default: []]
            .insert(leaseID)
    }

    static func release(
        _ leaseID: UUID,
        imageRef: String,
        directory: URL
    ) {
        shared.lock.lock()
        defer { shared.lock.unlock() }
        let fileKey = key(imageRef: imageRef, directory: directory)
        shared.leaseIDsByFile[fileKey]?.remove(leaseID)
        if shared.leaseIDsByFile[fileKey]?.isEmpty == true {
            shared.leaseIDsByFile[fileKey] = nil
        }
    }

    static func isLeased(imageRef: String, directory: URL) -> Bool {
        shared.lock.lock()
        defer { shared.lock.unlock() }
        return shared.leaseIDsByFile[key(imageRef: imageRef, directory: directory)]?.isEmpty == false
    }

    private static func key(imageRef: String, directory: URL) -> String {
        directory.standardizedFileURL.path + "\u{0}" + imageRef
    }
}

/// Request-scoped ownership for newly created avatar files. The durable entry
/// is reserved before each write. `commit` is called only after SwiftData save
/// succeeds; every other exit releases its leases and runs the same guarded
/// retry path used after process restart.
@MainActor
final class ChekinanaIdolAvatarStagingTransaction {
    let libraryGeneration: UUID

    private let modelContext: ModelContext
    private let directory: URL
    private let defaults: UserDefaults
    private var entriesByReference: [String: ChekinanaIdolAvatarCleanupEntry] = [:]
    private var isFinished = false

    init(
        in modelContext: ModelContext,
        directory: URL? = nil,
        defaults: UserDefaults = .standard
    ) throws {
        self.modelContext = modelContext
        self.directory = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        self.defaults = defaults
        try ChekinanaIdolAvatarCleanupQueue.validate(defaults: defaults)
        libraryGeneration = try ChekinanaPersistenceMutationCoordinator.withLock {
            try ChekinanaLibraryGenerationStore.ensureCurrent(in: modelContext)
        }
    }

    func stage(
        _ data: Data,
        idolID: UUID
    ) async throws -> ChekinanaIdolReferenceStore.StoredAvatar {
        try await ChekinanaIdolReferenceStore.saveAvatar(
            data,
            idolID: idolID,
            directory: directory,
            reserveBeforeWrite: { [self] avatar in
                try reserve(avatar, idolID: idolID)
            }
        )
    }

    func stage(
        _ prepared: ChekinanaPreparedIdolCandidate,
        idolID: UUID
    ) async throws -> ChekinanaIdolReferenceStore.StoredAvatar {
        try await ChekinanaCatalogueIdolAvatarLocalizer.stage(
            prepared,
            idolID: idolID,
            directory: directory,
            reserveBeforeWrite: { [self] avatar in
                try reserve(avatar, idolID: idolID)
            }
        )
    }

    @discardableResult
    func commit(referencedImageRef: String?) -> ChekinanaIdolAvatarCleanupTarget? {
        guard !isFinished else { return nil }
        isFinished = true
        let committedReference = referencedImageRef?.trimmingCharacters(
            in: .whitespacesAndNewlines
        )
        var retainedOperationID: UUID?
        for entry in entriesByReference.values {
            releaseLease(for: entry)
            if entry.imageRef == committedReference {
                try? ChekinanaIdolAvatarCleanupQueue.discard(
                    operationID: entry.operationID,
                    defaults: defaults
                )
            } else {
                retainedOperationID = retainedOperationID ?? entry.operationID
            }
        }
        _ = cleanupPending()
        guard let retainedOperationID,
              ChekinanaIdolAvatarCleanupQueue.contains(
                operationID: retainedOperationID,
                defaults: defaults
              ),
              let entry = entriesByReference.values.first(where: {
                  $0.operationID == retainedOperationID
              }) else { return nil }
        return target(for: entry)
    }

    @discardableResult
    func rollback(
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        }
    ) -> ChekinanaIdolAvatarCleanupTarget? {
        guard !isFinished else { return nil }
        isFinished = true
        for entry in entriesByReference.values {
            releaseLease(for: entry)
        }
        _ = cleanupPending(removeItem: removeItem)
        guard let entry = entriesByReference.values.first(where: {
            ChekinanaIdolAvatarCleanupQueue.contains(
                operationID: $0.operationID,
                defaults: defaults
            )
        }) else { return nil }
        return target(for: entry)
    }

    deinit {
        // Queue entries remain durable if an unexpected owner path omits its
        // explicit finish. Leases are process-local and must not outlive the
        // request object.
        guard !isFinished else { return }
        for entry in entriesByReference.values {
            ChekinanaIdolAvatarFileLeaseRegistry.release(
                entry.operationID,
                imageRef: entry.imageRef,
                directory: directory
            )
        }
    }

    private func reserve(
        _ avatar: ChekinanaIdolReferenceStore.StoredAvatar,
        idolID: UUID
    ) throws {
        guard !isFinished, entriesByReference[avatar.ref] == nil else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let entry = try ChekinanaIdolAvatarCleanupQueue.register(
            avatar,
            idolID: idolID,
            libraryGeneration: libraryGeneration,
            purpose: .uncommittedStagedAvatar,
            defaults: defaults
        )
        entriesByReference[entry.imageRef] = entry
        ChekinanaIdolAvatarFileLeaseRegistry.acquire(
            entry.operationID,
            imageRef: entry.imageRef,
            directory: directory
        )
    }

    private func releaseLease(for entry: ChekinanaIdolAvatarCleanupEntry) {
        ChekinanaIdolAvatarFileLeaseRegistry.release(
            entry.operationID,
            imageRef: entry.imageRef,
            directory: directory
        )
    }

    private func target(
        for entry: ChekinanaIdolAvatarCleanupEntry
    ) -> ChekinanaIdolAvatarCleanupTarget {
        .init(
            imageRef: entry.imageRef,
            idolID: entry.idolID,
            directory: directory,
            operationID: entry.operationID
        )
    }

    private func cleanupPending(
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        }
    ) -> Int {
        ChekinanaIdolAvatarCleanupQueue.cleanupNow(
            in: modelContext,
            directory: directory,
            defaults: defaults,
            removeItem: removeItem
        )
    }
}

enum ChekinanaLocalAvatarInvalidationReason: Equatable, CaseIterable {
    case pickerBecameNil
    case avatarRemoved
    case selectionReplaced
    case userCancelledSelection
    case editorExited
    case saveCompleted
}

struct ChekinanaLocalAvatarPreparationOwner: Equatable {
    let selectionRevision: Int
    let selectionID: UUID
}

struct ChekinanaLocalAvatarPreparationState: Equatable {
    private enum Phase: Equatable {
        case idle
        case preparing
        case ready
        case failed(String)
    }

    private(set) var selectionRevision = 0
    private(set) var owner: ChekinanaLocalAvatarPreparationOwner?
    private(set) var lastInvalidationReason: ChekinanaLocalAvatarInvalidationReason?
    private var phase = Phase.idle

    var isPreparing: Bool { phase == .preparing }

    var failureMessage: String? {
        guard case .failed(let message) = phase else { return nil }
        return message
    }

    @discardableResult
    mutating func begin(selectionID: UUID) -> ChekinanaLocalAvatarPreparationOwner {
        selectionRevision &+= 1
        let owner = ChekinanaLocalAvatarPreparationOwner(
            selectionRevision: selectionRevision,
            selectionID: selectionID
        )
        self.owner = owner
        lastInvalidationReason = nil
        phase = .preparing
        return owner
    }

    func owns(_ owner: ChekinanaLocalAvatarPreparationOwner) -> Bool {
        self.owner == owner
            && owner.selectionRevision == selectionRevision
    }

    @discardableResult
    mutating func completeSuccess(
        ifOwnedBy owner: ChekinanaLocalAvatarPreparationOwner
    ) -> Bool {
        guard owns(owner), phase == .preparing else { return false }
        phase = .ready
        return true
    }

    @discardableResult
    mutating func completeFailure(
        ifOwnedBy owner: ChekinanaLocalAvatarPreparationOwner,
        message: String
    ) -> Bool {
        guard owns(owner), phase == .preparing else { return false }
        phase = .failed(message)
        return true
    }

    @discardableResult
    mutating func invalidate(
        ifOwnedBy owner: ChekinanaLocalAvatarPreparationOwner?,
        reason: ChekinanaLocalAvatarInvalidationReason
    ) -> Bool {
        guard self.owner == owner else { return false }
        selectionRevision &+= 1
        self.owner = nil
        lastInvalidationReason = reason
        phase = .idle
        return true
    }

    func allowsSave(
        preparedOwner: ChekinanaLocalAvatarPreparationOwner?
    ) -> Bool {
        switch phase {
        case .idle:
            return owner == nil && preparedOwner == nil
        case .ready:
            return owner != nil && preparedOwner == owner
        case .preparing, .failed:
            return false
        }
    }
}

struct ChekinanaPreparedLocalAvatar {
    let owner: ChekinanaLocalAvatarPreparationOwner
    let data: Data
    let preview: ChekinanaRenderedImage
}

enum ChekinanaLocalAvatarPreparationError: LocalizedError {
    case previewUnavailable
    case selectionNotPrepared

    var errorDescription: String? {
        switch self {
        case .previewUnavailable:
            return ChekinanaL10n.message("The selected photo could not be previewed.")
        case .selectionNotPrepared:
            return ChekinanaL10n.message("Wait for the selected avatar to finish loading, or retry or cancel the selection.")
        }
    }
}

struct ChekinanaCataloguePreparationOwner: Equatable {
    let generation: Int
    let candidateIdentity: String
}

struct ChekinanaCataloguePreparationState: Equatable {
    private(set) var owner: ChekinanaCataloguePreparationOwner?
    private(set) var isPreparing = false
    private(set) var hasTask = false

    mutating func begin(_ owner: ChekinanaCataloguePreparationOwner) {
        self.owner = owner
        isPreparing = true
        hasTask = true
    }

    func owns(
        _ owner: ChekinanaCataloguePreparationOwner,
        currentGeneration: Int,
        currentCandidateIdentity: String?
    ) -> Bool {
        self.owner == owner
            && owner.generation == currentGeneration
            && owner.candidateIdentity == currentCandidateIdentity
    }

    @discardableResult
    mutating func release(
        ifOwnedBy owner: ChekinanaCataloguePreparationOwner,
        currentGeneration: Int,
        currentCandidateIdentity: String?
    ) -> Bool {
        guard owns(
            owner,
            currentGeneration: currentGeneration,
            currentCandidateIdentity: currentCandidateIdentity
        ) else { return false }
        self.owner = nil
        isPreparing = false
        hasTask = false
        return true
    }
}

enum ChekinanaIdolReferenceAvatarTargetKind: Equatable {
    case newManual
    case existingManual
    case newCatalogue
    case reusedCatalogue

    var isManual: Bool {
        switch self {
        case .newManual, .existingManual:
            true
        case .newCatalogue, .reusedCatalogue:
            false
        }
    }
}

@MainActor
enum ChekinanaIdolEditorAvatarMutation {
    struct Snapshot {
        let idolID: UUID
        let modelID: PersistentIdentifier?
        let sourceID: String?
        let reference: String?
        let state: ChekinanaIdolAvatarStateSnapshot
        let libraryGeneration: UUID
    }

    enum CatalogueAction: Equatable {
        case none
        case selection
        case repair
    }

    enum Operation {
        case keep
        case remove
        case custom
        case catalogueSelection
        case catalogueRepair
    }

    static func capture(
        _ target: Idol,
        inserting: Bool,
        libraryGeneration: UUID,
        in context: ModelContext
    ) throws -> Snapshot {
        let fresh = ModelContext(context.container)
        let state = try ChekinanaIdolAvatarStatePersistence.snapshot(
            for: target.id, in: fresh
        )
        let snapshot = Snapshot(
            idolID: target.id,
            modelID: inserting ? nil : target.persistentModelID,
            sourceID: target.sourceId,
            reference: target.avatarImageRef,
            state: state,
            libraryGeneration: libraryGeneration
        )
        try validate(snapshot, target: target, in: context)
        return snapshot
    }

    static func validate(
        _ snapshot: Snapshot,
        target: Idol,
        in context: ModelContext
    ) throws {
        let fresh = ModelContext(context.container)
        let idolID = snapshot.idolID
        let matches = try fresh.fetch(FetchDescriptor<Idol>(
            predicate: #Predicate { $0.id == idolID }
        ))
        guard try ChekinanaLibraryGenerationStore.current(in: fresh)
                == snapshot.libraryGeneration,
              target.id == snapshot.idolID,
              target.sourceId == snapshot.sourceID,
              target.avatarImageRef == snapshot.reference,
              try ChekinanaIdolAvatarStatePersistence.snapshot(
                for: idolID, in: fresh
              ) == snapshot.state else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        if let modelID = snapshot.modelID {
            guard target.modelContext === context,
                  !context.deletedModelsArray.contains(where: {
                      $0.persistentModelID == modelID
                  }),
                  target.persistentModelID == modelID,
                  matches.count == 1,
                  let live = matches.first,
                  live.persistentModelID == modelID,
                  live.sourceId == snapshot.sourceID,
                  live.avatarImageRef == snapshot.reference else {
                throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
            }
        } else {
            guard matches.isEmpty else {
                throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
            }
        }
    }

    static func catalogueAction(
        for snapshot: Snapshot,
        explicitlySelectingCatalogue: Bool,
        hasManagedAvatar: Bool,
        referenceIsManaged: Bool
    ) -> CatalogueAction {
        // Ordinary local edits preserve the existing avatar reference/state,
        // including a missing local file. Only an explicit catalogue selection
        // may install a remotely prepared avatar.
        explicitlySelectingCatalogue ? .selection : .none
    }

    static func record(
        _ operation: Operation,
        snapshot: Snapshot,
        finalReference: String?,
        in context: ModelContext
    ) throws {
        let source: ChekinanaIdolAvatarSource
        let intent: ChekinanaIdolAvatarIntent
        switch operation {
        case .keep:
            guard finalReference == snapshot.reference,
                  snapshot.state.isValid(avatarImageRef: finalReference) else {
                throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
            }
            return
        case .remove:
            source = .none
            intent = .explicitlyRemoved
        case .custom:
            source = .custom
            intent = .userSelected
        case .catalogueSelection:
            source = .catalogue
            intent = .userSelected
        case .catalogueRepair:
            guard snapshot.state.allowsCatalogueRepair else {
                throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
            }
            source = .catalogue
            intent = snapshot.state.intent
        }
        let state = ChekinanaIdolAvatarStateSnapshot(
            source: source, intent: intent, revision: nil
        )
        guard state.isValid(avatarImageRef: finalReference) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        try ChekinanaIdolAvatarStatePersistence.record(
            idolID: snapshot.idolID, source: source, intent: intent, in: context
        )
    }
}


@MainActor
enum ChekinanaIdolReferenceAvatarPolicy {
    static func targetKind(
        for target: ChekinanaCatalogueIdolTarget
    ) -> ChekinanaIdolReferenceAvatarTargetKind {
        let isCatalogue = ChekinanaManualIdolInput.requiresManagedAvatar(
            sourceId: target.idol.sourceId
        )
        return switch (target.shouldInsert, isCatalogue) {
        case (true, false): .newManual
        case (false, false): .existingManual
        case (true, true): .newCatalogue
        case (false, true): .reusedCatalogue
        }
    }

    static func shouldInitializeAvatarFromReference(
        targetKind: ChekinanaIdolReferenceAvatarTargetKind,
        targetHasManagedAvatar: Bool,
        hasExplicitAvatarReplacement: Bool,
        explicitlyRemovingAvatar: Bool
    ) -> Bool {
        targetKind.isManual
            && !targetHasManagedAvatar
            && !hasExplicitAvatarReplacement
            && !explicitlyRemovingAvatar
    }
}

struct ChekinanaIdolReferenceAvatarPreparationResult {
    let encodedReferencePattern: [Float]?
    let stagedAvatar: ChekinanaIdolReferenceStore.StoredAvatar?
    let initializedAvatarFromReference: Bool
}

@MainActor
enum ChekinanaIdolReferenceAvatarPreparation {
    typealias EncodeReference = (Data) async throws -> [Float]
    typealias StageAvatar = (
        Data
    ) async throws -> ChekinanaIdolReferenceStore.StoredAvatar

    static func prepare(
        referenceData: Data?,
        explicitAvatarData: Data?,
        targetKind: ChekinanaIdolReferenceAvatarTargetKind,
        targetHasManagedAvatar: Bool,
        explicitlyRemovingAvatar: Bool,
        encodeReference: EncodeReference,
        stageAvatar: StageAvatar
    ) async throws -> ChekinanaIdolReferenceAvatarPreparationResult {
        guard !explicitlyRemovingAvatar else {
            return ChekinanaIdolReferenceAvatarPreparationResult(
                encodedReferencePattern: nil,
                stagedAvatar: nil,
                initializedAvatarFromReference: false
            )
        }

        // Encoding precedes every avatar write. A failed Reference can neither
        // create a new avatar file nor transfer ownership of the old one.
        let encodedReferencePattern: [Float]?
        if let referenceData {
            encodedReferencePattern = try await encodeReference(referenceData)
        } else {
            encodedReferencePattern = nil
        }

        let initializesFromReference = referenceData != nil
            && ChekinanaIdolReferenceAvatarPolicy.shouldInitializeAvatarFromReference(
                targetKind: targetKind,
                targetHasManagedAvatar: targetHasManagedAvatar,
                hasExplicitAvatarReplacement: explicitAvatarData != nil,
                explicitlyRemovingAvatar: explicitlyRemovingAvatar
            )
        let avatarData = explicitAvatarData
            ?? (initializesFromReference ? referenceData : nil)
        let stagedAvatar: ChekinanaIdolReferenceStore.StoredAvatar?
        if let avatarData {
            stagedAvatar = try await stageAvatar(avatarData)
        } else {
            stagedAvatar = nil
        }
        return ChekinanaIdolReferenceAvatarPreparationResult(
            encodedReferencePattern: encodedReferencePattern,
            stagedAvatar: stagedAvatar,
            initializedAvatarFromReference: initializesFromReference
        )
    }
}

enum ChekinanaIdolAvatarSelectionPolicy {
    static func invalidatingCataloguePreparation(
        generation: Int
    ) -> (generation: Int, isPreparingCatalogueAvatar: Bool) {
        (generation &+ 1, false)
    }

    static func afterDelete(
        generation: Int
    ) -> (
        generation: Int,
        removesAvatar: Bool,
        isPreparingCatalogueAvatar: Bool
    ) {
        let invalidation = invalidatingCataloguePreparation(
            generation: generation
        )
        return (
            invalidation.generation,
            true,
            invalidation.isPreparingCatalogueAvatar
        )
    }
    static func shouldReadExistingAvatar(explicitlyRemoving: Bool) -> Bool { !explicitlyRemoving }
    static func acceptsCatalogueCompletion(
        generation: Int,
        currentGeneration: Int,
        candidateMatches: Bool
    ) -> Bool {
        generation == currentGeneration && candidateMatches
    }
    static func acceptsCataloguePreview(generation: Int, currentGeneration: Int, candidateMatches: Bool, removesAvatar: Bool, hasLocalItem: Bool) -> Bool {
        acceptsCatalogueCompletion(
            generation: generation,
            currentGeneration: currentGeneration,
            candidateMatches: candidateMatches
        ) && !removesAvatar && !hasLocalItem
    }
}

enum ChekinanaIdolAvatarEditorCleanupPurpose {
    case afterSuccessfulSave
    case rollbackAfterFailedSave
}

enum ChekinanaIdolPersistenceError: LocalizedError {
    case linkedChekiRecords(Int)
    case mergeSourceMissing
    case mergeTargetMissing
    case mergeTargetMatchesSource
    case databaseSaveAndStagedAvatarCleanupFailed(
        save: String,
        cleanup: String,
        pendingCleanupTarget: ChekinanaIdolAvatarCleanupTarget
    )

    var pendingCleanupTarget: ChekinanaIdolAvatarCleanupTarget? {
        switch self {
        case .linkedChekiRecords, .mergeSourceMissing, .mergeTargetMissing,
                .mergeTargetMatchesSource:
            return nil
        case .databaseSaveAndStagedAvatarCleanupFailed(_, _, let target):
            return target
        }
    }

    var errorDescription: String? {
        switch self {
        case .linkedChekiRecords(let count):
            return ChekinanaProductCopy.format(
                "idols.delete.error.linked_records",
                "This Idol has %lld linked Cheki record(s). Reassign them before deleting.",
                Int64(count)
            )
        case .mergeSourceMissing:
            return ChekinanaProductCopy.text(
                "idols.merge.error.source_missing",
                "The Idol being merged no longer exists. Close this editor and try again."
            )
        case .mergeTargetMissing:
            return ChekinanaProductCopy.text(
                "idols.merge.error.target_missing",
                "The selected target Idol no longer exists. Choose another target and try again."
            )
        case .mergeTargetMatchesSource:
            return ChekinanaProductCopy.text(
                "idols.merge.error.same_idol",
                "An Idol cannot be merged into itself."
            )
        case .databaseSaveAndStagedAvatarCleanupFailed(let save, let cleanup, _):
            return ChekinanaProductCopy.format(
                "idols.avatar_cleanup_database_failure",
                "The database was not saved and the previous Idol/avatar reference remains unchanged. The new staged avatar still needs cleanup (save: %1$@; cleanup: %2$@). Retry cleanup before closing.",
                save,
                cleanup
            )
        }
    }
}

struct ChekinanaIdolPersistenceResult {
    let pendingAvatarCleanup: ChekinanaIdolAvatarCleanupTarget?
    var pendingAssociatedMediaCleanup = false
}

/// A confirmation authorizes this exact associated-record set, not future links.
struct ChekinanaIdolCascadeAuthorization: Equatable, Sendable {
    struct Media: Equatable, Sendable {
        let kind: String
        let record: ChekinanaChekiEditRecordSnapshot
    }
    struct Quantity: Equatable, Sendable {
        let id: UUID
        let idolIDs: [UUID]
        let eventID: UUID?
        let date: Date?
        let sizeRawValue: String?
        let note: String
        let count: Int

        @MainActor init(_ record: ChekiRecord) {
            id = record.id; idolIDs = record.idolIDs; eventID = record.eventID
            date = record.date; sizeRawValue = record.sizeRawValue
            note = record.note; count = record.count
        }
    }
    struct IdolWitness: Equatable, Sendable {
        let id: UUID
        let name: String
        let updatedAt: Date
        let avatarRef: String?
    }
    let libraryGeneration: UUID?
    let idols: [IdolWitness]
    var selectedIdolIDs: Set<UUID> { Set(idols.map(\.id)) }
    let media: [Media]
    let quantities: [Quantity]
    let memories: [ChekinanaMemoryRecordSnapshot]
    let attachments: [ChekinanaMemoryAttachmentRecordSnapshot]

    @MainActor static func capture(idolID: UUID, in context: ModelContext) throws -> Self {
        try capture(idolIDs: [idolID], in: context)
    }

    @MainActor static func capture(idolIDs: Set<UUID>, in context: ModelContext) throws -> Self {
        let selected = try context.fetch(FetchDescriptor<Idol>()).filter { idolIDs.contains($0.id) }
            .sorted { $0.id.uuidString < $1.id.uuidString }
        guard !idolIDs.isEmpty, idolIDs.count <= 50, selected.count == idolIDs.count else {
            throw ChekinanaIdolCascadeError.changedAssociations
        }
        let media = try context.fetch(FetchDescriptor<MediaItem>())
            .filter { !idolIDs.isDisjoint(with: $0.idolIDs) }
            .sorted { $0.id.uuidString < $1.id.uuidString }
            .map { Media(kind: $0.kindRawValue, record: ChekinanaChekiEditRecordSnapshot($0)) }
        let quantities = try context.fetch(FetchDescriptor<ChekiRecord>())
            .filter { !idolIDs.isDisjoint(with: $0.idolIDs) }
            .sorted { $0.id.uuidString < $1.id.uuidString }.map(Quantity.init)
        let memories = try context.fetch(FetchDescriptor<Memory>())
            .filter { !idolIDs.isDisjoint(with: $0.idolIDs) }
            .sorted { $0.id.uuidString < $1.id.uuidString }.map(ChekinanaMemoryRecordSnapshot.init)
        let memoryIDs = Set(memories.map(\.id))
        let attachments = try context.fetch(FetchDescriptor<MemoryAttachment>())
            .filter { memoryIDs.contains($0.memoryID) }
            .sorted { $0.id.uuidString < $1.id.uuidString }.map(ChekinanaMemoryAttachmentRecordSnapshot.init)
        return Self(libraryGeneration: try ChekinanaLibraryGenerationStore.current(in: context), idols: selected.map { IdolWitness(id: $0.id, name: $0.name,
            updatedAt: $0.updatedAt, avatarRef: $0.avatarImageRef) }, media: media,
            quantities: quantities, memories: memories, attachments: attachments)
    }

    func retains(_ idolIDs: [UUID]) -> Bool {
        idolIDs.contains { !selectedIdolIDs.contains($0) }
    }
    var deletedMedia: [Media] { media.filter { !retains($0.record.idolIDs) } }
    var retainedMedia: [Media] { media.filter { retains($0.record.idolIDs) } }
    var deletedQuantities: [Quantity] { quantities.filter { !retains($0.idolIDs) } }
    var retainedQuantities: [Quantity] { quantities.filter { retains($0.idolIDs) } }
    var deletedMemories: [ChekinanaMemoryRecordSnapshot] { memories.filter { !retains($0.idolIDs) } }
    var retainedMemories: [ChekinanaMemoryRecordSnapshot] { memories.filter { retains($0.idolIDs) } }
    var deletedAttachments: [ChekinanaMemoryAttachmentRecordSnapshot] {
        let ids = Set(deletedMemories.map(\.id))
        return attachments.filter { ids.contains($0.memoryID) }
    }
    var retainedAttachmentCount: Int { attachments.count - deletedAttachments.count }
    static func quantityCount(_ records: [Quantity]) throws -> Int {
        try records.reduce(0) { try ChekinanaChekiRecordStore.checkedCountSum($0, max(1, $1.count)) }
    }
}

enum ChekinanaIdolCascadeError: LocalizedError {
    case changedAssociations
    var errorDescription: String? {
        ChekinanaProductCopy.text("idols.delete.changed_associations",
            "The Idol or its associated records changed. Request deletion again to review the updated impact.")
    }
}

enum ChekinanaIdolMergePolicy {
    static func targets(
        from storedIdols: [Idol],
        sourceID: UUID,
        hiddenIDs: Set<UUID>,
        chekiCountsByIdolID: [UUID: Int] = [:]
    ) -> [Idol] {
        ChekinanaIdolOrdering.orderedForList(
            storedIdols,
            chekiCountsByIdolID: chekiCountsByIdolID
        ).filter {
            $0.id != sourceID && !hiddenIDs.contains($0.id)
        }
    }

    static func replacingSource(
        in idols: [Idol],
        sourceID: UUID,
        with target: Idol
    ) -> [Idol] {
        var seen = Set<UUID>()
        return idols.compactMap { idol in
            let replacement = idol.id == sourceID ? target : idol
            return seen.insert(replacement.id).inserted ? replacement : nil
        }
    }

    static func replacingSource(
        in idolIDs: [UUID],
        sourceID: UUID,
        with targetID: UUID
    ) -> [UUID] {
        var seen = Set<UUID>()
        return idolIDs.compactMap { idolID in
            let replacement = idolID == sourceID ? targetID : idolID
            return seen.insert(replacement).inserted ? replacement : nil
        }
    }
}

@MainActor
enum ChekinanaIdolPersistence {
    typealias SaveContext = (ModelContext) throws -> Void
    typealias RemoveStagedAvatar = (ChekinanaIdolReferenceStore.StoredAvatar) throws -> Void
    typealias RemoveManagedAvatar = (String?, UUID, URL?) throws -> Bool

    static func save(
        _ idol: Idol,
        inserting: Bool,
        previousAvatarRef: String?,
        stagedAvatar: ChekinanaIdolReferenceStore.StoredAvatar?,
        in modelContext: ModelContext,
        avatarDirectory: URL? = nil,
        libraryGeneration: UUID? = nil,
        cleanupDefaults: UserDefaults = .standard,
        saveContext: SaveContext = { try $0.save() },
        removeStagedAvatar: RemoveStagedAvatar = {
            try FileManager.default.removeItem(at: $0.url)
        },
        removeReplacedAvatar: RemoveManagedAvatar = {
            try ChekinanaIdolReferenceStore.removeManagedAvatar(
                $0,
                idolID: $1,
                directory: $2
            )
        },
        apply: (Idol) -> Void
    ) throws -> ChekinanaIdolPersistenceResult {
        if inserting {
            modelContext.insert(idol)
        }
        apply(idol)
        do {
            try saveContext(modelContext)
        } catch {
            let saveError = error
            if inserting {
                modelContext.delete(idol)
            }
            modelContext.rollback()
            if let stagedAvatar {
                do {
                    try removeStagedAvatar(stagedAvatar)
                } catch {
                    throw ChekinanaIdolPersistenceError.databaseSaveAndStagedAvatarCleanupFailed(
                        save: saveError.localizedDescription,
                        cleanup: error.localizedDescription,
                        pendingCleanupTarget: ChekinanaIdolAvatarCleanupTarget(
                            imageRef: stagedAvatar.ref,
                            idolID: idol.id,
                            directory: avatarDirectory
                                ?? stagedAvatar.url.deletingLastPathComponent()
                        )
                    )
                }
            }
            throw saveError
        }

        return cleanupResult(
            previousAvatarRef,
            replacingWith: idol.avatarImageRef,
            idolID: idol.id,
            directory: avatarDirectory,
            libraryGeneration: libraryGeneration
                ?? (try? ChekinanaLibraryGenerationStore.current(in: modelContext)),
            cleanupDefaults: cleanupDefaults,
            removeManagedAvatar: removeReplacedAvatar
        )
    }

    static func delete(
        _ idol: Idol,
        from modelContext: ModelContext,
        cascadeAuthorization: ChekinanaIdolCascadeAuthorization? = nil,
        avatarDirectory: URL? = nil,
        libraryGeneration: UUID? = nil,
        cleanupDefaults: UserDefaults = .standard,
        saveContext: SaveContext = { try $0.save() },
        removeManagedAvatar: RemoveManagedAvatar = {
            try ChekinanaIdolReferenceStore.removeManagedAvatar(
                $0,
                idolID: $1,
                directory: $2
            )
        }
    ) throws -> ChekinanaIdolPersistenceResult {
        if let cascadeAuthorization {
            return try deleteConfirmedCascade(idol, authorization: cascadeAuthorization,
                from: modelContext, directory: avatarDirectory,
                cleanupDefaults: cleanupDefaults, saveContext: saveContext)
        }
        return try ChekinanaLibraryMutationProtocol.withExclusiveOperationSync {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: avatarDirectory
            )
            let (avatarRef, idolID) = try ChekinanaChekiRecordStore.withMutationLock {
                do {
                    let idolID = idol.id
                    let mediaCount = try modelContext.fetch(
                        FetchDescriptor<MediaItem>()
                    ).filter { $0.idolIDs.contains(idolID) }.count
                    let simpleCount = try modelContext.fetch(
                        FetchDescriptor<ChekiRecord>()
                    ).filter { $0.idolIDs.contains(idolID) }
                        .reduce(0) { partialResult, record in
                            try ChekinanaChekiRecordStore.checkedCountSum(
                                partialResult,
                                max(1, record.count)
                            )
                        }
                    let linkedRecordCount = try ChekinanaChekiRecordStore
                        .checkedCountSum(mediaCount, simpleCount)
                    guard linkedRecordCount == 0 else {
                        throw ChekinanaIdolPersistenceError.linkedChekiRecords(
                            linkedRecordCount
                        )
                    }
                    let avatarRef = idol.avatarImageRef
                    if let patternState = (try? ChekinanaIdolPatternPersistence.state(
                        for: idolID,
                        in: modelContext
                    )) ?? nil {
                        modelContext.delete(patternState)
                    }
                    try ChekinanaIdolAvatarStatePersistence.delete(
                        for: idolID,
                        in: modelContext
                    )
                    for memory in try modelContext.fetch(FetchDescriptor<Memory>())
                    where memory.idolIDs.contains(idolID) {
                        memory.idolIDs.removeAll { $0 == idolID }
                        memory.updatedAt = Date()
                    }
                    modelContext.delete(idol)
                    try saveContext(modelContext)
                    return (avatarRef, idolID)
                } catch {
                    modelContext.rollback()
                    throw error
                }
            }
            return cleanupResult(
                avatarRef,
                replacingWith: nil,
                idolID: idolID,
                directory: avatarDirectory,
                libraryGeneration: libraryGeneration
                    ?? (try? ChekinanaLibraryGenerationStore.current(in: modelContext)),
                cleanupDefaults: cleanupDefaults,
                removeManagedAvatar: removeManagedAvatar
            )
        }
    }

    /// Assistant-only cascade: the preview's exact witness is required. Files stay
    /// at their original locations until the single database save commits.
    private static func deleteConfirmedCascade(
        _ idol: Idol,
        authorization: ChekinanaIdolCascadeAuthorization,
        from context: ModelContext,
        directory: URL?,
        cleanupDefaults: UserDefaults,
        saveContext: SaveContext
    ) throws -> ChekinanaIdolPersistenceResult {
        try ChekinanaLibraryMutationProtocol.withExclusiveOperationSync {
            let directory = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(in: context, directory: directory)
            return try ChekinanaChekiRecordStore.withMutationLock {
                try ChekinanaChekiEditRecovery.requireConvergedExclusively(in: context, directory: directory)
                guard authorization.selectedIdolIDs.contains(idol.id),
                      try ChekinanaIdolCascadeAuthorization.capture(idolIDs: authorization.selectedIdolIDs, in: context) == authorization,
                      try ChekinanaIdolCascadeAuthorization.capture(idolIDs: authorization.selectedIdolIDs, in: ModelContext(context.container)) == authorization else {
                    throw ChekinanaIdolCascadeError.changedAssociations
                }
                let generation = try ChekinanaLibraryGenerationStore.ensureCurrent(in: context)
                let mediaIDs = Set(authorization.deletedMedia.map { $0.record.id })
                let recordIDs = Set(authorization.deletedQuantities.map(\.id))
                let memoryIDs = Set(authorization.deletedMemories.map(\.id))
                let attachmentIDs = Set(authorization.deletedAttachments.map(\.id))
                let survivors = try ChekinanaLibraryFileReferenceSnapshot.capture(
                    in: ModelContext(context.container), directory: directory,
                    excludingMediaItemIDs: mediaIDs, excludingIdolIDs: authorization.selectedIdolIDs,
                    excludingMemoryAttachmentIDs: attachmentIDs
                ).referencedFilenames
                var chekiJournals: [ChekinanaChekiDeletionJournal] = []
                var galleryJournal: ChekinanaGalleryDeletionJournal?
                var memoryJournal: ChekinanaMemoryAttachmentDeletionJournal?
                var avatarEntries: [ChekinanaIdolAvatarCleanupEntry] = []
                var claimedFilenames = survivors
                let originalAutosave = context.autosaveEnabled
                context.autosaveEnabled = false
                defer { context.autosaveEnabled = originalAutosave }
                @MainActor func recoverFiles() -> Bool {
                    var deferred = false
                    for journal in chekiJournals {
                        do {
                            _ = try ChekinanaChekiDeletionRecovery.recover(journal, in: context, directory: directory,
                                moveItem: { try FileManager.default.moveItem(at: $0, to: $1) },
                                removeItem: { try FileManager.default.removeItem(at: $0) })
                        } catch { deferred = true }
                    }
                    if galleryJournal != nil {
                        deferred = ChekinanaGalleryDeletionRecoveryCoordinator.recoverExclusively(
                            in: context, directory: directory) > 0 || deferred
                    }
                    if memoryJournal != nil {
                        deferred = ChekinanaMemoryAttachmentDeletionCoordinator.recoverExclusively(
                            in: context, directory: directory) > 0 || deferred
                    }
                    if !avatarEntries.isEmpty {
                        deferred = ChekinanaIdolAvatarCleanupQueue.cleanupNow(
                            in: context, directory: directory, defaults: cleanupDefaults) > 0 || deferred
                    }
                    return deferred
                }
                do {
                    let galleryOperationID = UUID()
                    var galleryEntries: [ChekinanaGalleryDeletionJournal.Entry] = []
                    for media in authorization.deletedMedia {
                        let record = media.record
                        if media.kind == MediaItemKind.cheki.rawValue {
                            let filename = ChekinanaChekiDeletionJournal.managedFilename(for: record)
                            let identity: ChekinanaImportFileIdentity?
                            if let filename, claimedFilenames.insert(filename).inserted {
                                identity = try ChekinanaChekiDeletionJournalStore.identity(
                                    at: directory.appendingPathComponent(filename), in: directory)
                            } else { identity = nil }
                            let operationID = UUID()
                            let journal = ChekinanaChekiDeletionJournal(formatVersion: 1,
                                operationID: operationID, libraryGeneration: generation, recordBefore: record,
                                originalFilename: filename,
                                quarantineFilename: ".delete-\(record.id.uuidString)-\(operationID.uuidString).quarantine",
                                identity: identity, restorationOnly: false)
                            // Track before persistence, so a partial journal write is
                            // retained/recovered rather than silently losing ownership.
                            chekiJournals.append(journal)
                            try ChekinanaChekiDeletionJournalStore.persist(journal, in: directory)
                        } else if let kind = ChekinanaGalleryMediaKind(rawValue: media.kind) {
                            for filename in ChekinanaGalleryMediaStore.managedFilenames(
                                kind: kind, id: record.mediaOwnerID, reference: record.mediaRef
                            ) where claimedFilenames.insert(filename).inserted {
                                guard let identity = try ChekinanaChekiDeletionJournalStore.identity(
                                    at: directory.appendingPathComponent(filename), in: directory) else { continue }
                                galleryEntries.append(.init(originalName: filename,
                                    quarantineName: ".delete-\(galleryOperationID.uuidString.lowercased())-\(filename)",
                                    identity: identity, stage: .planned))
                            }
                        } else { throw ChekinanaIdolCascadeError.changedAssociations }
                    }
                    if !galleryEntries.isEmpty {
                        let journal = ChekinanaGalleryDeletionJournal(formatVersion: 1,
                            operationID: galleryOperationID, libraryGeneration: generation,
                            phase: .databaseCommitPending, entries: galleryEntries)
                        galleryJournal = journal
                        try ChekinanaGalleryDeletionJournalStore.persist(journal, in: directory)
                    }
                    memoryJournal = try ChekinanaMemoryAttachmentDeletionCoordinator.preparePersistedDeletion(
                        authorization.deletedAttachments, libraryGeneration: generation, in: context, directory: directory)
                    for selected in authorization.idols {
                        if let avatarRef = selected.avatarRef,
                           let entry = try ChekinanaIdolAvatarCleanupQueue.registerExisting(imageRef: avatarRef,
                            idolID: selected.id, directory: directory, libraryGeneration: generation,
                            purpose: .replacedCommittedAvatar, defaults: cleanupDefaults) {
                            avatarEntries.append(entry)
                        }
                    }
                    let selectedIDs = authorization.selectedIdolIDs
                    let mediaItems = try context.fetch(FetchDescriptor<MediaItem>())
                    let movingChekiIDs = Set(authorization.retainedMedia.filter {
                        $0.kind == MediaItemKind.cheki.rawValue
                    }.map { $0.record.id })
                    for item in mediaItems {
                        if mediaIDs.contains(item.id) { context.delete(item) }
                        else if !selectedIDs.isDisjoint(with: item.idolIDs) {
                            item.idolIDs.removeAll { selectedIDs.contains($0) }
                            item.updatedAt = Date()
                        }
                    }
                    // Removing an Idol changes the complete group key. Reuse the
                    // existing merge allocator only for groups receiving shared Cheki.
                    let assignments = try ChekinanaChekiIndexing.assignmentsForMergedGroups(
                        mediaItems.compactMap { item in
                            guard !mediaIDs.contains(item.id), item.kind == .cheki,
                                  let group = ChekinanaChekiGroupKey(idolIDs: item.idolIDs, date: item.date) else { return nil }
                            return ChekinanaChekiIndexSnapshot(chekiID: item.id, group: group,
                                idx: item.idx, isFavorite: item.isFavorite, createdAt: item.createdAt)
                        }, movingChekiIDs: movingChekiIDs)
                    for item in mediaItems {
                        if let idx = assignments[item.id], item.idx != idx { item.idx = idx }
                    }
                    for record in try context.fetch(FetchDescriptor<ChekiRecord>()) {
                        if recordIDs.contains(record.id) { context.delete(record) }
                        else if !selectedIDs.isDisjoint(with: record.idolIDs) {
                            record.idolIDs.removeAll { selectedIDs.contains($0) }
                        }
                    }
                    for attachment in try context.fetch(FetchDescriptor<MemoryAttachment>()) where attachmentIDs.contains(attachment.id) { context.delete(attachment) }
                    for memory in try context.fetch(FetchDescriptor<Memory>()) {
                        if memoryIDs.contains(memory.id) { context.delete(memory) }
                        else if !selectedIDs.isDisjoint(with: memory.idolIDs) {
                            memory.idolIDs.removeAll { selectedIDs.contains($0) }
                            memory.updatedAt = Date()
                        }
                    }
                    for selected in try context.fetch(FetchDescriptor<Idol>()) where selectedIDs.contains(selected.id) {
                        if let state = try ChekinanaIdolPatternPersistence.state(for: selected.id, in: context) { context.delete(state) }
                        try ChekinanaIdolAvatarStatePersistence.delete(for: selected.id, in: context)
                        context.delete(selected)
                    }
                    try saveContext(context)
                } catch {
                    context.rollback()
                    _ = recoverFiles()
                    throw error
                }
                if var journal = galleryJournal {
                    journal.phase = .databaseCommitted
                    try? ChekinanaGalleryDeletionJournalStore.persist(journal, in: directory)
                }
                ChekinanaMemoryAttachmentDeletionCoordinator.markDatabaseCommitted(memoryJournal, directory: directory)
                let deferred = recoverFiles()
                let avatarTarget = avatarEntries.first(where: { entry in
                    ChekinanaIdolAvatarCleanupQueue.contains(operationID: entry.operationID, defaults: cleanupDefaults)
                }).map { entry in
                    ChekinanaIdolAvatarCleanupTarget(imageRef: entry.imageRef, idolID: entry.idolID,
                        directory: directory, operationID: entry.operationID)
                }
                return ChekinanaIdolPersistenceResult(pendingAvatarCleanup: avatarTarget, pendingAssociatedMediaCleanup: deferred)
            }
        }
    }

    static func merge(
        sourceID: UUID,
        into targetID: UUID,
        in modelContext: ModelContext,
        avatarDirectory: URL? = nil,
        libraryGeneration: UUID? = nil,
        cleanupDefaults: UserDefaults = .standard,
        saveContext: SaveContext = { try $0.save() },
        removeManagedAvatar: RemoveManagedAvatar = {
            try ChekinanaIdolReferenceStore.removeManagedAvatar(
                $0,
                idolID: $1,
                directory: $2
            )
        }
    ) throws -> ChekinanaIdolPersistenceResult {
        guard sourceID != targetID else {
            throw ChekinanaIdolPersistenceError.mergeTargetMatchesSource
        }
        return try ChekinanaLibraryMutationProtocol
            .withExclusiveOperationSync {
                try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                    in: modelContext, directory: avatarDirectory
                )
                let avatarRef = try ChekinanaChekiRecordStore.withMutationLock {
                    try ChekinanaChekiEditRecovery.requireConvergedExclusively(
                        in: modelContext,
                        directory: avatarDirectory
                    )
                    var mediaSnapshots: [(model: MediaItem, idolIDs: [UUID])] = []
                    var indexSnapshots: [(model: MediaItem, idx: Int?)] = []
                    var recordSnapshots: [(model: ChekiRecord, idolIDs: [UUID])] = []
                    var memorySnapshots: [(model: Memory, idolIDs: [UUID])] = []
                    do {
                let idols = try modelContext.fetch(FetchDescriptor<Idol>())
                guard let source = idols.first(where: { $0.id == sourceID }) else {
                    throw ChekinanaIdolPersistenceError.mergeSourceMissing
                }
                guard let target = idols.first(where: { $0.id == targetID }) else {
                    throw ChekinanaIdolPersistenceError.mergeTargetMissing
                }

                let mediaItems = try modelContext.fetch(FetchDescriptor<MediaItem>())
                mediaSnapshots = mediaItems
                    .filter { $0.idolIDs.contains(sourceID) }
                    .map { ($0, $0.idolIDs) }
                recordSnapshots = try modelContext.fetch(FetchDescriptor<ChekiRecord>())
                    .filter { $0.idolIDs.contains(sourceID) }
                    .map { ($0, $0.idolIDs) }
                memorySnapshots = try modelContext.fetch(FetchDescriptor<Memory>())
                    .filter { $0.idolIDs.contains(sourceID) }
                    .map { ($0, $0.idolIDs) }

                for snapshot in mediaSnapshots {
                    snapshot.model.idolIDs = ChekinanaIdolMergePolicy.replacingSource(
                        in: snapshot.model.idolIDs,
                        sourceID: sourceID,
                        with: target.id
                    )
                }
                for snapshot in recordSnapshots {
                    let record = snapshot.model
                    record.idolIDs = ChekinanaIdolMergePolicy.replacingSource(
                        in: record.idolIDs,
                        sourceID: sourceID,
                        with: targetID
                    )
                }
                let indexAssignments = try ChekinanaChekiIndexing.assignmentsForMergedGroups(
                    mediaItems.compactMap { item in
                        guard item.kind == .cheki,
                              let group = ChekinanaChekiGroupKey(
                                idolIDs: item.idolIDs, date: item.date) else { return nil }
                        return ChekinanaChekiIndexSnapshot(
                            chekiID: item.id, group: group, idx: item.idx,
                            isFavorite: item.isFavorite, createdAt: item.createdAt
                        )
                    },
                    movingChekiIDs: Set(mediaSnapshots.filter {
                        $0.model.kind == .cheki
                    }.map { $0.model.id })
                )
                for item in mediaItems {
                    guard let idx = indexAssignments[item.id], item.idx != idx else { continue }
                    indexSnapshots.append((item, item.idx))
                    item.idx = idx
                }
                for snapshot in memorySnapshots {
                    snapshot.model.idolIDs = ChekinanaIdolMergePolicy.replacingSource(
                        in: snapshot.model.idolIDs,
                        sourceID: sourceID,
                        with: targetID
                    )
                    snapshot.model.updatedAt = Date()
                }

                for state in try modelContext.fetch(FetchDescriptor<IdolPatternState>())
                where state.idolID == sourceID {
                    modelContext.delete(state)
                }
                try ChekinanaIdolAvatarStatePersistence.delete(
                    for: sourceID,
                    in: modelContext
                )
                let previousAvatarRef = source.avatarImageRef
                modelContext.delete(source)
                try saveContext(modelContext)
                return previousAvatarRef
                    } catch {
                        for snapshot in indexSnapshots {
                            snapshot.model.idx = snapshot.idx
                        }
                        for snapshot in mediaSnapshots {
                            snapshot.model.idolIDs = snapshot.idolIDs
                        }
                        for snapshot in recordSnapshots {
                            snapshot.model.idolIDs = snapshot.idolIDs
                        }
                        for snapshot in memorySnapshots {
                            snapshot.model.idolIDs = snapshot.idolIDs
                        }
                        modelContext.rollback()
                        throw error
                    }
                }
                return cleanupResult(
                    avatarRef,
                    replacingWith: nil,
                    idolID: sourceID,
                    directory: avatarDirectory,
                    libraryGeneration: libraryGeneration
                        ?? (try? ChekinanaLibraryGenerationStore.current(in: modelContext)),
                    cleanupDefaults: cleanupDefaults,
                    removeManagedAvatar: removeManagedAvatar
                )
            }
    }

    private static func cleanupResult(
        _ previousAvatarRef: String?,
        replacingWith newAvatarRef: String?,
        idolID: UUID,
        directory: URL?,
        libraryGeneration: UUID?,
        cleanupDefaults: UserDefaults,
        removeManagedAvatar: RemoveManagedAvatar
    ) -> ChekinanaIdolPersistenceResult {
        guard let previousAvatarRef,
              previousAvatarRef != newAvatarRef else {
            return ChekinanaIdolPersistenceResult(pendingAvatarCleanup: nil)
        }
        do {
            _ = try removeManagedAvatar(
                previousAvatarRef,
                idolID,
                directory
            )
            return ChekinanaIdolPersistenceResult(pendingAvatarCleanup: nil)
        } catch {
            let resolvedDirectory = try? directory
                ?? ChekiImageRefResolver.chekiImagesDirectory()
            let operationID: UUID?
            if let resolvedDirectory, let libraryGeneration {
                operationID = try? ChekinanaIdolAvatarCleanupQueue.registerExisting(
                    imageRef: previousAvatarRef,
                    idolID: idolID,
                    directory: resolvedDirectory,
                    libraryGeneration: libraryGeneration,
                    purpose: .replacedCommittedAvatar,
                    defaults: cleanupDefaults
                )?.operationID
            } else {
                operationID = nil
            }
            return ChekinanaIdolPersistenceResult(
                pendingAvatarCleanup: ChekinanaIdolAvatarCleanupTarget(
                    imageRef: previousAvatarRef,
                    idolID: idolID,
                    directory: directory,
                    operationID: operationID
                )
            )
        }
    }
}

enum ChekinanaIdolReferenceStore {
    struct StoredAvatar: Equatable {
        let ref: String
        let url: URL
        let identity: ChekinanaImportFileIdentity?

        init(
            ref: String,
            url: URL,
            identity: ChekinanaImportFileIdentity? = nil
        ) {
            self.ref = ref
            self.url = url
            self.identity = identity
        }
    }

    @MainActor
    static func saveAvatar(
        _ originalData: Data,
        idolID: UUID,
        directory: URL? = nil,
        reserveBeforeWrite: ((StoredAvatar) throws -> Void)? = nil
    ) async throws -> StoredAvatar {
        guard let jpeg = await ChekinanaImageWorker.reencodedJPEGData(from: originalData),
              !jpeg.isEmpty else {
            throw ChekinanaProductMediaError.unreadableImage
        }
        let resolvedDirectory = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        try FileManager.default.createDirectory(
            at: resolvedDirectory,
            withIntermediateDirectories: true
        )
        let filename = managedFilename(idolID: idolID)
        let url = resolvedDirectory.appendingPathComponent(filename)
        let stored = StoredAvatar(
            ref: filename,
            url: url,
            identity: ChekinanaImportFileIdentity(jpeg)
        )
        try reserveBeforeWrite?(stored)
        try jpeg.write(to: url, options: .atomic)
        return stored
    }

    static func managedFilename(idolID: UUID, token: UUID = UUID()) -> String {
        "idol-avatar-\(idolID.uuidString.lowercased())-\(token.uuidString.lowercased()).jpg"
    }

    static func managedAvatarURL(
        for imageRef: String?,
        idolID: UUID,
        directory: URL? = nil
    ) throws -> URL? {
        guard let imageRef = imageRef?.trimmingCharacters(in: .whitespacesAndNewlines),
              !imageRef.isEmpty,
              imageRef == URL(fileURLWithPath: imageRef).lastPathComponent else {
            return nil
        }
        let lowercasedRef = imageRef.lowercased()
        let legacyFilename = "idol-\(idolID.uuidString.lowercased()).jpg"
        if lowercasedRef != legacyFilename {
            let prefix = "idol-avatar-\(idolID.uuidString.lowercased())-"
            guard lowercasedRef.hasPrefix(prefix),
                  lowercasedRef.hasSuffix(".jpg") else {
                return nil
            }
            let tokenStart = lowercasedRef.index(
                lowercasedRef.startIndex,
                offsetBy: prefix.count
            )
            let tokenEnd = lowercasedRef.index(lowercasedRef.endIndex, offsetBy: -4)
            guard tokenStart < tokenEnd,
                  UUID(uuidString: String(lowercasedRef[tokenStart..<tokenEnd])) != nil else {
                return nil
            }
        }
        let resolvedDirectory = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        return resolvedDirectory.appendingPathComponent(imageRef)
    }

    static func validatedManagedAvatar(
        imageRef: String?,
        idolID: UUID,
        directory: URL? = nil
    ) async -> ChekinanaRenderedImage? {
        guard let url = try? managedAvatarURL(
            for: imageRef,
            idolID: idolID,
            directory: directory
        ),
        FileManager.default.fileExists(atPath: url.path),
        let data = try? Data(contentsOf: url) else {
            return nil
        }
        return await ChekinanaImageWorker.thumbnailImage(
            from: data,
            maxDimension: 256
        )
    }

    static func hasManagedAvatarFile(
        imageRef: String?,
        idolID: UUID,
        directory: URL? = nil,
        fileManager: FileManager = .default
    ) -> Bool {
        guard let url = try? managedAvatarURL(
            for: imageRef,
            idolID: idolID,
            directory: directory
        ),
        fileManager.fileExists(atPath: url.path),
        let attributes = try? fileManager.attributesOfItem(atPath: url.path),
        let fileSize = attributes[.size] as? NSNumber else {
            return false
        }
        return fileSize.int64Value > 0
    }

    @discardableResult
    static func removeManagedAvatar(
        _ imageRef: String?,
        idolID: UUID,
        directory: URL? = nil,
        fileManager: FileManager = .default
    ) throws -> Bool {
        guard let url = try managedAvatarURL(
            for: imageRef,
            idolID: idolID,
            directory: directory
        ) else {
            return false
        }
        var isDirectory: ObjCBool = false
        guard fileManager.fileExists(atPath: url.path, isDirectory: &isDirectory),
              !isDirectory.boolValue else {
            return false
        }
        try fileManager.removeItem(at: url)
        return true
    }
}

enum ChekinanaCatalogueIdolAvatarLocalizerError: LocalizedError {
    case missingAvatar
    case identityMismatch
    case cleanupRequired

    var errorDescription: String? {
        switch self {
        case .missingAvatar:
            ChekinanaL10n.message("The catalogue avatar is unavailable. Retry the same catalogue result before saving.")
        case .identityMismatch:
            ChekinanaProductCopy.text(
                "idols.catalogue_avatar_identity_mismatch",
                "The prepared avatar does not match this catalogue Idol. Search and select the Idol again."
            )
        case .cleanupRequired:
            ChekinanaProductCopy.text(
                "idols.avatar_cleanup_required_after_save",
                "The Idol was saved, but an old managed avatar still requires cleanup."
            )
        }
    }
}

enum ChekinanaCatalogueIdolAvatarLocalizer {
    @MainActor
    static func stage(
        _ prepared: ChekinanaPreparedIdolCandidate,
        idolID: UUID,
        directory: URL? = nil,
        reserveBeforeWrite: ((ChekinanaIdolReferenceStore.StoredAvatar) throws -> Void)? = nil
    ) async throws -> ChekinanaIdolReferenceStore.StoredAvatar {
        guard let expectedIdentity = ChekinanaIdolAvatarIdentity.make(
            sourceID: prepared.candidate.sourceId,
            avatarURL: prepared.candidate.avatarUrl
        ) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.missingAvatar
        }
        guard prepared.avatarIdentity == expectedIdentity else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        guard let data = prepared.avatarThumbnailData, !data.isEmpty else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.missingAvatar
        }
        return try await ChekinanaIdolReferenceStore.saveAvatar(
            data,
            idolID: idolID,
            directory: directory,
            reserveBeforeWrite: reserveBeforeWrite
        )
    }
}

@MainActor
enum ChekinanaIdolAvatarRepairCoordinator {
    typealias PrepareExact = (String, String) async throws -> ChekinanaPreparedIdolCandidate
    typealias Stage = (
        ChekinanaPreparedIdolCandidate,
        UUID,
        URL?
    ) async throws -> ChekinanaIdolReferenceStore.StoredAvatar

    private struct FlightKey: Hashable {
        let modelContext: ObjectIdentifier
        let idolID: UUID
        let sourceID: String
        let avatarReference: String
        let avatarRevision: UUID
        let directoryPath: String
    }

    private struct Flight {
        let token: UUID
        let task: Task<Bool, Error>
    }

    private static var flights: [FlightKey: Flight] = [:]

    @discardableResult
    static func repairIfNeeded(
        _ idol: Idol,
        in modelContext: ModelContext,
        directory: URL? = nil,
        prepareExact: @escaping PrepareExact = { sourceID, query in
            try await ChekinanaCatalogueIdolAvatarResolver.prepareExact(
                sourceID: sourceID,
                query: query
            )
        },
        stage: @escaping Stage = { prepared, idolID, directory in
            try await ChekinanaCatalogueIdolAvatarLocalizer.stage(
                prepared,
                idolID: idolID,
                directory: directory
            )
        }
    ) async throws -> Bool {
        let expectedIdolID = idol.id
        let expectedModelID = idol.persistentModelID
        let initialSourceID = idol.sourceId?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let initialAvatarRef = idol.avatarImageRef?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let initialAvatarState = try ChekinanaIdolAvatarStatePersistence.snapshot(
            for: expectedIdolID,
            in: modelContext
        )
        guard initialAvatarState.allowsCatalogueRepair,
              let avatarRevision = initialAvatarState.revision,
              let initialAvatarRef,
              !initialAvatarRef.isEmpty,
              try ChekinanaIdolReferenceStore.managedAvatarURL(
                  for: initialAvatarRef,
                  idolID: expectedIdolID,
                  directory: directory
              ) != nil else {
            return false
        }
        guard isLive(
            idol,
            expectedIdolID: expectedIdolID,
            expectedModelID: expectedModelID,
            expectedSourceID: initialSourceID,
            expectedAvatarRef: initialAvatarRef,
            expectedAvatarState: initialAvatarState,
            in: modelContext
        ) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        let sourceID = initialSourceID
        guard let sourceID, !sourceID.isEmpty else {
            throw ChekinanaIdolAvatarRepairError.missingCatalogueIdentity(idol.name)
        }
        let key = FlightKey(
            modelContext: ObjectIdentifier(modelContext),
            idolID: idol.id,
            sourceID: sourceID,
            avatarReference: initialAvatarRef,
            avatarRevision: avatarRevision,
            directoryPath: directory?.standardizedFileURL.path ?? "<managed-default>"
        )
        if let flight = flights[key] {
            return try await flight.task.value
        }
        let token = UUID()
        let task = Task { @MainActor in
            try await performRepair(
                idol,
                expectedModelID: expectedModelID,
                sourceID: sourceID,
                expectedAvatarRef: initialAvatarRef,
                expectedAvatarState: initialAvatarState,
                in: modelContext,
                directory: directory,
                prepareExact: prepareExact,
                stage: stage
            )
        }
        flights[key] = Flight(token: token, task: task)
        do {
            let result = try await task.value
            if flights[key]?.token == token {
                flights[key] = nil
            }
            return result
        } catch {
            if flights[key]?.token == token {
                flights[key] = nil
            }
            throw error
        }
    }

    private static func performRepair(
        _ idol: Idol,
        expectedModelID: PersistentIdentifier,
        sourceID: String,
        expectedAvatarRef: String,
        expectedAvatarState: ChekinanaIdolAvatarStateSnapshot,
        in modelContext: ModelContext,
        directory: URL?,
        prepareExact: PrepareExact,
        stage: Stage
    ) async throws -> Bool {
        let expectedIdolID = idol.id
        guard isLive(
            idol,
            expectedIdolID: expectedIdolID,
            expectedModelID: expectedModelID,
            expectedSourceID: sourceID,
            expectedAvatarRef: expectedAvatarRef,
            expectedAvatarState: expectedAvatarState,
            in: modelContext
        ) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        let initiallyValid = await hasValidManagedAvatar(idol, directory: directory)
        guard isLive(
            idol,
            expectedIdolID: expectedIdolID,
            expectedModelID: expectedModelID,
            expectedSourceID: sourceID,
            expectedAvatarRef: expectedAvatarRef,
            expectedAvatarState: expectedAvatarState,
            in: modelContext
        ) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        if initiallyValid { return false }
        let prepared = try await prepareExact(sourceID, idol.name)
        guard isLive(
                  idol,
                  expectedIdolID: expectedIdolID,
                  expectedModelID: expectedModelID,
                  expectedSourceID: sourceID,
                  expectedAvatarRef: expectedAvatarRef,
                  expectedAvatarState: expectedAvatarState,
                  in: modelContext
              ),
              prepared.candidate.sourceId == sourceID else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        let validAfterPreparation = await hasValidManagedAvatar(idol, directory: directory)
        guard isLive(
            idol,
            expectedIdolID: expectedIdolID,
            expectedModelID: expectedModelID,
            expectedSourceID: sourceID,
            expectedAvatarRef: expectedAvatarRef,
            expectedAvatarState: expectedAvatarState,
            in: modelContext
        ) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        if validAfterPreparation { return false }
        return try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: directory
            )
            try Task.checkCancellation()
            guard isLive(
                idol,
                expectedIdolID: expectedIdolID,
                expectedModelID: expectedModelID,
                expectedSourceID: sourceID,
                expectedAvatarRef: expectedAvatarRef,
                expectedAvatarState: expectedAvatarState,
                in: modelContext
            ) else {
                throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
            }
            let staged = try await stage(prepared, expectedIdolID, directory)
            guard isLive(
                idol,
                expectedIdolID: expectedIdolID,
                expectedModelID: expectedModelID,
                expectedSourceID: sourceID,
                expectedAvatarRef: expectedAvatarRef,
                expectedAvatarState: expectedAvatarState,
                in: modelContext
            ) else {
                try removeUnusedStagedAvatar(staged)
                throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
            }
            let validAfterStaging = await hasValidManagedAvatar(idol, directory: directory)
            guard isLive(
                idol,
                expectedIdolID: expectedIdolID,
                expectedModelID: expectedModelID,
                expectedSourceID: sourceID,
                expectedAvatarRef: expectedAvatarRef,
                expectedAvatarState: expectedAvatarState,
                in: modelContext
            ) else {
                try removeUnusedStagedAvatar(staged)
                throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
            }
            if validAfterStaging {
                try removeUnusedStagedAvatar(staged)
                return false
            }
            return try ChekinanaPersistenceMutationCoordinator.withLock {
                guard isLive(
                    idol,
                    expectedIdolID: expectedIdolID,
                    expectedModelID: expectedModelID,
                    expectedSourceID: sourceID,
                    expectedAvatarRef: expectedAvatarRef,
                    expectedAvatarState: expectedAvatarState,
                    in: modelContext
                ), let avatarState = try ChekinanaIdolAvatarStatePersistence.state(
                    for: expectedIdolID,
                    in: modelContext
                ), avatarState.snapshot == expectedAvatarState else {
                    try removeUnusedStagedAvatar(staged)
                    throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
                }
                let previousAvatarRef = idol.avatarImageRef
                _ = try ChekinanaIdolPersistence.save(
                    idol,
                    inserting: false,
                    previousAvatarRef: previousAvatarRef,
                    stagedAvatar: staged,
                    in: modelContext,
                    avatarDirectory: directory
                ) { target in
                    target.avatarImageRef = staged.ref
                    target.updatedAt = Date()
                    avatarState.revision = UUID()
                }
                return true
            }
        }
    }

    private static func hasValidManagedAvatar(
        _ idol: Idol,
        directory: URL?
    ) async -> Bool {
        await ChekinanaIdolReferenceStore.validatedManagedAvatar(
            imageRef: idol.avatarImageRef,
            idolID: idol.id,
            directory: directory
        ) != nil
    }

    private static func isLive(
        _ idol: Idol,
        expectedIdolID: UUID,
        expectedModelID: PersistentIdentifier,
        expectedSourceID: String?,
        expectedAvatarRef: String,
        expectedAvatarState: ChekinanaIdolAvatarStateSnapshot,
        in modelContext: ModelContext
    ) -> Bool {
        guard idol.modelContext === modelContext,
              idol.persistentModelID == expectedModelID,
              !modelContext.deletedModelsArray.contains(where: {
                  $0.persistentModelID == expectedModelID
              }) else {
            return false
        }
        guard let liveAvatarState = try? ChekinanaIdolAvatarStatePersistence.snapshot(
            for: expectedIdolID,
            in: modelContext
        ) else {
            return false
        }
        return idol.id == expectedIdolID
            && idol.sourceId?.trimmingCharacters(in: .whitespacesAndNewlines)
                == expectedSourceID
            && idol.avatarImageRef?.trimmingCharacters(in: .whitespacesAndNewlines)
                == expectedAvatarRef
            && liveAvatarState == expectedAvatarState
            && liveAvatarState.allowsCatalogueRepair
    }

    private static func removeUnusedStagedAvatar(
        _ staged: ChekinanaIdolReferenceStore.StoredAvatar
    ) throws {
        do {
            try FileManager.default.removeItem(at: staged.url)
        } catch {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.cleanupRequired
        }
    }
}

enum ChekinanaCatalogueIdolAvatarResolver {
    static func prepare(
        _ candidate: ChekinanaEnrichedIdol
    ) async throws -> ChekinanaPreparedIdolCandidate {
        let candidate = try ChekinanaBirthdayValue.normalizedCatalogueCandidate(
            candidate
        )
        guard let identity = ChekinanaIdolAvatarIdentity.make(
            sourceID: candidate.sourceId,
            avatarURL: candidate.avatarUrl
        ),
        let data = try await ChekinanaCatalogueAvatarThumbnailCache.shared
            .thumbnailData(for: candidate),
        !data.isEmpty,
        let image = await ChekinanaImageWorker.thumbnailImage(
            from: data,
            maxDimension: 256
        ) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.missingAvatar
        }
        return ChekinanaPreparedIdolCandidate(
            candidate: candidate,
            avatarThumbnailData: data,
            avatarIdentity: identity,
            avatarThumbnailImage: image
        )
    }

    static func prepareExact(
        sourceID: String,
        query: String
    ) async throws -> ChekinanaPreparedIdolCandidate {
        let results = try await ChekinanaIdolEnrichmentClient().search(for: query)
        guard let exact = results.first(where: { $0.sourceId == sourceID }) else {
            throw ChekinanaCatalogueIdolAvatarLocalizerError.identityMismatch
        }
        return try await prepare(exact)
    }
}

private enum ChekinanaEventListPage: String, CaseIterable, Identifiable {
    case upcoming
    case past

    var id: String { rawValue }
    var title: String {
        switch self {
        case .upcoming: ChekinanaProductCopy.text("events.upcoming", "Upcoming")
        case .past: ChekinanaProductCopy.text("events.past", "Past")
        }
    }
}

enum ChekinanaEventListPresentation {
    static func asciiEllipsis(_ value: String) -> String {
        value.replacingOccurrences(of: "…", with: "...")
    }

    static func remainingDays(
        until eventDate: Date,
        from now: Date,
        calendar: Calendar = .current
    ) -> Int {
        let today = calendar.startOfDay(for: now)
        let eventDay = calendar.startOfDay(for: eventDate)
        return calendar.dateComponents([.day], from: today, to: eventDay).day ?? 0
    }

    static func remainingDaysLabel(_ dayDifference: Int) -> String {
        switch dayDifference {
        case 0:
            ChekinanaProductCopy.text("events.remaining_days.today", "Today")
        case 1:
            ChekinanaProductCopy.text(
                "events.remaining_days.tomorrow",
                "Tomorrow"
            )
        default:
            ChekinanaProductCopy.format(
                "events.remaining_days.future",
                "In %lld days",
                Int64(dayDifference)
            )
        }
    }

    static func displayedCity(_ city: String?) -> String? {
        ChekinanaEventCity.displayed(city)
    }

    static func travelTimelineTitle(departure: String, arrival: String) -> String {
        "\(departure) → \(arrival)"
    }
}

enum ChekinanaTravelTimelinePolicy {
    static func isUpcoming(
        departureTime: Date,
        arrivalTime: Date? = nil,
        from now: Date,
        calendar: Calendar = .current
    ) -> Bool {
        ChekinanaEventListPresentation.remainingDays(
            until: arrivalTime ?? departureTime,
            from: now,
            calendar: calendar
        ) >= 0
    }

    static func remainingDays(
        departureTime: Date,
        arrivalTime: Date,
        from now: Date,
        calendar: Calendar = .current
    ) -> Int {
        let departureDays = ChekinanaEventListPresentation.remainingDays(
            until: departureTime, from: now, calendar: calendar
        )
        if departureDays < 0, isUpcoming(
            departureTime: departureTime, arrivalTime: arrivalTime,
            from: now, calendar: calendar
        ) { return 0 }
        return departureDays
    }

    static func futureSegments(
        _ segments: [TravelSegment],
        from now: Date,
        calendar: Calendar = .current
    ) -> [TravelSegment] {
        segments.filter {
            isUpcoming(
                departureTime: $0.departureTime,
                arrivalTime: $0.arrivalTime,
                from: now,
                calendar: calendar
            )
        }
    }

    @MainActor
    @discardableResult
    static func pruneExpiredSegments(
        _ segments: [TravelSegment],
        from now: Date,
        calendar: Calendar = .current,
        in modelContext: ModelContext
    ) -> Int {
        var deletedCount = 0
        for segment in segments where !isUpcoming(
            departureTime: segment.departureTime,
            arrivalTime: segment.arrivalTime,
            from: now,
            calendar: calendar
        ) {
            do {
                try ChekinanaTravelSegmentPersistence.delete(
                    segment,
                    from: modelContext
                )
                deletedCount += 1
            } catch {
                // Opportunistic cleanup is retried when Events next refreshes.
                continue
            }
        }
        return deletedCount
    }
}

enum ChekinanaEventChekiCount {
    static func visibleRecords(
        _ records: [ChekiRecord],
        eventID: UUID,
        hiddenIDs: Set<UUID>
    ) -> [ChekiRecord] {
        records.filter {
            ChekinanaChekiRecordReadPolicy.isLinked($0, eventID: eventID)
                && ChekinanaChekiRecordReadPolicy.isVisible(
                    $0,
                    hiddenIDs: hiddenIDs
                )
        }
    }

    static func total(
        eventID: UUID,
        mediaChekis: [MediaItem],
        simpleRecords: [ChekiRecord],
        hiddenIDs: Set<UUID>
    ) -> Int {
        let mediaCount = mediaChekis.filter {
            $0.event?.id == eventID
                && ChekinanaVisibilityPolicy.includesRecord(
                    idols: $0.idols,
                    hiddenIDs: hiddenIDs
                )
        }.count
        let simpleCount = ChekinanaChekiRecordStore.totalCount(
            visibleRecords(
                simpleRecords,
                eventID: eventID,
                hiddenIDs: hiddenIDs
            )
        )
        return ChekinanaDisplayCount.adding(mediaCount, simpleCount)
    }
}

private enum ChekinanaEventTimelineEntry: Identifiable {
    case event(Event)
    case travel(TravelSegment)

    var id: String {
        switch self {
        case .event(let event): "event-\(event.id.uuidString.lowercased())"
        case .travel(let segment): "travel-\(segment.id.uuidString.lowercased())"
        }
    }

    var title: String {
        switch self {
        case .event(let event): event.name
        case .travel(let segment):
            ChekinanaEventListPresentation.travelTimelineTitle(
                departure: segment.displayedDepartureLocation,
                arrival: segment.displayedArrivalLocation
            )
        }
    }
}

enum ChekinanaEventRemoteImagePolicy {
    private static let trustedHostFamilies = ["sinaimg.cn", "weibo.cn", "weibocdn.com"]
    private static let trustedExactHosts = ["pbs.twimg.com"]

    static func trustedURL(_ rawURL: String) -> URL? {
        guard let url = URL(string: rawURL) else { return nil }
        return isTrusted(url) ? url : nil
    }

    static func isTrusted(_ url: URL) -> Bool {
        guard url.scheme?.lowercased() == "https",
              let host = url.host?.lowercased(),
              url.user == nil,
              url.password == nil,
              url.fragment == nil else {
            return false
        }
        if host == "api.chekinana.top" {
            guard (url.port == nil || url.port == 443),
                  url.path == "/api/event/x-media",
                  let components = URLComponents(
                      url: url,
                      resolvingAgainstBaseURL: false
                  ),
                  let queryItems = components.queryItems,
                  queryItems.count == 1,
                  queryItems[0].name == "url",
                  let nestedRawValue = queryItems[0].value,
                  !nestedRawValue.isEmpty else {
                return false
            }
            return isCanonicalTwitterMediaURL(nestedRawValue)
        }
        guard url.port == nil else { return false }
        return trustedExactHosts.contains(host)
            || trustedHostFamilies.contains(where: {
                host == $0 || host.hasSuffix(".\($0)")
            })
    }

    private static func isCanonicalTwitterMediaURL(_ rawValue: String) -> Bool {
        guard rawValue == rawValue.trimmingCharacters(
            in: .whitespacesAndNewlines
        ),
        !rawValue.unicodeScalars.contains(where: {
            CharacterSet.controlCharacters.contains($0)
        }),
        let components = URLComponents(string: rawValue),
        components.scheme == "https",
        components.host == "pbs.twimg.com",
        components.user == nil,
        components.password == nil,
        components.port == nil,
        components.fragment == nil,
        !components.path.isEmpty,
        components.path != "/",
        let canonicalURL = components.url,
        canonicalURL.absoluteString == rawValue else {
            return false
        }
        return true
    }
}

final class ChekinanaEventRemoteImageRedirectDelegate: NSObject,
    URLSessionTaskDelegate,
    @unchecked Sendable
{
    typealias TrustEvaluator = @Sendable (URL) -> Bool
    private let trustEvaluator: TrustEvaluator

    init(trustEvaluator: @escaping TrustEvaluator = ChekinanaEventRemoteImagePolicy.isTrusted) {
        self.trustEvaluator = trustEvaluator
    }

    func trustedRedirectRequest(_ request: URLRequest) -> URLRequest? {
        guard let url = request.url, trustEvaluator(url) else { return nil }
        return request
    }

    func urlSession(
        _ session: URLSession,
        task: URLSessionTask,
        willPerformHTTPRedirection response: HTTPURLResponse,
        newRequest request: URLRequest,
        completionHandler: @escaping @Sendable (URLRequest?) -> Void
    ) {
        completionHandler(trustedRedirectRequest(request))
    }
}

actor ChekinanaEventRemoteImageDownloader {
    static let shared = ChekinanaEventRemoteImageDownloader()

    typealias DownloadOperation = @Sendable (URLRequest) async throws -> (URL, URLResponse)

    enum DownloadError: Error, Equatable {
        case untrustedURL
        case invalidResponse
        case invalidContentType
        case emptyBody
        case bodyTooLarge
    }

    /// Matches the existing ImageWorker budget for an in-memory image source.
    static let maximumBodySize = 128 * 1_024 * 1_024
    private let download: DownloadOperation

    init(
        session: URLSession = ChekinanaEventRemoteImageDownloader.makeSession(),
        temporaryDirectory: URL = FileManager.default.temporaryDirectory
    ) {
        download = { request in
            do {
                return try await ChekinanaBoundedImageDownload.download(
                    for: request, session: session, maximumByteCount: Self.maximumBodySize,
                    temporaryDirectory: temporaryDirectory,
                    validateResponse: Self.validateResponse
                )
            } catch ChekinanaBoundedImageDownload.DownloadError.bodyTooLarge {
                throw DownloadError.bodyTooLarge
            }
        }
    }

    init(download: @escaping DownloadOperation) {
        self.download = download
    }

    private static func validateResponse(_ response: URLResponse) throws {
        guard let http = response as? HTTPURLResponse,
              200..<300 ~= http.statusCode,
              let finalURL = response.url,
              ChekinanaEventRemoteImagePolicy.isTrusted(finalURL) else {
            throw DownloadError.invalidResponse
        }
        let contentType = http.value(forHTTPHeaderField: "Content-Type")?
            .split(separator: ";", maxSplits: 1)
            .first?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard contentType?.hasPrefix("image/") == true else {
            throw DownloadError.invalidContentType
        }
    }

    func data(for url: URL) async throws -> Data {
        guard ChekinanaEventRemoteImagePolicy.isTrusted(url) else {
            throw DownloadError.untrustedURL
        }
        try Task.checkCancellation()
        var request = URLRequest(url: url, cachePolicy: .reloadIgnoringLocalAndRemoteCacheData)
        request.timeoutInterval = 12
        request.setValue("image/*", forHTTPHeaderField: "Accept")
        let (temporaryURL, response) = try await download(request)
        defer {
            if !ChekinanaBoundedImageDownload.removeTemporaryFileIfOwned(temporaryURL) {
                try? FileManager.default.removeItem(at: temporaryURL)
            }
        }
        try Task.checkCancellation()
        try Self.validateResponse(response)
        if response.expectedContentLength > Int64(Self.maximumBodySize) {
            throw DownloadError.bodyTooLarge
        }
        let fileSize = try temporaryURL.resourceValues(forKeys: [.fileSizeKey]).fileSize
        guard let fileSize, fileSize > 0 else { throw DownloadError.emptyBody }
        guard fileSize <= Self.maximumBodySize else { throw DownloadError.bodyTooLarge }
        let data = try Data(contentsOf: temporaryURL)
        try Task.checkCancellation()
        guard !data.isEmpty else { throw DownloadError.emptyBody }
        guard data.count <= Self.maximumBodySize else { throw DownloadError.bodyTooLarge }
        return data
    }

    private static func makeSession() -> URLSession {
        let configuration = URLSessionConfiguration.ephemeral
        configuration.timeoutIntervalForRequest = 12
        configuration.timeoutIntervalForResource = 12
        configuration.waitsForConnectivity = false
        configuration.httpMaximumConnectionsPerHost = 3
        configuration.urlCache = nil
        configuration.requestCachePolicy = .reloadIgnoringLocalAndRemoteCacheData
        configuration.httpCookieStorage = nil
        configuration.httpShouldSetCookies = false
        configuration.connectionProxyDictionary =
            ChekinanaCatalogueNetworkPolicy.directConnectionProxyDictionary()
        return URLSession(
            configuration: configuration,
            delegate: ChekinanaEventRemoteImageRedirectDelegate(),
            delegateQueue: nil
        )
    }
}

/// Owns files staged by the shared Event/Travel media path until the database
/// save that references them has committed. Ownership is deliberately
/// generation-scoped and has no clock or TTL: a backgrounded editor, a photo
/// picker, or a cross-day suspension must not make a live draft collectible.
enum ChekinanaEventTravelMediaOwnership {
    private struct Record: Codable, Hashable {
        let reference: String
        let ownerID: UUID
        let processID: UUID
        let generation: UUID
        let kind: String
    }

    private static let key = "chekinana.event-travel-media.ownership.v1"
    private static let lock = NSLock()
    private static let processID = UUID()
    private nonisolated(unsafe) static var activeOwnerIDs = Set<UUID>()

    static func beginDraftSession(
        ownerID: UUID,
        generation: UUID,
        defaults: UserDefaults = .standard
    ) {
        lock.lock()
        defer { lock.unlock() }
        activeOwnerIDs.insert(ownerID)
        // The session itself is kept in memory. Individual files are added to
        // the durable record only after they have been atomically staged.
        _ = generation
        _ = defaults
    }

    static func beginSaveTask(
        ownerID: UUID,
        generation: UUID,
        references: [String],
        defaults: UserDefaults = .standard
    ) {
        lock.lock()
        defer { lock.unlock() }
        activeOwnerIDs.insert(ownerID)
        var records = load(defaults: defaults)
        records = records.filter { $0.ownerID != ownerID }
        records.append(contentsOf: references.filter(ChekinanaEventMediaJournal.isManaged).map {
            Record(
                reference: $0,
                ownerID: ownerID,
                processID: processID,
                generation: generation,
                kind: "save"
            )
        })
        store(records, defaults: defaults)
    }

    static func retain(
        _ references: [String],
        ownerID: UUID,
        generation: UUID,
        kind: String = "draft",
        defaults: UserDefaults = .standard
    ) {
        let managed = references.filter(ChekinanaEventMediaJournal.isManaged)
        guard !managed.isEmpty else { return }
        lock.lock()
        defer { lock.unlock() }
        activeOwnerIDs.insert(ownerID)
        var records = load(defaults: defaults)
        records.removeAll { $0.ownerID == ownerID && managed.contains($0.reference) }
        records.append(contentsOf: managed.map {
            Record(
                reference: $0,
                ownerID: ownerID,
                processID: processID,
                generation: generation,
                kind: kind
            )
        })
        store(records, defaults: defaults)
    }

    static func transfer(
        _ references: [String],
        from sourceOwnerID: UUID,
        to targetOwnerID: UUID,
        generation: UUID,
        defaults: UserDefaults = .standard
    ) {
        let managed = Set(references.filter(ChekinanaEventMediaJournal.isManaged))
        guard !managed.isEmpty else { return }
        lock.lock()
        defer { lock.unlock() }
        activeOwnerIDs.insert(targetOwnerID)
        var records = load(defaults: defaults)
        records.removeAll {
            $0.ownerID == sourceOwnerID && managed.contains($0.reference)
        }
        records.removeAll {
            $0.ownerID == targetOwnerID && managed.contains($0.reference)
        }
        records.append(contentsOf: managed.map {
            Record(
                reference: $0,
                ownerID: targetOwnerID,
                processID: processID,
                generation: generation,
                kind: "save"
            )
        })
        store(records, defaults: defaults)
    }

    static func release(
        ownerID: UUID,
        defaults: UserDefaults = .standard
    ) {
        lock.lock()
        defer { lock.unlock() }
        activeOwnerIDs.remove(ownerID)
        var records = load(defaults: defaults)
        records.removeAll { $0.ownerID == ownerID }
        store(records, defaults: defaults)
    }

    static func protectedReferences(
        defaults: UserDefaults = .standard
    ) -> Set<String> {
        lock.lock()
        defer { lock.unlock() }
        let active = activeOwnerIDs
        return Set(load(defaults: defaults).filter {
            $0.processID == processID && active.contains($0.ownerID)
        }.map(\.reference))
    }

    /// Called once before the first editor is created. A persisted owner from
    /// another process is a lost owner only at this process boundary; there is
    /// no wall-clock expiration. The launch path has no active editor yet, so
    /// stale owners can be safely reconciled before pending cleanup.
    static func reconcileAfterProcessRestart(
        currentGeneration: UUID? = nil,
        defaults: UserDefaults = .standard
    ) {
        lock.lock()
        defer { lock.unlock() }
        let current = load(defaults: defaults).filter {
            $0.processID == processID
                && (currentGeneration == nil || $0.generation == currentGeneration)
        }
        store(current, defaults: defaults)
    }

    @MainActor
    static func currentGeneration(in modelContext: ModelContext) -> UUID? {
        try? ChekinanaPersistenceMutationCoordinator.withLock {
            try ChekinanaLibraryGenerationStore.ensureCurrent(in: modelContext)
        }
    }

    enum SaveAuthorizationError: LocalizedError, Equatable {
        case generationChanged
        case ownerUnavailable
        case referencesNotOwned

        var errorDescription: String? {
            switch self {
            case .generationChanged:
                ChekinanaL10n.message("The library changed while this editor was open. Reopen the draft and try again.")
            case .ownerUnavailable:
                ChekinanaL10n.message("This save task is no longer active. Reopen the draft and try again.")
            case .referencesNotOwned:
                ChekinanaL10n.message("A staged image is no longer owned by this save task. Reopen the draft and try again.")
            }
        }
    }

    @MainActor
    static func validateSaveAuthorization(
        ownerID: UUID,
        expectedGeneration: UUID,
        ownedReferences: [String],
        in modelContext: ModelContext
    ) throws {
        guard try ChekinanaLibraryGenerationStore.current(in: modelContext)
                == expectedGeneration else {
            throw SaveAuthorizationError.generationChanged
        }
        let required = Set(ownedReferences.filter(ChekinanaEventMediaJournal.isManaged))
        lock.lock()
        defer { lock.unlock() }
        guard activeOwnerIDs.contains(ownerID) else {
            throw SaveAuthorizationError.ownerUnavailable
        }
        let records = Set(load(defaults: .standard).filter {
            $0.processID == processID
                && $0.ownerID == ownerID
                && $0.generation == expectedGeneration
        }.map(\.reference))
        guard required.isSubset(of: records) else {
            throw SaveAuthorizationError.referencesNotOwned
        }
    }

    private static func load(defaults: UserDefaults) -> [Record] {
        guard let data = defaults.data(forKey: key),
              let records = try? JSONDecoder().decode([Record].self, from: data) else {
            return []
        }
        return records
    }

    private static func store(_ records: [Record], defaults: UserDefaults) {
        guard !records.isEmpty else {
            defaults.removeObject(forKey: key)
            return
        }
        if let data = try? JSONEncoder().encode(records) {
            defaults.set(data, forKey: key)
        }
    }
}

/// One filename contract for imported and locally staged Event/Travel images.
/// Historical backup names remain readable without rewriting their DB rows.
/// They may be collected only through the fresh-library-witness cleanup path.
enum ChekinanaEventMediaReference {
    enum Kind: Equatable { case avatar, image }

    struct Parsed: Equatable {
        let kind: Kind
        let isLegacyBackup: Bool
        let fileExtension: String

        var permitsImmediateDiscard: Bool {
            !isLegacyBackup && fileExtension == "jpg"
        }
    }

    private static let imageExtensions: Set<String> = [
        "jpg", "jpeg", "png", "heic", "heif", "webp", "gif", "tif", "tiff", "bmp",
    ]

    static func parse(_ reference: String) -> Parsed? {
        guard reference == URL(fileURLWithPath: reference).lastPathComponent else {
            return nil
        }
        let value = reference.lowercased()
        let url = URL(fileURLWithPath: value)
        let ext = url.pathExtension
        guard imageExtensions.contains(ext) else { return nil }
        let stem = url.deletingPathExtension().lastPathComponent
        let prefixes: [(String, Kind, Bool)] = [
            ("event-avatar-", .avatar, false),
            ("event-image-", .image, false),
            ("backup-event-image-", .image, true),
            ("backup-event-", .avatar, true),
            ("backup-travel-", .avatar, true),
        ]
        for (prefix, kind, legacy) in prefixes where stem.hasPrefix(prefix) {
            let suffix = String(stem.dropFirst(prefix.count))
            if legacy {
                guard suffix.count == 36, UUID(uuidString: suffix) != nil else { return nil }
            } else {
                guard suffix.count == 73,
                      suffix[suffix.index(suffix.startIndex, offsetBy: 36)] == "-",
                      UUID(uuidString: String(suffix.prefix(36))) != nil,
                      UUID(uuidString: String(suffix.suffix(36))) != nil else { return nil }
            }
            return Parsed(kind: kind, isLegacyBackup: legacy, fileExtension: ext)
        }
        return nil
    }

    static func importedFilename(
        kind: Kind,
        ownerID: UUID,
        originalReference: String
    ) throws -> String {
        let ext = URL(fileURLWithPath: originalReference).pathExtension.lowercased()
        guard imageExtensions.contains(ext) else {
            throw ChekinanaDataImportError.mediaIntegrity
        }
        let prefix = kind == .avatar ? "event-avatar" : "event-image"
        return "\(prefix)-\(ownerID.uuidString.lowercased())-\(UUID().uuidString.lowercased()).\(ext)"
    }

    static func localFileURL(for reference: String, directory: URL) -> URL? {
        guard parse(reference) != nil else { return nil }
        let root = directory.standardizedFileURL
        let url = root.appendingPathComponent(reference).standardizedFileURL
        guard url.deletingLastPathComponent() == root,
              let values = try? url.resourceValues(forKeys: [
                .isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey,
              ]),
              values.isRegularFile == true,
              values.isSymbolicLink != true,
              (values.fileSize ?? 0) > 0,
              FileManager.default.isReadableFile(atPath: url.path) else { return nil }
        return url
    }
}

enum ChekinanaEventMediaJournal {
    private static let pendingKey = "chekinana.event-media.pending.v1"
    private static let deletionKey = "chekinana.event-media.deletion.v1"
    private static let lock = NSLock()

    static func recordPending(_ ref: String, defaults: UserDefaults = .standard) {
        update(key: pendingKey, adding: [ref], removing: [], defaults: defaults)
    }

    static func clearPending(_ refs: [String], defaults: UserDefaults = .standard) {
        update(key: pendingKey, adding: [], removing: refs, defaults: defaults)
    }

    static func queueDeletion(_ refs: [String], defaults: UserDefaults = .standard) {
        update(key: deletionKey, adding: refs, removing: [], defaults: defaults)
    }

    static func cancelDeletion(_ refs: [String], defaults: UserDefaults = .standard) {
        update(key: deletionKey, adding: [], removing: refs, defaults: defaults)
    }

    static func discardPending(
        _ refs: [String],
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        removeItem: (URL) throws -> Void = { try FileManager.default.removeItem(at: $0) }
    ) {
        recoverQueue(
            key: pendingKey,
            referencedRefs: [],
            limitedTo: Set(refs),
            directory: directory,
            defaults: defaults,
            removeItem: removeItem
        )
    }

    static func recover(
        modelContext: ModelContext,
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        removeItem: (URL) throws -> Void = { try FileManager.default.removeItem(at: $0) }
    ) throws {
        let eventRefs = try modelContext.fetch(FetchDescriptor<Event>())
            .compactMap(\.avatarImageRef)
        let travelRefs = try modelContext.fetch(FetchDescriptor<TravelSegment>())
            .compactMap(\.operatorIconRef)
        let imageRefs = try modelContext.fetch(FetchDescriptor<EventImage>())
            .map(\.imageRef)
        recover(
            referencedRefs: Set(eventRefs + travelRefs + imageRefs),
            directory: directory,
            defaults: defaults,
            removeItem: removeItem
        )
    }

    static func recover(
        referencedRefs: Set<String>,
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        removeItem: (URL) throws -> Void = { try FileManager.default.removeItem(at: $0) }
    ) {
        recoverQueue(
            key: pendingKey,
            referencedRefs: referencedRefs,
            limitedTo: nil,
            directory: directory,
            defaults: defaults,
            removeItem: removeItem
        )
        recoverQueue(
            key: deletionKey,
            referencedRefs: referencedRefs,
            limitedTo: nil,
            directory: directory,
            defaults: defaults,
            removeItem: removeItem
        )
    }

    static func pendingRefs(defaults: UserDefaults = .standard) -> Set<String> {
        Set(defaults.stringArray(forKey: pendingKey) ?? [])
    }

    static func deletionRefs(defaults: UserDefaults = .standard) -> Set<String> {
        Set(defaults.stringArray(forKey: deletionKey) ?? [])
    }

    @MainActor
    static func scheduleSafeCleanup(in modelContext: ModelContext) {
        Task { @MainActor in
            _ = await ChekinanaLibraryQueueReconciler.cleanupOrdinaryQueues(
                in: modelContext,
                recoverEventPending: false
            )
        }
    }

    /// A successful full-library replacement makes both Event queues belong to
    /// the previous generation. References committed by the new generation
    /// cancel either old intent; unreferenced entries remain actionable and are
    /// retried by ordinary cleanup.
    @MainActor
    @discardableResult
    static func reconcileAfterCommittedImport(
        referencedRefs: Set<String>,
        defaults: UserDefaults = .standard
    ) -> Int {
        lock.lock()
        defer { lock.unlock() }
        guard let pending = strictQueue(key: pendingKey, defaults: defaults),
              let deletion = strictQueue(key: deletionKey, defaults: defaults) else {
            return 1
        }
        setQueue(
            Set(pending.filter(isManaged)).subtracting(referencedRefs),
            key: pendingKey,
            defaults: defaults
        )
        setQueue(
            Set(deletion.filter(isManaged)).subtracting(referencedRefs),
            key: deletionKey,
            defaults: defaults
        )
        return 0
    }

    /// Cleans Event pending/deletion entries using a per-file validator that
    /// re-reads the current library witness and references before unlink.
    @MainActor
    @discardableResult
    static func cleanupSafely(
        referencedRefs: Set<String>,
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        includePending: Bool = true,
        removeCandidate: (URL, String, ChekinanaImportFileIdentity) -> Bool
    ) -> Int {
        let resolvedDirectory: URL
        do {
            resolvedDirectory = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        } catch {
            return 1
        }
        var deferred = 0
        let keys = includePending ? [pendingKey, deletionKey] : [deletionKey]
        let protected = ChekinanaEventTravelMediaOwnership
            .protectedReferences(defaults: defaults)
        for key in keys {
            lock.lock()
            guard let queued = strictQueue(key: key, defaults: defaults) else {
                lock.unlock()
                deferred += 1
                continue
            }
            lock.unlock()

            var remaining = Set<String>()
            for ref in queued {
                guard isManaged(ref) else { continue }
                guard !protected.contains(ref) else {
                    remaining.insert(ref)
                    continue
                }
                guard !referencedRefs.contains(ref) else { continue }
                let url = resolvedDirectory.appendingPathComponent(ref)
                guard FileManager.default.fileExists(atPath: url.path) else { continue }
                guard let values = try? url.resourceValues(forKeys: [
                        .isRegularFileKey, .isSymbolicLinkKey,
                      ]),
                      values.isRegularFile == true,
                      values.isSymbolicLink != true,
                      let identity = try? ChekinanaImportFileIdentity.inspect(url),
                      removeCandidate(url, ref, identity) else {
                    remaining.insert(ref)
                    deferred += 1
                    continue
                }
            }
            let processed = queued.subtracting(remaining)
            lock.lock()
            if var current = strictQueue(key: key, defaults: defaults) {
                current.subtract(processed)
                setQueue(current, key: key, defaults: defaults)
            } else {
                deferred += 1
            }
            lock.unlock()
        }
        return deferred
    }

    static func isManaged(_ ref: String) -> Bool {
        ChekinanaEventMediaReference.parse(ref) != nil
    }

    static func validateManagedFiles(_ refs: [String]) throws {
        let managed = refs.filter { ChekinanaTravelOperatorIcon.assetName(from: $0) == nil }
        guard !managed.isEmpty else { return }
        let directory = try ChekiImageRefResolver.chekiImagesDirectory()
        for ref in managed {
            guard ChekinanaEventMediaReference.localFileURL(
                for: ref, directory: directory
            ) != nil else {
                throw ChekinanaEventMediaPersistenceError.missingFile(ref)
            }
        }
    }

    private static func update(
        key: String,
        adding: [String],
        removing: [String],
        defaults: UserDefaults
    ) {
        lock.lock()
        defer { lock.unlock() }
        var values = Set(defaults.stringArray(forKey: key) ?? [])
        values.formUnion(adding.filter(isManaged))
        values.subtract(removing)
        if values.isEmpty {
            defaults.removeObject(forKey: key)
        } else {
            defaults.set(values.sorted(), forKey: key)
        }
    }

    private static func strictQueue(
        key: String,
        defaults: UserDefaults
    ) -> Set<String>? {
        guard defaults.object(forKey: key) != nil else { return [] }
        guard let values = defaults.stringArray(forKey: key) else { return nil }
        return Set(values)
    }

    private static func setQueue(
        _ values: Set<String>,
        key: String,
        defaults: UserDefaults
    ) {
        if values.isEmpty {
            defaults.removeObject(forKey: key)
        } else {
            defaults.set(values.sorted(), forKey: key)
        }
    }

    private static func recoverQueue(
        key: String,
        referencedRefs: Set<String>,
        limitedTo: Set<String>?,
        directory: URL?,
        defaults: UserDefaults,
        removeItem: (URL) throws -> Void
    ) {
        let resolvedDirectory: URL
        do {
            resolvedDirectory = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        } catch {
            return
        }
        lock.lock()
        let queued = Set(defaults.stringArray(forKey: key) ?? [])
        lock.unlock()
        var remaining = queued
        for ref in queued where limitedTo?.contains(ref) ?? true {
            guard isManaged(ref) else {
                remaining.remove(ref)
                continue
            }
            // Compatibility names and byte-preserving imported formats were
            // never owned by this direct pending-file remover. Leave their
            // intent for cleanupSafely, whose production caller rechecks the
            // committed generation, all current references and exact identity.
            guard ChekinanaEventMediaReference.parse(ref)?.permitsImmediateDiscard == true else {
                continue
            }
            guard !referencedRefs.contains(ref) else {
                remaining.remove(ref)
                continue
            }
            let url = resolvedDirectory.appendingPathComponent(ref)
            guard FileManager.default.fileExists(atPath: url.path) else {
                remaining.remove(ref)
                continue
            }
            guard ChekinanaEventMediaReference.localFileURL(
                for: ref, directory: resolvedDirectory
            ) != nil else { continue }
            do {
                try removeItem(url)
                remaining.remove(ref)
            } catch {
                continue
            }
        }
        lock.lock()
        var current = Set(defaults.stringArray(forKey: key) ?? [])
        current.subtract(queued.subtracting(remaining))
        if current.isEmpty {
            defaults.removeObject(forKey: key)
        } else {
            defaults.set(current.sorted(), forKey: key)
        }
        lock.unlock()
    }
}

enum ChekinanaEventMediaPersistenceError: LocalizedError, Equatable {
    case missingFile(String)

    var errorDescription: String? {
        switch self {
        case .missingFile(let reference):
            return ChekinanaL10n.message("The staged Event/Travel image is unavailable (\(reference)). Keep the draft and try again.")
        }
    }
}

enum ChekinanaEventAvatarStore {

    static func save(
        _ data: Data,
        eventID: UUID,
        ownerID: UUID? = nil,
        generation: UUID? = nil
    ) async throws -> String {
        let filename = "event-avatar-\(eventID.uuidString.lowercased())-\(UUID().uuidString.lowercased()).jpg"
        if let ownerID, let generation {
            ChekinanaEventTravelMediaOwnership.retain(
                [filename], ownerID: ownerID, generation: generation
            )
        }
        ChekinanaEventMediaJournal.recordPending(filename)
        do {
            guard let jpeg = await ChekinanaImageWorker.downsampledJPEGData(
                from: data,
                maxDimension: 512,
                compressionQuality: 0.9
            ), !jpeg.isEmpty else {
                throw ChekinanaProductMediaError.unreadableImage
            }
            let directory = try ChekiImageRefResolver.chekiImagesDirectory()
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try jpeg.write(to: directory.appendingPathComponent(filename), options: .atomic)
            return filename
        } catch {
            ChekinanaEventMediaJournal.discardPending([filename])
            throw error
        }
    }

    static func downloadAndSave(
        _ rawURL: String,
        eventID: UUID,
        ownerID: UUID? = nil,
        generation: UUID? = nil
    ) async throws -> String {
        guard let url = trustedRemoteURL(rawURL) else {
            throw ChekinanaProductMediaError.unreadableImage
        }
        let data = try await ChekinanaEventRemoteImageDownloader.shared.data(for: url)
        return try await save(
            data,
            eventID: eventID,
            ownerID: ownerID,
            generation: generation
        )
    }

#if DEBUG
    static func saveUIFixtureAvatar(
        eventID: UUID,
        ownerID: UUID? = nil,
        generation: UUID? = nil
    ) async throws -> String {
        let format = UIGraphicsImageRendererFormat.default()
        format.scale = 1
        format.opaque = true
        let image = UIGraphicsImageRenderer(
            size: CGSize(width: 96, height: 96),
            format: format
        ).image { context in
            UIColor(red: 0.94, green: 0.92, blue: 0.97, alpha: 1).setFill()
            context.fill(CGRect(x: 0, y: 0, width: 96, height: 96))
            UIColor(red: 0.31, green: 0.20, blue: 0.48, alpha: 1).setFill()
            context.cgContext.fillEllipse(in: CGRect(x: 24, y: 18, width: 48, height: 48))
        }
        guard let data = image.jpegData(compressionQuality: 0.9) else {
            throw ChekinanaProductMediaError.unreadableImage
        }
        return try await save(
            data,
            eventID: eventID,
            ownerID: ownerID,
            generation: generation
        )
    }
#endif

    static func trustedRemoteURL(_ rawURL: String) -> URL? {
        ChekinanaEventRemoteImagePolicy.trustedURL(rawURL)
    }

    static func image(for ref: String?) -> UIImage? {
        if let assetName = ChekinanaTravelOperatorIcon.assetName(from: ref) {
            return UIImage(named: assetName)
        }
        guard let ref, isManaged(ref),
              let directory = try? ChekiImageRefResolver.chekiImagesDirectory(),
              let url = ChekinanaEventMediaReference.localFileURL(
                for: ref, directory: directory
              ) else { return nil }
        return UIImage(contentsOfFile: url.path)
    }

    static func remove(_ ref: String?) {
        guard let ref, isManaged(ref) else { return }
        ChekinanaEventMediaJournal.discardPending([ref])
    }

    static func isManaged(_ ref: String) -> Bool {
        ChekinanaEventMediaReference.parse(ref)?.kind == .avatar
    }
}

enum ChekinanaEventImageStore {
    static let maximumImageCount = 12
    static let maximumConcurrentDownloads = 3

    typealias RemoteFetcher = @Sendable (URL) async throws -> Data
    typealias StagedObserver = @Sendable (Int, String) async -> Void

    static func save(
        _ data: Data,
        eventID: UUID,
        ownerID: UUID? = nil,
        generation: UUID? = nil
    ) async throws -> String {
        let filename = "event-image-\(eventID.uuidString.lowercased())-\(UUID().uuidString.lowercased()).jpg"
        if let ownerID, let generation {
            ChekinanaEventTravelMediaOwnership.retain(
                [filename], ownerID: ownerID, generation: generation
            )
        }
        ChekinanaEventMediaJournal.recordPending(filename)
        do {
            guard let jpeg = await ChekinanaImageWorker.downsampledJPEGData(
                from: data,
                maxDimension: 2_048,
                compressionQuality: 0.9
            ), !jpeg.isEmpty else {
                throw ChekinanaProductMediaError.unreadableImage
            }
            let directory = try ChekiImageRefResolver.chekiImagesDirectory()
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            try jpeg.write(to: directory.appendingPathComponent(filename), options: .atomic)
            return filename
        } catch {
            ChekinanaEventMediaJournal.discardPending([filename])
            throw error
        }
    }

    static func stageRemoteImages(
        _ rawURLs: [String],
        eventID: UUID,
        ownerID: UUID? = nil,
        generation: UUID? = nil,
        fetch: @escaping RemoteFetcher = fetchRemoteImage,
        onStaged: @escaping StagedObserver = { _, _ in }
    ) async throws -> [String?] {
        let boundedURLs = Array(rawURLs.prefix(maximumImageCount))
        var orderedRefs = Array<String?>(repeating: nil, count: boundedURLs.count)
        do {
            for start in stride(
                from: 0,
                to: boundedURLs.count,
                by: maximumConcurrentDownloads
            ) {
                try Task.checkCancellation()
                let end = min(start + maximumConcurrentDownloads, boundedURLs.count)
                await withTaskGroup(of: (Int, String?).self) { group in
                    for index in start..<end {
                        guard let url = ChekinanaEventAvatarStore.trustedRemoteURL(
                            boundedURLs[index]
                        ) else { continue }
                        group.addTask {
                            do {
                                let data = try await fetch(url)
                                try Task.checkCancellation()
                                return (
                                    index,
                                    try await save(
                                        data,
                                        eventID: eventID,
                                        ownerID: ownerID,
                                        generation: generation
                                    )
                                )
                            } catch {
                                return (index, nil)
                            }
                        }
                    }
                    for await (index, ref) in group {
                        orderedRefs[index] = ref
                        if let ref { await onStaged(index, ref) }
                    }
                }
            }
            try Task.checkCancellation()
            return orderedRefs
        } catch {
            remove(orderedRefs.compactMap { $0 })
            throw error
        }
    }

    static func image(for ref: String) -> UIImage? {
        guard isManaged(ref),
              let directory = try? ChekiImageRefResolver.chekiImagesDirectory(),
              let url = ChekinanaEventMediaReference.localFileURL(
                for: ref, directory: directory
              ) else { return nil }
        return UIImage(contentsOfFile: url.path)
    }

    static func remove(_ refs: [String]) {
        ChekinanaEventMediaJournal.discardPending(refs.filter(isManaged))
    }

    static func isManaged(_ ref: String) -> Bool {
        ChekinanaEventMediaReference.parse(ref)?.kind == .image
    }

    private static func fetchRemoteImage(_ url: URL) async throws -> Data {
        try await ChekinanaEventRemoteImageDownloader.shared.data(for: url)
    }
}

struct ChekinanaEventImageValue: Equatable, Sendable {
    let id: UUID?
    let imageRef: String
}

@MainActor
enum ChekinanaEventPersistence {
    enum PersistenceError: LocalizedError {
        case invalidImages

        var errorDescription: String? {
            switch self {
            case .invalidImages:
                ChekinanaL10n.message("The Event images are invalid.")
            }
        }
    }

    static func images(
        for eventID: UUID,
        in modelContext: ModelContext
    ) throws -> [EventImage] {
        try modelContext.fetch(FetchDescriptor<EventImage>(
            predicate: #Predicate { $0.eventID == eventID },
            sortBy: [SortDescriptor(\EventImage.sortOrder)]
        ))
    }

    static func imageValues(
        for eventID: UUID,
        in modelContext: ModelContext,
        directory: URL? = nil
    ) throws -> [ChekinanaEventImageValue] {
        let records = try images(for: eventID, in: modelContext)
        guard !records.isEmpty else { return [] }
        let resolvedDirectory = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        guard records.allSatisfy({
            ChekinanaEventImageStore.isManaged($0.imageRef)
                && ChekinanaEventMediaReference.localFileURL(
                    for: $0.imageRef, directory: resolvedDirectory
                ) != nil
        }) else {
            // Never turn an unreadable persisted association into an omitted
            // draft that a later text-only save would interpret as deletion.
            throw PersistenceError.invalidImages
        }
        return records.map { .init(id: $0.id, imageRef: $0.imageRef) }
    }

    static func save(
        _ event: Event,
        inserting: Bool,
        expectedUpdatedAt: Date? = nil,
        images values: [ChekinanaEventImageValue],
        schedule: ChekinanaEventScheduleValue? = nil,
        source: ChekinanaEventSource? = nil,
        previousAvatarRef: String?,
        in modelContext: ModelContext,
        saveContext: (ModelContext) throws -> Void = { try $0.save() },
        validateManagedFiles: Bool = false,
        expectedGeneration: UUID? = nil,
        mediaOwnerID: UUID? = nil,
        mediaOwnerReferences: [String] = [],
        apply: (Event) -> Void = { _ in }
    ) throws {
        let refs = values.map(\.imageRef)
        guard values.count <= ChekinanaEventImageStore.maximumImageCount,
              Set(refs).count == refs.count,
              refs.allSatisfy(ChekinanaEventImageStore.isManaged) else {
            throw PersistenceError.invalidImages
        }
        var committedAvatarRef: String?
        var deletionRefs: [String] = []
        try ChekinanaLibraryMutationProtocol.withExclusiveOperationSync {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(in: modelContext)
            try ChekinanaPersistenceMutationCoordinator.withLock {
            do {
                if let mediaOwnerID, let expectedGeneration {
                    try ChekinanaEventTravelMediaOwnership.validateSaveAuthorization(
                        ownerID: mediaOwnerID,
                        expectedGeneration: expectedGeneration,
                        ownedReferences: mediaOwnerReferences,
                        in: modelContext
                    )
                } else if validateManagedFiles {
                    throw ChekinanaEventTravelMediaOwnership
                        .SaveAuthorizationError.ownerUnavailable
                }
                let liveEvent: Event
                let eventID = event.id
                if inserting {
                    let matches = try modelContext.fetch(FetchDescriptor<Event>(
                        predicate: #Predicate { $0.id == eventID }
                    ))
                    guard matches.isEmpty else {
                        throw ChekinanaEventMutationError.changedOrMissingEvent
                    }
                    modelContext.insert(event)
                    liveEvent = event
                } else {
                    let authoritativeUpdatedAt = try
                        ChekinanaEventSchedulePersistence.persistedEventUpdatedAtLocked(
                            eventID: event.id,
                            from: modelContext
                        )
                    let matches = try modelContext.fetch(FetchDescriptor<Event>(
                        predicate: #Predicate { $0.id == eventID }
                    ))
                    guard matches.count == 1,
                          expectedUpdatedAt == nil
                            || authoritativeUpdatedAt == expectedUpdatedAt else {
                        throw ChekinanaEventMutationError.changedOrMissingEvent
                    }
                    liveEvent = matches[0]
                }
                apply(liveEvent)
                if validateManagedFiles {
                    try ChekinanaEventMediaJournal.validateManagedFiles(
                        refs + [liveEvent.avatarImageRef].compactMap { $0 }
                    )
                }
                liveEvent.date = try ChekinanaPersistedContentDatePolicy
                    .validatedCanonical(liveEvent.date)
                liveEvent.source = source

                let existing = try images(for: liveEvent.id, in: modelContext)
                let existingByID = Dictionary(uniqueKeysWithValues: existing.map { ($0.id, $0) })
                var retainedIDs = Set<UUID>()
                for (sortOrder, value) in values.enumerated() {
                    if let id = value.id,
                       let record = existingByID[id],
                       record.eventID == liveEvent.id {
                        if record.imageRef != value.imageRef { record.imageRef = value.imageRef }
                        if record.sortOrder != sortOrder { record.sortOrder = sortOrder }
                        retainedIDs.insert(id)
                    } else {
                        let record = EventImage(
                            eventID: liveEvent.id,
                            imageRef: value.imageRef,
                            sortOrder: sortOrder
                        )
                        modelContext.insert(record)
                        retainedIDs.insert(record.id)
                    }
                }
                for record in existing where !retainedIDs.contains(record.id) {
                    modelContext.delete(record)
                }
                if let schedule {
                    try ChekinanaEventSchedulePersistence.applyLocked(
                        eventID: liveEvent.id,
                        openTime: schedule.openTime,
                        startTime: schedule.startTime,
                        in: modelContext
                    )
                }

                let retainedRefs = Set(refs)
                deletionRefs = existing.map(\.imageRef)
                    .filter { !retainedRefs.contains($0) }
                if let previousAvatarRef,
                   previousAvatarRef != liveEvent.avatarImageRef,
                   ChekinanaEventAvatarStore.isManaged(previousAvatarRef) {
                    deletionRefs.append(previousAvatarRef)
                }
                ChekinanaEventMediaJournal.queueDeletion(deletionRefs)
                if let mediaOwnerID, let expectedGeneration {
                    try ChekinanaEventTravelMediaOwnership.validateSaveAuthorization(
                        ownerID: mediaOwnerID,
                        expectedGeneration: expectedGeneration,
                        ownedReferences: mediaOwnerReferences,
                        in: modelContext
                    )
                } else if validateManagedFiles {
                    throw ChekinanaEventTravelMediaOwnership
                        .SaveAuthorizationError.ownerUnavailable
                }
                try saveContext(modelContext)
                committedAvatarRef = liveEvent.avatarImageRef
            } catch {
                modelContext.rollback()
                ChekinanaEventMediaJournal.cancelDeletion(deletionRefs)
                throw error
            }
            }
        }
        ChekinanaEventMediaJournal.clearPending(
            refs + [committedAvatarRef].compactMap { $0 }
        )
        if let mediaOwnerID {
            ChekinanaEventTravelMediaOwnership.release(ownerID: mediaOwnerID)
        }
        ChekinanaEventMediaJournal.scheduleSafeCleanup(in: modelContext)
    }

    @discardableResult
    static func update(
        eventID: UUID,
        expectedUpdatedAt: Date,
        schedule: ChekinanaEventScheduleValue? = nil,
        sourceUpdate: ChekinanaEventSource?? = nil,
        in modelContext: ModelContext,
        saveContext: (ModelContext) throws -> Void = { try $0.save() },
        apply: (Event) -> Void
    ) throws -> Event {
        try ChekinanaPersistenceMutationCoordinator.withLock {
            do {
                let authoritativeUpdatedAt = try
                    ChekinanaEventSchedulePersistence.persistedEventUpdatedAtLocked(
                        eventID: eventID,
                        from: modelContext
                    )
                let matches = try modelContext.fetch(FetchDescriptor<Event>())
                    .filter { $0.id == eventID }
                guard matches.count == 1,
                      authoritativeUpdatedAt == expectedUpdatedAt else {
                    throw ChekinanaEventMutationError.changedOrMissingEvent
                }
                let liveEvent = matches[0]
                apply(liveEvent)
                liveEvent.date = try ChekinanaPersistedContentDatePolicy
                    .validatedCanonical(liveEvent.date)
                if let schedule {
                    try ChekinanaEventSchedulePersistence.applyLocked(
                        eventID: eventID,
                        openTime: schedule.openTime,
                        startTime: schedule.startTime,
                        in: modelContext
                    )
                }
                if let sourceUpdate {
                    liveEvent.source = sourceUpdate
                }
                try saveContext(modelContext)
                return liveEvent
            } catch {
                modelContext.rollback()
                throw error
            }
        }
    }

    static func delete(
        _ event: Event,
        from modelContext: ModelContext,
        editIntentDirectory: URL? = nil,
        saveContext: (ModelContext) throws -> Void = { try $0.save() }
    ) throws {
        try delete(
            eventID: event.id,
            from: modelContext,
            editIntentDirectory: editIntentDirectory,
            saveContext: saveContext
        )
    }

    static func delete(
        eventID: UUID,
        from modelContext: ModelContext,
        editIntentDirectory: URL? = nil,
        saveContext: (ModelContext) throws -> Void = { try $0.save() }
    ) throws {
        try ChekinanaLibraryMutationProtocol.withExclusiveOperationSync {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: editIntentDirectory
            )
            try ChekinanaPersistenceMutationCoordinator.withLock {
                try ChekinanaChekiEditRecovery.requireConvergedExclusively(
                    in: modelContext,
                    directory: editIntentDirectory
                )
                var deletionRefs: [String] = []
                do {
                _ = try ChekinanaEventSchedulePersistence
                    .persistedEventUpdatedAtLocked(
                        eventID: eventID,
                        from: modelContext
                    )
                let eventMatches = try modelContext.fetch(FetchDescriptor<Event>())
                    .filter { $0.id == eventID }
                guard eventMatches.count == 1 else {
                    throw ChekinanaEventMutationError.changedOrMissingEvent
                }
                let liveEvent = eventMatches[0]
                for mediaItem in try modelContext.fetch(
                    FetchDescriptor<MediaItem>()
                ) where mediaItem.eventID == eventID {
                    mediaItem.event = nil
                    mediaItem.updatedAt = Date()
                }
                for record in try modelContext.fetch(
                    FetchDescriptor<ChekiRecord>()
                ) where record.eventID == eventID {
                    record.event = nil
                }
                for memory in try modelContext.fetch(FetchDescriptor<Memory>())
                where memory.eventID == eventID {
                    memory.eventID = nil
                    memory.updatedAt = Date()
                }
                let records = try images(for: eventID, in: modelContext)
                deletionRefs = records.map(\.imageRef)
                    + [liveEvent.avatarImageRef].compactMap { $0 }
                ChekinanaEventMediaJournal.queueDeletion(deletionRefs)
                records.forEach(modelContext.delete)
                try ChekinanaEventSchedulePersistence.deleteLocked(
                    eventID: eventID,
                    in: modelContext
                )
                modelContext.delete(liveEvent)
                try saveContext(modelContext)
                } catch {
                    modelContext.rollback()
                    ChekinanaEventMediaJournal.cancelDeletion(deletionRefs)
                    throw error
                }
            }
        }
        ChekinanaEventMediaJournal.scheduleSafeCleanup(in: modelContext)
    }
}

private struct ChekinanaEventAvatar: View {
