                       let carriage = segment.carriageNumber?.nonEmpty {
                        LabeledContent(
                            ChekinanaProductCopy.text("travel.carriage", "Carriage"),
                            value: carriage
                        )
                    }
                    if let seat = segment.seatNumber.nonEmpty {
