struct ChekinanaTravelRouteDraft: Hashable {
    var departureLocation: String
    var arrivalLocation: String
    var departureTime: Date
    var arrivalTime: Date

    init(departureLocation: String, arrivalLocation: String, departureTime: Date, arrivalTime: Date) {
        self.departureLocation = departureLocation
        self.arrivalLocation = arrivalLocation
        self.departureTime = departureTime
        self.arrivalTime = arrivalTime
    }

    init(_ route: ChekinanaTravelResolvedRoute) {
        self.init(
            departureLocation: route.departureLocation,
            arrivalLocation: route.arrivalLocation,
            departureTime: route.departureTime,
            arrivalTime: route.arrivalTime
        )
    }

    var resolvedRoute: ChekinanaTravelResolvedRoute? {
        guard departureLocation.nonEmpty != nil, arrivalLocation.nonEmpty != nil else { return nil }
        return ChekinanaTravelResolvedRoute(
            departureLocation: departureLocation,
            arrivalLocation: arrivalLocation,
            departureTime: departureTime,
            arrivalTime: arrivalTime
        )
    }
}

private struct ChekinanaTravelSegmentEditorView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    let segment: TravelSegment?

    @State private var mode: ChekinanaTravelMode
    @State private var routeDate: Date
    @State private var serviceNumber: String
    @State private var seatNumber: String
    @State private var carriageNumber: String
    @State private var note: String
    @State private var scheduleResult: ChekinanaScheduleResult?
    @State private var resultSignature: ChekinanaScheduleRequestSignature?
    @State private var originIndex: Int?
    @State private var destinationIndex: Int?
    @State private var routeDraft: ChekinanaTravelRouteDraft
    @State private var routeEditRevision = UUID()
    @State private var resolvedIconReference: String?
    @State private var isLookingUp = false
    @State private var isSaving = false
    @State private var errorMessage: String?
    @State private var lookupTask: Task<Void, Never>?
    @State private var lookupRequestID: UUID?
    @State private var scheduleClient = ChekinanaScheduleClient()
    @State private var iconPickerItem: PhotosPickerItem?
    @State private var selectedIconData: Data?
    @State private var iconImportTask: Task<Void, Never>?
    @State private var iconImportRequestID: UUID?
    @State private var isImportingIcon = false
    @State private var mediaDraftOwnerID = UUID()
    @State private var mediaGeneration: UUID?
    @FocusState private var isServiceNumberFocused: Bool

    private let draftID: UUID
    private let expectedUpdatedAt: Date?

    init(segment: TravelSegment?) {
        self.segment = segment
        let now = Date()
        let initialMode = segment?.mode ?? .flight
        let initialDate = segment?.departureTime ?? now
        let initialNumber = segment?.serviceNumber ?? ""
        _mode = State(initialValue: initialMode)
        _routeDate = State(initialValue: initialDate)
        _serviceNumber = State(initialValue: initialNumber)
        _seatNumber = State(initialValue: segment?.seatNumber ?? "")
        _carriageNumber = State(initialValue: segment?.carriageNumber ?? "")
        _note = State(initialValue: segment?.note ?? "")
        draftID = segment?.id ?? UUID()
        expectedUpdatedAt = segment?.updatedAt
        _routeDraft = State(initialValue: ChekinanaTravelRouteDraft(
            departureLocation: segment?.displayedDepartureLocation ?? "",
            arrivalLocation: segment?.displayedArrivalLocation ?? "",
            departureTime: segment?.departureTime ?? now,
            arrivalTime: segment?.arrivalTime ?? now
        ))
        _resolvedIconReference = State(initialValue: segment?.operatorIconRef)
    }

    private var currentSignature: ChekinanaScheduleRequestSignature {
        ChekinanaScheduleRequestSignature(
            mode: mode,
            serviceNumber: serviceNumber,
            date: routeDate
        )
    }

    private var resolvedRoute: ChekinanaTravelResolvedRoute? {
        routeDraft.resolvedRoute
    }

    private func routeBinding<Value>(_ keyPath: WritableKeyPath<ChekinanaTravelRouteDraft, Value>) -> Binding<Value> {
        Binding(
            get: { routeDraft[keyPath: keyPath] },
            set: {
                routeDraft[keyPath: keyPath] = $0
                routeEditRevision = UUID()
            }
        )
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    Picker(
                        ChekinanaProductCopy.text("travel.mode", "Mode"),
                        selection: $mode
                    ) {
                        ForEach(ChekinanaTravelMode.allCases) { value in
                            Label(value.title, systemImage: value.systemImage).tag(value)
                        }
                    }
                    .pickerStyle(.segmented)

                    ChekinanaExpandableDateWheel(
                        ChekinanaProductCopy.text("travel.schedule.date", "Date"),
                        selection: $routeDate,
                        constrainsToPersistedContentRange: false,
                        accessibilityIdentifier: "chekinana.travel.schedule.date"
                    )
                    TextField(
                        mode == .flight
                            ? ChekinanaProductCopy.text("travel.flight_number", "Flight number")
                            : ChekinanaProductCopy.text("travel.train_number", "Train number"),
                        text: $serviceNumber
                    )
                    .textInputAutocapitalization(.characters)
                    .autocorrectionDisabled()
                    .submitLabel(.search)
                    .focused($isServiceNumberFocused)
                    .onSubmit { lookupSchedule() }

                    Button(action: lookupSchedule) {
                        HStack {
                            Text(
                                isLookingUp
                                    ? ChekinanaProductCopy.text("travel.schedule.looking_up", "Looking up…")
                                    : errorMessage == nil
                                        ? ChekinanaProductCopy.text("travel.schedule.lookup", "Look up schedule")
                                        : ChekinanaProductCopy.text("travel.schedule.retry", "Retry lookup")
                            )
                            Spacer()
                            Image(systemName: "magnifyingglass")
                                .opacity(isLookingUp ? 0 : 1)
                                .overlay { if isLookingUp { ProgressView() } }
                        }
                    }
                    .disabled(
                        isLookingUp
                            || isImportingIcon
                            || currentSignature.serviceNumber.isEmpty
                    )
                    .accessibilityIdentifier("chekinana.travel.schedule.lookup")
                }

                if let scheduleResult, resultSignature == currentSignature {
                    scheduleSelection(result: scheduleResult)
                }
                routeEditor

                Section(ChekinanaProductCopy.text("travel.seat_details", "Seat")) {
                    if mode == .train {
                        TextField(
                            ChekinanaProductCopy.text("travel.carriage", "Carriage"),
                            text: $carriageNumber
                        )
                    }
                    TextField(
                        ChekinanaProductCopy.text("travel.seat", "Seat"),
                        text: $seatNumber
                    )
                    ChekinanaSingleLineNoteField(
                        ChekinanaProductCopy.text("common.note", "Note"),
                        text: $note
                    )
                }

                if let errorMessage {
                    Section {
                        Text(errorMessage)
                            .foregroundStyle(.red)
                            .accessibilityIdentifier("chekinana.travel.schedule.error")
                    }
                }
            }
            .navigationTitle(
                segment == nil
                    ? ChekinanaProductCopy.text("travel.add", "Add trip")
                    : ChekinanaProductCopy.text("travel.edit", "Edit trip")
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        dismiss()
                    }
                    .disabled(isSaving)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.save", "Save")) {
                        Task { await save() }
                    }
                    .disabled(
                        isSaving
                            || isLookingUp
                            || isImportingIcon
                            || resolvedRoute == nil
                    )
                    .accessibilityIdentifier("chekinana.travel.editor.save")
                }
            }
            .onChange(of: mode) { _, value in
                if value == .flight { carriageNumber = "" }
                invalidateScheduleInput()
            }
            .onChange(of: routeDate) { _, _ in invalidateScheduleInput() }
            .onChange(of: serviceNumber) { _, _ in invalidateScheduleInput() }
            .onDisappear {
                ChekinanaEventTravelMediaOwnership.release(ownerID: mediaDraftOwnerID)
                lookupTask?.cancel()
                lookupTask = nil
                lookupRequestID = nil
                iconImportTask?.cancel()
                iconImportTask = nil
                iconImportRequestID = nil
                Task { await scheduleClient.cancel() }
            }
            .onAppear {
                beginMediaDraftOwnershipIfNeeded()
            }
            .onChange(of: iconPickerItem) { _, item in
                guard let item else { return }
                iconImportTask?.cancel()
                let requestID = UUID()
                iconImportRequestID = requestID
                isImportingIcon = true
                iconImportTask = Task { @MainActor in
                    defer {
                        if iconImportRequestID == requestID {
                            isImportingIcon = false
                            iconImportTask = nil
                            iconPickerItem = nil
                        }
                    }
                    let transfer = try? await item.loadTransferable(
                        type: ChekinanaProductTransferableImage.self
                    )
                    guard !Task.isCancelled,
                       iconImportRequestID == requestID else { return }
                    selectedIconData = ChekinanaTravelIconPickerPolicy.selectedData(
                        afterPickerResult: transfer?.data,
                        current: selectedIconData
                    )
                }
            }
            .interactiveDismissDisabled(isSaving)
            .accessibilityIdentifier("chekinana.travel.editor")
        }
        .chekinanaSheetDraftDismiss(
            isBusy: { isSaving || isImportingIcon },
            snapshot: { [AnyHashable(mode.rawValue), AnyHashable(routeDate), AnyHashable(serviceNumber), AnyHashable(seatNumber), AnyHashable(carriageNumber), AnyHashable(note), AnyHashable(originIndex), AnyHashable(destinationIndex), AnyHashable(routeDraft), AnyHashable(selectedIconData)] }
        )
    }

    @ViewBuilder
    private func scheduleSelection(result: ChekinanaScheduleResult) -> some View {
        Section(ChekinanaProductCopy.text("travel.route", "Route")) {
            ForEach(result.stops.indices, id: \.self) { index in
                Button {
                    selectStop(index, in: result)
                } label: {
                    HStack(spacing: 9) {
                        Image(
                            systemName: isSelectedStop(index)
                                ? "checkmark.circle.fill" : "circle"
                        )
                        .foregroundStyle(
                            isSelectedStop(index)
                                ? ChekinanaProductTheme.accent : Color.secondary
                        )
                        Text(result.stops[index].name)
                            .foregroundStyle(.primary)
                            .lineLimit(1)
                        Spacer(minLength: 8)
                        Text(stopTimeLabel(at: index, in: result))
                            .font(.caption.monospacedDigit())
                            .foregroundStyle(.secondary)
                            .lineLimit(1)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
                .contentShape(Rectangle())
                .disabled(
                    result.stops.count > 2
                        && !isSelectableStop(index, in: result)
                )
                .accessibilityIdentifier("chekinana.travel.schedule.stop.\(index)")
            }
        }
    }

    private var routeEditor: some View {
        Section(ChekinanaProductCopy.text("travel.route", "Route")) {
            operatorIconPicker
            TextField(
                ChekinanaProductCopy.text("travel.departure_location", "From"),
                text: routeBinding(\.departureLocation)
            )
            .accessibilityIdentifier("chekinana.travel.departure-location")
            ChekinanaExpandableDateWheel(
                ChekinanaProductCopy.text("travel.departure", "Departure"),
                selection: routeBinding(\.departureTime),
                constrainsToPersistedContentRange: false,
                accessibilityIdentifier: "chekinana.travel.departure-date"
            )
            DatePicker(
                ChekinanaProductCopy.text("travel.departure", "Departure"),
                selection: routeBinding(\.departureTime),
                displayedComponents: .hourAndMinute
            )
            .environment(\.locale, ChekinanaLanguagePreference.displayLocale())
            .accessibilityIdentifier("chekinana.travel.departure-time")
            TextField(
                ChekinanaProductCopy.text("travel.arrival_location", "To"),
                text: routeBinding(\.arrivalLocation)
            )
            .accessibilityIdentifier("chekinana.travel.arrival-location")
            ChekinanaExpandableDateWheel(
                ChekinanaProductCopy.text("travel.arrival", "Arrival"),
                selection: routeBinding(\.arrivalTime),
                constrainsToPersistedContentRange: false,
                accessibilityIdentifier: "chekinana.travel.arrival-date"
            )
            DatePicker(
                ChekinanaProductCopy.text("travel.arrival", "Arrival"),
                selection: routeBinding(\.arrivalTime),
                displayedComponents: .hourAndMinute
            )
            .environment(\.locale, ChekinanaLanguagePreference.displayLocale())
            .accessibilityIdentifier("chekinana.travel.arrival-time")
        }
    }

    @MainActor
    private var operatorIconPicker: some View {
        let label = ChekinanaTravelOperatorIconPickerLabel(
            selectedIconData: selectedIconData,
            resolvedIconReference: resolvedIconReference,
            mode: mode,
            isImporting: isImportingIcon
        )
        return PhotosPicker(selection: $iconPickerItem, matching: .images) {
            label
        }
        .buttonStyle(.plain)
        .disabled(isImportingIcon || isSaving)
        .accessibilityIdentifier("chekinana.travel.icon-picker")
    }

    private func stopTimeLabel(
        at index: Int,
        in result: ChekinanaScheduleResult
    ) -> String {
        let stop = result.stops[index]
        if destinationIndex == index, let arrival = stop.arrival {
            return ChekinanaProductCopy.format(
                "travel.schedule.arrival_time",
                "Arr %@",
                localScheduleTime(arrival, timeZone: stop.arrivalTimeZone)
            )
        }
        if originIndex == index, let departure = stop.departure {
            return ChekinanaProductCopy.format(
                "travel.schedule.departure_time",
                "Dep %@",
                localScheduleTime(departure, timeZone: stop.departureTimeZone)
            )
        }
        if let departure = stop.departure {
            return ChekinanaProductCopy.format(
                "travel.schedule.departure_time",
                "Dep %@",
                localScheduleTime(departure, timeZone: stop.departureTimeZone)
            )
        }
        if let arrival = stop.arrival {
            return ChekinanaProductCopy.format(
                "travel.schedule.arrival_time",
                "Arr %@",
                localScheduleTime(arrival, timeZone: stop.arrivalTimeZone)
            )
        }
        return ChekinanaProductCopy.text("common.none", "None")
    }

    private func localScheduleTime(_ date: Date, timeZone: TimeZone?) -> String {
        let formatter = DateFormatter()
        formatter.locale = ChekinanaLanguagePreference.displayLocale()
        formatter.timeZone = timeZone ?? .current
        formatter.dateStyle = .none
        formatter.timeStyle = .short
        return formatter.string(from: date)
    }

    private func isSelectedStop(_ index: Int) -> Bool {
        originIndex == index || destinationIndex == index
    }

    private func isSelectableStop(
        _ index: Int,
        in result: ChekinanaScheduleResult
    ) -> Bool {
        ChekinanaTravelStopTapSelectionPolicy.isSelectable(
            index,
            in: result,
            selection: .init(
                originIndex: originIndex,
                destinationIndex: destinationIndex
            )
        )
    }

    private func selectStop(
        _ index: Int,
        in result: ChekinanaScheduleResult
    ) {
        guard result.stops.count > 2,
              isSelectableStop(index, in: result) else { return }
        let updated = ChekinanaTravelStopTapSelectionPolicy.selection(
            afterTapping: index,
            in: result,
            current: .init(
                originIndex: originIndex,
                destinationIndex: destinationIndex
            )
        )
        originIndex = updated.originIndex
        destinationIndex = updated.destinationIndex
        fillRouteDraft(from: result)
    }

    private func fillRouteDraft(from result: ChekinanaScheduleResult) {
        guard let route = ChekinanaTravelRouteSelectionPolicy.resolvedRoute(
            result: result,
            originIndex: originIndex,
            destinationIndex: destinationIndex
        ) else { return }
        routeDraft = ChekinanaTravelRouteDraft(route)
    }

    @MainActor
    private func invalidateScheduleInput() {
        lookupTask?.cancel()
        lookupTask = nil
        lookupRequestID = nil
        Task { await scheduleClient.cancel() }
        isLookingUp = false
        scheduleResult = nil
        resultSignature = nil
        originIndex = nil
        destinationIndex = nil
        errorMessage = nil
    }

    @MainActor
    private func lookupSchedule() {
        isServiceNumberFocused = false
        guard !isLookingUp else { return }
        let signature = currentSignature
        let queryDate = routeDate
        let requestedRouteRevision = routeEditRevision
        guard !signature.serviceNumber.isEmpty else {
            errorMessage = ChekinanaScheduleClientError.missingQuery.localizedDescription
            return
        }
        lookupTask?.cancel()
        let requestID = UUID()
        lookupRequestID = requestID
        isLookingUp = true
        errorMessage = nil
        scheduleResult = nil
        resultSignature = nil
        originIndex = nil
        destinationIndex = nil
        lookupTask = Task {
            do {
                let result = try await scheduleClient.schedule(
                    mode: signature.mode,
                    serviceNumber: signature.serviceNumber,
                    date: queryDate
                )
                guard !Task.isCancelled,
                      lookupRequestID == requestID,
                      currentSignature == signature else { return }
                iconImportTask?.cancel()
                iconImportTask = nil
                iconImportRequestID = nil
                isImportingIcon = false
                iconPickerItem = nil
                selectedIconData = nil
                scheduleResult = result
                resultSignature = signature
                resolvedIconReference = ChekinanaTravelOperatorIcon.assetReference(
                    forOperatorCode: result.operatorCode
                )
                if let automatic = ChekinanaTravelRouteSelectionPolicy.automaticSelection(
                    for: result
                ) {
                    originIndex = automatic.0
                    destinationIndex = automatic.1
                } else if let segment,
                          let matchedOrigin = result.stops.firstIndex(where: {
                              $0.name == segment.displayedDepartureLocation
                                  && $0.departure != nil
                          }),
                          let matchedDestination = result.stops.indices.first(where: {
                              $0 > matchedOrigin
                                  && result.stops[$0].name == segment.displayedArrivalLocation
                                  && result.stops[$0].arrival != nil
                          }) {
                    originIndex = matchedOrigin
                    destinationIndex = matchedDestination
                }
                if routeEditRevision == requestedRouteRevision {
                    fillRouteDraft(from: result)
                }
                lookupTask = nil
                lookupRequestID = nil
                isLookingUp = false
            } catch is CancellationError {
                guard lookupRequestID == requestID,
                      currentSignature == signature else { return }
                lookupTask = nil
                lookupRequestID = nil
                isLookingUp = false
            } catch {
                guard !Task.isCancelled,
                      lookupRequestID == requestID,
                      currentSignature == signature else { return }
                lookupTask = nil
                lookupRequestID = nil
                isLookingUp = false
                errorMessage = error.localizedDescription
            }
        }
    }

    @MainActor
    private func save() async {
        guard !isSaving, let resolvedRoute else {
            errorMessage = ChekinanaTravelSegmentValidationError
                .missingRequiredFields.localizedDescription
            return
        }
        guard segment != nil || ChekinanaTravelTimelinePolicy.isUpcoming(
            departureTime: resolvedRoute.departureTime,
            arrivalTime: resolvedRoute.arrivalTime,
            from: Date()
        ) else {
            errorMessage = ChekinanaTravelSegmentValidationError.arrivalBeforeToday.localizedDescription
            return
        }
        isSaving = true
        defer { isSaving = false }
        let fields = ChekinanaTravelSegmentFields(
            mode: mode,
            operatorName: "",
            serviceNumber: currentSignature.serviceNumber,
            departureCity: "",
            departureLocation: resolvedRoute.departureLocation,
            arrivalCity: "",
            arrivalLocation: resolvedRoute.arrivalLocation,
            departureTime: resolvedRoute.departureTime,
            arrivalTime: resolvedRoute.arrivalTime,
            seatNumber: seatNumber,
            carriageNumber: carriageNumber,
            note: note
        )
        let target = segment ?? TravelSegment(
            id: draftID,
            mode: mode,
            serviceNumber: currentSignature.serviceNumber,
            departureCity: "",
            departureLocation: resolvedRoute.departureLocation,
            arrivalCity: "",
            arrivalLocation: resolvedRoute.arrivalLocation,
            departureTime: resolvedRoute.departureTime,
            arrivalTime: resolvedRoute.arrivalTime
        )
        guard let mediaGeneration else {
            errorMessage = ChekinanaProductCopy.text(
                "travel.media_generation_failed",
                "Unable to establish the library generation. Reopen the trip and try again."
            )
            return
        }
        let saveOwnerID = UUID()
        ChekinanaEventTravelMediaOwnership.beginSaveTask(
            ownerID: saveOwnerID,
            generation: mediaGeneration,
            references: [resolvedIconReference].compactMap { $0 }
        )
        ChekinanaEventTravelMediaOwnership.transfer(
            [resolvedIconReference].compactMap { $0 },
            from: mediaDraftOwnerID,
            to: saveOwnerID,
            generation: mediaGeneration
        )
        var stagedIconReference: String?
        do {
            if let selectedIconData {
                stagedIconReference = try await ChekinanaEventAvatarStore.save(
                    selectedIconData,
                    eventID: target.id,
                    ownerID: saveOwnerID,
                    generation: mediaGeneration
                )
            }
            try Task.checkCancellation()
            if segment == nil, !ChekinanaTravelTimelinePolicy.isUpcoming(
                departureTime: resolvedRoute.departureTime,
                arrivalTime: resolvedRoute.arrivalTime,
                from: Date()
            ) {
                throw ChekinanaTravelSegmentValidationError.arrivalBeforeToday
            }
            _ = try ChekinanaTravelSegmentPersistence.save(
                target,
                inserting: segment == nil,
                expectedUpdatedAt: expectedUpdatedAt,
                fields: fields,
                operatorIconRef: stagedIconReference ?? resolvedIconReference,
                previousIconRef: segment?.operatorIconRef,
                in: modelContext,
                validateManagedFiles: true,
                expectedGeneration: mediaGeneration,
                mediaOwnerID: saveOwnerID,
                mediaOwnerReferences: [
                    resolvedIconReference,
                    stagedIconReference,
                ].compactMap { $0 }
            )
            ChekinanaEventTravelMediaOwnership.release(ownerID: mediaDraftOwnerID)
            ChekinanaEventMediaJournal.scheduleSafeCleanup(in: modelContext)
            dismiss()
        } catch {
            ChekinanaEventAvatarStore.remove(stagedIconReference)
            ChekinanaEventTravelMediaOwnership.transfer(
                [resolvedIconReference, stagedIconReference].compactMap { $0 },
                from: saveOwnerID,
                to: mediaDraftOwnerID,
                generation: mediaGeneration
            )
            ChekinanaEventTravelMediaOwnership.release(ownerID: saveOwnerID)
            errorMessage = error.localizedDescription
        }
    }

    @MainActor
    private func beginMediaDraftOwnershipIfNeeded() {
        guard mediaGeneration == nil,
              let generation = ChekinanaEventTravelMediaOwnership.currentGeneration(
                  in: modelContext
              ) else { return }
        mediaGeneration = generation
        ChekinanaEventTravelMediaOwnership.beginDraftSession(
            ownerID: mediaDraftOwnerID,
            generation: generation
        )
    }
}

enum ChekinanaEventMediaPresenterPolicy {
    struct Selection: Identifiable, Equatable {
        let id: UUID
        let kind: MediaItemKind

        init?(media: MediaItem) {
            guard media.kind == .shame || media.kind == .douga else {
                return nil
            }
            id = media.id
            kind = media.kind
        }
    }

    static func visibleItems(
        in values: [MediaItem],
        eventID: UUID,
        hiddenIDs: Set<UUID>
    ) -> [MediaItem] {
        ChekinanaShotDisplayOrdering.media(values.filter {
            $0.eventID == eventID
                && ChekinanaVisibilityPolicy.includesRecord(
                    idolIDs: $0.idolIDs,
                    hiddenIDs: hiddenIDs
                )
        })
    }

    static func pagerItems(
        for selection: Selection,
        eventID: UUID,
        shames: [MediaItem],
        dougas: [MediaItem],
        hiddenIDs: Set<UUID>
    ) -> [MediaItem] {
        let matchingKind: [MediaItem]
        switch selection.kind {
        case .shame:
            matchingKind = shames
        case .douga:
            matchingKind = dougas
        case .cheki:
            return []
        }
        return visibleItems(
            in: matchingKind,
            eventID: eventID,
            hiddenIDs: hiddenIDs
        ).filter { $0.kind == selection.kind }
    }

    static func reconciledSelection(
        _ selection: Selection?,
        available: [Selection]
    ) -> Selection? {
        guard let selection, available.contains(selection) else { return nil }
        return selection
    }
}

/// One per-render relationship snapshot for Event details. It resolves local
/// media from the already complete Idol query; foreign/detached objects retain
/// their own context's relationship semantics.
private struct ChekinanaEventDetailMediaSnapshot {
    let visibleChekis: [MediaItem]
    let visibleRecords: [ChekiRecord]
    let total: Int

    init(
        event: Event, context: ModelContext, idols: [Idol],
        chekis: [MediaItem], records: [ChekiRecord], hiddenIDs: Set<UUID>,
        countsByIdolID: [UUID: Int]
    ) {
        let byID = Dictionary(uniqueKeysWithValues: idols.map { ($0.id, $0) })
        let candidates = chekis.filter { $0.eventID == event.id }
        let resolved = Dictionary(candidates.map { item in
            let values: [Idol]
            if item.modelContext === context {
                var seen = Set<UUID>()
                values = item.idolIDs.compactMap { id in
                    seen.insert(id).inserted ? byID[id] : nil
                }
            } else {
                values = item.idols
            }
            return (ObjectIdentifier(item), values)
        }, uniquingKeysWith: { first, _ in first })
        visibleChekis = ChekinanaEventChekiOrdering.ordered(
            candidates, hiddenIDs: hiddenIDs, chekiCountsByIdolID: countsByIdolID,
            resolvedIdols: { resolved[ObjectIdentifier($0)] ?? [] }
        )
        visibleRecords = ChekinanaEventChekiCount.visibleRecords(
            records, eventID: event.id, hiddenIDs: hiddenIDs
        ).sorted { $0.id.uuidString < $1.id.uuidString }
        // Preserve total's non-deduplicating count and foreign/detached Event
        // resolution, while the actual displayed Event is authoritative locally.
        let mediaCount = candidates.filter { item in
            let linked = item.modelContext === context && event.modelContext === context
                ? item.eventID == event.id : item.event?.id == event.id
            return linked && ChekinanaVisibilityPolicy.includesRecord(
                idolIDs: (resolved[ObjectIdentifier(item)] ?? []).map(\.id), hiddenIDs: hiddenIDs
            )
        }.count
        total = ChekinanaDisplayCount.adding(
            mediaCount, ChekinanaChekiRecordStore.totalCount(visibleRecords)
        )
    }
}

private struct ChekinanaEventFullWidthSeparator: ViewModifier {
    @Environment(\.layoutDirection) private var layoutDirection
    @State private var contentBounds: CGRect = .zero
    @State private var rowBounds: CGRect = .zero

    private var leftInset: CGFloat {
        rowBounds.width > 0 && contentBounds.width > 0
            ? max(0, contentBounds.minX - rowBounds.minX) : 0
    }
    private var rightInset: CGFloat {
        rowBounds.width > 0 && contentBounds.width > 0
            ? max(0, rowBounds.maxX - contentBounds.maxX) : 0
    }

    func body(content: Content) -> some View {
        let leadingOffset = layoutDirection == .rightToLeft ? rightInset : -leftInset
        let trailingOffset = layoutDirection == .rightToLeft ? -leftInset : rightInset
        return content
            .onGeometryChange(for: CGRect.self) { proxy in
                let frame = proxy.frame(in: .global)
                return CGRect(x: frame.minX, y: 0, width: frame.width, height: 0)
            } action: { contentBounds = $0 }
            .alignmentGuide(.listRowSeparatorLeading) { dimensions in
                dimensions[.leading] + leadingOffset
            }
            .alignmentGuide(.listRowSeparatorTrailing) { dimensions in
                dimensions[.trailing] + trailingOffset
            }
            .listRowBackground(
                Color(uiColor: .secondarySystemGroupedBackground)
                    .onGeometryChange(for: CGRect.self) { proxy in
                        let frame = proxy.frame(in: .global)
                        return CGRect(x: frame.minX, y: 0, width: frame.width, height: 0)
                    } action: { rowBounds = $0 }
            )
    }
}

enum ChekinanaEventMediaGroupPresentation {
    static func count(_ group: ChekinanaCalendarIdolGroup, kind: ChekinanaRecordKind) -> Int {
        switch kind {
        case .cheki: return group.chekiCount
        case .shame: return group.shames.count
        case .douga: return group.dougas.count
        }
    }

    static func selecting(_ group: ChekinanaCalendarIdolGroup, kind: ChekinanaRecordKind) -> ChekinanaCalendarIdolGroup {
        var result = group
        if kind != .cheki {
            result.chekis = []
            result.records = []
        }
        if kind != .shame { result.shames = [] }
        if kind != .douga { result.dougas = [] }
        return result
    }
}

private struct ChekinanaEventDetailView: View {
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query private var memoryAttachments: [MemoryAttachment]
    @Query private var eventImages: [EventImage]
    @Query private var eventSchedules: [EventSchedule]
    @Query private var chekiRecords: [ChekiRecord]
    @Query private var idols: [Idol]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "shame" }) private var shames: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @Query private var memories: [Memory]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let event: Event
    let requestDeletion: (UUID) -> Void
    @State private var isEditing = false
    @State private var isDeleting = false
    @State private var selectedChekiGroupID: String?
    @State private var selectedMediaGroupKind: ChekinanaRecordKind = .cheki
    @State private var selectedCheki: MediaItem?
    @State private var selectedOtherMedia: ChekinanaEventMediaPresenterPolicy.Selection?
    @State private var selectedChekiRecord: ChekinanaChekiRecordSelection?
    @State private var selectedMemory: Memory?
    @State private var message: String?
    @State private var isSaving = false
    @State private var isEditingNote = false
    @State private var selectedEventImage: ChekinanaEventImageViewerSelection?
    @State private var noteDraft = ""
    @State private var noteExpectedUpdatedAt: Date?
    @FocusState private var isNoteFocused: Bool

    init(event: Event, requestDeletion: @escaping (UUID) -> Void) {
        self.event = event
        self.requestDeletion = requestDeletion
        let eventID = event.id
        _eventImages = Query(
            filter: #Predicate<EventImage> { $0.eventID == eventID },
            sort: \EventImage.sortOrder
        )
        _eventSchedules = Query(
            filter: #Predicate<EventSchedule> { $0.eventID == eventID }
        )
        _chekis = Query(filter: #Predicate<MediaItem> {
            $0.kindRawValue == "cheki" && $0.eventID == eventID
        })
        _shames = Query(filter: #Predicate<MediaItem> {
            $0.kindRawValue == "shame" && $0.eventID == eventID
        })
        _dougas = Query(filter: #Predicate<MediaItem> {
            $0.kindRawValue == "douga" && $0.eventID == eventID
        })
        _chekiRecords = Query(filter: #Predicate<ChekiRecord> { $0.eventID == eventID })
        _memories = Query(filter: #Predicate<Memory> { $0.eventID == eventID })
    }

    private var linkedMemories: [Memory] {
        memories.filter { $0.eventID == event.id }
            .sorted { ($0.date ?? $0.createdAt) > ($1.date ?? $1.createdAt) }
    }

    private func visibleEventMedia(_ values: [MediaItem]) -> [MediaItem] {
        ChekinanaEventMediaPresenterPolicy.visibleItems(
            in: values,
            eventID: event.id,
            hiddenIDs: hiddenIdols.hiddenIDs
        )
    }

    private var visibleOtherMediaSelections: [
        ChekinanaEventMediaPresenterPolicy.Selection
    ] {
        (visibleEventMedia(shames) + visibleEventMedia(dougas)).compactMap {
            ChekinanaEventMediaPresenterPolicy.Selection(media: $0)
        }
    }

    private func presentOtherMedia(_ media: MediaItem) {
        selectedOtherMedia = ChekinanaEventMediaPresenterPolicy.Selection(
            media: media
        )
    }

    @AppStorage(ChekinanaShotDisplayOrdering.defaultsKey) private var twoShotFirst = false

    var body: some View {
        let _ = twoShotFirst
        let mediaSnapshot = ChekinanaEventDetailMediaSnapshot(
            event: event, context: modelContext, idols: idols, chekis: chekis,
            records: chekiRecords, hiddenIDs: hiddenIdols.hiddenIDs,
            countsByIdolID: idolOrdering.chekiCountsByIdolID
        )
        let visibleChekis = mediaSnapshot.visibleChekis
        let visibleChekiRecords = mediaSnapshot.visibleRecords
        let chekiCount = mediaSnapshot.total
        let chekiGroups = ChekinanaCalendarIdolGroup.groups(
            for: visibleChekis, records: visibleChekiRecords,
            relationshipIndex: ChekinanaChekiRecordRelationshipIndex(idols: idols),
            groupsByExactIdolCombination: true,
            shames: visibleEventMedia(shames), dougas: visibleEventMedia(dougas),
            chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
        )
        let selectedTypeGroups = chekiGroups.filter {
            ChekinanaEventMediaGroupPresentation.count($0, kind: selectedMediaGroupKind) > 0
        }
        let selectedGroup = selectedTypeGroups.first { $0.id == selectedChekiGroupID }
            .map { ChekinanaEventMediaGroupPresentation.selecting($0, kind: selectedMediaGroupKind) }
        let linkedMemories = self.linkedMemories
        let linkedMemoryIDs = Set(linkedMemories.map(\.id))
        let memoryAttachmentCounts = linkedMemoryIDs.isEmpty ? [:]
            : ChekinanaMemoryAttachmentCounts.byMemory(
                memoryAttachments.filter { linkedMemoryIDs.contains($0.memoryID) }
            )
        let _ = languageRevision
        NavigationStack {
            if let group = selectedGroup {
                ChekinanaUnifiedChekiGroupPage(
                    groups: [group],
                    title: event.name,
                    selectCheki: { selectedCheki = $0 },
                    selectRecord: {
                        selectedChekiRecord = ChekinanaChekiRecordSelection(
                            record: $0
                        )
                    },
                    selectOtherMedia: presentOtherMedia,
                    separatesMediaTypes: true,
                    onBack: { selectedChekiGroupID = nil }
                )
            } else {
                List {
                Section {
                    ChekinanaSectionCard {
                        HStack(spacing: 16) {
                            ChekinanaEventAvatar(event: event, size: 76)
                            VStack(alignment: .leading, spacing: 6) {
                                Text(event.name)
                                    .font(.title3.weight(.bold))
                                    .foregroundStyle(.primary)
                                Text(ChekinanaProductDate.displayString(event.date))
                                    .font(.subheadline.weight(.medium))
                                    .foregroundStyle(ChekinanaProductTheme.accent)
                                Text(
                                    [ChekinanaEventCity.displayed(event.city), event.resolvedLivehouse]
                                        .compactMap { $0 }
                                        .joined(separator: " · ")
                                        .nonEmpty
                                        ?? ChekinanaProductCopy.text(
                                            "events.no_date_venue",
                                            "No date or venue"
                                        )
                                )
                                .font(.caption)
                                .foregroundStyle(.secondary)
                            }
                            Spacer(minLength: 0)
                        }
                    }
                    .listRowInsets(EdgeInsets())
                    .listRowBackground(Color.clear)
                }
                Section(ChekinanaProductCopy.text("events.details", "Details")) {
                    if let schedule = eventSchedules.first,
                       let summary = ChekinanaEventTime.summary(
                           openTime: schedule.openTime,
                           startTime: schedule.startTime
                       ) {
                        Text(summary)
                            .font(.body.monospacedDigit())
                            .accessibilityIdentifier("chekinana.events.detail.schedule")
                    }
                    if let city = ChekinanaEventCity.displayed(event.city) {
                        LabeledContent(
                            ChekinanaProductCopy.text("events.city", "City"),
                            value: city
                        )
                    }
                    if let livehouse = event.resolvedLivehouse {
                        LabeledContent(
                            ChekinanaProductCopy.text("events.livehouse", "Livehouse"),
                            value: livehouse
                        )
                    }
                    if let price = event.price?.nonEmpty {
                        LabeledContent(
                            ChekinanaProductCopy.text("events.price", "Price"),
                            value: price
                        )
                    }
                    if let url = event.weiboURL,
                       let source = event.source {
                        Link(
                            source == .weibo
                                ? ChekinanaProductCopy.text(
                                    "events.open_weibo",
                                    "Open Weibo"
                                )
                                : ChekinanaProductCopy.text(
                                    "events.open_x",
                                    "Open X"
                                ),
                            destination: url
                        )
                    }
                    if let url = event.ticketURL {
                        Link(
                            ChekinanaProductCopy.text(
                                "events.open_ticket",
                                "Open ticket page"
                            ),
                            destination: url
                        )
                    }
                    if isEditingNote {
                        VStack(alignment: .leading, spacing: 8) {
                            Text(ChekinanaProductCopy.text("common.note", "Note"))
                                .font(.subheadline.weight(.semibold))
                            ChekinanaSingleLineNoteField(
                                ChekinanaProductCopy.text("common.note", "Note"),
                                text: $noteDraft,
                                focus: $isNoteFocused,
                                onSubmit: saveNote
                            )
                                .accessibilityIdentifier("chekinana.events.detail.note.editor")
                            HStack {
                                Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                                    isEditingNote = false
                                    isNoteFocused = false
                                }
                                Spacer()
                                Button(ChekinanaProductCopy.text("common.save", "Save")) {
                                    saveNote()
                                }
                                    .buttonStyle(.borderedProminent)
                                    .accessibilityIdentifier("chekinana.events.detail.note.save")
                            }
                        }
                    } else {
                        Button {
                            noteDraft = event.note
                            noteExpectedUpdatedAt = event.updatedAt
                            isEditingNote = true
                            isNoteFocused = true
                        } label: {
                            HStack(alignment: .firstTextBaseline) {
                                Text(ChekinanaProductCopy.text("common.note", "Note"))
                                    .foregroundStyle(.primary)
                                Spacer(minLength: 12)
                                Text(
                                    event.note.nonEmpty
                                        ?? ChekinanaProductCopy.text(
                                            "common.add_note",
                                            "Add note"
                                        )
                                )
                                    .foregroundStyle(event.note.isEmpty ? .blue : .primary)
                                    .multilineTextAlignment(.trailing)
                            }
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .accessibilityIdentifier("chekinana.events.detail.note")
                    }
                }
                if !eventImages.isEmpty {
                    Section(ChekinanaProductCopy.text("events.images", "Images")) {
                        ScrollView(.horizontal) {
                            LazyHStack(spacing: 12) {
                                ForEach(Array(eventImages.enumerated()), id: \.element.id) { index, record in
                                    Button {
                                        selectedEventImage = .init(id: record.id)
                                    } label: {
                                        ChekinanaEventImageThumbnail(record: record)
                                    }
                                    .buttonStyle(.plain)
                                    .accessibilityLabel(
                                        ChekinanaProductCopy.format(
                                            "events.image_number",
                                            "Event image %lld",
                                            Int64(index + 1)
                                        )
                                    )
                                    .accessibilityHint(ChekinanaProductCopy.text(
                                        "events.image.open_hint",
                                        "Open this image full screen"
                                    ))
                                    .accessibilityIdentifier(
                                        "chekinana.events.detail.image.\(record.id.uuidString.lowercased())"
                                    )
                                }
                            }
                            .padding(.vertical, 4)
                        }
                        .scrollIndicators(.hidden)
                        Text(
                            ChekinanaProductCopy.text(
                                "events.images.edit_hint",
                                "Use Edit to add or remove Event images."
                            )
                        )
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                }
                ForEach([ChekinanaRecordKind.cheki, .shame, .douga], id: \.rawValue) { kind in
                    let typeGroups = chekiGroups.filter {
                        ChekinanaEventMediaGroupPresentation.count($0, kind: kind) > 0
                    }
                    let total = kind == .cheki ? chekiCount : ChekinanaDisplayCount.total(
                        typeGroups.map { ChekinanaEventMediaGroupPresentation.count($0, kind: kind) }
                    )
                    if kind == .cheki || total > 0 {
                        Section(kind.countLabel(total)) {
                            if kind == .cheki && chekiCount == 0 {
                                Text(
                                    ChekinanaProductCopy.text(
                                        "events.no_linked_cheki",
                                        "No linked Cheki"
                                    )
                                )
                                .foregroundStyle(.secondary)
                            }
                            ForEach(typeGroups) { group in
                                let count = ChekinanaEventMediaGroupPresentation.count(group, kind: kind)
                                let countLabel = kind == .cheki ? eventChekiGroupCount(count) : kind.countLabel(count)
                                Button {
                                    selectedMediaGroupKind = kind
                                    selectedChekiGroupID = group.id
                                } label: {
                                    HStack(spacing: 12) {
                                        ChekinanaIdolAvatarRow(
                                            idols: group.orderedIdols,
                                            size: 36,
                                            showsNames: false
                                        )
                                        Spacer(minLength: 8)
                                        Text(countLabel)
                                            .font(.caption.weight(.semibold))
                                            .foregroundStyle(.secondary)
                                        Image(systemName: "chevron.right")
                                            .font(.caption)
                                            .foregroundStyle(.tertiary)
                                    }
                                    .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
                                    .contentShape(Rectangle())
                                }
                                .modifier(ChekinanaEventFullWidthSeparator())
                                .buttonStyle(.plain)
                                .accessibilityLabel(ChekinanaProductCopy.format(
                                    "events.cheki_group_accessibility",
                                    "%1$@, %2$@",
                                    group.name,
                                    countLabel
                                ))
                                .accessibilityIdentifier(
                                    "chekinana.events.detail.\(kind.rawValue)-group.\(group.id)"
                                )
                            }
                    }
                    }
                }
                if !linkedMemories.isEmpty {
                    Section(ChekinanaProductCopy.text("gallery.memory", "Memory")) {
                        ForEach(linkedMemories) { memory in
                            Button { selectedMemory = memory } label: {
                                ChekinanaIdolMemoryEventRow(
                                    memory: memory,
                                    idols: idolOrdering.ordered(
                                        idols.filter { memory.idolIDs.contains($0.id) }
                                    ),
                                    event: event,
                                    counts: memoryAttachmentCounts[memory.id] ?? .init(),
                                    titleOnly: true
                                )
                            }
                            .buttonStyle(.plain)
                        }
                    }
                }
            }
            .chekinanaGroupedPageBackground()
            .navigationTitle(ChekinanaProductCopy.text("events.event", "Event"))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) { dismiss() }
                        .accessibilityIdentifier("chekinana.events.detail.done")
                }
                ToolbarItemGroup(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.edit", "Edit")) { isEditing = true }
                        .accessibilityIdentifier("chekinana.events.detail.edit")
                    Button(role: .destructive) { deleteEvent() } label: {
                        Image(systemName: "trash")
                    }
                    .disabled(isDeleting)
                        .accessibilityIdentifier("chekinana.events.detail.delete")
                }
            }
            .sheet(isPresented: $isEditing) { ChekinanaEventEditorView(event: event) }
            .sheet(item: $selectedMemory) { ChekinanaMemoryDetailView(memory: $0) }
            .fullScreenCover(item: $selectedEventImage) { selection in
                ChekinanaEventImageViewer(
                    images: eventImages,
                    initialID: selection.id
                )
            }
            .alert(ChekinanaProductCopy.text("events.event", "Event"), isPresented: Binding(
                get: { message != nil },
                set: { if !$0 { message = nil } }
            )) {
                Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
            } message: {
                Text(message ?? "")
            }
            .chekinanaScreenMarker("chekinana.events.detail")
            .onChange(of: selectedTypeGroups.map(\.id)) { _, ids in
                if let selectedChekiGroupID, !ids.contains(selectedChekiGroupID) {
                    self.selectedChekiGroupID = nil
                }
                if let selectedCheki,
                   !visibleChekis.contains(where: { $0.id == selectedCheki.id }) {
                    self.selectedCheki = nil
                }
                if let selectedChekiRecord,
                   !visibleChekiRecords.contains(where: {
                       $0.id == selectedChekiRecord.id
                   }) {
                    self.selectedChekiRecord = nil
                }
            }
        }
        }
        .sheet(item: $selectedChekiRecord) { selection in
            ChekinanaChekiRecordEditor(selection: selection)
        }
        .fullScreenCover(item: $selectedCheki) { cheki in
            ChekinanaGalleryDetailView(
                chekis: visibleChekis,
                initialID: cheki.id
            )
        }
        .fullScreenCover(item: $selectedOtherMedia) { selection in
            ChekinanaGalleryMediaPagerView(
                items: ChekinanaEventMediaPresenterPolicy.pagerItems(
                    for: selection,
                    eventID: event.id,
                    shames: shames,
                    dougas: dougas,
                    hiddenIDs: hiddenIdols.hiddenIDs
                ),
                kind: selection.kind,
                initialID: selection.id
            )
        }
        .onChange(of: visibleOtherMediaSelections) { _, selections in
            selectedOtherMedia = ChekinanaEventMediaPresenterPolicy
                .reconciledSelection(
                    selectedOtherMedia,
                    available: selections
                )
        }
        .chekinanaSheetDraftDismiss(
            isBusy: { isSaving || isDeleting },
            snapshot: { [] },
            hasUnsavedChanges: { isEditingNote && noteDraft != event.note }
        )
    }

    private func eventChekiGroupCount(_ count: Int) -> String {
        ChekinanaProductCopy.quantity(
            "events.cheki_group_count",
            count: count,
            one: "%lld Cheki",
            other: "%lld chekis"
        )
    }

    private func deleteEvent() {
        guard !isDeleting else { return }
        isDeleting = true
        selectedEventImage = nil
        selectedCheki = nil
        selectedOtherMedia = nil
        selectedChekiRecord = nil
        selectedChekiGroupID = nil
        isEditing = false
        requestDeletion(event.id)
    }

    private func saveNote() {
        guard let noteExpectedUpdatedAt else {
            message = ChekinanaProductCopy.text(
                "error.event_changed_reopen",
                "This Event changed or was deleted. Reopen it and try again."
            )
            return
        }
        do {
            try ChekinanaEventPersistence.update(
                eventID: event.id,
                expectedUpdatedAt: noteExpectedUpdatedAt,
                in: modelContext,
                apply: {
                    $0.note = noteDraft
                    $0.updatedAt = Date()
                }
            )
            isEditingNote = false
            isNoteFocused = false
            self.noteExpectedUpdatedAt = nil
        } catch {
            noteDraft = event.note
            message = error.localizedDescription
        }
    }
}

struct ChekinanaUnifiedChekiOrderSnapshot: Equatable, Sendable {
    let id: UUID
    let isFavorite: Bool
    let idx: Int?
    let createdAt: Date
    var isTwoShot: Bool = false
}

enum ChekinanaUnifiedChekiOrderPolicy {
    static func orderedIDs(
        _ values: [ChekinanaUnifiedChekiOrderSnapshot]
    ) -> [UUID] {
        values.sorted { lhs, rhs in
            if lhs.idx != rhs.idx {
                return (lhs.idx ?? .max) < (rhs.idx ?? .max)
            }
            if lhs.createdAt != rhs.createdAt {
                return lhs.createdAt < rhs.createdAt
            }
            return lhs.id.uuidString < rhs.id.uuidString
        }
        .map(\.id)
    }

    static func reorderedIDs(
        moving sourceID: UUID,
        toPartitionIndex targetIndex: Int,
        values: [ChekinanaUnifiedChekiOrderSnapshot]
    ) throws -> [UUID] {
        let byID = Dictionary(uniqueKeysWithValues: values.map { ($0.id, $0) })
        guard let source = byID[sourceID] else {
            throw ChekinanaIdolChekiReorderError.changedRecords
        }
        let ordered = orderedIDs(values)
        let slots = ordered.indices.filter { byID[ordered[$0]]?.isFavorite == source.isFavorite && byID[ordered[$0]]?.isTwoShot == source.isTwoShot }
        var partition = slots.map { ordered[$0] }
        guard let sourceIndex = partition.firstIndex(of: sourceID), partition.indices.contains(targetIndex) else { throw ChekinanaIdolChekiReorderError.changedRecords }
        partition.remove(at: sourceIndex)
        partition.insert(sourceID, at: targetIndex)
        var result = ordered
        for (slot, id) in zip(slots, partition) { result[slot] = id }
        return result
    }

    /// Reuses exactly the indices already owned by the inclusive movement
    /// interval. No row outside that interval is renumbered and legal gaps are
    /// retained.
    static func minimalIndexAssignments(
        moving sourceID: UUID,
        toPartitionIndex targetIndex: Int,
        values: [ChekinanaUnifiedChekiOrderSnapshot]
    ) throws -> [UUID: Int] {
        let byID = Dictionary(uniqueKeysWithValues: values.map { ($0.id, $0) })
        guard let source = byID[sourceID] else {
            throw ChekinanaIdolChekiReorderError.changedRecords
        }
        let originalPartition = orderedIDs(values).filter {
            byID[$0]?.isFavorite == source.isFavorite && byID[$0]?.isTwoShot == source.isTwoShot
        }
        guard let sourceIndex = originalPartition.firstIndex(of: sourceID),
              originalPartition.indices.contains(targetIndex) else {
            throw ChekinanaIdolChekiReorderError.changedRecords
        }
        guard sourceIndex != targetIndex else { return [:] }

        var movedPartition = originalPartition
        movedPartition.remove(at: sourceIndex)
        movedPartition.insert(sourceID, at: targetIndex)
        let interval = min(sourceIndex, targetIndex)...max(sourceIndex, targetIndex)
        let ownedIndices = try originalPartition[interval].map { id -> Int in
            guard let value = byID[id],
                  let idx = value.idx,
                  ChekinanaChekiIndexing.isValid(idx, isFavorite: source.isFavorite) else {
                throw ChekinanaIdolChekiReorderError.changedRecords
            }
            return idx
        }.sorted()
        guard Set(ownedIndices).count == ownedIndices.count else {
            throw ChekinanaIdolChekiReorderError.changedRecords
        }
        return Dictionary(uniqueKeysWithValues: zip(movedPartition[interval], ownedIndices))
    }
}

@MainActor
enum ChekinanaUnifiedChekiReorderPersistence {
    @discardableResult
    static func reorder(
        moving sourceID: UUID,
        toPartitionIndex targetIndex: Int,
        values: [MediaItem],
        in modelContext: ModelContext,
        editIntentDirectory: URL? = nil,
        now: () -> Date = Date.init,
        saveContext: (ModelContext) throws -> Void = { try $0.save() }
    ) throws -> [UUID] {
        try ChekinanaLibraryMutationProtocol.withExclusiveOperationSync {
            try ChekinanaPersistenceMutationCoordinator.withLock {
                do {
                    try ChekinanaChekiEditRecovery.requireConvergedExclusively(
                        in: modelContext,
                        directory: editIntentDirectory
                    )
                    let orderSnapshots = try values.map { value in
                        guard value.modelContext === modelContext else {
                            throw ChekinanaIdolChekiReorderError.changedRecords
                        }
                        return ChekinanaUnifiedChekiOrderSnapshot(
                            id: value.id,
                            isFavorite: value.isFavorite,
                            idx: value.idx,
                            createdAt: value.createdAt,
                            isTwoShot: value.userAppears
                        )
                    }
                    let orderedIDs = try ChekinanaUnifiedChekiOrderPolicy.reorderedIDs(
                        moving: sourceID,
                        toPartitionIndex: targetIndex,
                        values: orderSnapshots
                    )
                    let assignments = try ChekinanaUnifiedChekiOrderPolicy
                        .minimalIndexAssignments(
                            moving: sourceID,
                            toPartitionIndex: targetIndex,
                            values: orderSnapshots
                        )
                    let liveSnapshots = try values.map { value in
                        guard let groupIdentity = ChekinanaIdolChekiReorderGroupIdentity(
                            idolIDs: value.idolIDs,
                            date: value.date) else {
                            throw ChekinanaIdolChekiReorderError.changedRecords
                        }
                        return ChekinanaIdolChekiReorderSnapshot(
                            chekiID: value.id,
                            groupIdentity: groupIdentity,
                            idx: value.idx
                        )
                    }
                    guard Set(liveSnapshots.map(\.group)).count == 1 else {
                        throw ChekinanaIdolChekiReorderError.mixedGroups
                    }
                    let allIndices = liveSnapshots.compactMap(\.idx)
                    guard allIndices.count == liveSnapshots.count,
                          Set(allIndices).count == allIndices.count,
                          liveSnapshots.allSatisfy({ snapshot in
                              guard let value = values.first(where: {
                                  $0.id == snapshot.chekiID
                              }) else { return false }
                              return ChekinanaChekiIndexing.isValid(
                                  snapshot.idx,
                                  isFavorite: value.isFavorite
                              )
                          }) else {
                        throw ChekinanaIdolChekiReorderError.changedRecords
                    }
                    let liveByID = Dictionary(
                        uniqueKeysWithValues: values.map { ($0.id, $0) }
                    )
                    guard assignments.keys.allSatisfy({ liveByID[$0] != nil }) else {
                        throw ChekinanaIdolChekiReorderError.changedRecords
                    }
                    for (id, idx) in assignments {
                        if liveByID[id]?.idx != idx { liveByID[id]?.idx = idx }
                    }
                    try saveContext(modelContext)
                    return orderedIDs
                } catch {
                    modelContext.rollback()
                    throw error
                }
            }
        }
    }
}

enum ChekinanaUnifiedChekiRowLayout {
    static let thumbnailHeight: CGFloat = 62
    static let verticalPadding: CGFloat = 8
    static let rowStride = thumbnailHeight + verticalPadding * 2
    static let horizontalPadding: CGFloat = 20
}

enum ChekinanaChekiRecordListCopy {
    static func title(bundle: Bundle? = nil) -> String {
        ChekinanaProductCopy.text(
            "calendar.simple_record",
            "Cheki record",
            bundle: bundle
        )
    }

    static func noteStatus(
        note: String,
        bundle: Bundle? = nil
    ) -> String {
        note.nonEmpty == nil
            ? ChekinanaProductCopy.text(
                "common.no_note",
                "No note",
                bundle: bundle
            )
            : note
    }
}

private struct ChekinanaUnifiedChekiGroupRows: View {
    @Environment(\.modelContext) private var modelContext
    let group: ChekinanaCalendarIdolGroup
    let selectCheki: (MediaItem) -> Void
    let selectRecord: (ChekiRecord) -> Void
    let reportReorderError: (Error) -> Void
    var allowsReordering = true
    var showsRecords = true
    @State private var committedOrderIDs: [UUID] = []
    @StateObject private var thumbnailHandoff = ChekinanaReorderThumbnailHandoff()

    private var orderSnapshots: [ChekinanaUnifiedChekiOrderSnapshot] {
        group.chekis.map {
            .init(
                id: $0.id,
                isFavorite: $0.isFavorite,
                idx: $0.idx,
                createdAt: $0.createdAt,
                isTwoShot: $0.userAppears
            )
        }
    }

    private var canonicalOrderIDs: [UUID] {
        ChekinanaUnifiedChekiOrderPolicy.orderedIDs(orderSnapshots)
    }

    private var renderOrder: (canonical: [UUID], base: [UUID], ordered: [MediaItem]) {
        let byID = Dictionary(uniqueKeysWithValues: group.chekis.map { ($0.id, $0) })
        let canonicalIDs = canonicalOrderIDs
        let liveIDs = Set(canonicalIDs)
        let retainedIDs = committedOrderIDs.filter(liveIDs.contains)
        func reconciledPartition(isFavorite: Bool) -> [UUID] {
            let retained = retainedIDs.filter {
                byID[$0]?.isFavorite == isFavorite
            }
            let retainedSet = Set(retained)
            return retained + canonicalIDs.filter {
                byID[$0]?.isFavorite == isFavorite
                    && !retainedSet.contains($0)
            }
        }
        let favoriteIDs = reconciledPartition(isFavorite: true)
        let standardIDs = reconciledPartition(isFavorite: false)
        let base = favoriteIDs + standardIDs
        let orderedFavorites = ChekinanaShotDisplayOrdering.chekis(
            favoriteIDs.compactMap { byID[$0] }
        )
        let orderedStandard = ChekinanaShotDisplayOrdering.chekis(
            standardIDs.compactMap { byID[$0] }
        )
        return (canonicalIDs, base, orderedFavorites + orderedStandard)
    }

    private var committedBaseOrderIDs: [UUID] { renderOrder.base }
    private var orderedChekis: [MediaItem] { renderOrder.ordered }

    private struct PartitionKey: Hashable {
        let identity: ChekinanaIdolChekiReorderGroupIdentity
        let isFavorite: Bool
        let isTwoShot: Bool
    }

    private struct RenderPartition {
        let orderedIDs: [UUID]
        let orderedItemKeys: [String]
    }

    private func renderPartitions(_ values: [MediaItem]) -> [UUID: RenderPartition] {
        var groups: [PartitionKey: [MediaItem]] = [:]
        for item in values {
            guard let identity = ChekinanaIdolChekiReorderGroupIdentity(
                idolIDs: item.idolIDs, date: item.date) else { continue }
            groups[PartitionKey(identity: identity, isFavorite: item.isFavorite, isTwoShot: item.userAppears), default: []].append(item)
        }
        var byID: [UUID: RenderPartition] = [:]
        for partition in groups.values {
            let ids = partition.map(\.id)
            let snapshot = RenderPartition(
                orderedIDs: ids, orderedItemKeys: ids.map { $0.uuidString.lowercased() }
            )
            for id in ids { byID[id] = snapshot }
        }
        return byID
    }

    @AppStorage(ChekinanaShotDisplayOrdering.defaultsKey) private var twoShotFirst = false

    var body: some View {
        let _ = twoShotFirst
        let order = allowsReordering ? renderOrder : nil
        let rows = order?.ordered ?? group.chekis
        let partitions = allowsReordering ? renderPartitions(rows) : [:]
        ForEach(rows) { cheki in
            mediaRow(cheki)
            .contentShape(Rectangle())
            .accessibilityElement(children: .combine)
            .accessibilityAddTraits(.isButton)
            .accessibilityAction { selectCheki(cheki) }
            .accessibilityIdentifier(
                "chekinana.cheki-list.media.\(cheki.id.uuidString.lowercased())"
            )
            .padding(.horizontal, ChekinanaUnifiedChekiRowLayout.horizontalPadding)
            .frame(height: ChekinanaUnifiedChekiRowLayout.rowStride)
            .listRowInsets(EdgeInsets())
            .listRowSeparator(.visible, edges: .all)
            .overlay {
                if allowsReordering, let partition = partitions[cheki.id] {
                    ChekinanaSnapshotReorderGestureSurface(
                        scopeKey: reorderScopeKey(
                            for: cheki,
                            partitionIsFavorite: cheki.isFavorite
                        ),
                        itemKey: cheki.id.uuidString.lowercased(),
                        orderedItemKeys: partition.orderedItemKeys,
                        requiresAllItemsVisible: false,
                        onTap: { _, _ in selectCheki(cheki) },
                        onReorderEnded: { targetIndex in
                            commitSnapshotReorder(
                                cheki,
                                targetPartitionIndex: targetIndex,
                                expectedPartitionIDs: partition.orderedIDs
                            )
                        },
                        onDebugState: { _ in }
                    )
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .allowsHitTesting(true)
                    .accessibilityHidden(true)
                } else if !allowsReordering {
                    Button { selectCheki(cheki) } label: {
                        Color.clear.contentShape(Rectangle())
                    }
                    .buttonStyle(.plain)
                    .accessibilityHidden(true)
                }
            }
        }
        .onChange(of: order?.canonical) { _, newOrderIDs in
            guard allowsReordering, let newOrderIDs else { return }
            committedOrderIDs = newOrderIDs
        }

        ForEach(showsRecords ? group.records : []) { record in
            Button { selectRecord(record) } label: {
                HStack(spacing: 12) {
                    Image(systemName: "doc.text")
                        .foregroundStyle(ChekinanaProductTheme.accent)
                        .frame(width: 50, height: 44)
                    VStack(alignment: .leading, spacing: 3) {
                        Text(ChekinanaChekiRecordListCopy.title())
                        .font(.subheadline.weight(.semibold))
                        .foregroundStyle(.primary)
                        .lineLimit(1)
                        Text(
                            ChekinanaChekiRecordListCopy.noteStatus(
                                note: record.note
                            )
                        )
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                    }
                    Spacer(minLength: 8)
                    Text(
                        ChekinanaRecordKind.cheki.countLabel(
                            ChekinanaDisplayCount.normalized(record.count)
                        )
                    )
                    .font(.caption.monospacedDigit())
                    .foregroundStyle(.secondary)
                    Image(systemName: "chevron.right")
                        .font(.caption)
                        .foregroundStyle(.tertiary)
                }
                .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .accessibilityIdentifier(
                "chekinana.cheki-list.record.\(record.id.uuidString.lowercased())"
            )
        }
    }

    private func mediaRow(_ cheki: MediaItem) -> some View {
        HStack(spacing: 12) {
            ChekinanaCalendarThumbnail(cheki: cheki, tracksReorderPreview: allowsReordering, handoff: thumbnailHandoff)
            VStack(alignment: .leading, spacing: 3) {
                Text(ChekinanaRecordKind.cheki.title)
                    .font(.subheadline.weight(.semibold))
                    .foregroundStyle(.primary)
                    .lineLimit(1)
                Text(
                    cheki.note.nonEmpty
                        ?? ChekinanaProductCopy.text(
                            "common.no_note",
                            "No note"
                        )
                )
                .font(.caption)
                .foregroundStyle(.secondary)
                .lineLimit(1)
            }
            Spacer(minLength: 8)
            if cheki.isFavorite {
                Image(systemName: "star.fill")
                    .font(.caption)
                    .foregroundStyle(ChekinanaProductTheme.accent)
            }
            Image(systemName: "chevron.right")
                .font(.caption)
                .foregroundStyle(.tertiary)
        }
        .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
    }

    private func commitSnapshotReorder(
        _ cheki: MediaItem,
        targetPartitionIndex: Int,
        expectedPartitionIDs: [UUID]
    ) {
        guard let partition = reorderPartition(containing: cheki),
              partition.map(\.id) == expectedPartitionIDs,
              partition.indices.contains(targetPartitionIndex),
              partition[targetPartitionIndex].id != cheki.id else { return }
        do {
            let reorderedPartitionIDs = try ChekinanaUnifiedChekiReorderPersistence.reorder(
                moving: cheki.id,
                toPartitionIndex: targetPartitionIndex,
                values: partition,
                in: modelContext
            )
            let partitionIDSet = Set(reorderedPartitionIDs)
            var reorderedIterator = reorderedPartitionIDs.makeIterator()
            committedOrderIDs = committedBaseOrderIDs.map { id in
                partitionIDSet.contains(id) ? (reorderedIterator.next() ?? id) : id
            }
        } catch {
            reportReorderError(error)
        }
    }

    private func reorderPartition(
        containing cheki: MediaItem
    ) -> [MediaItem]? {
        guard let identity = ChekinanaIdolChekiReorderGroupIdentity(
            idolIDs: cheki.idolIDs,
            date: cheki.date) else { return nil }
        let values = orderedChekis.filter { candidate in
            candidate.isFavorite == cheki.isFavorite && candidate.userAppears == cheki.userAppears
                && ChekinanaIdolChekiReorderGroupIdentity(
                    idolIDs: candidate.idolIDs,
                    date: candidate.date) == identity
        }
        return values.contains(where: { $0.id == cheki.id }) ? values : nil
    }

    private func reorderScopeKey(
        for cheki: MediaItem,
        partitionIsFavorite: Bool
    ) -> String {
        let dateKey = cheki.date.map(ChekinanaDateOnly.string) ?? "undated"
        let idolKey = Set(cheki.idolIDs).sorted {
            $0.uuidString < $1.uuidString
        }
        .map { $0.uuidString.lowercased() }
        .joined(separator: "+")
        return "cheki|\(group.id)|\(dateKey)|\(idolKey)|favorite:\(partitionIsFavorite)|shot:\(cheki.userAppears)"
    }
}

