enum ChekinanaZoomPanGeometry {
    static let minimumScale: CGFloat = 1
    static let maximumScale: CGFloat = 4

    static func clampedScale(_ scale: CGFloat, maximum: CGFloat = maximumScale) -> CGFloat {
        guard scale.isFinite else { return minimumScale }
        return min(maximum.isFinite ? max(minimumScale, maximum) : maximumScale, max(minimumScale, scale))
    }

    static func scaleApplyingIncrementalMagnification(
        currentScale: CGFloat,
        magnification: CGFloat,
        previousMagnification: CGFloat,
        maximum: CGFloat = maximumScale
    ) -> CGFloat {
        guard magnification.isFinite,
              previousMagnification.isFinite,
              magnification > 0,
              previousMagnification > 0 else {
            return clampedScale(currentScale, maximum: maximum)
        }
        return clampedScale(
            clampedScale(currentScale, maximum: maximum) * magnification / previousMagnification, maximum: maximum
        )
    }

    static func aspectFitSize(
        imageSize: CGSize,
        viewportSize: CGSize
    ) -> CGSize {
        guard isValid(imageSize), isValid(viewportSize) else { return .zero }
        let fitScale = min(
            viewportSize.width / imageSize.width,
            viewportSize.height / imageSize.height
        )
        guard fitScale.isFinite, fitScale > 0 else { return .zero }
        let fitted = CGSize(
            width: imageSize.width * fitScale,
            height: imageSize.height * fitScale
        )
        return isFinite(fitted) ? fitted : .zero
    }

    static func clampedOffset(
        _ offset: CGSize,
        imageSize: CGSize,
        viewportSize: CGSize,
        scale: CGFloat,
        maximum: CGFloat = maximumScale
    ) -> CGSize {
        let scale = clampedScale(scale, maximum: maximum)
        guard isValid(imageSize),
              isValid(viewportSize),
              scale > minimumScale,
              offset.width.isFinite,
              offset.height.isFinite else { return .zero }
        let fitted = aspectFitSize(
            imageSize: imageSize,
            viewportSize: viewportSize
        )
        // Preserve a pinch anchor inside the initially fitted image, including
        // its letterboxed axis. Using the whole viewport here forces that axis
        // back to the image center until the enlarged image fills the viewport.
        let maximumX = max(0, fitted.width * (scale - minimumScale) / 2)
        let maximumY = max(0, fitted.height * (scale - minimumScale) / 2)
        return CGSize(
            width: min(maximumX, max(-maximumX, offset.width)),
            height: min(maximumY, max(-maximumY, offset.height))
        )
    }

    /// Consume image panning first. A projected page gesture is valid only
    /// after the real finger position reaches the horizontal image boundary.
    static func pageDragRelease(
        translation: CGSize,
        predictedEndTranslation: CGSize,
        initialOffset: CGSize,
        imageSize: CGSize,
        viewportSize: CGSize,
        scale: CGFloat,
        maximum: CGFloat = maximumScale
    ) -> ChekinanaMediaPagerDragRelease {
        let zero = ChekinanaMediaPagerDragRelease(translation: 0, predictedEndTranslation: 0)
        guard isValid(imageSize), isValid(viewportSize),
              isFinite(translation), isFinite(predictedEndTranslation),
              isFinite(initialOffset),
              abs(translation.width) > abs(translation.height) else { return zero }
        let start = clampedOffset(initialOffset, imageSize: imageSize, viewportSize: viewportSize, scale: scale, maximum: maximum)
        let proposed = CGSize(width: start.width + translation.width, height: start.height + translation.height)
        let end = clampedOffset(proposed, imageSize: imageSize, viewportSize: viewportSize, scale: scale, maximum: maximum)
        let consumed = end.width - start.width
        let remainder = translation.width - consumed
        let limit = max(0, aspectFitSize(imageSize: imageSize, viewportSize: viewportSize).width
            * (clampedScale(scale, maximum: maximum) - minimumScale) / 2)
        let reachedEdge = translation.width > 0 ? proposed.width >= limit : proposed.width <= -limit
        guard reachedEdge else { return zero }
        // Reversal toward the image may settle the page but must not project
        // through the opposite image edge during the same release.
        let projectedRemainder = predictedEndTranslation.width - consumed
        let compatibleProjection = translation.width > 0
            ? max(0, projectedRemainder) : min(0, projectedRemainder)
        return ChekinanaMediaPagerDragRelease(
            translation: remainder,
            predictedEndTranslation: compatibleProjection
        )
    }

    static func offsetKeepingAnchorFixed(
        _ offset: CGSize,
        from oldScale: CGFloat,
        to newScale: CGFloat,
        anchor: UnitPoint,
        viewportSize: CGSize,
        maximum: CGFloat = maximumScale
    ) -> CGSize {
        guard isFinite(offset),
              isValid(viewportSize),
              anchor.x.isFinite,
              anchor.y.isFinite else { return .zero }
        let oldScale = clampedScale(oldScale, maximum: maximum)
        let newScale = clampedScale(newScale, maximum: maximum)
        guard oldScale > 0 else { return offset }
        let ratio = newScale / oldScale
        let anchorFromCenter = CGSize(
            width: (anchor.x - 0.5) * viewportSize.width,
            height: (anchor.y - 0.5) * viewportSize.height
        )
        let anchored = CGSize(
            width: ratio * offset.width + (1 - ratio) * anchorFromCenter.width,
            height: ratio * offset.height + (1 - ratio) * anchorFromCenter.height
        )
        return isFinite(anchored) ? anchored : .zero
    }

    private static func isValid(_ size: CGSize) -> Bool {
        isFinite(size) && size.width > 0 && size.height > 0
    }

    private static func isFinite(_ size: CGSize) -> Bool {
        size.width.isFinite && size.height.isFinite
    }
}

struct ChekinanaZoomViewportTransform: Equatable {
    var scale: CGFloat = ChekinanaZoomPanGeometry.minimumScale
    var offset: CGSize = .zero

    func imageOffset(compensatingPageTranslation pageTranslation: CGFloat) -> CGSize {
        guard scale > ChekinanaZoomPanGeometry.minimumScale + 0.001,
              pageTranslation.isFinite else { return offset }
        // The enclosing page already moves by this amount. Subtract only that
        // actual (possibly edge-damped) displacement, not the raw finger drag.
        return CGSize(width: offset.width - pageTranslation, height: offset.height)
    }

    mutating func reset() {
        self = Self()
    }
}

struct ChekinanaZoomViewportGestureHandoff: Equatable {
    var magnification: CGFloat = 1
    var anchor: UnitPoint = .center
    var translation: CGSize = .zero

    func effectiveTransform(
        from persistent: ChekinanaZoomViewportTransform,
        imageSize: CGSize,
        viewportSize: CGSize,
        maximumScale: CGFloat = ChekinanaZoomPanGeometry.maximumScale
    ) -> ChekinanaZoomViewportTransform {
        let scale = ChekinanaZoomPanGeometry.clampedScale(
            persistent.scale * magnification, maximum: maximumScale
        )
        let anchoredOffset = ChekinanaZoomPanGeometry.offsetKeepingAnchorFixed(
            persistent.offset,
            from: persistent.scale,
            to: scale,
            anchor: anchor,
            viewportSize: viewportSize,
            maximum: maximumScale
        )
        return ChekinanaZoomViewportTransform(
            scale: scale,
            offset: ChekinanaZoomPanGeometry.clampedOffset(
                CGSize(
                    width: anchoredOffset.width + translation.width,
                    height: anchoredOffset.height + translation.height
                ),
                imageSize: imageSize,
                viewportSize: viewportSize,
                scale: scale,
                maximum: maximumScale
            )
        )
    }
}

struct ChekinanaMediaDragLifecycle: Equatable {
    private(set) var hasPendingDrag = false

    mutating func changed() {
        hasPendingDrag = true
    }

    mutating func finish() {
        hasPendingDrag = false
    }

    /// GestureState also resets after a normal end. Only an unfinished drag
    /// may request cancellation, so that reset cannot undo a committed page.
    mutating func cancel() -> Bool {
        let shouldClear = hasPendingDrag
        hasPendingDrag = false
        return shouldClear
    }
}

private struct ChekinanaZoomPinchState {
    var magnification: CGFloat = 1
    var anchor: UnitPoint = .center
}

enum ChekinanaZoomInteractionResolution: CaseIterable, Equatable {
    case cleanTap
    case pan
    case pinch
    case panAndPinch

    var routesSingleTap: Bool {
        self == .cleanTap
    }
}

private struct ChekinanaEditableVideoPlayer: UIViewControllerRepresentable {
    let player: AVPlayer
    let onSingleTap: () -> Void

    func makeCoordinator() -> Coordinator {
        Coordinator(onSingleTap: onSingleTap)
    }

    func makeUIViewController(context: Context) -> AVPlayerViewController {
        let controller = AVPlayerViewController()
        controller.player = player
        controller.showsPlaybackControls = false
        controller.videoGravity = .resizeAspect
        controller.view.backgroundColor = .white
        let recognizer = UITapGestureRecognizer(
            target: context.coordinator,
            action: #selector(Coordinator.handleTap(_:))
        )
        recognizer.cancelsTouchesInView = false
        recognizer.delegate = context.coordinator
        controller.view.addGestureRecognizer(recognizer)
        return controller
    }

    func updateUIViewController(
        _ controller: AVPlayerViewController,
        context: Context
    ) {
        controller.player = player
        controller.view.backgroundColor = .white
        context.coordinator.onSingleTap = onSingleTap
    }

    final class Coordinator: NSObject, UIGestureRecognizerDelegate {
        var onSingleTap: () -> Void

        init(onSingleTap: @escaping () -> Void) {
            self.onSingleTap = onSingleTap
        }

        @objc func handleTap(_ recognizer: UITapGestureRecognizer) {
            guard recognizer.state == .ended else { return }
            onSingleTap()
        }

        func gestureRecognizer(
            _ gestureRecognizer: UIGestureRecognizer,
            shouldRecognizeSimultaneouslyWith otherGestureRecognizer: UIGestureRecognizer
        ) -> Bool {
            true
        }

        func gestureRecognizer(
            _ gestureRecognizer: UIGestureRecognizer,
            shouldReceive touch: UITouch
        ) -> Bool {
            var view: UIView? = touch.view
            while let current = view {
                if current is UIControl { return false }
                view = current.superview
            }
            return true
        }
    }
}

/// System playback chrome for read-only video previews. Keeping the player in
/// the surrounding SwiftUI view makes its lifetime explicit across covers.
private struct ChekinanaPlaybackVideoPlayer: UIViewControllerRepresentable {
    let player: AVPlayer

    func makeUIViewController(context: Context) -> AVPlayerViewController {
        let controller = AVPlayerViewController()
        controller.player = player
        controller.showsPlaybackControls = true
        controller.videoGravity = .resizeAspect
        controller.view.backgroundColor = .white
        return controller
    }

    func updateUIViewController(
        _ controller: AVPlayerViewController,
        context: Context
    ) {
        controller.player = player
        controller.view.backgroundColor = .white
    }
}

/// A shared aspect-fit image viewport whose zoom and pan state stays bounded.
/// Its gesture tree stays identical throughout a pinch. The viewport reports
/// only the horizontal motion left after panning to an image edge to the
/// pager. Pinching and vertical panning never initiate a page transition.
struct ChekinanaZoomableImageViewport<Content: View>: View {
    let imageSize: CGSize
    let resetID: AnyHashable
    let isActive: Bool
    let pageTranslation: CGFloat
    let maximumScale: CGFloat
    let onViewportChanged: (CGSize, ChekinanaZoomViewportTransform) -> Void
    let onZoomChanged: (Bool) -> Void
    let onHorizontalDragChanged: (CGFloat) -> Void
    let onHorizontalDragEnded: (ChekinanaMediaPagerDragRelease) -> Bool
    let onSingleTap: (() -> Void)?
    @ViewBuilder let content: () -> Content

    @State private var transform = ChekinanaZoomViewportTransform()
    @State private var dragLifecycle = ChekinanaMediaDragLifecycle()
    @State private var gestureHandoff: ChekinanaZoomViewportGestureHandoff?
    @State private var previousPinchMagnification: CGFloat = 1
    @State private var interactionIncludedPinch = false
    @GestureState private var pinch = ChekinanaZoomPinchState()
    @GestureState private var pinchIsActive = false
    @GestureState private var dragTranslation: CGSize = .zero
    @GestureState private var interactionIsActive = false

    init(
        imageSize: CGSize,
        resetID: AnyHashable,
        isActive: Bool = true,
        pageTranslation: CGFloat = 0,
        maximumScale: CGFloat = ChekinanaZoomPanGeometry.maximumScale,
        onViewportChanged: @escaping (CGSize, ChekinanaZoomViewportTransform) -> Void = { _, _ in },
        onZoomChanged: @escaping (Bool) -> Void = { _ in },
        onHorizontalDragChanged: @escaping (CGFloat) -> Void = { _ in },
        onHorizontalDragEnded: @escaping (ChekinanaMediaPagerDragRelease) -> Bool = { _ in false },
        onSingleTap: (() -> Void)? = nil,
        @ViewBuilder content: @escaping () -> Content
    ) {
        self.imageSize = imageSize
        self.resetID = resetID
        self.isActive = isActive
        self.pageTranslation = pageTranslation
        self.maximumScale = maximumScale
        self.onViewportChanged = onViewportChanged
        self.onZoomChanged = onZoomChanged
        self.onHorizontalDragChanged = onHorizontalDragChanged
        self.onHorizontalDragEnded = onHorizontalDragEnded
        self.onSingleTap = onSingleTap
        self.content = content
    }

    var body: some View {
        GeometryReader { geometry in
            let fallbackGesture = ChekinanaZoomViewportGestureHandoff(
                magnification: pinch.magnification,
                anchor: pinch.anchor,
                translation: dragTranslation
            )
            let liveTransform = (gestureHandoff ?? fallbackGesture)
                .effectiveTransform(
                    from: transform,
                    imageSize: imageSize,
                    viewportSize: geometry.size,
                    maximumScale: maximumScale
                )
            let liveScale = liveTransform.scale
            let isZoomed = liveScale > ChekinanaZoomPanGeometry.minimumScale + 0.001
            // The parent moves only by overflow beyond the image boundary.
            // Let this movement carry the edge with the outgoing page.
            let renderedOffset = liveTransform.offset
            let fittedSize = ChekinanaZoomPanGeometry.aspectFitSize(
                imageSize: imageSize,
                viewportSize: geometry.size
            )

            let surface = singleTapSurface(
                ZStack {
                    content()
                        .frame(width: fittedSize.width, height: fittedSize.height)
                        .scaleEffect(liveScale)
                        .offset(renderedOffset)
                }
                .contentShape(Rectangle())
            )
                .frame(
                    width: geometry.size.width,
                    height: geometry.size.height,
                    alignment: .center
                )
                .contentShape(Rectangle())

            interactionSurface(
                surface,
                viewportSize: geometry.size
            )
                .onChange(of: liveTransform, initial: true) { _, value in
                    onViewportChanged(geometry.size, value)
                }
                .onChange(of: geometry.size) { _, size in
                    onViewportChanged(size, liveTransform)
                }
                .onChange(of: isZoomed) { _, value in
                    onZoomChanged(value)
                }
        }
        .clipped()
        .onAppear { onZoomChanged(false) }
        .onDisappear { reset() }
        .onChange(of: interactionIsActive) { _, active in
            if !active {
                cancelPageDrag()
                gestureHandoff = nil
                previousPinchMagnification = 1
                interactionIncludedPinch = false
            }
        }
        .onChange(of: resetID) { _, _ in reset() }
        .onChange(of: isActive) { _, active in
            if !active { reset() }
        }
    }

    @ViewBuilder
    private func singleTapSurface<Surface: View>(
        _ surface: Surface
    ) -> some View {
        if let onSingleTap {
            surface.simultaneousGesture(
                TapGesture().onEnded { onSingleTap() }
            )
        } else {
            surface
        }
    }

    /// The same simultaneous pinch/pan gesture remains installed at every
    /// scale, preventing a state transition from cancelling an active pinch.
    private func interactionSurface<Surface: View>(
        _ surface: Surface,
        viewportSize: CGSize
    ) -> some View {
        surface.simultaneousGesture(
            interactionGesture(viewportSize: viewportSize)
        )
    }

    private func interactionGesture(
        viewportSize: CGSize
    ) -> some Gesture {
        let magnify = MagnifyGesture()
            .updating($pinch) { value, state, _ in
                state.magnification = value.magnification
                state.anchor = value.startAnchor
            }
            .updating($pinchIsActive) { _, state, _ in
                state = true
            }
            .onChanged { value in
                interactionIncludedPinch = true
                var handoff = gestureHandoff
                    ?? ChekinanaZoomViewportGestureHandoff(
                        magnification: 1,
                        anchor: value.startAnchor,
                        translation: dragTranslation
                    )
                let currentScale = ChekinanaZoomPanGeometry.clampedScale(
                    transform.scale * handoff.magnification, maximum: maximumScale
                )
                let scale = ChekinanaZoomPanGeometry
                    .scaleApplyingIncrementalMagnification(
                        currentScale: currentScale,
                        magnification: value.magnification,
                        previousMagnification: previousPinchMagnification,
                        maximum: maximumScale
                    )
                handoff.magnification = scale / transform.scale
                handoff.anchor = value.startAnchor
                gestureHandoff = handoff
                previousPinchMagnification = value.magnification
                cancelPageDrag()
            }
        let pan = DragGesture(minimumDistance: 4, coordinateSpace: .global)
            .updating($dragTranslation) { value, state, _ in
                state = value.translation
            }
            .onChanged { value in
                var handoff = gestureHandoff
                    ?? ChekinanaZoomViewportGestureHandoff(
                        magnification: pinch.magnification,
                        anchor: pinch.anchor,
                        translation: dragTranslation
                    )
                handoff.translation = value.translation
                gestureHandoff = handoff
                guard isActive, !pinchIsActive, !interactionIncludedPinch else {
                    cancelPageDrag()
                    return
                }
                dragLifecycle.changed()
                let release = ChekinanaZoomPanGeometry.pageDragRelease(
                    translation: value.translation,
                    predictedEndTranslation: value.translation,
                    initialOffset: transform.offset,
                    imageSize: imageSize,
                    viewportSize: viewportSize,
                    scale: transform.scale,
                    maximum: maximumScale
                )
                onHorizontalDragChanged(release.translation)
            }
        return magnify
            .simultaneously(with: pan)
            .updating($interactionIsActive) { _, state, _ in
                state = true
            }
            .onEnded { zoomOrPan in
                dragLifecycle.finish()
                previousPinchMagnification = 1
                guard isActive else { return }
                // Commit the image pan and settle the enclosing page in the
                // same transaction, including a below-threshold release.
                withAnimation(
                    .interactiveSpring(response: 0.28, dampingFraction: 0.9)
                ) {
                    commitZoomOrPan(
                        magnification: zoomOrPan.first,
                        pan: zoomOrPan.second,
                        gestureHandoff: gestureHandoff,
                        viewportSize: viewportSize
                    )
                    gestureHandoff = nil
                }
            }
    }

    private func commitZoomOrPan(
        magnification: MagnifyGesture.Value?,
        pan: DragGesture.Value?,
        gestureHandoff: ChekinanaZoomViewportGestureHandoff?,
        viewportSize: CGSize
    ) {
        let resolution: ChekinanaZoomInteractionResolution
        switch (magnification != nil, pan != nil) {
        case (true, true): resolution = .panAndPinch
        case (true, false): resolution = .pinch
        case (false, true): resolution = .pan
        case (false, false): return
        }
        guard !resolution.routesSingleTap else { return }

        if resolution == .pan, !interactionIncludedPinch,
           let pan,
           onHorizontalDragEnded(ChekinanaZoomPanGeometry.pageDragRelease(
            translation: pan.translation,
            predictedEndTranslation: pan.predictedEndTranslation,
            initialOffset: transform.offset,
            imageSize: imageSize,
            viewportSize: viewportSize,
            scale: transform.scale,
                    maximum: maximumScale
           )) {
            reset()
            return
        }
        if resolution != .pan || interactionIncludedPinch {
            onHorizontalDragChanged(0)
        }

        let committed = (gestureHandoff ?? ChekinanaZoomViewportGestureHandoff(
            magnification: magnification?.magnification ?? 1,
            anchor: magnification?.startAnchor ?? .center,
            translation: pan?.translation ?? .zero
        )).effectiveTransform(
            from: transform,
            imageSize: imageSize,
            viewportSize: viewportSize,
            maximumScale: maximumScale
        )
        transform = committed
        if committed.scale <= ChekinanaZoomPanGeometry.minimumScale + 0.001 {
            reset()
        }
    }

    private func cancelPageDrag() {
        if dragLifecycle.cancel() {
            onHorizontalDragChanged(0)
        }
    }

    private func reset() {
        cancelPageDrag()
        gestureHandoff = nil
        previousPinchMagnification = 1
        interactionIncludedPinch = false
        transform.reset()
        onZoomChanged(false)
    }
}

private struct ChekinanaEventImageViewerSelection: Identifiable {
    let id: UUID
}

private struct ChekinanaEventImageThumbnail: View {
    let record: EventImage

    var body: some View {
        Group {
            if let image = ChekinanaEventImageStore.image(for: record.imageRef) {
                Image(uiImage: image)
                    .resizable()
                    .scaledToFill()
            } else {
                VStack(spacing: 8) {
                    Image(systemName: "photo.badge.exclamationmark")
                        .font(.title2)
                    Text(ChekinanaProductCopy.text(
                        "events.image.unavailable",
                        "Image unavailable"
                    ))
                    .font(.caption)
                }
                .foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.secondary.opacity(0.08))
            }
        }
        .frame(width: 165, height: 220)
        .clipped()
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .contentShape(Rectangle())
    }
}

private struct ChekinanaEventImageViewer: View {
    @Environment(\.dismiss) private var dismiss
    let images: [EventImage]
    @State private var selectedID: UUID?
    @State private var selectedImageIsZoomed = false

    init(images: [EventImage], initialID: UUID) {
        self.images = images
        _selectedID = State(initialValue: ChekinanaMediaPagerPolicy.initialID(
            requested: initialID,
            available: images.map(\.id)
        ))
    }

    var body: some View {
        ZStack(alignment: .topTrailing) {
            ChekinanaProductTheme.pageBackground.ignoresSafeArea()
            if images.isEmpty {
                ChekinanaEmptyState(
                    title: ChekinanaProductCopy.text(
                        "events.image.unavailable",
                        "Image unavailable"
                    ),
                    message: "",
                    systemImage: "photo.badge.exclamationmark"
                )
            } else {
                ChekinanaFullScreenMediaPager(
                    items: images,
                    selectedID: $selectedID,
                    usesEmbeddedPagingGesture: true,
                    showsPageIndicator: images.count > 1
                ) { record, _, pageInteraction in
                    ChekinanaEventZoomableImage(
                        record: record,
                        isActive: selectedID == record.id,
                        pageTranslation: pageInteraction.translation,
                        onHorizontalDragChanged: pageInteraction.dragChanged,
                        onHorizontalDragEnded: pageInteraction.dragEnded,
                        onZoomChanged: { isZoomed in
                            guard selectedID == record.id else { return }
                            selectedImageIsZoomed = isZoomed
                        }
                    )
                }
                .accessibilityIdentifier("chekinana.events.image-viewer.pages")
            }

            Button { dismiss() } label: {
                Image(systemName: "xmark")
                    .font(.headline)
                    .foregroundStyle(.primary)
                    .frame(width: 44, height: 44)
                    .background(
                        Color(uiColor: .secondarySystemGroupedBackground),
                        in: Circle()
                    )
            }
            .buttonStyle(.plain)
            .accessibilityLabel(ChekinanaProductCopy.text("common.close", "Close"))
            .accessibilityIdentifier("chekinana.events.image-viewer.close")
            .padding(16)
        }
        .simultaneousGesture(DragGesture(minimumDistance: 36).onEnded { value in
            guard !selectedImageIsZoomed else { return }
            guard abs(value.translation.height) > abs(value.translation.width),
                  value.translation.height > 100 else { return }
            dismiss()
        })
        .onChange(of: selectedID) { _, _ in
            selectedImageIsZoomed = false
        }
        .onChange(of: images.map(\.id)) { _, ids in
            selectedID = ChekinanaMediaPagerPolicy.initialID(
                requested: selectedID,
                available: ids
            )
            if ids.isEmpty { dismiss() }
        }
        .accessibilityIdentifier("chekinana.events.image-viewer")
    }
}

private struct ChekinanaEventZoomableImage: View {
    let record: EventImage
    let isActive: Bool
    let pageTranslation: CGFloat
    let onHorizontalDragChanged: (CGFloat) -> Void
    let onHorizontalDragEnded: (ChekinanaMediaPagerDragRelease) -> Bool
    let onZoomChanged: (Bool) -> Void

    var body: some View {
        Group {
            if let image = ChekinanaEventImageStore.image(for: record.imageRef) {
                ChekinanaZoomableImageViewport(
                    imageSize: image.size,
                    resetID: record.imageRef,
                    isActive: isActive,
                    pageTranslation: pageTranslation,
                    onZoomChanged: onZoomChanged,
                    onHorizontalDragChanged: onHorizontalDragChanged,
                    onHorizontalDragEnded: onHorizontalDragEnded
                ) {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFit()
                }
            } else {
                ContentUnavailableView(
                    ChekinanaProductCopy.text(
                        "events.image.unavailable",
                        "Image unavailable"
                    ),
                    systemImage: "photo.badge.exclamationmark"
                )
                .foregroundStyle(.primary)
            }
        }
        .accessibilityIdentifier(
            "chekinana.events.image-viewer.image.\(record.id.uuidString.lowercased())"
        )
    }
}

private struct ChekinanaEventImageDraft: Identifiable, Equatable {
    enum Origin: Equatable {
        case existing(recordID: UUID)
        case parsed(generation: UInt64, index: Int)
        case photoLibrary
    }

    let id = UUID()
    let ref: String
    let origin: Origin

    var isNew: Bool {
        guard case .existing = origin else { return true }
        return false
    }

    var recordID: UUID? {
        guard case .existing(let recordID) = origin else { return nil }
        return recordID
    }

    var parsedMetadata: (generation: UInt64, index: Int)? {
        guard case .parsed(let generation, let index) = origin else { return nil }
        return (generation, index)
    }

    static func restoringExisting(
        _ values: [ChekinanaEventImageValue],
        preserving drafts: [Self]
    ) throws -> [Self] {
        let existing = try values.map { value -> Self in
            guard let id = value.id else {
                throw ChekinanaEventPersistence.PersistenceError.invalidImages
            }
            return .init(ref: value.imageRef, origin: .existing(recordID: id))
        }
        let pending = drafts.filter(\.isNew)
        guard existing.count + pending.count <= ChekinanaEventImageStore.maximumImageCount else {
            throw ChekinanaEventPersistence.PersistenceError.invalidImages
        }
        return existing + pending
    }
}

struct ChekinanaEventSaveGate: Equatable, Sendable {
    private(set) var generation: UInt64 = 0
    private(set) var inFlightToken: UInt64?

    var isInFlight: Bool { inFlightToken != nil }

    mutating func begin() -> UInt64? {
        guard inFlightToken == nil else { return nil }
        generation &+= 1
        inFlightToken = generation
        return generation
    }

    func accepts(_ token: UInt64, isCancelled: Bool = false) -> Bool {
        !isCancelled && inFlightToken == token && generation == token
    }

    @discardableResult
    mutating func finish(_ token: UInt64) -> Bool {
        guard accepts(token) else { return false }
        inFlightToken = nil
        return true
    }

    mutating func cancelIfIdle() -> Bool {
        guard inFlightToken == nil else { return false }
        generation &+= 1
        return true
    }
}

enum ChekinanaEventEditorParsedField: CaseIterable, Hashable, Sendable {
    case name
    case date
    case openTime
    case startTime
    case city
    case livehouse
    case address
    case price
    case weiboURL
    case ticketURL
    case avatar
}

struct ChekinanaEventEditorFieldRevisionSnapshot: Equatable, Sendable {
    fileprivate let revisions: [ChekinanaEventEditorParsedField: UInt64]

    func revision(for field: ChekinanaEventEditorParsedField) -> UInt64 {
        revisions[field, default: 0]
    }
}

struct ChekinanaEventEditorFieldRevisions: Equatable, Sendable {
    private(set) var userEditRevision: UInt64 = 0
    private var revisions: [ChekinanaEventEditorParsedField: UInt64] = [:]

    mutating func recordUserEdit(_ field: ChekinanaEventEditorParsedField) {
        userEditRevision &+= 1
        revisions[field] = userEditRevision
    }

    func revision(for field: ChekinanaEventEditorParsedField) -> UInt64 {
        revisions[field, default: 0]
    }

    func snapshot() -> ChekinanaEventEditorFieldRevisionSnapshot {
        ChekinanaEventEditorFieldRevisionSnapshot(revisions: revisions)
    }

    func isUnedited(
        _ field: ChekinanaEventEditorParsedField,
        since snapshot: ChekinanaEventEditorFieldRevisionSnapshot
    ) -> Bool {
        revision(for: field) == snapshot.revision(for: field)
    }
}

struct ChekinanaEventEditorParseRequest: Equatable, Sendable {
    let generation: UInt64
    let sourceIdentity: String
    let editorOwnerID: UUID
    let fieldRevisions: ChekinanaEventEditorFieldRevisionSnapshot
}

struct ChekinanaEventEditorParseCoordinator: Equatable, Sendable {
    private(set) var editorOwnerID: UUID
    private(set) var generation: UInt64 = 0
    private(set) var activeRequest: ChekinanaEventEditorParseRequest?
    private(set) var publishedContentMetadata:
        ChekinanaEventCandidateContentMetadata?
    private(set) var publishedSourceIdentity: String?
    private(set) var isEditorActive = true
    private(set) var fieldRevisions = ChekinanaEventEditorFieldRevisions()

    init(editorOwnerID: UUID = UUID()) {
        self.editorOwnerID = editorOwnerID
    }

    mutating func activateIfNeeded(newOwnerID: UUID = UUID()) {
        guard !isEditorActive else { return }
        editorOwnerID = newOwnerID
        isEditorActive = true
        activeRequest = nil
        publishedContentMetadata = nil
        publishedSourceIdentity = nil
    }

    mutating func recordUserEdit(_ field: ChekinanaEventEditorParsedField) {
        fieldRevisions.recordUserEdit(field)
    }

    mutating func begin(sourceIdentity: String) -> ChekinanaEventEditorParseRequest {
        generation &+= 1
        let request = ChekinanaEventEditorParseRequest(
            generation: generation,
            sourceIdentity: sourceIdentity,
            editorOwnerID: editorOwnerID,
            fieldRevisions: fieldRevisions.snapshot()
        )
        activeRequest = request
        publishedContentMetadata = nil
        publishedSourceIdentity = nil
        return request
    }

    func accepts(
        _ request: ChekinanaEventEditorParseRequest,
        currentSourceIdentity: String,
        isCancelled: Bool
    ) -> Bool {
        !isCancelled
            && owns(request)
            && request.sourceIdentity == currentSourceIdentity
    }

    func owns(_ request: ChekinanaEventEditorParseRequest) -> Bool {
        isEditorActive
            && request.editorOwnerID == editorOwnerID
            && request.generation == generation
            && activeRequest == request
    }

    func shouldApply(
        _ field: ChekinanaEventEditorParsedField,
        from request: ChekinanaEventEditorParseRequest,
        currentSourceIdentity: String,
        isCancelled: Bool = false
    ) -> Bool {
        accepts(
            request,
            currentSourceIdentity: currentSourceIdentity,
            isCancelled: isCancelled
        ) && fieldRevisions.isUnedited(field, since: request.fieldRevisions)
    }

    @discardableResult
    mutating func publishContentMetadata(
        _ metadata: ChekinanaEventCandidateContentMetadata,
        from request: ChekinanaEventEditorParseRequest,
        currentSourceIdentity: String,
        isCancelled: Bool = false
    ) -> Bool {
        guard accepts(
            request,
            currentSourceIdentity: currentSourceIdentity,
            isCancelled: isCancelled
        ) else { return false }
        publishedContentMetadata = metadata
        publishedSourceIdentity = request.sourceIdentity
        return true
    }

    func contentMetadata(
        currentSourceIdentity: String
    ) -> ChekinanaEventCandidateContentMetadata? {
        guard publishedSourceIdentity == currentSourceIdentity else { return nil }
        return publishedContentMetadata
    }

    @discardableResult
    mutating func finish(_ request: ChekinanaEventEditorParseRequest) -> Bool {
        guard owns(request) else { return false }
        activeRequest = nil
        return true
    }

    mutating func invalidateRequest() {
        generation &+= 1
        activeRequest = nil
        publishedContentMetadata = nil
        publishedSourceIdentity = nil
    }

    @discardableResult
    mutating func closeEditor() -> Bool {
        guard isEditorActive else { return false }
        generation &+= 1
        activeRequest = nil
        publishedContentMetadata = nil
        publishedSourceIdentity = nil
        isEditorActive = false
        return true
    }
}

enum ChekinanaEventContentWarningPresentation {
    static func message(
        for metadata: ChekinanaEventCandidateContentMetadata
    ) -> String? {
        switch metadata.completeness {
        case .complete:
            nil
        case .incomplete:
            ChekinanaProductCopy.text(
                "events.content_incomplete_warning",
                "Only part of the source content was available. Review the parsed Event details before saving."
            )
        case .unknown:
            ChekinanaProductCopy.text(
                "events.content_unknown_warning",
                "Source content completeness could not be verified. Review the parsed Event details before saving."
            )
        }
    }
}

enum ChekinanaEventAvatarSelectionInvalidationReason: Equatable, Sendable {
    case pickerCancelled
    case selectionReplaced
    case avatarCleared
    case parseReplacedSelection
    case editorExited
}

struct ChekinanaEventAvatarSelectionOwner: Equatable, Sendable {
    let generation: UInt64
    let selectionID: UUID
}

struct ChekinanaEventAvatarSelectionState: Equatable, Sendable {
    private enum Phase: Equatable, Sendable {
        case idle
        case preparing
        case ready
        case failed(String)
    }

    private(set) var generation: UInt64 = 0
    private(set) var owner: ChekinanaEventAvatarSelectionOwner?
    private(set) var taskOwner: ChekinanaEventAvatarSelectionOwner?
    private(set) var lastInvalidationReason:
        ChekinanaEventAvatarSelectionInvalidationReason?
    private var phase = Phase.idle

    var isPreparing: Bool { phase == .preparing }

    var failureMessage: String? {
        guard case .failed(let message) = phase else { return nil }
        return message
    }

    @discardableResult
    mutating func begin(
        selectionID: UUID = UUID()
    ) -> ChekinanaEventAvatarSelectionOwner {
        generation &+= 1
        let owner = ChekinanaEventAvatarSelectionOwner(
            generation: generation,
            selectionID: selectionID
        )
        self.owner = owner
        taskOwner = owner
        lastInvalidationReason = nil
        phase = .preparing
        return owner
    }

    func owns(_ candidateOwner: ChekinanaEventAvatarSelectionOwner) -> Bool {
        owner == candidateOwner && candidateOwner.generation == generation
    }

    @discardableResult
    mutating func completeSuccess(
        ifOwnedBy candidateOwner: ChekinanaEventAvatarSelectionOwner
    ) -> Bool {
        guard owns(candidateOwner), phase == .preparing else { return false }
        phase = .ready
        return true
    }

    @discardableResult
    mutating func completeFailure(
        ifOwnedBy candidateOwner: ChekinanaEventAvatarSelectionOwner,
        message: String
    ) -> Bool {
        guard owns(candidateOwner), phase == .preparing else { return false }
        phase = .failed(message)
        return true
    }

    @discardableResult
    mutating func releaseTask(
        ifOwnedBy candidateOwner: ChekinanaEventAvatarSelectionOwner
    ) -> Bool {
        guard taskOwner == candidateOwner else { return false }
        taskOwner = nil
        return true
    }

    mutating func invalidate(
        reason: ChekinanaEventAvatarSelectionInvalidationReason
    ) {
        generation &+= 1
        owner = nil
        taskOwner = nil
        lastInvalidationReason = reason
        phase = .idle
    }

    func allowsSave(
        preparedOwner: ChekinanaEventAvatarSelectionOwner?
    ) -> Bool {
        switch phase {
        case .idle:
            owner == nil && preparedOwner == nil
        case .ready:
            owner != nil && preparedOwner == owner
        case .preparing, .failed:
            false
        }
    }
}

enum ChekinanaEventAvatarSelectionError: LocalizedError {
    case dataUnavailable

    var errorDescription: String? {
        switch self {
        case .dataUnavailable:
            ChekinanaProductCopy.text(
                "events.avatar.data_unavailable",
                "The selected avatar photo is unavailable."
            )
        }
    }
}

private struct ChekinanaEventEditorView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Query private var eventSchedules: [EventSchedule]
    let event: Event?

    @State private var sourceURL = ""
    @State private var name: String
    @State private var hasDate: Bool
    @State private var date: Date
    @State private var openTimeDraft: ChekinanaEventTimeDraft
    @State private var startTimeDraft: ChekinanaEventTimeDraft
    @State private var city: String
    @State private var livehouse: String
    @State private var parsedAddress = ""
    @State private var price: String
    @State private var weiboURL: String
    @State private var ticketURL: String
    @State private var note: String
    @State private var isExtracting = false
    @State private var saveGate = ChekinanaEventSaveGate()
    @State private var saveTask: Task<Void, Never>?
    @State private var errorMessage: String?
    @State private var extractionTask: Task<Void, Never>?
    @State private var parseCoordinator = ChekinanaEventEditorParseCoordinator()
    @State private var avatarPickerItem: PhotosPickerItem?
    @State private var avatarRetryItem: PhotosPickerItem?
    @State private var avatarImportTask: Task<Void, Never>?
    @State private var avatarSelection = ChekinanaEventAvatarSelectionState()
    @State private var selectedAvatarData: Data?
    @State private var selectedAvatarOwner: ChekinanaEventAvatarSelectionOwner?
    @State private var parsedAvatarURL = ""
    @State private var clearsAvatar = false
    @State private var imageDrafts: [ChekinanaEventImageDraft]
    @State private var imagePickerItems: [PhotosPickerItem] = []
    @State private var imageImportTask: Task<Void, Never>?
    @State private var isImportingImages = false
    @State private var didLoadImages = false
    @State private var imageLoadError: String?
    @State private var didLoadSchedule = false
    @State private var isLoadingImages = false
    @State private var didCommit = false
    @State private var mediaDraftOwnerID = UUID()
    @State private var mediaGeneration: UUID?
    private let draftEventID: UUID
    private let expectedUpdatedAt: Date?
    private let initialSocialURL: String
    @FocusState private var focusedSource: SourceField?

    private enum SourceField: Hashable {
        case weiboURL
    }

    private var isSaving: Bool { saveGate.isInFlight }

    init(event: Event?) {
        self.event = event
        let eventID = event?.id ?? UUID()
        draftEventID = eventID
        expectedUpdatedAt = event?.updatedAt
        initialSocialURL = event?.weiboURL?.absoluteString ?? ""
        _eventSchedules = Query(
            filter: #Predicate<EventSchedule> { $0.eventID == eventID }
        )
        _sourceURL = State(initialValue: event?.weiboURL?.absoluteString ?? "")
        _name = State(initialValue: event?.name ?? "")
        _hasDate = State(initialValue: event?.date != nil)
        _date = State(initialValue: event?.date.flatMap {
            ChekinanaDateOnly.displayDate(from: $0, calendar: .current)
        } ?? Date())
        _openTimeDraft = State(initialValue: .init(storedValue: nil))
        _startTimeDraft = State(initialValue: .init(storedValue: nil))
        _city = State(initialValue: ChekinanaEventCity.displayed(event?.city) ?? "")
        _livehouse = State(initialValue: event?.resolvedLivehouse ?? "")
        _price = State(initialValue: event?.price ?? "")
        _weiboURL = State(initialValue: event?.weiboURL?.absoluteString ?? "")
        _ticketURL = State(initialValue: event?.ticketURL?.absoluteString ?? "")
        _note = State(initialValue: event?.note ?? "")
        _imageDrafts = State(initialValue: [])
    }

    var body: some View {
        let avatarPickerSelection = Binding<PhotosPickerItem?>(
            get: { avatarPickerItem },
            set: { updateAvatarPickerSelection($0) }
        )
        NavigationStack {
            Form {
                Section(
                    ChekinanaProductCopy.text(
                        "events.weibo_import",
                        "Fill from public Weibo / X"
                    )
                ) {
                        weiboSourceInputRow
                        Button { startExtraction() } label: {
                            if isExtracting {
                                Label(
                                    ChekinanaProductCopy.text(
                                        "events.parsing_weibo",
                                        "Parsing Weibo / X…"
                                    ),
                                    systemImage: "hourglass"
