                        PhotosPicker(selection: avatarPickerSelection, matching: .images) {
                            Text(
                                ChekinanaProductCopy.text(
                                    "events.avatar.choose",
                                    "Choose or replace avatar"
                                )
                            )
                        }
                        Spacer()
                        if selectedAvatarData != nil
                            || event?.avatarImageRef != nil
                            || !parsedAvatarURL.isEmpty
                            || avatarSelection.owner != nil {
                            Button(
                                ChekinanaProductCopy.text("common.clear", "Clear"),
