                        .textInputAutocapitalization(.never).keyboardType(.URL)
                        .accessibilityIdentifier("chekinana.events.editor.weibo-url")
                    TextField(
                        ChekinanaProductCopy.text("events.ticket_url", "Ticket URL"),
