                    }
                }
            }
            .disabled(isSaving)
            .chekinanaGroupedPageBackground()
            .navigationTitle(event == nil
                ? ChekinanaProductCopy.text("events.add", "Add Event")
                : ChekinanaProductCopy.text("events.edit", "Edit Event"))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        guard saveGate.cancelIfIdle() else { return }
                        endEditorSession()
                        discardUncommittedImages()
                        dismiss()
                    }
                    .disabled(isSaving)
                    .accessibilityIdentifier("chekinana.events.editor.cancel")
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.save", "Save")) { startSave() }
                        .disabled(
                            name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                || normalizedCity.isEmpty
                                || isSaving
                                || isExtracting
                                || isImportingImages
                                || isImportingAvatar
                                || !isAvatarSelectionResolved
                                || isLoadingImages
                        )
                        .accessibilityIdentifier("chekinana.events.editor.save")
                }
            }
        }
        .interactiveDismissDisabled(isSaving)
        .onAppear {
            parseCoordinator.activateIfNeeded()
            loadExistingScheduleIfNeeded()
            loadExistingImagesIfNeeded()
        }
        .onChange(of: imagePickerItems) { _, items in
            guard !items.isEmpty else { return }
            startPhotoImport(items)
        }
        .onAppear {
            beginMediaDraftOwnershipIfNeeded()
        }
        .onDisappear {
            guard !isSaving else { return }
            _ = saveGate.cancelIfIdle()
            endEditorSession()
            if !didCommit { discardUncommittedImages() }
            ChekinanaEventTravelMediaOwnership.release(ownerID: mediaDraftOwnerID)
        }
        .accessibilityIdentifier("chekinana.events.editor")
        .chekinanaSheetDraftDismiss(
            ready: didLoadImages && didLoadSchedule,
            isBusy: { isSaving || isImportingImages || isImportingAvatar || isLoadingImages },
            snapshot: { [AnyHashable(sourceURL), AnyHashable(name), AnyHashable(hasDate), AnyHashable(hasDate ? date : nil), AnyHashable(openTimeDraft.persistedValue()), AnyHashable(startTimeDraft.persistedValue()), AnyHashable(city), AnyHashable(livehouse), AnyHashable(parsedAddress), AnyHashable(price), AnyHashable(weiboURL), AnyHashable(ticketURL), AnyHashable(note), AnyHashable(selectedAvatarOwner?.selectionID), AnyHashable(parsedAvatarURL), AnyHashable(clearsAvatar), AnyHashable(imageDrafts.map(\.ref))] },
            onDiscard: { initial in guard saveGate.cancelIfIdle() else { return }; endEditorSession(); discardUncommittedImages(); dismiss() }
        )
    }

    private var weiboPasteTitle: String {
        ChekinanaProductCopy.text("events.paste_weibo", "Paste Weibo / X URL")
    }

    @MainActor
    private func beginMediaDraftOwnershipIfNeeded() {
        guard mediaGeneration == nil,
              let generation = ChekinanaEventTravelMediaOwnership.currentGeneration(
                  in: modelContext
              ) else { return }
        mediaGeneration = generation
        ChekinanaEventTravelMediaOwnership.beginDraftSession(
            ownerID: mediaDraftOwnerID,
            generation: generation
        )
    }

    private var weiboSourceInputRow: some View {
        HStack(spacing: 8) {
            TextField(
                ChekinanaProductCopy.text("events.weibo_url", "Weibo / X URL"),
                text: $sourceURL
            )
            .textInputAutocapitalization(.never)
            .keyboardType(.URL)
            .focused($focusedSource, equals: .weiboURL)
            .disabled(isExtracting)
            .frame(height: ChekinanaEventEditorLayout.singleLineInputHeight)
