    private var normalizedCity: String {
        ChekinanaEventCity.normalized(city)
    }

    private var isImportingAvatar: Bool {
        avatarSelection.isPreparing
    }

    private var isAvatarSelectionResolved: Bool {
        guard (selectedAvatarData == nil) == (selectedAvatarOwner == nil) else {
            return false
        }
        return avatarSelection.allowsSave(preparedOwner: selectedAvatarOwner)
    }

    private var cityRequiredMessage: String {
        ChekinanaProductCopy.text("events.city_required", "City is required.")
    }

    private var contentMetadataWarningMessage: String? {
        guard let metadata = parseCoordinator.contentMetadata(
            currentSourceIdentity: sourceURL
        ) else { return nil }
        return ChekinanaEventContentWarningPresentation.message(for: metadata)
    }

    private func userEditableBinding<Value>(
        _ binding: Binding<Value>,
        field: ChekinanaEventEditorParsedField
    ) -> Binding<Value> {
        Binding(
            get: { binding.wrappedValue },
            set: { value in
                binding.wrappedValue = value
                parseCoordinator.recordUserEdit(field)
            }
        )
    }

    private func optionalTimeControl(
        label: String,
        draft: Binding<ChekinanaEventTimeDraft>,
        identifier: String
    ) -> some View {
        VStack(alignment: .leading, spacing: 2) {
            HStack(spacing: 4) {
                Text(label)
                    .font(.caption.weight(.semibold))
                Spacer(minLength: 2)
                Toggle("", isOn: draft.isEnabled)
                    .labelsHidden()
                    .controlSize(.mini)
                    .accessibilityLabel(label)
                    .accessibilityIdentifier(
                        "chekinana.events.editor.\(identifier).enabled"
                    )
            }
            if draft.wrappedValue.isEnabled {
                DatePicker(
                    "",
                    selection: draft.selection,
                    displayedComponents: .hourAndMinute
                )
                .labelsHidden()
                .environment(\.locale, ChekinanaLanguagePreference.displayLocale())
                .accessibilityLabel(label)
                .accessibilityIdentifier(
                    "chekinana.events.editor.\(identifier).picker"
                )
            } else {
                Text(ChekinanaProductCopy.text("common.none", "None"))
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .frame(height: 30)
            }
        }
        .frame(maxWidth: .infinity, minHeight: 58, alignment: .topLeading)
    }

    @MainActor
    private func startExtraction() {
        cancelExtraction()
        focusedSource = nil
        let requestedURL = sourceURL
        let request = parseCoordinator.begin(sourceIdentity: requestedURL)
        isExtracting = true
        errorMessage = nil
        extractionTask = Task { @MainActor in
            defer {
                if parseCoordinator.finish(request) {
                    isExtracting = false
                    extractionTask = nil
                }
            }
            do {
                let client = ChekinanaEventCandidateClient()
                let response = try await client.fetchResponse(
                    weiboURL: requestedURL
                )
                guard parseCoordinator.publishContentMetadata(
                    response.contentMetadata,
                    from: request,
                    currentSourceIdentity: sourceURL,
                    isCancelled: Task.isCancelled
                ) else {
                    return
                }
                let candidate = response.fields
                apply(candidate, from: request)
                await stageParsedImages(candidate.imageUrls, request: request)
            } catch is CancellationError {
                return
            } catch {
                guard parseCoordinator.accepts(
                    request,
                    currentSourceIdentity: sourceURL,
                    isCancelled: Task.isCancelled
                ) else {
                    return
                }
                errorMessage = error.localizedDescription
            }
        }
    }

    @MainActor
    private func cancelExtraction() {
        parseCoordinator.invalidateRequest()
        extractionTask?.cancel()
        extractionTask = nil
        isExtracting = false
    }

    @MainActor
    private func endEditorSession() {
        guard parseCoordinator.closeEditor() else { return }
        extractionTask?.cancel()
        extractionTask = nil
        isExtracting = false
        imageImportTask?.cancel()
        imageImportTask = nil
        isImportingImages = false
        invalidateAvatarSelection(reason: .editorExited)
    }

    @MainActor
    private func updateAvatarPickerSelection(_ item: PhotosPickerItem?) {
        parseCoordinator.recordUserEdit(.avatar)
        guard let item else {
            invalidateAvatarSelection(reason: .pickerCancelled)
            return
        }
        beginAvatarPreparation(item)
    }

    @MainActor
    private func beginAvatarPreparation(_ item: PhotosPickerItem) {
        let replacedTask = avatarImportTask
        let owner = avatarSelection.begin()
        avatarPickerItem = item
        avatarRetryItem = item
        selectedAvatarData = nil
        selectedAvatarOwner = nil
        parsedAvatarURL = ""
        clearsAvatar = false
        replacedTask?.cancel()
        avatarImportTask = Task { @MainActor in
            await prepareAvatar(item, owner: owner)
        }
    }

    @MainActor
    private func prepareAvatar(
        _ item: PhotosPickerItem,
        owner: ChekinanaEventAvatarSelectionOwner
    ) async {
        defer { releaseAvatarTask(ifOwnedBy: owner) }
        do {
            guard let transfer = try await item.loadTransferable(
                type: ChekinanaProductTransferableImage.self
            ) else {
                throw ChekinanaEventAvatarSelectionError.dataUnavailable
            }
            guard !Task.isCancelled,
                  avatarSelection.completeSuccess(ifOwnedBy: owner) else {
                return
            }
            selectedAvatarData = transfer.data
            selectedAvatarOwner = owner
            avatarPickerItem = nil
            avatarRetryItem = nil
            parsedAvatarURL = ""
            clearsAvatar = false
        } catch is CancellationError {
            return
        } catch {
            guard !Task.isCancelled else { return }
            let message = ChekinanaProductCopy.format(
                "events.avatar.selection_failed",
                "Unable to prepare Event avatar. %@ Retry or cancel this selection.",
                error.localizedDescription
            )
            guard avatarSelection.completeFailure(
                ifOwnedBy: owner,
                message: message
            ) else { return }
            selectedAvatarData = nil
            selectedAvatarOwner = nil
            avatarPickerItem = nil
        }
    }

    @MainActor
    @discardableResult
    private func releaseAvatarTask(
        ifOwnedBy owner: ChekinanaEventAvatarSelectionOwner
    ) -> Bool {
        guard avatarSelection.releaseTask(ifOwnedBy: owner) else { return false }
        avatarImportTask = nil
        return true
    }

    @MainActor
    private func retryAvatarSelection() {
        guard let avatarRetryItem else { return }
        parseCoordinator.recordUserEdit(.avatar)
        beginAvatarPreparation(avatarRetryItem)
    }

    @MainActor
    private func cancelAvatarSelection() {
        parseCoordinator.recordUserEdit(.avatar)
        invalidateAvatarSelection(reason: .pickerCancelled)
    }

    @MainActor
    private func clearAvatar() {
        parseCoordinator.recordUserEdit(.avatar)
        invalidateAvatarSelection(reason: .avatarCleared)
        parsedAvatarURL = ""
        clearsAvatar = true
    }

    @MainActor
    private func invalidateAvatarSelection(
        reason: ChekinanaEventAvatarSelectionInvalidationReason
    ) {
        let task = avatarImportTask
        avatarSelection.invalidate(reason: reason)
        avatarImportTask = nil
        avatarPickerItem = nil
        avatarRetryItem = nil
        selectedAvatarData = nil
        selectedAvatarOwner = nil
        task?.cancel()
    }

    private func shouldApply(
        _ field: ChekinanaEventEditorParsedField,
        from request: ChekinanaEventEditorParseRequest
    ) -> Bool {
        parseCoordinator.shouldApply(
            field,
            from: request,
            currentSourceIdentity: sourceURL
        )
    }

    @MainActor
    private func apply(
        _ candidate: ChekinanaEventCandidateFields,
        from request: ChekinanaEventEditorParseRequest
    ) {
        if shouldApply(.name, from: request) { name = candidate.name }
        if shouldApply(.city, from: request) { city = candidate.city }
        if shouldApply(.livehouse, from: request) { livehouse = candidate.livehouse }
        if shouldApply(.address, from: request) { parsedAddress = candidate.address }
        if shouldApply(.price, from: request) { price = candidate.price }
        if shouldApply(.weiboURL, from: request) { weiboURL = candidate.weiboURL }
        if shouldApply(.ticketURL, from: request) { ticketURL = candidate.ticketURL }
        if shouldApply(.openTime, from: request) {
            openTimeDraft.replace(with: candidate.openTime)
        }
        if shouldApply(.startTime, from: request) {
            startTimeDraft.replace(with: candidate.startTime)
        }
        if shouldApply(.avatar, from: request) {
            if candidate.avatarURL.isEmpty {
                parsedAvatarURL = ""
            } else {
                invalidateAvatarSelection(reason: .parseReplacedSelection)
                parsedAvatarURL = candidate.avatarURL
                clearsAvatar = false
            }
        }
        if shouldApply(.date, from: request),
           let displayed = ChekinanaEventDateState.parsedCandidateDate(
            candidate.date
           ) {
            date = displayed
            hasDate = true
        }
    }

    @MainActor
    private func stageParsedImages(
        _ rawURLs: [String],
        request: ChekinanaEventEditorParseRequest
    ) async {
        let generation = request.generation
        let priorParsed = imageDrafts.filter { $0.parsedMetadata != nil }
        imageDrafts.removeAll { $0.parsedMetadata != nil }
        ChekinanaEventImageStore.remove(priorParsed.map(\.ref))
        guard !rawURLs.isEmpty else {
            errorMessage = nil
            return
        }
        do {
            let staged = try await ChekinanaEventImageStore.stageRemoteImages(
                rawURLs,
                eventID: draftEventID,
                ownerID: mediaDraftOwnerID,
                generation: mediaGeneration,
                onStaged: { index, ref in
                    await MainActor.run {
                        guard parseCoordinator.accepts(
                            request,
                            currentSourceIdentity: sourceURL,
                            isCancelled: Task.isCancelled
                        ), imageDrafts.count < ChekinanaEventImageStore.maximumImageCount else {
                            return
                        }
                        imageDrafts.append(.init(
                            ref: ref,
                            origin: .parsed(generation: generation, index: index)
                        ))
                        let otherDrafts = imageDrafts.filter {
                            $0.parsedMetadata?.generation != generation
                        }
                        let currentParsed = imageDrafts.filter {
                            $0.parsedMetadata?.generation == generation
                        }.sorted {
                            ($0.parsedMetadata?.index ?? 0) < ($1.parsedMetadata?.index ?? 0)
                        }
                        imageDrafts = otherDrafts + currentParsed
                    }
                }
            )
            let stagedRefs = staged.compactMap { $0 }
            guard parseCoordinator.accepts(
                request,
                currentSourceIdentity: sourceURL,
                isCancelled: Task.isCancelled
            ) else {
                ChekinanaEventImageStore.remove(stagedRefs)
                imageDrafts.removeAll { $0.parsedMetadata?.generation == generation }
                return
            }
            let acceptedRefs = Set(imageDrafts.compactMap { draft in
                draft.parsedMetadata?.generation == generation ? draft.ref : nil
            })
            ChekinanaEventImageStore.remove(stagedRefs.filter { !acceptedRefs.contains($0) })
            let failedCount = staged.count - acceptedRefs.count
            errorMessage = failedCount > 0
                ? ChekinanaProductCopy.format(
                    "events.images.partial",
                    "Loaded %1$lld Event images; %2$lld could not be loaded. You can still edit and save this Event.",
                    Int64(acceptedRefs.count),
                    Int64(failedCount)
                )
                : nil
        } catch is CancellationError {
            let cancelledRefs = imageDrafts.compactMap { draft in
                draft.parsedMetadata?.generation == generation ? draft.ref : nil
            }
            imageDrafts.removeAll { $0.parsedMetadata?.generation == generation }
            ChekinanaEventImageStore.remove(cancelledRefs)
            return
        } catch {
            let failedRefs = imageDrafts.compactMap { draft in
                draft.parsedMetadata?.generation == generation ? draft.ref : nil
            }
            imageDrafts.removeAll { $0.parsedMetadata?.generation == generation }
            ChekinanaEventImageStore.remove(failedRefs)
            guard parseCoordinator.accepts(
                request,
                currentSourceIdentity: sourceURL,
                isCancelled: Task.isCancelled
            ) else { return }
            errorMessage = ChekinanaProductCopy.text(
                "events.images.parse_failed",
                "Event fields were parsed, but images could not be loaded. You can still edit and save this Event."
            )
        }
    }

    @MainActor
    private func startPhotoImport(_ items: [PhotosPickerItem]) {
        imageImportTask?.cancel()
        isImportingImages = true
        let capacity = max(
            0,
            ChekinanaEventImageStore.maximumImageCount - imageDrafts.count
        )
        let acceptedItems = Array(items.prefix(capacity))
        imageImportTask = Task { @MainActor in
            var failureCount = items.count - acceptedItems.count
            defer {
                isImportingImages = false
                imageImportTask = nil
                imagePickerItems = []
            }
            for item in acceptedItems {
                guard !Task.isCancelled else { return }
                do {
                    guard let transfer = try await item.loadTransferable(
                        type: ChekinanaProductTransferableImage.self
                    ) else {
                        failureCount += 1
                        continue
                    }
                    let ref = try await ChekinanaEventImageStore.save(
                        transfer.data,
                        eventID: draftEventID,
                        ownerID: mediaDraftOwnerID,
                        generation: mediaGeneration
                    )
                    guard !Task.isCancelled else {
                        ChekinanaEventImageStore.remove([ref])
                        return
                    }
                    imageDrafts.append(.init(ref: ref, origin: .photoLibrary))
                } catch is CancellationError {
                    return
                } catch {
                    failureCount += 1
                }
            }
            if failureCount > 0 {
                errorMessage = ChekinanaProductCopy.text(
                    "events.images.selection_failed",
                    "Some selected images could not be added. Other images and Event fields were kept."
                )
            }
        }
    }

    @MainActor
    private func removeImage(_ draft: ChekinanaEventImageDraft) {
        imageDrafts.removeAll { $0.id == draft.id }
        if draft.isNew { ChekinanaEventImageStore.remove([draft.ref]) }
    }

    @MainActor
    private func discardUncommittedImages() {
        ChekinanaEventImageStore.remove(imageDrafts.filter(\.isNew).map(\.ref))
        imageDrafts.removeAll(keepingCapacity: false)
        if let event {
            do {
                imageDrafts = try ChekinanaEventPersistence.imageValues(
                    for: event.id, in: modelContext
                ).map { value in
                    guard let id = value.id else {
                        throw ChekinanaEventPersistence.PersistenceError.invalidImages
                    }
                    return .init(ref: value.imageRef, origin: .existing(recordID: id))
                }
                imageLoadError = nil
            } catch {
                imageLoadError = error.localizedDescription
                errorMessage = error.localizedDescription
            }
        }
    }

    @MainActor
    private func loadExistingImagesIfNeeded() {
        guard !didLoadImages || imageLoadError != nil else { return }
        didLoadImages = true
        guard let event else { return }
        isLoadingImages = true
        defer { isLoadingImages = false }
        do {
            let values = try ChekinanaEventPersistence.imageValues(
                for: event.id,
                in: modelContext
            )
            imageDrafts = try ChekinanaEventImageDraft.restoringExisting(
                values, preserving: imageDrafts
            )
            imageLoadError = nil
        } catch {
            imageLoadError = error.localizedDescription
            errorMessage = error.localizedDescription
        }
    }

    @MainActor
    private func loadExistingScheduleIfNeeded() {
        guard !didLoadSchedule else { return }
        didLoadSchedule = true
        guard event != nil, let schedule = eventSchedules.first else { return }
        openTimeDraft.replace(with: schedule.openTime)
        startTimeDraft.replace(with: schedule.startTime)
    }

    @MainActor
    private func startSave() {
        if event != nil {
            loadExistingImagesIfNeeded()
            guard didLoadImages, !isLoadingImages, imageLoadError == nil else {
                errorMessage = imageLoadError
                    ?? ChekinanaEventPersistence.PersistenceError.invalidImages.localizedDescription
                return
            }
        }
        guard !normalizedCity.isEmpty else {
            errorMessage = cityRequiredMessage
            return
        }
        guard isAvatarSelectionResolved else {
            errorMessage = avatarSelection.failureMessage
                ?? ChekinanaProductCopy.text(
                    "events.avatar.selection_pending",
                    "Wait for the selected Event avatar to finish, or retry or cancel the selection."
                )
            return
        }
        guard let token = saveGate.begin() else { return }
        saveTask = Task { @MainActor in
            await save(token: token)
            if saveGate.finish(token) { saveTask = nil }
        }
    }

    @MainActor
    private func save(token: UInt64) async {
        guard saveGate.accepts(token, isCancelled: Task.isCancelled) else { return }
        let selectedDate = ChekinanaEventDateState.persistedDate(
            hasDate: hasDate,
            selection: date
        )
        if hasDate, selectedDate == nil {
            errorMessage = ChekinanaProductCopy.text(
                "error.read_date",
                "Unable to read the selected date. Choose it again."
            )
            return
        }
        let dateText = selectedDate.map(ChekinanaDateOnly.string) ?? ""
        let fields = ChekinanaEventCandidateFields(
            name: name,
            date: dateText,
            city: city,
            livehouse: livehouse,
            address: parsedAddress,
            price: price,
            avatarURL: parsedAvatarURL,
            imageUrls: [],
            weiboURL: weiboURL,
            ticketURL: ticketURL,
            openTime: openTimeDraft.persistedValue(),
            startTime: startTimeDraft.persistedValue(),
            note: note
        )
        let normalizedSocialURL = weiboURL.trimmingCharacters(in: .whitespacesAndNewlines)
        let validatedSocialLink = normalizedSocialURL.isEmpty
            ? nil : ChekinanaEventSource.validatedURL(from: normalizedSocialURL)
        let preservesUnsupportedLegacyURL = event != nil
            && normalizedSocialURL == initialSocialURL
            && !normalizedSocialURL.isEmpty
            && validatedSocialLink == nil
        let blockers = ChekinanaEventCandidateValidator.blockers(for: fields).filter {
            guard $0 == .invalidWeiboURL else { return true }
            return !normalizedSocialURL.isEmpty && !preservesUnsupportedLegacyURL
        }
        guard blockers.isEmpty else {
            errorMessage = blockers.map(\.message).joined(separator: "\n")
            return
        }
        let persistedSocialURL = validatedSocialLink?.url
            ?? (preservesUnsupportedLegacyURL ? event?.weiboURL : nil)
        let target = event ?? Event(id: draftEventID, name: name)
        let previousAvatarRef = event?.avatarImageRef
        guard let mediaGeneration else {
            errorMessage = ChekinanaProductCopy.text(
                "events.media_generation_failed",
                "Unable to establish the library generation. Reopen the Event and try again."
            )
            return
        }
        let saveOwnerID = UUID()
        let draftReferences = imageDrafts.map(\.ref)
        ChekinanaEventTravelMediaOwnership.beginSaveTask(
            ownerID: saveOwnerID,
            generation: mediaGeneration,
            references: draftReferences
        )
        ChekinanaEventTravelMediaOwnership.transfer(
            draftReferences,
            from: mediaDraftOwnerID,
            to: saveOwnerID,
            generation: mediaGeneration
        )
        var stagedAvatarRef: String?
        do {
            if let selectedAvatarData {
                stagedAvatarRef = try await ChekinanaEventAvatarStore.save(
                    selectedAvatarData,
                    eventID: target.id,
                    ownerID: saveOwnerID,
                    generation: mediaGeneration
                )
            } else if event == nil, !parsedAvatarURL.isEmpty {
#if DEBUG
                if ProcessInfo.processInfo.environment["CHEKINANA_EVENT_CANDIDATE_UI_STUB"]
                    == "fixture" {
                    stagedAvatarRef = try await ChekinanaEventAvatarStore
                        .saveUIFixtureAvatar(
                            eventID: target.id,
                            ownerID: saveOwnerID,
                            generation: mediaGeneration
                        )
                } else {
                    stagedAvatarRef = try await ChekinanaEventAvatarStore.downloadAndSave(
                        parsedAvatarURL,
                        eventID: target.id,
                        ownerID: saveOwnerID,
                        generation: mediaGeneration
                    )
                }
#else
                stagedAvatarRef = try await ChekinanaEventAvatarStore.downloadAndSave(
                    parsedAvatarURL,
                    eventID: target.id,
                    ownerID: saveOwnerID,
                    generation: mediaGeneration
                )
#endif
            }
        } catch {
            ChekinanaEventTravelMediaOwnership.transfer(
                draftReferences,
                from: saveOwnerID,
                to: mediaDraftOwnerID,
                generation: mediaGeneration
            )
            ChekinanaEventTravelMediaOwnership.release(ownerID: saveOwnerID)
            errorMessage = ChekinanaProductCopy.format(
                "events.avatar.save_failed",
                "Unable to save Event avatar. %@",
                error.localizedDescription
            )
            return
        }
        guard saveGate.accepts(token, isCancelled: Task.isCancelled) else {
            ChekinanaEventAvatarStore.remove(stagedAvatarRef)
            ChekinanaEventTravelMediaOwnership.transfer(
                draftReferences,
                from: saveOwnerID,
                to: mediaDraftOwnerID,
                generation: mediaGeneration
            )
            ChekinanaEventTravelMediaOwnership.release(ownerID: saveOwnerID)
            return
        }
        do {
            guard saveGate.accepts(token, isCancelled: Task.isCancelled) else {
                modelContext.rollback()
                ChekinanaEventAvatarStore.remove(stagedAvatarRef)
                ChekinanaEventTravelMediaOwnership.transfer(
                    draftReferences,
                    from: saveOwnerID,
                    to: mediaDraftOwnerID,
                    generation: mediaGeneration
                )
                ChekinanaEventTravelMediaOwnership.release(ownerID: saveOwnerID)
                return
            }
            try ChekinanaEventPersistence.save(
                target,
                inserting: event == nil,
                expectedUpdatedAt: expectedUpdatedAt,
                images: imageDrafts.map {
                    ChekinanaEventImageValue(id: $0.recordID, imageRef: $0.ref)
                },
                schedule: ChekinanaEventScheduleValue(
                    openTime: fields.openTime,
                    startTime: fields.startTime
                ),
                source: validatedSocialLink?.source,
                previousAvatarRef: previousAvatarRef,
                in: modelContext,
                validateManagedFiles: true,
                expectedGeneration: mediaGeneration,
                mediaOwnerID: saveOwnerID,
                mediaOwnerReferences: draftReferences
                    + [stagedAvatarRef].compactMap { $0 },
                apply: { liveEvent in
                    liveEvent.name = name.trimmingCharacters(in: .whitespacesAndNewlines)
                    liveEvent.date = selectedDate
                    liveEvent.city = normalizedCity
                    liveEvent.livehouse = livehouse.nonEmpty
                    liveEvent.legacyVenue = nil
                    liveEvent.price = price.nonEmpty
                    if clearsAvatar {
                        liveEvent.avatarImageRef = nil
                    } else if let stagedAvatarRef {
                        liveEvent.avatarImageRef = stagedAvatarRef
                    }
                    liveEvent.weiboURL = persistedSocialURL
                    liveEvent.ticketURL = ticketURL.nonEmpty.flatMap(URL.init(string:))
                    liveEvent.note = note
                    liveEvent.updatedAt = Date()
                }
            )
            didCommit = true
            ChekinanaEventTravelMediaOwnership.release(ownerID: mediaDraftOwnerID)
            cancelExtraction()
            dismiss()
        } catch {
            modelContext.rollback()
            ChekinanaEventAvatarStore.remove(stagedAvatarRef)
            ChekinanaEventTravelMediaOwnership.transfer(
                draftReferences,
                from: saveOwnerID,
                to: mediaDraftOwnerID,
                generation: mediaGeneration
            )
            ChekinanaEventTravelMediaOwnership.release(ownerID: saveOwnerID)
            errorMessage = error.localizedDescription
        }
    }

}

enum ChekinanaGalleryMediaKind: String, Sendable {
    case shame
    case douga
}

enum ChekinanaGalleryMediaStoreError: LocalizedError {
    case invalidMedia
    case missingManagedFile
    case thumbnailFailed
    case fileOperation(String)

    var errorDescription: String? {
        switch self {
        case .invalidMedia:
            ChekinanaL10n.message("The selected media is unavailable or invalid.")
        case .missingManagedFile:
            ChekinanaL10n.message("The app-managed media file is unavailable.")
        case .thumbnailFailed:
            ChekinanaL10n.message("A stable video thumbnail could not be generated.")
        case .fileOperation(let detail):
            ChekinanaL10n.message("The managed media file could not be updated: \(detail)")
        }
    }
}

struct ChekinanaGalleryDeletionJournal: Codable, Equatable, Sendable {
    enum Phase: String, Codable, Sendable {
        case movingFiles
        case databaseCommitPending
        case databaseCommitted
    }

    struct Entry: Codable, Equatable, Sendable {
        enum Stage: String, Codable, Sendable {
            case planned
            case quarantined
            case restored
            case removed
        }

        let originalName: String
        let quarantineName: String
        let identity: ChekinanaImportFileIdentity
        var stage: Stage
    }

    let formatVersion: Int
    let operationID: UUID
    let libraryGeneration: UUID
    var phase: Phase
    var entries: [Entry]

    var isValid: Bool {
        guard formatVersion == 1,
              !entries.isEmpty,
              Set(entries.map(\.originalName)).count == entries.count,
              Set(entries.map(\.quarantineName)).count == entries.count else {
            return false
        }
        let prefix = ".delete-\(operationID.uuidString.lowercased())-"
        return entries.allSatisfy { entry in
            entry.identity.isValid
                && ChekinanaGalleryMediaStore.isManagedDeletionFilename(
                    entry.originalName
                )
                && entry.quarantineName == prefix + entry.originalName
                && ChekinanaGalleryMediaStore
                    .isRecognizedDeletionQuarantineFilename(
                        entry.quarantineName
                    )
        }
    }
}

/// A small, fsync-backed intent file for one Gallery deletion. It deliberately
/// lives beside (not inside) the quarantined files so a crash between the main
/// media move and the video-thumbnail move still leaves the complete plan.
enum ChekinanaGalleryDeletionJournalStore {
    static let filenamePrefix = ".gallery-delete-transaction-"
    static let filenameSuffix = ".json"

    static func journalURL(operationID: UUID, in directory: URL) -> URL {
        directory.standardizedFileURL.appendingPathComponent(
            "\(filenamePrefix)\(operationID.uuidString.lowercased())\(filenameSuffix)"
        )
    }

    static func persist(
        _ journal: ChekinanaGalleryDeletionJournal,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws {
        guard journal.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let canonicalDirectory = directory.standardizedFileURL
        let directoryValues = try canonicalDirectory.resourceValues(
            forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        )
        guard directoryValues.isDirectory == true,
              directoryValues.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let url = journalURL(operationID: journal.operationID, in: canonicalDirectory)
        if fileManager.fileExists(atPath: url.path) {
            let values = try url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            guard values.isRegularFile == true,
                  values.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
        }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        do {
            try encoder.encode(journal).write(to: url, options: [.atomic])
            let handle = try FileHandle(forWritingTo: url)
            do {
                try handle.synchronize()
                try handle.close()
            } catch {
                try? handle.close()
                throw error
            }
            guard try load(
                operationID: journal.operationID,
                in: canonicalDirectory,
                fileManager: fileManager
            ) == journal else {
                throw ChekinanaImportTransactionError.incomplete
            }
        } catch {
            throw ChekinanaImportTransactionError.incomplete
        }
    }

    static func load(
        operationID: UUID,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws -> ChekinanaGalleryDeletionJournal? {
        let url = journalURL(operationID: operationID, in: directory)
        guard fileManager.fileExists(atPath: url.path) else { return nil }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true,
              values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let journal: ChekinanaGalleryDeletionJournal
        do {
            journal = try JSONDecoder().decode(
                ChekinanaGalleryDeletionJournal.self,
                from: Data(contentsOf: url, options: [.mappedIfSafe])
            )
        } catch {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        guard journal.operationID == operationID, journal.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        return journal
    }

    static func discover(
        in directory: URL,
        fileManager: FileManager = .default
    ) throws -> [ChekinanaGalleryDeletionJournal] {
        let canonicalDirectory = directory.standardizedFileURL
        let entries = try fileManager.contentsOfDirectory(
            at: canonicalDirectory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
            options: []
        )
        return try entries.compactMap { url in
            guard let operationID = operationID(fromJournalFilename: url.lastPathComponent)
            else { return nil }
            let values = try url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            guard url.standardizedFileURL.deletingLastPathComponent()
                    == canonicalDirectory,
                  values.isRegularFile == true,
                  values.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            return try load(
                operationID: operationID,
                in: canonicalDirectory,
                fileManager: fileManager
            )
        }.sorted { $0.operationID.uuidString < $1.operationID.uuidString }
    }

    static func discard(
        operationID: UUID,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws {
        let url = journalURL(operationID: operationID, in: directory)
        guard fileManager.fileExists(atPath: url.path) else { return }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true,
              values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        try fileManager.removeItem(at: url)
    }

    static func operationID(fromJournalFilename filename: String) -> UUID? {
        guard filename.hasPrefix(filenamePrefix), filename.hasSuffix(filenameSuffix)
        else { return nil }
        let start = filename.index(filename.startIndex, offsetBy: filenamePrefix.count)
        let end = filename.index(filename.endIndex, offsetBy: -filenameSuffix.count)
        guard start < end else { return nil }
        return UUID(uuidString: String(filename[start..<end]))
    }

    static func operationID(fromQuarantineFilename filename: String) -> UUID? {
        guard filename.hasPrefix(".delete-") else { return nil }
        let remainder = filename.dropFirst(".delete-".count)
        guard remainder.count > 36 else { return nil }
        return UUID(uuidString: String(remainder.prefix(36)))
    }
}

enum ChekinanaGalleryMediaStore {
    /// Used only by Memory creation; ordinary Gallery saves keep their contract.
    typealias MemoryFileWillPublish = @Sendable (
        URL, ChekinanaImportFileIdentity
    ) throws -> Void

    private static let maximumImageBytes = 64 * 1_024 * 1_024
    private static let maximumVideoBytes: Int64 = 2 * 1_024 * 1_024 * 1_024
    private static let cleanupQueueKey = "ChekinanaGalleryCommittedDeletionQueue"
    private static let restoreQueueKey = "ChekinanaGalleryRestoreRecoveryQueue"
    private static let orphanQueueKey = "ChekinanaGalleryOrphanCleanupQueue"

    private struct RestoreEntry: Codable, Hashable {
        let original: String
        let quarantine: String
    }

    static func performFileIO<Value: Sendable>(
        priority: TaskPriority = .userInitiated,
        _ operation: @escaping @Sendable () throws -> Value
    ) async throws -> Value {
        try await Task.detached(priority: priority, operation: operation).value
    }

    static func saveImage(
        _ data: Data,
        id: UUID,
        filenameExtension: String,
        directory: URL? = nil
    ) throws -> String {
        guard !data.isEmpty,
              data.count <= maximumImageBytes,
              let source = CGImageSourceCreateWithData(
                data as CFData,
                [kCGImageSourceShouldCache: false] as CFDictionary
              ),
              ChekinanaImageSourceValidator.accepts(
                source: source,
                maxDimension: ChekinanaImageSourceValidator.maximumThumbnailDimension
              ) else {
            throw ChekinanaGalleryMediaStoreError.invalidMedia
        }
        let ext = imageExtension(for: source, fallback: filenameExtension)
        let filename = "shame-\(id.uuidString.lowercased()).\(ext)"
        let destination = try resolvedDirectory(directory)
            .appendingPathComponent(filename, isDirectory: false)
        do {
            try data.write(to: destination, options: [.atomic])
            return filename
        } catch {
            throw ChekinanaGalleryMediaStoreError.fileOperation(error.localizedDescription)
        }
    }

    static func makeStagedImageCopy(
        from data: Data,
        filenameExtension: String
    ) async throws -> URL {
        try await performFileIO {
            guard !data.isEmpty,
                  data.count <= maximumImageBytes,
                  let source = CGImageSourceCreateWithData(
                    data as CFData,
                    [kCGImageSourceShouldCache: false] as CFDictionary
                  ),
                  ChekinanaImageSourceValidator.accepts(
                    source: source,
                    maxDimension: ChekinanaImageSourceValidator.maximumThumbnailDimension
                  ) else {
                throw ChekinanaGalleryMediaStoreError.invalidMedia
            }
            let directory = try stagingDirectory()
            let ext = imageExtension(for: source, fallback: filenameExtension)
            let destination = directory.appendingPathComponent(
                "\(UUID().uuidString.lowercased()).\(ext)"
            )
            do {
                try data.write(to: destination, options: [.atomic])
                return destination
            } catch {
                throw ChekinanaGalleryMediaStoreError.fileOperation(
                    error.localizedDescription
                )
            }
        }
    }

    static func makeStagedImageCopy(from source: URL) throws -> URL {
        guard ChekiImageRefResolver.isRegularReadableFile(source),
              let size = try? source.resourceValues(forKeys: [.fileSizeKey]).fileSize,
              size > 0,
              size <= maximumImageBytes,
              let imageSource = CGImageSourceCreateWithURL(
                source as CFURL,
                [kCGImageSourceShouldCache: false] as CFDictionary
              ),
              ChekinanaImageSourceValidator.accepts(
                source: imageSource,
                maxDimension: ChekinanaImageSourceValidator.maximumThumbnailDimension
              ) else {
            throw ChekinanaGalleryMediaStoreError.invalidMedia
        }
        let directory = try stagingDirectory()
        let ext = imageExtension(for: imageSource, fallback: source.pathExtension)
        let destination = directory.appendingPathComponent(
            "\(UUID().uuidString.lowercased()).\(ext)"
        )
        do {
            try FileManager.default.copyItem(at: source, to: destination)
            return destination
        } catch {
            throw ChekinanaGalleryMediaStoreError.fileOperation(
                error.localizedDescription
            )
        }
    }

    static func saveImage(
        from stagedURL: URL,
        id: UUID,
        filenameExtension: String,
        directory: URL? = nil,
        memoryFileWillPublish: MemoryFileWillPublish? = nil
    ) async throws -> String {
        try await performFileIO {
            guard isOwnedStagedImport(stagedURL),
                  ChekiImageRefResolver.isRegularReadableFile(stagedURL),
                  let size = try? stagedURL.resourceValues(
                    forKeys: [.fileSizeKey]
                  ).fileSize,
                  size > 0,
                  size <= maximumImageBytes,
                  let source = CGImageSourceCreateWithURL(
                    stagedURL as CFURL,
                    [kCGImageSourceShouldCache: false] as CFDictionary
                  ),
                  ChekinanaImageSourceValidator.accepts(
                    source: source,
                    maxDimension: ChekinanaImageSourceValidator.maximumThumbnailDimension
                  ) else {
                throw ChekinanaGalleryMediaStoreError.invalidMedia
            }
            let ext = imageExtension(for: source, fallback: filenameExtension)
            let filename = "shame-\(id.uuidString.lowercased()).\(ext)"
            let destination = try resolvedDirectory(directory)
                .appendingPathComponent(filename, isDirectory: false)
            if let memoryFileWillPublish {
                let prepared = try prepareMemoryPublicationFile(from: stagedURL)
                defer { try? FileManager.default.removeItem(at: prepared) }
                try publishMemoryPreparedFile(
                    prepared, at: destination, willPublish: memoryFileWillPublish
                )
                return filename
            }
            do {
                if FileManager.default.fileExists(atPath: destination.path) {
                    try FileManager.default.removeItem(at: destination)
                }
                try materializeStagedImport(
                    from: stagedURL,
                    to: destination
                )
                return filename
            } catch {
                try? FileManager.default.removeItem(at: destination)
                throw ChekinanaGalleryMediaStoreError.fileOperation(
                    error.localizedDescription
                )
            }
        }
    }

    static func saveVideo(
        from stagedURL: URL,
        id: UUID,
        directory: URL? = nil,
        memoryFileWillPublish: MemoryFileWillPublish? = nil
    ) async throws -> String {
        try await performFileIO {
            guard isOwnedStagedImport(stagedURL),
                  ChekiImageRefResolver.isRegularReadableFile(stagedURL),
                  let size = try? stagedURL.resourceValues(
                    forKeys: [.fileSizeKey]
                  ).fileSize,
                  size > 0,
                  Int64(size) <= maximumVideoBytes else {
                throw ChekinanaGalleryMediaStoreError.invalidMedia
            }
            let ext = normalizedVideoExtension(stagedURL.pathExtension)
            let resolvedDirectory = try resolvedDirectory(directory)
            let filename = "douga-\(id.uuidString.lowercased()).\(ext)"
            let destination = resolvedDirectory.appendingPathComponent(filename)
            let thumbnail = thumbnailURL(id: id, directory: resolvedDirectory)
            if let memoryFileWillPublish {
                let prepared = try prepareMemoryPublicationFile(from: stagedURL)
                defer { try? FileManager.default.removeItem(at: prepared) }
                guard let thumbnailData = videoThumbnailDataSynchronously(
                    at: prepared
                ) else {
                    throw ChekinanaGalleryMediaStoreError.thumbnailFailed
                }
                let preparedThumbnail = try stagingDirectory().appendingPathComponent(
                    "\(UUID().uuidString.lowercased()).jpg"
                )
                defer { try? FileManager.default.removeItem(at: preparedThumbnail) }
                try thumbnailData.write(to: preparedThumbnail, options: [.atomic])
                try publishMemoryPreparedFile(
                    prepared, at: destination, willPublish: memoryFileWillPublish
                )
                try publishMemoryPreparedFile(
                    preparedThumbnail, at: thumbnail, willPublish: memoryFileWillPublish
                )
                return filename
            }
            do {
                if FileManager.default.fileExists(atPath: destination.path) {
                    try FileManager.default.removeItem(at: destination)
                }
                try materializeStagedImport(
                    from: stagedURL,
                    to: destination
                )
                guard let thumbnailData = videoThumbnailDataSynchronously(
                    at: destination
                ) else {
                    try? FileManager.default.removeItem(at: destination)
                    throw ChekinanaGalleryMediaStoreError.thumbnailFailed
                }
                try thumbnailData.write(to: thumbnail, options: [.atomic])
                return filename
            } catch let error as ChekinanaGalleryMediaStoreError {
                throw error
            } catch {
                try? FileManager.default.removeItem(at: destination)
                try? FileManager.default.removeItem(at: thumbnail)
                throw ChekinanaGalleryMediaStoreError.fileOperation(
                    error.localizedDescription
                )
            }
        }
    }

    /// Preparations stay in the existing owned staging directory. Failed
    /// teardown is discoverable by its existing staging cleanup, never as a
    /// public Memory attachment. The accepted input itself is not consumed.
    private static func prepareMemoryPublicationFile(from source: URL) throws -> URL {
        let prepared = try stagingDirectory().appendingPathComponent(
            "\(UUID().uuidString.lowercased()).\(source.pathExtension)"
        )
        do {
            try materializeStagedImport(from: source, to: prepared)
            return prepared
        } catch {
            try? FileManager.default.removeItem(at: prepared)
            throw error
        }
    }

    private static func publishMemoryPreparedFile(
        _ prepared: URL,
        at destination: URL,
        willPublish: MemoryFileWillPublish
    ) throws {
        let identity = try ChekinanaImportFileIdentity.inspect(prepared)
        try willPublish(destination, identity)
        let result = try prepared.withUnsafeFileSystemRepresentation { source in
            guard let source else { throw POSIXError(.EINVAL) }
            return try destination.withUnsafeFileSystemRepresentation { target in
                guard let target else { throw POSIXError(.EINVAL) }
                return Darwin.renameatx_np(
                    AT_FDCWD, source, AT_FDCWD, target, UInt32(RENAME_EXCL)
                )
            }
        }
        guard result == 0 else {
            // EXDEV is an error: never fall back to a partial public copy.
            throw POSIXError(POSIXErrorCode(rawValue: errno) ?? .EIO)
        }
        guard try ChekinanaImportFileIdentity.inspect(destination) == identity else {
            throw ChekinanaImportTransactionError.indeterminate
        }
    }

    static func managedURL(
        for reference: String?,
        id: UUID,
        kind: ChekinanaGalleryMediaKind,
        directory: URL? = nil
    ) -> URL? {
        guard let reference = reference?.trimmingCharacters(in: .whitespacesAndNewlines),
              reference == URL(fileURLWithPath: reference).lastPathComponent,
              reference != ".",
              reference != "..",
              isManagedFilename(reference) else { return nil }
        let expectedStem = "\(kind.rawValue)-\(id.uuidString.lowercased())"
        guard URL(fileURLWithPath: reference).deletingPathExtension().lastPathComponent
            == expectedStem,
              let resolvedDirectory = try? resolvedDirectory(directory) else { return nil }
        let candidate = resolvedDirectory.appendingPathComponent(reference)
        return ChekiImageRefResolver.isRegularReadableFile(candidate) ? candidate : nil
    }

    static func thumbnailURL(
        id: UUID,
        directory: URL? = nil
    ) -> URL {
        let resolved = (try? resolvedDirectory(directory)) ?? directory
            ?? FileManager.default.temporaryDirectory
        return resolved.appendingPathComponent(
            "douga-thumb-\(id.uuidString.lowercased()).jpg"
        )
    }

    static func thumbnailReference(id: UUID, directory: URL? = nil) -> String? {
        let url = thumbnailURL(id: id, directory: directory)
        return ChekiImageRefResolver.isRegularReadableFile(url) ? url.lastPathComponent : nil
    }

    static func videoThumbnailImage(
        at url: URL,
        maxDimension: Int = 512
    ) async -> ChekinanaRenderedImage? {
        guard maxDimension > 0 else { return nil }
        return try? await performFileIO(priority: .utility) {
            guard ChekiImageRefResolver.isRegularReadableFile(url),
                  let image = videoThumbnailImageSynchronously(
                    at: url,
                    maximumSize: CGSize(
                        width: maxDimension,
                        height: maxDimension
                    )
                  ) else { return nil }
            return ChekinanaRenderedImage(cgImage: image)
        }
    }

    /// Produces the exact thumbnail bytes that a file transaction will publish.
    /// Callers can hash and journal these bytes before the destination path is
    /// touched, eliminating the create-before-journal crash window.
    static func preparedVideoThumbnailData(at stagedURL: URL) async throws -> Data {
        try await performFileIO {
            guard isOwnedStagedImport(stagedURL),
                  ChekiImageRefResolver.isRegularReadableFile(stagedURL),
                  let data = videoThumbnailDataSynchronously(at: stagedURL) else {
                throw ChekinanaGalleryMediaStoreError.thumbnailFailed
            }
            return data
        }
    }

    static func removeFiles(
        kind: ChekinanaGalleryMediaKind,
        id: UUID,
        reference: String?,
        directory: URL? = nil,
        removeItem: (URL) throws -> Void = { try FileManager.default.removeItem(at: $0) }
    ) throws {
        let resolvedDirectory = try resolvedDirectory(directory)
        var urls: [URL] = []
        if let media = managedURL(
            for: reference,
            id: id,
            kind: kind,
            directory: resolvedDirectory
        ) {
            urls.append(media)
        }
        if kind == .douga {
            let thumbnail = thumbnailURL(id: id, directory: resolvedDirectory)
            if ChekiImageRefResolver.isRegularReadableFile(thumbnail) {
                urls.append(thumbnail)
            }
        }
        for url in urls {
            try removeItem(url)
        }
    }

    static func removeFilesInBackground(
        kind: ChekinanaGalleryMediaKind,
        id: UUID,
        reference: String?,
        directory: URL? = nil
    ) async throws {
        try await performFileIO(priority: .utility) {
            try removeFiles(
                kind: kind,
                id: id,
                reference: reference,
                directory: directory
            )
        }
    }

    static func removeAllManagedMediaFiles(directory: URL? = nil) throws {
        let resolvedDirectory = try resolvedDirectory(directory)
        let entries = try FileManager.default.contentsOfDirectory(
            at: resolvedDirectory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        for entry in entries {
            let name = entry.lastPathComponent
            guard isManagedFilename(name) || validQuarantineFilename(name) else {
                continue
            }
            let values = try entry.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            guard values.isRegularFile == true, values.isSymbolicLink != true else { continue }
            try FileManager.default.removeItem(at: entry)
        }
    }

    static func stageFilesForDeletion(
        kind: ChekinanaGalleryMediaKind,
        id: UUID,
        reference: String?,
        directory: URL? = nil,
        libraryGeneration: UUID? = nil,
        fileManager: FileManager = .default,
        defaults: UserDefaults = .standard,
        journalWriter: ((ChekinanaGalleryDeletionJournal, URL) throws -> Void)? = nil,
        beforeMove: ((URL, ChekinanaImportFileIdentity) throws -> Void)? = nil,
        moveItem: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        }
    ) throws -> [(original: URL, quarantine: URL)] {
        let resolvedDirectory = try resolvedDirectory(directory)
        var originals: [URL] = []
        if let media = managedURL(
            for: reference,
            id: id,
            kind: kind,
            directory: resolvedDirectory
        ) {
            originals.append(media)
        }
        if kind == .douga {
            let thumbnail = thumbnailURL(id: id, directory: resolvedDirectory)
            if ChekiImageRefResolver.isRegularReadableFile(thumbnail) {
                originals.append(thumbnail)
            }
        }
        guard !originals.isEmpty else { return [] }
        let operationID = UUID()
        let staged = originals.map { original in
            (
                original: original,
                quarantine: resolvedDirectory.appendingPathComponent(
                    ".delete-\(operationID.uuidString.lowercased())-\(original.lastPathComponent)"
                )
            )
        }
        let writeJournal = journalWriter ?? { journal, directory in
            try ChekinanaGalleryDeletionJournalStore.persist(
                journal,
                in: directory,
                fileManager: fileManager
            )
        }
        var journal: ChekinanaGalleryDeletionJournal?
        if let libraryGeneration {
            let entries = try staged.map { pair in
                ChekinanaGalleryDeletionJournal.Entry(
                    originalName: pair.original.lastPathComponent,
                    quarantineName: pair.quarantine.lastPathComponent,
                    identity: try ChekinanaImportFileIdentity.inspect(pair.original),
                    stage: .planned
                )
            }
            let value = ChekinanaGalleryDeletionJournal(
                formatVersion: 1,
                operationID: operationID,
                libraryGeneration: libraryGeneration,
                phase: .movingFiles,
                entries: entries
            )
            // This fsync-backed write is the point of no return. No managed
            // file is moved if the complete main+thumbnail plan cannot be
            // persisted and read back first.
            try writeJournal(value, resolvedDirectory)
            journal = value
        }
        var movedCount = 0
        do {
            for index in staged.indices {
                let pair = staged[index]
                if let expected = journal?.entries[index].identity {
                    try beforeMove?(pair.original, expected)
                }
                try moveItem(pair.original, pair.quarantine)
                movedCount += 1
                if var value = journal {
                    value.entries[index].stage = .quarantined
                    try writeJournal(value, resolvedDirectory)
                    journal = value
                }
            }
            if var value = journal {
                value.phase = .databaseCommitPending
                try writeJournal(value, resolvedDirectory)
                journal = value
            }
            return staged
        } catch {
            var fullyRestored = true
            for index in (0..<movedCount).reversed() {
                let pair = staged[index]
                guard fileManager.fileExists(atPath: pair.quarantine.path) else {
                    continue
                }
                do {
                    let expected: ChekinanaImportFileIdentity
                    if let journalIdentity = journal?.entries[index].identity {
                        expected = journalIdentity
                    } else {
                        expected = try ChekinanaImportFileIdentity.inspect(
                            pair.quarantine
                        )
                    }
                    if fileManager.fileExists(atPath: pair.original.path) {
                        guard try ChekinanaImportFileIdentity.inspect(pair.original)
                                == expected else {
                            fullyRestored = false
                            continue
                        }
                        try fileManager.removeItem(at: pair.quarantine)
                    } else {
                        guard try ChekinanaImportFileIdentity.inspect(pair.quarantine)
                                == expected else {
                            fullyRestored = false
                            continue
                        }
                        try moveItem(pair.quarantine, pair.original)
                    }
                    if var value = journal {
                        value.entries[index].stage = .restored
                        try writeJournal(value, resolvedDirectory)
                        journal = value
                    }
                } catch {
                    fullyRestored = false
                }
            }
            if fullyRestored, let value = journal {
                try? ChekinanaGalleryDeletionJournalStore.discard(
                    operationID: value.operationID,
                    in: resolvedDirectory,
                    fileManager: fileManager
                )
            } else if !fullyRestored {
                recordRestoreRecovery(
                    staged,
                    directory: resolvedDirectory,
                    defaults: defaults
                )
            }
            throw ChekinanaGalleryMediaStoreError.fileOperation(error.localizedDescription)
        }
    }

    static func restoreStagedFiles(
        _ files: [(original: URL, quarantine: URL)],
        fileManager: FileManager = .default,
        moveItem: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        }
    ) throws {
        guard let directory = files.first?.original.deletingLastPathComponent()
                .standardizedFileURL else { return }
        let operationIDs = Set(files.compactMap {
            ChekinanaGalleryDeletionJournalStore.operationID(
                fromQuarantineFilename: $0.quarantine.lastPathComponent
            )
        })
        var journal: ChekinanaGalleryDeletionJournal?
        if operationIDs.count == 1, let operationID = operationIDs.first {
            journal = try ChekinanaGalleryDeletionJournalStore.load(
                operationID: operationID,
                in: directory,
                fileManager: fileManager
            )
        }
        let journalEntries = Dictionary(uniqueKeysWithValues:
            (journal?.entries ?? []).map { ($0.quarantineName, $0) }
        )
        for pair in files.reversed() {
            guard pair.original.deletingLastPathComponent().standardizedFileURL == directory,
                  pair.quarantine.deletingLastPathComponent().standardizedFileURL == directory
            else { throw ChekinanaImportTransactionError.indeterminate }
            let expected = journalEntries[pair.quarantine.lastPathComponent]?.identity
            if fileManager.fileExists(atPath: pair.quarantine.path) {
                let quarantineIdentity = try ChekinanaImportFileIdentity.inspect(
                    pair.quarantine
                )
                if let expected, quarantineIdentity != expected {
                    throw ChekinanaImportTransactionError.indeterminate
                }
                if fileManager.fileExists(atPath: pair.original.path) {
                    let originalIdentity = try ChekinanaImportFileIdentity.inspect(
                        pair.original
                    )
                    guard originalIdentity == quarantineIdentity else {
                        // Both byte identities are retained for explicit
                        // recovery; an unrelated destination is never replaced.
                        throw ChekinanaImportTransactionError.indeterminate
                    }
                    try fileManager.removeItem(at: pair.quarantine)
                } else {
                    try moveItem(pair.quarantine, pair.original)
                    guard try ChekinanaImportFileIdentity.inspect(pair.original)
                            == quarantineIdentity else {
                        throw ChekinanaImportTransactionError.indeterminate
                    }
                }
            } else if let expected {
                guard fileManager.fileExists(atPath: pair.original.path),
                      try ChekinanaImportFileIdentity.inspect(pair.original)
                        == expected else {
                    throw ChekinanaImportTransactionError.indeterminate
                }
            }
            if var value = journal,
               let index = value.entries.firstIndex(where: {
                   $0.quarantineName == pair.quarantine.lastPathComponent
               }) {
                value.entries[index].stage = .restored
                try ChekinanaGalleryDeletionJournalStore.persist(
                    value,
                    in: directory,
                    fileManager: fileManager
                )
                journal = value
            }
        }
    }

    static func finalizeStagedDeletion(_ files: [(original: URL, quarantine: URL)]) throws {
        for pair in files where FileManager.default.fileExists(atPath: pair.quarantine.path) {
            try FileManager.default.removeItem(at: pair.quarantine)
        }
        removeCommittedDeletion(files)
    }

    static func recordCommittedDeletion(
        _ files: [(original: URL, quarantine: URL)],
        directory: URL? = nil,
        defaults: UserDefaults = .standard
    ) {
        guard let resolvedDirectory = try? resolvedDirectory(directory) else { return }
        let operationIDs = Set(files.compactMap {
            ChekinanaGalleryDeletionJournalStore.operationID(
                fromQuarantineFilename: $0.quarantine.lastPathComponent
            )
        })
        for operationID in operationIDs {
            let loaded: ChekinanaGalleryDeletionJournal?
            do {
                loaded = try ChekinanaGalleryDeletionJournalStore.load(
                    operationID: operationID,
                    in: resolvedDirectory
                )
            } catch { continue }
            guard var journal = loaded else { continue }
            journal.phase = .databaseCommitted
            try? ChekinanaGalleryDeletionJournalStore.persist(
                journal,
                in: resolvedDirectory
            )
        }
        let restoring = Set(restoreEntries(defaults: defaults).map(\.quarantine))
        let additions = files.compactMap { pair -> String? in
            guard pair.original.deletingLastPathComponent().standardizedFileURL == resolvedDirectory,
                  pair.quarantine.deletingLastPathComponent().standardizedFileURL == resolvedDirectory,
                  validRestoreEntry(
                    RestoreEntry(
                        original: pair.original.lastPathComponent,
                        quarantine: pair.quarantine.lastPathComponent
                    )
                  ),
                  !restoring.contains(pair.quarantine.lastPathComponent) else { return nil }
            return pair.quarantine.lastPathComponent
        }
        guard !additions.isEmpty else { return }
        let existing = defaults.stringArray(forKey: cleanupQueueKey) ?? []
        defaults.set(Array(Set(existing + additions)).sorted(), forKey: cleanupQueueKey)
    }

    static func recordRestoreRecovery(
        _ files: [(original: URL, quarantine: URL)],
        directory: URL? = nil,
        defaults: UserDefaults = .standard
    ) {
        guard let resolvedDirectory = try? resolvedDirectory(directory) else { return }
        let additions = files.compactMap { pair -> RestoreEntry? in
            guard pair.original.deletingLastPathComponent().standardizedFileURL == resolvedDirectory,
                  pair.quarantine.deletingLastPathComponent().standardizedFileURL == resolvedDirectory else {
                return nil
            }
            let entry = RestoreEntry(
                original: pair.original.lastPathComponent,
                quarantine: pair.quarantine.lastPathComponent
            )
            return validRestoreEntry(entry) ? entry : nil
        }
        guard !additions.isEmpty else { return }
        let merged = Array(Set(restoreEntries(defaults: defaults) + additions)).sorted {
            $0.quarantine < $1.quarantine
        }
        setRestoreEntries(merged, defaults: defaults)
        let restoring = Set(merged.map(\.quarantine))
        let committed = defaults.stringArray(forKey: cleanupQueueKey) ?? []
        defaults.set(committed.filter { !restoring.contains($0) }, forKey: cleanupQueueKey)
    }

    static func removeRestoreRecovery(
        _ files: [(original: URL, quarantine: URL)],
        defaults: UserDefaults = .standard
    ) {
        let removed = Set(files.map(\.quarantine.lastPathComponent))
        setRestoreEntries(
            restoreEntries(defaults: defaults).filter { !removed.contains($0.quarantine) },
            defaults: defaults
        )
        guard let directory = files.first?.original.deletingLastPathComponent()
                .standardizedFileURL else { return }
        let operationIDs = Set(files.compactMap {
            ChekinanaGalleryDeletionJournalStore.operationID(
                fromQuarantineFilename: $0.quarantine.lastPathComponent
            )
        })
        for operationID in operationIDs {
            let loaded: ChekinanaGalleryDeletionJournal?
            do {
                loaded = try ChekinanaGalleryDeletionJournalStore.load(
                    operationID: operationID,
                    in: directory
                )
            } catch { continue }
            guard let journal = loaded else { continue }
            let restored = journal.entries.allSatisfy { entry in
                let original = directory.appendingPathComponent(entry.originalName)
                let quarantine = directory.appendingPathComponent(entry.quarantineName)
                return !FileManager.default.fileExists(atPath: quarantine.path)
                    && (try? ChekinanaImportFileIdentity.inspect(original))
                        == entry.identity
            }
            if restored {
                try? ChekinanaGalleryDeletionJournalStore.discard(
                    operationID: operationID,
                    in: directory
                )
            }
        }
    }

    @discardableResult
    static func cleanupRestoreRecoveries(
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        moveItem: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        }
    ) -> Bool {
        guard let resolvedDirectory = try? resolvedDirectory(directory) else { return false }
        var remaining: [RestoreEntry] = []
        for entry in restoreEntries(defaults: defaults) where validRestoreEntry(entry) {
            let original = resolvedDirectory.appendingPathComponent(entry.original)
            let quarantine = resolvedDirectory.appendingPathComponent(entry.quarantine)
            let originalExists = FileManager.default.fileExists(atPath: original.path)
            let quarantineExists = FileManager.default.fileExists(atPath: quarantine.path)
            if originalExists, !quarantineExists,
               ChekiImageRefResolver.isRegularReadableFile(original) {
                continue
            }
            guard !originalExists, quarantineExists,
                  ChekiImageRefResolver.isRegularReadableFile(quarantine) else {
                remaining.append(entry)
                continue
            }
            do {
                try moveItem(quarantine, original)
                guard ChekiImageRefResolver.isRegularReadableFile(original) else {
                    remaining.append(entry)
                    continue
                }
            } catch {
                remaining.append(entry)
            }
        }
        setRestoreEntries(remaining, defaults: defaults)
        return remaining.isEmpty
    }

    static func restoreRecoveryFiles(
        kind: ChekinanaGalleryMediaKind,
        id: UUID,
        reference: String?,
        directory: URL? = nil,
        defaults: UserDefaults = .standard
    ) -> [(original: URL, quarantine: URL)] {
        guard let resolvedDirectory = try? resolvedDirectory(directory) else { return [] }
        let expected = Set(managedFilenames(kind: kind, id: id, reference: reference))
        return restoreEntries(defaults: defaults).compactMap { entry in
            guard validRestoreEntry(entry), expected.contains(entry.original) else { return nil }
            return (
                resolvedDirectory.appendingPathComponent(entry.original),
                resolvedDirectory.appendingPathComponent(entry.quarantine)
            )
        }
    }

    static func pendingRestoreRecoveryCount(defaults: UserDefaults = .standard) -> Int {
        restoreEntries(defaults: defaults).count
    }

    static func pendingCommittedDeletionCount(
        defaults: UserDefaults = .standard
    ) -> Int {
        defaults.stringArray(forKey: cleanupQueueKey)?.count ?? 0
    }

    static func recordOrphanedImport(
        kind: ChekinanaGalleryMediaKind,
        id: UUID,
        reference: String?,
        defaults: UserDefaults = .standard
    ) {
        let additions = managedFilenames(kind: kind, id: id, reference: reference)
        guard !additions.isEmpty else { return }
        let existing = defaults.stringArray(forKey: orphanQueueKey) ?? []
        defaults.set(Array(Set(existing + additions)).sorted(), forKey: orphanQueueKey)
    }

    static func cleanupOrphanedImports(
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        removeItem: (URL) throws -> Void = { try FileManager.default.removeItem(at: $0) }
    ) {
        guard let resolvedDirectory = try? resolvedDirectory(directory) else { return }
        let restoringOriginals = Set(restoreEntries(defaults: defaults).map(\.original))
        var remaining: [String] = []
        for filename in defaults.stringArray(forKey: orphanQueueKey) ?? [] {
            guard isManagedFilename(filename), !restoringOriginals.contains(filename) else {
                if restoringOriginals.contains(filename) { remaining.append(filename) }
                continue
            }
            let url = resolvedDirectory.appendingPathComponent(filename)
            guard FileManager.default.fileExists(atPath: url.path) else { continue }
            guard ChekiImageRefResolver.isRegularReadableFile(url) else { continue }
            do {
                try removeItem(url)
            } catch {
                remaining.append(filename)
            }
        }
        if remaining.isEmpty {
            defaults.removeObject(forKey: orphanQueueKey)
        } else {
            defaults.set(remaining, forKey: orphanQueueKey)
        }
    }

    static func pendingOrphanCleanupCount(defaults: UserDefaults = .standard) -> Int {
        defaults.stringArray(forKey: orphanQueueKey)?.count ?? 0
    }

    /// Rebinds every legacy Gallery queue to a newly committed library
    /// generation. A restore entry belongs to the replaced generation, so it
    /// must never move old quarantine bytes back over the new library. Its
    /// quarantine becomes committed cleanup, while an unreferenced original
    /// becomes orphan cleanup. Current references are removed only from the
    /// direct-original orphan queue.
    @MainActor
    @discardableResult
    static func reconcileAfterCommittedImport(
        referencedFilenames: Set<String>,
        defaults: UserDefaults = .standard
    ) -> Int {
        let restores: [RestoreEntry]
        let committed: Set<String>
        let orphans: Set<String>
        do {
            restores = try strictRestoreEntries(defaults: defaults)
            committed = try strictStringSet(forKey: cleanupQueueKey, defaults: defaults)
            orphans = try strictStringSet(forKey: orphanQueueKey, defaults: defaults)
        } catch {
            // Unknown persisted shapes are not rewritten. Leaving them in
            // place is safer than guessing at a destructive migration.
            return 1
        }

        let validCommitted = Set(committed.filter(validQuarantineFilename))
        let validOrphans = Set(orphans.filter(isManagedFilename))
        var reconciledCommitted = validCommitted
        var reconciledOrphans = validOrphans
        for entry in restores {
            reconciledCommitted.insert(entry.quarantine)
            if referencedFilenames.contains(entry.original) {
                reconciledOrphans.remove(entry.original)
            } else {
                reconciledOrphans.insert(entry.original)
            }
        }
        reconciledOrphans.subtract(referencedFilenames)

        setRestoreEntries([], defaults: defaults)
        setStringSet(
            Set(reconciledCommitted),
            forKey: cleanupQueueKey,
            defaults: defaults
        )
        setStringSet(
            Set(reconciledOrphans),
            forKey: orphanQueueKey,
            defaults: defaults
        )
        return 0
    }

    /// Runs the three Gallery journal state machines against one library
    /// snapshot. `removeCandidate` and `restoreCandidate` must revalidate the
    /// library generation, DB references, and file identity immediately before
    /// changing the filesystem.
    @MainActor
    @discardableResult
    static func cleanupSafely(
        referencedFilenames: Set<String>,
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        removeCandidate: (URL, String?, ChekinanaImportFileIdentity) -> Bool,
        restoreCandidate: (
            URL,
            URL,
            String,
            ChekinanaImportFileIdentity
        ) -> Bool
    ) -> Int {
        guard let resolvedDirectory = try? resolvedDirectory(directory) else { return 1 }
        var deferred = 0
        var restores: [RestoreEntry]
        var committed: Set<String>
        var orphans: Set<String>
        do {
            restores = try strictRestoreEntries(defaults: defaults)
            committed = try strictStringSet(forKey: cleanupQueueKey, defaults: defaults)
            orphans = try strictStringSet(forKey: orphanQueueKey, defaults: defaults)
        } catch {
            return 1
        }

        // Recover legacy, unregistered `.delete-*` files conservatively. Only
        // direct regular children matching the Gallery grammar are considered;
        // files claimed by a durable transaction journal are left to that
        // journal, and links/directories/outside paths are never followed.
        let loggedQuarantines: Set<String>
        do {
            loggedQuarantines = Set(
                try ChekinanaGalleryDeletionJournalStore.discover(
                    in: resolvedDirectory
                ).flatMap { $0.entries.map(\.quarantineName) }
            )
        } catch {
            return 1
        }
        let registeredQuarantines = Set(restores.map(\.quarantine))
            .union(committed)
            .union(loggedQuarantines)
        let directoryEntries = (try? FileManager.default.contentsOfDirectory(
            at: resolvedDirectory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
            options: []
        )) ?? []
        for quarantine in directoryEntries {
            let filename = quarantine.lastPathComponent
            guard quarantine.standardizedFileURL.deletingLastPathComponent()
                    == resolvedDirectory.standardizedFileURL,
                  validQuarantineFilename(filename),
                  !registeredQuarantines.contains(filename),
                  let originalName = originalFilename(
                    fromDeletionQuarantine: filename
                  ),
                  let values = try? quarantine.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                  ),
                  values.isRegularFile == true,
                  values.isSymbolicLink != true,
                  let identity = try? ChekinanaImportFileIdentity.inspect(quarantine)
            else { continue }
            let original = resolvedDirectory.appendingPathComponent(originalName)
            if referencedFilenames.contains(originalName) {
                if FileManager.default.fileExists(atPath: original.path) {
                    guard let originalIdentity = try? ChekinanaImportFileIdentity.inspect(
                        original
                    ), originalIdentity == identity,
                    removeCandidate(quarantine, nil, identity) else {
                        deferred += 1
                        continue
                    }
                } else if !restoreCandidate(
                    quarantine,
                    original,
                    originalName,
                    identity
                ) {
                    deferred += 1
                }
            } else if !removeCandidate(quarantine, nil, identity) {
                deferred += 1
            }
        }

        var remainingRestores: [RestoreEntry] = []
        for entry in restores {
            let original = resolvedDirectory.appendingPathComponent(entry.original)
            let quarantine = resolvedDirectory.appendingPathComponent(entry.quarantine)
            let originalExists = FileManager.default.fileExists(atPath: original.path)
            let quarantineExists = FileManager.default.fileExists(atPath: quarantine.path)

            guard referencedFilenames.contains(entry.original) else {
                // The DB deletion committed. Do not resurrect the original;
                // make both possible names converge through their own queues.
                committed.insert(entry.quarantine)
                orphans.insert(entry.original)
                continue
            }
            if originalExists, !quarantineExists,
               ChekiImageRefResolver.isRegularReadableFile(original) {
                continue
            }
            guard !originalExists, quarantineExists,
                  let identity = try? ChekinanaImportFileIdentity.inspect(quarantine),
                  restoreCandidate(
                    quarantine,
                    original,
                    entry.original,
                    identity
                  ) else {
                remainingRestores.append(entry)
                deferred += 1
                continue
            }
        }
        restores = remainingRestores
        setRestoreEntries(restores, defaults: defaults)

        let restoringQuarantines = Set(restores.map(\.quarantine))
        var remainingCommitted = Set<String>()
        for filename in committed {
            guard validQuarantineFilename(filename) else { continue }
            guard !restoringQuarantines.contains(filename) else {
                remainingCommitted.insert(filename)
                continue
            }
            let url = resolvedDirectory.appendingPathComponent(filename)
            guard FileManager.default.fileExists(atPath: url.path) else { continue }
            guard let identity = try? ChekinanaImportFileIdentity.inspect(url),
                  removeCandidate(url, nil, identity) else {
                remainingCommitted.insert(filename)
                deferred += 1
                continue
            }
        }
        setStringSet(
            remainingCommitted,
            forKey: cleanupQueueKey,
            defaults: defaults
        )

        var remainingOrphans = Set<String>()
        for filename in orphans {
            guard isManagedFilename(filename) else { continue }
            guard !referencedFilenames.contains(filename) else { continue }
            let url = resolvedDirectory.appendingPathComponent(filename)
            guard FileManager.default.fileExists(atPath: url.path) else { continue }
            guard let identity = try? ChekinanaImportFileIdentity.inspect(url),
                  removeCandidate(url, filename, identity) else {
                remainingOrphans.insert(filename)
                deferred += 1
                continue
            }
        }
        setStringSet(
            remainingOrphans,
            forKey: orphanQueueKey,
            defaults: defaults
        )
        return deferred
    }

    static func reconcileQueuesAfterFullClear(
        failedFilenames: Set<String>?,
        defaults: UserDefaults = .standard
    ) {
        let restores = restoreEntries(defaults: defaults)
        var committed = Set(defaults.stringArray(forKey: cleanupQueueKey) ?? [])
        var orphans = Set(defaults.stringArray(forKey: orphanQueueKey) ?? [])
        committed.formUnion(restores.map(\.quarantine))
        orphans.formUnion(restores.map(\.original))

        if let failedFilenames {
            committed = Set(committed.filter(failedFilenames.contains))
            orphans = Set(orphans.filter(failedFilenames.contains))
            for filename in failedFilenames {
                if isManagedFilename(filename) {
                    orphans.insert(filename)
                } else if validQuarantineFilename(filename) {
                    committed.insert(filename)
                }
            }
        }

        defaults.removeObject(forKey: restoreQueueKey)
        if committed.isEmpty {
            defaults.removeObject(forKey: cleanupQueueKey)
        } else {
            defaults.set(committed.sorted(), forKey: cleanupQueueKey)
        }
        if orphans.isEmpty {
            defaults.removeObject(forKey: orphanQueueKey)
        } else {
            defaults.set(orphans.sorted(), forKey: orphanQueueKey)
        }
    }

    static func cleanupCommittedDeletions(
        directory: URL? = nil,
        defaults: UserDefaults = .standard
    ) {
        guard let resolvedDirectory = try? resolvedDirectory(directory) else { return }
        let queued = defaults.stringArray(forKey: cleanupQueueKey) ?? []
        let restoring = Set(restoreEntries(defaults: defaults).map(\.quarantine))
        var remaining: [String] = []
        for filename in queued {
            guard filename.hasPrefix(".delete-"),
                  filename == URL(fileURLWithPath: filename).lastPathComponent,
                  !restoring.contains(filename) else {
                continue
            }
            let url = resolvedDirectory.appendingPathComponent(filename)
            guard FileManager.default.fileExists(atPath: url.path) else { continue }
            do {
                let values = try url.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                )
                guard values.isRegularFile == true, values.isSymbolicLink != true else {
                    continue
                }
                try FileManager.default.removeItem(at: url)
            } catch {
                remaining.append(filename)
            }
        }
        if remaining.isEmpty {
            defaults.removeObject(forKey: cleanupQueueKey)
        } else {
            defaults.set(remaining, forKey: cleanupQueueKey)
        }
    }

    static func makeStagedVideoCopy(from source: URL) throws -> URL {
        try makeStagedVideoCopy(
            from: source,
            fileSize: {
                Int64(try $0.resourceValues(forKeys: [.fileSizeKey]).fileSize ?? 0)
            },
            copyItem: { try FileManager.default.copyItem(at: $0, to: $1) }
        )
    }

    /// Staged imports and managed media normally share the app container's
    /// filesystem, so a hard link avoids a second full-byte media copy. The
    /// staged link remains available until the database save commits, keeping
    /// the existing retry/rollback guarantee. Filesystems that reject links
    /// transparently use the prior copy behavior.
    @discardableResult
    static func materializeStagedImport(
        from source: URL,
        to destination: URL,
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        },
        linkItem: (URL, URL) throws -> Void = {
            try FileManager.default.linkItem(at: $0, to: $1)
        },
        copyItem: (URL, URL) throws -> Void = {
            try FileManager.default.copyItem(at: $0, to: $1)
        }
    ) throws -> Bool {
        do {
            try linkItem(source, destination)
            return true
        } catch {
            try? removeItem(destination)
            try copyItem(source, destination)
            return false
        }
    }

    static func makeStagedVideoCopy(
        from source: URL,
        fileSize: (URL) throws -> Int64,
        copyItem: (URL, URL) throws -> Void
    ) throws -> URL {
        guard ChekiImageRefResolver.isRegularReadableFile(source) else {
            throw ChekinanaGalleryMediaStoreError.invalidMedia
        }
        let size = try fileSize(source)
        guard size > 0, size <= maximumVideoBytes else {
            throw ChekinanaGalleryMediaStoreError.invalidMedia
        }
        let stagingDirectory = try stagingDirectory()
        let ext = normalizedVideoExtension(source.pathExtension)
        let destination = stagingDirectory.appendingPathComponent(
            "\(UUID().uuidString.lowercased()).\(ext)"
        )
        try copyItem(source, destination)
        return destination
    }

    static func discardStagedVideo(at url: URL?) {
        guard let url, isOwnedStagedImport(url) else { return }
        try? FileManager.default.removeItem(at: url)
    }

    static func discardStagedImport(at url: URL?) async {
        try? await performFileIO(priority: .utility) {
            discardStagedVideo(at: url)
        }
    }

    static func cleanupStagedImports() {
        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("ChekinanaGalleryImports", isDirectory: true)
        guard let entries = try? FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        ) else { return }
        for entry in entries {
            guard let values = try? entry.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            ), values.isRegularFile == true, values.isSymbolicLink != true else { continue }
            try? FileManager.default.removeItem(at: entry)
        }
    }

    private static func restoreEntries(defaults: UserDefaults) -> [RestoreEntry] {
        guard let data = defaults.data(forKey: restoreQueueKey),
              let decoded = try? JSONDecoder().decode([RestoreEntry].self, from: data) else {
            return []
        }
        return decoded.filter(validRestoreEntry)
    }

    private static func strictRestoreEntries(
        defaults: UserDefaults
    ) throws -> [RestoreEntry] {
        guard defaults.object(forKey: restoreQueueKey) != nil else { return [] }
        guard let data = defaults.data(forKey: restoreQueueKey),
              let decoded = try? JSONDecoder().decode([RestoreEntry].self, from: data),
              decoded.allSatisfy(validRestoreEntry),
              Set(decoded).count == decoded.count else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return decoded
    }

    private static func strictStringSet(
        forKey key: String,
        defaults: UserDefaults
    ) throws -> Set<String> {
        guard defaults.object(forKey: key) != nil else { return [] }
        guard let values = defaults.stringArray(forKey: key) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return Set(values)
    }

    private static func setStringSet(
        _ values: Set<String>,
        forKey key: String,
        defaults: UserDefaults
    ) {
        if values.isEmpty {
            defaults.removeObject(forKey: key)
        } else {
            defaults.set(values.sorted(), forKey: key)
        }
    }

    private static func setRestoreEntries(
        _ entries: [RestoreEntry],
        defaults: UserDefaults
    ) {
        guard !entries.isEmpty,
              let data = try? JSONEncoder().encode(entries) else {
            defaults.removeObject(forKey: restoreQueueKey)
            return
        }
        defaults.set(data, forKey: restoreQueueKey)
    }

    private static func validRestoreEntry(_ entry: RestoreEntry) -> Bool {
        guard isManagedFilename(entry.original),
              entry.original == URL(fileURLWithPath: entry.original).lastPathComponent,
              entry.quarantine == URL(fileURLWithPath: entry.quarantine).lastPathComponent,
              entry.quarantine.hasPrefix(".delete-") else { return false }
        let suffix = "-\(entry.original)"
        guard entry.quarantine.hasSuffix(suffix) else { return false }
        let start = entry.quarantine.index(
            entry.quarantine.startIndex,
            offsetBy: ".delete-".count
        )
        let end = entry.quarantine.index(entry.quarantine.endIndex, offsetBy: -suffix.count)
        return start < end && UUID(uuidString: String(entry.quarantine[start..<end])) != nil
    }

    private static func validQuarantineFilename(_ filename: String) -> Bool {
        guard filename == URL(fileURLWithPath: filename).lastPathComponent,
              filename.hasPrefix(".delete-") else { return false }
        let remainder = String(filename.dropFirst(".delete-".count))
        guard remainder.count > 37 else { return false }
        let uuidText = String(remainder.prefix(36))
        guard UUID(uuidString: uuidText) != nil,
              remainder[remainder.index(remainder.startIndex, offsetBy: 36)] == "-" else {
            return false
        }
        let original = String(remainder.dropFirst(37))
        return isManagedFilename(original)
    }

    static func isManagedDeletionFilename(_ filename: String) -> Bool {
        isManagedFilename(filename)
    }

    static func originalFilename(fromDeletionQuarantine filename: String) -> String? {
        guard validQuarantineFilename(filename) else { return nil }
        let remainder = filename.dropFirst(".delete-".count)
        guard remainder.count > 37 else { return nil }
        return String(remainder.dropFirst(37))
    }

    static func managedFilenames(
        kind: ChekinanaGalleryMediaKind,
        id: UUID,
        reference: String?
    ) -> [String] {
        var values: [String] = []
        if let reference = reference?.trimmingCharacters(in: .whitespacesAndNewlines),
           reference == URL(fileURLWithPath: reference).lastPathComponent,
           URL(fileURLWithPath: reference).deletingPathExtension().lastPathComponent
            == "\(kind.rawValue)-\(id.uuidString.lowercased())",
           isManagedFilename(reference) {
            values.append(reference)
        }
        if kind == .douga {
            values.append("douga-thumb-\(id.uuidString.lowercased()).jpg")
        }
        return values
    }

    private static func isManagedFilename(_ filename: String) -> Bool {
        guard filename == URL(fileURLWithPath: filename).lastPathComponent else { return false }
        let lowercased = filename.lowercased()
        let patterns = [
            #"^shame-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]{1,12}$"#,
            #"^douga-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]{1,12}$"#,
            #"^douga-thumb-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.jpg$"#,
        ]
        return patterns.contains {
            lowercased.range(of: $0, options: .regularExpression) != nil
        }
    }

    private static func removeCommittedDeletion(
        _ files: [(original: URL, quarantine: URL)],
        defaults: UserDefaults = .standard
    ) {
        let removed = Set(files.map(\.quarantine.lastPathComponent))
        let existing = defaults.stringArray(forKey: cleanupQueueKey) ?? []
        let remaining = existing.filter { !removed.contains($0) }
        if remaining.isEmpty {
            defaults.removeObject(forKey: cleanupQueueKey)
        } else {
            defaults.set(remaining, forKey: cleanupQueueKey)
        }
    }

    private static func resolvedDirectory(_ directory: URL?) throws -> URL {
        let resolved = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        try FileManager.default.createDirectory(
            at: resolved,
            withIntermediateDirectories: true
        )
        return resolved.standardizedFileURL
    }

    private static func imageExtension(
        for source: CGImageSource,
        fallback: String
    ) -> String {
        if let typeIdentifier = CGImageSourceGetType(source) as String?,
           let preferredExtension = UTType(typeIdentifier)?.preferredFilenameExtension {
            return safeMediaExtension(preferredExtension, fallback: "jpg")
        }
        return safeMediaExtension(fallback, fallback: "jpg")
    }

    private static func normalizedVideoExtension(_ value: String) -> String {
        safeMediaExtension(value, fallback: "mp4")
    }

    static func safeMediaExtension(
        _ value: String,
        fallback: String
    ) -> String {
        let normalized = value.lowercased()
        guard (1...12).contains(normalized.count),
              normalized.utf8.allSatisfy({ byte in
                  (byte >= 97 && byte <= 122) || (byte >= 48 && byte <= 57)
              }) else {
            return fallback
        }
        return normalized
    }

    /// Shared classification used by full-library cleanup. These wrappers keep
    /// the Gallery filename grammar authoritative without exposing queue
    /// storage details or allowing arbitrary hidden files to become deletable.
    static func isRecognizedDeletionQuarantineFilename(
        _ filename: String
    ) -> Bool {
        validQuarantineFilename(filename)
    }

    private static func stagingDirectory() throws -> URL {
        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("ChekinanaGalleryImports", isDirectory: true)
        try FileManager.default.createDirectory(
            at: directory,
            withIntermediateDirectories: true
        )
        return directory.standardizedFileURL
    }

    private static func isOwnedStagedImport(_ url: URL) -> Bool {
        url.standardizedFileURL.deletingLastPathComponent().lastPathComponent
            == "ChekinanaGalleryImports"
    }

    private static func videoThumbnailDataSynchronously(at url: URL) -> Data? {
        guard let image = videoThumbnailImageSynchronously(
            at: url,
            maximumSize: CGSize(width: 1_200, height: 1_200)
        ) else { return nil }
        return UIImage(cgImage: image).jpegData(compressionQuality: 0.82)
    }

    private static func videoThumbnailImageSynchronously(
        at url: URL,
        maximumSize: CGSize
    ) -> CGImage? {
        let generator = AVAssetImageGenerator(asset: AVURLAsset(url: url))
        generator.appliesPreferredTrackTransform = true
        generator.maximumSize = maximumSize
        return try? generator.copyCGImage(
            at: CMTime(seconds: 0, preferredTimescale: 600),
            actualTime: nil
        )
    }
}

private enum ChekinanaGalleryFilter: String, CaseIterable, Identifiable {
    case all = "All"
    case favorites = "Favorites"
    var id: String { rawValue }
}

private enum ChekinanaGalleryContentType: String, CaseIterable, Identifiable {
    case cheki
    case shame
    case douga
    case memory

    var id: String { rawValue }

    var title: String {
        switch self {
        case .cheki: ChekinanaRecordKind.cheki.title
        case .shame: ChekinanaRecordKind.shame.title
        case .douga: ChekinanaRecordKind.douga.title
        case .memory: ChekinanaProductCopy.text("gallery.memory", "Memory")
        }
    }

    var mediaKind: ChekinanaRecordKind? {
        switch self {
        case .cheki: .cheki
        case .shame: .shame
        case .douga: .douga
        case .memory: nil
        }
    }
}

enum ChekinanaGalleryOrder: String, CaseIterable, Identifiable {
    case dateAscending
    case dateDescending

    var id: String { rawValue }

    var stateTitle: String {
        switch self {
        case .dateAscending:
            ChekinanaProductCopy.text(
                "gallery.sort.time.ascending",
                "Oldest first"
            )
        case .dateDescending:
            ChekinanaProductCopy.text(
                "gallery.sort.time.descending",
                "Newest first"
            )
        }
    }

    var next: Self {
        switch self {
        case .dateAscending: .dateDescending
        case .dateDescending: .dateAscending
        }
    }
}

struct ChekinanaGalleryDateRange: Equatable {
    var start: Date
    var end: Date

    init(start: Date, end: Date) {
        let fallback = ChekinanaProductDate.fixtureAwareToday
        self.start = ChekinanaDateOnly.canonicalized(start) ?? fallback
        self.end = ChekinanaDateOnly.canonicalized(end) ?? fallback
        normalize()
    }

    mutating func setStart(_ value: Date) {
        start = ChekinanaDateOnly.canonicalized(value) ?? start
        if start > end { end = start }
    }

    mutating func setEnd(_ value: Date) {
        end = ChekinanaDateOnly.canonicalized(value) ?? end
        if start > end { start = end }
    }

    func includes(_ date: Date?) -> Bool {
        guard let day = date.flatMap(ChekinanaDateOnly.canonicalized) else {
            return false
        }
        return day >= start && day <= end
    }

    private mutating func normalize() {
        if start > end { end = start }
    }

    static func defaultRange(earliest: Date?, today: Date) -> Self {
        let canonicalToday = ChekinanaDateOnly.canonicalized(today) ?? today
        return .init(start: earliest ?? canonicalToday, end: canonicalToday)
    }
}

struct ChekinanaGalleryDateRangeState: Equatable {
    private(set) var range: ChekinanaGalleryDateRange
    private(set) var defaultRange: ChekinanaGalleryDateRange
    private(set) var isActive = false
    private(set) var hasInitialized = false
    private(set) var didManuallyEditStart = false

    init(today: Date) {
        let value = ChekinanaGalleryDateRange.defaultRange(
            earliest: nil,
            today: today
        )
        range = value
        defaultRange = value
    }

    mutating func syncDefaults(earliest: Date?, today: Date) {
        let updated = ChekinanaGalleryDateRange.defaultRange(
            earliest: earliest,
            today: today
        )
        defaultRange = updated
        if !hasInitialized {
            range = updated
            hasInitialized = true
        } else if !didManuallyEditStart {
            range.setStart(updated.start)
        }
    }

    mutating func applyUserRange(
        _ value: ChekinanaGalleryDateRange,
        startWasEdited: Bool
    ) {
        range = value
        isActive = true
        didManuallyEditStart = didManuallyEditStart || startWasEdited
    }

    mutating func reset() {
        range = defaultRange
        isActive = false
        didManuallyEditStart = false
    }

    func includes(_ date: Date?) -> Bool {
        !isActive || range.includes(date)
    }
}

/// Copy sorting fields before editing so live model mutations cannot change the baseline.
struct ChekinanaGallerySortWitness: Equatable {
    let date: Date?
    let idolIDs: Set<UUID>
    let index: Int?
    let isTwoShot: Bool
    init(_ item: ChekinanaGalleryItem) {
        date = item.date
        idolIDs = Set(item.idolIDs)
        if case .cheki(let model) = item { index = model.idx } else { index = nil }
        isTwoShot = item.chekiUserAppears == true
    }
    func mayChangeIdolCounts(comparedTo previous: Self) -> Bool {
        idolIDs != previous.idolIDs
    }
}

enum ChekinanaGalleryOrdering {
    /// Model reads and Idol ordering happen once before the comparison loop.
    /// In particular, sorting must not repeatedly resolve SwiftData relations.
    private struct Entry {
        let item: ChekinanaGalleryItem
        let date: Date?
        let day: Date?
        let idolRanks: [Int]
        let isCheki: Bool
        let index: Int?
        let identifier: String
    }

    static func ordered(
        _ values: [ChekinanaGalleryItem],
        order: ChekinanaGalleryOrder,
        sortByIdol: Bool,
        chekiCountsByIdolID: [UUID: Int] = [:]
    ) -> [ChekinanaGalleryItem] {
        let idolGroups = values.map(\.idols)
        let orderedIdols = ChekinanaIdolOrdering.Context(
            chekiCountsByIdolID: chekiCountsByIdolID
        ).orderedUnique(idolGroups.flatMap { $0 })
        let rankByID = Dictionary(uniqueKeysWithValues:
            orderedIdols.enumerated().map { ($0.element.id, $0.offset) }
        )
        let entries = zip(values, idolGroups).map { item, idols in
            let date = item.date
            let isCheki: Bool
            let index: Int?
            if case .cheki(let cheki) = item {
                isCheki = true
                index = cheki.idx
            } else {
                isCheki = false
                index = nil
            }
            return Entry(
                item: item,
                date: date,
                day: sortByIdol ? nil : date.map {
                    ChekinanaDateOnly.canonicalDate(from: $0, displayedIn: .current) ?? $0
                },
                idolRanks: Set(idols.compactMap { rankByID[$0.id] }).sorted(),
                isCheki: isCheki,
                index: index,
                identifier: item.modelID.uuidString
            )
        }
        let ascending = order == .dateAscending
        let sorted = entries.sorted { lhs, rhs in
            if sortByIdol {
                if let comparison = combinationPrecedes(lhs.idolRanks, rhs.idolRanks) {
                    return comparison
                }
                if let comparison = datePrecedes(lhs.date, rhs.date, ascending: ascending) {
                    return comparison
                }
            } else {
                if let comparison = datePrecedes(lhs.day, rhs.day, ascending: ascending) {
                    return comparison
                }
                if let comparison = combinationPrecedes(lhs.idolRanks, rhs.idolRanks) {
                    return comparison
                }
            }
            // Keep the original optional-index rule, including nil vs Int.max.
            if lhs.isCheki, rhs.isCheki, lhs.index != rhs.index {
                return (lhs.index ?? .max) < (rhs.index ?? .max)
            }
            return lhs.identifier < rhs.identifier
        }.map(\.item)
        return ChekinanaShotDisplayOrdering.gallery(sorted)
    }

    static func primaryIdolID(
        for item: ChekinanaGalleryItem,
        chekiCountsByIdolID: [UUID: Int] = [:]
    ) -> UUID? {
        ChekinanaIdolOrdering.orderedForList(
            item.idols,
            chekiCountsByIdolID: chekiCountsByIdolID
        ).first?.id
    }

    private static func combinationPrecedes(_ lhs: [Int], _ rhs: [Int]) -> Bool? {
        switch (lhs.isEmpty, rhs.isEmpty) {
        case (true, true): return nil
        case (false, true): return true
        case (true, false): return false
        default: break
        }
        for (left, right) in zip(lhs, rhs) where left != right {
            return left < right
        }
        return lhs.count == rhs.count ? nil : lhs.count < rhs.count
    }

    private static func datePrecedes(_ lhs: Date?, _ rhs: Date?, ascending: Bool) -> Bool? {
        switch (lhs, rhs) {
        case let (left?, right?) where left != right: return ascending ? left < right : left > right
        case (_?, nil): return true
        case (nil, _?): return false
        default: return nil
        }
    }
}

enum ChekinanaGalleryShotFilter: String, CaseIterable, Identifiable {
    case all
    case solo
    case twoShot = "two-shot"

    var id: String { rawValue }

