        case .twoShot:
            ChekinanaProductCopy.text("gallery.shot_filter.two_shot", "2-shot")
        }
    }

    var next: Self {
        switch self {
        case .all: .solo
        case .solo: .twoShot
        case .twoShot: .all
        }
    }

    func includes(_ userAppears: Bool?) -> Bool {
        switch self {
        case .all: true
        case .solo: userAppears != true
        case .twoShot: userAppears == true
