        case .invalidIndex: "error.invalid_index"
        case .indexCollision: "error.index_collision"
        case .invalidBatchQuantity: "error.record_quantity"
        }
    }

    var fallback: String {
        switch self {
        case .modelContextMismatch:
            ChekinanaL10n.text("product.error.record_context_mismatch", fallback: "The selected relationships are no longer available in this library.")
        case .indexOverflow:
