private struct ChekinanaGalleryGridThumbSlider: UIViewRepresentable {
    @Binding var value: Double
    let range: ClosedRange<Double>
    let step: Double

    func makeCoordinator() -> Coordinator {
        Coordinator(parent: self)
    }

    func makeUIView(context: Context) -> UISlider {
        let slider = UISlider(frame: .zero)
        slider.minimumValue = Float(range.lowerBound)
        slider.maximumValue = Float(range.upperBound)
        slider.isContinuous = true
        slider.setThumbImage(Self.compactThumbImage, for: .normal)
        slider.setThumbImage(Self.compactThumbImage, for: .highlighted)
        slider.addTarget(
            context.coordinator,
            action: #selector(Coordinator.valueChanged(_:)),
            for: .valueChanged
        )
        return slider
    }

    func updateUIView(_ slider: UISlider, context: Context) {
        context.coordinator.parent = self
        slider.minimumValue = Float(range.lowerBound)
        slider.maximumValue = Float(range.upperBound)
        if abs(Double(slider.value) - value) > 0.001 {
            slider.setValue(Float(value), animated: false)
        }
    }

    final class Coordinator: NSObject {
        var parent: ChekinanaGalleryGridThumbSlider

        init(parent: ChekinanaGalleryGridThumbSlider) {
            self.parent = parent
        }

        @MainActor @objc func valueChanged(_ slider: UISlider) {
            let raw = Double(slider.value)
            let stepped = ((raw - parent.range.lowerBound) / parent.step).rounded()
                * parent.step + parent.range.lowerBound
            let value = min(parent.range.upperBound, max(parent.range.lowerBound, stepped))
            slider.setValue(Float(value), animated: false)
            parent.value = value
        }
    }

    private static let compactThumbImage: UIImage = {
        let diameter: CGFloat = 15
        return UIGraphicsImageRenderer(size: CGSize(width: diameter, height: diameter))
            .image { context in
                let rect = CGRect(x: 0.5, y: 0.5, width: diameter - 1, height: diameter - 1)
                UIColor.systemBackground.setFill()
                context.cgContext.fillEllipse(in: rect)
                UIColor.separator.setStroke()
                context.cgContext.setLineWidth(0.5)
                context.cgContext.strokeEllipse(in: rect)
            }
    }()
}

private struct ChekinanaGalleryGridSizeControl: View {
    @Binding var columnCount: Int
    @State private var draftValue: Double

    init(columnCount: Binding<Int>) {
        _columnCount = columnCount
        _draftValue = State(
            initialValue: ChekinanaGalleryGridSizePolicy.sliderValue(
                forColumnCount: columnCount.wrappedValue
            )
        )
    }

    private var sliderValue: Binding<Double> {
        Binding(
            get: { draftValue },
            set: {
                draftValue = $0
                let snapped = ChekinanaGalleryGridSizePolicy.columnCount(forSliderValue: $0)
                if snapped != columnCount { columnCount = snapped }
            }
        )
    }

    var body: some View {
        HStack(spacing: ChekinanaGalleryGridControlLayout.spacing) {
            Image(systemName: "square.grid.3x3.fill")
                .font(.system(size: ChekinanaGalleryGridControlLayout.iconVisualSize))
                .frame(
                    width: ChekinanaGalleryGridControlLayout.iconWidth,
                    height: ChekinanaGalleryGridControlLayout.iconHeight
                )
                .accessibilityHidden(true)
            ChekinanaGalleryGridThumbSlider(
                value: sliderValue,
                range: Double(ChekinanaGalleryGridSizePolicy.minimumColumnCount)...Double(ChekinanaGalleryGridSizePolicy.maximumColumnCount),
                step: 1
            )
            .accessibilityLabel(ChekinanaProductCopy.text(
                "gallery.grid_size.label",
                "Image size"
            ))
            .accessibilityValue(ChekinanaProductCopy.format(
                "gallery.grid_size.columns",
                "%lld columns",
                Int64(columnCount)
            ))
            .accessibilityHint(ChekinanaProductCopy.text(
                "gallery.grid_size.hint",
                "Move right for larger images and fewer columns per row."
            ))
            .accessibilityIdentifier("chekinana.gallery.grid-size")
            Image(systemName: "photo.fill")
                .font(.system(size: ChekinanaGalleryGridControlLayout.iconVisualSize))
                .frame(
                    width: ChekinanaGalleryGridControlLayout.iconWidth,
                    height: ChekinanaGalleryGridControlLayout.iconHeight
                )
                .accessibilityHidden(true)
        }
        .frame(
            width: ChekinanaGalleryGridControlLayout.controlWidth,
            height: ChekinanaGalleryGridControlLayout.controlHeight
        )
        .overlay(alignment: .leading) {
            gridStepButton(
                value: ChekinanaGalleryGridSizePolicy.smallerImages(from: columnCount),
                isDisabled: columnCount
                    >= ChekinanaGalleryGridSizePolicy.maximumColumnCount,
                labelKey: "gallery.grid_size.smaller",
                fallbackLabel: "Smaller images",
                identifier: "chekinana.gallery.grid-size.smaller"
            )
            .offset(x: -ChekinanaGalleryGridControlLayout.hitTargetOutset)
        }
        .overlay(alignment: .trailing) {
            gridStepButton(
                value: ChekinanaGalleryGridSizePolicy.largerImages(from: columnCount),
                isDisabled: columnCount
                    <= ChekinanaGalleryGridSizePolicy.minimumColumnCount,
                labelKey: "gallery.grid_size.larger",
                fallbackLabel: "Larger images",
                identifier: "chekinana.gallery.grid-size.larger"
            )
            .offset(x: ChekinanaGalleryGridControlLayout.hitTargetOutset)
        }
    }

    private var gridSizeAccessibilityValue: String {
        ChekinanaProductCopy.format(
            "gallery.grid_size.columns",
            "%lld columns",
            Int64(columnCount)
        )
    }

    private func setColumnCount(_ value: Int) {
        guard value != columnCount else { return }
        columnCount = value
        draftValue = ChekinanaGalleryGridSizePolicy.sliderValue(
            forColumnCount: value
        )
    }

    private func gridStepButton(
        value: Int,
        isDisabled: Bool,
        labelKey: String,
        fallbackLabel: String,
        identifier: String
    ) -> some View {
        Button {
            setColumnCount(value)
        } label: {
            Color.clear
                .frame(
                    width: ChekinanaGalleryGridControlLayout.hitTargetSide,
                    height: ChekinanaGalleryGridControlLayout.hitTargetSide
                )
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .disabled(isDisabled)
        .accessibilityLabel(ChekinanaProductCopy.text(labelKey, fallbackLabel))
        .accessibilityValue(gridSizeAccessibilityValue)
        .accessibilityIdentifier(identifier)
    }
}

