private struct ChekinanaGalleryFilterDraft {
    enum Kind { case idols, dates }
    let category: ChekinanaGalleryContentType
    let kind: Kind
    var value: ChekinanaGalleryTypeFilterState
    var isConfirmed = false

    func applying(to applied: ChekinanaGalleryTypeFilterState) -> ChekinanaGalleryTypeFilterState {
        var result = applied
        switch kind {
        case .idols:
            result.unassignedOnly = value.unassignedOnly
            result.selectedIdolIDs = value.selectedIdolIDs
        case .dates:
            result.dateRangeState = value.dateRangeState
        }
        return result
    }

    static func consume(_ draft: inout Self?) -> Self? {
        defer { draft = nil }
        return draft?.isConfirmed == true ? draft : nil
    }
}

