private struct ChekinanaGalleryPhotoExportItem {
    let reference: String
    let ownerID: UUID
    let kind: ChekinanaRecordKind

    func managedURL() throws -> URL {
        let url: URL?
        switch kind {
        case .cheki:
            url = ChekiImageRefResolver.managedLocalFileURL(for: reference)
        case .shame:
            url = ChekinanaGalleryMediaStore.managedURL(for: reference, id: ownerID, kind: .shame)
        case .douga:
            url = ChekinanaGalleryMediaStore.managedURL(for: reference, id: ownerID, kind: .douga)
        }
        guard let url else { throw ChekinanaGalleryMediaStoreError.missingManagedFile }
        return url
    }
}

private enum ChekinanaOrderedPhotoExport {
    // A Photos transaction cannot be revoked once submitted. Record its success
    // before observing cancellation, then stop before submitting the next item.
    @MainActor
    static func save<Item>(
        _ items: [Item],
        authorize: @MainActor () async throws -> Void,
        write: @MainActor (Item) async throws -> Void,
        didSave: @MainActor (Int) -> Void
    ) async throws {
        guard !items.isEmpty else { return }
        try Task.checkCancellation()
        try await authorize()
        for (index, item) in items.enumerated() {
            try Task.checkCancellation()
            try await write(item)
            didSave(index + 1)
        }
    }
}

