    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @Query private var memories: [Memory]
    @Query private var memoryAttachments: [MemoryAttachment]
    @Query private var allIdols: [Idol]
    @Query private var allEvents: [Event]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let openMenu: () -> Void
    @State private var selectedType = ChekinanaGalleryContentType.cheki
    @State private var selectedIdolIDs: Set<UUID> = []
    @State private var unassignedOnly = false
    @State private var isIdolFilterPresented = false
    @State private var idolFilterDraft: ChekinanaGalleryFilterDraft?
    @State private var dateFilterDraft: ChekinanaGalleryFilterDraft?
    @State private var favoritesOnly = false
    @State private var shotFilter = ChekinanaGalleryShotFilter.all
    @State private var galleryOrder = ChekinanaGalleryOrder.dateAscending
    @State private var sortByIdol = false
    @State private var gridColumnCount = ChekinanaGalleryGridSizePolicy
        .defaultColumnCount
    @State private var dateRangeState = ChekinanaGalleryDateRangeState(
        today: ChekinanaProductDate.fixtureAwareToday
    )
    @State private var isDateFilterPresented = false
    @Query private var rankingChekiRecords: [ChekiRecord]
    @State private var previewIdolCountsMayHaveChanged = false
    @State private var gallerySortIdolIDs: [UUID] = []
    @State private var gallerySortWitnesses: [UUID: ChekinanaGallerySortWitness] = [:]
    @State private var localEditRefreshGate = ChekinanaGalleryLocalEditRefreshGate()
    @State private var previewSessionItems: [ChekinanaGalleryItem] = []
    @State private var previewSessionIDs: [UUID] = []
    @State private var previewPresentedID: UUID?
    @State private var previewHiddenIDs = Set<UUID>()
    @State private var selectedItem: ChekinanaGalleryItem?
    @State private var selectedMemory: Memory?
    @State private var isAddingMemory = false
    @State private var shamePickerItem: PhotosPickerItem?
    @State private var dougaPickerItem: PhotosPickerItem?
    @State private var isShamePickerPresented = false
    @State private var isDougaPickerPresented = false
    @State private var importDraft: ChekinanaGalleryImportDraft?
    @State private var importError: String?
    @State private var isLoadingImport = false
    @State private var importPreparationTask: Task<Void, Never>?
    @State private var importRequestGate = ChekinanaGalleryImportRequestGate()
    @State private var cleanupGate = ChekinanaGalleryImportOnceGate()
    @State private var derivedRefreshTask: Task<Void, Never>?
    @State private var lastShotDisplayPreference: Bool?
    @State private var lastDerivationIdentity: ChekinanaGalleryDerivationIdentity?
    @State private var filterStatesByType: [ChekinanaGalleryContentType: ChekinanaGalleryTypeFilterState] = [:]
    // Derived media is rebuilt only when its source or filters change. Grid
    // zoom, scrolling, image loading, and unrelated view state no longer
    // repeat full-library relationship resolution, filtering, and sorting.
    @State private var allItemsSnapshot: [ChekinanaGalleryItem] = []
    @State private var currentTypeItemsSnapshot: [ChekinanaGalleryItem] = []
    @State private var filteredItemsSnapshot: [ChekinanaGalleryItem] = []
    @State private var filteredChekisSnapshot: [MediaItem] = []
    @State private var uniqueGalleryIdolsSnapshot: [Idol] = []
    @State private var hasUnassignedGalleryItemsSnapshot = false
    @State private var earliestDatedMediaDaySnapshot: Date?
    @State private var filteredMemoriesSnapshot: [Memory] = []

    @State private var photoExportItems: [ChekinanaGalleryPhotoExportItem] = []
    @State private var isPhotoExportConfirmationPresented = false
    @State private var photoExportTask: Task<Void, Never>?
    @State private var isExportingPhotos = false
    @State private var photoExportCompleted = 0
    @State private var photoExportMessage: String?

    private var derivationFilter: ChekinanaGalleryDerivationFilter {
        ChekinanaGalleryDerivationFilter(
            selectedIdolIDs: selectedIdolIDs,
            unassignedOnly: unassignedOnly,
            favoritesOnly: favoritesOnly,
            shotFilter: shotFilter,
            galleryOrder: galleryOrder,
            sortByIdol: sortByIdol,
            dateRangeState: dateRangeState
        )
    }

    private var sourceIdentity: ChekinanaGallerySourceIdentity {
        ChekinanaGallerySourceIdentity(
            chekiIDs: chekis.map(\.id),
            shameIDs: shames.map(\.id),
            dougaIDs: dougas.map(\.id),
            memoryIDs: memories.map(\.id),
            memoryAttachmentIDs: memoryAttachments.map(\.id)
        )
    }

    private var importErrorIsPresented: Binding<Bool> {
        Binding(
            get: { importError != nil },
            set: { isPresented in
                if !isPresented { importError = nil }
            }
        )
    }

    private var columns: [GridItem] {
        Array(
            repeating: GridItem(.flexible(), spacing: 0),
            count: gridColumnCount
        )
    }

    @AppStorage(ChekinanaShotDisplayOrdering.defaultsKey) private var twoShotFirst = false

    var body: some View {
        let avatarMarkers = avatarLibraryMarkers.map { "\($0.id)|\($0.groupKey)" }.sorted().joined(separator: ";")
        let avatarSourceKey = "gallery-\(ObjectIdentifier(modelContext.container))|\(avatarMarkers)"
        let _ = twoShotFirst
        let memoryAttachmentCounts = ChekinanaMemoryAttachmentCounts.byMemory(memoryAttachments)
        let _ = languageRevision
        let _ = themeRevision
        NavigationStack {
            VStack(spacing: ChekinanaMainPageLayout.galleryHeaderToSegmentSpacing) {
                HStack(alignment: .center, spacing: 12) {
                    Text(ChekinanaProductTab.gallery.title)
                        .font(.largeTitle.bold())
                        .lineLimit(1)
                        .minimumScaleFactor(0.8)
                        .layoutPriority(1)
                        .accessibilityIdentifier("chekinana.gallery.title")
                    Spacer(minLength: 8)
                    ChekinanaGalleryGridSizeControl(
                        columnCount: $gridColumnCount
                    )
                    .accessibilityIdentifier("chekinana.gallery.grid-controls")
                }
                .frame(maxWidth: .infinity)
                .modifier(ChekinanaNaturalPageTitleHeight(
                    title: ChekinanaProductTab.gallery.title
                ))
                .padding(.horizontal, 16)
                .padding(
                    .top,
                    ChekinanaMainPageLayout.navigationTitleFirstContentTopPadding
                )
                .accessibilityIdentifier("chekinana.gallery.header")

                Picker(ChekinanaL10n.message("Media type"), selection: $selectedType) {
                    ForEach(ChekinanaGalleryContentType.allCases) { kind in
                        Text(kind.title)
                            .tag(kind)
                            .accessibilityIdentifier("chekinana.gallery.type.\(kind.rawValue)")
                    }
                }
                .pickerStyle(.segmented)
                .zIndex(1)
                .padding(.horizontal, 16)
                .accessibilityIdentifier("chekinana.gallery.type")

                ScrollView {
                    VStack(
                        spacing: ChekinanaMainPageLayout.galleryHeaderToSegmentSpacing
                    ) {
                        HStack(spacing: ChekinanaGalleryFilterBarPolicy.spacing) {
                                Button {
                                    idolFilterDraft = .init(category: selectedType, kind: .idols, value: currentFilterState)
                                    isIdolFilterPresented = true
                                } label: {
                                    ChekinanaGalleryCompactFilterLabel(
                                        title: ChekinanaProductCopy.text(
                                            "gallery.filter.idols",
                                            "Idols"
                                        ),
                                        subtitle: idolFilterSummary,
                                        systemImage: selectedIdolIDs.isEmpty
                                            ? "person.crop.circle" : "person.crop.circle.fill",
                                        isSelected: unassignedOnly || !selectedIdolIDs.isEmpty
                                    )
                                }
                                .accessibilityValue(
                                    idolFilterSummary ?? ChekinanaProductCopy.text("common.all", "All")
                                )
                                .accessibilityIdentifier("chekinana.gallery.idol-filter")

                                if selectedType != .memory {
                                    Button { favoritesOnly.toggle() } label: {
                                    ChekinanaGalleryCompactFilterLabel(
                                        title: ChekinanaProductCopy.text(
                                            "common.favorite",
                                            "Favorite"
                                        ),
                                        systemImage: favoritesOnly ? "star.fill" : "star",
                                        isSelected: favoritesOnly
                                    )
                                }
                                .accessibilityValue(
                                    favoritesOnly
                                        ? ChekinanaProductCopy.text("common.selected", "Selected")
                                        : ChekinanaProductCopy.text("common.not_selected", "Not selected")
                                )
                                    .accessibilityIdentifier("chekinana.gallery.favorite")
                                }

                                Button {
                                    dateFilterDraft = .init(category: selectedType, kind: .dates, value: currentFilterState)
                                    isDateFilterPresented = true
                                } label: {
                                    ChekinanaGalleryCompactFilterLabel(
                                        title: ChekinanaProductCopy.text(
                                            "gallery.date_filter",
                                            "Period"
                                        ),
                                        systemImage: "calendar.badge.checkmark",
                                        isSelected: dateRangeState.isActive
                                    )
                                }
                                .accessibilityIdentifier("chekinana.gallery.date-filter")

                                Button { galleryOrder = galleryOrder.next } label: {
                                    ChekinanaGalleryCompactFilterLabel(
                                        title: galleryOrder.stateTitle,
                                        systemImage: galleryOrder == .dateAscending
                                            ? "arrow.up" : "arrow.down"
                                    )
                                }
                                .accessibilityLabel(galleryOrder.stateTitle)
                                .accessibilityValue(galleryOrder.stateTitle)
                                .accessibilityHint(
                                    ChekinanaProductCopy.text(
                                        "gallery.order.cycle_hint",
                                        "Toggles between oldest and newest first."
                                    )
                                )
                                .accessibilityIdentifier("chekinana.gallery.order")

                                Button { sortByIdol.toggle() } label: {
                                    ChekinanaGalleryCompactFilterLabel(
                                        title: ChekinanaProductCopy.text(
                                            "gallery.sort.idol",
                                            "Idol order"
                                        ),
                                        systemImage: sortByIdol
                                            ? "person.crop.circle.fill" : "person.crop.circle",
                                        isSelected: sortByIdol
                                    )
                                }
                                .accessibilityValue(
                                    sortByIdol
                                        ? ChekinanaProductCopy.text("common.selected", "Selected")
                                        : ChekinanaProductCopy.text("common.not_selected", "Not selected")
                                )
                                .accessibilityIdentifier("chekinana.gallery.idol-order")

                                if selectedType != .memory {
                                    Button {
                                        shotFilter = shotFilter.next
                                    } label: {
                                        ChekinanaGalleryCompactFilterLabel(
                                            title: shotFilter.title,
                                            systemImage: shotFilter == .twoShot
                                                ? "person.2" : "person",
                                            isSelected: shotFilter != .all
                                        )
                                    }
                                    .accessibilityValue(shotFilter.title)
                                    .accessibilityHint(
                                        ChekinanaProductCopy.text(
                                            "gallery.shot_filter.cycle_hint",
                                            "Cycles through All, solo, and 2-shot."
                                        )
                                    )
                                    .accessibilityIdentifier("chekinana.gallery.shot-filter")
                                }
                            }
                            .buttonStyle(.plain)
                            .padding(.vertical, 2)
                            .accessibilityIdentifier("chekinana.gallery.filters")

                            if selectedType == .memory {
                                if filteredMemoriesSnapshot.isEmpty {
                                    ChekinanaEmptyState(
                                        title: ChekinanaProductCopy.text("gallery.memory.empty", "No Memory"),
                                        message: ChekinanaProductCopy.text("gallery.memory.empty.message", "Add a Memory to begin."),
                                        systemImage: "text.book.closed"
                                    )
                                    .frame(maxWidth: .infinity, minHeight: 420)
                                } else {
                                    LazyVStack(spacing: 10) {
                                        ForEach(filteredMemoriesSnapshot) { memory in
                                            Button { selectedMemory = memory } label: {
                                                ChekinanaIdolMemoryEventRow(
                                                    memory: memory,
                                                    idols: resolvedIdols(for: memory),
                                                    event: resolvedEvent(for: memory),
                                                    counts: memoryAttachmentCounts[memory.id] ?? .init()
                                                )
                                                .padding(14)
                                                .background(Color(uiColor: .secondarySystemGroupedBackground))
                                                .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
                                                .accessibilityIdentifier("chekinana.memory.row.\(memory.id.uuidString.lowercased())")
                                            }
                                            .buttonStyle(.plain)
                                            .contentShape(Rectangle())
                                        }
                                    }
                                }
                            } else if filteredItemsSnapshot.isEmpty {
                                ChekinanaEmptyState(
                                    title: ChekinanaL10n.message("No matching media"),
                                    message: ChekinanaL10n.message("Add media for this type."),
                                    systemImage: "line.3.horizontal.decrease.circle"
                                )
                                .frame(maxWidth: .infinity, minHeight: 420)
                                .chekinanaScreenMarker("chekinana.gallery.empty")
                            } else {
                                LazyVGrid(columns: columns, spacing: 0) {
                                    ForEach(filteredItemsSnapshot) { item in
                                        Button {
                                            previewSessionItems = filteredItemsSnapshot
                                            previewSessionIDs = filteredItemsSnapshot.map(\.modelID)
                                            previewPresentedID = item.modelID
                                            previewHiddenIDs = hiddenIdols.hiddenIDs
                                            selectedItem = item
                                        } label: {
                                            ChekinanaGalleryCard(
                                                item: item,
                                                avatarMaximumDiameter:
                                                    ChekinanaGalleryGridSizePolicy
                                                        .avatarDiameter(
                                                            forColumnCount:
                                                                gridColumnCount
                                                        )
                                            )
                                        }
                                        .buttonStyle(.plain)
                                        .contentShape(Rectangle())
                                        .accessibilityIdentifier("chekinana.gallery.card.\(item.id)")
                                    }
                                }
                            }
                        }
                        .padding(.horizontal, 16)
                        .padding(.bottom, 110)
                    }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .background(ChekinanaProductTheme.pageBackground)
            .toolbar {
                ChekinanaPageToolbar(pageID: "gallery", openMenu: openMenu)
                ToolbarItem(placement: .topBarTrailing) {
                    HStack(spacing: 0) {
                        if selectedType != .memory {
                            Button { preparePhotoExport() } label: {
                                Image(systemName: "square.and.arrow.down")
                                    .frame(width: 44, height: 44)
                            }
                            .disabled(isExportingPhotos || isLoadingImport || filteredItemsSnapshot.isEmpty)
                            .accessibilityLabel(ChekinanaProductCopy.text("gallery.photos.save", "Save to Photos"))
                            .accessibilityIdentifier("chekinana.gallery.save-to-photos")
                        }
                        Menu {
                            Button {
                                isShamePickerPresented = true
                            } label: {
                                Text(ChekinanaGalleryAddCopy.photo)
                            }
                            Button {
                                isDougaPickerPresented = true
                            } label: {
                                Text(ChekinanaGalleryAddCopy.video)
                            }
                            Button {
                                isAddingMemory = true
                            } label: {
                                Label {
                                    Text(ChekinanaProductCopy.text("gallery.add.memory", "Add Memory"))
                                } icon: {
                                    ChekinanaMemoryCategoryIcon()
                                }
                            }
                        } label: {
                            Image(systemName: "plus")
                                .frame(width: 44, height: 44)
                        }
                        .accessibilityLabel(ChekinanaL10n.message("Add Gallery media"))
                        .accessibilityIdentifier("chekinana.gallery.add")
                    }
                    .frame(width: 88, alignment: .trailing)
                }
            }
            .fullScreenCover(item: $selectedItem, onDismiss: finishMediaPreviewSession) { [previewSessionItems] item in
                switch item {
                case .cheki(let cheki):
                    ChekinanaGalleryDetailView(
                        chekis: previewSessionItems.compactMap { if case .cheki(let value) = $0 { return value }; return nil },
                        initialID: cheki.id
                    )
                case .shame(let shame):
                    ChekinanaGalleryMediaPagerView(
                        items: previewSessionItems.compactMap {
                            guard case .shame(let value) = $0 else { return nil }
                            return value
                        },
                        kind: .shame,
                        initialID: shame.id
                    )
                case .douga(let douga):
                    ChekinanaGalleryMediaPagerView(
                        items: previewSessionItems.compactMap {
                            guard case .douga(let value) = $0 else { return nil }
                            return value
                        },
                        kind: .douga,
                        initialID: douga.id
                    )
                }
            }
            .sheet(item: $selectedMemory) { memory in
                ChekinanaMemoryDetailView(memory: memory)
            }
            .sheet(isPresented: $isAddingMemory) {
                ChekinanaMemoryEditor(memory: nil)
            }
            .sheet(isPresented: $isIdolFilterPresented, onDismiss: {
                commitFilterDraft(ChekinanaGalleryFilterDraft.consume(&idolFilterDraft))
            }) {
                ChekinanaGalleryIdolFilterPicker(
                    idols: uniqueGalleryIdolsSnapshot,
                    showsUnassigned: hasUnassignedGalleryItemsSnapshot,
                    selectedIDs: Binding(
                        get: { idolFilterDraft?.value.selectedIdolIDs ?? [] },
                        set: { idolFilterDraft?.value.selectedIdolIDs = $0 }
                    ),
                    unassignedOnly: Binding(
                        get: { idolFilterDraft?.value.unassignedOnly ?? false },
                        set: { idolFilterDraft?.value.unassignedOnly = $0 }
                    ),
                    onConfirm: { idolFilterDraft?.isConfirmed = true }
                )
                .presentationDetents([.medium, .large])
            }
            .sheet(isPresented: $isDateFilterPresented, onDismiss: {
                commitFilterDraft(ChekinanaGalleryFilterDraft.consume(&dateFilterDraft))
            }) {
                ChekinanaGalleryDateFilterView(state: Binding(
                    get: { dateFilterDraft?.value.dateRangeState ?? dateRangeState },
                    set: { dateFilterDraft?.value.dateRangeState = $0 }
                ), onCancel: { dateFilterDraft = nil },
                   onConfirm: { dateFilterDraft?.isConfirmed = true })
                    .presentationDetents([.medium])
            }
            .photosPicker(
                isPresented: $isShamePickerPresented,
                selection: $shamePickerItem,
                matching: .images,
                preferredItemEncoding: .current
            )
            .photosPicker(
                isPresented: $isDougaPickerPresented,
                selection: $dougaPickerItem,
                matching: .videos,
                preferredItemEncoding: .current
            )
            .fullScreenCover(item: $importDraft) { draft in
                ChekinanaGalleryImportEditor(
                    draft: draft,
                    onSaved: {
                        cleanupImportDraft(draft)
                        importDraft = nil
                    },
                    onCancel: {
                        cleanupImportDraft(draft)
                        importDraft = nil
                    }
                )
            }
            .onChange(of: shamePickerItem) { _, item in
                guard let item else { return }
                beginShameImport(item)
            }
            .onChange(of: selectedType) { previousType, newType in
                localEditRefreshGate.resumeNormalRefresh()
                filterStatesByType[previousType] = currentFilterState
                applyFilterState(filterStatesByType[newType] ?? .init())
                refreshGalleryDerivedState(rebuildSource: false)
                selectedIdolIDs.formIntersection(Set(
                    uniqueGalleryIdolsSnapshot.map(\.id)
                ))
                refreshGalleryDerivedState(rebuildSource: false)
            }
            .onChange(of: dougaPickerItem) { _, item in
                guard let item else { return }
                beginDougaImport(item)
            }
            .onAppear {
                if !localEditRefreshGate.preservesCurrentResults {
                    refreshGalleryDerivedState(rebuildSource: true)
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: ModelContext.didSave)) { notification in
                if localEditRefreshGate.receiveSave(from: notification.object as? ModelContext) {
                    scheduleGallerySourceRefresh()
                }
            }
            .onChange(of: twoShotFirst) { _, _ in
                localEditRefreshGate.resumeNormalRefresh()
                refreshGalleryDerivedState(rebuildSource: false)
            }
            .onChange(of: hiddenIdols.hiddenIDs) { _, _ in
                localEditRefreshGate.resumeNormalRefresh()
                scheduleGallerySourceRefresh()
            }
            .onChange(of: sourceIdentity) { previous, current in
                if localEditRefreshGate.preservesCurrentResults,
                   Set(previous.chekiIDs) == Set(current.chekiIDs),
                   Set(previous.shameIDs) == Set(current.shameIDs),
                   Set(previous.dougaIDs) == Set(current.dougaIDs),
                   Set(previous.memoryIDs) == Set(current.memoryIDs),
                   Set(previous.memoryAttachmentIDs) == Set(current.memoryAttachmentIDs) { return }
                localEditRefreshGate.resumeNormalRefresh()
                scheduleGallerySourceRefresh()
            }
            .onChange(of: idolOrdering) { _, _ in
                if !localEditRefreshGate.preservesCurrentResults {
                    refreshGalleryDerivedState(rebuildSource: false)
                }
            }
            .onChange(of: derivationFilter) { _, _ in
                localEditRefreshGate.resumeNormalRefresh()
                refreshGalleryDerivedState(rebuildSource: false)
            }
            .onDisappear {
                photoExportTask?.cancel()
                importPreparationTask?.cancel()
                derivedRefreshTask?.cancel()
            }
            .disabled(isExportingPhotos)
            .overlay {
                if isExportingPhotos {
                    VStack(spacing: 12) {
                        ProgressView(value: Double(photoExportCompleted), total: Double(max(1, photoExportItems.count)))
                        Text(ChekinanaProductCopy.format("gallery.photos.progress", "Saved %1$lld of %2$lld", Int64(photoExportCompleted), Int64(photoExportItems.count)))
                        Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) { photoExportTask?.cancel() }
                    }
                    .padding(22).frame(maxWidth: 300)
                    .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 16))
                }
            }
            .alert(ChekinanaProductCopy.text("gallery.photos.save", "Save to Photos"), isPresented: $isPhotoExportConfirmationPresented) {
                Button(ChekinanaProductCopy.text("common.cancel", "Cancel"), role: .cancel) { photoExportItems = [] }
                Button(ChekinanaProductCopy.text("gallery.photos.save", "Save to Photos")) {
                    guard !isExportingPhotos else { return }
                    isExportingPhotos = true
                    photoExportTask = Task { await exportPhotos() }
                }
            } message: {
                Text(ChekinanaProductCopy.format("gallery.photos.confirm", "Save all %lld media items in the current filtered view to Photos?", Int64(photoExportItems.count)))
            }
            .alert(ChekinanaProductCopy.text("gallery.photos.save", "Save to Photos"), isPresented: Binding(
                get: { photoExportMessage != nil },
                set: { if !$0 { photoExportMessage = nil } }
            )) {
                Button(ChekinanaL10n.message("OK"), role: .cancel) {}
            } message: { Text(photoExportMessage ?? "") }
            .overlay { if isLoadingImport { ProgressView(ChekinanaL10n.message("Preparing media…"))
                .padding(22).background(.regularMaterial).clipShape(RoundedRectangle(cornerRadius: 16)) } }
            .alert(ChekinanaL10n.message("Unable to add media"), isPresented: importErrorIsPresented) {
                Button(ChekinanaL10n.message("OK"), role: .cancel) {}
            } message: {
                Text(importError ?? "")
            }
        }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("chekinana.gallery.page")
        .chekinanaScreenMarker("chekinana.gallery.page")
        .environment(\.chekinanaMediaEditHooks, ChekinanaMediaEditHooks(
            save: { try localEditRefreshGate.save($0) },
            didSave: { id in
                localEditRefreshGate.recordSuccessfulEdit(id)
                if let item = previewSessionItems.first(where: { $0.modelID == id }),
                   case .cheki = item {
                    let current = ChekinanaGallerySortWitness(item)
                    if let before = gallerySortWitnesses[id] {
                        previewIdolCountsMayHaveChanged = previewIdolCountsMayHaveChanged
                            || current.mayChangeIdolCounts(comparedTo: before)
                    } else {
                        previewIdolCountsMayHaveChanged = true
                    }
                }
            }
        ))
        .environment(\.chekinanaDisplayHiddenIdolIDs, hiddenIdols.hiddenIDs)
        .environment(\.chekinanaGalleryAvatarSourceKey, avatarSourceKey)
    }

    private func finishMediaPreviewSession() {
        let editedIDs = localEditRefreshGate.takeEditedIDs()
        let edited = previewSessionItems.filter { editedIDs.contains($0.modelID) }
        let mayChangeCounts = previewIdolCountsMayHaveChanged || edited.contains { item in
            guard case .cheki = item else { return false }
            guard let before = gallerySortWitnesses[item.modelID] else { return true }
            return ChekinanaGallerySortWitness(item).mayChangeIdolCounts(comparedTo: before)
        }
        let rejectedIDs = Set(filteredItemsSnapshot.compactMap { item -> UUID? in
            guard editedIDs.contains(item.modelID) else { return nil }
            let idolIDs = item.idolIDs
            let matches = ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: idolIDs, hiddenIDs: hiddenIdols.hiddenIDs
            ) && ChekinanaGalleryIdolFilterPolicy.includes(
                idolIDs: idolIDs, selectedIDs: selectedIdolIDs, unassignedOnly: unassignedOnly
            ) && (!favoritesOnly || item.isFavoriteCheki)
                && shotFilter.includes(item.chekiUserAppears)
                && dateRangeState.includes(item.date)
            return matches ? nil : item.modelID
        })
        if !rejectedIDs.isEmpty {
            filteredItemsSnapshot.removeAll { rejectedIDs.contains($0.modelID) }
            filteredChekisSnapshot.removeAll { rejectedIDs.contains($0.id) }
        }
        let counts = mayChangeCounts
            ? ChekinanaIdolCardChekiCount.countsByIdolID(mediaChekis: chekis,
                simpleRecords: rankingChekiRecords, hiddenIDs: hiddenIdols.hiddenIDs,
                includesSharedHiddenRecords: true)
            : idolOrdering.chekiCountsByIdolID
        let currentIdolIDs = mayChangeCounts ? sortIdolIDs(counts: counts) : gallerySortIdolIDs
        let currentIdolSet = Set(currentIdolIDs)
        let rankChanged = mayChangeCounts && gallerySortIdolIDs.filter { currentIdolSet.contains($0) } != currentIdolIDs
        let changedSort = !editedIDs.isEmpty && (rankChanged || filteredItemsSnapshot.contains {
            gallerySortWitnesses[$0.modelID] != ChekinanaGallerySortWitness($0)
        })
        if changedSort {
            filteredItemsSnapshot = ChekinanaGalleryOrdering.ordered(
                filteredItemsSnapshot, order: galleryOrder, sortByIdol: sortByIdol,
                chekiCountsByIdolID: counts
            )
            filteredChekisSnapshot = filteredItemsSnapshot.compactMap {
                guard case .cheki(let model) = $0 else { return nil }; return model
            }
        }
        gallerySortIdolIDs = currentIdolIDs
        gallerySortWitnesses = Dictionary(uniqueKeysWithValues: filteredItemsSnapshot.map {
            ($0.modelID, ChekinanaGallerySortWitness($0))
        })
        previewSessionItems = []
        previewSessionIDs = []
        previewPresentedID = nil
        previewIdolCountsMayHaveChanged = false
    }

    private func sortIdolIDs(counts: [UUID: Int]) -> [UUID] {
        ChekinanaIdolOrdering.Context(chekiCountsByIdolID: counts)
            .orderedUnique(filteredItemsSnapshot.flatMap(\.idols)).map(\.id)
    }

    @MainActor
    private func preparePhotoExport() {
        guard !isExportingPhotos, selectedType != .memory else { return }
        // Flush pending derivation so the button uses exactly the current filters
        // and their displayed ordering, including off-screen grid items.
        refreshGalleryDerivedState(rebuildSource: true)
        do {
            let items = try filteredItemsSnapshot.map { item in
                let model: MediaItem
                switch item {
                case .cheki(let value), .shame(let value), .douga(let value): model = value
                }
                guard let reference = (item.kind == .douga ? model.videoRef : model.imageRef)?.nonEmpty else {
                    throw ChekinanaGalleryMediaStoreError.missingManagedFile
                }
                let value = ChekinanaGalleryPhotoExportItem(reference: reference, ownerID: model.mediaOwnerID, kind: item.kind)
                _ = try value.managedURL()
                return value
            }
            guard !items.isEmpty else { return }
            photoExportItems = items
            photoExportCompleted = 0
            isPhotoExportConfirmationPresented = true
        } catch { photoExportMessage = error.localizedDescription }
    }

    @MainActor
    private func exportPhotos() async {
        let items = photoExportItems
        defer {
            isExportingPhotos = false
            photoExportTask = nil
            photoExportItems = []
        }
        do {
            try await ChekinanaOrderedPhotoExport.save(items,
                authorize: { try await ChekinanaProductPhotoSaver.authorizeAdding() },
                write: { item in
                    // Revalidate at use time; a stale or deleted managed file
                    // fails this item without touching its source or database.
                    try await ChekinanaProductPhotoSaver.saveAuthorizedFile(
                        at: item.managedURL(), isVideo: item.kind == .douga
                    )
                },
                didSave: { photoExportCompleted = $0 }
            )
            photoExportMessage = ChekinanaProductCopy.format("gallery.photos.complete", "Saved %lld media items to Photos.", Int64(photoExportCompleted))
        } catch is CancellationError {
            photoExportMessage = ChekinanaProductCopy.format("gallery.photos.stopped", "Stopped. Saved %1$lld of %2$lld media items.", Int64(photoExportCompleted), Int64(items.count))
        } catch {
            photoExportMessage = ChekinanaProductCopy.format("gallery.photos.failed", "Saved %1$lld of %2$lld media items. %3$@", Int64(photoExportCompleted), Int64(items.count), error.localizedDescription)
        }
    }

    @MainActor
    private func beginShameImport(_ item: PhotosPickerItem) {
        importPreparationTask?.cancel()
        dougaPickerItem = nil
        let requestID = importRequestGate.begin()
        isLoadingImport = true
        importPreparationTask = Task {
            await prepareShameImport(item, requestID: requestID)
        }
    }

    @MainActor
    private func prepareShameImport(
        _ item: PhotosPickerItem,
        requestID: UUID
    ) async {
        var stagedURL: URL?
        defer {
            if importRequestGate.finish(requestID) {
                isLoadingImport = false
                shamePickerItem = nil
                importPreparationTask = nil
            }
        }
        do {
            guard let transfer = try await item.loadTransferable(
                type: ChekinanaGalleryImageTransfer.self
            ) else {
                throw ChekinanaGalleryMediaStoreError.invalidMedia
            }
            try Task.checkCancellation()
            stagedURL = transfer.stagedURL
            try Task.checkCancellation()
            guard importRequestGate.isCurrent(requestID), let readyURL = stagedURL else {
                throw CancellationError()
            }
            replaceImportDraft(with: ChekinanaGalleryImportDraft(
                payload: .shame(
                    stagedURL: readyURL,
                    filenameExtension: transfer.filenameExtension
                )
            ))
            stagedURL = nil
        } catch is CancellationError {
            await ChekinanaGalleryMediaStore.discardStagedImport(at: stagedURL)
        } catch {
            await ChekinanaGalleryMediaStore.discardStagedImport(at: stagedURL)
            if importRequestGate.isCurrent(requestID) {
                importError = error.localizedDescription
            }
        }
    }

    @MainActor
    private func beginDougaImport(_ item: PhotosPickerItem) {
        importPreparationTask?.cancel()
        shamePickerItem = nil
        let requestID = importRequestGate.begin()
        isLoadingImport = true
        importPreparationTask = Task {
            await prepareDougaImport(item, requestID: requestID)
        }
    }

    @MainActor
    private func prepareDougaImport(
        _ item: PhotosPickerItem,
        requestID: UUID
    ) async {
        var stagedURL: URL?
        defer {
            if importRequestGate.finish(requestID) {
                isLoadingImport = false
                dougaPickerItem = nil
                importPreparationTask = nil
            }
        }
        do {
            guard let transfer = try await item.loadTransferable(
                type: ChekinanaGalleryVideoTransfer.self
            ) else {
                throw ChekinanaGalleryMediaStoreError.invalidMedia
            }
            stagedURL = transfer.stagedURL
            try Task.checkCancellation()
            guard importRequestGate.isCurrent(requestID), let readyURL = stagedURL else {
                throw CancellationError()
            }
            replaceImportDraft(with: ChekinanaGalleryImportDraft(
                payload: .douga(stagedURL: readyURL)
            ))
            stagedURL = nil
        } catch is CancellationError {
            await ChekinanaGalleryMediaStore.discardStagedImport(at: stagedURL)
        } catch {
            await ChekinanaGalleryMediaStore.discardStagedImport(at: stagedURL)
            if importRequestGate.isCurrent(requestID) {
                importError = error.localizedDescription
            }
        }
    }

    private func cleanupImportDraft(_ draft: ChekinanaGalleryImportDraft) {
        guard cleanupGate.claim(draft.id) else { return }
        let stagedURL = draft.payload.stagedURL
        Task { await ChekinanaGalleryMediaStore.discardStagedImport(at: stagedURL) }
    }

    private func replaceImportDraft(with newDraft: ChekinanaGalleryImportDraft) {
        if let importDraft {
            cleanupImportDraft(importDraft)
        }
        importDraft = newDraft
    }

    private func syncGalleryDateDefaults() {
        dateRangeState.syncDefaults(
            earliest: earliestDatedMediaDaySnapshot,
            today: ChekinanaProductDate.fixtureAwareToday
        )
    }

    private func scheduleGallerySourceRefresh() {
        derivedRefreshTask?.cancel()
        derivedRefreshTask = Task { @MainActor in
            do {
                try await Task.sleep(
                    nanoseconds: ChekinanaGalleryDerivedRefreshPolicy
                        .debounceNanoseconds
                )
            } catch {
                return
            }
            guard !Task.isCancelled else { return }
            refreshGalleryDerivedState(rebuildSource: true)
            derivedRefreshTask = nil
        }
    }

    private func refreshGalleryDerivedState(rebuildSource: Bool) {
        if rebuildSource {
            let hiddenIDs = hiddenIdols.hiddenIDs
            allItemsSnapshot = (
                chekis.filter {
                    ChekinanaFourPageVisibilityPolicy.includesRecord(
                        idolIDs: $0.idolIDs,
                        hiddenIDs: hiddenIDs
                    )
                }.map(ChekinanaGalleryItem.cheki)
                + shames.filter {
                    ChekinanaFourPageVisibilityPolicy.includesRecord(
                        idolIDs: $0.idolIDs,
                        hiddenIDs: hiddenIDs
                    )
                }.map(ChekinanaGalleryItem.shame)
                + dougas.filter {
                    ChekinanaFourPageVisibilityPolicy.includesRecord(
                        idolIDs: $0.idolIDs,
                        hiddenIDs: hiddenIDs
                    )
                }.map(ChekinanaGalleryItem.douga)
            ).filter(\.hasMedia)
            earliestDatedMediaDaySnapshot = allItemsSnapshot.compactMap {
                $0.date.flatMap(ChekinanaDateOnly.canonicalized)
            }.min()
        }
        // Establish final defaults before sorting, so the ensuing onChange
        // observes a snapshot already built for those same filter values.
        if rebuildSource || lastDerivationIdentity?.category != selectedType {
            syncGalleryDateDefaults()
        }
        let identity = ChekinanaGalleryDerivationIdentity(
            category: selectedType, filter: derivationFilter, idolOrdering: idolOrdering
        )
        guard rebuildSource || lastDerivationIdentity != identity
            || lastShotDisplayPreference != twoShotFirst else { return }
        lastShotDisplayPreference = twoShotFirst
        currentTypeItemsSnapshot = allItemsSnapshot.filter {
            $0.kind == selectedType.mediaKind
        }
        hasUnassignedGalleryItemsSnapshot = selectedType == .memory
            ? memories.contains { $0.idolIDs.isEmpty }
            : currentTypeItemsSnapshot.contains { $0.idolIDs.isEmpty }
        // An active filter remains active when editing removes its last match.
        // Picker drafts are only committed by their existing confirmation flow.
        let orderedResult = ChekinanaGalleryOrdering.ordered(
            currentTypeItemsSnapshot.filter { item in
                ChekinanaGalleryIdolFilterPolicy.includes(
                    idolIDs: item.idolIDs, selectedIDs: selectedIdolIDs,
                    unassignedOnly: unassignedOnly
                )
                    && (!favoritesOnly || item.isFavoriteCheki)
                    && shotFilter.includes(item.chekiUserAppears)
                    && dateRangeState.includes(item.date)
            },
            order: galleryOrder,
            sortByIdol: sortByIdol,
            chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
        )
        filteredItemsSnapshot = orderedResult
        gallerySortIdolIDs = sortIdolIDs(counts: idolOrdering.chekiCountsByIdolID)
        // A normal external refresh may run while local edits are deferred.
        // Keep their original scalar baseline until this preview session ends.
        let pendingIDs = localEditRefreshGate.pendingEditedIDs
        let pendingWitnesses = gallerySortWitnesses.filter { pendingIDs.contains($0.key) }
        gallerySortWitnesses = Dictionary(uniqueKeysWithValues: orderedResult.map {
            ($0.modelID, ChekinanaGallerySortWitness($0))
        })
        gallerySortWitnesses.merge(pendingWitnesses) { _, before in before }
        filteredChekisSnapshot = filteredItemsSnapshot.compactMap { item in
            guard case .cheki(let cheki) = item else { return nil }
            return cheki
        }
        var seenIDs = Set<UUID>()
        uniqueGalleryIdolsSnapshot = idolOrdering.ordered(
            (selectedType == .memory
                ? filteredMemoryIdols()
                : currentTypeItemsSnapshot.flatMap(\.idols)).filter {
                !hiddenIdols.hiddenIDs.contains($0.id) && seenIDs.insert($0.id).inserted
            }
        )
        filteredMemoriesSnapshot = orderedMemories(
            memories.filter { memory in
                ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: memory.idolIDs,
                    hiddenIDs: hiddenIdols.hiddenIDs
                )
                    && ChekinanaGalleryIdolFilterPolicy.includes(idolIDs: memory.idolIDs, selectedIDs: selectedIdolIDs, unassignedOnly: unassignedOnly)
                    && dateRangeState.includes(memory.date)
            }
        )
        synchronizeMediaPreviewSession()
        lastDerivationIdentity = ChekinanaGalleryDerivationIdentity(
            category: selectedType, filter: derivationFilter, idolOrdering: idolOrdering
        )
    }

    private func synchronizeMediaPreviewSession() {
        guard selectedItem != nil || !previewSessionIDs.isEmpty else { return }
        // Resolve from live query members, never inspect models already deleted
        // from the previous session. Only locally edited members receive the
        // deferred-filter exception; unrelated changes follow normal refresh.
        let live = (chekis.map(ChekinanaGalleryItem.cheki)
            + shames.map(ChekinanaGalleryItem.shame)
            + dougas.map(ChekinanaGalleryItem.douga))
        let byID = Dictionary(uniqueKeysWithValues: live.map { ($0.modelID, $0) })
        let hiddenPolicyChanged = previewHiddenIDs != hiddenIdols.hiddenIDs
        let retained = Set(localEditRefreshGate.pendingEditedIDs.filter { id in
            guard let item = byID[id] else { return false }
            return !hiddenPolicyChanged || ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: item.idolIDs, hiddenIDs: hiddenIdols.hiddenIDs
            )
        })
        previewSessionIDs = ChekinanaGalleryPreviewSessionPolicy.synchronizedIDs(
            previous: previewSessionIDs,
            refreshed: filteredItemsSnapshot.map(\.modelID), retainedEditedIDs: retained
        )
        previewSessionItems = previewSessionIDs.compactMap { byID[$0] }
        // Keep the same deferred members in the current Gallery result too,
        // so another save cannot drop them before their final exit-time check.
        filteredItemsSnapshot = previewSessionItems
        filteredChekisSnapshot = previewSessionItems.compactMap {
            guard case .cheki(let value) = $0 else { return nil }
            return value
        }
        if let presentedID = previewPresentedID, byID[presentedID] == nil {
            selectedItem = previewSessionItems.first
            previewPresentedID = previewSessionIDs.first
        }
        previewHiddenIDs = hiddenIdols.hiddenIDs
    }

    private func commitFilterDraft(_ draft: ChekinanaGalleryFilterDraft?) {
        guard let draft else { return }
        let base = draft.category == selectedType
            ? currentFilterState : (filterStatesByType[draft.category] ?? .init())
        let committed = draft.applying(to: base)
        filterStatesByType[draft.category] = committed
        if draft.category == selectedType {
            applyFilterState(committed)
        }
    }

    private var idolFilterSummary: String? {
        var components: [String] = []
        if !selectedIdolIDs.isEmpty {
            components.append(selectedIdolIDs.count.formatted(.number.locale(ChekinanaLanguagePreference.displayLocale())))
        }
        if unassignedOnly {
            components.append(ChekinanaProductCopy.text("common.unassigned", "Unassigned"))
        }
        return components.isEmpty ? nil : components.joined(separator: " + ")
    }

    private var currentFilterState: ChekinanaGalleryTypeFilterState {
        ChekinanaGalleryTypeFilterState(
            selectedIdolIDs: selectedIdolIDs,
            unassignedOnly: unassignedOnly,
            favoritesOnly: favoritesOnly,
            shotFilter: shotFilter,
            galleryOrder: galleryOrder,
            sortByIdol: sortByIdol,
            dateRangeState: dateRangeState
        )
    }

    private func applyFilterState(_ state: ChekinanaGalleryTypeFilterState) {
        unassignedOnly = state.unassignedOnly
        selectedIdolIDs = state.selectedIdolIDs
        favoritesOnly = state.favoritesOnly
        shotFilter = state.shotFilter
        galleryOrder = state.galleryOrder
        sortByIdol = state.sortByIdol
        dateRangeState = state.dateRangeState
    }

    private func resolvedIdols(for memory: Memory) -> [Idol] {
        idolOrdering.ordered(allIdols.filter { memory.idolIDs.contains($0.id) && !hiddenIdols.hiddenIDs.contains($0.id) })
    }

    private func resolvedEvent(for memory: Memory) -> Event? {
        guard let eventID = memory.eventID else { return nil }
        return allEvents.first { $0.id == eventID }
    }

    private func filteredMemoryIdols() -> [Idol] {
        let ids = Set(memories.flatMap(\.idolIDs))
        return allIdols.filter { ids.contains($0.id) && !hiddenIdols.hiddenIDs.contains($0.id) }
    }

    private func orderedMemories(_ values: [Memory]) -> [Memory] {
        values.sorted { lhs, rhs in
            if sortByIdol {
                let left = idolOrdering.ordered(allIdols.filter { lhs.idolIDs.contains($0.id) })
                let right = idolOrdering.ordered(allIdols.filter { rhs.idolIDs.contains($0.id) })
                if let comparison = idolOrdering.combinationPrecedes(left, right) {
                    return comparison
                }
            }
            switch (lhs.date, rhs.date) {
            case let (left?, right?) where left != right:
                return galleryOrder == .dateAscending ? left < right : left > right
            case (_?, nil): return true
            case (nil, _?): return false
            default:
                if lhs.createdAt != rhs.createdAt { return lhs.createdAt < rhs.createdAt }
                return lhs.id.uuidString < rhs.id.uuidString
            }
        }
    }

}

struct ChekinanaMemoryAttachmentCounts: Equatable {
    var images = 0
    var videos = 0

    static func byMemory(_ attachments: [MemoryAttachment]) -> [UUID: Self] {
        attachments.reduce(into: [:]) { counts, attachment in
            if attachment.kind == .image {
                counts[attachment.memoryID, default: Self()].images += 1
            } else {
                counts[attachment.memoryID, default: Self()].videos += 1
            }
        }
    }

    var summary: String? {
        let parts = [
            images > 0 ? ChekinanaProductCopy.format(
                "memory.images_count", "%lld images", Int64(images)
            ) : nil,
            videos > 0 ? ChekinanaProductCopy.format(
                "memory.videos_count", "%lld videos", Int64(videos)
            ) : nil,
        ].compactMap { $0 }
        return parts.isEmpty ? nil : parts.joined(separator: " · ")
    }
}

enum ChekinanaMemoryRowPresentation {
    struct Copy: Equatable {
        let primary: String
        let secondary: String?
    }

    static func copy(
        title: String?,
        bodyText: String?,
        dateText: String?,
        eventName: String?,
        attachmentSummary: String? = nil,
        noDate: String = ChekinanaProductCopy.text("common.no_date", "No date"),
        memoryName: String = ChekinanaProductCopy.text("gallery.memory", "Memory"),
        emptyBody: String = ChekinanaProductCopy.text("memory.body.empty", "No body text")
    ) -> Copy {
        let title = ChekinanaMemoryPolicy.normalizedTitle(title)
        let body = ChekinanaMemoryPolicy.meaningfulText(bodyText)
        let heading = [dateText?.nonEmpty ?? noDate, title ?? eventName?.nonEmpty]
            .compactMap { $0 }
            .joined(separator: " · ")
        return Copy(primary: heading, secondary: body ?? attachmentSummary?.nonEmpty ?? emptyBody)
    }
}

private struct ChekinanaMemoryRow: View {
    let memory: Memory
    let idols: [Idol]
    let event: Event?
    let attachmentCounts: ChekinanaMemoryAttachmentCounts

    private var copy: ChekinanaMemoryRowPresentation.Copy {
        ChekinanaMemoryRowPresentation.copy(
            title: memory.title,
            bodyText: memory.bodyText,
            dateText: memory.date.map(ChekinanaProductDate.displayString),
            eventName: event?.name,
            attachmentSummary: attachmentCounts.summary,
            emptyBody: ChekinanaProductCopy.text(
                "memory.body.empty",
                "No body text"
            )
        )
    }

    var body: some View {
        HStack(spacing: 12) {
            ChekinanaIdolAvatarRow(idols: idols, size: 36, showsNames: false)
                .frame(width: min(124, CGFloat(max(1, idols.count)) * 44 - 8), alignment: .leading)
                .clipped()
            VStack(alignment: .leading, spacing: 4) {
                Text(copy.primary)
                    .font(.body.weight(.semibold))
                    .foregroundStyle(.primary)
                    .lineLimit(1)
                    .multilineTextAlignment(.leading)
                if let secondary = copy.secondary {
                    Text(secondary)
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                        .multilineTextAlignment(.leading)
                }
            }
            .frame(minWidth: 0, maxWidth: .infinity, alignment: .leading)
            Image(systemName: "chevron.right")
                .foregroundStyle(.tertiary)
        }
        .padding(14)
        .background(Color(uiColor: .secondarySystemGroupedBackground))
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .accessibilityIdentifier("chekinana.memory.row.\(memory.id.uuidString.lowercased())")
    }
}

private struct ChekinanaIdolMemoryEventRow: View {
    let memory: Memory
    let idols: [Idol]
