private struct ChekinanaMemoryListView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query private var memoryAttachments: [MemoryAttachment]
    @Query private var idols: [Idol]
    @Query private var events: [Event]
    let memories: [Memory]
    var usesEventRows = false
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    @State private var selectedMemory: Memory?

    var body: some View {
        let memoryAttachmentCounts = ChekinanaMemoryAttachmentCounts.byMemory(memoryAttachments)
        NavigationStack {
            List(memories) { memory in
                Button { selectedMemory = memory } label: {
                    let visible = idolOrdering.ordered(idols.filter {
                        memory.idolIDs.contains($0.id) && !hiddenIdols.hiddenIDs.contains($0.id)
                    })
                    let event = memory.eventID.flatMap { id in events.first { $0.id == id } }
                    let counts = memoryAttachmentCounts[memory.id] ?? .init()
                    if usesEventRows {
                        ChekinanaIdolMemoryEventRow(memory: memory, idols: visible, event: event, counts: counts)
                    } else {
                        ChekinanaMemoryRow(
                            memory: memory,
                            idols: idolOrdering.ordered(idols.filter { memory.idolIDs.contains($0.id) }),
                            event: event,
                            attachmentCounts: counts
                        )
                    }
                }
                .buttonStyle(.plain)
                .listRowInsets(usesEventRows ? nil : EdgeInsets(top: 5, leading: 16, bottom: 5, trailing: 16))
                .listRowBackground(Color.clear)
            }
            .listStyle(.plain)
            .navigationTitle(ChekinanaProductCopy.text("gallery.memory", "Memory"))
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) { dismiss() }
                }
            }
        }
        .sheet(item: $selectedMemory) { ChekinanaMemoryDetailView(memory: $0) }
    }
}

enum ChekinanaMemoryMediaSelectionPolicy {
    static func isVideo(_ types: [UTType]) -> Bool {
        // Live Photos still use their image representation; actual video items
        // are transferred as files, never loaded into an unbounded Data value.
        !types.contains(where: { $0.conforms(to: .image) })
            && types.contains(where: { $0.conforms(to: .movie) || $0.conforms(to: .video) })
    }
}

private struct ChekinanaMemoryAttachmentDraft: Identifiable {
    let id: UUID
    let kind: MemoryAttachmentKind
    let existingReference: String?
    let stagedURL: URL?
    var sortOrder: Int

    init(_ attachment: MemoryAttachment) {
        id = attachment.id
        kind = attachment.kind
        existingReference = attachment.managedRef
        stagedURL = nil
        sortOrder = attachment.sortOrder
    }

    init(id: UUID = UUID(), kind: MemoryAttachmentKind, stagedURL: URL, sortOrder: Int) {
        self.id = id
        self.kind = kind
        existingReference = nil
        self.stagedURL = stagedURL
        self.sortOrder = sortOrder
    }
}

private struct ChekinanaMemoryAttachmentPreviewSelection: Identifiable {
    let id: UUID
    let kind: MemoryAttachmentKind
    let url: URL
    var cacheKey: ChekinanaMemoryPreviewKey { .init(id: id, url: url) }
}

struct ChekinanaMemoryPreviewKey: Hashable {
    let id: UUID
    let url: URL
}

enum ChekinanaMemoryPreviewBudget {
    static let baseBytes = 48 * 1_024 * 1_024
    static let fitBytes = 64 * 1_024 * 1_024

    static func baseDimension(count: Int, requested: Int) -> Int {
        guard count > 0 else { return 1 }
        let perImage = baseBytes / count
        var dimension = min(1_600, max(1, requested), max(1, Int(sqrt(Double(perImage / 4)))))
        while dimension > 1 && (dimension * 4 + 64) * dimension > perImage { dimension -= 1 }
        return dimension
    }

    static func orderedIndices(selected: Int, count: Int) -> [Int] {
        guard (0..<count).contains(selected) else { return Array(0..<count) }
        let priority = [selected, selected - 1, selected + 1].filter { (0..<count).contains($0) }
        return priority + (0..<count).filter { !priority.contains($0) }
    }
}

@MainActor
private final class ChekinanaMemoryPreviewCache: ObservableObject {
    struct Entry {
        let image: ChekinanaRenderedImage
        let requestedDimension: Int
        var bytes: Int { image.cgImage.bytesPerRow * image.cgImage.height }
    }
    @Published private(set) var base: [ChekinanaMemoryPreviewKey: Entry] = [:]
    @Published private(set) var fit: [ChekinanaMemoryPreviewKey: Entry] = [:]
    @Published private(set) var sizes: [ChekinanaMemoryPreviewKey: CGSize] = [:]
    @Published private(set) var unavailable: Set<ChekinanaMemoryPreviewKey> = []
    private var baseGeneration = UUID()
    private var baseImageCount = 0
    private var viewerGeneration = UUID()

    func image(for selection: ChekinanaMemoryAttachmentPreviewSelection) -> ChekinanaRenderedImage? {
        fit[selection.cacheKey]?.image ?? base[selection.cacheKey]?.image
    }

    func prepareBase(_ items: [ChekinanaMemoryAttachmentPreviewSelection], requested: Int,
                     selectedID: UUID? = nil) async {
        guard !Task.isCancelled else { return }
        let token = UUID(); baseGeneration = token
        let images = items.filter { $0.kind == .image }
        let valid = Set(images.map(\.cacheKey))
        base = base.filter { valid.contains($0.key) }
        unavailable.formIntersection(valid)
        let dimension = ChekinanaMemoryPreviewBudget.baseDimension(count: images.count, requested: requested)
        let mustShrink = images.count > baseImageCount
        baseImageCount = images.count
        let selected = images.firstIndex { $0.id == selectedID } ?? 0
        var order = ChekinanaMemoryPreviewBudget.orderedIndices(selected: selected, count: images.count)
        if mustShrink { order = order.filter { base[images[$0].cacheKey] != nil } + order.filter { base[images[$0].cacheKey] == nil } }
        for index in order {
            guard !Task.isCancelled, baseGeneration == token else { return }
            let item = images[index], key = item.cacheKey
            if let current = base[key], current.requestedDimension == dimension
                || (!mustShrink && current.requestedDimension > dimension) { continue }
            let loaded = await ChekinanaMemoryOriginalImageRenderer.shared.preview(at: item.url, maximumDimension: dimension)
            guard !Task.isCancelled, baseGeneration == token else { return }
            guard let loaded else { unavailable.insert(key); continue }
            let entry = Entry(image: loaded, requestedDimension: dimension)
            let otherBytes = base.filter { $0.key != key }.values.reduce(0) { $0 + $1.bytes }
            guard otherBytes + entry.bytes <= ChekinanaMemoryPreviewBudget.baseBytes else { continue }
            base[key] = entry
            unavailable.remove(key)
        }
    }

    func prepareViewer(_ items: [ChekinanaMemoryAttachmentPreviewSelection], selectedID: UUID?) async {
        guard !Task.isCancelled else { return }
        let token = UUID(); viewerGeneration = token
        let selected = items.firstIndex { $0.id == selectedID } ?? 0
        for index in [selected, selected - 1, selected + 1] where items.indices.contains(index) && items[index].kind == .image {
            let key = items[index].cacheKey
            if sizes[key] == nil {
                let size = await ChekinanaMemoryOriginalImageRenderer.shared.imageSize(at: items[index].url)
                guard !Task.isCancelled, viewerGeneration == token else { return }
                if let size { sizes[key] = size }
            }
        }
        // Base images survive paging and the viewer cover. Populate every base
        // before spending remaining memory on higher-quality fit previews.
        if !items.filter({ $0.kind == .image }).allSatisfy({ base[$0.cacheKey] != nil || unavailable.contains($0.cacheKey) }) {
            await prepareBase(items, requested: 1_600, selectedID: selectedID)
        }
        guard !Task.isCancelled, viewerGeneration == token else { return }
        let order = ChekinanaMemoryPreviewBudget.orderedIndices(selected: selected, count: items.count)
        let protected = Set([selected, selected - 1, selected + 1]
            .filter { items.indices.contains($0) }.map { items[$0].cacheKey })
        let valid = Set(items.map(\.cacheKey))
        fit = fit.filter { valid.contains($0.key) }
        sizes = sizes.filter { valid.contains($0.key) }
        for index in order where items[index].kind == .image {
            guard !Task.isCancelled, viewerGeneration == token else { return }
            let item = items[index], key = item.cacheKey
            if sizes[key] == nil {
                let size = await ChekinanaMemoryOriginalImageRenderer.shared.imageSize(at: item.url)
                guard !Task.isCancelled, viewerGeneration == token else { return }
                if let size { sizes[key] = size } else { unavailable.insert(key); continue }
            }
            if fit[key] != nil { continue }
            let reservation = 2_048 * 2_048 * 4
            while fit.values.reduce(0, { $0 + $1.bytes }) + reservation > ChekinanaMemoryPreviewBudget.fitBytes {
                guard protected.contains(key), let victim = items.enumerated()
                    .filter({ fit[$0.element.cacheKey] != nil && !protected.contains($0.element.cacheKey) })
                    .max(by: { abs($0.offset - selected) < abs($1.offset - selected) }) else { break }
                fit[victim.element.cacheKey] = nil
            }
            guard fit.values.reduce(0, { $0 + $1.bytes }) + reservation <= ChekinanaMemoryPreviewBudget.fitBytes else { continue }
            let loaded = await ChekinanaMemoryOriginalImageRenderer.shared.preview(at: item.url, maximumDimension: 2_048)
            guard !Task.isCancelled, viewerGeneration == token else { return }
            if let loaded {
                let entry = Entry(image: loaded, requestedDimension: 2_048)
                if fit.values.reduce(0, { $0 + $1.bytes }) + entry.bytes <= ChekinanaMemoryPreviewBudget.fitBytes {
                    fit[key] = entry
                }
            }
        }
    }

    func finishViewer() {
        viewerGeneration = UUID()
        fit = [:]
        sizes = [:]
    }

    func close() {
        baseGeneration = UUID()
        finishViewer()
        base = [:]
        baseImageCount = 0
        unavailable = []
    }
}

struct ChekinanaMemoryOriginalTileRequest: Equatable, Sendable {
    let rect: CGRect // Oriented source pixels, Core Image bottom-left origin.
    let divisor: CGFloat
}

struct ChekinanaMemoryOriginalTile: Identifiable, Sendable {
    let id: Int
    let request: ChekinanaMemoryOriginalTileRequest
    let image: ChekinanaRenderedImage
}

struct ChekinanaMemoryOriginalTileLoadKey: Equatable {
    let url: URL
    let requests: [ChekinanaMemoryOriginalTileRequest]
}

enum ChekinanaMemoryOriginalTileReuse {
    static func retained(
        _ tiles: [ChekinanaMemoryOriginalTile],
        for requests: [ChekinanaMemoryOriginalTileRequest]
    ) -> [ChekinanaMemoryOriginalTile] {
        guard requests.count <= ChekinanaMemoryOriginalTilePolicy.maximumTiles else { return [] }
        return requests.enumerated().compactMap { index, request in
            guard let tile = tiles.first(where: { $0.request == request }) else { return nil }
            return .init(id: index, request: request, image: tile.image)
        }
    }
}

enum ChekinanaMemoryOriginalTilePolicy {
    static let tilePixels: CGFloat = 512
    static let maximumTiles = 64 // At most 64 MiB of RGBA output per batch.

    static func maximumScale(imageSize: CGSize, viewport: CGSize, displayScale: CGFloat) -> CGFloat {
        let fit = ChekinanaZoomPanGeometry.aspectFitSize(imageSize: imageSize, viewportSize: viewport)
        guard fit.width > 0, displayScale.isFinite, displayScale > 0 else { return 4 }
        return max(4, imageSize.width / (fit.width * displayScale))
    }

    static func requests(imageSize: CGSize, viewport: CGSize,
                         transform: ChekinanaZoomViewportTransform,
                         displayScale: CGFloat) -> [ChekinanaMemoryOriginalTileRequest] {
        let fit = ChekinanaZoomPanGeometry.aspectFitSize(imageSize: imageSize, viewportSize: viewport)
        guard fit.width > 0, imageSize.width.isFinite, imageSize.height.isFinite,
              displayScale.isFinite, displayScale > 0, transform.scale.isFinite, transform.scale > 0,
              transform.offset.width.isFinite, transform.offset.height.isFinite else { return [] }
        let pointsPerPixel = fit.width / imageSize.width * transform.scale
        let pixelsPerSourcePixel = pointsPerPixel * displayScale
        guard pointsPerPixel > 0, pixelsPerSourcePixel > 0 else { return [] }
        // SwiftUI top-left viewport -> oriented source bottom-left coordinates.
        let visible = CGRect(
            x: imageSize.width / 2 - (viewport.width / 2 + transform.offset.width) / pointsPerPixel,
            y: imageSize.height / 2 - (viewport.height / 2 - transform.offset.height) / pointsPerPixel,
            width: viewport.width / pointsPerPixel,
            height: viewport.height / pointsPerPixel
        ).intersection(CGRect(origin: .zero, size: imageSize))
        guard !visible.isNull, !visible.isEmpty else { return [] }
        var divisor: CGFloat = 1
        while divisor * 2 <= 1 / pixelsPerSourcePixel { divisor *= 2 }
        while true {
            let span = tilePixels * divisor
            let minX = floor(visible.minX / span), maxX = ceil(visible.maxX / span)
            let minY = floor(visible.minY / span), maxY = ceil(visible.maxY / span)
            guard [minX, maxX, minY, maxY, span].allSatisfy(\.isFinite) else { return [] }
            if (maxX - minX) * (maxY - minY) > CGFloat(maximumTiles) {
                divisor *= 2
                continue
            }
            var result: [ChekinanaMemoryOriginalTileRequest] = []
            for y in Int(minY)..<Int(maxY) {
                for x in Int(minX)..<Int(maxX) {
                    let rect = CGRect(x: CGFloat(x) * span, y: CGFloat(y) * span, width: span, height: span)
                        .intersection(CGRect(origin: .zero, size: imageSize))
                    result.append(.init(rect: rect, divisor: divisor))
                }
            }
            return result
        }
    }
}

/// The public decoder does not promise a bounded internal JPEG/HEIC working
/// set. Only our rendered tile outputs are bounded; no whole-source CGImage or
/// Data is retained. All source/CI work is serialized through this actor.
actor ChekinanaMemoryOriginalImageRenderer {
    static let shared = ChekinanaMemoryOriginalImageRenderer()
    private let context = CIContext(options: [.cacheIntermediates: false])

    private func source(_ url: URL) -> CIImage? {
        guard let image = CIImage(contentsOf: url, options: [.applyOrientationProperty: true]),
              !image.extent.isInfinite, !image.extent.isEmpty,
              image.extent.width.isFinite, image.extent.height.isFinite else { return nil }
        return image.transformed(by: CGAffineTransform(translationX: -image.extent.minX, y: -image.extent.minY))
    }

    func preview(at url: URL, maximumDimension: Int) -> ChekinanaRenderedImage? {
        guard !Task.isCancelled, maximumDimension > 0 else { return nil }
        return autoreleasepool {
            guard let source = CGImageSourceCreateWithURL(url as CFURL, [kCGImageSourceShouldCache: false] as CFDictionary),
                  let thumbnail = CGImageSourceCreateThumbnailAtIndex(source, 0, [
                    kCGImageSourceCreateThumbnailFromImageAlways: true,
                    kCGImageSourceCreateThumbnailWithTransform: true,
                    kCGImageSourceThumbnailMaxPixelSize: maximumDimension,
                    kCGImageSourceShouldCacheImmediately: true
                  ] as CFDictionary), !Task.isCancelled,
                  let colorSpace = CGColorSpace(name: CGColorSpace.sRGB),
                  let bitmap = CGContext(data: nil, width: thumbnail.width, height: thumbnail.height,
                    bitsPerComponent: 8, bytesPerRow: thumbnail.width * 4, space: colorSpace,
                    bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
            bitmap.draw(thumbnail, in: CGRect(x: 0, y: 0, width: thumbnail.width, height: thumbnail.height))
            guard !Task.isCancelled, let image = bitmap.makeImage() else { return nil }
            return .init(cgImage: image)
        }
    }

    func imageSize(at url: URL) -> CGSize? {
        guard !Task.isCancelled else { return nil }
        return autoreleasepool { source(url)?.extent.size }
    }

    func render(
        at url: URL, requests: [ChekinanaMemoryOriginalTileRequest],
        reusing retained: [ChekinanaMemoryOriginalTile] = []
    ) -> [ChekinanaMemoryOriginalTile] {
        guard !Task.isCancelled, requests.count <= ChekinanaMemoryOriginalTilePolicy.maximumTiles else { return [] }
        defer { context.clearCaches() }
        let reusable = ChekinanaMemoryOriginalTileReuse.retained(retained, for: requests)
        if reusable.count == requests.count { return reusable }
        guard let source = source(url) else { return [] }
        var result: [ChekinanaMemoryOriginalTile] = []
        for (index, request) in requests.enumerated() {
            guard !Task.isCancelled else { return [] }
            if let tile = reusable.first(where: { $0.id == index }) {
                result.append(tile)
                continue
            }
            let tile: ChekinanaMemoryOriginalTile? = autoreleasepool {
                guard request.divisor.isFinite, request.divisor >= 1,
                      source.extent.contains(request.rect), !request.rect.isEmpty else { return nil }
                let scaled = source.cropped(to: request.rect).transformed(by:
                    CGAffineTransform(scaleX: 1 / request.divisor, y: 1 / request.divisor))
                let bounds = scaled.extent.integral
                guard bounds.width <= ChekinanaMemoryOriginalTilePolicy.tilePixels,
                      bounds.height <= ChekinanaMemoryOriginalTilePolicy.tilePixels,
                      let colorSpace = CGColorSpace(name: CGColorSpace.sRGB),
                      let image = context.createCGImage(scaled, from: bounds, format: .RGBA8, colorSpace: colorSpace)
                else { return nil }
                return .init(id: index, request: request, image: .init(cgImage: image))
            }
            if let tile { result.append(tile) }
        }
        return Task.isCancelled ? [] : result
    }
}

private struct ChekinanaMemoryOriginalImage: View {
    let selection: ChekinanaMemoryAttachmentPreviewSelection
    let isActive: Bool
    @ObservedObject var cache: ChekinanaMemoryPreviewCache
    let pageInteraction: ChekinanaMediaPagerPageInteraction
    @Environment(\.displayScale) private var displayScale
    @State private var requests: [ChekinanaMemoryOriginalTileRequest] = []
    @State private var tiles: [ChekinanaMemoryOriginalTile] = []
    @State private var tilesURL: URL?
    @State private var tileUnavailable = false
    private var imageSize: CGSize {
        if let size = cache.sizes[selection.cacheKey] { return size }
        guard let image = cache.image(for: selection) else { return .zero }
        return CGSize(width: image.cgImage.width, height: image.cgImage.height)
    }
    private var unavailable: Bool { cache.unavailable.contains(selection.cacheKey) || tileUnavailable }

    var body: some View {
        GeometryReader { geometry in
            if unavailable {
                ChekinanaZoomableImageViewport(
                    imageSize: geometry.size, resetID: selection.id, isActive: isActive,
                    pageTranslation: pageInteraction.translation,
                    onHorizontalDragChanged: pageInteraction.dragChanged,
                    onHorizontalDragEnded: pageInteraction.dragEnded
                ) {
                    ContentUnavailableView(
                        ChekinanaProductCopy.text("memory.attachment.unavailable", "Attachment unavailable"),
                        systemImage: "photo.badge.exclamationmark"
                    ).foregroundStyle(.white)
                }
            } else if imageSize.width > 0 {
                ChekinanaZoomableImageViewport(
                    imageSize: imageSize,
                    resetID: selection.id,
                    isActive: isActive,
                    pageTranslation: pageInteraction.translation,
                    maximumScale: ChekinanaMemoryOriginalTilePolicy.maximumScale(
                        imageSize: imageSize, viewport: geometry.size, displayScale: displayScale),
                    onViewportChanged: { viewport, transform in
                        guard isActive, cache.sizes[selection.cacheKey] != nil else { return }
                        requests = ChekinanaMemoryOriginalTilePolicy.requests(
                            imageSize: imageSize, viewport: viewport, transform: transform, displayScale: displayScale)
                    },
                    onHorizontalDragChanged: pageInteraction.dragChanged,
                    onHorizontalDragEnded: pageInteraction.dragEnded
                ) {
                    GeometryReader { fitted in
                        ZStack(alignment: .topLeading) {
                            if let preview = cache.image(for: selection) {
                                Image(decorative: preview.cgImage, scale: 1)
                                    .resizable().scaledToFit()
                                    .frame(width: fitted.size.width, height: fitted.size.height)
                            }
                            ForEach(tiles) { tile in
                                Image(decorative: tile.image.cgImage, scale: 1)
                                    .resizable().interpolation(.high)
                                    .frame(width: tile.request.rect.width / imageSize.width * fitted.size.width,
                                           height: tile.request.rect.height / imageSize.height * fitted.size.height)
                                    .offset(x: tile.request.rect.minX / imageSize.width * fitted.size.width,
                                            y: (imageSize.height - tile.request.rect.maxY) / imageSize.height * fitted.size.height)
                            }
                        }
                    }
                }
            } else {
                // A cold, not-yet-preloaded page remains pageable. This is a
                // placeholder, never an assertion that original pixels loaded.
                ChekinanaZoomableImageViewport(
                    imageSize: geometry.size, resetID: selection.id, isActive: isActive,
                    pageTranslation: pageInteraction.translation,
                    onHorizontalDragChanged: pageInteraction.dragChanged,
                    onHorizontalDragEnded: pageInteraction.dragEnded
                ) { Image(systemName: "photo").font(.largeTitle).foregroundStyle(.secondary) }
            }
        }
        .onChange(of: isActive) { _, active in
            if !active { requests = []; tiles = []; tilesURL = nil; tileUnavailable = false }
        }
        .id("\(imageSize.width):\(imageSize.height):\(isActive)")
        .task(id: ChekinanaMemoryOriginalTileLoadKey(url: selection.url, requests: requests)) {
            guard isActive, !requests.isEmpty else { return }
            let expected = requests
            // Coalesce gesture frames without starting a queue of obsolete decodes.
            try? await Task.sleep(for: .milliseconds(50))
            guard !Task.isCancelled else { return }
            let retained = tilesURL == selection.url
                ? ChekinanaMemoryOriginalTileReuse.retained(tiles, for: expected) : []
            // Release tiles outside the new viewport before allocating replacements.
            // The retained and newly rendered outputs together still fit one batch.
            tiles = retained
            tilesURL = selection.url
            let loaded = await ChekinanaMemoryOriginalImageRenderer.shared.render(
                at: selection.url, requests: expected, reusing: retained
            )
            guard !Task.isCancelled, isActive, requests == expected else { return }
            guard loaded.count == expected.count else {
                tiles = []
                tileUnavailable = true
                return
            }
            tiles = loaded
        }
        .onDisappear { requests = []; tiles = []; tilesURL = nil }
    }
}

private struct ChekinanaMemoryAttachmentPreview: View {
    @Environment(\.dismiss) private var dismiss
    let items: [ChekinanaMemoryAttachmentPreviewSelection]
    @State private var selectedID: UUID?
    @StateObject private var cache: ChekinanaMemoryPreviewCache
    private let ownsCache: Bool

    init(selection: ChekinanaMemoryAttachmentPreviewSelection,
         items: [ChekinanaMemoryAttachmentPreviewSelection],
         cache: ChekinanaMemoryPreviewCache? = nil) {
        self.items = items
        ownsCache = cache == nil
        _cache = StateObject(wrappedValue: cache ?? ChekinanaMemoryPreviewCache())
        _selectedID = State(initialValue: ChekinanaMediaPagerPolicy.initialID(
            requested: selection.id, available: items.map(\.id)
        ))
    }

    var body: some View {
        ZStack(alignment: .topTrailing) {
            (items.first(where: { $0.id == selectedID })?.kind == .video ? Color.white : Color.black)
                .ignoresSafeArea()
            ChekinanaFullScreenMediaPager(
                items: items,
                selectedID: $selectedID,
                usesEmbeddedPagingGesture: true,
                showsPageIndicator: items.count > 1
            ) { selection, _, interaction in
                ChekinanaMemoryAttachmentPreviewPage(
                    selection: selection,
                    isActive: selectedID == selection.id,
                    cache: cache,
                    pageInteraction: interaction
                )
            }
            Button { dismiss() } label: {
                Image(systemName: "xmark").font(.title2.weight(.bold))
                    .foregroundStyle(.white).frame(width: 48, height: 48)
                    .background(.black.opacity(0.55), in: Circle())
            }
            .padding()
        }
        .task(id: selectedID) { await cache.prepareViewer(items, selectedID: selectedID) }
        .onDisappear {
            if ownsCache { cache.close() } else { cache.finishViewer() }
        }
    }
}

private struct ChekinanaMemoryAttachmentPreviewPage: View {
    let selection: ChekinanaMemoryAttachmentPreviewSelection
    let isActive: Bool
    @ObservedObject var cache: ChekinanaMemoryPreviewCache
    let pageInteraction: ChekinanaMediaPagerPageInteraction
    @GestureState private var videoDragIsActive = false
    @State private var videoDragLifecycle = ChekinanaMediaDragLifecycle()
    @State private var player: AVPlayer?
    @State private var videoUnavailable = false

    var body: some View {
        ZStack(alignment: .topTrailing) {
            (selection.kind == .video ? Color.white : Color.black).ignoresSafeArea()
            Group {
                if selection.kind == .image {
                    ChekinanaMemoryOriginalImage(selection: selection, isActive: isActive, cache: cache, pageInteraction: pageInteraction)
                } else if selection.kind == .video, let player {
                    ChekinanaPlaybackVideoPlayer(player: player)
                        .simultaneousGesture(videoPagingGesture)
                } else if videoUnavailable {
                    ContentUnavailableView(
                        ChekinanaProductCopy.text(
                            "memory.attachment.unavailable",
                            "Attachment unavailable"
                        ),
                        systemImage: "video.slash"
                    )
                    .foregroundStyle(.black)
                    .simultaneousGesture(videoPagingGesture)
                } else {
                    ProgressView().tint(selection.kind == .video ? .black : .white)
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                        .contentShape(Rectangle())
                        .simultaneousGesture(videoPagingGesture)
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .task(id: isActive) {
            switch selection.kind {
            case .image: break
            case .video:
                if isActive { await prepareVideoPlayback() }
                else { releaseVideoPlayback() }
            }
        }
        .onChange(of: videoDragIsActive) { _, active in
            if !active, videoDragLifecycle.cancel() { pageInteraction.dragChanged(0) }
        }
        .onDisappear {
            if videoDragLifecycle.cancel() { pageInteraction.dragChanged(0) }
            releaseVideoPlayback()
        }
    }

    private var videoPagingGesture: some Gesture {
        DragGesture(minimumDistance: 8, coordinateSpace: .global)
            .updating($videoDragIsActive) { _, state, _ in state = true }
            .onChanged { value in
                guard isActive else { return }
                videoDragLifecycle.changed()
                pageInteraction.dragChanged(abs(value.translation.width) > abs(value.translation.height)
                    ? value.translation.width : 0)
            }
            .onEnded { value in
                videoDragLifecycle.finish()
                guard isActive else { return }
                let horizontal = abs(value.translation.width) > abs(value.translation.height)
                _ = pageInteraction.dragEnded(.init(
                    translation: horizontal ? value.translation.width : 0,
                    predictedEndTranslation: horizontal ? value.predictedEndTranslation.width : 0
                ))
            }
    }

    private func releaseVideoPlayback() {
        player?.pause()
        player?.replaceCurrentItem(with: nil)
        player = nil
    }

    @MainActor
    private func prepareVideoPlayback() async {
        videoUnavailable = false
        guard ChekiImageRefResolver.isRegularReadableFile(selection.url) else {
            videoUnavailable = true
            return
        }
        let asset = AVURLAsset(url: selection.url)
        do {
            guard try await asset.load(.isPlayable), !Task.isCancelled, isActive else {
                videoUnavailable = true
                return
            }
            ChekinanaMediaPlaybackAudioSession.activate(mode: .moviePlayback)
            let value = AVPlayer(playerItem: AVPlayerItem(asset: asset))
            player = value
            value.play()
        } catch {
            guard !Task.isCancelled, isActive else { return }
            videoUnavailable = true
        }
    }
}

private struct ChekinanaMemoryAttachmentThumbnail: View {
    let selection: ChekinanaMemoryAttachmentPreviewSelection
    var displaysFullSize = false
    var cachedImage: ChekinanaRenderedImage? = nil
    var usesPageCache = false
    var cachedUnavailable = false
    var onImageLoaded: ((ChekinanaRenderedImage?) -> Void)? = nil
    @Environment(\.displayScale) private var displayScale
    @State private var image: ChekinanaRenderedImage?
    @State private var availableWidth: CGFloat = 0

    private var maximumPixelDimension: Int {
        guard displaysFullSize else { return 256 }
        guard availableWidth.isFinite, displayScale.isFinite, availableWidth > 0 else { return 0 }
        return Int(min(1_600, max(1, (availableWidth * displayScale).rounded(.up))))
    }

    var body: some View {
        Group {
            if let image = cachedImage ?? image {
                if displaysFullSize {
                    Image(decorative: image.cgImage, scale: 1)
                        .resizable()
                        .scaledToFit()
                        .frame(maxWidth: .infinity)
                } else {
                    Image(decorative: image.cgImage, scale: 1)
                        .resizable()
                        .scaledToFill()
                        .frame(width: 82, height: 82)
                        .clipped()
                }
            } else {
                Color(uiColor: .tertiarySystemGroupedBackground)
                    .frame(height: displaysFullSize ? 150 : 82)
                    .overlay {
                        if cachedUnavailable { Image(systemName: "photo.badge.exclamationmark") }
                        else { ProgressView().controlSize(.small) }
                    }
            }
        }
        .background {
            GeometryReader { geometry in
                Color.clear
                    .onAppear { availableWidth = geometry.size.width }
                    .onChange(of: geometry.size.width) { _, width in availableWidth = width }
            }
        }
        .background(Color(uiColor: .tertiarySystemGroupedBackground))
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        .overlay {
            if selection.kind == .video {
                Image(systemName: "play.fill")
                    .font(.title2.weight(.semibold))
                    .foregroundStyle(.white)
                    .shadow(color: .black.opacity(0.55), radius: 3)
            }
        }
        .onChange(of: image) { _, loaded in onImageLoaded?(loaded) }
        .task(id: maximumPixelDimension) {
            guard !usesPageCache, maximumPixelDimension > 0 else { return }
            image = nil
            switch selection.kind {
            case .image:
                let loaded = await ChekinanaImageWorker.thumbnailImage(
                    fromFileAt: selection.url,
                    maxDimension: maximumPixelDimension
                )
                guard !Task.isCancelled else { return }
                image = loaded
            case .video:
                if let thumbnailReference = ChekinanaGalleryMediaStore
                    .thumbnailReference(id: selection.id) {
                    let loaded = await ChekinanaThumbnailCache.shared.thumbnailImage(
                        forManagedImageRef: thumbnailReference,
                        key: "memory-video-\(selection.id.uuidString.lowercased())",
                        maxDimension: maximumPixelDimension
                    )
                    guard !Task.isCancelled else { return }
                    image = loaded
                }
                if image == nil, !Task.isCancelled {
                    let loaded = await ChekinanaGalleryMediaStore.videoThumbnailImage(
                        at: selection.url,
                        maxDimension: maximumPixelDimension
                    )
                    guard !Task.isCancelled else { return }
                    image = loaded
                }
            }
        }
    }
}

private struct ChekinanaMemoryDetailView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Environment(\.chekinanaDisplayHiddenIdolIDs) private var hiddenDisplayIDs
    @Query private var idols: [Idol]
    @Query private var events: [Event]
    @Query private var persistedAttachments: [MemoryAttachment]
    let memory: Memory
    @State private var isSelectingAttachments = false
    @State private var selectedAttachmentIDs: Set<UUID> = []
    @State private var isExportingPhotos = false
    @State private var photoExportTask: Task<Void, Never>?
    @State private var photoExportCompleted = 0
    @State private var photoExportTotal = 0
    @State private var photoExportMessage: String?
    @State private var isEditing = false
    @StateObject private var imageCache = ChekinanaMemoryPreviewCache()
    @Environment(\.displayScale) private var displayScale
    @State private var viewportWidth: CGFloat = 0
    @State private var previewSelection: ChekinanaMemoryAttachmentPreviewSelection?

    private var linkedIdols: [Idol] {
        idolOrdering.ordered(
            idols.filter { memory.idolIDs.contains($0.id) && !hiddenDisplayIDs.contains($0.id) }
        )
    }

    private var linkedEvent: Event? {
        guard let eventID = memory.eventID else { return nil }
        return events.first { $0.id == eventID }
    }

    private var attachments: [MemoryAttachment] {
        persistedAttachments
            .filter { $0.memoryID == memory.id }
            .sorted {
                if $0.kind != $1.kind { return $0.kind == .image }
                return $0.sortOrder == $1.sortOrder
                    ? $0.id.uuidString < $1.id.uuidString
                    : $0.sortOrder < $1.sortOrder
            }
    }

    var body: some View {
        let attachments = self.attachments
        let attachmentIDs = attachments.map(\.id)
        let preloadKey = detailPreloadKey(attachments)
        return NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 14) {
                    if !linkedIdols.isEmpty {
                        ChekinanaIdolAvatarRow(
                            idols: linkedIdols,
                            size: 36,
                            showsNames: false
                        )
                    }

                    if memory.date != nil || linkedEvent != nil {
                        HStack(spacing: 8) {
                            if let date = memory.date {
                                Text(ChekinanaProductDate.displayString(date))
                            }
                            if memory.date != nil, linkedEvent != nil {
                                Text("·")
                            }
                            if let linkedEvent {
                                Text(linkedEvent.name)
                            }
                        }
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                    }

                    if let bodyText = ChekinanaMemoryPolicy.meaningfulText(memory.bodyText) {
                        ChekinanaSectionCard {
                            Text(bodyText)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .multilineTextAlignment(.leading)
                        }
                    }

                    if !attachments.isEmpty {
                        VStack(alignment: .leading, spacing: 10) {
                            Text(ChekinanaProductCopy.text(
                                "memory.attachments",
                                "Attachments"
                            ))
                            .font(.headline)

                            LazyVStack(spacing: 10) {
                                ForEach(attachments) { attachment in
                                    memoryAttachmentButton(attachment)
                                }
                            }
                        }
                    }
                }
                .padding(16)
                .padding(.bottom, 24)
            }
            .background {
                GeometryReader { geometry in
                    Color.clear.onAppear { viewportWidth = geometry.size.width }
                        .onChange(of: geometry.size.width) { _, width in viewportWidth = width }
                }
            }
            .background(ChekinanaProductTheme.pageBackground)
            .navigationTitle(
                memory.title?.nonEmpty
                    ?? ChekinanaProductCopy.text("gallery.memory", "Memory")
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button {
                        if isSelectingAttachments { beginPhotoExport() }
                        else { selectedAttachmentIDs = []; isSelectingAttachments = true }
                    } label: {
                        Image(systemName: "square.and.arrow.down")
                            .frame(width: 44, height: 44)
                    }
                    .disabled(isExportingPhotos || attachments.isEmpty
                        || (isSelectingAttachments && selectedAttachmentIDs.isEmpty))
                    .accessibilityLabel(ChekinanaProductCopy.text("gallery.photos.save", "Save to Photos"))
                    .accessibilityIdentifier("chekinana.memory.save-to-photos")
                }
                ToolbarItem(placement: .cancellationAction) {
                    Button(isSelectingAttachments
                        ? ChekinanaProductCopy.text("common.cancel", "Cancel")
                        : ChekinanaProductCopy.text("common.done", "Done")) {
                        if isExportingPhotos {
                            photoExportTask?.cancel()
                        } else if isSelectingAttachments {
                            isSelectingAttachments = false
                            selectedAttachmentIDs = []
                        } else {
                            imageCache.close()
                            dismiss()
                        }
                    }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.edit", "Edit")) {
                        isEditing = true
                    }
                    .disabled(isSelectingAttachments || isExportingPhotos)
                    .accessibilityIdentifier("chekinana.memory.detail.edit")
                }
            }
        }
        .task(id: preloadKey) {
            guard viewportWidth > 0 else { return }
            await imageCache.prepareBase(attachments.compactMap { preview(for: $0) },
                requested: Int(min(1_600, max(1, (viewportWidth - 32) * displayScale))))
        }
        .onDisappear {
            photoExportTask?.cancel()
            if previewSelection == nil, !isEditing { imageCache.close() }
        }
        .interactiveDismissDisabled(isExportingPhotos)
        .onChange(of: attachmentIDs) { _, ids in
            selectedAttachmentIDs.formIntersection(Set(ids))
        }
        .overlay {
            if isExportingPhotos {
                VStack(spacing: 12) {
                    ProgressView(value: Double(photoExportCompleted), total: Double(max(1, photoExportTotal)))
                    Text(ChekinanaProductCopy.format("gallery.photos.progress", "Saved %1$lld of %2$lld",
                        Int64(photoExportCompleted), Int64(photoExportTotal)))
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) { photoExportTask?.cancel() }
                }
                .padding(24)
                .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 16))
                .padding(24)
            }
        }
        .alert(ChekinanaProductCopy.text("gallery.photos.save", "Save to Photos"), isPresented: Binding(
            get: { photoExportMessage != nil },
            set: { if !$0 { photoExportMessage = nil } }
        )) { Button(ChekinanaL10n.message("OK"), role: .cancel) {} }
        message: { Text(photoExportMessage ?? "") }
        .sheet(isPresented: $isEditing) {
            ChekinanaMemoryEditor(memory: memory, onDeleted: { dismiss() })
        }
        .fullScreenCover(item: $previewSelection) {
            ChekinanaMemoryAttachmentPreview(selection: $0, items: attachments.compactMap { preview(for: $0) }, cache: imageCache)
        }
        .accessibilityIdentifier("chekinana.memory.detail")
    }

    private func detailPreloadKey(_ attachments: [MemoryAttachment]) -> String {
        let identifiers = attachments.map { attachment in
            "\(attachment.id.uuidString):\(attachment.managedRef)"
        }.joined(separator: "|")
        return "\(viewportWidth):\(displayScale):\(identifiers)"
    }

    @ViewBuilder
    private func memoryAttachmentButton(
        _ attachment: MemoryAttachment
    ) -> some View {
        if let selection = preview(for: attachment) {
            Button {
                if isSelectingAttachments {
                    if !selectedAttachmentIDs.insert(attachment.id).inserted {
                        selectedAttachmentIDs.remove(attachment.id)
                    }
                } else { previewSelection = selection }
            } label: {
                ChekinanaMemoryAttachmentThumbnail(
                    selection: selection, displaysFullSize: true,
                    cachedImage: imageCache.image(for: selection),
                    usesPageCache: attachment.kind == .image,
                    cachedUnavailable: imageCache.unavailable.contains(selection.cacheKey)
                )
                    .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .disabled(isExportingPhotos)
            .overlay(alignment: .topTrailing) {
                if isSelectingAttachments {
                    Image(systemName: selectedAttachmentIDs.contains(attachment.id)
                        ? "checkmark.circle.fill" : "circle")
                        .font(.title2)
                        .symbolRenderingMode(.palette)
                        .foregroundStyle(.white, ChekinanaProductTheme.accent)
                        .background(.black.opacity(0.35), in: Circle())
                        .padding(8)
                        .allowsHitTesting(false)
                }
            }
            .accessibilityAddTraits(selectedAttachmentIDs.contains(attachment.id) ? .isSelected : [])
            .accessibilityLabel(
                attachment.kind == .image
                    ? ChekinanaProductCopy.text("memory.attachment.image", "Image")
                    : ChekinanaProductCopy.text("memory.attachment.video", "Video")
            )
            .accessibilityHint(
                isSelectingAttachments ? "" : ChekinanaProductCopy.text(
                    "memory.attachment.open_hint",
                    "Open this attachment"
                )
            )
            .accessibilityIdentifier(
                "chekinana.memory.detail.attachment.\(attachment.id.uuidString.lowercased())"
            )
        } else {
            Label(
                ChekinanaProductCopy.text(
                    "memory.attachment.unavailable",
                    "Attachment unavailable"
                ),
                systemImage: "exclamationmark.triangle"
            )
            .foregroundStyle(.secondary)
            .frame(maxWidth: .infinity, minHeight: 150)
        }
    }

    private func beginPhotoExport() {
        guard isSelectingAttachments, !isExportingPhotos else { return }
        let chosen = attachments.filter { selectedAttachmentIDs.contains($0.id) }
        guard !chosen.isEmpty else { return }
        let items = chosen.map { attachment in
            (id: attachment.id, file: ChekinanaGalleryPhotoExportItem(
                reference: attachment.managedRef, ownerID: attachment.id,
                kind: attachment.kind == .image ? .shame : .douga))
        }
        photoExportCompleted = 0
        photoExportTotal = items.count
        isExportingPhotos = true
        photoExportTask = Task { @MainActor in
            defer { isExportingPhotos = false; photoExportTask = nil }
            do {
                try await ChekinanaOrderedPhotoExport.save(items,
                    authorize: { try await ChekinanaProductPhotoSaver.authorizeAdding() },
                    write: { item in
                        try await ChekinanaProductPhotoSaver.saveAuthorizedFile(
                            at: item.file.managedURL(), isVideo: item.file.kind == .douga)
                    },
                    didSave: { count in
                        photoExportCompleted = count
                        // A committed Photos item must not be repeated on retry.
                        selectedAttachmentIDs.remove(items[count - 1].id)
                    })
                photoExportMessage = ChekinanaProductCopy.format("gallery.photos.complete",
                    "Saved %lld media items to Photos.", Int64(photoExportCompleted))
            } catch is CancellationError {
                photoExportMessage = ChekinanaProductCopy.format("gallery.photos.stopped",
                    "Stopped. Saved %1$lld of %2$lld media items.", Int64(photoExportCompleted), Int64(items.count))
            } catch {
                photoExportMessage = ChekinanaProductCopy.format("gallery.photos.failed",
                    "Saved %1$lld of %2$lld media items. %3$@", Int64(photoExportCompleted), Int64(items.count), error.localizedDescription)
            }
        }
    }

    private func preview(
        for attachment: MemoryAttachment
    ) -> ChekinanaMemoryAttachmentPreviewSelection? {
        guard let url = ChekinanaGalleryMediaStore.managedURL(
            for: attachment.managedRef,
            id: attachment.id,
            kind: attachment.kind == .image ? .shame : .douga
        ) else { return nil }
        return .init(id: attachment.id, kind: attachment.kind, url: url)
    }
}

struct ChekinanaMemoryAttachmentDeletionJournal: Codable, Equatable, Sendable {
    enum Purpose: String, Codable, Sendable {
        case removePersistedAttachment
        case rollbackMaterializedAttachment
    }

    enum Phase: String, Codable, Sendable {
        case intentPersisted
        case databaseCommitted
    }

    struct Entry: Codable, Equatable, Sendable {
        enum Role: String, Codable, Sendable {
            case main
            case thumbnail
        }

        enum Status: String, Codable, Sendable {
            case pending
            case removed
            case cancelled
        }

        let attachmentID: UUID
        let kind: MemoryAttachmentKind
        let role: Role
        let filename: String
        let identity: ChekinanaImportFileIdentity?
        var status: Status

        var isValid: Bool {
            let expectedStem: String
            switch kind {
            case .image:
                expectedStem = "shame-\(attachmentID.uuidString.lowercased())"
            case .video:
                expectedStem = "douga-\(attachmentID.uuidString.lowercased())"
            }
            let filenameURL = URL(fileURLWithPath: filename)
            let hasExpectedName: Bool
            switch role {
            case .main:
                hasExpectedName = filenameURL.deletingPathExtension()
                    .lastPathComponent == expectedStem
                    && ChekinanaGalleryMediaStore
                        .isManagedDeletionFilename(filename)
            case .thumbnail:
                hasExpectedName = kind == .video
                    && filename
                        == "douga-thumb-\(attachmentID.uuidString.lowercased()).jpg"
            }
            guard filename == filenameURL.lastPathComponent,
                  filename != ".",
                  filename != "..",
                  hasExpectedName,
                  identity?.isValid != false else {
                return false
            }
            return status != .pending || identity != nil
        }
    }

    let formatVersion: Int
    let operationID: UUID
    let libraryGeneration: UUID
    let purpose: Purpose
    var phase: Phase
    var entries: [Entry]

    var isValid: Bool {
        formatVersion == 1
            && !entries.isEmpty
            && Set(entries.map(\.filename)).count == entries.count
            && entries.allSatisfy(\.isValid)
    }
}

/// The Memory queue is intentionally separate from Gallery deletion and Idol
/// avatar cleanup. A complete main/thumbnail plan is atomically persisted and
/// synchronized before the corresponding SwiftData reference can be removed.
enum ChekinanaMemoryAttachmentDeletionJournalStore {
    static let filenamePrefix = ".memory-attachment-delete-"
    static let filenameSuffix = ".json"

    static func journalURL(operationID: UUID, in directory: URL) -> URL {
        directory.standardizedFileURL.appendingPathComponent(
            "\(filenamePrefix)\(operationID.uuidString.lowercased())\(filenameSuffix)"
        )
    }

    static func persist(
        _ journal: ChekinanaMemoryAttachmentDeletionJournal,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws {
        guard journal.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let canonicalDirectory = directory.standardizedFileURL
        let directoryValues = try canonicalDirectory.resourceValues(
            forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        )
        guard directoryValues.isDirectory == true,
              directoryValues.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let url = journalURL(
            operationID: journal.operationID,
            in: canonicalDirectory
        )
        if fileManager.fileExists(atPath: url.path) {
            let values = try url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            guard values.isRegularFile == true,
                  values.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
        }
        do {
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.sortedKeys]
            try encoder.encode(journal).write(to: url, options: [.atomic])
            let handle = try FileHandle(forWritingTo: url)
            do {
                try handle.synchronize()
                try handle.close()
            } catch {
                try? handle.close()
                throw error
            }
            guard try load(
                operationID: journal.operationID,
                in: canonicalDirectory,
                fileManager: fileManager
            ) == journal else {
                throw ChekinanaImportTransactionError.incomplete
            }
        } catch {
            throw ChekinanaImportTransactionError.incomplete
        }
    }

    static func load(
        operationID: UUID,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws -> ChekinanaMemoryAttachmentDeletionJournal? {
        let url = journalURL(operationID: operationID, in: directory)
        guard fileManager.fileExists(atPath: url.path) else { return nil }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true,
              values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let journal: ChekinanaMemoryAttachmentDeletionJournal
        do {
            journal = try JSONDecoder().decode(
                ChekinanaMemoryAttachmentDeletionJournal.self,
                from: Data(contentsOf: url, options: [.mappedIfSafe])
            )
        } catch {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        guard journal.operationID == operationID, journal.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        return journal
    }

    static func discover(
        in directory: URL,
        fileManager: FileManager = .default
    ) throws -> [ChekinanaMemoryAttachmentDeletionJournal] {
        let canonicalDirectory = directory.standardizedFileURL
        return try fileManager.contentsOfDirectory(
            at: canonicalDirectory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
            options: []
        ).compactMap { url in
            guard let operationID = operationID(
                fromJournalFilename: url.lastPathComponent
            ) else { return nil }
            let values = try url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            guard url.standardizedFileURL.deletingLastPathComponent()
                    == canonicalDirectory,
                  values.isRegularFile == true,
                  values.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            return try load(
                operationID: operationID,
                in: canonicalDirectory,
                fileManager: fileManager
            )
        }.sorted { $0.operationID.uuidString < $1.operationID.uuidString }
    }

    static func discard(
        operationID: UUID,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws {
        let url = journalURL(operationID: operationID, in: directory)
        guard fileManager.fileExists(atPath: url.path) else { return }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true,
              values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        try fileManager.removeItem(at: url)
        guard !fileManager.fileExists(atPath: url.path) else {
            throw ChekinanaImportTransactionError.incomplete
        }
    }

    static func operationID(fromJournalFilename filename: String) -> UUID? {
        guard filename.hasPrefix(filenamePrefix),
              filename.hasSuffix(filenameSuffix) else { return nil }
        let start = filename.index(
            filename.startIndex,
            offsetBy: filenamePrefix.count
        )
        let end = filename.index(
            filename.endIndex,
            offsetBy: -filenameSuffix.count
        )
        guard start < end else { return nil }
        return UUID(uuidString: String(filename[start..<end]))
    }
}

/// Managed Memory files are leased from materialization until their database
/// save commits or rollback cleanup takes ownership. Recovery never unlinks a
/// filename held by any active generation-scoped lease.
enum ChekinanaMemoryAttachmentLeaseRegistry {
    private struct Lease: Sendable {
        let generation: UUID
        var filenames: Set<String>
    }

    private static let lock = NSLock()
    private nonisolated(unsafe) static var leases: [UUID: Lease] = [:]

    static func acquire(
        ownerID: UUID,
        generation: UUID,
        filenames: some Sequence<String>
    ) {
        lock.lock()
        defer { lock.unlock() }
        var lease = leases[ownerID] ?? Lease(
            generation: generation,
            filenames: []
        )
        guard lease.generation == generation else { return }
        lease.filenames.formUnion(filenames)
        leases[ownerID] = lease
    }

    static func release(ownerID: UUID) {
        lock.lock()
        defer { lock.unlock() }
        leases[ownerID] = nil
    }

    static func isLeased(
        filename: String,
        generation: UUID,
        ignoring ownerID: UUID? = nil
    ) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        return leases.contains { currentOwner, lease in
            currentOwner != ownerID
                && lease.generation == generation
                && lease.filenames.contains(filename)
        }
    }
}

/// Persists and replays Memory attachment cleanup without changing Memory's
/// data model. DB references, active leases, library generation, and byte
/// identity are all re-read immediately before each unlink.
@MainActor
enum ChekinanaMemoryAttachmentDeletionCoordinator {
    private struct Candidate {
        let attachmentID: UUID
        let kind: MemoryAttachmentKind
        let managedRef: String
    }

    static func preparePersistedDeletion(
        _ attachments: [ChekinanaMemoryAttachmentRecordSnapshot],
        libraryGeneration: UUID,
        in modelContext: ModelContext,
        directory: URL? = nil,
        fileManager: FileManager = .default,
        beforeJournalPersist: (
            ChekinanaMemoryAttachmentDeletionJournal
        ) throws -> Void = { _ in }
    ) throws -> ChekinanaMemoryAttachmentDeletionJournal? {
        try prepare(
            attachments.map {
                Candidate(
                    attachmentID: $0.id,
                    kind: $0.kind,
                    managedRef: $0.managedRef
                )
            },
            purpose: .removePersistedAttachment,
            libraryGeneration: libraryGeneration,
            in: modelContext,
            directory: directory,
            fileManager: fileManager,
            ignoringLeaseOwnerID: nil,
            requiresCurrentReferences: true,
            beforeJournalPersist: beforeJournalPersist
        )
    }

    /// Called synchronously from Memory's file worker while the save owns the
    /// library gate. The captured reference set was read from a fresh context.
    /// Every public write gets a complete existing-v1 intent before publication.
    nonisolated static func reserveMaterializedFileBeforeWrite(
        at destination: URL,
        identity: ChekinanaImportFileIdentity,
        attachmentID: UUID,
        kind: MemoryAttachmentKind,
        ownerID: UUID,
        libraryGeneration: UUID,
        referencedFilenames: Set<String>,
        directory: URL,
        fileManager: FileManager = .default
    ) throws {
        let canonicalDirectory = directory.standardizedFileURL
        let filename = destination.lastPathComponent
        guard destination.standardizedFileURL.deletingLastPathComponent()
                == canonicalDirectory,
              !referencedFilenames.contains(filename),
              !ChekinanaMemoryAttachmentLeaseRegistry.isLeased(
                filename: filename, generation: libraryGeneration, ignoring: ownerID
              ),
              try !fileManager.contentsOfDirectory(atPath: canonicalDirectory.path)
                .contains(filename) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let role: ChekinanaMemoryAttachmentDeletionJournal.Entry.Role =
            filename == "douga-thumb-\(attachmentID.uuidString.lowercased()).jpg"
                ? .thumbnail : .main
        let journal = ChekinanaMemoryAttachmentDeletionJournal(
            formatVersion: 1,
            operationID: UUID(),
            libraryGeneration: libraryGeneration,
            purpose: .rollbackMaterializedAttachment,
            phase: .intentPersisted,
            entries: [.init(
                attachmentID: attachmentID, kind: kind, role: role,
                filename: filename, identity: identity, status: .pending
            )]
        )
        try ChekinanaMemoryAttachmentDeletionJournalStore.persist(
            journal, in: canonicalDirectory, fileManager: fileManager
        )
        ChekinanaMemoryAttachmentLeaseRegistry.acquire(
            ownerID: ownerID, generation: libraryGeneration, filenames: [filename]
        )
    }

    static func prepareMaterializedRollback(
        _ attachment: ChekinanaMemoryMaterializedAttachment,
        in modelContext: ModelContext,
        directory: URL? = nil,
        fileManager: FileManager = .default,
        beforeJournalPersist: (
            ChekinanaMemoryAttachmentDeletionJournal
        ) throws -> Void = { _ in }
    ) throws -> ChekinanaMemoryAttachmentDeletionJournal? {
        try prepare(
            [Candidate(
                attachmentID: attachment.id,
                kind: attachment.kind,
                managedRef: attachment.managedRef
            )],
            purpose: .rollbackMaterializedAttachment,
            libraryGeneration: attachment.libraryGeneration,
            in: modelContext,
            directory: directory,
            fileManager: fileManager,
            ignoringLeaseOwnerID: attachment.ownerID,
            requiresCurrentReferences: false,
            beforeJournalPersist: beforeJournalPersist
        )
    }

    static func leaseFilenames(
        for attachment: ChekinanaMemoryMaterializedAttachment
    ) -> [String] {
        filenames(for: Candidate(
            attachmentID: attachment.id,
            kind: attachment.kind,
            managedRef: attachment.managedRef
        )).map(\.1)
    }

    static func markDatabaseCommitted(
        _ journal: ChekinanaMemoryAttachmentDeletionJournal?,
        directory: URL,
        fileManager: FileManager = .default
    ) {
        guard var journal else { return }
        journal.phase = .databaseCommitted
        try? ChekinanaMemoryAttachmentDeletionJournalStore.persist(
            journal,
            in: directory,
            fileManager: fileManager
        )
    }

    static func discard(
        _ journal: ChekinanaMemoryAttachmentDeletionJournal?,
        directory: URL,
        fileManager: FileManager = .default
    ) {
        guard let journal else { return }
        try? ChekinanaMemoryAttachmentDeletionJournalStore.discard(
            operationID: journal.operationID,
            in: directory,
            fileManager: fileManager
        )
    }

    @discardableResult
    static func recoverExclusively(
        in modelContext: ModelContext,
        directory: URL,
        fileManager: FileManager = .default,
        beforeCandidateValidation: (
            ChekinanaMemoryAttachmentDeletionJournal.Entry
        ) -> Void = { _ in },
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        }
    ) -> Int {
        let canonicalDirectory = directory.standardizedFileURL
        let journals: [ChekinanaMemoryAttachmentDeletionJournal]
        do {
            journals = try ChekinanaMemoryAttachmentDeletionJournalStore.discover(
                in: canonicalDirectory,
                fileManager: fileManager
            )
        } catch {
            return 1
        }

        var deferred = 0
        for original in journals {
            var journal = original
            let snapshot: ChekinanaLibraryFileReferenceSnapshot
            do {
                snapshot = try ChekinanaLibraryFileReferenceSnapshot.capture(
                    in: ModelContext(modelContext.container),
                    directory: canonicalDirectory
                )
            } catch {
                deferred += 1
                continue
            }

            guard snapshot.generation == journal.libraryGeneration else {
                // The import/clear protocol published another library. This
                // intent has no authority over files in that generation.
                do {
                    try ChekinanaMemoryAttachmentDeletionJournalStore.discard(
                        operationID: journal.operationID,
                        in: canonicalDirectory,
                        fileManager: fileManager
                    )
                } catch {
                    deferred += 1
                }
                continue
            }

            var journalNeedsRetry = false
            for index in journal.entries.indices
            where journal.entries[index].status == .pending {
                let entry = journal.entries[index]
                beforeCandidateValidation(entry)
                let outcome = recover(
                    entry,
                    journal: journal,
                    modelContext: modelContext,
                    directory: canonicalDirectory,
                    fileManager: fileManager,
                    removeItem: removeItem
                )
                switch outcome {
                case .removed:
                    journal.entries[index].status = .removed
                case .cancelled:
                    journal.entries[index].status = .cancelled
                case .deferred:
                    deferred += 1
                    journalNeedsRetry = true
                    continue
                }
                do {
                    try ChekinanaMemoryAttachmentDeletionJournalStore.persist(
                        journal,
                        in: canonicalDirectory,
                        fileManager: fileManager
                    )
                } catch {
                    deferred += 1
                    journalNeedsRetry = true
                }
            }

            guard !journalNeedsRetry,
                  journal.entries.allSatisfy({ $0.status != .pending }) else {
                continue
            }
            do {
                try ChekinanaMemoryAttachmentDeletionJournalStore.discard(
                    operationID: journal.operationID,
                    in: canonicalDirectory,
                    fileManager: fileManager
                )
            } catch {
                deferred += 1
            }
        }
        return deferred
    }

    private enum RecoveryOutcome {
        case removed
        case cancelled
        case deferred
    }

    private static func prepare(
        _ candidates: [Candidate],
        purpose: ChekinanaMemoryAttachmentDeletionJournal.Purpose,
        libraryGeneration: UUID,
        in modelContext: ModelContext,
        directory: URL?,
        fileManager: FileManager,
        ignoringLeaseOwnerID: UUID?,
        requiresCurrentReferences: Bool,
        beforeJournalPersist: (
            ChekinanaMemoryAttachmentDeletionJournal
        ) throws -> Void
    ) throws -> ChekinanaMemoryAttachmentDeletionJournal? {
        guard !candidates.isEmpty else { return nil }
        let resolvedDirectory = try directory
            ?? ChekiImageRefResolver.chekiImagesDirectory()
        let snapshot = try ChekinanaLibraryFileReferenceSnapshot.capture(
            in: ModelContext(modelContext.container),
            directory: resolvedDirectory
        )
        guard snapshot.generation == libraryGeneration else {
            throw ChekinanaImportTransactionError.indeterminate
        }

        var entries: [ChekinanaMemoryAttachmentDeletionJournal.Entry] = []
        for candidate in candidates {
            for (role, filename) in filenames(for: candidate) {
                if requiresCurrentReferences {
                    guard snapshot.referencedFilenames.contains(filename) else {
                        throw ChekinanaImportTransactionError.indeterminate
                    }
                } else {
                    guard !snapshot.referencedFilenames.contains(filename) else {
                        throw ChekinanaImportTransactionError.indeterminate
                    }
                }
                guard !ChekinanaMemoryAttachmentLeaseRegistry.isLeased(
                    filename: filename,
                    generation: libraryGeneration,
                    ignoring: ignoringLeaseOwnerID
                ) else {
                    throw ChekinanaImportTransactionError.incomplete
                }
                let url = resolvedDirectory.appendingPathComponent(filename)
                let identity = try identityIfPresent(
                    url,
                    directory: resolvedDirectory,
                    fileManager: fileManager
                )
                entries.append(.init(
                    attachmentID: candidate.attachmentID,
                    kind: candidate.kind,
                    role: role,
                    filename: filename,
                    identity: identity,
                    status: identity == nil ? .removed : .pending
                ))
            }
        }
        guard !entries.isEmpty else { return nil }
        let journal = ChekinanaMemoryAttachmentDeletionJournal(
            formatVersion: 1,
            operationID: UUID(),
            libraryGeneration: libraryGeneration,
            purpose: purpose,
            phase: .intentPersisted,
            entries: entries
        )
        guard journal.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        try beforeJournalPersist(journal)
        try ChekinanaMemoryAttachmentDeletionJournalStore.persist(
            journal,
            in: resolvedDirectory,
            fileManager: fileManager
        )
        return journal
    }

    private static func filenames(
        for candidate: Candidate
    ) -> [(ChekinanaMemoryAttachmentDeletionJournal.Entry.Role, String)] {
        let reference = candidate.managedRef.trimmingCharacters(
            in: .whitespacesAndNewlines
        )
        let expectedStem = candidate.kind == .image
            ? "shame-\(candidate.attachmentID.uuidString.lowercased())"
            : "douga-\(candidate.attachmentID.uuidString.lowercased())"
        var result: [(
            ChekinanaMemoryAttachmentDeletionJournal.Entry.Role,
            String
        )] = []
        if reference == URL(fileURLWithPath: reference).lastPathComponent,
           URL(fileURLWithPath: reference).deletingPathExtension()
            .lastPathComponent == expectedStem,
           ChekinanaGalleryMediaStore.isManagedDeletionFilename(reference) {
            result.append((.main, reference))
        }
        if candidate.kind == .video {
            result.append((
                .thumbnail,
                "douga-thumb-\(candidate.attachmentID.uuidString.lowercased()).jpg"
            ))
        }
        return result
    }

    private static func recover(
        _ entry: ChekinanaMemoryAttachmentDeletionJournal.Entry,
        journal: ChekinanaMemoryAttachmentDeletionJournal,
        modelContext: ModelContext,
        directory: URL,
        fileManager: FileManager,
        removeItem: (URL) throws -> Void
    ) -> RecoveryOutcome {
        do {
            return try ChekinanaPersistenceMutationCoordinator.withLock {
                let latest = try ChekinanaLibraryFileReferenceSnapshot.capture(
                    in: ModelContext(modelContext.container),
                    directory: directory
                )
                guard latest.generation == journal.libraryGeneration else {
                    return .cancelled
                }
                guard !latest.referencedFilenames.contains(entry.filename) else {
                    return .cancelled
                }
                guard !ChekinanaMemoryAttachmentLeaseRegistry.isLeased(
                    filename: entry.filename,
                    generation: journal.libraryGeneration
                ) else {
                    return .deferred
                }
                let url = directory.appendingPathComponent(entry.filename)
                guard let currentIdentity = try identityIfPresent(
                    url,
                    directory: directory,
                    fileManager: fileManager
                ) else {
                    return .removed
                }
                guard currentIdentity == entry.identity else {
                    // A restored backup or a newly materialized object reused
                    // this public name. Retire the old intent without unlinking.
                    return .cancelled
                }

                // Recheck every authority immediately before unlink. No await
                // occurs while the persistence lock is held.
                let refreshed = try ChekinanaLibraryFileReferenceSnapshot.capture(
                    in: ModelContext(modelContext.container),
                    directory: directory
                )
                guard refreshed.generation == journal.libraryGeneration,
                      !refreshed.referencedFilenames.contains(entry.filename),
                      !ChekinanaMemoryAttachmentLeaseRegistry.isLeased(
                        filename: entry.filename,
                        generation: journal.libraryGeneration
                      ),
                      try identityIfPresent(
                        url,
                        directory: directory,
                        fileManager: fileManager
                      ) == entry.identity else {
                    return .deferred
                }
                do {
                    try removeItem(url)
                } catch {
                    // File-not-found is an idempotent success even if the
                    // injected remover reports it as an error.
                    guard !fileManager.fileExists(atPath: url.path) else {
                        return .deferred
                    }
                }
                return fileManager.fileExists(atPath: url.path)
                    ? .deferred : .removed
            }
        } catch {
            return .deferred
        }
    }

    private static func identityIfPresent(
        _ url: URL,
        directory: URL,
        fileManager: FileManager
    ) throws -> ChekinanaImportFileIdentity? {
        guard url.standardizedFileURL.deletingLastPathComponent()
                == directory.standardizedFileURL else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        guard fileManager.fileExists(atPath: url.path) else { return nil }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true,
              values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return try ChekinanaImportFileIdentity.inspect(url)
    }
}

/// Controlled injected file managers must synchronize their own mutable state
/// and must not be externally mutated while a Memory file operation is in flight.
protocol ChekinanaMemoryReservationFileManager: AnyObject, Sendable {}

/// Transfers only immutable file authority to one awaited file operation.
/// No ModelContext crosses executors. The default manager has no delegate;
/// injected managers require an explicit, synchronized Sendable contract.
private final class ChekinanaMemoryFileReservation: @unchecked Sendable {
    private let lock = NSLock()
    private let attachmentID: UUID
    private let kind: MemoryAttachmentKind
    private let ownerID: UUID
    private let libraryGeneration: UUID
    private let referencedFilenames: Set<String>
    private let directory: URL
    private let fileManager: FileManager

    static func validate(_ fileManager: FileManager) throws {
        guard fileManager.delegate == nil,
              fileManager === FileManager.default
                || fileManager is any ChekinanaMemoryReservationFileManager else {
            throw ChekinanaImportTransactionError.indeterminate
        }
    }

    init(
        attachmentID: UUID, kind: MemoryAttachmentKind, ownerID: UUID,
        libraryGeneration: UUID, referencedFilenames: Set<String>,
        directory: URL, fileManager: FileManager
    ) throws {
        try Self.validate(fileManager)
        self.attachmentID = attachmentID
        self.kind = kind
        self.ownerID = ownerID
        self.libraryGeneration = libraryGeneration
        self.referencedFilenames = referencedFilenames
        self.directory = directory
        self.fileManager = fileManager
    }

    func reserve(at destination: URL, identity: ChekinanaImportFileIdentity) throws {
        lock.lock()
        defer { lock.unlock() }
        try Self.validate(fileManager)
        try ChekinanaMemoryAttachmentDeletionCoordinator.reserveMaterializedFileBeforeWrite(
            at: destination, identity: identity, attachmentID: attachmentID,
            kind: kind, ownerID: ownerID, libraryGeneration: libraryGeneration,
            referencedFilenames: referencedFilenames, directory: directory,
            fileManager: fileManager
        )
    }
}

@MainActor
enum ChekinanaMemorySaveCommitter {
    typealias SaveContext = @MainActor (ModelContext) throws -> Void
    typealias MaterializeAttachment = @MainActor (
        ChekinanaMemorySaveAttachmentDraft
    ) async throws -> String
    typealias RemoveManagedFile = @MainActor (
        MemoryAttachmentKind,
        UUID,
        String
    ) throws -> Void
    typealias RecordOrphanedFile = @MainActor (
        MemoryAttachmentKind,
        UUID,
        String
    ) -> Void
    typealias DeletionJournalPersisted = @MainActor (
        ChekinanaMemoryAttachmentDeletionJournal
    ) throws -> Void

    @discardableResult
    static func save(
        draft: ChekinanaMemorySaveDraft,
        expectedTarget: ChekinanaMemoryTargetSnapshot?,
        ownerID: UUID,
        targetID: UUID,
        in modelContext: ModelContext,
        directory: URL? = nil,
        fileManager: FileManager = .default,
        saveContext: SaveContext = { try $0.save() },
        materializeAttachment: MaterializeAttachment? = nil,
        removeManagedFile: RemoveManagedFile? = nil,
        recordOrphanedFile: RecordOrphanedFile? = nil,
        deletionJournalPersisted: DeletionJournalPersisted = { _ in }
    ) async throws -> ChekinanaMemorySaveAuthorization {
        try validateDraft(draft, expectedTarget: expectedTarget, targetID: targetID)
        let usesJournaledCleanup = materializeAttachment == nil
            && removeManagedFile == nil
            && recordOrphanedFile == nil
        if usesJournaledCleanup {
            try ChekinanaMemoryFileReservation.validate(fileManager)
        }
        let materializeAttachment: MaterializeAttachment = materializeAttachment
            ?? { try await defaultMaterialize($0) }
        let removeManagedFile = removeManagedFile ?? defaultRemove
        let recordOrphanedFile = recordOrphanedFile ?? defaultRecordOrphan
        var materialized: [ChekinanaMemoryMaterializedAttachment] = []
        var persistedDeletionJournal: ChekinanaMemoryAttachmentDeletionJournal?
        var databaseCommitted = false

        return try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: directory
            )
            let managedDirectory = usesJournaledCleanup
                ? try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
                : nil
            defer {
                if usesJournaledCleanup {
                    ChekinanaMemoryAttachmentLeaseRegistry.release(ownerID: ownerID)
                }
            }
            do {
                let authorization = try ChekinanaPersistenceMutationCoordinator.withLock {
                    try Task.checkCancellation()
                    let generation = try ChekinanaLibraryGenerationStore.ensureCurrent(
                        in: modelContext
                    )
                    if let managedDirectory {
                        // Reuse accepted input after an earlier failed save. A
                        // still-protected destination is rejected by its reservation.
                        _ = ChekinanaMemoryAttachmentDeletionCoordinator.recoverExclusively(
                            in: modelContext,
                            directory: managedDirectory,
                            fileManager: fileManager
                        )
                    }
                    let authorization = ChekinanaMemorySaveAuthorization(
                        ownerID: ownerID,
                        libraryGeneration: generation,
                        targetID: targetID,
                        expectedTarget: expectedTarget
                    )
                    _ = try validateAuthorization(authorization, in: modelContext)
                    try validateAttachmentOwnership(
                        draft,
                        targetID: targetID,
                        in: modelContext
                    )
                    return authorization
                }

                for attachment in draft.attachments where attachment.stagedURL != nil {
                    try ChekinanaPersistenceMutationCoordinator.withLock {
                        try Task.checkCancellation()
                        _ = try validateAuthorization(authorization, in: modelContext)
                    }
                    let managedRef: String
                    if let managedDirectory {
                        let references = try ChekinanaPersistenceMutationCoordinator.withLock {
                            let snapshot = try ChekinanaLibraryFileReferenceSnapshot.capture(
                                in: ModelContext(modelContext.container),
                                directory: managedDirectory
                            )
                            guard snapshot.generation == authorization.libraryGeneration else {
                                throw ChekinanaMemorySaveMutationError.changedLibrary
                            }
                            return snapshot.referencedFilenames
                        }
                        let reservation = try ChekinanaMemoryFileReservation(
                            attachmentID: attachment.id, kind: attachment.kind,
                            ownerID: authorization.ownerID,
                            libraryGeneration: authorization.libraryGeneration,
                            referencedFilenames: references,
                            directory: managedDirectory, fileManager: fileManager
                        )
                        managedRef = try await defaultMaterialize(
                            attachment,
                            directory: managedDirectory,
                            memoryFileWillPublish: { destination, identity in
                                try reservation.reserve(at: destination, identity: identity)
                            }
                        )
                    } else {
                        managedRef = try await materializeAttachment(attachment)
                    }
                    let output = ChekinanaMemoryMaterializedAttachment(
                        ownerID: authorization.ownerID,
                        libraryGeneration: authorization.libraryGeneration,
                        id: attachment.id,
                        kind: attachment.kind,
                        managedRef: managedRef
                    )
                    materialized.append(output)
                }

                let removedAttachments = try ChekinanaPersistenceMutationCoordinator.withLock {
                    try Task.checkCancellation()
                    let target = try validateAuthorization(
                        authorization,
                        in: modelContext
                    ) ?? Memory(id: authorization.targetID)
                    try validateAttachmentOwnership(
                        draft,
                        targetID: authorization.targetID,
                        in: modelContext
                    )
                    try validateRelationships(draft, in: modelContext)

                    let currentAttachments = try modelContext.fetch(
                        FetchDescriptor<MemoryAttachment>()
                    ).filter { $0.memoryID == authorization.targetID }
                    let currentByID = Dictionary(
                        currentAttachments.map { ($0.id, $0) },
                        uniquingKeysWith: { first, _ in first }
                    )
                    let materializedByID = Dictionary(
                        materialized.map { ($0.id, $0) },
                        uniquingKeysWith: { first, _ in first }
                    )
                    let retainedIDs = Set(draft.attachments.map(\.id))
                    let removedAttachmentSnapshots = currentAttachments
                        .filter { !retainedIDs.contains($0.id) }
                        .map(ChekinanaMemoryAttachmentRecordSnapshot.init)

                    do {
                        if let managedDirectory {
                            persistedDeletionJournal = try
                                ChekinanaMemoryAttachmentDeletionCoordinator
                                    .preparePersistedDeletion(
                                        removedAttachmentSnapshots,
                                        libraryGeneration: authorization.libraryGeneration,
                                        in: modelContext,
                                        directory: managedDirectory,
                                        fileManager: fileManager
                                    )
                            if let persistedDeletionJournal {
                                try deletionJournalPersisted(
                                    persistedDeletionJournal
                                )
                            }
                        }
                        target.title = ChekinanaMemoryPolicy.normalizedTitle(draft.title)
                        target.bodyText = ChekinanaMemoryPolicy.meaningfulText(draft.bodyText)
                        target.date = draft.date
                        target.eventID = draft.eventID
                        target.idolIDs = draft.idolIDs
                        target.updatedAt = Date()
                        if authorization.expectedTarget == nil {
                            modelContext.insert(target)
                        }

                        for attachment in currentAttachments
                        where !retainedIDs.contains(attachment.id) {
                            modelContext.delete(attachment)
                        }
                        for attachment in draft.attachments {
                            if let live = currentByID[attachment.id] {
                                live.sortOrder = attachment.sortOrder
                                live.updatedAt = Date()
                            } else if let output = materializedByID[attachment.id] {
                                guard output.ownerID == authorization.ownerID,
                                      output.libraryGeneration
                                        == authorization.libraryGeneration else {
                                    throw ChekinanaMemorySaveMutationError.invalidDraft
                                }
                                modelContext.insert(MemoryAttachment(
                                    id: output.id,
                                    memoryID: authorization.targetID,
                                    kind: output.kind,
                                    managedRef: output.managedRef,
                                    sortOrder: attachment.sortOrder
                                ))
                            } else {
                                throw ChekinanaMemorySaveMutationError.invalidDraft
                            }
                        }
                        try saveContext(modelContext)
                    } catch {
                        modelContext.rollback()
                        throw error
                    }

                    return removedAttachmentSnapshots
                }
                databaseCommitted = true

                if let managedDirectory {
                    ChekinanaMemoryAttachmentLeaseRegistry.release(
                        ownerID: authorization.ownerID
                    )
                    ChekinanaMemoryAttachmentDeletionCoordinator.markDatabaseCommitted(
                        persistedDeletionJournal,
                        directory: managedDirectory,
                        fileManager: fileManager
                    )
                    _ = ChekinanaMemoryAttachmentDeletionCoordinator
                        .recoverExclusively(
                            in: modelContext,
                            directory: managedDirectory,
                            fileManager: fileManager
                        )
                } else {
                    cleanupPersistedAttachments(
                        removedAttachments,
                        libraryGeneration: authorization.libraryGeneration,
                        in: modelContext,
                        removeManagedFile: removeManagedFile,
                        recordOrphanedFile: recordOrphanedFile
                    )
                }
                return authorization
            } catch {
                if !databaseCommitted {
                    if let managedDirectory {
                        ChekinanaMemoryAttachmentLeaseRegistry.release(ownerID: ownerID)
                        _ = ChekinanaMemoryAttachmentDeletionCoordinator
                            .recoverExclusively(
                                in: modelContext,
                                directory: managedDirectory,
                                fileManager: fileManager
                            )
                    } else {
                        cleanupMaterializedAttachments(
                            materialized,
                            in: modelContext,
                            removeManagedFile: removeManagedFile,
                            recordOrphanedFile: recordOrphanedFile
                        )
                    }
                }
                throw error
            }
        }
    }

    static func delete(
        expectedTarget: ChekinanaMemoryTargetSnapshot,
        in modelContext: ModelContext,
        directory: URL? = nil,
        fileManager: FileManager = .default,
        saveContext: SaveContext = { try $0.save() },
        removeManagedFile: RemoveManagedFile? = nil,
        recordOrphanedFile: RecordOrphanedFile? = nil,
        deletionJournalPersisted: DeletionJournalPersisted = { _ in }
    ) async throws {
        let usesJournaledCleanup = removeManagedFile == nil
            && recordOrphanedFile == nil
        let removeManagedFile = removeManagedFile ?? defaultRemove
        let recordOrphanedFile = recordOrphanedFile ?? defaultRecordOrphan
        try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: directory
            )
            let managedDirectory = usesJournaledCleanup
                ? try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
                : nil
            var deletionJournal: ChekinanaMemoryAttachmentDeletionJournal?
            do {
                let deletion = try ChekinanaPersistenceMutationCoordinator.withLock {
                    try Task.checkCancellation()
                    let generation = try ChekinanaLibraryGenerationStore.ensureCurrent(
                        in: modelContext
                    )
                    let authorization = ChekinanaMemorySaveAuthorization(
                        ownerID: UUID(),
                        libraryGeneration: generation,
                        targetID: expectedTarget.record.id,
                        expectedTarget: expectedTarget
                    )
                    guard let target = try validateAuthorization(
                        authorization,
                        in: modelContext
                    ) else {
                        throw ChekinanaMemorySaveMutationError.changedMemory
                    }
                    let attachments = try modelContext.fetch(
                        FetchDescriptor<MemoryAttachment>()
                    ).filter { $0.memoryID == target.id }
                    let attachmentSnapshots = attachments.map(
                        ChekinanaMemoryAttachmentRecordSnapshot.init
                    )
                    do {
                        if let managedDirectory {
                            deletionJournal = try
                                ChekinanaMemoryAttachmentDeletionCoordinator
                                    .preparePersistedDeletion(
                                        attachmentSnapshots,
                                        libraryGeneration: authorization.libraryGeneration,
                                        in: modelContext,
                                        directory: managedDirectory,
                                        fileManager: fileManager
                                    )
                            if let deletionJournal {
                                try deletionJournalPersisted(deletionJournal)
                            }
                        }
                        attachments.forEach(modelContext.delete)
                        modelContext.delete(target)
                        try saveContext(modelContext)
                    } catch {
                        modelContext.rollback()
                        throw error
                    }
                    return (
                        libraryGeneration: authorization.libraryGeneration,
                        attachments: attachmentSnapshots
                    )
                }
                if let managedDirectory {
                    ChekinanaMemoryAttachmentDeletionCoordinator.markDatabaseCommitted(
                        deletionJournal,
                        directory: managedDirectory,
                        fileManager: fileManager
                    )
                    _ = ChekinanaMemoryAttachmentDeletionCoordinator
                        .recoverExclusively(
                            in: modelContext,
                            directory: managedDirectory,
                            fileManager: fileManager
                        )
                } else {
                    cleanupPersistedAttachments(
                        deletion.attachments,
                        libraryGeneration: deletion.libraryGeneration,
                        in: modelContext,
                        removeManagedFile: removeManagedFile,
                        recordOrphanedFile: recordOrphanedFile
                    )
                }
            } catch {
                if let managedDirectory {
                    _ = ChekinanaMemoryAttachmentDeletionCoordinator
                        .recoverExclusively(
                            in: modelContext,
                            directory: managedDirectory,
                            fileManager: fileManager
                        )
                }
                throw error
            }
        }
    }

    static func targetSnapshot(
        memoryID: UUID,
        in modelContext: ModelContext
    ) throws -> ChekinanaMemoryTargetSnapshot? {
        let matches = try modelContext.fetch(FetchDescriptor<Memory>())
            .filter { $0.id == memoryID }
        guard matches.count <= 1 else {
            throw ChekinanaMemorySaveMutationError.changedMemory
        }
        let attachments = try modelContext.fetch(FetchDescriptor<MemoryAttachment>())
            .filter { $0.memoryID == memoryID }
        guard let memory = matches.first else {
            guard attachments.isEmpty else {
                throw ChekinanaMemorySaveMutationError.changedMemory
            }
            return nil
        }
        return ChekinanaMemoryTargetSnapshot(
            record: ChekinanaMemoryRecordSnapshot(memory),
            attachments: attachments.map(ChekinanaMemoryAttachmentRecordSnapshot.init)
        )
    }

    private static func validateDraft(
        _ draft: ChekinanaMemorySaveDraft,
        expectedTarget: ChekinanaMemoryTargetSnapshot?,
        targetID: UUID
    ) throws {
        let canonicalDate = try ChekinanaMemoryPolicy.validateContent(
            title: draft.title,
            bodyText: draft.bodyText,
            date: draft.date,
            eventID: draft.eventID,
            idolIDs: draft.idolIDs,
            attachmentCount: draft.attachments.count
        )
        guard canonicalDate == draft.date,
              Set(draft.idolIDs).count == draft.idolIDs.count,
              Set(draft.attachments.map(\.id)).count == draft.attachments.count,
              draft.attachments.enumerated().allSatisfy({ index, attachment in
                  attachment.sortOrder == index
                      && ((attachment.existingReference?.nonEmpty != nil)
                          != (attachment.stagedURL != nil))
              }),
              expectedTarget?.record.id == targetID || expectedTarget == nil else {
            throw ChekinanaMemorySaveMutationError.invalidDraft
        }
        if expectedTarget == nil,
           draft.attachments.contains(where: { $0.existingReference != nil }) {
            throw ChekinanaMemorySaveMutationError.invalidDraft
        }
    }

    private static func validateAuthorization(
        _ authorization: ChekinanaMemorySaveAuthorization,
        in modelContext: ModelContext
    ) throws -> Memory? {
        guard try ChekinanaLibraryGenerationStore.current(in: modelContext)
                == authorization.libraryGeneration else {
            throw ChekinanaMemorySaveMutationError.changedLibrary
        }
        let current = try targetSnapshot(
            memoryID: authorization.targetID,
            in: modelContext
        )
        if let expected = authorization.expectedTarget {
            guard current == expected else {
                throw ChekinanaMemorySaveMutationError.changedMemory
            }
            let matches = try modelContext.fetch(FetchDescriptor<Memory>())
                .filter { $0.id == authorization.targetID }
            guard matches.count == 1 else {
                throw ChekinanaMemorySaveMutationError.changedMemory
            }
            return matches[0]
        }
        guard current == nil else {
            throw ChekinanaMemorySaveMutationError.changedMemory
        }
        return nil
    }

    private static func validateAttachmentOwnership(
        _ draft: ChekinanaMemorySaveDraft,
        targetID: UUID,
        in modelContext: ModelContext
    ) throws {
        let allAttachments = try modelContext.fetch(FetchDescriptor<MemoryAttachment>())
        let targetByID = Dictionary(
            allAttachments.filter { $0.memoryID == targetID }.map { ($0.id, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        for attachment in draft.attachments {
            if let existingReference = attachment.existingReference {
                guard let persisted = targetByID[attachment.id],
                      persisted.kind == attachment.kind,
                      persisted.managedRef == existingReference else {
                    throw ChekinanaMemorySaveMutationError.changedMemory
                }
            } else if allAttachments.contains(where: { $0.id == attachment.id }) {
                throw ChekinanaMemorySaveMutationError.changedMemory
            }
        }
    }

    private static func validateRelationships(
        _ draft: ChekinanaMemorySaveDraft,
        in modelContext: ModelContext
    ) throws {
        let validIdolIDs = Set(try modelContext.fetch(FetchDescriptor<Idol>()).map(\.id))
        guard Set(draft.idolIDs).isSubset(of: validIdolIDs) else {
            throw ChekinanaMemorySaveMutationError.changedRelationships
        }
        if let eventID = draft.eventID {
            let matches = try modelContext.fetch(FetchDescriptor<Event>())
                .filter { $0.id == eventID }
            guard matches.count == 1 else {
                throw ChekinanaMemorySaveMutationError.changedRelationships
            }
        }
    }

    private static func defaultMaterialize(
        _ attachment: ChekinanaMemorySaveAttachmentDraft,
        directory: URL? = nil,
        memoryFileWillPublish: ChekinanaGalleryMediaStore.MemoryFileWillPublish? = nil
    ) async throws -> String {
        guard let stagedURL = attachment.stagedURL else {
            throw ChekinanaMemorySaveMutationError.invalidDraft
        }
        switch attachment.kind {
        case .image:
            return try await ChekinanaGalleryMediaStore.saveImage(
                from: stagedURL,
                id: attachment.id,
                filenameExtension: stagedURL.pathExtension,
                directory: directory,
                memoryFileWillPublish: memoryFileWillPublish
            )
        case .video:
            return try await ChekinanaGalleryMediaStore.saveVideo(
                from: stagedURL,
                id: attachment.id,
                directory: directory,
                memoryFileWillPublish: memoryFileWillPublish
            )
        }
    }

    private static func defaultRemove(
        kind: MemoryAttachmentKind,
        id: UUID,
        managedRef: String
    ) throws {
        try ChekinanaGalleryMediaStore.removeFiles(
            kind: kind == .image ? .shame : .douga,
            id: id,
            reference: managedRef
        )
    }

    private static func defaultRecordOrphan(
        kind: MemoryAttachmentKind,
        id: UUID,
        managedRef: String
    ) {
        ChekinanaGalleryMediaStore.recordOrphanedImport(
            kind: kind == .image ? .shame : .douga,
            id: id,
            reference: managedRef
        )
    }

    private static func cleanupMaterializedAttachments(
        _ attachments: [ChekinanaMemoryMaterializedAttachment],
        in modelContext: ModelContext,
        removeManagedFile: RemoveManagedFile,
        recordOrphanedFile: RecordOrphanedFile
    ) {
        for attachment in attachments {
            ChekinanaPersistenceMutationCoordinator.withLock {
                guard canRemoveManagedFileLocked(
                    kind: attachment.kind,
                    id: attachment.id,
                    managedRef: attachment.managedRef,
                    libraryGeneration: attachment.libraryGeneration,
                    in: modelContext
                ) else {
                    recordOrphanedFile(
                        attachment.kind,
                        attachment.id,
                        attachment.managedRef
                    )
                    return
                }
                cleanup(
                    kind: attachment.kind,
                    id: attachment.id,
                    managedRef: attachment.managedRef,
                    removeManagedFile: removeManagedFile,
                    recordOrphanedFile: recordOrphanedFile
                )
            }
        }
    }

    /// The caller holds the persistence mutation lock through the unlink so a
    /// new reference cannot appear between this generation check and cleanup.
    private static func canRemoveManagedFileLocked(
        kind: MemoryAttachmentKind,
        id: UUID,
        managedRef: String,
        libraryGeneration: UUID,
        in modelContext: ModelContext
    ) -> Bool {
        do {
            guard try ChekinanaLibraryGenerationStore.current(in: modelContext)
                    == libraryGeneration else {
                return false
            }
            let directory = try ChekiImageRefResolver.chekiImagesDirectory()
            let references = try ChekinanaLibraryFileReferenceSnapshot.capture(
                in: modelContext,
                directory: directory
            ).referencedFilenames
            guard !references.contains(managedRef) else { return false }
            if kind == .video {
                let thumbnail = ChekinanaGalleryMediaStore.thumbnailURL(
                    id: id,
                    directory: directory
                ).lastPathComponent
                guard !references.contains(thumbnail) else { return false }
            }
            return true
        } catch {
            return false
        }
    }

    private static func cleanupPersistedAttachments(
        _ attachments: [ChekinanaMemoryAttachmentRecordSnapshot],
        libraryGeneration: UUID,
        in modelContext: ModelContext,
        removeManagedFile: RemoveManagedFile,
        recordOrphanedFile: RecordOrphanedFile
    ) {
        for attachment in attachments {
            ChekinanaPersistenceMutationCoordinator.withLock {
                guard canRemoveManagedFileLocked(
                    kind: attachment.kind,
                    id: attachment.id,
                    managedRef: attachment.managedRef,
                    libraryGeneration: libraryGeneration,
                    in: modelContext
                ) else {
                    recordOrphanedFile(
                        attachment.kind,
                        attachment.id,
                        attachment.managedRef
                    )
                    return
                }
                cleanup(
                    kind: attachment.kind,
                    id: attachment.id,
                    managedRef: attachment.managedRef,
                    removeManagedFile: removeManagedFile,
                    recordOrphanedFile: recordOrphanedFile
                )
            }
        }
    }

    private static func cleanup(
        kind: MemoryAttachmentKind,
        id: UUID,
        managedRef: String,
        removeManagedFile: RemoveManagedFile,
        recordOrphanedFile: RecordOrphanedFile
    ) {
        do {
            try removeManagedFile(kind, id, managedRef)
        } catch {
            recordOrphanedFile(kind, id, managedRef)
        }
    }
}

@MainActor
private final class ChekinanaThumbnailDragSession {
    final class Ticket {
        let sourceID: UUID
        let initialOrder: [UUID]
        let restoreOrder: ([UUID]) -> Void
        var cleanup: (() -> Void)?
        let sourcePreviewTarget: () -> UIDragPreviewTarget?
        init(sourceID: UUID, initialOrder: [UUID], restoreOrder: @escaping ([UUID]) -> Void, sourcePreviewTarget: @escaping () -> UIDragPreviewTarget?) {
            self.sourceID = sourceID
            self.initialOrder = initialOrder
            self.restoreOrder = restoreOrder
            self.sourcePreviewTarget = sourcePreviewTarget
        }
    }
    private(set) var active: Ticket?
    func begin(_ sourceID: UUID, initialOrder: [UUID], restoreOrder: @escaping ([UUID]) -> Void, sourcePreviewTarget: @escaping () -> UIDragPreviewTarget? = { nil }) -> Ticket {
        cancel()
        let ticket = Ticket(sourceID: sourceID, initialOrder: initialOrder, restoreOrder: restoreOrder, sourcePreviewTarget: sourcePreviewTarget)
        active = ticket
        return ticket
    }
    func contains(_ ticket: Ticket) -> Bool { active === ticket }
    func commit(_ ticket: Ticket) {
        if active === ticket { active = nil; ticket.cleanup?(); ticket.cleanup = nil }
    }
    func cancel(sourceID: UUID? = nil) {
        guard let ticket = active, sourceID == nil || ticket.sourceID == sourceID else { return }
        active = nil
        ticket.cleanup?()
        ticket.cleanup = nil
        ticket.restoreOrder(ticket.initialOrder)
    }
    func cancel(_ ticket: Ticket) {
        if active === ticket { cancel() }
    }
}

private enum ChekinanaThumbnailOrder {
    static func crossesMidpoint(source: Int, target: Int, x: CGFloat, midpoint: CGFloat) -> Bool {
        source < target ? x > midpoint : (source > target && x < midpoint)
    }
    static func scrolledTarget(sourceID: UUID, order: [UUID], midpoints: [UUID: CGFloat], x: CGFloat) -> UUID? {
        guard let source = order.firstIndex(of: sourceID) else { return nil }
        return order.enumerated().compactMap { index, id -> (UUID, CGFloat)? in
            guard let midpoint = midpoints[id],
                  crossesMidpoint(source: source, target: index, x: x, midpoint: midpoint) else { return nil }
            return (id, abs(midpoint - x))
        }.min { $0.1 < $1.1 }?.0
    }

    static func restoring<Element: Identifiable>(_ items: [Element], to originalIDs: [UUID]) -> [Element] where Element.ID == UUID {
        let byID = Dictionary(items.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
        let originalSet = Set(originalIDs)
        return originalIDs.compactMap { byID[$0] } + items.filter { !originalSet.contains($0.id) }
    }
}

/// A real per-attachment UIKit interaction host, independent of Form's cell drag host.
private struct ChekinanaThumbnailRotationControl {
    let enabled: Bool
    let dimmed: Bool
    let value: String
    let action: () -> Void
}

private struct ChekinanaThumbnailReorderInteraction: UIViewRepresentable {
    let id: UUID
    let kind: MemoryAttachmentKind
    let image: ChekinanaRenderedImage?
    let unavailable: Bool
    var imageFrameSize: CGSize? = nil
    var identifierPrefix = "chekinana.memory.editor.attachment"
    var rotation: ChekinanaThumbnailRotationControl? = nil
    var deleteEnabled = true
    var deleteDimmed = false
    let dragSession: ChekinanaThumbnailDragSession
    let allowsReorder: (UUID) -> Bool
    let currentOrder: () -> [UUID]
    let restoreOrder: ([UUID]) -> Void
    let onPreview: (() -> Void)?
    let onRemove: () -> Void
    let onMove: (UUID, UUID) -> Void

    final class TileView: UIView {
        let content = UIButton(type: .custom)
        let imageView = UIImageView()
        let videoMark = UIImageView(image: UIImage(systemName: "play.fill"))
        let placeholder = UIActivityIndicatorView(style: .medium)
        let failure = UIImageView(image: UIImage(systemName: "exclamationmark.triangle"))
        let removeButton = UIButton(type: .system)
        let rotateButton = UIButton(type: .system)
        var imageFrameSize: CGSize?

        override init(frame: CGRect) {
            super.init(frame: frame)
            content.backgroundColor = .tertiarySystemGroupedBackground
            content.layer.cornerRadius = 12
            content.clipsToBounds = true
            addSubview(content)
            imageView.contentMode = .scaleAspectFill
            imageView.clipsToBounds = true
            content.addSubview(imageView)
            videoMark.tintColor = .white
            videoMark.layer.shadowColor = UIColor.black.cgColor
            videoMark.layer.shadowOpacity = 0.55
            videoMark.layer.shadowRadius = 3
            videoMark.layer.shadowOffset = .zero
            videoMark.contentMode = .scaleAspectFit
            content.addSubview(videoMark)
            content.addSubview(placeholder)
            failure.contentMode = .scaleAspectFit
            content.addSubview(failure)
            content.subviews.forEach { $0.isUserInteractionEnabled = false }
            removeButton.setImage(UIImage(systemName: "xmark", withConfiguration: UIImage.SymbolConfiguration(pointSize: UIFont.preferredFont(forTextStyle: .caption1).pointSize, weight: .bold)), for: .normal)
            removeButton.tintColor = .white
            removeButton.backgroundColor = .systemRed
            removeButton.layer.cornerRadius = 15
            addSubview(removeButton)
            rotateButton.setImage(UIImage(systemName: "rotate.left", withConfiguration: UIImage.SymbolConfiguration(pointSize: UIFont.preferredFont(forTextStyle: .caption1).pointSize, weight: .bold)), for: .normal)
            rotateButton.tintColor = .white
            rotateButton.backgroundColor = UIColor.black.withAlphaComponent(0.72)
            rotateButton.layer.cornerRadius = 15
            addSubview(rotateButton)

        }
        func setSourceLifted(_ lifted: Bool) {
            content.alpha = lifted ? 0 : 1
            removeButton.alpha = lifted ? 0 : (deleteIsDimmed ? 0.45 : 1)
            rotateButton.alpha = lifted ? 0 : (rotationIsDimmed ? 0.45 : 1)
        }
        var deleteIsDimmed = false
        var rotationIsDimmed = false
        required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }
        override func layoutSubviews() {
            super.layoutSubviews()
            content.frame = bounds
            let imageSize = imageFrameSize ?? content.bounds.size
            imageView.frame = CGRect(x: content.bounds.midX - imageSize.width / 2, y: content.bounds.midY - imageSize.height / 2, width: imageSize.width, height: imageSize.height)
            videoMark.frame = CGRect(x: bounds.midX - 11, y: bounds.midY - 11, width: 22, height: 22)
            placeholder.center = CGPoint(x: bounds.midX, y: bounds.midY)
            failure.frame = videoMark.frame
            removeButton.frame = CGRect(x: bounds.maxX - 32, y: bounds.minY + 2, width: 30, height: 30)
            rotateButton.frame = CGRect(x: bounds.minX + 2, y: bounds.minY + 2, width: 30, height: 30)
        }
    }

    func makeCoordinator() -> Coordinator { Coordinator(parent: self) }
    func makeUIView(context: Context) -> TileView {
        let view = TileView()
        context.coordinator.install(on: view)
        updateUIView(view, context: context)
        return view
    }
    func updateUIView(_ view: TileView, context: Context) {
        context.coordinator.parent = self
        view.isUserInteractionEnabled = context.environment.isEnabled
        view.imageView.image = image.map { UIImage(cgImage: $0.cgImage) }
        view.videoMark.isHidden = kind != .video
        view.failure.isHidden = !unavailable
        if image == nil && !unavailable { view.placeholder.startAnimating() }
        else { view.placeholder.stopAnimating() }
        view.imageFrameSize = imageFrameSize
        view.setNeedsLayout()
        view.rotateButton.isHidden = rotation == nil
        view.rotateButton.isEnabled = rotation?.enabled == true
        view.rotateButton.alpha = rotation?.dimmed == true ? 0.45 : 1
        view.rotateButton.accessibilityLabel = ChekinanaProductCopy.text("scan.input.rotate_counterclockwise", "Rotate input photo counterclockwise")
        view.rotateButton.accessibilityHint = ChekinanaProductCopy.text("scan.input.rotate_hint", "Rotates only this input photo counterclockwise.")
        view.rotateButton.accessibilityValue = rotation?.value
        view.rotateButton.accessibilityIdentifier = "chekinana.scan.input.rotate.\(id.uuidString.lowercased())"
        view.removeButton.isEnabled = deleteEnabled
        view.removeButton.alpha = deleteDimmed ? 0.45 : 1
        view.deleteIsDimmed = deleteDimmed
        view.rotationIsDimmed = rotation?.dimmed == true
        view.setSourceLifted(context.coordinator.isLifted && dragSession.active?.sourceID == id)
        view.content.isAccessibilityElement = onPreview != nil
        view.content.accessibilityTraits = onPreview == nil ? [] : .button
        view.content.accessibilityLabel = kind == .image
            ? ChekinanaProductCopy.text("memory.attachment.image", "Image")
            : ChekinanaProductCopy.text("memory.attachment.video", "Video")
        view.content.accessibilityIdentifier = "\(identifierPrefix).\(id.uuidString.lowercased())"
        view.removeButton.accessibilityLabel = ChekinanaProductCopy.text("common.delete", "Delete")
        if rotation != nil {
            view.accessibilityIdentifier = "\(identifierPrefix).\(id.uuidString.lowercased())"
            view.failure.isAccessibilityElement = unavailable
            view.failure.accessibilityLabel = ChekinanaProductCopy.text("scan.input.preview_unavailable", "Photo preview unavailable")
            view.removeButton.accessibilityLabel = ChekinanaProductCopy.text("scan.input.delete", "Delete input photo")
            view.removeButton.accessibilityHint = ChekinanaProductCopy.text("scan.input.delete_hint", "Removes only this photo from the scan inputs.")
            view.removeButton.accessibilityIdentifier = "chekinana.scan.input.delete.\(id.uuidString.lowercased())"
        }
    }
    static func dismantleUIView(_ view: TileView, coordinator: Coordinator) {
        coordinator.parent.dragSession.cancel(sourceID: coordinator.parent.id)
        view.interactions.forEach { view.removeInteraction($0) }
    }

    final class Coordinator: NSObject, UIDragInteractionDelegate, UIDropInteractionDelegate {
        private static let instances = NSHashTable<Coordinator>.weakObjects()
        var parent: ChekinanaThumbnailReorderInteraction
        private weak var view: TileView?
        private var dropTarget: UIDragPreviewTarget?
        private var previewBitmap: UIImage?
        private(set) var isLifted = false
        private weak var edgeScroll: UIScrollView?
        private var edgeSession: (any UIDragSession)?
        private var edgeLink: CADisplayLink?
        private var edgeLastTime: CFTimeInterval = 0
        private var edgeLastOffset: CGFloat = 0
        private var observedVelocity: CGFloat = 0
        private var ownsEdgeScroll = false
        private var originalScrollEnabled = true

        private func startEdgeTracking(_ session: any UIDragSession) {
            stopEdgeTracking()
            var ancestor = view?.superview
            while let current = ancestor {
                if let scroll = current as? UIScrollView, scroll.contentSize.width > scroll.bounds.width {
                    edgeScroll = scroll
                    originalScrollEnabled = scroll.isScrollEnabled
                    edgeLastOffset = scroll.contentOffset.x
                    edgeSession = session
                    let link = CADisplayLink(target: self, selector: #selector(edgeTick(_:)))
                    link.add(to: .main, forMode: .common)
                    edgeLink = link
                    return
                }
                ancestor = current.superview
            }
        }

        private func stopEdgeTracking() {
            edgeLink?.invalidate()
            edgeLink = nil
            if ownsEdgeScroll { edgeScroll?.isScrollEnabled = originalScrollEnabled }
            ownsEdgeScroll = false
            edgeScroll = nil
            edgeSession = nil
            edgeLastTime = 0
            observedVelocity = 0
        }

        private func synchronizeScrolledOrder(_ session: any UIDragSession, ticket: ChekinanaThumbnailDragSession.Ticket, scroll: UIScrollView) {
            guard parent.dragSession.contains(ticket) else { return }
            scroll.layoutIfNeeded()
            let viewport = scroll.bounds.inset(by: scroll.adjustedContentInset)
            let point = session.location(in: scroll)
            let x = min(viewport.maxX, max(viewport.minX, point.x))
            var targets: [UUID: Coordinator] = [:]
            var midpoints: [UUID: CGFloat] = [:]
            for target in Self.instances.allObjects {
                guard target.parent.dragSession === parent.dragSession,
                      target.parent.allowsReorder(target.parent.id),
                      let tile = target.view, tile.window === scroll.window,
                      tile.isDescendant(of: scroll), !tile.isHidden else { continue }
                let frame = tile.convert(tile.bounds, to: scroll)
                // Eagerly loaded offscreen tiles must not be skipped over in one
                // jump. Only a center that has scrolled into view can be passed.
                guard frame.midX >= viewport.minX, frame.midX <= viewport.maxX,
                      frame.maxY > viewport.minY, frame.minY < viewport.maxY else { continue }
                targets[target.parent.id] = target
                midpoints[target.parent.id] = frame.midX
            }
            guard let targetID = ChekinanaThumbnailOrder.scrolledTarget(
                sourceID: ticket.sourceID, order: parent.currentOrder(), midpoints: midpoints, x: x
            ), let target = targets[targetID], let tile = target.view else { return }
            let projected = scroll.convert(CGPoint(x: x, y: point.y), to: tile)
            target.previewMove(at: projected, ticket: ticket)
        }

        @objc private func edgeTick(_ link: CADisplayLink) {
            guard let scroll = edgeScroll, scroll.window != nil, let session = edgeSession,
                  let ticket = session.localContext as? ChekinanaThumbnailDragSession.Ticket,
                  parent.dragSession.contains(ticket), parent.allowsReorder(ticket.sourceID) else {
                stopEdgeTracking(); return
            }
            let elapsed = edgeLastTime == 0 ? 0 : link.timestamp - edgeLastTime
            edgeLastTime = link.timestamp
            let currentOffset = scroll.contentOffset.x
            defer { edgeLastOffset = scroll.contentOffset.x }
            guard elapsed > 0 else { return }
            let viewport = scroll.bounds.inset(by: scroll.adjustedContentInset)
            let point = session.location(in: scroll)
            let direction: CGFloat = point.x < viewport.minX ? -1 : (point.x > viewport.maxX ? 1 : 0)
            if direction == 0 {
                if ownsEdgeScroll {
                    scroll.isScrollEnabled = originalScrollEnabled
                    ownsEdgeScroll = false
                    observedVelocity = 0
                } else {
                    let velocity = (currentOffset - edgeLastOffset) / elapsed
                    if abs(velocity) > 1 { observedVelocity = velocity }
                }
                if currentOffset != edgeLastOffset { synchronizeScrolledOrder(session, ticket: ticket, scroll: scroll) }
                return
            }
            // Inside the viewport UIKit remains the sole owner. Outside, disable
            // its scroll handling before advancing the offset ourselves.
            if !ownsEdgeScroll {
                scroll.isScrollEnabled = false
                ownsEdgeScroll = true
            }
            let delta: CGFloat
            if observedVelocity * direction > 0 {
                delta = observedVelocity * min(elapsed, 1.0 / 15.0)
            } else {
                // Reuse the existing project's edge policy, transposed to X.
                delta = ChekinanaReorderEdgeScrollPolicy.delta(
                    point: CGPoint(x: 1, y: point.x),
                    viewport: CGRect(x: 0, y: viewport.minX, width: 2, height: viewport.width),
                    elapsed: elapsed
                )
            }
            let minimum = -scroll.adjustedContentInset.left
            let maximum = max(minimum, scroll.contentSize.width - scroll.bounds.width + scroll.adjustedContentInset.right)
            let next = min(maximum, max(minimum, currentOffset + delta))
            if next != currentOffset {
                scroll.setContentOffset(CGPoint(x: next, y: scroll.contentOffset.y), animated: false)
                scroll.layoutIfNeeded()
                synchronizeScrolledOrder(session, ticket: ticket, scroll: scroll)
            }
        }
        private var droppedTicket: ChekinanaThumbnailDragSession.Ticket?
        init(parent: ChekinanaThumbnailReorderInteraction) { self.parent = parent }
        func install(on view: TileView) {
            self.view = view
            Self.instances.add(self)
            let drag = UIDragInteraction(delegate: self)
            drag.isEnabled = true
            view.addInteraction(drag)
            view.addInteraction(UIDropInteraction(delegate: self))
            view.content.addTarget(self, action: #selector(preview), for: .touchUpInside)
            view.removeButton.addTarget(self, action: #selector(remove), for: .touchUpInside)
            view.rotateButton.addTarget(self, action: #selector(rotate), for: .touchUpInside)
        }
        @objc private func preview() { parent.onPreview?() }
        @objc private func rotate() { parent.rotation?.action() }
        @objc private func remove() { parent.onRemove() }
        func dragInteraction(_ interaction: UIDragInteraction, itemsForBeginning session: any UIDragSession) -> [UIDragItem] {
            guard let view, parent.allowsReorder(parent.id),
                  !view.removeButton.frame.contains(session.location(in: view)),
                  view.rotateButton.isHidden || !view.rotateButton.frame.contains(session.location(in: view)) else { return [] }
            let ticket = parent.dragSession.begin(parent.id, initialOrder: parent.currentOrder(), restoreOrder: parent.restoreOrder, sourcePreviewTarget: { [weak view] in
                guard let view, let window = view.window else { return nil }
                return UIDragPreviewTarget(container: window, center: view.convert(CGPoint(x: view.bounds.midX, y: view.bounds.midY), to: window))
            })
            previewBitmap = UIGraphicsImageRenderer(bounds: view.content.bounds).image { context in
                view.content.layer.render(in: context.cgContext)
            }
            ticket.cleanup = { [weak self, weak view] in
                self?.stopEdgeTracking()
                self?.isLifted = false
                view?.setSourceLifted(false)
            }
            let item = UIDragItem(itemProvider: NSItemProvider(object: parent.id.uuidString as NSString))
            item.localObject = ticket
            session.localContext = ticket
            return [item]
        }
        func dragInteraction(_ interaction: UIDragInteraction, sessionWillBegin session: any UIDragSession) {
            guard let ticket = session.localContext as? ChekinanaThumbnailDragSession.Ticket,
                  parent.dragSession.contains(ticket), ticket.sourceID == parent.id else { return }
            isLifted = true
            view?.setSourceLifted(true)
            startEdgeTracking(session)
        }
        func dragInteraction(_ interaction: UIDragInteraction, sessionIsRestrictedToDraggingApplication session: any UIDragSession) -> Bool { true }
        func dragInteraction(_ interaction: UIDragInteraction, previewForLifting item: UIDragItem, session: any UIDragSession) -> UITargetedDragPreview? { targetedPreview() }
        func dragInteraction(_ interaction: UIDragInteraction, previewForCancelling item: UIDragItem, withDefault defaultPreview: UITargetedDragPreview) -> UITargetedDragPreview? { targetedPreview() }
        func dragInteraction(_ interaction: UIDragInteraction, session: any UIDragSession, didEndWith operation: UIDropOperation) {
            if let ticket = session.localContext as? ChekinanaThumbnailDragSession.Ticket {
                parent.dragSession.cancel(ticket)
            }
        }
        private func targetedPreview() -> UITargetedDragPreview? {
            guard let view, view.window != nil else { return nil }
            let parameters = UIDragPreviewParameters()
            parameters.backgroundColor = .clear
            parameters.visiblePath = UIBezierPath(roundedRect: view.content.bounds, cornerRadius: 12)
            guard let bitmap = previewBitmap, let window = view.window else { return nil }
            let preview = UIImageView(image: bitmap)
            preview.bounds = view.content.bounds
            let target = UIDragPreviewTarget(container: window, center: view.content.convert(CGPoint(x: view.content.bounds.midX, y: view.content.bounds.midY), to: window))
            return UITargetedDragPreview(view: preview, parameters: parameters, target: target)
        }
        private func ticket(for session: any UIDropSession) -> ChekinanaThumbnailDragSession.Ticket? {
            guard session.items.count == 1,
                  let ticket = session.localDragSession?.localContext as? ChekinanaThumbnailDragSession.Ticket,
                  session.items.first?.localObject as? ChekinanaThumbnailDragSession.Ticket === ticket,
                  parent.dragSession.contains(ticket), parent.allowsReorder(ticket.sourceID),
                  parent.allowsReorder(parent.id) else { return nil }
            return ticket
        }
        @discardableResult
        private func previewMove(_ session: any UIDropSession, ticket: ChekinanaThumbnailDragSession.Ticket) -> Bool {
            guard let view else { return false }
            return previewMove(at: session.location(in: view), ticket: ticket)
        }
        @discardableResult
        private func previewMove(at point: CGPoint, ticket: ChekinanaThumbnailDragSession.Ticket) -> Bool {
            guard let view, parent.dragSession.contains(ticket),
                  parent.allowsReorder(ticket.sourceID), parent.allowsReorder(parent.id) else { return false }
            let order = parent.currentOrder()
            guard let source = order.firstIndex(of: ticket.sourceID),
                  let target = order.firstIndex(of: parent.id),
                  ChekinanaThumbnailOrder.crossesMidpoint(source: source, target: target, x: point.x, midpoint: view.bounds.midX) else { return false }
            parent.onMove(ticket.sourceID, parent.id)
            return parent.currentOrder().firstIndex(of: ticket.sourceID) != source
        }
        func dropInteraction(_ interaction: UIDropInteraction, canHandle session: any UIDropSession) -> Bool { ticket(for: session) != nil }
        func dropInteraction(_ interaction: UIDropInteraction, sessionDidUpdate session: any UIDropSession) -> UIDropProposal {
            guard let view, view.bounds.contains(session.location(in: view)),
                  ticket(for: session) != nil else { return UIDropProposal(operation: .cancel) }
            if let ticket = ticket(for: session) { previewMove(session, ticket: ticket) }
            return UIDropProposal(operation: .move)
        }
        func dropInteraction(_ interaction: UIDropInteraction, performDrop session: any UIDropSession) {
            guard let view, let window = view.window,
                  view.bounds.contains(session.location(in: view)),
                  let ticket = ticket(for: session) else { return }
            let targetSlot = UIDragPreviewTarget(
                container: window,
                center: view.convert(CGPoint(x: view.bounds.midX, y: view.bounds.midY), to: window)
            )
            // Crossing on release uses the target's old slot. Otherwise the source
            // already occupies its final slot, including any earlier hover moves.
            let movedOnDrop = previewMove(session, ticket: ticket)
            dropTarget = movedOnDrop ? targetSlot : ticket.sourcePreviewTarget()
            droppedTicket = ticket
            parent.dragSession.commit(ticket)
        }
        func dropInteraction(_ interaction: UIDropInteraction, previewForDropping item: UIDragItem, withDefault defaultPreview: UITargetedDragPreview) -> UITargetedDragPreview? {
            guard let dropTarget, let droppedTicket,
                  item.localObject as? ChekinanaThumbnailDragSession.Ticket === droppedTicket else { return nil }
            return defaultPreview.retargetedPreview(with: dropTarget)
        }
        func dropInteraction(_ interaction: UIDropInteraction, sessionDidEnd session: any UIDropSession) {
            dropTarget = nil
            droppedTicket = nil
        }
    }
}

private struct ChekinanaMemoryEditorAttachmentTile: View {
    let selection: ChekinanaMemoryAttachmentPreviewSelection?
    let kind: MemoryAttachmentKind
    let id: UUID
    let dragSession: ChekinanaThumbnailDragSession
    let allowsReorder: (UUID) -> Bool
    let currentOrder: () -> [UUID]
    let restoreOrder: ([UUID]) -> Void
    let onPreview: () -> Void
    let onRemove: () -> Void
    let onMove: (UUID, UUID) -> Void
    @State private var loadedImage: ChekinanaRenderedImage?

    var body: some View {
        ZStack {
            if let selection {
                // Load once using the existing thumbnail path; the UIKit host
                // displays this same CGImage and snapshots only its own content.
                ChekinanaMemoryAttachmentThumbnail(
                    selection: selection,
                    onImageLoaded: { loadedImage = $0 }
                )
                .hidden()
                .accessibilityHidden(true)
            }
            ChekinanaThumbnailReorderInteraction(
                id: id, kind: kind, image: loadedImage, unavailable: selection == nil,
                dragSession: dragSession, allowsReorder: allowsReorder,
                currentOrder: currentOrder, restoreOrder: restoreOrder,
                onPreview: onPreview, onRemove: onRemove, onMove: onMove
            )
        }
        .frame(width: 82, height: 82)
    }
}

private struct ChekinanaMemoryEditor: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query private var idols: [Idol]
    @Query private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @Query private var persistedAttachments: [MemoryAttachment]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared

    let memory: Memory?
    let onDeleted: (() -> Void)?
    @State private var title: String
    @State private var bodyText: String
    @State private var hasDate: Bool
    @State private var date: Date
    @State private var eventID: UUID?
    @State private var idolRelationshipDraft: ChekinanaMemoryIdolRelationshipDraft
    @State private var attachments: [ChekinanaMemoryAttachmentDraft] = []
    @State private var attachmentDragSession = ChekinanaThumbnailDragSession()
    @State private var mediaPickerItems: [PhotosPickerItem] = []
    @State private var isMediaPickerPresented = false
    @State private var isIdolPickerPresented = false
    @State private var isSaving = false
    @State private var isDeleting = false
    @State private var didFinish = false
    @State private var importGate = ChekinanaMemoryAttachmentImportGate()
    @State private var importTasks: [UUID: Task<Void, Never>] = [:]
    @State private var didLoadAttachments = false
    @State private var originalMemorySnapshot: ChekinanaMemoryRecordSnapshot?
    @State private var originalAttachmentSnapshots:
        [ChekinanaMemoryAttachmentRecordSnapshot] = []
    @State private var message: String?
    @State private var previewSelection: ChekinanaMemoryAttachmentPreviewSelection?

    init(memory: Memory?, onDeleted: (() -> Void)? = nil) {
        self.memory = memory
        self.onDeleted = onDeleted
        _title = State(initialValue: memory?.title ?? "")
        _bodyText = State(initialValue: memory?.bodyText ?? "")
        _hasDate = State(initialValue: memory?.date != nil)
        _date = State(initialValue: memory?.date ?? ChekinanaProductDate.fixtureAwareToday)
        _eventID = State(initialValue: memory?.eventID)
        _idolRelationshipDraft = State(initialValue: .init(
            initialIDs: memory?.idolIDs ?? []
        ))
        _originalMemorySnapshot = State(
            initialValue: memory.map(ChekinanaMemoryRecordSnapshot.init)
        )
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(idols.filter { !hiddenIdols.hiddenIDs.contains($0.id) })
    }

    private var draftCanonicalDate: Date? {
        guard hasDate else { return nil }
        return ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
    }

    private var currentPersistedIdolIDs: [UUID] {
        memory?.idolIDs ?? Array(idolRelationshipDraft.initialIDs)
    }

    private var selectedIdolIDs: Set<UUID> {
        idolRelationshipDraft.selectedIDs(
            currentPersistedIDs: currentPersistedIdolIDs
        )
    }

    private var resolvedIdolIDs: Set<UUID> {
        idolRelationshipDraft.resolvedIDs(
            currentPersistedIDs: currentPersistedIdolIDs,
            validIDs: Set(idols.map(\.id))
        )
    }

    private var visibleIdolSelection: Binding<Set<UUID>> {
        Binding(
            get: {
                idolRelationshipDraft.selectedVisibleIDs(
                    currentPersistedIDs: currentPersistedIdolIDs,
                    visibleIDs: Set(visibleIdols.map(\.id))
                )
            },
            set: { selection in
                guard !isSaving, !isDeleting else { return }
                var draft = idolRelationshipDraft
                draft.recordVisibleSelection(
                    selection,
                    visibleIDs: Set(visibleIdols.map(\.id)),
                    currentPersistedIDs: currentPersistedIdolIDs
                )
                idolRelationshipDraft = draft
            }
        )
    }

    private var canSave: Bool {
        ChekinanaMemoryPolicy.isValid(
            title: title,
            bodyText: bodyText,
            date: hasDate ? date : nil,
            eventID: eventID,
            idolIDs: Array(resolvedIdolIDs),
            attachmentCount: attachments.count
        ) && didLoadAttachments && !isSaving && !isDeleting
            && importGate.allowsSave
    }

    var body: some View {
        NavigationStack {
            Form {
                Section(ChekinanaProductCopy.text("memory.content", "Content")) {
                    TextField(ChekinanaProductCopy.text("memory.title", "Title"), text: $title)
                    TextEditor(text: $bodyText)
                        .frame(minHeight: 150)
                        .accessibilityLabel(ChekinanaProductCopy.text("memory.body", "Body"))
                        .accessibilityIdentifier("chekinana.memory.body")
                }
                Section(ChekinanaProductCopy.text("common.idols", "Idols")) {
                    ChekinanaIdolSelectionSummaryButton(
                        idols: visibleIdols.filter { selectedIdolIDs.contains($0.id) },
                        identifier: "chekinana.memory.change-idols"
                    ) { isIdolPickerPresented = true }
                }
                Section(ChekinanaProductCopy.text("memory.relationships", "Relationships")) {
                    Toggle(ChekinanaProductCopy.text("common.include_date", "Include date"), isOn: $hasDate)
                    if hasDate {
                        ChekinanaExpandableDateWheel(
                            ChekinanaProductCopy.text("common.date", "Date"),
                            selection: $date,
                            accessibilityIdentifier: "chekinana.memory.date"
                        )
                    }
                    ChekinanaChekiEventSelectionField(
                        eventID: $eventID,
                        recordDate: draftCanonicalDate,
                        events: events,
                        schedules: eventSchedules,
                        primaryScope: .exactDate
                    )
                }
                Section(ChekinanaProductCopy.text("memory.attachments", "Attachments")) {
                    if importGate.isImporting {
                        ProgressView()
                            .frame(maxWidth: .infinity, alignment: .center)
                    }
                    if !attachments.isEmpty {
                        ScrollView(.horizontal, showsIndicators: false) {
                            HStack(spacing: 10) {
                                ForEach(attachments, id: \.id) { attachment in
                                    attachmentThumbnail(attachment)
                                }
                            }
                        }
                        .frame(height: 88)
                    }
                    Button { isMediaPickerPresented = true } label: {
                        Label(ChekinanaProductCopy.text("memory.add.media", "Add images or videos"), systemImage: "photo.badge.plus")
                    }
                    .disabled(importGate.isImporting || importGate.isClosing)
                    .accessibilityIdentifier("chekinana.memory.add-media")
                }
                if memory != nil {
                    Section {
                        Button(role: .destructive) { Task { await deleteMemory() } } label: {
                            Text(ChekinanaProductCopy.text("memory.delete", "Delete Memory"))
                                .frame(maxWidth: .infinity)
                        }
                        .disabled(
                            isSaving || isDeleting || importGate.isImporting
                                || importGate.isClosing
                        )
                    }
                }
            }
            .disabled(isSaving || isDeleting)
            .navigationTitle(memory == nil
                ? ChekinanaProductCopy.text("memory.add", "Add Memory")
                : ChekinanaProductCopy.text("memory.edit", "Edit Memory"))
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        cancelAndDismiss()
                    }
                        .disabled(isSaving || isDeleting)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.save", "Save")) { Task { await save() } }
                        .disabled(!canSave)
                }
            }
        }
        .interactiveDismissDisabled(isSaving || isDeleting || importGate.isImporting || importGate.isClosing)
        .sheet(isPresented: $isIdolPickerPresented) {
            ChekinanaIdolAvatarCheckSelectionView(
                idols: visibleIdols,
                selectedIDs: visibleIdolSelection,
                identifierPrefix: "chekinana.memory.idols"
            )
            .disabled(isSaving || isDeleting)
        }
        .photosPicker(
            isPresented: $isMediaPickerPresented,
            selection: $mediaPickerItems,
            maxSelectionCount: 0,
            selectionBehavior: .ordered,
            matching: .any(of: [.images, .videos]),
            preferredItemEncoding: .current
        )
        .onChange(of: mediaPickerItems) { _, items in
            guard !items.isEmpty else { return }
            startMediaImport(items)
        }
        .onAppear { loadPersistedAttachmentsOnce() }
        .onDisappear {
            attachmentDragSession.cancel()
        }
        .fullScreenCover(item: $previewSelection) {
            ChekinanaMemoryAttachmentPreview(selection: $0, items: attachments.compactMap { preview(for: $0) })
        }
        .alert(ChekinanaProductCopy.text("memory.error", "Memory"), isPresented: Binding(
            get: { message != nil },
            set: { if !$0 { message = nil } }
        )) { Button(ChekinanaL10n.message("OK"), role: .cancel) {} } message: { Text(message ?? "") }
        .chekinanaSheetDraftDismiss(
            ready: didLoadAttachments,
            isBusy: { isSaving || isDeleting || importGate.isImporting || importGate.isClosing },
            snapshot: { [AnyHashable(title), AnyHashable(bodyText), AnyHashable(hasDate), AnyHashable(hasDate ? date : nil), AnyHashable(eventID), AnyHashable(resolvedIdolIDs)] + attachments.flatMap { [AnyHashable($0.id), AnyHashable($0.kind.rawValue), AnyHashable($0.existingReference), AnyHashable($0.stagedURL), AnyHashable($0.sortOrder)] } },
            onDiscard: { initial in cancelAndDismiss() },
            onDismissed: { cancelAndDismiss(dismissAfterCleanup: false) }
        )
    }

    private func attachmentThumbnail(_ attachment: ChekinanaMemoryAttachmentDraft) -> some View {
        ChekinanaMemoryEditorAttachmentTile(
            selection: preview(for: attachment),
            kind: attachment.kind,
            id: attachment.id,
            dragSession: attachmentDragSession,
            allowsReorder: { id in canReorderAttachments && attachments.contains { $0.id == id } },
            currentOrder: { attachments.map(\.id) },
            restoreOrder: { order in
                withAnimation {
                    attachments = ChekinanaThumbnailOrder.restoring(attachments, to: order)
                    for index in attachments.indices { attachments[index].sortOrder = index }
                }
            },
            onPreview: { previewSelection = preview(for: attachment) },
            onRemove: {
                if let currentIndex = attachments.firstIndex(where: { $0.id == attachment.id }) {
                    removeAttachment(at: currentIndex)
                }
            },
            onMove: { sourceID, targetID in
                withAnimation { moveAttachment(sourceID, to: targetID) }
            }
        )
    }

    private func loadPersistedAttachmentsOnce() {
        guard !didLoadAttachments else { return }
        guard let memory else {
            didLoadAttachments = true
            return
        }
        let persisted = persistedAttachments
            .filter { $0.memoryID == memory.id }
            .sorted { $0.sortOrder == $1.sortOrder
                ? $0.id.uuidString < $1.id.uuidString
                : $0.sortOrder < $1.sortOrder }
        attachments = persisted.map(ChekinanaMemoryAttachmentDraft.init)
        originalAttachmentSnapshots = persisted.map(
            ChekinanaMemoryAttachmentRecordSnapshot.init
        )
        didLoadAttachments = true
    }

    private var canReorderAttachments: Bool {
        !isSaving && !isDeleting && !didFinish && !importGate.isClosing && !importGate.isImporting
    }

    private func moveAttachment(_ sourceID: UUID, to targetID: UUID) {
        guard canReorderAttachments,
              let source = attachments.firstIndex(where: { $0.id == sourceID }),
              let target = attachments.firstIndex(where: { $0.id == targetID }), source != target else { return }
        let moved = attachments.remove(at: source)
        attachments.insert(moved, at: target)
        for position in attachments.indices { attachments[position].sortOrder = position }
    }

    private func removeAttachment(at index: Int) {
        guard !isSaving, !isDeleting, attachments.indices.contains(index) else {
            return
        }
        let removed = attachments.remove(at: index)
        attachmentDragSession.cancel(sourceID: removed.id)
        for position in attachments.indices { attachments[position].sortOrder = position }
        guard ChekinanaMemoryAttachmentLifecyclePolicy.removesStagedFileImmediately(
            existingReference: removed.existingReference,
            stagedURL: removed.stagedURL
        ) else { return }
        Task { await ChekinanaGalleryMediaStore.discardStagedImport(at: removed.stagedURL) }
    }

    private func cancelAndDismiss(dismissAfterCleanup: Bool = true) {
        guard !didFinish, !isSaving, !isDeleting, !importGate.isClosing else {
            return
        }
        importGate.close()
        let tasks = Array(importTasks.values)
        tasks.forEach { $0.cancel() }
        Task { @MainActor in
            for task in tasks { await task.value }
            discardNewStaging()
            didFinish = true
            if dismissAfterCleanup { dismiss() }
        }
    }

    private func preview(
        for attachment: ChekinanaMemoryAttachmentDraft
    ) -> ChekinanaMemoryAttachmentPreviewSelection? {
        let url = attachment.stagedURL ?? ChekinanaGalleryMediaStore.managedURL(
            for: attachment.existingReference,
            id: attachment.id,
            kind: attachment.kind == .image ? .shame : .douga
        )
        guard let url else { return nil }
        return .init(id: attachment.id, kind: attachment.kind, url: url)
    }

    private func startMediaImport(_ items: [PhotosPickerItem]) {
        guard !items.isEmpty, !isSaving, !isDeleting,
              !importGate.isImporting, !importGate.isClosing,
              let token = importGate.begin() else { return }
        mediaPickerItems = []
        let task = Task { @MainActor in
            for item in items {
                guard !Task.isCancelled, importGate.acceptsCompletion(token) else { break }
                if ChekinanaMemoryMediaSelectionPolicy.isVideo(item.supportedContentTypes) {
                    await appendVideo(item, token: token)
                } else {
                    await appendImage(item, token: token)
                }
            }
            importGate.finish(token)
            importTasks[token] = nil
            resumeDeferredPickerImports()
        }
        importTasks[token] = task
    }

    private func appendImage(_ item: PhotosPickerItem, token: UUID) async {
        var stagedURL: URL?
        do {
            guard let transfer = try await item.loadTransferable(
                type: ChekinanaGalleryImageTransfer.self
            ) else {
                throw ChekinanaGalleryMediaStoreError.invalidMedia
            }
            let url = transfer.stagedURL
            stagedURL = url
            guard !Task.isCancelled, importGate.acceptsCompletion(token) else {
                await ChekinanaGalleryMediaStore.discardStagedImport(at: url)
                return
            }
            attachments.append(.init(kind: .image, stagedURL: url, sortOrder: attachments.count))
            stagedURL = nil
        } catch {
            if let stagedURL {
                await ChekinanaGalleryMediaStore.discardStagedImport(at: stagedURL)
            }
            if !Task.isCancelled, importGate.acceptsCompletion(token) {
                message = error.localizedDescription
            }
        }
    }

    private func appendVideo(_ item: PhotosPickerItem, token: UUID) async {
        var stagedURL: URL?
        do {
            guard let transfer = try await item.loadTransferable(type: ChekinanaGalleryVideoTransfer.self) else {
                throw ChekinanaGalleryMediaStoreError.invalidMedia
            }
            stagedURL = transfer.stagedURL
            guard !Task.isCancelled, importGate.acceptsCompletion(token) else {
                await ChekinanaGalleryMediaStore.discardStagedImport(at: transfer.stagedURL)
                return
            }
            attachments.append(.init(kind: .video, stagedURL: transfer.stagedURL, sortOrder: attachments.count))
            stagedURL = nil
        } catch {
            if let stagedURL {
                await ChekinanaGalleryMediaStore.discardStagedImport(at: stagedURL)
            }
            if !Task.isCancelled, importGate.acceptsCompletion(token) {
                message = error.localizedDescription
            }
        }
    }

    @MainActor
    private func save() async {
        guard canSave, importGate.allowsSave else { return }
        let ownerID = UUID()
        guard importGate.beginSave(ownerID: ownerID) else { return }
        isSaving = true
        var succeeded = false
        defer {
            isSaving = false
            if !succeeded {
                importGate.finishSave(ownerID: ownerID)
                resumeDeferredPickerImports()
            }
        }
        do {
            let draft = try frozenSaveDraft()
            let expectedTarget = originalMemorySnapshot.map {
                ChekinanaMemoryTargetSnapshot(
                    record: $0,
                    attachments: originalAttachmentSnapshots
                )
            }
            _ = try await ChekinanaMemorySaveCommitter.save(
                draft: draft,
                expectedTarget: expectedTarget,
                ownerID: ownerID,
                targetID: expectedTarget?.record.id ?? UUID(),
                in: modelContext
            )
            succeeded = true
            importGate.close()
            didFinish = true
            discardStaging(in: draft.attachments)
            dismiss()
        } catch {
            message = localizedMemoryErrorMessage(error)
        }
    }

    private func frozenSaveDraft() throws -> ChekinanaMemorySaveDraft {
        let committedIdolIDs = idolOrdering.ordered(
            idols.filter { resolvedIdolIDs.contains($0.id) }
        ).map(\.id)
        let canonicalDate = try ChekinanaMemoryPolicy.validateContent(
            title: title,
            bodyText: bodyText,
            date: hasDate ? date : nil,
            eventID: eventID,
            idolIDs: committedIdolIDs,
            attachmentCount: attachments.count
        )
        return ChekinanaMemorySaveDraft(
            title: title,
            bodyText: bodyText,
            date: canonicalDate,
            eventID: eventID,
            idolIDs: committedIdolIDs,
            attachments: attachments.enumerated().map { index, attachment in
                ChekinanaMemorySaveAttachmentDraft(
                    id: attachment.id,
                    kind: attachment.kind,
                    existingReference: attachment.existingReference,
                    stagedURL: attachment.stagedURL,
                    sortOrder: index
                )
            }
        )
    }

    private func localizedMemoryErrorMessage(_ error: Error) -> String {
        guard let validationError = error as? ChekinanaMemoryValidationError else {
            return error.localizedDescription
        }
        switch validationError {
        case .empty:
            return ChekinanaProductCopy.text(
                "memory.validation.empty",
                "Memory must contain at least one value."
            )
        case .invalidDate:
            return ChekinanaProductCopy.text(
                "memory.validation.invalid_date",
                "The Memory date is outside the supported range."
            )
        case .invalidAttachment:
            return ChekinanaProductCopy.text(
                "memory.validation.invalid_attachment",
                "A Memory attachment is invalid."
            )
        }
    }

    @MainActor
    private func deleteMemory() async {
        guard let record = originalMemorySnapshot, didLoadAttachments else { return }
        let ownerID = UUID()
        guard importGate.beginSave(ownerID: ownerID) else { return }
        isDeleting = true
        var succeeded = false
        defer {
            isDeleting = false
            if !succeeded {
                importGate.finishSave(ownerID: ownerID)
                resumeDeferredPickerImports()
            }
        }
        do {
            try await ChekinanaMemorySaveCommitter.delete(
                expectedTarget: ChekinanaMemoryTargetSnapshot(
                    record: record,
                    attachments: originalAttachmentSnapshots
                ),
                in: modelContext
            )
            succeeded = true
            importGate.close()
            didFinish = true
            discardNewStaging()
            onDeleted?()
            dismiss()
        } catch {
            modelContext.rollback()
            message = error.localizedDescription
        }
    }

    private func resumeDeferredPickerImports() {
        if !mediaPickerItems.isEmpty { startMediaImport(mediaPickerItems) }
    }

    private func discardStaging(
        in drafts: [ChekinanaMemorySaveAttachmentDraft]
    ) {
        for draft in drafts where draft.stagedURL != nil {
            Task {
                await ChekinanaGalleryMediaStore.discardStagedImport(
                    at: draft.stagedURL
                )
            }
        }
    }

    private func discardNewStaging() {
        for draft in attachments where draft.stagedURL != nil {
            Task { await ChekinanaGalleryMediaStore.discardStagedImport(at: draft.stagedURL) }
        }
    }
}

private struct ChekinanaGalleryCompactFilterLabel: View {
    let title: String
    var subtitle: String? = nil
    let systemImage: String?
    var isSelected: Bool = false
    var isEnabled: Bool = true

    var body: some View {
        VStack(spacing: 1) {
            if let systemImage {
                Image(systemName: systemImage)
                    .font(.system(size: 13, weight: .semibold))
            }
            Text(title)
                .font(.system(size: 9, weight: .semibold))
                .lineLimit(1)
                .minimumScaleFactor(0.65)
            if let subtitle {
                Text(subtitle)
                    .font(.system(size: 7.5, weight: .medium))
                    .lineLimit(1)
                    .minimumScaleFactor(0.6)
            }
        }
        .foregroundStyle(
            isSelected ? ChekinanaProductTheme.accent : Color.primary
        )
        .opacity(isEnabled ? 1 : 0.38)
        .frame(
            maxWidth: .infinity,
            minHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget,
            maxHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget
        )
        .background(
            isSelected
                ? ChekinanaProductTheme.accent.opacity(0.14)
                : Color(uiColor: .secondarySystemGroupedBackground)
        )
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: 10, style: .continuous).stroke(
                isSelected
                    ? ChekinanaProductTheme.accent.opacity(0.45)
                    : ChekinanaProductTheme.border,
                lineWidth: 1
            )
        }
    }
}

private struct ChekinanaGalleryDateFilterView: View {
    @Environment(\.dismiss) private var dismiss
    @Binding var state: ChekinanaGalleryDateRangeState
    var onCancel: () -> Void = {}
    var onConfirm: () -> Void = {}
    @State private var resetRequested = false

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    ChekinanaExpandableDateWheel(
                        ChekinanaProductCopy.text(
                            "gallery.date_filter.start",
                            "Start date"
                        ),
                        selection: Binding(
                            get: { state.range.start },
                            set: { value in
                                resetRequested = false
                                var range = state.range
                                range.setStart(value)
                                state.applyUserRange(range, startWasEdited: true)
                            }
                        ),
                        accessibilityIdentifier: "chekinana.gallery.date-filter.start"
                    )
                    ChekinanaExpandableDateWheel(
                        ChekinanaProductCopy.text(
                            "gallery.date_filter.end",
                            "End date"
                        ),
                        selection: Binding(
                            get: { state.range.end },
                            set: {
                                resetRequested = false
                                var range = state.range
                                range.setEnd($0)
                                state.applyUserRange(range, startWasEdited: false)
                            }
                        ),
                        accessibilityIdentifier: "chekinana.gallery.date-filter.end"
                    )
                }
                Section {
                    Button(
                        ChekinanaProductCopy.text(
                            "gallery.date_filter.reset",
                            "Reset date range"
                        )
                    ) {
                        resetRequested = true
                        state.reset()
                    }
                    .accessibilityIdentifier("chekinana.gallery.date-filter.reset")
                }
            }
            .chekinanaGroupedPageBackground()
            .navigationTitle(
                ChekinanaProductCopy.text("gallery.date_filter", "Date range")
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        onCancel()
                        dismiss()
                    }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) {
                        if !resetRequested {
                            state.applyUserRange(state.range, startWasEdited: false)
                        }
                        onConfirm()
                        dismiss()
                    }
                    .accessibilityIdentifier("chekinana.gallery.date-filter.done")
                }
            }
        }
        .chekinanaSheetDraftDismiss(
            snapshot: { [AnyHashable(state.range.start), AnyHashable(state.range.end), AnyHashable(state.isActive), AnyHashable(state.didManuallyEditStart)] },
            onDiscard: { initial in onCancel(); dismiss() }
        )
    }
}

enum ChekinanaGalleryIdolFilterPolicy {
    static func includes(idolIDs: [UUID], selectedIDs: Set<UUID>, unassignedOnly: Bool) -> Bool {
        if selectedIDs.isEmpty && !unassignedOnly { return true }
        return (unassignedOnly && idolIDs.isEmpty) || !selectedIDs.isDisjoint(with: idolIDs)
    }

    static func toggleIdol(_ id: UUID, selectedIDs: inout Set<UUID>, unassignedOnly: Bool) {
        if !selectedIDs.insert(id).inserted { selectedIDs.remove(id) }
    }

    static func toggleUnassigned(selectedIDs: Set<UUID>, unassignedOnly: inout Bool) {
        unassignedOnly.toggle()
    }
}

private struct ChekinanaGalleryIdolFilterPicker: View {
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Environment(\.dismiss) private var dismiss
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" })
    private var mediaChekis: [MediaItem]
    @Query private var simpleRecords: [ChekiRecord]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let idols: [Idol]
    let showsUnassigned: Bool
    @Binding var selectedIDs: Set<UUID>
    @Binding var unassignedOnly: Bool
    var onConfirm: () -> Void = {}

    private var orderedIdols: [Idol] {
        ChekinanaIdolSelectionOrdering.ordered(
            idols,
            mediaChekis: mediaChekis,
            simpleRecords: simpleRecords,
            hiddenIDs: hiddenIdols.hiddenIDs,
            preferredID: idolOrdering.preferredID
        )
    }

    var body: some View {
        NavigationStack {
            ChekinanaIdolPickerContent(
                options: orderedIdols.map(ChekinanaIdolSelectionOption.init),
                selectedIDs: $selectedIDs,
                identifierPrefix: "chekinana.gallery.idol-filter",
                showsUnassigned: showsUnassigned,
                unassignedSelection: $unassignedOnly
            )
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaL10n.message("Done")) {
                        onConfirm()
                        dismiss()
                    }
                        .accessibilityIdentifier("chekinana.gallery.idol-filter.done")
                }
            }
        }
        .chekinanaSheetDraftDismiss(
            snapshot: { [AnyHashable(selectedIDs), AnyHashable(unassignedOnly)] },
            onDiscard: { initial in if let value = initial[0].base as? Set<UUID> { selectedIDs = value }; if let value = initial[1].base as? Bool { unassignedOnly = value }; dismiss() }
        )
    }


}

private struct ChekinanaGalleryCard: View {
    let item: ChekinanaGalleryItem
    let showsIdolAvatars: Bool
    let avatarMaximumDiameter: CGFloat
    @ObservedObject private var thumbnailRevisions =
        ChekinanaThumbnailRevisionStore.shared
    @State private var image: ChekinanaRenderedImage?

    init(
        item: ChekinanaGalleryItem,
        showsIdolAvatars: Bool = true,
        avatarMaximumDiameter: CGFloat =
            ChekinanaGalleryGridSizePolicy.defaultAvatarDiameter
    ) {
        self.item = item
        self.showsIdolAvatars = showsIdolAvatars
        self.avatarMaximumDiameter = avatarMaximumDiameter
    }

    init(cheki: MediaItem) {
        item = .cheki(cheki)
        showsIdolAvatars = true
        avatarMaximumDiameter =
            ChekinanaGalleryGridSizePolicy.defaultAvatarDiameter
    }

    private var imageReference: String? {
        switch item {
        case .cheki(let value): value.imageRef
        case .shame(let value): value.imageRef
        case .douga(let value):
            ChekinanaGalleryMediaStore.thumbnailReference(id: value.mediaOwnerID)
        }
    }

    private var aspectRatio: CGFloat {
        return ChekinanaGalleryMediaAspectRatio.value(for: item)
    }

    private var imageLoadIdentity: ChekinanaThumbnailLoadIdentity {
        thumbnailRevisions.identity(
            imageRef: imageReference,
            sourceKey: "product-gallery-\(item.id)"
        )
    }

    var body: some View {
        GeometryReader { geometry in
            ZStack {
                Color(uiColor: .tertiarySystemGroupedBackground)
                if let image {
                    if item.kind == .cheki {
                        ChekinanaFixedChekiThumbnailImage(image: image)
                    } else {
                        Image(decorative: image.cgImage, scale: 1)
                            .resizable()
                            .scaledToFill()
                    }
                }
            }
            .frame(width: geometry.size.width, height: geometry.size.height)
            .clipped()
            .overlay(alignment: .bottomLeading) {
                if showsIdolAvatars, !item.idols.isEmpty {
                    ChekinanaGalleryOverlayAvatars(
                        idols: item.idols,
                        maximumDiameter: avatarMaximumDiameter
                    )
                        .padding(6)
                }
            }
        }
        .aspectRatio(aspectRatio, contentMode: .fit)
        .task(id: imageLoadIdentity) {
            image = nil
            image = await ChekinanaThumbnailCache.shared.thumbnailImage(
                forManagedImageRef: imageReference,
                key: "product-gallery-\(item.id)",
                maxDimension: 720
            )
        }
    }
}

