enum ChekinanaGalleryDeleteDismissPolicy {
    static func canDismiss(
        pendingConfirmationCode: String?,
        recoveryRequired: Bool
    ) -> Bool {
        pendingConfirmationCode == nil || !recoveryRequired
    }
}

enum ChekinanaChekiViewerRoutingPolicy {
    static func initialID(requested: UUID?, available: [UUID]) -> UUID? {
        ChekinanaMediaPagerPolicy.initialID(
            requested: requested,
            available: available
        )
    }
}

enum ChekinanaMediaPagerPolicy {
    static let previewMaximumPixelDimension = 2_048
    static let previewCacheEntryLimit = 4
    static let projectedSwitchFraction: CGFloat = 0.35
    static let minimumProjectedGainFraction: CGFloat = 0.12

    static func initialID(requested: UUID?, available: [UUID]) -> UUID? {
        guard !available.isEmpty else { return nil }
        if let requested, available.contains(requested) { return requested }
        return available.first
    }

    /// Only the current page and its immediate neighbours are materialized.
    /// This keeps large image decode work and GPU textures bounded regardless
    /// of the number of MediaItems in the viewer's paging scope.
    static func renderedIndices(selectedIndex: Int, itemCount: Int) -> [Int] {
        guard itemCount > 0, (0..<itemCount).contains(selectedIndex) else {
            return []
        }
        return [selectedIndex, selectedIndex - 1, selectedIndex + 1]
            .filter { (0..<itemCount).contains($0) }
    }

    /// A page changes only after the horizontal drag strictly exceeds half of
    /// the visible canvas. Positive translation requests the previous page.
    static func pageStep(
        horizontalTranslation: CGFloat,
        canvasWidth: CGFloat
    ) -> Int? {
        guard horizontalTranslation.isFinite,
              canvasWidth.isFinite,
              canvasWidth > 0,
              abs(horizontalTranslation) > canvasWidth / 2 else {
            return nil
        }
        return horizontalTranslation > 0 ? -1 : 1
    }

    /// Keeps the exact half-canvas distance rule while allowing a short,
    /// decisive flick to use the system-projected resting translation.
    static func pageStep(
        release: ChekinanaMediaPagerDragRelease,
        canvasWidth: CGFloat
    ) -> Int? {
        if let distanceStep = pageStep(
            horizontalTranslation: release.translation,
            canvasWidth: canvasWidth
        ) {
            return distanceStep
        }
        guard release.translation.isFinite,
              release.predictedEndTranslation.isFinite,
              canvasWidth.isFinite,
              canvasWidth > 0 else { return nil }

        let actual = release.translation
        let projected = release.predictedEndTranslation
        let hasCompatibleDirection = abs(actual) < 1
            || (actual > 0) == (projected > 0)
        let projectedDistance = abs(projected)
        let projectedGain = projectedDistance - abs(actual)
        guard hasCompatibleDirection,
              projectedDistance > canvasWidth * projectedSwitchFraction,
              projectedGain > canvasWidth * minimumProjectedGainFraction else {
            return nil
        }
        return projected > 0 ? -1 : 1
    }

    static func targetIndex(
        currentIndex: Int,
        itemCount: Int,
        horizontalTranslation: CGFloat,
        canvasWidth: CGFloat
    ) -> Int {
        guard itemCount > 0,
              (0..<itemCount).contains(currentIndex),
              let step = pageStep(
                horizontalTranslation: horizontalTranslation,
                canvasWidth: canvasWidth
              ) else {
            return currentIndex
        }
        return min(itemCount - 1, max(0, currentIndex + step))
    }

    static func targetIndex(
        currentIndex: Int,
        itemCount: Int,
        release: ChekinanaMediaPagerDragRelease,
        canvasWidth: CGFloat
    ) -> Int {
        guard itemCount > 0,
              (0..<itemCount).contains(currentIndex),
              let step = pageStep(
                release: release,
                canvasWidth: canvasWidth
              ) else {
            return currentIndex
        }
        return min(itemCount - 1, max(0, currentIndex + step))
    }

    /// SwiftUI spring velocity is normalized to the remaining displacement.
    /// Positive values preserve flick momentum into a page transition; a
    /// below-threshold release uses a small opposing value for natural return.
    static func settlingInitialVelocity(
        release: ChekinanaMediaPagerDragRelease,
        canvasWidth: CGFloat,
        changesPage: Bool
    ) -> CGFloat {
        guard release.translation.isFinite,
              release.predictedEndTranslation.isFinite,
              canvasWidth.isFinite,
              canvasWidth > 0 else { return 0 }
        let gain = max(
            0,
            abs(release.predictedEndTranslation) - abs(release.translation)
        )
        guard gain > 0 else { return 0 }
        let remaining = changesPage
            ? max(1, canvasWidth - abs(release.translation))
            : max(1, abs(release.translation))
        let magnitude = min(3.5, gain / remaining)
        return changesPage ? magnitude : -magnitude
    }

    static func interactiveTranslation(
        horizontalTranslation: CGFloat,
        currentIndex: Int,
        itemCount: Int
    ) -> CGFloat {
        guard horizontalTranslation.isFinite,
              itemCount > 0,
              (0..<itemCount).contains(currentIndex) else {
            return 0
        }
        let isDraggingPastStart = currentIndex == 0
            && horizontalTranslation > 0
        let isDraggingPastEnd = currentIndex == itemCount - 1
            && horizontalTranslation < 0
        return (isDraggingPastStart || isDraggingPastEnd)
            ? horizontalTranslation / 3
            : horizontalTranslation
    }
}

struct ChekinanaMediaPagerDragRelease: Equatable {
    let translation: CGFloat
    let predictedEndTranslation: CGFloat
}

private struct ChekinanaMediaPreviewCacheKey: Hashable, Sendable {
    let identity: ChekinanaThumbnailLoadIdentity
    let maximumPixelDimension: Int
}

/// A deliberately small cache for full-screen previews. It coalesces the
/// current/adjacent page requests without turning the thumbnail cache into an
/// unbounded store of multi-megapixel images. Original media files are never
/// modified or replaced by these display-only images.
private actor ChekinanaMediaPreviewCache {
    static let shared = ChekinanaMediaPreviewCache()

    private var entries: [ChekinanaMediaPreviewCacheKey: ChekinanaRenderedImage] = [:]
    private var accessOrder: [ChekinanaMediaPreviewCacheKey] = []
    private var inFlight: [
        ChekinanaMediaPreviewCacheKey: Task<ChekinanaRenderedImage?, Never>
    ] = [:]

    func image(
        identity: ChekinanaThumbnailLoadIdentity,
        imageReference: String
    ) async -> ChekinanaRenderedImage? {
        let key = ChekinanaMediaPreviewCacheKey(
            identity: identity,
            maximumPixelDimension: ChekinanaMediaPagerPolicy
                .previewMaximumPixelDimension
        )
        if let cached = entries[key] {
            touch(key)
            return cached
        }
        if let task = inFlight[key] {
            return await task.value
        }

        let maximumPixelDimension = key.maximumPixelDimension
        let task = Task<ChekinanaRenderedImage?, Never> {
            await ChekinanaImageWorker.previewImage(
                fromImageRef: imageReference,
                maxDimension: maximumPixelDimension
            )
        }
        inFlight[key] = task
        let image = await task.value
        inFlight[key] = nil
        if let image {
            entries[key] = image
            touch(key)
            while accessOrder.count
                > ChekinanaMediaPagerPolicy.previewCacheEntryLimit,
                let oldest = accessOrder.first {
                accessOrder.removeFirst()
                entries[oldest] = nil
            }
        }
        return image
    }

    private func touch(_ key: ChekinanaMediaPreviewCacheKey) {
        accessOrder.removeAll { $0 == key }
        accessOrder.append(key)
    }
}

private struct ChekinanaPassivePageIndicator: UIViewRepresentable {
    let currentPage: Int
    let numberOfPages: Int

    func makeUIView(context: Context) -> UIPageControl {
        let control = UIPageControl()
        control.isUserInteractionEnabled = false
        control.backgroundStyle = .minimal
        return control
    }

    func updateUIView(_ control: UIPageControl, context: Context) {
        control.currentPage = currentPage
        control.numberOfPages = numberOfPages
        control.isHidden = numberOfPages <= 1
    }
}

private struct ChekinanaMediaPagerPageInteraction {
    let translation: CGFloat
    let dragChanged: (CGFloat) -> Void
    let dragEnded: (ChekinanaMediaPagerDragRelease) -> Bool
}

private struct ChekinanaFullScreenMediaPager<Item: Identifiable, Page: View>: View
where Item.ID == UUID {
    let items: [Item]
    @Binding var selectedID: UUID?
    let usesEmbeddedPagingGesture: Bool
    let showsPageIndicator: Bool
    @ViewBuilder let page: (
        Item,
        Int,
        ChekinanaMediaPagerPageInteraction
    ) -> Page
    @State private var pageDrag: CGFloat = 0
    @State private var dragLifecycle = ChekinanaMediaDragLifecycle()
    @GestureState private var directDragIsActive = false

    private let indexByID: [UUID: Int]

    init(items: [Item], selectedID: Binding<UUID?>,
         usesEmbeddedPagingGesture: Bool, showsPageIndicator: Bool,
         @ViewBuilder page: @escaping (Item, Int, ChekinanaMediaPagerPageInteraction) -> Page) {
        self.items = items
        self._selectedID = selectedID
        self.usesEmbeddedPagingGesture = usesEmbeddedPagingGesture
        self.showsPageIndicator = showsPageIndicator
        self.page = page
        var positions: [UUID: Int] = [:]
        for (index, item) in items.enumerated() where positions[item.id] == nil {
            positions[item.id] = index
        }
        self.indexByID = positions
    }

    var body: some View {
        GeometryReader { geometry in
            let selectedIndex = selectedID.flatMap { indexByID[$0] } ?? 0
            let visibleIndices = ChekinanaMediaPagerPolicy.renderedIndices(
                selectedIndex: selectedIndex,
                itemCount: items.count
            )
            let pageInteraction = ChekinanaMediaPagerPageInteraction(
                translation: pageDrag,
                dragChanged: { translation in
                    updatePageDrag(
                        translation,
                        selectedIndex: selectedIndex
                    )
                },
                dragEnded: { release in
                    finishPageDrag(
                        release,
                        canvasWidth: geometry.size.width,
                        selectedIndex: selectedIndex
                    )
                }
            )

            let pages = ZStack {
                ForEach(visibleIndices, id: \.self) { index in
                    page(items[index], index, pageInteraction)
                        .frame(
                            width: geometry.size.width,
                            height: geometry.size.height
                        )
                        .offset(
                            x: CGFloat(index - selectedIndex)
                                * geometry.size.width + pageDrag
                        )
                        .zIndex(index == selectedIndex ? 1 : 0)
                }
            }
            .frame(width: geometry.size.width, height: geometry.size.height)
            .contentShape(Rectangle())
            .clipped()

            pagingSurface(
                pages,
                canvasWidth: geometry.size.width,
                selectedIndex: selectedIndex
            )
            .overlay(alignment: .bottom) {
                if showsPageIndicator {
                    ChekinanaPassivePageIndicator(
                        currentPage: selectedIndex,
                        numberOfPages: items.count
                    )
                    .frame(height: 20)
                    .padding(.bottom, 8)
                    .allowsHitTesting(false)
                }
            }
        }
        .onChange(of: selectedID) { _, _ in resetPageDrag() }
        .onChange(of: directDragIsActive) { _, active in
            if !active, dragLifecycle.cancel() { pageDrag = 0 }
        }
        .onDisappear { resetPageDrag() }
        .accessibilityIdentifier("chekinana.media.viewer.pager")
    }

    @ViewBuilder
    private func pagingSurface<Surface: View>(
        _ surface: Surface,
        canvasWidth: CGFloat,
        selectedIndex: Int
    ) -> some View {
        if usesEmbeddedPagingGesture {
            surface
        } else {
            surface.gesture(
                pageGesture(
                    canvasWidth: canvasWidth,
                    selectedIndex: selectedIndex
                )
            )
        }
    }

    private func pageGesture(
        canvasWidth: CGFloat,
        selectedIndex: Int
    ) -> some Gesture {
        DragGesture(minimumDistance: 8, coordinateSpace: .global)
            .updating($directDragIsActive) { _, state, _ in
                state = true
            }
            .onChanged { value in
                dragLifecycle.changed()
                updatePageDrag(
                    value.translation.width,
                    selectedIndex: selectedIndex
                )
            }
            .onEnded { value in
                dragLifecycle.finish()
                _ = finishPageDrag(
                    ChekinanaMediaPagerDragRelease(
                        translation: value.translation.width,
                        predictedEndTranslation: value.predictedEndTranslation.width
                    ),
                    canvasWidth: canvasWidth,
                    selectedIndex: selectedIndex
                )
            }
    }

    private func updatePageDrag(
        _ translation: CGFloat,
        selectedIndex: Int
    ) {
        pageDrag = ChekinanaMediaPagerPolicy.interactiveTranslation(
            horizontalTranslation: translation,
            currentIndex: selectedIndex,
            itemCount: items.count
        )
    }

    @discardableResult
    private func finishPageDrag(
        _ release: ChekinanaMediaPagerDragRelease,
        canvasWidth: CGFloat,
        selectedIndex: Int
    ) -> Bool {
        let targetIndex = ChekinanaMediaPagerPolicy.targetIndex(
            currentIndex: selectedIndex,
            itemCount: items.count,
            release: release,
            canvasWidth: canvasWidth
        )
        let changesPage = targetIndex != selectedIndex
        let initialVelocity = ChekinanaMediaPagerPolicy.settlingInitialVelocity(
            release: release,
            canvasWidth: canvasWidth,
            changesPage: changesPage
        )
        withAnimation(
            .interpolatingSpring(
                mass: 1,
                stiffness: 225,
                damping: 29,
                initialVelocity: initialVelocity
            )
        ) {
            pageDrag = 0
            if items.indices.contains(targetIndex) {
                selectedID = items[targetIndex].id
            }
        }
        return changesPage
    }

    private func resetPageDrag() {
        dragLifecycle.finish()
        pageDrag = 0
    }
}

private struct ChekinanaMediaViewerPageChrome<
    MediaContent: View,
    FooterContent: View
>: View {
    @Environment(\.chekinanaDisplayHiddenIdolIDs) private var hiddenDisplayIDs
    let idols: [Idol]
    let date: Date?
    let centerTitle: String?
    let pageLabel: String?
    let backgroundColor: Color
    let foregroundColor: Color
    let controlBackgroundColor: Color
    let closeDisabled: Bool
    let closeIdentifier: String
    let headerIdentifier: String
    let onClose: () -> Void
    @ViewBuilder let mediaContent: () -> MediaContent
    @ViewBuilder let footerContent: () -> FooterContent

    var body: some View {
        ZStack {
            backgroundColor.ignoresSafeArea()
            VStack(spacing: 0) {
                ZStack(alignment: .top) {
                    HStack(alignment: .top) {
                        VStack(alignment: .leading, spacing: 3) {
                            ChekinanaIdolAvatarRow(
                                idols: idols.filter { !hiddenDisplayIDs.contains($0.id) },
                                size: 34,
                                showsNames: false
                            )
                            Text(ChekinanaProductDate.displayString(date))
                                .font(.caption)
                                .foregroundStyle(.secondary)
                        }
                        Spacer()
                        Button(action: onClose) {
                            Image(systemName: "xmark")
                                .font(.headline)
                                .foregroundStyle(foregroundColor)
                                .frame(width: 44, height: 44)
                                .background(controlBackgroundColor)
                                .clipShape(Circle())
                        }
                        .buttonStyle(.plain)
                        .disabled(closeDisabled)
                        .accessibilityLabel(
                            ChekinanaProductCopy.text("common.close", "Close")
                        )
                        .accessibilityIdentifier(closeIdentifier)
                    }

                    VStack(spacing: 3) {
                        if let centerTitle = centerTitle?.nonEmpty {
                            Text(centerTitle)
                                .font(.headline)
                                .lineLimit(1)
                        }
                        if let pageLabel {
                            Text(pageLabel)
                                .font(.caption.monospacedDigit())
                                .foregroundStyle(.secondary)
                        }
                    }
                    .padding(.horizontal, 140)
                    .padding(.top, 8)
                }
                .padding(.horizontal, 16)
                .padding(.vertical, 8)
                .foregroundStyle(foregroundColor)
                .accessibilityIdentifier(headerIdentifier)

                mediaContent()
                    .frame(maxWidth: .infinity, maxHeight: .infinity)

                footerContent()
            }
        }
    }
}

enum ChekinanaGalleryVideoInteractionPolicy {
    struct State: Equatable {
        var isPlaying = false
        var isEditing = false
    }

    enum Action {
        case togglePlayback
        case openEditor
        case tapVideo
        case pageBecameInactive
        case viewDisappeared
        case playbackEnded
    }

    enum PlaybackEffect: Equatable {
        case play
        case pause
        case pauseAndRewind
    }

    struct Transition: Equatable {
        let state: State
        let playbackEffect: PlaybackEffect
    }

    static func reduce(state: State, action: Action) -> Transition {
        var next = state
        let effect: PlaybackEffect
        switch action {
        case .togglePlayback:
            next.isPlaying.toggle()
            effect = next.isPlaying ? .play : .pause
        case .tapVideo:
            next.isPlaying = false
            next.isEditing = !state.isPlaying
            effect = .pause
        case .openEditor:
            next.isPlaying = false
            next.isEditing = true
            effect = .pause
        case .pageBecameInactive, .viewDisappeared:
            next.isPlaying = false
            effect = .pause
        case .playbackEnded:
            next.isPlaying = false
            effect = .pauseAndRewind
        }
        return Transition(state: next, playbackEffect: effect)
    }
}

enum ChekinanaChekiViewerAppearance: Equatable {
    case standard
    case calendar

    var backgroundColor: Color {
        ChekinanaProductTheme.pageBackground
    }

    var foregroundColor: Color {
        .primary
    }

    var controlBackgroundColor: Color {
        Color(uiColor: .secondarySystemGroupedBackground)
    }

    var preferredColorScheme: ColorScheme? {
        nil
    }
}

