private struct ChekinanaChekiImageViewer: View {
    @Environment(\.dismiss) private var dismiss
    let chekis: [MediaItem]
    let initialID: UUID?
    let onClose: (() -> Void)?
    let appearance: ChekinanaChekiViewerAppearance
    let title: String?
    @State private var visibleID: UUID?
    @State private var editingCheki: MediaItem?

    init(
        chekis: [MediaItem],
        initialID: UUID? = nil,
        onClose: (() -> Void)? = nil,
        appearance: ChekinanaChekiViewerAppearance = .standard,
        title: String? = nil
    ) {
        let media = chekis.filter { $0.imageRef?.nonEmpty != nil }
        self.chekis = media
        self.initialID = initialID
        self.onClose = onClose
        self.appearance = appearance
        self.title = title
        _visibleID = State(initialValue: ChekinanaChekiViewerRoutingPolicy.initialID(
            requested: initialID,
            available: media.map(\.id)
        ))
    }

    var body: some View {
        ZStack(alignment: .topTrailing) {
            appearance.backgroundColor.ignoresSafeArea()
            if chekis.isEmpty {
                Image(systemName: "photo.slash")
                    .font(.largeTitle)
                    .foregroundStyle(.secondary)
                Button(action: close) {
                    Image(systemName: "xmark")
                        .font(.headline)
                        .foregroundStyle(appearance.foregroundColor)
                        .frame(width: 44, height: 44)
                        .background(appearance.controlBackgroundColor)
                        .clipShape(Circle())
                }
                .buttonStyle(.plain)
                .padding(16)
                .accessibilityLabel(
                    ChekinanaProductCopy.text("common.close", "Close")
                )
                .accessibilityIdentifier("chekinana.cheki.viewer.close")
            } else {
                ChekinanaFullScreenMediaPager(
                    items: chekis,
                    selectedID: $visibleID,
                    usesEmbeddedPagingGesture: true,
                    showsPageIndicator: false
                ) { cheki, index, pageInteraction in
                    ChekinanaChekiViewerPage(
                        cheki: cheki,
                        isActive: visibleID == cheki.id,
                        pageNumber: index + 1,
                        pageCount: chekis.count,
                        title: appearance == .calendar ? title : nil,
                        onClose: close,
                        pageTranslation: pageInteraction.translation,
                        onHorizontalDragChanged: pageInteraction.dragChanged,
                        onHorizontalDragEnded: pageInteraction.dragEnded,
                        onTap: { editingCheki = cheki },
                        appearance: appearance
                    )
                    .accessibilityAddTraits(.isButton)
                    .accessibilityAction { editingCheki = cheki }
                    .accessibilityHint(
                        ChekinanaProductCopy.text(
                            "gallery.viewer.edit_hint",
                            "Tap to edit this Cheki"
                        )
                    )
                    .accessibilityIdentifier(
                        "chekinana.cheki.viewer.page.\(cheki.id.uuidString.lowercased())"
                    )
                }
            }
        }
        .preferredColorScheme(appearance.preferredColorScheme)
        .toolbar(.hidden, for: .navigationBar)
        .sheet(item: $editingCheki) { cheki in
            ChekinanaChekiEditorView(
                cheki: cheki,
                allowsDelete: true,
                onDelete: close
            )
        }
        .onChange(of: chekis.map(\.id)) { _, ids in
            visibleID = ChekinanaChekiViewerRoutingPolicy.initialID(
                requested: visibleID ?? initialID,
                available: ids
            )
            if ids.isEmpty { close() }
        }
        .chekinanaScreenMarker("chekinana.cheki.viewer")
    }

    private func close() {
        if let onClose { onClose() } else { dismiss() }
    }

}

enum ChekinanaViewerRefitFileStore {
    struct Stamp: Equatable, Sendable {
        let size: UInt64
        let modified: Date
        let inode: UInt64
    }
    struct Source: Sendable {
        let url: URL
        let data: Data
        let stamp: Stamp
    }
    struct Prepared: Sendable {
        let temporaryURL: URL
        let source: Source
    }
    enum Failure: LocalizedError {
        case changed, invalidImage
        var errorDescription: String? {
            ChekinanaProductCopy.text("scan.review.refit_failed", "Unable to refit this Cheki. The image was kept.")
        }
    }
    static func stamp(_ url: URL) throws -> Stamp {
        let attributes = try FileManager.default.attributesOfItem(atPath: url.path)
        guard attributes[.type] as? FileAttributeType == .typeRegular,
              let size = attributes[.size] as? NSNumber,
              let modified = attributes[.modificationDate] as? Date,
              let inode = attributes[.systemFileNumber] as? NSNumber else { throw Failure.changed }
        return Stamp(size: size.uint64Value, modified: modified, inode: inode.uint64Value)
    }
    static func load(_ url: URL) async throws -> Source {
        try await Task.detached(priority: .userInitiated) {
            let before = try stamp(url)
            let data = try Data(contentsOf: url)
            guard before == (try stamp(url)) else { throw Failure.changed }
            return Source(url: url, data: data, stamp: before)
        }.value
    }
    static func prepare(_ output: Data, source: Source) async throws -> Prepared {
        try await Task.detached(priority: .userInitiated) {
            guard try stamp(source.url) == source.stamp,
                  SHA256.hash(data: try Data(contentsOf: source.url)) == SHA256.hash(data: source.data),
                  let original = CGImageSourceCreateWithData(source.data as CFData, nil),
                  let originalType = CGImageSourceGetType(original),
                  let result = CGImageSourceCreateWithData(output as CFData, nil),
                  let resultType = CGImageSourceGetType(result),
                  let image = CGImageSourceCreateImageAtIndex(result, 0, nil) else { throw Failure.changed }
            let encoded: Data
            if originalType as String == resultType as String {
                encoded = output
            } else {
                // Keep the existing managed filename/format without changing the model reference.
                let bytes = NSMutableData()
                guard let destination = CGImageDestinationCreateWithData(bytes, originalType, 1, nil) else { throw Failure.invalidImage }
                CGImageDestinationAddImage(destination, image, [kCGImagePropertyOrientation: 1] as CFDictionary)
                guard CGImageDestinationFinalize(destination) else { throw Failure.invalidImage }
                encoded = bytes as Data
            }
            let temporaryURL = source.url.deletingLastPathComponent()
                .appendingPathComponent(".refit-\(UUID().uuidString).tmp")
            do {
                try encoded.write(to: temporaryURL, options: [.withoutOverwriting])
                let originalAttributes = try FileManager.default.attributesOfItem(atPath: source.url.path)
                let preserved = originalAttributes.filter { $0.key == .posixPermissions || $0.key == .protectionKey }
                try FileManager.default.setAttributes(preserved, ofItemAtPath: temporaryURL.path)
                return Prepared(temporaryURL: temporaryURL, source: source)
            } catch {
                try? FileManager.default.removeItem(at: temporaryURL)
                throw error
            }
        }.value
    }
    /// Called without suspension after validating the live model on the main actor.
    static func commit(_ prepared: Prepared) throws {
        guard try stamp(prepared.source.url) == prepared.source.stamp else { throw Failure.changed }
        let result = prepared.temporaryURL.withUnsafeFileSystemRepresentation { temporary in
            prepared.source.url.withUnsafeFileSystemRepresentation { original in
                rename(temporary!, original!)
            }
        }
        if result != 0 { throw POSIXError(POSIXErrorCode(rawValue: errno) ?? .EIO) }
    }
    static func discard(_ prepared: Prepared) {
        try? FileManager.default.removeItem(at: prepared.temporaryURL)
    }
}

private struct ChekinanaChekiViewerPage: View {
    @Environment(\.modelContext) private var modelContext
    let cheki: MediaItem
    let isActive: Bool
    let pageNumber: Int?
    let pageCount: Int
    let title: String?
    let onClose: () -> Void
    let pageTranslation: CGFloat
    let onHorizontalDragChanged: (CGFloat) -> Void
    let onHorizontalDragEnded: (ChekinanaMediaPagerDragRelease) -> Bool
    let onTap: () -> Void
    let appearance: ChekinanaChekiViewerAppearance
    @ObservedObject private var thumbnailRevisions =
        ChekinanaThumbnailRevisionStore.shared
    @State private var image: ChekinanaRenderedImage?
    @State private var refitImage: ChekinanaRenderedImage?
    @State private var refitSource: ChekinanaViewerRefitFileStore.Source?
    @State private var refitOutput: Data?
    @State private var refitSize: ChekiSize?
    @State private var refitReference: String?
    @State private var refitGeneration: UUID?
    @State private var refitOwnerID: UUID?
    @State private var refitTask: Task<Void, Never>?
    @State private var refitToken = UUID()
    @State private var refitError: String?

    private var imageLoadIdentity: ChekinanaThumbnailLoadIdentity {
        thumbnailRevisions.identity(
            imageRef: cheki.imageRef,
            sourceKey: "cheki-viewer-\(cheki.id.uuidString)"
        )
    }

    var body: some View {
        ChekinanaMediaViewerPageChrome(
            idols: cheki.idols,
            date: cheki.date,
            centerTitle: title,
            pageLabel: pageCount > 1
                ? pageNumber.map { "\($0)/\(pageCount)" }
                : nil,
            backgroundColor: appearance.backgroundColor,
            foregroundColor: appearance.foregroundColor,
            controlBackgroundColor: appearance.controlBackgroundColor,
            closeDisabled: false,
            closeIdentifier: "chekinana.cheki.viewer.close",
            headerIdentifier: "chekinana.cheki-viewer.header",
            onClose: onClose
        ) {
            ZStack {
                appearance.backgroundColor
                if let image = refitImage ?? image {
                    ChekinanaZoomableImageViewport(
                        imageSize: CGSize(
                            width: image.cgImage.width,
                            height: image.cgImage.height
                        ),
                        resetID: imageLoadIdentity,
                        isActive: isActive,
                        pageTranslation: pageTranslation,
                        onHorizontalDragChanged: onHorizontalDragChanged,
                        onHorizontalDragEnded: onHorizontalDragEnded,
                        onSingleTap: onTap
                    ) {
                        Image(decorative: image.cgImage, scale: 1)
                            .resizable()
                            .scaledToFit()
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    ProgressView().tint(appearance.foregroundColor)
                }
            }
        } footerContent: {
            Button(action: refitOrApply) {
                HStack(spacing: 8) {
                    if refitTask != nil { ProgressView() }
                    Text(refitOutput == nil
                         ? ChekinanaProductCopy.text("scan.review.refit", "Refit")
                         : ChekinanaProductCopy.text("gallery.refit.apply", "Apply"))
                }
            }
            .buttonStyle(.bordered)
            .disabled(true)
            .hidden()
            .accessibilityHidden(true)
            .padding(.bottom, 12)
            .accessibilityIdentifier("chekinana.cheki.viewer.refit")
        }
        .onChange(of: isActive) { _, active in
            if !active { discardRefit() }
        }
        .onDisappear { discardRefit() }
        .alert(ChekinanaProductCopy.text("common.error", "Error"), isPresented: Binding(
            get: { refitError != nil }, set: { if !$0 { refitError = nil } }
        )) {
            Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
        } message: { Text(refitError ?? "") }
        .task(id: imageLoadIdentity) {
            image = nil
            let loadedImage = await ChekinanaMediaPreviewCache.shared.image(
                identity: imageLoadIdentity,
                imageReference: cheki.imageRef ?? ""
            )
            guard !Task.isCancelled else { return }
            image = loadedImage
        }
    }
    private func discardRefit() {
        refitToken = UUID()
        refitTask?.cancel()
        refitTask = nil
        refitImage = nil
        refitSource = nil
        refitOutput = nil
        refitSize = nil
        refitReference = nil
        refitGeneration = nil
        refitOwnerID = nil
        refitError = nil
    }

    private func refitOrApply() {
        guard isActive, refitTask == nil else { return }
        let token = UUID()
        refitToken = token
        if let output = refitOutput, let source = refitSource {
            refitTask = Task { @MainActor in
                var prepared: ChekinanaViewerRefitFileStore.Prepared?
                defer {
                    if let prepared { ChekinanaViewerRefitFileStore.discard(prepared) }
                    if refitToken == token { refitTask = nil }
                }
                do {
                    try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
                        try Task.checkCancellation()
                        try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(in: modelContext)
                        guard refitToken == token else { throw CancellationError() }
                        try validateRefitTarget(reference: refitReference, size: refitSize,
                                                ownerID: refitOwnerID, generation: refitGeneration)
                        prepared = try await ChekinanaViewerRefitFileStore.prepare(output, source: source)
                        try Task.checkCancellation()
                        guard refitToken == token, let prepared else { throw CancellationError() }
                        try validateRefitTarget(reference: refitReference, size: refitSize,
                                                ownerID: refitOwnerID, generation: refitGeneration)
                        try ChekinanaViewerRefitFileStore.commit(prepared)
                        await ChekinanaThumbnailCache.shared.invalidate(imageRef: refitReference)
                    }
                    if refitToken == token {
                        image = refitImage
                        discardRefit()
                    }
                } catch is CancellationError {
                } catch {
                    if refitToken == token { refitError = error.localizedDescription }
                }
            }
        } else {
            let reference = cheki.imageRef
            let size = cheki.size ?? .mini
            let ownerID = cheki.mediaOwnerID
            refitTask = Task { @MainActor in
                defer { if refitToken == token { refitTask = nil } }
                do {
                    let (source, generation) = try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
                        try Task.checkCancellation()
                        try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(in: modelContext)
                        guard refitToken == token else { throw CancellationError() }
                        let generation = try ChekinanaLibraryGenerationStore.current(in: ModelContext(modelContext.container))
                        try validateRefitTarget(reference: reference, size: size, ownerID: ownerID, generation: generation)
                        guard let url = ChekiImageRefResolver.managedChekiFileURL(for: reference, chekiID: ownerID) else {
                            throw ChekinanaViewerRefitFileStore.Failure.changed
                        }
                        let loaded = try await ChekinanaViewerRefitFileStore.load(url)
                        try Task.checkCancellation()
                        return (loaded, generation)
                    }
                    try Task.checkCancellation()
                    let result = try await ChekinanaOnDeviceScannerClient().refit(
                        ChekinanaPendingChekiImage(data: source.data, filenameExtension: source.url.pathExtension), size: size
                    )
                    try Task.checkCancellation()
                    guard case .image(let output) = result,
                          let preview = await ChekinanaImageWorker.previewImage(
                            from: output.data, maxDimension: ChekinanaMediaPagerPolicy.previewMaximumPixelDimension
                          ) else { throw ChekinanaViewerRefitFileStore.Failure.invalidImage }
                    try Task.checkCancellation()
                    guard refitToken == token, cheki.imageRef == reference,
                          (cheki.size ?? .mini) == size else { return }
                    refitSource = source
                    refitOutput = output.data
                    refitSize = size
                    refitReference = reference
                    refitGeneration = generation
                    refitOwnerID = ownerID
                    refitImage = preview
                } catch is CancellationError {
                } catch {
                    if refitToken == token { refitError = error.localizedDescription }
                }
            }
        }
    }

    private func validateRefitTarget(reference: String?, size: ChekiSize?, ownerID: UUID?, generation: UUID?) throws {
        let context = ModelContext(modelContext.container)
        let id = cheki.id
        let candidates = try context.fetch(FetchDescriptor<MediaItem>(predicate: #Predicate { $0.id == id }))
        guard !cheki.isDeleted, cheki.modelContext === modelContext,
              cheki.imageRef == reference, cheki.mediaOwnerID == ownerID, (cheki.size ?? .mini) == size,
              try ChekinanaLibraryGenerationStore.current(in: context) == generation,
              candidates.count == 1, let current = candidates.first,
              current.persistentModelID == cheki.persistentModelID,
              current.kind == .cheki, current.imageRef == reference,
              current.mediaOwnerID == ownerID, (current.size ?? .mini) == size else {
            throw ChekinanaViewerRefitFileStore.Failure.changed
        }
    }

}

private struct ChekinanaLegacyGalleryDetailView: View {
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    let cheki: MediaItem
    let onClose: (() -> Void)?
    @ObservedObject private var thumbnailRevisions =
        ChekinanaThumbnailRevisionStore.shared
    @State private var image: ChekinanaRenderedImage?
    @State private var isEditing = false
    @State private var message: String?
    @State private var confirmationLedger = ChekinanaConfirmationLedger()
    @State private var pendingDeleteConfirmationCode: String?

    init(cheki: MediaItem, onClose: (() -> Void)? = nil) {
        self.cheki = cheki
        self.onClose = onClose
    }

    private var imageLoadIdentity: ChekinanaThumbnailLoadIdentity {
        thumbnailRevisions.identity(
            imageRef: cheki.imageRef,
            sourceKey: "legacy-gallery-detail-\(cheki.id.uuidString)"
        )
    }

    var body: some View {
        let _ = languageRevision
        ZStack {
            ChekinanaProductTheme.pageBackground.ignoresSafeArea()
            ChekinanaAccessibilityMarker(identifier: "chekinana.gallery.detail.light")
            VStack(spacing: 0) {
                HStack {
                    VStack(alignment: .leading, spacing: 2) {
                        ChekinanaIdolAvatarRow(idols: cheki.idols, size: 36, showsNames: false)
                        Text(ChekinanaProductDate.displayString(cheki.date))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                    Spacer()
                    Button {
                        if canDismiss {
                            closeDetail()
                        }
                    } label: {
                        Image(systemName: "xmark")
                            .frame(width: 44, height: 44)
                            .background(Color(uiColor: .tertiarySystemGroupedBackground))
                            .clipShape(Circle())
                    }
                    .buttonStyle(.plain)
                    .disabled(!canDismiss)
                    .accessibilityLabel(ChekinanaL10n.text("关闭预览", fallback: "Close preview"))
                    .accessibilityHint(
                        canDismiss
                            ? ChekinanaL10n.text("关闭 Cheki 详情", fallback: "Close Cheki details")
                            : ChekinanaL10n.message("Tap Delete to complete image recovery or cleanup before closing.")
                    )
                    .accessibilityIdentifier("chekinana.gallery.detail.close")
                }
                .foregroundStyle(.primary)
                .padding(.horizontal, 16)
                .padding(.vertical, 8)

                ZStack {
                    if let image {
                        Image(decorative: image.cgImage, scale: 1)
                            .resizable()
                            .scaledToFit()
                    } else {
                        ProgressView().tint(ChekinanaProductTheme.accent)
                    }
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)

                if let note = cheki.note.nonEmpty {
                    Text(note)
                        .font(.subheadline)
                        .foregroundStyle(.primary)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(16)
                }

                if deleteRecoveryRequired {
                    Label(
                        ChekinanaL10n.text("Deletion recovery is required. Tap Delete again to finish restoring or cleaning up the managed image before closing.", fallback: "Deletion recovery is required. Tap Delete again to finish restoring or cleaning up the managed image before closing."),
                        systemImage: "exclamationmark.triangle.fill"
                    )
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(.orange)
                    .padding(.horizontal, 16)
                    .accessibilityIdentifier("chekinana.gallery.detail.delete-recovery-required")
                }

                HStack(spacing: 12) {
                    Button { isEditing = true } label: { Label(ChekinanaL10n.message("Edit"), systemImage: "pencil") }
                        .accessibilityIdentifier("chekinana.gallery.detail.edit")
                    Button { exportImage() } label: { Label(ChekinanaL10n.message("Export"), systemImage: "square.and.arrow.down") }
                        .accessibilityIdentifier("chekinana.gallery.detail.export")
                    Spacer()
                    Button(role: .destructive) { Task { await deleteCheki() } } label: {
                        Label(
                            deleteRecoveryRequired ? ChekinanaL10n.text("product.common.retry_recovery", fallback: "Retry recovery") : ChekinanaL10n.text("assistant.delete", fallback: "Delete"),
                            systemImage: deleteRecoveryRequired ? "arrow.clockwise" : "trash"
                        )
                    }
                    .accessibilityIdentifier("chekinana.gallery.detail.delete")
                }
                .buttonStyle(.bordered)
                .tint(ChekinanaProductTheme.accent)
                .padding(16)
            }
        }
        .preferredColorScheme(.light)
        .toolbar(.hidden, for: .navigationBar)
        .interactiveDismissDisabled(!canDismiss)
        .chekinanaScreenMarker("chekinana.gallery.detail")
        .task(id: imageLoadIdentity) {
            image = nil
            image = await ChekinanaImageWorker.previewImage(fromImageRef: cheki.imageRef ?? "", maxDimension: 2400)
        }
        .sheet(isPresented: $isEditing) { ChekinanaChekiEditorView(cheki: cheki) }
        .alert(ChekinanaRecordKind.cheki.title, isPresented: Binding(
            get: { message != nil },
            set: { if !$0 { message = nil } }
        )) { Button(ChekinanaL10n.message("OK"), role: .cancel) {} } message: { Text(message ?? "") }
    }

    private var deleteRecoveryRequired: Bool {
        guard let pendingDeleteConfirmationCode else { return false }
        return confirmationLedger.cancellationRequiresRecovery(pendingDeleteConfirmationCode)
    }

    private var canDismiss: Bool {
        ChekinanaGalleryDeleteDismissPolicy.canDismiss(
            pendingConfirmationCode: pendingDeleteConfirmationCode,
            recoveryRequired: deleteRecoveryRequired
        )
    }

    private func closeDetail() {
        if let onClose {
            onClose()
        } else {
            dismiss()
        }
    }

    private func exportImage() {
        guard let url = ChekiImageRefResolver.managedChekiFileURL(
            for: cheki.imageRef,
            chekiID: cheki.mediaOwnerID
        ) ?? ChekiImageRefResolver.localFileURL(for: cheki.imageRef) else {
            message = ChekinanaL10n.message("The clean stored image is unavailable.")
            return
        }
        Task {
            do {
                try await ChekinanaProductPhotoSaver.saveImage(at: url)
                message = ChekinanaL10n.message("Saved the clean image without bbox to Photos.")
            } catch {
                message = error.localizedDescription
            }
        }
    }

    @MainActor
    private func deleteCheki() async {
        let executor = ChekinanaCommandExecutor(
            modelContext: modelContext,
            confirmationLedger: confirmationLedger
        )
        let code: String
        if let pendingDeleteConfirmationCode {
            code = pendingDeleteConfirmationCode
        } else {
            let prepared = await executor.execute("deletecheki \(cheki.id.uuidString.lowercased())")
            guard let preparedCode = ChekinanaConfirmationResponseValidator.deleteChekiConfirmationCode(
                from: prepared,
                expectedChekiID: cheki.id
            ) else {
                message = ChekinanaConfirmationResponseValidator.failureDescription(
                    for: prepared,
                    fallback: ChekinanaL10n.message("This Cheki could not be prepared for deletion.")
                )
                return
            }
            pendingDeleteConfirmationCode = preparedCode
            code = preparedCode
        }
        let result = await executor.execute("confirm \(code)")
        guard ChekinanaConfirmationResponseValidator.isDeleteChekiSuccess(result) else {
            if confirmationLedger.entry(for: code) == nil {
                pendingDeleteConfirmationCode = nil
            }
            let reason = ChekinanaConfirmationResponseValidator.failureDescription(
                for: result,
                fallback: ChekinanaL10n.message("The deletion confirmation did not return a verifiable success result.")
            )
            if confirmationLedger.cancellationRequiresRecovery(code) {
                message = ChekinanaL10n.message("\(reason) This deletion is in required image recovery/cleanup. You must tap Delete / Retry recovery until it completes; this view cannot close yet.")
            } else {
                message = reason
            }
            return
        }
        pendingDeleteConfirmationCode = nil
        closeDetail()
    }
}

private enum ChekinanaGalleryEditableMedia {
    case shame(MediaItem)
    case douga(MediaItem)

    var id: UUID {
        switch self {
        case .shame(let value): value.id
        case .douga(let value): value.id
        }
    }

    var mediaOwnerID: UUID {
        switch self {
        case .shame(let value), .douga(let value): value.mediaOwnerID
        }
    }

    var typeName: String {
        switch self {
        case .shame: ChekinanaRecordKind.shame.title
        case .douga: ChekinanaRecordKind.douga.title
        }
    }

    var idols: [Idol] {
        switch self {
        case .shame(let value): value.idols
        case .douga(let value): value.idols
        }
    }

    var date: Date? {
        switch self {
        case .shame(let value): value.date
        case .douga(let value): value.date
        }
    }

    var note: String {
        switch self {
        case .shame(let value): value.note
        case .douga(let value): value.note
        }
    }

    var eventID: UUID? {
        switch self {
        case .shame(let value), .douga(let value): value.eventID
        }
    }

    var userAppears: Bool {
        switch self {
        case .shame(let value), .douga(let value): value.userAppears
        }
    }

    var isFavorite: Bool {
        switch self {
        case .shame(let value), .douga(let value): value.isFavorite
        }
    }

    var hasPostedToSNS: Bool {
        switch self {
        case .shame(let value), .douga(let value): value.hasPostedToSNS
        }
    }

    var managedURL: URL? {
        switch self {
        case .shame(let value):
            ChekinanaGalleryMediaStore.managedURL(
                for: value.imageRef,
                id: value.mediaOwnerID,
                kind: .shame
            )
        case .douga(let value):
            ChekinanaGalleryMediaStore.managedURL(
                for: value.videoRef,
                id: value.mediaOwnerID,
                kind: .douga
            )
        }
    }

    var mediaKind: ChekinanaGalleryMediaKind {
        switch self {
        case .shame: .shame
        case .douga: .douga
        }
    }

    var mediaReference: String? {
        switch self {
        case .shame(let value): value.imageRef
        case .douga(let value): value.videoRef
        }
    }
}

private struct ChekinanaGalleryEditableMediaSnapshot {
    let id: UUID
    let mediaOwnerID: UUID
    let kind: ChekinanaGalleryMediaKind
    let typeName: String
    let idolIDs: Set<UUID>
    let date: Date?
    let eventID: UUID?
    let userAppears: Bool
    let isFavorite: Bool
    let hasPostedToSNS: Bool
    let note: String
    let mediaReference: String?

    init(_ item: ChekinanaGalleryEditableMedia) {
        id = item.id
        mediaOwnerID = item.mediaOwnerID
        kind = item.mediaKind
        typeName = item.typeName
        idolIDs = Set(item.idols.map(\.id))
        date = item.date
        eventID = item.eventID
        userAppears = item.userAppears
        isFavorite = item.isFavorite
        hasPostedToSNS = item.hasPostedToSNS
        note = item.note
        mediaReference = item.mediaReference
    }
}

private struct ChekinanaGalleryMediaPagerView: View {
    let items: [MediaItem]
    let kind: MediaItemKind
    @State private var selectedID: UUID?

    init(items: [MediaItem], kind: MediaItemKind, initialID: UUID) {
        let matchingItems = items.filter { $0.kind == kind }
        self.items = matchingItems
        self.kind = kind
        _selectedID = State(initialValue: ChekinanaMediaPagerPolicy.initialID(
            requested: initialID,
            available: matchingItems.map(\.id)
        ))
    }

    var body: some View {
        ZStack {
            ChekinanaProductTheme.pageBackground.ignoresSafeArea()
            ChekinanaFullScreenMediaPager(
                items: items,
                selectedID: $selectedID,
                usesEmbeddedPagingGesture: kind == .shame,
                showsPageIndicator: items.count > 1
            ) { item, _, pageInteraction in
                Group {
                    if kind == .shame {
                        ChekinanaGalleryMediaDetailView(
                            shame: item,
                            isActive: selectedID == item.id,
                            pageTranslation: pageInteraction.translation,
                            onHorizontalDragChanged: pageInteraction.dragChanged,
                            onHorizontalDragEnded: pageInteraction.dragEnded
                        )
                    } else {
                        ChekinanaGalleryMediaDetailView(
                            douga: item,
                            isActive: selectedID == item.id
                        )
                    }
                }
            }
            .onChange(of: items.map(\.id)) { _, ids in
                selectedID = ChekinanaMediaPagerPolicy.initialID(
                    requested: selectedID,
                    available: ids
                )
            }
        }
    }
}

private struct ChekinanaGalleryMediaDetailView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    let item: ChekinanaGalleryEditableMedia
    @State private var image: ChekinanaRenderedImage?
    @State private var player: AVPlayer?
    @State private var isPlaying = false
    @State private var isEditing = false
    @State private var message: String?
    @State private var pendingRestore: [(original: URL, quarantine: URL)] = []
    @ObservedObject private var thumbnailRevisions =
        ChekinanaThumbnailRevisionStore.shared
    let isActive: Bool
    let pageTranslation: CGFloat
    let onHorizontalDragChanged: (CGFloat) -> Void
    let onHorizontalDragEnded: (ChekinanaMediaPagerDragRelease) -> Bool

    init(
        shame: MediaItem,
        isActive: Bool = true,
        pageTranslation: CGFloat = 0,
        onHorizontalDragChanged: @escaping (CGFloat) -> Void = { _ in },
        onHorizontalDragEnded: @escaping (ChekinanaMediaPagerDragRelease) -> Bool = { _ in false }
    ) {
        item = .shame(shame)
        self.isActive = isActive
        self.pageTranslation = pageTranslation
        self.onHorizontalDragChanged = onHorizontalDragChanged
        self.onHorizontalDragEnded = onHorizontalDragEnded
    }

    init(douga: MediaItem, isActive: Bool = true) {
        item = .douga(douga)
        self.isActive = isActive
        pageTranslation = 0
        onHorizontalDragChanged = { _ in }
        onHorizontalDragEnded = { _ in false }
    }

    private var imageLoadIdentity: ChekinanaThumbnailLoadIdentity {
        thumbnailRevisions.identity(
            imageRef: item.mediaReference,
            sourceKey: "gallery-media-viewer-\(item.id.uuidString)"
        )
    }

    var body: some View {
        ChekinanaMediaViewerPageChrome(
            idols: item.idols,
            date: item.date,
            centerTitle: nil,
            pageLabel: nil,
            backgroundColor: ChekinanaProductTheme.pageBackground,
            foregroundColor: .primary,
            controlBackgroundColor: Color(uiColor: .tertiarySystemGroupedBackground),
            closeDisabled: !pendingRestore.isEmpty,
            closeIdentifier: "chekinana.gallery.media.detail.close",
            headerIdentifier: "chekinana.gallery.media.detail.header",
            onClose: { dismiss() }
        ) {
            mediaContent
        } footerContent: {
            footerContent
        }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("chekinana.gallery.media.detail.\(item.mediaKind.rawValue)")
        .toolbar(.hidden, for: .navigationBar)
        .interactiveDismissDisabled(!pendingRestore.isEmpty)
        .task(id: imageLoadIdentity) {
            pendingRestore = ChekinanaGalleryMediaStore.restoreRecoveryFiles(
                kind: item.mediaKind,
                id: item.mediaOwnerID,
                reference: item.mediaReference
            )
            guard pendingRestore.isEmpty else { return }
            await loadMedia()
        }
        .sheet(isPresented: $isEditing) {
            ChekinanaGalleryMetadataEditor(
                item: ChekinanaGalleryEditableMediaSnapshot(item),
                onDeleted: { dismiss() }
            )
        }
        .alert(item.typeName, isPresented: Binding(
            get: { message != nil },
            set: { if !$0 { message = nil } }
        )) { Button(ChekinanaL10n.message("OK"), role: .cancel) {} } message: { Text(message ?? "") }
    }

    @ViewBuilder
    private var mediaContent: some View {
        Group {
            switch item {
            case .shame:
                if let image {
                    ChekinanaZoomableImageViewport(
                        imageSize: CGSize(
                            width: image.cgImage.width,
                            height: image.cgImage.height
                        ),
                        resetID: item.id,
                        isActive: isActive,
                        pageTranslation: pageTranslation,
                        onHorizontalDragChanged: onHorizontalDragChanged,
                        onHorizontalDragEnded: onHorizontalDragEnded,
                        onSingleTap: { isEditing = true }
                    ) {
                        Image(decorative: image.cgImage, scale: 1)
                            .resizable()
                            .scaledToFit()
                    }
                } else {
                    ProgressView()
                }
            case .douga:
                if let player {
                    ZStack {
                        ChekinanaEditableVideoPlayer(
                            player: player,
                            onSingleTap: { tapMedia() }
                        )
                        if !isPlaying {
                            Button {
                                handleVideoInteraction(.togglePlayback, player: player)
                            } label: {
                                Image(systemName: "play.fill")
                                    .font(.system(size: 26, weight: .semibold))
                                    .foregroundStyle(.white)
                                    .frame(width: 64, height: 64)
                                    .background(.black.opacity(0.58), in: Circle())
                            }
                            .buttonStyle(.plain)
                            .accessibilityLabel(
                                ChekinanaL10n.text(
                                    "播放",
                                    fallback: "Play"
                                )
                            )
                            .accessibilityIdentifier(
                                "chekinana.gallery.video.playback"
                            )
                        }
                    }
                    .onChange(of: isActive) { _, active in
                        guard !active else { return }
                        handleVideoInteraction(.pageBecameInactive, player: player)
                    }
                    .onReceive(
                        NotificationCenter.default.publisher(
                            for: .AVPlayerItemDidPlayToEndTime,
                            object: player.currentItem
                        )
                    ) { _ in
                        handleVideoInteraction(.playbackEnded, player: player)
                    }
                    .onDisappear {
                        handleVideoInteraction(.viewDisappeared, player: player)
                    }
                } else {
                    ProgressView()
                }
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .accessibilityAddTraits(.isButton)
        .accessibilityAction { tapMedia() }
        .accessibilityHint(
            isPlaying ? ChekinanaL10n.text("暂停", fallback: "Pause")
            : ChekinanaProductCopy.text(
                "gallery.viewer.edit_hint",
                "Tap to edit this item"
            )
        )
        .accessibilityIdentifier(
            "chekinana.gallery.media.detail.media.\(item.id.uuidString.lowercased())"
        )
    }

    @ViewBuilder
    private var footerContent: some View {
        VStack(alignment: .leading, spacing: 5) {
            if let note = item.note.nonEmpty {
                Text(note)
            }
        }
        .font(.subheadline)
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.horizontal, 16)
        .padding(.top, 12)

        if !pendingRestore.isEmpty {
            VStack(alignment: .leading, spacing: 8) {
                Label(
                    ChekinanaProductCopy.text(
                        "gallery.media.recovery_required",
                        "Media recovery is required before this item can be used or closed."
                    ),
                    systemImage: "exclamationmark.triangle.fill"
                )
                .font(.caption.weight(.semibold))
                .foregroundStyle(.orange)
                Button(
                    ChekinanaProductCopy.text(
                        "common.retry_recovery",
                        "Retry recovery"
                    )
                ) { Task { await retryRecovery() } }
                    .buttonStyle(.borderedProminent)
                    .accessibilityIdentifier("chekinana.gallery.media.retry-recovery")
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(.horizontal, 16)
            .padding(.top, 8)
            .accessibilityIdentifier("chekinana.gallery.media.recovery-required")
        }
    }

    @MainActor
    private func handleVideoInteraction(
        _ action: ChekinanaGalleryVideoInteractionPolicy.Action,
        player: AVPlayer
    ) {
        let transition = ChekinanaGalleryVideoInteractionPolicy.reduce(
            state: .init(isPlaying: isPlaying, isEditing: isEditing),
            action: action
        )
        isPlaying = transition.state.isPlaying
        isEditing = transition.state.isEditing
        switch transition.playbackEffect {
        case .play:
            ChekinanaMediaPlaybackAudioSession.activate(mode: .moviePlayback)
            player.play()
        case .pause:
            player.pause()
        case .pauseAndRewind:
            player.pause()
            player.seek(to: .zero)
        }
    }

    @MainActor
    private func tapMedia() {
        if case .douga = item, let player {
            handleVideoInteraction(.tapVideo, player: player)
        } else {
            openEditor()
        }
    }

    @MainActor
    private func openEditor() {
        if case .douga = item, let player {
            handleVideoInteraction(.openEditor, player: player)
        } else {
            isEditing = true
        }
    }

    @MainActor
    private func retryRecovery() async {
        guard !pendingRestore.isEmpty else { return }
        do {
            try await ChekinanaGalleryDeletionCoordinator.recoverPending(
                pendingRestore,
                in: modelContext
            )
            pendingRestore = []
            message = ChekinanaProductCopy.text(
                "gallery.media.recovery_complete",
                "Media recovery completed."
            )
            Task { await loadMedia() }
        } catch {
            message = ChekinanaProductCopy.format(
                "gallery.media.error.restore_required",
                "The delete failed and the media could not be restored. Retry recovery before closing: %@",
                error.localizedDescription
            )
        }
    }

    @MainActor
    private func loadMedia() async {
        guard let url = item.managedURL else { return }
        switch item {
        case .shame:
            image = await ChekinanaMediaPreviewCache.shared.image(
                identity: imageLoadIdentity,
                imageReference: url.lastPathComponent
            )
        case .douga:
            player = AVPlayer(url: url)
        }
    }
}

private struct ChekinanaGalleryImportEditor: View {
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query(sort: \Idol.name) private var idols: [Idol]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let draft: ChekinanaGalleryImportDraft
    let onSaved: () -> Void
    let onCancel: () -> Void

    @State private var idolIDs = Set<UUID>()
    @State private var hasDate = false
    @State private var date = Date()
    @State private var eventID: UUID?
    @State private var userAppears: Bool
    @State private var isFavorite = false
    @State private var hasPostedToSNS = false
    @State private var note = ""
    @State private var isIdolSelectionPresented = false
    @State private var isSaving = false
    @State private var message: String?
    @State private var image: ChekinanaRenderedImage?
    @State private var player: AVPlayer?
    @State private var didFinish = false
    @State private var preparedDraftID: UUID?

    init(
        draft: ChekinanaGalleryImportDraft,
        onSaved: @escaping () -> Void,
        onCancel: @escaping () -> Void
    ) {
        self.draft = draft
        self.onSaved = onSaved
        self.onCancel = onCancel
        let kind: MediaItemKind = switch draft.payload {
        case .shame: .shame
        case .douga: .douga
        }
        _userAppears = State(
            initialValue: ChekinanaNewMediaDefaults.userAppears(for: kind)
        )
    }

    private var title: String {
        switch draft.payload {
        case .shame: ChekinanaGalleryAddCopy.photo
        case .douga: ChekinanaGalleryAddCopy.video
        }
    }

    var body: some View {
        let _ = languageRevision
        NavigationStack {
            Form {
                Section(ChekinanaProductCopy.text("common.preview", "Preview")) {
                    Group {
                        switch draft.payload {
                        case .shame:
                            if let image {
                                Image(decorative: image.cgImage, scale: 1)
                                    .resizable().scaledToFit()
                            } else {
                                ProgressView()
                            }
                        case .douga:
                            if let player {
                                ChekinanaPlaybackVideoPlayer(player: player)
                                    .frame(minHeight: 240)
                            } else {
                                ProgressView()
                            }
                        }
                    }
                    .frame(maxWidth: .infinity, minHeight: 180)
                }
                Section(ChekinanaProductCopy.text("common.idols", "Idols")) {
                    ChekinanaIdolSelectionSummaryButton(
                        idols: visibleIdols.filter { idolIDs.contains($0.id) },
                        identifier: "chekinana.gallery.import.idols"
                    ) {
                        isIdolSelectionPresented = true
                    }
                }
                Section(ChekinanaProductCopy.text("common.metadata", "Metadata")) {
                    Toggle(
                        ChekinanaProductCopy.text("common.include_date", "Include date"),
                        isOn: $hasDate
                    )
                    if hasDate {
                        ChekinanaExpandableDateWheel(
                            ChekinanaProductCopy.text("common.date", "Date"),
                            selection: $date,
                            accessibilityIdentifier: "chekinana.gallery.import.date"
                        )
                    }
                    ChekinanaChekiEventSelectionField(
                        eventID: $eventID,
                        recordDate: draftCanonicalDate,
                        events: events,
                        schedules: eventSchedules,
                        primaryScope: .exactDate
                    )
                    ChekinanaUserAppearsPicker(
                        userAppears: $userAppears,
                        identifier: "chekinana.gallery.import.user-appears"
                    )
                    Toggle(
                        ChekinanaProductCopy.text("common.favorite", "Favorite"),
                        isOn: $isFavorite
                    )
                    ChekinanaSingleLineNoteField(
                        ChekinanaProductCopy.text("common.note", "Note"),
                        text: $note
                    )
                }
                if let message {
                    Section { Text(message).foregroundStyle(.red) }
                }
            }
            .disabled(isSaving)
            .navigationTitle(title)
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        finish(saved: false)
                    }
                        .disabled(isSaving)
                        .accessibilityIdentifier("chekinana.gallery.import.cancel")
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.save", "Save")) {
                        Task { await save() }
                    }
                        .disabled(isSaving)
                        .accessibilityIdentifier("chekinana.gallery.import.save")
                }
            }
        }
        .interactiveDismissDisabled()
        .sheet(isPresented: $isIdolSelectionPresented) {
            ChekinanaIdolSelectionView(
                options: visibleIdols.map(ChekinanaIdolSelectionOption.init),
                selectedIDs: $idolIDs
            )
        }
        .task(id: draft.id) {
            guard ChekinanaGalleryImportPreviewPolicy.shouldPrepare(
                preparedDraftID: preparedDraftID,
                draftID: draft.id
            ) else { return }
            preparedDraftID = draft.id
            switch draft.payload {
            case .shame(let stagedURL, _):
                let preparedImage = await ChekinanaImageWorker.thumbnailImage(
                    fromFileAt: stagedURL,
                    maxDimension: 1_600
                )
                guard !didFinish else { return }
                image = preparedImage
            case .douga(let stagedURL):
                guard !didFinish, player == nil else { return }
                ChekinanaMediaPlaybackAudioSession.activate(mode: .moviePlayback, options: .mixWithOthers)
                player = AVPlayer(url: stagedURL)
            }
        }
        .onDisappear {
            guard ChekinanaGalleryImportEditorTeardownPolicy.shouldCancelImport(
                didFinish: didFinish
            ) else { return }
            finish(saved: false)
        }
        .onChange(of: hasDate) { _, _ in clearInvalidEventSelection() }
        .onChange(of: date) { _, _ in clearInvalidEventSelection() }
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    private var draftCanonicalDate: Date? {
        guard hasDate else { return nil }
        return ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
    }

    private func clearInvalidEventSelection() {
        eventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
            eventID,
            recordDate: draftCanonicalDate,
            events: events
        )
    }

    @MainActor
    private func save() async {
        guard !isSaving, !didFinish else { return }
        isSaving = true
        defer { isSaving = false }
        let normalizedDate = hasDate
            ? ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
            : nil
        if hasDate, normalizedDate == nil {
            message = ChekinanaProductCopy.text(
                "error.normalize_date",
                "Unable to normalize the selected date."
            )
            return
        }
        let selectedIdolIDs = idolIDs
        let savedUserAppears = userAppears
        let savedIsFavorite = isFavorite
        let savedHasPostedToSNS = hasPostedToSNS
        let savedNote = note
        let id = UUID()
        do {
            switch draft.payload {
            case .shame(let stagedURL, let filenameExtension):
                let reference = try await ChekinanaGalleryMediaStore.saveImage(
                    from: stagedURL,
                    id: id,
                    filenameExtension: filenameExtension
                )
                do {
                    let selectedIdols = try ChekinanaModelContextResolver.idols(
                        idolIDs: selectedIdolIDs,
                        in: modelContext
                    )
                    let shame = MediaItem(
                        id: id,
                        kind: .shame,
                        event: events.first { $0.id == eventID },
                        date: normalizedDate,
                        userAppears: savedUserAppears,
                        mediaRef: reference,
                        isFavorite: savedIsFavorite,
                        hasPostedToSNS: savedHasPostedToSNS,
                        note: savedNote
                    )
                    modelContext.insert(shame)
                    guard shame.modelContext === modelContext,
                          selectedIdols.allSatisfy({
                              $0.modelContext === modelContext
                          }) else {
                        throw ChekinanaProductRecordCreationError.modelContextMismatch
                    }
                    shame.idols = selectedIdols
                    try ChekinanaEventAssociationPropagation.propagate(
                        from: shame,
                        in: modelContext
                    )
                    try modelContext.save()
                } catch {
                    modelContext.rollback()
                    do {
                        try await ChekinanaGalleryMediaStore.removeFilesInBackground(
                            kind: .shame,
                            id: id,
                            reference: reference
                        )
                    } catch {
                        ChekinanaGalleryMediaStore.recordOrphanedImport(
                            kind: .shame,
                            id: id,
                            reference: reference
                        )
                    }
                    throw error
                }
            case .douga(let stagedURL):
                let reference = try await ChekinanaGalleryMediaStore.saveVideo(
                    from: stagedURL,
                    id: id
                )
                do {
                    let selectedIdols = try ChekinanaModelContextResolver.idols(
                        idolIDs: selectedIdolIDs,
                        in: modelContext
                    )
                    let douga = MediaItem(
                        id: id,
                        kind: .douga,
                        event: events.first { $0.id == eventID },
                        date: normalizedDate,
                        userAppears: savedUserAppears,
                        mediaRef: reference,
                        isFavorite: savedIsFavorite,
                        hasPostedToSNS: savedHasPostedToSNS,
                        note: savedNote
                    )
                    modelContext.insert(douga)
                    guard douga.modelContext === modelContext,
                          selectedIdols.allSatisfy({
                              $0.modelContext === modelContext
                          }) else {
                        throw ChekinanaProductRecordCreationError.modelContextMismatch
                    }
                    douga.idols = selectedIdols
                    try ChekinanaEventAssociationPropagation.propagate(
                        from: douga,
                        in: modelContext
                    )
                    try modelContext.save()
                } catch {
                    modelContext.rollback()
                    do {
                        try await ChekinanaGalleryMediaStore.removeFilesInBackground(
                            kind: .douga,
                            id: id,
                            reference: reference
                        )
                    } catch {
                        ChekinanaGalleryMediaStore.recordOrphanedImport(
                            kind: .douga,
                            id: id,
                            reference: reference
                        )
                    }
                    throw error
                }
            }
            finish(saved: true)
        } catch {
            message = error.localizedDescription
        }
    }

    @MainActor
    private func finish(saved: Bool) {
        guard !didFinish else { return }
        didFinish = true
        isIdolSelectionPresented = false
        player?.pause()
        player?.replaceCurrentItem(with: nil)
        player = nil
        image = nil
        if saved {
            onSaved()
        } else {
            onCancel()
        }
    }
}

private struct ChekinanaTextActionPressFeedbackStyle: ButtonStyle {
    @Environment(\.isEnabled) private var isEnabled

    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .frame(maxWidth: .infinity, alignment: .leading)
            .contentShape(Rectangle())
            // colorMultiply is applied directly to the label foreground and
            // remains visible inside Form rows; it does not tint the row.
            .colorMultiply(
                configuration.isPressed && isEnabled
                    ? Color(white: 0.45)
                    : .white
            )
            .opacity(isEnabled ? 1 : 0.35)
    }
}

private struct ChekinanaPhotoSaveFeedbackButton: View {
    @Environment(\.isEnabled) private var isEnabled
    let action: () -> Void
    @State private var feedbackRevision = 0
    @State private var showsFeedback = false

    var body: some View {
        Button {
            feedbackRevision &+= 1
            showsFeedback = true
            action()
        } label: {
            Text(ChekinanaProductCopy.text("gallery.save_to_photos", "Save to Photos"))
                .frame(maxWidth: .infinity, alignment: .leading)
                .contentShape(Rectangle())
                .foregroundStyle(showsFeedback ? Color.gray : ChekinanaProductTheme.accent)
                .opacity(isEnabled ? 1 : 0.35)
        }
        .buttonStyle(.plain)
        .task(id: feedbackRevision) {
            guard feedbackRevision != 0 else { return }
            let revision = feedbackRevision
            do { try await Task.sleep(for: .milliseconds(200)) }
            catch { return }
            guard !Task.isCancelled, revision == feedbackRevision else { return }
            showsFeedback = false
        }
    }
}

private struct ChekinanaGalleryMetadataEditor: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.chekinanaMediaEditHooks) private var mediaEditHooks
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query(sort: \Idol.name) private var idols: [Idol]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let item: ChekinanaGalleryEditableMediaSnapshot
    var onDeleted: (() -> Void)? = nil

    @State private var idolIDs: Set<UUID>
    @State private var hasDate: Bool
    @State private var date: Date
    @State private var eventID: UUID?
    @State private var userAppears: Bool
    @State private var isFavorite: Bool
    @State private var hasPostedToSNS: Bool
    @State private var note: String
    @State private var message: String?
    @State private var isIdolSelectionPresented = false
    @State private var didLoadMetadata = false
    @State private var isDeleteConfirmationPresented = false
    @State private var isDeleting = false
    @State private var pendingRestore: [(original: URL, quarantine: URL)] = []

    init(
        item: ChekinanaGalleryEditableMediaSnapshot,
        onDeleted: (() -> Void)? = nil
    ) {
        self.item = item
        self.onDeleted = onDeleted
        _idolIDs = State(initialValue: item.idolIDs)
        _hasDate = State(initialValue: item.date != nil)
        _date = State(initialValue: item.date.flatMap {
            ChekinanaDateOnly.displayDate(from: $0, calendar: .current)
        } ?? Date())
        _eventID = State(initialValue: item.eventID)
        _userAppears = State(initialValue: item.userAppears)
        _isFavorite = State(initialValue: item.isFavorite)
        _hasPostedToSNS = State(initialValue: item.hasPostedToSNS)
        _note = State(initialValue: item.note)
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    ChekinanaPhotoSaveFeedbackButton(action: exportMedia)
                    .disabled(!pendingRestore.isEmpty)
                    .accessibilityIdentifier("chekinana.gallery.media.editor.export")
                }
                Section(ChekinanaProductCopy.text("common.idols", "Idols")) {
                    ChekinanaIdolSelectionSummaryButton(
                        idols: visibleIdols.filter { idolIDs.contains($0.id) },
                        identifier: "chekinana.gallery.media.editor.idols"
                    ) { isIdolSelectionPresented = true }
                }
                Section {
                    ChekinanaMediaMetadataEditorFields(
                        visibleIdols: visibleIdols,
                        events: events,
                        schedules: eventSchedules,
                        identifierPrefix: "chekinana.gallery.media.editor",
                        chooseIdols: { isIdolSelectionPresented = true },
                        idolIDs: $idolIDs,
                        hasDate: $hasDate,
                        date: $date,
                        eventID: $eventID,
                        userAppears: $userAppears,
                        isFavorite: $isFavorite,
                        hasPostedToSNS: $hasPostedToSNS,
                        note: $note
                    )
                    if let message {
                        ChekinanaInlineStatus(message: message, kind: .error)
                    }
                }
                Section {
                    Button(
                        pendingRestore.isEmpty
                            ? ChekinanaProductCopy.text("common.delete", "Delete")
                            : ChekinanaProductCopy.text(
                                "common.retry_recovery",
                                "Retry recovery"
                            ),
                        role: .destructive
                    ) {
                        if pendingRestore.isEmpty {
                            isDeleteConfirmationPresented = true
                        } else {
                            Task { await retryRecovery() }
                        }
                    }
                    .foregroundStyle(.red)
                    .buttonStyle(ChekinanaTextActionPressFeedbackStyle())
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .disabled(isDeleting)
                    .accessibilityIdentifier("chekinana.gallery.media.editor.delete")
                }
            }
            .chekinanaGroupedPageBackground()
            .navigationTitle(
                ChekinanaProductCopy.format(
                    "calendar.edit_record",
                    "Edit %@",
                    item.typeName
                )
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        dismiss()
                    }
                    .disabled(!pendingRestore.isEmpty || isDeleting)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.save", "Save"), action: save)
                        .disabled(!pendingRestore.isEmpty || isDeleting)
                        .accessibilityIdentifier("chekinana.gallery.media.editor.save")
                }
            }
        }
        .sheet(isPresented: $isIdolSelectionPresented) {
            ChekinanaIdolSelectionView(
                options: visibleIdols.map(ChekinanaIdolSelectionOption.init),
                selectedIDs: visibleIdolSelection
            )
        }
        .task(id: item.id) {
            guard !didLoadMetadata else { return }
            didLoadMetadata = true
            pendingRestore = ChekinanaGalleryMediaStore.restoreRecoveryFiles(
                kind: item.kind,
                id: item.mediaOwnerID,
                reference: item.mediaReference
            )
        }
        .onChange(of: hasDate) { _, _ in clearInvalidEventSelection() }
        .onChange(of: date) { _, _ in clearInvalidEventSelection() }
        .interactiveDismissDisabled(!pendingRestore.isEmpty || isDeleting)
        .confirmationDialog(
            ChekinanaProductCopy.format(
                "gallery.media.delete.confirm",
                "Delete this %@?",
                item.typeName
            ),
            isPresented: $isDeleteConfirmationPresented,
            titleVisibility: .visible
        ) {
            Button(
                ChekinanaProductCopy.text("common.delete", "Delete"),
                role: .destructive
            ) { Task { await deleteMedia() } }
            Button(
                ChekinanaProductCopy.text("common.cancel", "Cancel"),
                role: .cancel
            ) {}
        }
        .chekinanaSheetDraftDismiss(
            ready: didLoadMetadata,
            isBusy: { !pendingRestore.isEmpty || isDeleting },
            snapshot: { [AnyHashable(idolIDs), AnyHashable(hasDate), AnyHashable(hasDate ? date : nil), AnyHashable(eventID), AnyHashable(userAppears), AnyHashable(isFavorite), AnyHashable(hasPostedToSNS), AnyHashable(note)] }
        )
    }

    private var visibleIdolSelection: Binding<Set<UUID>> {
        Binding(
            get: { idolIDs.subtracting(hiddenIdols.hiddenIDs) },
            set: { idolIDs = $0.union(idolIDs.intersection(hiddenIdols.hiddenIDs)) }
        )
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    private var draftCanonicalDate: Date? {
        guard hasDate else { return nil }
        return ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
    }

    private func clearInvalidEventSelection() {
        eventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
            eventID,
            recordDate: draftCanonicalDate,
            events: events
        )
    }

    private func save() {
        let normalizedDate = hasDate
            ? ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
            : nil
        if hasDate, normalizedDate == nil {
            message = ChekinanaL10n.text("product.error.normalize_date", fallback: "Unable to normalize the selected date.")
            return
        }
        do {
            let selectedIdols = try ChekinanaModelContextResolver.idols(
                idolIDs: idolIDs,
                preservingExistingIDs: item.idolIDs.intersection(Set(
                    try ChekinanaModelContextResolver.mediaItem(id: item.id, in: modelContext).idolIDs
                )),
                in: modelContext
            )
            switch item.kind {
            case .shame:
                let value = try ChekinanaModelContextResolver.shame(
                    id: item.id,
                    in: modelContext
                )
                value.idols = selectedIdols
                value.date = normalizedDate
                value.eventID = eventID
                value.userAppears = userAppears
                value.isFavorite = isFavorite
                value.hasPostedToSNS = hasPostedToSNS
                value.note = note
                try ChekinanaEventAssociationPropagation.propagate(
                    from: value,
                    in: modelContext
                )
            case .douga:
                let value = try ChekinanaModelContextResolver.douga(
                    id: item.id,
                    in: modelContext
                )
                value.idols = selectedIdols
                value.date = normalizedDate
                value.eventID = eventID
                value.userAppears = userAppears
                value.isFavorite = isFavorite
                value.hasPostedToSNS = hasPostedToSNS
                value.note = note
                try ChekinanaEventAssociationPropagation.propagate(
                    from: value,
                    in: modelContext
                )
            }
            try mediaEditHooks.save(modelContext)
            mediaEditHooks.didSave(item.id)
            dismiss()
        } catch {
            modelContext.rollback()
            message = error.localizedDescription
        }
    }

    private var managedURL: URL? {
        ChekinanaGalleryMediaStore.managedURL(
            for: item.mediaReference,
            id: item.mediaOwnerID,
            kind: item.kind
        )
    }

    private func exportMedia() {
        guard let managedURL else {
            message = ChekinanaGalleryMediaStoreError.missingManagedFile.localizedDescription
            return
        }
        Task {
            do {
                switch item.kind {
                case .shame:
                    try await ChekinanaProductPhotoSaver.saveImage(at: managedURL)
                case .douga:
                    try await ChekinanaProductPhotoSaver.saveVideo(at: managedURL)
                }
            } catch {
                message = error.localizedDescription
            }
        }
    }

    @MainActor
    private func deleteMedia() async {
        guard !isDeleting, pendingRestore.isEmpty else { return }
        isDeleting = true
        defer { isDeleting = false }
        do {
            try await ChekinanaGalleryDeletionCoordinator.delete(
                kind: item.kind,
                mediaOwnerID: item.mediaOwnerID,
                reference: item.mediaReference,
                in: modelContext,
                validateModel: {
                    let current: MediaItem
                    switch item.kind {
                    case .shame:
                        current = try ChekinanaModelContextResolver.shame(
                            id: item.id,
                            in: modelContext
                        )
                    case .douga:
                        current = try ChekinanaModelContextResolver.douga(
                            id: item.id,
                            in: modelContext
                        )
                    }
                    guard current.mediaOwnerID == item.mediaOwnerID,
                          current.mediaRef == item.mediaReference else {
                        throw ChekinanaImportTransactionError.indeterminate
                    }
                },
                deleteModel: {
                    switch item.kind {
                    case .shame:
                        let value = try ChekinanaModelContextResolver.shame(
                            id: item.id,
                            in: modelContext
                        )
                        modelContext.delete(value)
                    case .douga:
                        let value = try ChekinanaModelContextResolver.douga(
                            id: item.id,
                            in: modelContext
                        )
                        modelContext.delete(value)
                    }
                }
            )
            dismiss()
            onDeleted?()
        } catch {
            pendingRestore = ChekinanaGalleryMediaStore.restoreRecoveryFiles(
                kind: item.kind,
                id: item.mediaOwnerID,
                reference: item.mediaReference
            )
            message = error.localizedDescription
        }
    }

    @MainActor
    private func retryRecovery() async {
        guard !pendingRestore.isEmpty else { return }
        do {
            try await ChekinanaGalleryDeletionCoordinator.recoverPending(
                pendingRestore,
                in: modelContext
            )
            pendingRestore = []
            message = ChekinanaProductCopy.text(
                "gallery.media.recovery_complete",
                "Media recovery completed."
            )
        } catch {
            message = ChekinanaProductCopy.format(
                "gallery.media.error.restore_required",
                "The delete failed and the media could not be restored. Retry recovery before closing: %@",
                error.localizedDescription
            )
        }
    }

}

private enum ChekinanaProductPhotoSaver {
    static func authorizeAdding() async throws {
        let status = await PHPhotoLibrary.requestAuthorization(for: .addOnly)
        guard status == .authorized || status == .limited else {
            throw ChekinanaProductPhotoSaveError.notAuthorized
        }
    }

    static func saveAuthorizedFile(at url: URL, isVideo: Bool) async throws {
        try Task.checkCancellation()
        guard ChekiImageRefResolver.isRegularReadableFile(url) else {
            throw ChekinanaGalleryMediaStoreError.missingManagedFile
        }
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            PHPhotoLibrary.shared().performChanges {
                let request = PHAssetCreationRequest.forAsset()
                let options = PHAssetResourceCreationOptions()
                options.shouldMoveFile = false
                request.addResource(with: isVideo ? .video : .photo, fileURL: url, options: options)
            } completionHandler: { success, error in
                if success { continuation.resume(returning: ()) }
                else { continuation.resume(throwing: error ?? ChekinanaProductPhotoSaveError.failed) }
            }
        }
    }

    static func saveImages(_ images: [Data]) async throws {
        guard !images.isEmpty else { return }
        let status = await PHPhotoLibrary.requestAuthorization(for: .addOnly)
        guard status == .authorized || status == .limited else {
            throw ChekinanaProductPhotoSaveError.notAuthorized
        }
        try Task.checkCancellation()
        try await withCheckedThrowingContinuation { continuation in
            PHPhotoLibrary.shared().performChanges {
                for image in images {
                    let request = PHAssetCreationRequest.forAsset()
                    request.addResource(with: .photo, data: image, options: nil)
                }
            } completionHandler: { success, error in
                if success {
                    continuation.resume(returning: ())
                } else {
                    continuation.resume(
                        throwing: error ?? ChekinanaProductPhotoSaveError.failed
                    )
                }
            }
        }
        try Task.checkCancellation()
    }

    static func saveImage(at url: URL) async throws {
        let status = await PHPhotoLibrary.requestAuthorization(for: .addOnly)
        guard status == .authorized || status == .limited else {
            throw ChekinanaProductPhotoSaveError.notAuthorized
        }
        try await withCheckedThrowingContinuation { continuation in
            PHPhotoLibrary.shared().performChanges {
                PHAssetChangeRequest.creationRequestForAssetFromImage(atFileURL: url)
            } completionHandler: { success, error in
                if success {
                    continuation.resume(returning: ())
                } else {
                    continuation.resume(throwing: error ?? ChekinanaProductPhotoSaveError.failed)
                }
            }
        }
    }

    static func saveVideo(at url: URL) async throws {
        let status = await PHPhotoLibrary.requestAuthorization(for: .addOnly)
        guard status == .authorized || status == .limited else {
            throw ChekinanaProductPhotoSaveError.notAuthorized
        }
        try await withCheckedThrowingContinuation { continuation in
            PHPhotoLibrary.shared().performChanges {
                PHAssetChangeRequest.creationRequestForAssetFromVideo(atFileURL: url)
            } completionHandler: { success, error in
                if success {
                    continuation.resume(returning: ())
                } else {
                    continuation.resume(
                        throwing: error ?? ChekinanaProductPhotoSaveError.failed
                    )
                }
            }
        }
    }
}

private enum ChekinanaProductPhotoSaveError: LocalizedError {
    case notAuthorized
    case failed

    var errorDescription: String? {
        switch self {
        case .notAuthorized: ChekinanaL10n.message("Photos access is not authorized.")
        case .failed: ChekinanaL10n.message("The media could not be saved to Photos.")
        }
    }
}

private struct ChekinanaIdolSelectionOption: Identifiable, Hashable {
    let id: UUID
    let name: String
    let group: String?
    let color: String?
    let avatarImageRef: String?

    init(_ idol: Idol) {
        id = idol.id
        name = idol.name
        group = idol.group
        color = idol.color
        avatarImageRef = idol.avatarImageRef
    }
}

enum ChekinanaRequiredIdolSelectionPolicy {
    static func resolvedIDs(
        selectedIDs: Set<UUID>,
        visibleIDs: [UUID]
    ) -> [UUID] {
        var seen = Set<UUID>()
        return visibleIDs.filter {
            selectedIDs.contains($0) && seen.insert($0).inserted
        }
    }
}

private struct ChekinanaIdolSelectionView: View {
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Environment(\.dismiss) private var dismiss
    @Query private var storedIdols: [Idol]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" })
    private var mediaChekis: [MediaItem]
    @Query private var simpleRecords: [ChekiRecord]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let options: [ChekinanaIdolSelectionOption]
    @Binding var selectedIDs: Set<UUID>



    private var orderedOptions: [ChekinanaIdolSelectionOption] {
        let optionByID = Dictionary(uniqueKeysWithValues: options.map { ($0.id, $0) })
        let allowed = storedIdols.filter { optionByID[$0.id] != nil }
        return ChekinanaIdolSelectionOrdering.ordered(
            allowed,
            mediaChekis: mediaChekis,
            simpleRecords: simpleRecords,
            hiddenIDs: hiddenIdols.hiddenIDs,
            preferredID: idolOrdering.preferredID
        ).compactMap { optionByID[$0.id] }
    }

    var body: some View {
        NavigationStack {
            ChekinanaIdolPickerContent(
                options: orderedOptions, selectedIDs: $selectedIDs,
                identifierPrefix: "chekinana.gallery.editor.idol-option"
            )
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) {
                        dismiss()
                    }
                        .accessibilityIdentifier("chekinana.gallery.editor.idols.done")
                }
            }
        }
        .accessibilityIdentifier("chekinana.gallery.editor.idol-selection")
        .chekinanaSheetDraftDismiss(
            snapshot: { [AnyHashable(selectedIDs)] },
            onDiscard: { initial in if let value = initial[0].base as? Set<UUID> { selectedIDs = value }; dismiss() }
        )
    }


}

private enum ChekinanaChekiEventPrimaryScope: Equatable {
    case nearby
    case exactDate
}

