private struct ChekinanaCompactEditorRowModifier: ViewModifier {
    let showsDivider: Bool

    @ViewBuilder
    func body(content: Content) -> some View {
        if showsDivider {
            compact(content)
                .listRowSeparator(.visible)
                .listRowSeparatorTint(Color.secondary.opacity(0.22))
        } else {
            compact(content)
        }
    }

    private func compact(_ content: Content) -> some View {
        content
            .frame(minHeight: 38)
            .listRowInsets(
                EdgeInsets(top: 5, leading: 16, bottom: 5, trailing: 16)
            )
    }
}

private extension View {
    func chekinanaCompactEditorRow(showsDivider: Bool = false) -> some View {
        modifier(ChekinanaCompactEditorRowModifier(showsDivider: showsDivider))
    }
}

private struct ChekinanaSizeSelectionField: View {
