struct ChekinanaChekiEventSelectionRevision: Equatable {
    struct EventValue: Hashable {
        let id: UUID
        let date: Date?
        let name: String
    }

    struct ScheduleValue: Hashable {
        let eventID: UUID
        let openTime: String?
        let startTime: String?
    }

    let eventValues: Set<EventValue>
    let scheduleValues: Set<ScheduleValue>

    init(events: [Event], schedules: [EventSchedule]) {
        eventValues = Set(events.map {
            EventValue(id: $0.id, date: $0.date, name: $0.name)
        })
        scheduleValues = Set(schedules.map {
            ScheduleValue(
                eventID: $0.eventID,
                openTime: $0.openTime,
                startTime: $0.startTime
            )
        })
    }
}

private struct ChekinanaChekiEventSelectionField: View {
    @Binding var eventID: UUID?
    let recordDate: Date?
    let events: [Event]
    let schedules: [EventSchedule]
    let primaryScope: ChekinanaChekiEventPrimaryScope
    @State private var isAllEventsPresented = false
    @State private var cache = PresentationCache()

    @MainActor
    private final class PresentationCache {
        private struct Key: Equatable {
            let calendar: Calendar
            let localeIdentifier: String
            let date: Date?
            let scope: ChekinanaChekiEventPrimaryScope
            let events: [ChekinanaChekiEventSelectionRevision.EventValue]
            let schedules: [ChekinanaChekiEventSelectionRevision.ScheduleValue]
            let eventObjects: [ObjectIdentifier]
        }
        private var key: Key?
        private var primary: [Event] = []
        private var names: [UUID: String] = [:]

        func resolve(date: Date?, scope: ChekinanaChekiEventPrimaryScope,
                     events: [Event], schedules: [EventSchedule]) -> ([Event], [UUID: String]) {
            let next = Key(calendar: .current, localeIdentifier: Locale.current.identifier,
                date: date, scope: scope,
                events: events.map { .init(id: $0.id, date: $0.date, name: $0.name) },
                schedules: schedules.map {
                    .init(eventID: $0.eventID, openTime: $0.openTime, startTime: $0.startTime)
                }, eventObjects: events.map { ObjectIdentifier($0) })
            if next != key {
                primary = ChekinanaChekiEventSelectionField.primaryEvents(
                    scope: scope, events: events, schedules: schedules, recordDate: date
                )
                names = Dictionary(events.map { ($0.id, $0.name) },
                                   uniquingKeysWith: { current, _ in current })
                key = next
            }
            return (primary, names)
        }
    }

    init(
        eventID: Binding<UUID?>,
        recordDate: Date?,
        events: [Event],
        schedules: [EventSchedule],
        primaryScope: ChekinanaChekiEventPrimaryScope = .nearby
    ) {
        _eventID = eventID
        self.recordDate = recordDate
        self.events = events
        self.schedules = schedules
        self.primaryScope = primaryScope
    }

    var body: some View {
        let (cachedPrimaryEvents, cachedEventNames) = cache.resolve(
            date: recordDate, scope: primaryScope, events: events, schedules: schedules
        )
        let selectedName = eventID.flatMap { cachedEventNames[$0] }
        let selectedTitle = selectedName ?? ChekinanaProductCopy.text("common.none", "None")
        let hasResolvedSelection = selectedName != nil
        return Menu {
            Button(ChekinanaProductCopy.text("common.none", "None")) {
                eventID = nil
            }
            ForEach(cachedPrimaryEvents) { event in
                Button {
                    eventID = event.id
                } label: {
                    if event.id == eventID {
                        Label(event.name, systemImage: "checkmark")
                    } else {
                        Text(event.name)
                    }
                }
            }
            Divider()
            Button {
                isAllEventsPresented = true
            } label: {
                Label(
                    ChekinanaProductCopy.text("common.other", "Other"),
                    systemImage: "ellipsis"
                )
            }
        } label: {
            ChekinanaMetadataSelectionRow(
                label: ChekinanaProductCopy.text("events.event", "Event"),
                value: selectedTitle,
                valueIsResolved: hasResolvedSelection
            )
        }
        .sheet(isPresented: $isAllEventsPresented) {
            ChekinanaAllEventSelectionView(
                eventID: $eventID,
                events: events,
                schedules: schedules
            )
        }
    }

    private static func primaryEvents(
        scope: ChekinanaChekiEventPrimaryScope,
        events: [Event],
        schedules: [EventSchedule],
        recordDate: Date?
    ) -> [Event] {
        switch scope {
        case .nearby:
            ChekinanaChekiEventSelectionPolicy.eligibleEvents(
                events,
                schedules: schedules,
                for: recordDate
            )
        case .exactDate:
            ChekinanaChekiEventSelectionPolicy.eventsOnExactDate(
                events,
                schedules: schedules,
                for: recordDate
            )
        }
    }
}

