private struct ChekinanaChekiEditorView: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.chekinanaMediaEditHooks) private var mediaEditHooks
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query(sort: \Idol.name) private var idols: [Idol]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let cheki: MediaItem
    var allowsDelete = true
    var onDelete: (() -> Void)? = nil
    private let initialSnapshot: ChekinanaChekiEditRecordSnapshot

    @State private var idolIDs: Set<UUID>
    @State private var hasDate: Bool
    @State private var date: Date
    @State private var eventID: UUID?
    @State private var userAppears: Bool
    @State private var size: ChekiSize?
    @State private var isFavorite: Bool
    @State private var hasPostedToSNS: Bool
    @State private var note: String
    @State private var message: String?
    @State private var isSaving = false
    @State private var editAuthorization: ChekinanaChekiEditAuthorization?
    @State private var isIdolSelectionPresented = false
    @State private var confirmationLedger = ChekinanaConfirmationLedger()
    @State private var pendingDeleteConfirmationCode: String?
    @State private var isDeleteConfirmationPresented = false

    init(
        cheki: MediaItem,
        allowsDelete: Bool = true,
        onDelete: (() -> Void)? = nil
    ) {
        self.cheki = cheki
        self.allowsDelete = allowsDelete
        self.onDelete = onDelete
        initialSnapshot = ChekinanaChekiEditRecordSnapshot(cheki)
        _idolIDs = State(initialValue: Set(cheki.idols.map(\.id)))
        _hasDate = State(initialValue: cheki.date != nil)
        _date = State(initialValue: cheki.date.flatMap {
            ChekinanaDateOnly.displayDate(from: $0, calendar: .current)
        } ?? Date())
        _eventID = State(initialValue: cheki.event?.id)
        _userAppears = State(initialValue: cheki.userAppears)
        _size = State(initialValue: cheki.size ?? .mini)
        _isFavorite = State(initialValue: cheki.isFavorite)
        _hasPostedToSNS = State(initialValue: cheki.hasPostedToSNS)
        _note = State(initialValue: cheki.note)
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    ChekinanaPhotoSaveFeedbackButton(action: exportImage)
                    .accessibilityIdentifier("chekinana.gallery.editor.export")
                }
                Section(ChekinanaProductCopy.text("common.idols", "Idols")) {
                    ChekinanaIdolSelectionSummaryButton(
                        idols: visibleIdols.filter { idolIDs.contains($0.id) },
                        identifier: "chekinana.gallery.editor.change-idols"
                    ) { isIdolSelectionPresented = true }
                }
                Section {
                    ChekinanaChekiEditorFields(
                        visibleIdols: visibleIdols,
                        events: events,
                        schedules: eventSchedules,
                        identifierPrefix: "chekinana.gallery.editor",
                        chooseIdols: { isIdolSelectionPresented = true },
                        idolIDs: $idolIDs,
                        hasDate: $hasDate,
                        date: $date,
                        eventID: $eventID,
                        userAppears: $userAppears,
                        size: $size,
                        isFavorite: $isFavorite,
                        hasPostedToSNS: $hasPostedToSNS,
                        note: $note
                    )
                    if let message {
                        ChekinanaInlineStatus(message: message, kind: .error)
                    }
                }
                if allowsDelete {
                    Section {
                        Button(
                            deleteRecoveryRequired
                                ? ChekinanaProductCopy.text(
                                    "common.retry_recovery",
                                    "Retry recovery"
                                )
                                : ChekinanaProductCopy.text("common.delete", "Delete"),
                            role: .destructive
                        ) {
                            isDeleteConfirmationPresented = true
                        }
                        .foregroundStyle(.red)
                        .buttonStyle(ChekinanaTextActionPressFeedbackStyle())
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .accessibilityIdentifier("chekinana.gallery.editor.delete")
                    }
                }
            }
            .disabled(isSaving)
            .chekinanaGroupedPageBackground()
            .navigationTitle(
                ChekinanaProductCopy.format(
                    "calendar.edit_record",
                    "Edit %@",
                    ChekinanaRecordKind.cheki.title
                )
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        dismiss()
                    }
                        .disabled(!canDismiss)
                        .accessibilityIdentifier("chekinana.gallery.editor.cancel")
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.save", "Save")) {
                        Task { await save() }
                    }
                        .disabled(isSaving || editAuthorization == nil)
                        .accessibilityIdentifier("chekinana.gallery.editor.save")
                }
            }
        }
        .accessibilityIdentifier("chekinana.gallery.editor")
        .accessibilityValue(cheki.id.uuidString.lowercased())
        .interactiveDismissDisabled(!canDismiss)
        .task { await prepareEditAuthorization() }
        .sheet(isPresented: $isIdolSelectionPresented) {
            ChekinanaIdolSelectionView(
                options: visibleIdols.map(ChekinanaIdolSelectionOption.init),
                selectedIDs: visibleIdolSelection
            )
        }
        .onChange(of: hasDate) { _, _ in clearInvalidEventSelection() }
        .onChange(of: date) { _, _ in clearInvalidEventSelection() }
        .alert(
            ChekinanaProductCopy.text(
                "gallery.delete_confirmation.title",
                "Delete this item?"
            ),
            isPresented: $isDeleteConfirmationPresented
        ) {
            Button(
                ChekinanaProductCopy.text("common.delete", "Delete"),
                role: .destructive
            ) {
                Task { await delete() }
            }
            .disabled(isSaving)
            Button(
                ChekinanaProductCopy.text("common.cancel", "Cancel"),
                role: .cancel
            ) {}
        }
        .chekinanaSheetDraftDismiss(
            isBusy: { !canDismiss },
            snapshot: { [AnyHashable(idolIDs), AnyHashable(hasDate), AnyHashable(hasDate ? date : nil), AnyHashable(eventID), AnyHashable(userAppears), AnyHashable(isFavorite), AnyHashable(hasPostedToSNS), AnyHashable(note), AnyHashable(size)] }
        )
    }

    private var visibleIdolSelection: Binding<Set<UUID>> {
        Binding(
            get: { idolIDs.subtracting(hiddenIdols.hiddenIDs) },
            set: { idolIDs = $0.union(idolIDs.intersection(hiddenIdols.hiddenIDs)) }
        )
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    private var draftCanonicalDate: Date? {
        guard hasDate else { return nil }
        return ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
    }

    private func clearInvalidEventSelection() {
        eventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
            eventID,
            recordDate: draftCanonicalDate,
            events: events
        )
    }

    @MainActor
    private func save() async {
        guard !isSaving, let editAuthorization else { return }
        isSaving = true
        defer { isSaving = false }
        let normalizedDate = hasDate
            ? ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
            : nil
        if hasDate, normalizedDate == nil {
            message = ChekinanaProductCopy.text(
                "error.normalize_date",
                "Unable to normalize the selected date."
            )
            return
        }
        let validEventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
            eventID,
            recordDate: normalizedDate,
            events: events
        )
        let effectiveSize = size ?? .mini
        var edited = Set<ChekinanaChekiEditableField>()
        if idolIDs != Set(initialSnapshot.idolIDs) { edited.insert(.idols) }
        if normalizedDate != initialSnapshot.date { edited.insert(.date) }
        if validEventID != initialSnapshot.eventID { edited.insert(.event) }
        if userAppears != initialSnapshot.userAppears { edited.insert(.userAppears) }
        if effectiveSize.rawValue != initialSnapshot.sizeRawValue { edited.insert(.size) }
        if isFavorite != initialSnapshot.isFavorite { edited.insert(.favorite) }
        if hasPostedToSNS != initialSnapshot.hasPostedToSNS { edited.insert(.posted) }
        if note != initialSnapshot.note { edited.insert(.note) }
        guard !edited.isEmpty else {
            dismiss()
            return
        }

        var imageReplacement: ChekinanaChekiImageReplacementTransaction?
        do {
            let originalImageRef = editAuthorization.record.mediaRef
            if edited.contains(.size) {
                imageReplacement = try await ChekinanaChekiImageReplacementTransaction.stage(
                    currentImageRef: editAuthorization.record.mediaRef,
                    mediaOwnerID: editAuthorization.record.mediaOwnerID,
                    size: effectiveSize
                )
            }
            _ = try await ChekinanaChekiEditCommitter.commit(
                authorization: editAuthorization,
                imageReplacement: imageReplacement,
                in: modelContext,
                saveContext: { try mediaEditHooks.save($0) }
            ) { target in
                let finalIdolIDs = edited.contains(.idols)
                    ? idolIDs : Set(target.idolIDs)
                let finalEventID = edited.contains(.event)
                    ? validEventID : target.eventID
                let finalDate = edited.contains(.date)
                    ? normalizedDate : target.date
                let relationships = try ChekinanaModelContextResolver.relationships(
                    idolIDs: finalIdolIDs,
                    eventID: finalEventID,
                    preservingExistingIDs: Set(target.idolIDs),
                    in: modelContext
                )
                guard finalEventID == nil || relationships.event != nil else {
                    throw ChekinanaChekiEditCommitError.changedRecord
                }
                if edited.contains(.idols) { target.idols = relationships.idols }
                if edited.contains(.date) { target.date = finalDate }
                if edited.contains(.event) { target.event = relationships.event }
                if edited.contains(.userAppears) { target.userAppears = userAppears }
                if edited.contains(.size) { target.size = effectiveSize }
                if edited.contains(.favorite) { target.isFavorite = isFavorite }
                if edited.contains(.posted) {
                    target.hasPostedToSNS = hasPostedToSNS
                }
                if edited.contains(.note) { target.note = note }
                return !edited.isDisjoint(with: [.idols, .event, .date])
            }
            mediaEditHooks.didSave(cheki.id)
            await ChekinanaThumbnailCache.shared.invalidate(imageRef: originalImageRef)
            await ChekinanaThumbnailCache.shared.invalidate(
                imageRef: imageReplacement?.imageRef
            )
            dismiss()
        } catch {
            message = error.localizedDescription
        }
    }

    @MainActor
    private func prepareEditAuthorization() async {
        guard editAuthorization == nil else { return }
        do {
            editAuthorization = try await ChekinanaChekiEditCommitter.authorize(
                expected: initialSnapshot,
                in: modelContext
            )
        } catch {
            message = error.localizedDescription
        }
    }

    private var deleteRecoveryRequired: Bool {
        guard let pendingDeleteConfirmationCode else { return false }
        return confirmationLedger.cancellationRequiresRecovery(
            pendingDeleteConfirmationCode
        )
    }

    private var canDismiss: Bool {
        !isSaving && ChekinanaGalleryDeleteDismissPolicy.canDismiss(
            pendingConfirmationCode: pendingDeleteConfirmationCode,
            recoveryRequired: deleteRecoveryRequired
        )
    }

    private func exportImage() {
        guard let url = ChekiImageRefResolver.managedChekiFileURL(
            for: cheki.imageRef,
            chekiID: cheki.mediaOwnerID
        ) ?? ChekiImageRefResolver.localFileURL(for: cheki.imageRef) else {
            message = ChekinanaProductCopy.text(
                "gallery.image_unavailable",
                "The stored image is unavailable."
            )
            return
        }
        Task {
            do {
                try await ChekinanaProductPhotoSaver.saveImage(at: url)
            } catch {
                message = error.localizedDescription
            }
        }
    }

    @MainActor
    private func delete() async {
        guard !isSaving else { return }
        let executor = ChekinanaCommandExecutor(
            modelContext: modelContext,
            confirmationLedger: confirmationLedger
        )
        let code: String
        if let pendingDeleteConfirmationCode {
            code = pendingDeleteConfirmationCode
        } else {
            let prepared = await executor.execute(
                "deletecheki \(cheki.id.uuidString.lowercased())"
            )
            guard let preparedCode = ChekinanaConfirmationResponseValidator
                .deleteChekiConfirmationCode(
                    from: prepared,
                    expectedChekiID: cheki.id
                ) else {
                message = ChekinanaConfirmationResponseValidator.failureDescription(
                    for: prepared,
                    fallback: ChekinanaProductCopy.text(
                        "gallery.delete_prepare_failed",
                        "Unable to prepare this Cheki for deletion."
                    )
                )
                return
            }
            pendingDeleteConfirmationCode = preparedCode
            code = preparedCode
        }
        let result = await executor.execute("confirm \(code)")
        guard ChekinanaConfirmationResponseValidator.isDeleteChekiSuccess(result) else {
            if confirmationLedger.entry(for: code) == nil {
                pendingDeleteConfirmationCode = nil
            }
            message = ChekinanaConfirmationResponseValidator.failureDescription(
                for: result,
                fallback: ChekinanaProductCopy.text(
                    "gallery.delete_failed",
                    "Unable to delete this Cheki."
                )
            )
            return
        }
        pendingDeleteConfirmationCode = nil
        onDelete?()
        dismiss()
    }
}

/// Observation invalidates scalar changes without rescanning every model field
/// whenever the user changes only the selected day or displayed month.
private final class ChekinanaCalendarMetricInvalidation: @unchecked Sendable {
    private let lock = NSLock()
    private var invalidated = false
    func invalidate() { lock.lock(); invalidated = true; lock.unlock() }
    var isInvalidated: Bool {
        lock.lock(); defer { lock.unlock() }; return invalidated
    }
}

@MainActor
private final class ChekinanaCalendarMetricsCache: ObservableObject {
    private struct Identity: Equatable {
        let chekis: [ObjectIdentifier]
        let records: [ObjectIdentifier]
        let events: [ObjectIdentifier]
        let hiddenIDs: Set<UUID>
        let calendar: Calendar
    }
    private var identity: Identity?
    private var invalidation = ChekinanaCalendarMetricInvalidation()
    private var cached: ChekinanaCalendarMonthMetrics?

    func invalidateAfterEditing() {
        invalidation.invalidate()
        objectWillChange.send()
    }

    func metrics(chekis: [MediaItem], records: [ChekiRecord], events: [Event],
                 hiddenIDs: Set<UUID>) -> ChekinanaCalendarMonthMetrics {
        let next = Identity(chekis: chekis.map(ObjectIdentifier.init),
                            records: records.map(ObjectIdentifier.init),
                            events: events.map(ObjectIdentifier.init), hiddenIDs: hiddenIDs,
                            calendar: ChekinanaProductDate.calendar)
        if identity == next, !invalidation.isInvalidated, let cached { return cached }
        let token = ChekinanaCalendarMetricInvalidation()
        let value = withObservationTracking {
            ChekinanaCalendarMonthMetrics(chekis: chekis, records: records,
                                          events: events, hiddenIDs: hiddenIDs)
        } onChange: { [weak self, token] in
            token.invalidate()
            Task { @MainActor [weak self] in self?.objectWillChange.send() }
        }
        identity = next
        invalidation = token
        cached = value
        return value
    }
}

struct ChekinanaCalendarMonthMetrics {
    private let eventDateKeys: Set<String>
    private let chekiCountByDateKey: [String: Int]

    init(
        chekis: [MediaItem],
        records: [ChekiRecord],
        events: [Event],
        hiddenIDs: Set<UUID>
    ) {
        eventDateKeys = Set(events.compactMap { event in
            event.date.map(ChekinanaProductDate.key)
        })
        var counts: [String: Int] = [:]
        for cheki in chekis
        where cheki.imageRef?.nonEmpty != nil
            && ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: cheki.idolIDs,
                hiddenIDs: hiddenIDs
            ) {
            guard let date = cheki.date else { continue }
            Self.increment(
                &counts,
                key: ChekinanaProductDate.key(date),
                by: 1
            )
        }
        for record in records
        where ChekinanaFourPageVisibilityPolicy.includesRecord(
            idolIDs: record.idolIDs,
            hiddenIDs: hiddenIDs
        ) {
            guard let date = record.date else { continue }
            Self.increment(
                &counts,
                key: ChekinanaProductDate.key(date),
                by: record.count
            )
        }
        chekiCountByDateKey = counts
    }

    func hasEvent(on date: Date) -> Bool {
        eventDateKeys.contains(ChekinanaProductDate.key(date))
    }

    func chekiCount(on date: Date) -> Int {
        chekiCountByDateKey[ChekinanaProductDate.key(date), default: 0]
    }

    func chekiCount(inMonth month: Date) -> Int {
        let first = ChekinanaProductDate.startOfMonth(containing: month)
        let calendar = ChekinanaProductDate.calendar
        guard let days = calendar.range(of: .day, in: .month, for: first) else { return 0 }
        return ChekinanaDisplayCount.total(days.compactMap { day in
            calendar.date(byAdding: .day, value: day - 1, to: first).map { chekiCount(on: $0) }
        })
    }

    private static func increment(
        _ counts: inout [String: Int],
        key: String,
        by value: Int
    ) {
        counts[key] = ChekinanaDisplayCount.adding(
            counts[key, default: 0],
            value
        )
    }
}

enum ChekinanaCalendarMonthIdolStatistics {
    struct Row: Identifiable, Equatable {
        let idolID: UUID?
        let count: Int
        var id: String { idolID?.uuidString ?? "unassigned" }
    }

    static func rows(
        inMonth month: Date,
        chekis: [MediaItem],
        records: [ChekiRecord],
        hiddenIDs: Set<UUID>
    ) -> [Row] {
        let calendar = ChekinanaProductDate.calendar
        var counts: [UUID: Int] = [:]
        var unassigned = 0
        func add(date: Date?, idolIDs: [UUID], quantity: Int) {
            guard let date,
                  calendar.isDate(date, equalTo: month, toGranularity: .month),
                  ChekinanaFourPageVisibilityPolicy.includesRecord(idolIDs: idolIDs, hiddenIDs: hiddenIDs) else { return }
            let quantity = ChekinanaDisplayCount.normalized(quantity)
            if idolIDs.isEmpty {
                unassigned = ChekinanaDisplayCount.adding(unassigned, quantity)
            } else {
                for id in Set(idolIDs).subtracting(hiddenIDs) {
                    counts[id] = ChekinanaDisplayCount.adding(counts[id, default: 0], quantity)
                }
            }
        }
        for cheki in chekis where cheki.imageRef?.nonEmpty != nil {
            add(date: cheki.date, idolIDs: cheki.idolIDs, quantity: 1)
        }
        for record in records {
            add(date: record.date, idolIDs: record.idolIDs, quantity: record.count)
        }
        var result = counts.compactMap { id, count in
            count > 0 ? Row(idolID: id, count: count) : nil
        }
        if unassigned > 0 { result.append(Row(idolID: nil, count: unassigned)) }
        return result.sorted {
            if $0.count != $1.count { return $0.count > $1.count }
            return $0.id < $1.id
        }
    }
}

private struct ChekinanaCalendarMonthIdolStatisticsView: View {
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    let month: Date
    @Environment(\.dismiss) private var dismiss
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.chekinanaThemeRevision) private var themeRevision
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }) private var chekis: [MediaItem]
    @Query private var records: [ChekiRecord]
    @Query private var idols: [Idol]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared

    var body: some View {
        let _ = languageRevision
        let _ = themeRevision
        let rows = ChekinanaSingleOshiPreference.prioritized(
            ChekinanaCalendarMonthIdolStatistics.rows(
                inMonth: month, chekis: chekis, records: records, hiddenIDs: hiddenIdols.hiddenIDs
            ), preferredID: idolOrdering.preferredID,
            contains: { row, id in row.idolID == id }
        )
        let idolsByID = Dictionary(uniqueKeysWithValues: idols.map { ($0.id, $0) })
        NavigationStack {
            ScrollView {
                if rows.isEmpty {
                    Text(countLabel(0)).foregroundStyle(.secondary)
                        .frame(maxWidth: .infinity)
                        .padding(16)
                }
                Grid(alignment: .leading, horizontalSpacing: 24, verticalSpacing: 20) {
                    ForEach(rows) { row in
                        let idol = row.idolID.flatMap { idolsByID[$0] }
                        GridRow {
                            if let idol {
                                ChekinanaIdolAvatar(idol: idol, size: 44)
                            } else if row.idolID == nil {
                                Image(systemName: "person.slash")
                                    .font(.system(size: 22))
                                    .foregroundStyle(.secondary)
                                    .frame(width: 44, height: 44)
                                    .background(Color(uiColor: .tertiarySystemGroupedBackground), in: Circle())
                            } else {
                                ChekinanaNeutralIdolAvatar(size: 44)
                            }
                            Text(countLabel(row.count))
                                .monospacedDigit()
                                .lineLimit(1)
                        }
                        .accessibilityElement(children: .ignore)
                        .accessibilityLabel("\(idol?.name ?? ChekinanaProductCopy.text(row.idolID == nil ? "common.unassigned" : "common.idol", row.idolID == nil ? "Unassigned" : "Idol")), \(countLabel(row.count))")
                    }
                }
                .frame(maxWidth: .infinity, alignment: .center)
                .padding(16)
                .padding(.top, 4)
            }
            .background(ChekinanaProductTheme.pageBackground)
            .navigationTitle(ChekinanaProductDate.monthTitle(month))
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) { dismiss() }
                }
            }
        }
    }

    private func countLabel(_ count: Int) -> String {
        ChekinanaProductCopy.format("calendar.idol_cheki_count", "%lld cheki", Int64(count))
    }
}

private struct ChekinanaCalendarView: View {
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.chekinanaThemeRevision) private var themeRevision
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "cheki" }, sort: \MediaItem.date) private var chekis: [MediaItem]
    @Query(sort: \ChekiRecord.date) private var chekiRecords: [ChekiRecord]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "shame" }) private var shames: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @Query private var idols: [Idol]
    @Query private var calendarGroupOrders: [CalendarGroupOrder]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let openMenu: () -> Void
    @Binding var navigationDate: Date?

    @StateObject private var metricsCache = ChekinanaCalendarMetricsCache()
    @State private var displayedMonth = ChekinanaProductDate.startOfMonth(containing: ChekinanaProductDate.fixtureAwareToday)
    @State private var selectedDate = ChekinanaProductDate.fixtureAwareToday
    @State private var selectedGroupEditor: ChekinanaCalendarGroupEditorSelection?
    @State private var isAddingRecord = false
    @State private var isMonthStatisticsPresented = false
    @State private var isMonthYearWheelExpanded = false
    @State private var monthYearWheelDraft: ChekinanaCalendarMonthYearDraft?
    @State private var isUndatedUnassignedPresented = false
    @State private var reorderErrorMessage: String?
    @State private var selectedEvent: Event?
    @State private var pendingEventDeletionID: UUID?
    @State private var eventDeletionError: String?
#if DEBUG
    @State private var calendarGroupGestureDebugStates: [String: String] = [:]
#endif

    private var avatarSourceKey: String {
        let generations = calendarGroupOrders
            .filter { ChekinanaLibraryGenerationStore.isMarker($0) }
            .map(\.groupKey).sorted().joined(separator: "|")
        return "calendar-\(ObjectIdentifier(modelContext.container))|\(generations)"
    }

    private var cells: [ChekinanaCalendarCell] {
        ChekinanaProductDate.monthCells(for: displayedMonth)
    }

    private var selectedChekis: [MediaItem] {
        chekis.filter {
            $0.imageRef?.nonEmpty != nil
                && ChekinanaProductDate.isSameDay($0.date, selectedDate)
                && ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: $0.idolIDs,
                    hiddenIDs: hiddenIdols.hiddenIDs
                )
        }
    }

    private var selectedChekiRecords: [ChekiRecord] {
        chekiRecords.filter {
            ChekinanaProductDate.isSameDay($0.date, selectedDate)
                && ChekinanaFourPageVisibilityPolicy.includesRecord(
                    idolIDs: $0.idolIDs,
                    hiddenIDs: hiddenIdols.hiddenIDs
                )
        }.sorted { $0.id.uuidString < $1.id.uuidString }
    }

    private var selectedEvents: [Event] {
        ChekinanaEventOrdering.ordered(
            events.filter { ChekinanaProductDate.isSameDay($0.date, selectedDate) },
            schedules: eventSchedules,
            dateAscending: true
        )
    }
    private var selectedShames: [MediaItem] { shames.filter {
        ChekinanaProductDate.isSameDay($0.date, selectedDate)
            && ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: $0.idolIDs,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
    }.sorted { $0.id.uuidString < $1.id.uuidString } }
    private var selectedDougas: [MediaItem] { dougas.filter {
        ChekinanaProductDate.isSameDay($0.date, selectedDate)
            && ChekinanaFourPageVisibilityPolicy.includesRecord(
                idolIDs: $0.idolIDs,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
    }.sorted { $0.id.uuidString < $1.id.uuidString } }

    private struct SelectedDaySnapshot {
        let groups: [ChekinanaCalendarIdolGroup]
        let events: [Event]
        let chekiCount: Int
        let isEmpty: Bool
    }

    private var selectedDaySnapshot: SelectedDaySnapshot {
        let selectedChekis = self.selectedChekis
        let selectedRecords = selectedChekiRecords
        let selectedShames = self.selectedShames
        let selectedDougas = self.selectedDougas
        let selectedEvents = self.selectedEvents
        let groups = ChekinanaCalendarIdolGroup.groups(
            for: selectedChekis, records: selectedRecords,
            relationshipIndex: ChekinanaChekiRecordRelationshipIndex(idols: idols),
            groupsByExactIdolCombination: true, shames: selectedShames, dougas: selectedDougas,
            chekiCountsByIdolID: idolOrdering.chekiCountsByIdolID
        ).map { $0.displayingIdols(hiddenIDs: hiddenIdols.hiddenIDs) }
        let orderedKeys = ChekinanaCalendarGroupOrderPolicy.orderedGroupKeys(
            groups.map(\.combinationKey.id), dateKey: ChekinanaProductDate.key(selectedDate),
            orders: calendarGroupOrders
        )
        let byKey = Dictionary(uniqueKeysWithValues: groups.map { ($0.combinationKey.id, $0) })
        return SelectedDaySnapshot(
            groups: ChekinanaSingleOshiPreference.prioritized(
                orderedKeys.compactMap { byKey[$0] }, preferredID: idolOrdering.preferredID,
                contains: { group, id in group.orderedIdols.contains { $0.id == id } }
            ), events: selectedEvents,
            chekiCount: ChekinanaDisplayCount.adding(selectedChekis.count,
                ChekinanaChekiRecordStore.totalCount(selectedRecords)),
            isEmpty: selectedChekis.isEmpty && selectedRecords.isEmpty && selectedShames.isEmpty
                && selectedDougas.isEmpty && selectedEvents.isEmpty
        )
    }

    private var undatedUnassignedCount: Int {
        ChekinanaDisplayCount.total([
            ChekinanaChekiRecordStore.totalCount(chekiRecords.filter {
                ChekinanaChekiRecordReadPolicy.isUndatedAndUnassigned($0)
                    && ChekinanaChekiRecordReadPolicy.isVisible(
                        $0,
                        hiddenIDs: hiddenIdols.hiddenIDs
                    )
            }),
            shames.filter {
                $0.imageRef?.nonEmpty == nil && $0.idols.isEmpty && $0.date == nil
            }.count,
            dougas.filter {
                $0.videoRef?.nonEmpty == nil && $0.idols.isEmpty && $0.date == nil
            }.count,
        ])
    }

    @AppStorage(ChekinanaShotDisplayOrdering.defaultsKey) private var twoShotFirst = false

    var body: some View {
        let _ = twoShotFirst
        let undatedUnassignedCount = self.undatedUnassignedCount
        let monthMetrics = metricsCache.metrics(
            chekis: chekis,
            records: chekiRecords,
            events: events,
            hiddenIDs: hiddenIdols.hiddenIDs
        )
        let _ = languageRevision
        let _ = themeRevision
        NavigationStack {
            VStack(spacing: ChekinanaMainPageLayout.galleryHeaderToSegmentSpacing) {
                ChekinanaPinnedPageTitle(
                    title: ChekinanaProductCopy.text("calendar.title", "Calendar"),
                    identifier: "chekinana.calendar.fixed-title",
                    trailingText: ChekinanaProductCopy.format(
                        "calendar.month_cheki_count", "Selected month: %lld cheki",
                        Int64(monthMetrics.chekiCount(inMonth: displayedMonth))
                    ),
                    trailingAction: { isMonthStatisticsPresented = true }
                )
                ScrollView {
                    VStack(spacing: 16) {
                    calendarCard(metrics: monthMetrics)
                    if undatedUnassignedCount > 0 {
                        undatedUnassignedCard(count: undatedUnassignedCount)
                    }
                    selectedDayCard
                }
                .padding(.horizontal, 16)
                .padding(.bottom, 110)
                }
            }
            .background(ChekinanaProductTheme.pageBackground)
            .navigationTitle("")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ChekinanaPageToolbar(pageID: "calendar", openMenu: openMenu)
                ToolbarItem(placement: .topBarTrailing) {
                    Button { isAddingRecord = true } label: {
                        Image(systemName: "plus")
                            .frame(width: 44, height: 44)
                    }
                    .accessibilityLabel(
                        ChekinanaProductCopy.text("calendar.add_record", "Add record")
                    )
                    .accessibilityIdentifier("chekinana.calendar.add")
                    .frame(width: 88, alignment: .trailing)
                }
            }
            .sheet(item: $selectedGroupEditor, onDismiss: metricsCache.invalidateAfterEditing) { selection in
                ChekinanaCalendarGroupEditor(selection: selection)
            }
            .sheet(isPresented: $isMonthStatisticsPresented) {
                ChekinanaCalendarMonthIdolStatisticsView(month: displayedMonth)
            }
            .sheet(isPresented: $isAddingRecord, onDismiss: metricsCache.invalidateAfterEditing) {
                ChekinanaCalendarRecordEditor(initialDate: selectedDate)
            }
            .sheet(isPresented: $isUndatedUnassignedPresented, onDismiss: metricsCache.invalidateAfterEditing) {
                ChekinanaUndatedUnassignedRecordsView()
            }
            .sheet(item: $selectedEvent, onDismiss: deletePendingEvent) { event in
                ChekinanaEventDetailView(event: event) { eventID in
                    pendingEventDeletionID = eventID
                    selectedEvent = nil
                }
            }
            .alert(
                ChekinanaProductCopy.text("common.error", "Error"),
                isPresented: Binding(
                    get: { reorderErrorMessage != nil },
                    set: { if !$0 { reorderErrorMessage = nil } }
                )
            ) {
                Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
            } message: {
                Text(reorderErrorMessage ?? "")
            }
            .alert(
                ChekinanaProductCopy.text("common.error", "Error"),
                isPresented: Binding(
                    get: { eventDeletionError != nil },
                    set: { if !$0 { eventDeletionError = nil } }
                )
            ) {
                Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
            } message: {
                Text(eventDeletionError ?? "")
            }
        }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("chekinana.calendar.page")
        .chekinanaScreenMarker("chekinana.calendar.page")
        .environment(\.chekinanaDisplayHiddenIdolIDs, hiddenIdols.hiddenIDs)
        .onChange(of: navigationDate) { _, date in
            guard let date else { return }
            let boundedDate = ChekinanaCalendarDateBoundaryPolicy
                .clampedSelection(date)
            selectedDate = boundedDate
            displayedMonth = ChekinanaProductDate.startOfMonth(
                containing: boundedDate
            )
            isMonthYearWheelExpanded = false
            navigationDate = nil
        }
    }

    private func undatedUnassignedCard(count: Int) -> some View {
        ChekinanaSectionCard {
            Button {
                isUndatedUnassignedPresented = true
            } label: {
                HStack(spacing: 12) {
                    Image(systemName: "tray.full")
                        .foregroundStyle(ChekinanaProductTheme.accent)
                        .frame(width: 34, height: 34)
                        .background(ChekinanaProductTheme.accent.opacity(0.10))
                        .clipShape(RoundedRectangle(cornerRadius: 9))
                    VStack(alignment: .leading, spacing: 2) {
                        Text(ChekinanaProductCopy.text("calendar.undated_unassigned", "Undated & Unassigned"))
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(.primary)
                        Text(ChekinanaProductCopy.format("common.records_count", "%lld records", Int64(count)))
                            .font(.caption)
                            .foregroundStyle(.secondary)
                    }
                    Spacer()
                    Image(systemName: "chevron.right")
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(.tertiary)
                }
                .contentShape(Rectangle())
            }
            .buttonStyle(.plain)
            .accessibilityIdentifier("chekinana.calendar.undated-unassigned")
        }
    }

    private func calendarCard(metrics monthMetrics: ChekinanaCalendarMonthMetrics) -> some View {
        let accessibilityFormatter = DateFormatter()
        accessibilityFormatter.locale = ChekinanaLanguagePreference.displayLocale()
        var displayCalendar = Calendar(identifier: .gregorian)
        displayCalendar.locale = ChekinanaLanguagePreference.displayLocale()
        displayCalendar.timeZone = ChekinanaProductDate.calendar.timeZone
        accessibilityFormatter.calendar = displayCalendar
        accessibilityFormatter.timeZone = displayCalendar.timeZone
        accessibilityFormatter.setLocalizedDateFormatFromTemplate("yMMMMd")
        return ChekinanaSectionCard {
            VStack(spacing: 14) {
                HStack {
                    monthButton(systemImage: "chevron.left", offset: -1, id: "previous")
                    Spacer()
                    Button {
                        toggleMonthYearWheel()
                    } label: {
                        HStack(spacing: 6) {
                            Text(ChekinanaProductDate.monthTitle(displayedMonth))
                                .font(.headline)
                            Image(
                                systemName: isMonthYearWheelExpanded
                                    ? "chevron.up" : "chevron.down"
                            )
                            .font(.caption.weight(.semibold))
                        }
                        .accessibilityIdentifier("chekinana.calendar.month")
                    }
                    Spacer()
                    monthButton(systemImage: "chevron.right", offset: 1, id: "next")
                }
                .foregroundStyle(.white)
                .padding(.horizontal, 6)
                .background(ChekinanaDesignSystem.accent)
                .clipShape(RoundedRectangle(cornerRadius: ChekinanaDesignSystem.compactRadius))

                if isMonthYearWheelExpanded, let monthYearWheelDraft {
                    ChekinanaCalendarMonthYearWheels(
                        draft: monthYearWheelDraft
                    )
                    .transition(.opacity.combined(with: .move(edge: .top)))
                }

                LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 4), count: 7), spacing: 7) {
                    ForEach(ChekinanaProductDate.weekdaySymbols, id: \.self) { weekday in
                        Text(weekday)
                            .font(.caption2.weight(.semibold))
                            .foregroundStyle(.secondary)
                            .frame(maxWidth: .infinity)
                    }
                    ForEach(cells) { cell in
                        calendarDay(cell, metrics: monthMetrics, accessibilityDate: accessibilityFormatter.string(from: cell.date))
                    }
                }
                .allowsHitTesting(!isMonthYearWheelExpanded)
            }
        }
        .accessibilityIdentifier("chekinana.calendar.first-content")
        .gesture(DragGesture(minimumDistance: 30).onEnded { value in
            guard !isMonthYearWheelExpanded else { return }
            guard abs(value.translation.width) > abs(value.translation.height) else { return }
            let offset = value.translation.width < 0 ? 1 : -1
            if let next = ChekinanaCalendarDateBoundaryPolicy
                .adjacentDisplayedMonth(from: displayedMonth, offset: offset) {
                displayedMonth = next
                selectedDate = ChekinanaCalendarDateBoundaryPolicy
                    .clampedSelection(next)
                isMonthYearWheelExpanded = false
            }
        })
    }

    private func monthButton(systemImage: String, offset: Int, id: String) -> some View {
        Button {
            guard let next = ChekinanaCalendarDateBoundaryPolicy
                .adjacentDisplayedMonth(
                    from: displayedMonth,
                    offset: offset
                ) else { return }
            displayedMonth = next
            selectedDate = ChekinanaCalendarDateBoundaryPolicy
                .clampedSelection(next)
        } label: {
            Image(systemName: systemImage)
                .font(.subheadline.bold())
                .frame(width: 44, height: 44)
                .foregroundStyle(.white)
                .background(Color.white.opacity(0.16))
                .clipShape(Circle())
        }
        .buttonStyle(.plain)
        .disabled(
            isMonthYearWheelExpanded
                || ChekinanaCalendarDateBoundaryPolicy.adjacentDisplayedMonth(
                    from: displayedMonth,
                    offset: offset
                ) == nil
        )
        .accessibilityIdentifier("chekinana.calendar.\(id)-month")
    }

    private func toggleMonthYearWheel() {
        if isMonthYearWheelExpanded {
            commitMonthYearWheelDraft()
            return
        }
        monthYearWheelDraft = ChekinanaCalendarMonthYearDraft(
            displayedMonth: displayedMonth
        )
        withAnimation(.easeInOut(duration: 0.2)) {
            isMonthYearWheelExpanded = true
        }
    }

    private func commitMonthYearWheelDraft() {
        defer {
            monthYearWheelDraft = nil
            withAnimation(.easeInOut(duration: 0.2)) {
                isMonthYearWheelExpanded = false
            }
        }
        guard let monthYearWheelDraft,
              let next = monthYearWheelDraft.selection(
                  preservingDayFrom: selectedDate
              ) else { return }
        displayedMonth = next.displayedMonth
        selectedDate = next.selectedDate
    }

    private func calendarDay(
        _ cell: ChekinanaCalendarCell,
        metrics: ChekinanaCalendarMonthMetrics,
        accessibilityDate: String
    ) -> some View {
        let selected = ChekinanaProductDate.isSameDay(cell.date, selectedDate)
        let isToday = ChekinanaProductDate.isSameDay(
            cell.date,
            ChekinanaProductDate.fixtureAwareToday
        )
        let visualState = ChekinanaCalendarDayVisualState.resolve(
            isSelected: selected,
            isToday: isToday
        )
        let hasEvent = metrics.hasEvent(on: cell.date)
        let isSelectable = ChekinanaCalendarDateBoundaryPolicy.isSelectable(
            cell.date
        )
        let showsEventIcon = ChekinanaCalendarDayContentPolicy.showsEventIcon(
            hasEvent: hasEvent,
            isSelected: selected
        )
        let primaryForeground: Color =
            !isSelectable || ChekinanaCalendarDayContentPolicy.usesSecondaryDateNumber(
                isInDisplayedMonth: cell.isInDisplayedMonth,
                isSelected: selected
            )
            ? .secondary
            : (selected ? .white : .primary)
        let chekiCountForeground: Color =
            !isSelectable || ChekinanaCalendarDayContentPolicy.usesSecondaryChekiCount(
                isInDisplayedMonth: cell.isInDisplayedMonth,
                isSelected: selected
            )
            ? .secondary
            : (selected ? .white : ChekinanaProductTheme.accent)
        let chekiCount = metrics.chekiCount(on: cell.date)
        return Button {
            guard let selection = ChekinanaCalendarSelectionPolicy.selecting(
                cell.date,
                displayedMonth: displayedMonth
            ) else { return }
            selectedDate = selection.selectedDate
            displayedMonth = selection.displayedMonth
            isMonthYearWheelExpanded = false
        } label: {
            VStack(spacing: 6) {
                Group {
                    if showsEventIcon {
                        Image(systemName: "music.note.house")
                            .accessibilityIdentifier(
                                "chekinana.calendar.day-event.\(ChekinanaProductDate.key(cell.date))"
                            )
                    } else {
                        Text(ChekinanaProductDate.dayNumber(cell.date))
                            .accessibilityIdentifier(
                                "chekinana.calendar.day-number.\(ChekinanaProductDate.key(cell.date))"
                            )
                    }
                }
                .font(.body.weight(selected ? .bold : .regular))
                .foregroundStyle(primaryForeground)
                HStack(spacing: 3) {
                    if chekiCount > 0 {
                        Text(chekiCount.formatted(.number.locale(ChekinanaLanguagePreference.displayLocale())))
                            .font(.system(size: 9, weight: .bold))
                            .foregroundStyle(chekiCountForeground)
                            .accessibilityIdentifier("chekinana.calendar.count.\(ChekinanaProductDate.key(cell.date))")
                    }
                }
                .frame(height: 10)
            }
            .frame(
                maxWidth: .infinity,
                minHeight: ChekinanaAccessibilityMetrics.minimumTouchTarget
            )
            .background {
                RoundedRectangle(cornerRadius: 11, style: .continuous)
                    .fill(ChekinanaProductTheme.accent.opacity(
                        visualState.fillAccentOpacity
                    ))
            }
            .overlay {
                RoundedRectangle(cornerRadius: 11, style: .continuous)
                    .strokeBorder(
                        ChekinanaProductTheme.accent.opacity(
                            visualState.strokeAccentOpacity
                        ),
                        lineWidth: 2
                    )
            }
            .clipShape(RoundedRectangle(cornerRadius: 11, style: .continuous))
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .disabled(!isSelectable)
        .chekinanaMinimumTouchTarget()
        .accessibilityAddTraits(selected ? .isSelected : [])
        .accessibilityLabel(accessibilityDate)
        .accessibilityValue(
            [
                selected
                    ? ChekinanaProductCopy.text("calendar.selected", "Selected")
                    : nil,
                isToday
                    ? ChekinanaProductCopy.text("calendar.today", "Today")
                    : nil,
                ChekinanaRecordKind.cheki.countLabel(chekiCount),
            ].compactMap { $0 }.joined(separator: ", ")
        )
        .accessibilityIdentifier("chekinana.calendar.day.\(ChekinanaProductDate.key(cell.date))")
    }

    private var selectedDayCard: some View {
        let avatarSourceKey = self.avatarSourceKey
        let snapshot = selectedDaySnapshot
        let displayedGroups = snapshot.groups
        let orderedGroupKeys = displayedGroups.map(\.combinationKey.id)
        let selectedDateKey = ChekinanaProductDate.key(selectedDate)
        return ChekinanaSectionCard {
            VStack(alignment: .leading, spacing: ChekinanaCalendarSelectedDayLayout.sectionSpacing) {
                HStack(alignment: .firstTextBaseline) {
                    Text(ChekinanaProductDate.longTitle(selectedDate))
                        .font(.headline)
                        .accessibilityIdentifier("chekinana.calendar.selected-date")
                        .accessibilityValue(ChekinanaProductDate.key(selectedDate))
                    Spacer()
                    Text(
                        ChekinanaRecordKind.cheki.countLabel(
                            snapshot.chekiCount
                        )
                    )
                        .font(.caption.weight(.medium))
                        .foregroundStyle(.secondary)
                }

                if snapshot.isEmpty {
                    HStack(spacing: 12) {
                        Image(systemName: "calendar")
                            .foregroundStyle(ChekinanaProductTheme.accent)
                        Text(ChekinanaProductCopy.text("calendar.no_records", "No records for this day"))
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                    .frame(maxWidth: .infinity, minHeight: 74, alignment: .leading)
                    .chekinanaScreenMarker("chekinana.calendar.empty-day")
                } else {
                    VStack(
                        alignment: .leading,
                        spacing: ChekinanaCalendarSelectedDayLayout.recordSpacing
                    ) {
                    ForEach(snapshot.events) { event in
                        Button {
                            selectedEvent = event
                        } label: {
                            HStack(spacing: 12) {
                                Image(systemName: "music.note.house")
                                    .foregroundStyle(ChekinanaProductTheme.accent)
                                    .frame(width: 30)
                                VStack(alignment: .leading, spacing: 3) {
                                    Text(event.name)
                                        .font(.subheadline.weight(.semibold))
                                        .foregroundStyle(.primary)
                                        .lineLimit(1)
                                        .truncationMode(.tail)
                                    Text(
                                        [ChekinanaEventCity.displayed(event.city), event.resolvedLivehouse]
                                            .compactMap { $0 }
                                            .joined(separator: " · ")
                                            .nonEmpty
                                            ?? ChekinanaProductCopy.text("events.event", "Event")
                                    )
                                        .font(.caption).foregroundStyle(.secondary)
                                }
                                Spacer()
                            }
                            .padding(12)
                            .background(ChekinanaProductTheme.softAccent.opacity(0.72))
                            .clipShape(
                                RoundedRectangle(
                                    cornerRadius: ChekinanaProductTheme.compactRadius,
                                    style: .continuous
                                )
                            )
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                        .accessibilityIdentifier("chekinana.calendar.event.\(event.id)")
                    }

                    ForEach(displayedGroups) { group in
                        HStack(spacing: ChekinanaCalendarSelectedDayLayout.groupControlSpacing) {
                            HStack(spacing: 12) {
                                if group.isStandaloneMultiIdol {
                                    ChekinanaCalendarIdolAvatarStrip(
                                        idols: group.orderedIdols,
                                        size: ChekinanaCalendarSelectedDayLayout.idolAvatarSize,
                                        asyncSourceKey: avatarSourceKey
                                    )
                                } else if let idol = group.idol {
                                    ChekinanaCalendarDayIdolAvatar(
                                        idol: idol,
                                        size: ChekinanaCalendarSelectedDayLayout.idolAvatarSize,
                                        sourceKey: avatarSourceKey
                                    )
                                } else {
                                    Image(systemName: "person.slash")
                                        .frame(
                                            width: ChekinanaCalendarSelectedDayLayout.idolAvatarSize,
                                            height: ChekinanaCalendarSelectedDayLayout.idolAvatarSize
                                        )
                                        .background(Color(uiColor: .tertiarySystemGroupedBackground))
                                        .clipShape(Circle())
                                }
                                VStack(alignment: .leading, spacing: 4) {
                                    Text(group.name)
                                        .font(.subheadline.weight(.semibold))
                                        .foregroundStyle(.primary)
                                        .lineLimit(1)
                                    Text(group.countLabels.joined(separator: " · "))
                                        .font(.caption)
                                        .foregroundStyle(.secondary)
                                        .layoutPriority(1)
                                }
                                .layoutPriority(1)
                                Spacer(minLength: 0)
                            }
                            .frame(maxWidth: .infinity, minHeight: 62, alignment: .leading)
                            .contentShape(Rectangle())
                            .accessibilityElement(children: .combine)
                            .accessibilityAddTraits(.isButton)
                            .accessibilityAction {
                                openCalendarGroupEditor(group)
                            }
                            .accessibilityLabel(
                                "\(group.name), \(group.countLabels.joined(separator: ", "))"
                            )
                            .accessibilityIdentifier("chekinana.calendar.group.\(group.id)")

                            if !group.chekis.isEmpty {
                                ChekinanaCalendarThumbnailStrip(
                                    chekis: group.chekis,
                                    usesPreparedOrder: true,
                                    onSelect: { _ in
                                        openCalendarGroupEditor(group)
                                    }
                                )
                            }
                        }
                        .contentShape(Rectangle())
                        .overlay {
                            ChekinanaCalendarGroupGestureSurface(
                                dateKey: selectedDateKey,
                                groupKey: group.combinationKey.id,
                                orderedGroupKeys: orderedGroupKeys,
                                onTap: { location, size in
                                    handleCalendarGroupTap(
                                        group,
                                        location: location,
                                        rowSize: size
                                    )
                                },
                                onReorderEnded: { targetIndex in
                                    commitGroupDrag(
                                        groupKey: group.combinationKey.id,
                                        targetIndex: targetIndex,
                                        dateKey: selectedDateKey,
                                        expectedGroupKeys: orderedGroupKeys
                                    )
                                },
                                onDebugState: { state in
                                    updateCalendarGroupGestureDebugState(
                                        state,
                                        groupKey: group.combinationKey.id
                                    )
                                }
                            )
                            .frame(maxWidth: .infinity, maxHeight: .infinity)
                            .allowsHitTesting(true)
                            .accessibilityHidden(true)
                        }
#if DEBUG
                        .overlay(alignment: .topLeading) {
                            Text("")
                                .frame(width: 1, height: 1)
                                .allowsHitTesting(false)
                                .accessibilityElement(children: .ignore)
                                .accessibilityIdentifier(
                                    "chekinana.calendar.debug.group-gesture.\(group.id)"
                                )
                                .accessibilityValue(
                                    calendarGroupGestureDebugStates[
                                        group.combinationKey.id
                                    ] ?? "unlaid-out"
                                )
                        }
#endif
                    }
                    }
                }
            }
        }
        .chekinanaScreenMarker("chekinana.calendar.selected-day")
    }

    private func openCalendarGroupEditor(_ group: ChekinanaCalendarIdolGroup) {
        selectedGroupEditor = .init(
            date: selectedDate,
            group: group
        )
    }

    private func deletePendingEvent() {
        guard let eventID = pendingEventDeletionID else { return }
        pendingEventDeletionID = nil
        Task { @MainActor in
            // Match the Event list flow: release the detail sheet's live model
            // before deleting it on the next main-actor turn.
            await Task.yield()
            do {
                try ChekinanaEventPersistence.delete(
                    eventID: eventID,
                    from: modelContext
                )
            } catch {
                eventDeletionError = error.localizedDescription
            }
        }
    }

    private func handleCalendarGroupTap(
        _ group: ChekinanaCalendarIdolGroup,
        location: CGPoint,
        rowSize: CGSize
    ) {
        _ = location
        _ = rowSize
#if DEBUG
        updateCalendarGroupGestureDebugState(
            "route-editor",
            groupKey: group.combinationKey.id
        )
#endif
        openCalendarGroupEditor(group)
    }

    private func updateCalendarGroupGestureDebugState(
        _ state: String,
        groupKey: String
    ) {
#if DEBUG
        calendarGroupGestureDebugStates[groupKey] = state
#endif
    }

    private func commitGroupDrag(
        groupKey: String,
        targetIndex: Int,
        dateKey: String,
        expectedGroupKeys: [String]
    ) {
        guard dateKey == ChekinanaProductDate.key(selectedDate) else { return }
        let currentGroupKeys = selectedDaySnapshot.groups.map(
            \.combinationKey.id
        )
        guard currentGroupKeys == expectedGroupKeys,
              let sourceIndex = currentGroupKeys.firstIndex(of: groupKey),
              currentGroupKeys.indices.contains(targetIndex),
              sourceIndex != targetIndex else { return }
        var reorderedGroupKeys = currentGroupKeys
        let movedKey = reorderedGroupKeys.remove(at: sourceIndex)
        reorderedGroupKeys.insert(movedKey, at: targetIndex)
        do {
            try ChekinanaCalendarGroupOrderStore.setOrder(
                reorderedGroupKeys,
                dateKey: dateKey,
                in: modelContext
            )
        } catch {
            reorderErrorMessage = error.localizedDescription
        }
    }
}

private enum ChekinanaCalendarNoMediaRecord: Identifiable {
    case record(ChekinanaChekiRecordSelection)
    case shame(MediaItem)
    case douga(MediaItem)
    var id: UUID { switch self { case .record(let value): value.id; case .shame(let value): value.id; case .douga(let value): value.id } }
    var listID: String { "\(kind.rawValue)-\(id.uuidString.lowercased())" }
    var kind: ChekinanaRecordKind { switch self { case .record: .cheki; case .shame: .shame; case .douga: .douga } }
    var typeName: String { kind.title }
    var listTitle: String {
        switch self {
        case .record:
            ChekinanaChekiRecordListCopy.title()
        case .shame, .douga:
            typeName
        }
    }
    var listSubtitle: String {
        switch self {
        case .record(let value):
            ChekinanaChekiRecordListCopy.noteStatus(
                note: value.snapshot.identity.note
            )
        case .shame(let value), .douga(let value):
            value.note.nonEmpty
                ?? ChekinanaProductCopy.text(
                    "calendar.no_media_metadata",
                    "No media · No date · No Idols"
                )
        }
    }
    var createdAt: Date? { nil }
    var date: Date? { switch self { case .record(let value): value.snapshot.identity.canonicalDate; case .shame(let value): value.date; case .douga(let value): value.date } }
    var note: String { switch self { case .record(let value): value.snapshot.identity.note; case .shame(let value): value.note; case .douga(let value): value.note } }
    var idolIDs: Set<UUID> { switch self { case .record(let value): Set(value.snapshot.identity.idolIDs); case .shame(let value): Set(value.idols.map(\.id)); case .douga(let value): Set(value.idols.map(\.id)) } }
}

private struct ChekinanaUndatedUnassignedRecordsView: View {
    @Query private var chekiRecords: [ChekiRecord]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "shame" }) private var shames: [MediaItem]
    @Query(filter: #Predicate<MediaItem> { $0.kindRawValue == "douga" }) private var dougas: [MediaItem]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    @State private var selectedRecord: ChekinanaCalendarNoMediaRecord?

    private var records: [ChekinanaCalendarNoMediaRecord] {
        let values = chekiRecords.filter {
            ChekinanaChekiRecordReadPolicy.isUndatedAndUnassigned($0)
                && ChekinanaChekiRecordReadPolicy.isVisible(
                    $0,
                    hiddenIDs: hiddenIdols.hiddenIDs
                )
        }.map {
            .record(ChekinanaChekiRecordSelection(record: $0))
        } + shames.filter {
            $0.imageRef?.nonEmpty == nil && $0.idols.isEmpty && $0.date == nil
                && ChekinanaVisibilityPolicy.includesRecord(idols: $0.idols, hiddenIDs: hiddenIdols.hiddenIDs)
        }.map(ChekinanaCalendarNoMediaRecord.shame) + dougas.filter {
            $0.videoRef?.nonEmpty == nil && $0.idols.isEmpty && $0.date == nil
                && ChekinanaVisibilityPolicy.includesRecord(idols: $0.idols, hiddenIDs: hiddenIdols.hiddenIDs)
        }.map(ChekinanaCalendarNoMediaRecord.douga)
        let typeOrder: [ChekinanaRecordKind: Int] = [.cheki: 0, .shame: 1, .douga: 2]
        return values.sorted { lhs, rhs in
            let lhsType = typeOrder[lhs.kind] ?? Int.max
            let rhsType = typeOrder[rhs.kind] ?? Int.max
            if lhsType != rhsType { return lhsType < rhsType }
            if lhs.createdAt != rhs.createdAt {
                return (lhs.createdAt ?? .distantPast) < (rhs.createdAt ?? .distantPast)
            }
            return lhs.id.uuidString < rhs.id.uuidString
        }
    }

    var body: some View {
        NavigationStack {
            Group {
                if records.isEmpty {
                    ChekinanaEmptyState(
                        title: ChekinanaProductCopy.text(
                            "calendar.undated_unassigned",
                            "Undated & Unassigned"
                        ),
                        message: ChekinanaProductCopy.text(
                            "calendar.undated_empty_detail",
                            "Records move out of this list after you add a date or Idol."
                        ),
                        systemImage: "tray"
                    )
                } else {
                    List {
                        ForEach(records, id: \.listID) { record in
                            Button {
                                selectedRecord = record
                            } label: {
                                HStack(spacing: 12) {
                                    ChekinanaRecordCategoryIcon(kind: record.kind)
                                    .foregroundStyle(ChekinanaProductTheme.accent)
                                    .frame(width: 34, height: 40)
                                    .background(ChekinanaProductTheme.softAccent)
                                    .clipShape(
                                        RoundedRectangle(
                                            cornerRadius: 9,
                                            style: .continuous
                                        )
                                    )
                                    VStack(alignment: .leading, spacing: 3) {
                                        Text(record.listTitle)
                                            .font(.subheadline.weight(.semibold))
                                        Text(record.listSubtitle)
                                        .font(.caption)
                                        .foregroundStyle(.secondary)
                                        .lineLimit(1)
                                    }
                                    Spacer()
                                    Image(systemName: "chevron.right")
                                        .font(.caption.weight(.semibold))
                                        .foregroundStyle(.tertiary)
                                }
                                .frame(minHeight: 52)
                                .contentShape(Rectangle())
                            }
                            .buttonStyle(.plain)
                            .accessibilityIdentifier(
                                "chekinana.calendar.undated-unassigned.\(record.listID)"
                            )
                        }
                    }
                    .listStyle(.insetGrouped)
                    .chekinanaGroupedPageBackground()
                }
            }
            .background(ChekinanaProductTheme.pageBackground)
            .navigationTitle(
                ChekinanaProductCopy.text(
                    "calendar.undated_unassigned",
                    "Undated & Unassigned"
                )
            )
            .navigationBarTitleDisplayMode(.inline)
        }
        .sheet(item: $selectedRecord) { record in
            ChekinanaCalendarNoMediaRecordEditor(record: record)
        }
    }
}

private struct ChekinanaCalendarNoMediaRecordEditor: View {
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query private var idols: [Idol]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let record: ChekinanaCalendarNoMediaRecord
    @State private var hasDate: Bool
    @State private var date: Date
    @State private var eventID: UUID?
    @State private var note: String
    @State private var idolIDs: Set<UUID>
    @State private var choosingIdols = false
    @State private var errorMessage: String?
    init(record: ChekinanaCalendarNoMediaRecord) {
        self.record = record
        _hasDate = State(initialValue: record.date != nil)
        _date = State(initialValue: record.date ?? Date())
        switch record {
        case .record(let value):
            _eventID = State(initialValue: value.snapshot.identity.eventID)
        case .shame(let value), .douga(let value):
            _eventID = State(initialValue: value.eventID)
        }
        _note = State(initialValue: record.note)
        _idolIDs = State(initialValue: record.idolIDs)
    }
    @ViewBuilder
    var body: some View {
        switch record {
        case .record(let value):
            ChekinanaChekiRecordEditor(selection: value)
        case .shame, .douga:
            NavigationStack {
                Form {
                    Section(ChekinanaProductCopy.text("common.idols", "Idols")) {
                        ChekinanaIdolSelectionSummaryButton(
                            idols: visibleIdols.filter { idolIDs.contains($0.id) },
                            identifier: "chekinana.calendar.no-media.change-idols"
                        ) {
                            choosingIdols = true
                        }
                    }
                    Section(ChekinanaProductCopy.text("common.metadata", "Metadata")) {
                        Toggle(
                            ChekinanaProductCopy.text(
                                "common.include_date",
                                "Include date"
                            ),
                            isOn: $hasDate
                        )
                        if hasDate {
                            ChekinanaExpandableDateWheel(
                                ChekinanaProductCopy.text("common.date", "Date"),
                                selection: $date,
                                accessibilityIdentifier: "chekinana.calendar.no-media.date"
                            )
                        }
                        ChekinanaChekiEventSelectionField(
                            eventID: $eventID,
                            recordDate: draftCanonicalDate,
                            events: events,
                            schedules: eventSchedules,
                            primaryScope: .exactDate
                        )
                        ChekinanaSingleLineNoteField(
                            ChekinanaProductCopy.text("common.note", "Note"),
                            text: $note
                        )
                    }
                    if let errorMessage {
                        Section {
                            ChekinanaInlineStatus(message: errorMessage, kind: .error)
                        }
                    }
                }
                .chekinanaGroupedPageBackground()
                .navigationTitle(
                    ChekinanaProductCopy.format(
                        "calendar.edit_record",
                        "Edit %@",
                        record.typeName
                    )
                )
                .navigationBarTitleDisplayMode(.inline)
                .toolbar {
                    ToolbarItem(placement: .cancellationAction) {
                        Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                            dismiss()
                        }
                    }
                    ToolbarItem(placement: .confirmationAction) {
                        Button(
                            ChekinanaProductCopy.text("common.save", "Save"),
                            action: save
                        )
                    }
                    ToolbarItem(placement: .bottomBar) {
                        Button(
                            ChekinanaProductCopy.text("common.delete", "Delete"),
                            role: .destructive,
                            action: delete
                        )
                        .accessibilityIdentifier("chekinana.calendar.no-media.delete")
                    }
                }
            }
            .sheet(isPresented: $choosingIdols) {
                ChekinanaIdolSelectionView(
                    options: visibleIdols.map(ChekinanaIdolSelectionOption.init),
                    selectedIDs: visibleIdolSelection
                )
            }
            .chekinanaSheetDraftDismiss(snapshot: { [AnyHashable(idolIDs), AnyHashable(hasDate), AnyHashable(hasDate ? date : nil), AnyHashable(eventID), AnyHashable(note)] })
            .onChange(of: hasDate) { _, _ in clearInvalidEventSelection() }
            .onChange(of: date) { _, _ in clearInvalidEventSelection() }
        }
    }
    private var visibleIdolSelection: Binding<Set<UUID>> {
        Binding(
            get: { idolIDs.subtracting(hiddenIdols.hiddenIDs) },
            set: { idolIDs = $0.union(idolIDs.intersection(hiddenIdols.hiddenIDs)) }
        )
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    private var draftCanonicalDate: Date? {
        guard hasDate else { return nil }
        return ChekinanaPersistedContentDatePolicy.canonicalDate(from: date)
    }

    private func clearInvalidEventSelection() {
        eventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
            eventID,
            recordDate: draftCanonicalDate,
            events: events
        )
    }
    private func save() {
        let normalized: Date?
        if hasDate {
            guard let canonical = ChekinanaPersistedContentDatePolicy
                .canonicalDate(from: date) else {
                errorMessage = ChekinanaProductCopy.text(
                    "error.normalize_date",
                    "Unable to normalize the selected date."
                )
                return
            }
            normalized = canonical
        } else {
            normalized = nil
        }
        do {
            let selectedIdols = try ChekinanaModelContextResolver.idols(
                idolIDs: idolIDs,
                preservingExistingIDs: record.idolIDs,
                in: modelContext
            )
            switch record {
            case .record:
                return
            case .shame(let value):
                value.idols = selectedIdols
                value.date = normalized
                value.eventID = eventID
                value.note = note
                try ChekinanaEventAssociationPropagation.propagate(
                    from: value,
                    in: modelContext
                )
            case .douga(let value):
                value.idols = selectedIdols
                value.date = normalized
                value.eventID = eventID
                value.note = note
                try ChekinanaEventAssociationPropagation.propagate(
                    from: value,
                    in: modelContext
                )
            }
            try modelContext.save(); dismiss()
        } catch { modelContext.rollback(); errorMessage = error.localizedDescription }
    }
    private func delete() {
        do {
            switch record {
            case .record:
                return
            case .shame(let value):
                let target = try ChekinanaModelContextResolver.shame(
                    id: value.id,
                    in: modelContext
                )
                guard target.imageRef?.nonEmpty == nil else {
                    errorMessage = ChekinanaProductCopy.format(
                        "calendar.media_backed_delete",
                        "This %@ now has managed media. Delete it from its media detail page.",
                        ChekinanaRecordKind.shame.title
                    )
                    return
                }
                modelContext.delete(target)
            case .douga(let value):
                let target = try ChekinanaModelContextResolver.douga(
                    id: value.id,
                    in: modelContext
                )
                guard target.videoRef?.nonEmpty == nil else {
                    errorMessage = ChekinanaProductCopy.format(
                        "calendar.media_backed_delete",
                        "This %@ now has managed media. Delete it from its media detail page.",
                        ChekinanaRecordKind.douga.title
                    )
                    return
                }
                modelContext.delete(target)
            }
            try modelContext.save()
            dismiss()
        } catch {
            modelContext.rollback()
            errorMessage = error.localizedDescription
        }
    }
}

private struct ChekinanaChekiRecordEditor: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query private var idols: [Idol]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    private let recordID: UUID
    private let initialSnapshot: ChekinanaChekiRecordSnapshot

    @State private var idolIDs: Set<UUID>
    @State private var hasDate: Bool
    @State private var date: Date
    @State private var dateSession: ChekinanaDateOnlyEditorSession
    @State private var eventID: UUID?
    @State private var size: ChekiSize?
    @State private var noteDraft: ChekinanaRecordNoteDraft
    @State private var count: Int
    @State private var choosingIdols = false
    @State private var errorMessage: String?

    init(selection: ChekinanaChekiRecordSelection) {
        let snapshot = selection.snapshot
        let identity = snapshot.identity
        let dateSession = ChekinanaDateOnlyEditorSession(
            initialCanonicalDate: identity.canonicalDate
        )
        recordID = snapshot.id
        initialSnapshot = snapshot
        _idolIDs = State(initialValue: Set(identity.idolIDs))
        _hasDate = State(initialValue: identity.canonicalDate != nil)
        _date = State(initialValue: identity.canonicalDate.flatMap {
            dateSession.displayDate(from: $0)
        } ?? dateSession.displayDateForToday() ?? Date())
        _dateSession = State(initialValue: dateSession)
        _eventID = State(initialValue: identity.eventID)
        _size = State(
            initialValue: identity.sizeRawValue.flatMap(ChekiSize.init(rawValue:))
        )
        _noteDraft = State(initialValue: ChekinanaRecordNoteDraft(identity.note))
        _count = State(initialValue: snapshot.count)
    }

    var body: some View {
        let resolvedVisibleIdols = visibleIdols
        NavigationStack {
            Form {
                ChekinanaChekiRecordEditorFields(
                    visibleIdols: resolvedVisibleIdols,
                    events: events,
                    schedules: eventSchedules,
                    dateCalendar: dateSession.calendar,
                    identifierPrefix: "chekinana.record.editor",
                    chooseIdols: { choosingIdols = true },
                    idolIDs: $idolIDs,
                    count: $count,
                    hasDate: $hasDate,
                    date: $date,
                    eventID: $eventID,
                    size: $size,
                    noteDraft: noteDraft
                )
                if let errorMessage {
                    Section {
                        ChekinanaInlineStatus(message: errorMessage, kind: .error)
                    }
                }
            }
            .chekinanaGroupedPageBackground()
            .navigationTitle(
                ChekinanaProductCopy.text("calendar.edit_simple_record", "Edit record")
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        dismiss()
                    }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(
                        ChekinanaProductCopy.text("common.save", "Save"),
                        action: save
                    )
                    .accessibilityIdentifier("chekinana.record.editor.save")
                }
                ToolbarItem(placement: .bottomBar) {
                    Button(
                        ChekinanaProductCopy.text("common.delete", "Delete"),
                        role: .destructive,
                        action: delete
                    )
                    .accessibilityIdentifier("chekinana.record.editor.delete")
                }
            }
        }
        .accessibilityIdentifier("chekinana.record.editor")
        .sheet(isPresented: $choosingIdols) {
            ChekinanaIdolAvatarCheckSelectionView(
                idols: visibleIdols,
                selectedIDs: visibleIdolSelection,
                identifierPrefix: "chekinana.record.editor.idol-selection"
            )
        }
        .onChange(of: hasDate) { _, _ in clearInvalidEventSelection() }
        .onChange(of: date) { _, _ in clearInvalidEventSelection() }
        .chekinanaSheetDraftDismiss(
            snapshot: { [AnyHashable(idolIDs), AnyHashable(hasDate), AnyHashable(hasDate ? date : nil), AnyHashable(eventID), AnyHashable(size), AnyHashable(noteDraft.text), AnyHashable(count)] }
        )
    }

    private var visibleIdolSelection: Binding<Set<UUID>> {
        Binding(
            get: { idolIDs.subtracting(hiddenIdols.hiddenIDs) },
            set: { idolIDs = $0.union(idolIDs.intersection(hiddenIdols.hiddenIDs)) }
        )
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    private var draftCanonicalDate: Date? {
        guard hasDate else { return nil }
        return dateSession.canonicalDate(from: date)
    }

    private func clearInvalidEventSelection() {
        eventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
            eventID,
            recordDate: draftCanonicalDate,
            events: events
        )
    }

    private func save() {
        let selectedIDs = ChekinanaRequiredIdolSelectionPolicy.resolvedIDs(
            selectedIDs: idolIDs,
            visibleIDs: idols.map(\.id)
        )
        guard Set(selectedIDs) == idolIDs else {
            errorMessage = ChekinanaChekiRecordMutationError.missingRelationships.localizedDescription
            return
        }
        let normalizedDate: Date?
        if hasDate {
            guard let canonical = dateSession.canonicalDate(from: date) else {
                errorMessage = ChekinanaProductCopy.text(
                    "error.normalize_date",
                    "Unable to normalize the selected date."
                )
                return
            }
            normalizedDate = canonical
        } else {
            normalizedDate = nil
        }
        do {
            let validEventID = ChekinanaChekiEventSelectionPolicy.validatedEventID(
                eventID,
                recordDate: normalizedDate,
                events: events
            )
            _ = try ChekinanaChekiRecordStore.update(
                recordID: recordID,
                idolIDs: selectedIDs,
                eventID: validEventID,
                date: normalizedDate,
                size: size,
                note: noteDraft.text,
                count: count,
                expected: initialSnapshot,
                in: modelContext
            )
            dismiss()
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private func delete() {
        do {
            let target = try ChekinanaModelContextResolver.chekiRecord(
                id: recordID,
                in: modelContext
            )
            try ChekinanaChekiRecordStore.delete(
                target,
                expected: initialSnapshot,
                in: modelContext
            )
            dismiss()
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}

enum ChekinanaCalendarMonthYearWheelPolicy {
    static let yearRange = ChekinanaCalendarDateBoundaryPolicy.firstYear...ChekinanaCalendarDateBoundaryPolicy.lastYear
    static let monthRange = 1...12
    static func year(in date: Date) -> Int {
        ChekinanaProductDate.calendar.component(.year, from: date)
    }

    static func month(in date: Date) -> Int {
        ChekinanaProductDate.calendar.component(.month, from: date)
    }

    static func selection(
        year: Int,
        month: Int,
        preservingDayFrom selectedDate: Date
    ) -> (displayedMonth: Date, selectedDate: Date)? {
        guard yearRange.contains(year), monthRange.contains(month) else {
            return nil
        }
        let calendar = ChekinanaProductDate.calendar
        var monthComponents = DateComponents()
        monthComponents.calendar = calendar
        monthComponents.timeZone = calendar.timeZone
        monthComponents.year = year
        monthComponents.month = month
        monthComponents.day = 1
        guard let displayedMonth = calendar.date(from: monthComponents),
              let dayRange = calendar.range(
                  of: .day,
                  in: .month,
                  for: displayedMonth
              ) else {
            return nil
        }
        let currentDay = calendar.component(.day, from: selectedDate)
        var dateComponents = monthComponents
        dateComponents.day = min(max(currentDay, 1), dayRange.count)
        guard let candidateSelectedDate = calendar.date(from: dateComponents) else {
            return nil
        }
        return (
            displayedMonth,
            ChekinanaCalendarDateBoundaryPolicy.clampedSelection(
                candidateSelectedDate
            )
        )
    }

    static func yearTitle(_ year: Int) -> String {
        ChekinanaNumericDateWheelPolicy.title(year, locale: ChekinanaLanguagePreference.displayLocale())
    }

    static func monthTitle(_ month: Int) -> String {
        ChekinanaNumericDateWheelPolicy.title(month, locale: ChekinanaLanguagePreference.displayLocale())
    }
}

@MainActor
final class ChekinanaCalendarMonthYearDraft {
    var year: Int
    var month: Int

    init(displayedMonth: Date) {
        year = ChekinanaCalendarMonthYearWheelPolicy.year(in: displayedMonth)
        month = ChekinanaCalendarMonthYearWheelPolicy.month(in: displayedMonth)
    }

    func selection(
        preservingDayFrom selectedDate: Date
    ) -> (displayedMonth: Date, selectedDate: Date)? {
        ChekinanaCalendarMonthYearWheelPolicy.selection(
            year: year,
            month: month,
            preservingDayFrom: selectedDate
        )
    }
}

private struct ChekinanaCalendarLazyWheel: UIViewRepresentable {
    @Binding var selection: Int
    let range: ClosedRange<Int>
    let title: (Int) -> String
    let accessibilityIdentifier: String
    let accessibilityLabel: String?
    let height: CGFloat
    private let localeIdentifier: String

    init(
        selection: Binding<Int>,
        range: ClosedRange<Int>,
        accessibilityIdentifier: String,
        accessibilityLabel: String? = nil,
        height: CGFloat = 132,
        title: @escaping (Int) -> String
    ) {
        _selection = selection
        self.range = range
        self.accessibilityIdentifier = accessibilityIdentifier
        self.accessibilityLabel = accessibilityLabel
        self.height = height
        self.title = title
        localeIdentifier = ChekinanaLanguagePreference.displayLocale().identifier
    }

    func makeCoordinator() -> Coordinator {
        Coordinator(parent: self)
    }

    func makeUIView(context: Context) -> UIPickerView {
        let picker = UIPickerView(frame: .zero)
        picker.dataSource = context.coordinator
        picker.delegate = context.coordinator
        picker.accessibilityIdentifier = accessibilityIdentifier
        picker.accessibilityLabel = accessibilityLabel
        picker.selectRow(row(for: selection), inComponent: 0, animated: false)
        context.coordinator.localeIdentifier = localeIdentifier
        return picker
    }

    func updateUIView(_ picker: UIPickerView, context: Context) {
        let rangeChanged = context.coordinator.parent.range != range
        context.coordinator.parent = self
        picker.accessibilityLabel = accessibilityLabel
        if rangeChanged || context.coordinator.localeIdentifier != localeIdentifier {
            context.coordinator.localeIdentifier = localeIdentifier
            picker.reloadAllComponents()
        }
        let selectedRow = row(for: selection)
        if picker.selectedRow(inComponent: 0) != selectedRow {
            picker.selectRow(selectedRow, inComponent: 0, animated: false)
        }
    }

    func sizeThatFits(
        _ proposal: ProposedViewSize,
        uiView: UIPickerView,
        context: Context
    ) -> CGSize? {
        guard let width = proposal.width else { return nil }
        return CGSize(width: width, height: height)
    }

    private func row(for value: Int) -> Int {
        min(range.count - 1, max(0, value - range.lowerBound))
    }

    final class Coordinator: NSObject, UIPickerViewDataSource, UIPickerViewDelegate {
        var parent: ChekinanaCalendarLazyWheel
        var localeIdentifier: String

        init(parent: ChekinanaCalendarLazyWheel) {
            self.parent = parent
            localeIdentifier = parent.localeIdentifier
        }

        func numberOfComponents(in pickerView: UIPickerView) -> Int {
            1
        }

        func pickerView(
            _ pickerView: UIPickerView,
            numberOfRowsInComponent component: Int
        ) -> Int {
            parent.range.count
        }

        func pickerView(
            _ pickerView: UIPickerView,
            titleForRow row: Int,
            forComponent component: Int
        ) -> String? {
            guard row >= 0, row < parent.range.count else { return nil }
            return parent.title(parent.range.lowerBound + row)
        }

        func pickerView(
            _ pickerView: UIPickerView,
            didSelectRow row: Int,
            inComponent component: Int
        ) {
            guard row >= 0, row < parent.range.count else { return }
            let value = parent.range.lowerBound + row
            if parent.selection != value {
                parent.selection = value
            }
        }
    }
}

