struct ChekinanaCalendarRecordBatchPlan: Sendable {
    let kind: ChekinanaRecordKind
    let idolIDs: [UUID]
    let date: Date?
    let quantity: Int
    let manualStart: Int?
    let note: String
    let eventID: UUID?
    let size: ChekiSize?

    init(
        kind: ChekinanaRecordKind,
        idolIDs: [UUID],
        date: Date?,
        quantity: Int,
        manualStart: Int?,
        note: String,
        eventID: UUID?,
        size: ChekiSize? = .mini
    ) {
        self.kind = kind
        self.idolIDs = idolIDs
        self.date = date
        self.quantity = quantity
        self.manualStart = manualStart
        self.note = note
        self.eventID = eventID
        self.size = size
    }
