    }

    var resolvedInitialID: UUID? {
        ChekinanaChekiViewerRoutingPolicy.initialID(
            requested: initialID,
            available: mediaChekis.map(\.id)
        )
    }

    var id: String {
        group.id + "|" + (initialID?.uuidString.lowercased() ?? "first")
    }
}

struct ChekinanaCalendarGroupEditorSelection: Identifiable {
    let date: Date
    let combinationKey: ChekinanaIdolCombinationKey
    let chekiIDs: [UUID]
    let recordIDs: [UUID]
    let shameIDs: [UUID]
    let dougaIDs: [UUID]

    init(date: Date, group: ChekinanaCalendarIdolGroup) {
        self.date = date
        combinationKey = group.combinationKey
        chekiIDs = group.chekis.map(\.id)
        recordIDs = group.records.map(\.id)
        shameIDs = group.shames.map(\.id)
        dougaIDs = group.dougas.map(\.id)
    }

    var id: String {
        "\(ChekinanaProductDate.key(date))|\(combinationKey.id)"
    }
}

private struct ChekinanaCalendarDayIdolAvatar: View {
    let idol: Idol
    let size: CGFloat
    let sourceKey: String
    var borderLineWidth: CGFloat = 2
    @ObservedObject private var revisions = ChekinanaThumbnailRevisionStore.shared
    @State private var image: ChekinanaRenderedImage?
    @State private var loadedIdentity: ChekinanaThumbnailLoadIdentity?

    private var identity: ChekinanaThumbnailLoadIdentity {
        revisions.identity(
            imageRef: idol.avatarImageRef,
            sourceKey: "\(sourceKey)-idol-\(idol.id)"
        )
    }

    var body: some View {
        let currentIdentity = identity
        // Pass the prepared image only: the shared avatar initializer must not
        // synchronously resolve or read a managed file while Calendar lays out.
        ChekinanaIdolAvatarImage(
            name: idol.name, color: idol.color, imageRef: nil,
            cacheKey: currentIdentity.sourceKey, size: size,
            preparedImage: loadedIdentity == currentIdentity ? image : nil,
            borderLineWidth: borderLineWidth
        )
        .task(id: currentIdentity) {
            image = nil
            loadedIdentity = nil
            let ref = idol.avatarImageRef
            let idolID = idol.id
            let valid = await Task.detached(priority: .userInitiated) {
                (try? ChekinanaIdolReferenceStore.managedAvatarURL(
                    for: ref, idolID: idolID
                )) != nil
            }.value
            guard valid, !Task.isCancelled else { return }
            let loaded = await ChekinanaThumbnailCache.shared.thumbnailImage(
                forManagedImageRef: ref,
                key: "\(currentIdentity.sourceKey)-\(currentIdentity.revision)",
                maxDimension: 512
            )
            guard !Task.isCancelled, currentIdentity == identity else { return }
            image = loaded
            loadedIdentity = currentIdentity
        }
    }
}

private struct ChekinanaCalendarIdolAvatarStrip: View {
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    let idols: [Idol]
    let size: CGFloat
    var asyncSourceKey: String? = nil

    private var orderedIdols: [Idol] {
        idolOrdering.orderedUnique(idols)
    }

    var body: some View {
        if orderedIdols.isEmpty {
            Image(systemName: "person.slash")
                .frame(width: size, height: size)
                .background(Color(uiColor: .tertiarySystemGroupedBackground))
                .clipShape(Circle())
                .accessibilityHidden(true)
        } else {
            let width = ChekinanaCalendarSelectedDayLayout.idolAvatarStripWidth(
                count: orderedIdols.count,
                avatarSize: size
            )
            let layout = ChekinanaGalleryAvatarLayout.make(
                availableWidth: width,
                count: orderedIdols.count,
                maximumDiameter: size
            )
            ZStack(alignment: .leading) {
                ForEach(Array(orderedIdols.enumerated()), id: \.element.id) { index, idol in
                    Group {
                        if let asyncSourceKey {
                            ChekinanaCalendarDayIdolAvatar(
                                idol: idol, size: layout.diameter, sourceKey: asyncSourceKey
                            )
                        } else {
                            ChekinanaIdolAvatar(idol: idol, size: layout.diameter)
                        }
                    }
                        .overlay {
                            Circle().stroke(
                                Color(uiColor: .systemBackground),
                                lineWidth: 2
                            )
                        }
                        .offset(x: layout.x(for: index))
                }
            }
            .frame(width: width, height: size, alignment: .leading)
            .accessibilityHidden(true)
        }
    }
}

private struct ChekinanaCalendarThumbnailStrip: View {
    let chekis: [MediaItem]
    var usesPreparedOrder = false
    let onSelect: (MediaItem) -> Void

    private var displayedChekis: [MediaItem] {
        let ordered = usesPreparedOrder ? chekis
            : ChekinanaShotDisplayOrdering.chekis(chekis.sorted(by: ChekinanaRecordOrdering.chekiIndexPrecedes))
        return Array(ordered.prefix(5).reversed())
    }

    @AppStorage(ChekinanaShotDisplayOrdering.defaultsKey) private var twoShotFirst = false

    var body: some View {
        let _ = twoShotFirst
        HStack(spacing: ChekinanaCalendarSelectedDayLayout.thumbnailOverlap) {
            ForEach(Array(displayedChekis.enumerated()), id: \.element.id) { index, cheki in
                ChekinanaCalendarThumbnail(
                    cheki: cheki,
                    width: ChekinanaCalendarSelectedDayLayout.thumbnailWidth,
                    height: ChekinanaCalendarSelectedDayLayout.thumbnailHeight
                )
                    .overlay {
                        RoundedRectangle(cornerRadius: 7, style: .continuous)
                            .stroke(Color(uiColor: .systemBackground), lineWidth: 2)
                    }
                .zIndex(Double(index))
                .contentShape(Rectangle())
                .accessibilityElement(children: .ignore)
                .accessibilityAddTraits(.isButton)
                .accessibilityAction { onSelect(cheki) }
                .accessibilityLabel(
                    ChekinanaProductCopy.text(
                        "calendar.edit_record_action",
                        "Edit record"
                    )
                )
                .accessibilityIdentifier(
                    "chekinana.calendar.thumbnail.\(cheki.id.uuidString.lowercased())"
                )
            }
        }
        .frame(
            width: ChekinanaCalendarSelectedDayLayout.thumbnailStripWidth(
                count: min(chekis.count, 5)
            ),
            alignment: .trailing
        )
        .clipped()
    }
}

private struct ChekinanaCalendarThumbnail: View {
    let cheki: MediaItem
    var tracksReorderPreview = false
    var handoff: ChekinanaReorderThumbnailHandoff?
    var width: CGFloat = 50
    var height: CGFloat = 62
    @ObservedObject private var thumbnailRevisions =
        ChekinanaThumbnailRevisionStore.shared
    @State private var image: ChekinanaRenderedImage?
    @State private var loadedIdentity: ChekinanaThumbnailLoadIdentity?

    init(cheki: MediaItem, tracksReorderPreview: Bool = false, handoff: ChekinanaReorderThumbnailHandoff? = nil, width: CGFloat = 50, height: CGFloat = 62) {
        self.cheki = cheki
        self.tracksReorderPreview = tracksReorderPreview
        self.handoff = handoff
        self.width = width
        self.height = height
        let identity = ChekinanaThumbnailRevisionStore.shared.identity(imageRef: cheki.imageRef, sourceKey: "product-calendar-\(cheki.id.uuidString)")
        let seeded = handoff?.image(for: identity).map { ChekinanaRenderedImage(cgImage: $0) }
        _image = State(initialValue: seeded)
        _loadedIdentity = State(initialValue: seeded == nil ? nil : identity)
    }

    private var imageLoadIdentity: ChekinanaThumbnailLoadIdentity {
        thumbnailRevisions.identity(
            imageRef: cheki.imageRef,
            sourceKey: "product-calendar-\(cheki.id.uuidString)"
        )
    }

    var body: some View {
        let currentIdentity = imageLoadIdentity
        // Existing rows may already be awaiting the actor cache when the drag
        // ends. Render the transferred pixels without waiting for that task.
        let displayedImage = tracksReorderPreview
            ? ((loadedIdentity == currentIdentity ? image : nil)
                ?? handoff?.image(for: currentIdentity).map { ChekinanaRenderedImage(cgImage: $0) })
            : image
        ZStack {
            Color(uiColor: .tertiarySystemGroupedBackground)
            if let image = displayedImage {
                Image(decorative: image.cgImage, scale: 1).resizable().scaledToFill()
            } else {
                Image(systemName: "photo").foregroundStyle(.tertiary)
            }
        }
        .frame(width: width, height: height)
        .clipShape(RoundedRectangle(cornerRadius: 9, style: .continuous))
        .background {
            if tracksReorderPreview {
                ChekinanaReorderThumbnailSurface(itemKey: cheki.id.uuidString.lowercased(), image: displayedImage, identity: currentIdentity, handoff: handoff)
                    .allowsHitTesting(false)
            }
        }
        .onChange(of: handoff?.revision, initial: true) { _, _ in
            guard tracksReorderPreview,
                  let transferred = handoff?.image(for: imageLoadIdentity) else { return }
            // Adopt during this view update, independent of any suspended loader.
            // A subsequent drag can safely clear the now-consumed handoff.
            image = ChekinanaRenderedImage(cgImage: transferred)
            loadedIdentity = imageLoadIdentity
            handoff?.consumed(imageLoadIdentity)
        }
        .task(id: imageLoadIdentity) {
            let requestedIdentity = imageLoadIdentity
            if tracksReorderPreview {
                if let transferred = handoff?.image(for: requestedIdentity) {
                    image = ChekinanaRenderedImage(cgImage: transferred)
                    loadedIdentity = requestedIdentity
                    handoff?.consumed(requestedIdentity)
                    return
                }
                if loadedIdentity == requestedIdentity, image != nil { return }
            }
            image = nil
            loadedIdentity = nil
            let loaded = await ChekinanaThumbnailCache.shared.thumbnailImage(
                forManagedImageRef: cheki.imageRef,
                key: "product-calendar-\(cheki.id.uuidString)",
                maxDimension: 240
            )
            guard !Task.isCancelled, requestedIdentity == imageLoadIdentity else { return }
            if tracksReorderPreview, loadedIdentity == requestedIdentity, image != nil { return }
            image = handoff?.image(for: requestedIdentity).map { ChekinanaRenderedImage(cgImage: $0) } ?? loaded
            loadedIdentity = requestedIdentity
            handoff?.consumed(requestedIdentity)
        }
    }
}

enum ChekinanaCalendarGroupEditorError: LocalizedError, Equatable {
    case invalidDate
    case invalidIndex
    case indexRequiresGroup
    case indexCollision(Int)
    case missingIdol
    case changedRecord
    case changedField(ChekinanaCalendarRecordDraftField)
    case conflictingEventSelection

    var errorDescription: String? {
        switch self {
        case .invalidDate:
            ChekinanaProductCopy.text(
                "error.normalize_date",
                "Unable to normalize the selected date."
            )
        case .invalidIndex:
            ChekinanaProductCopy.text(
                "error.invalid_index",
                "Index must be empty or a positive integer."
            )
        case .indexRequiresGroup:
            ChekinanaProductCopy.text(
                "error.index_requires_group",
                "A positive index requires both a date and at least one Idol."
            )
        case .indexCollision(let value):
            ChekinanaProductCopy.format(
                "error.index_collision_for_value",
                "Index #%lld is already used in this Idol/date group.",
                Int64(value)
            )
        case .missingIdol:
            ChekinanaProductCopy.text(
                "calendar.choose_idol_error",
                "Choose at least one Idol."
            )
        case .changedRecord:
            ChekinanaProductCopy.text(
                "calendar.record_changed",
                "A Cheki record changed or was deleted. Reopen this editor and try again."
            )
        case .changedField(let field):
            ChekinanaProductCopy.format(
                "calendar.record_field_changed",
                "Another edit also changed %1$@. Reopen this editor to review both edits.",
                field.displayName
            )
        case .conflictingEventSelection:
            ChekinanaProductCopy.text(
                "calendar.conflicting_event_selection",
                "Two Cheki rows in the same Idol/date group select different Events. Choose one Event or clear a row, then save again."
            )
        }
    }
}

enum ChekinanaCalendarRecordDraftField: String, CaseIterable, Hashable, Sendable {
    case idolIDs
    case count
    case date
    case eventID
    case size
    case note

    var displayName: String {
        switch self {
        case .idolIDs:
            ChekinanaProductCopy.text("common.idols", "Idols")
        case .count:
            ChekinanaProductCopy.text("common.quantity", "Quantity")
        case .date:
            ChekinanaProductCopy.text("common.date", "Date")
        case .eventID:
            ChekinanaProductCopy.text("events.event", "Event")
        case .size:
            ChekinanaProductCopy.text("common.size", "Size")
        case .note:
            ChekinanaProductCopy.text("common.note", "Note")
        }
    }
}

struct ChekinanaCalendarRecordFingerprint: Hashable, Sendable {
    let id: UUID
    var idolIDs: [UUID]
    var count: Int
    var canonicalDate: Date?
    var eventID: UUID?
    var size: ChekiSize
    var note: String

    init(_ record: ChekiRecord) {
        id = record.id
        idolIDs = Self.normalizedIdolIDs(record.idolIDs)
        count = record.count
        canonicalDate = record.date.flatMap(ChekinanaDateOnly.canonicalized)
        eventID = record.eventID
        size = record.size ?? .mini
        note = record.note
    }

    init(
        id: UUID,
        idolIDs: some Sequence<UUID>,
        count: Int,
        canonicalDate: Date?,
        eventID: UUID?,
        size: ChekiSize,
        note: String
    ) {
        self.id = id
        self.idolIDs = Self.normalizedIdolIDs(idolIDs)
        self.count = count
        self.canonicalDate = canonicalDate.flatMap(ChekinanaDateOnly.canonicalized)
        self.eventID = eventID
        self.size = size
        self.note = note
    }

    private static func normalizedIdolIDs(
        _ ids: some Sequence<UUID>
    ) -> [UUID] {
        Array(Set(ids)).sorted { $0.uuidString < $1.uuidString }
    }
}

struct ChekinanaCalendarRecordDraft: Identifiable {
    let id: UUID
    var idolIDs: Set<UUID>
    var count: Int
    var hasDate: Bool
    var date: Date
    var eventID: UUID?
    var size: ChekiSize?
    var note: String
    private(set) var baselineFingerprint: ChekinanaCalendarRecordFingerprint
    private(set) var dirtyFields: Set<ChekinanaCalendarRecordDraftField> = []

    init(_ record: ChekiRecord) {
        let fingerprint = ChekinanaCalendarRecordFingerprint(record)
        id = record.id
        idolIDs = Set(record.idolIDs)
        count = max(1, record.count)
        hasDate = record.date != nil
        date = record.date.flatMap {
            ChekinanaDateOnly.displayDate(from: $0, calendar: .current)
        } ?? Date()
        eventID = record.eventID
        size = record.size
        note = record.note
        baselineFingerprint = fingerprint
    }

    mutating func set<Value>(
        _ value: Value,
        for field: ChekinanaCalendarRecordDraftField,
        at keyPath: WritableKeyPath<ChekinanaCalendarRecordDraft, Value>
    ) {
        self[keyPath: keyPath] = value
        dirtyFields.insert(field)
    }

    /// Three-way refresh for nested editor returns: clean fields follow the
    /// persisted value and advance their baseline, while dirty fields retain
    /// the user's unsaved value and original comparison point.
    mutating func mergeUnmodifiedFields(
        from live: ChekinanaCalendarRecordFingerprint,
        calendar: Calendar = .current
    ) {
        guard live.id == id else { return }
        if !dirtyFields.contains(.idolIDs) {
            idolIDs = Set(live.idolIDs)
            baselineFingerprint.idolIDs = live.idolIDs
        }
        if !dirtyFields.contains(.count) {
            count = max(1, live.count)
            baselineFingerprint.count = live.count
        }
        if !dirtyFields.contains(.date) {
            hasDate = live.canonicalDate != nil
            date = live.canonicalDate.flatMap {
                ChekinanaDateOnly.displayDate(from: $0, calendar: calendar)
            } ?? Date()
            baselineFingerprint.canonicalDate = live.canonicalDate
        }
        if !dirtyFields.contains(.eventID) {
            eventID = live.eventID
            baselineFingerprint.eventID = live.eventID
        }
        if !dirtyFields.contains(.size) {
            size = live.size
            baselineFingerprint.size = live.size
        }
        if !dirtyFields.contains(.note) {
            note = live.note
            baselineFingerprint.note = live.note
        }
    }
}

struct ChekinanaCalendarRecordPendingEdit: Sendable {
    let id: UUID
    let baseline: ChekinanaCalendarRecordFingerprint
    let dirtyFields: Set<ChekinanaCalendarRecordDraftField>
    let idolIDs: [UUID]
    let count: Int
    let canonicalDate: Date?
    let eventID: UUID?
    let size: ChekiSize
    let note: String

    init(
        draft: ChekinanaCalendarRecordDraft,
        resolvedIdolIDs: some Sequence<UUID>,
        canonicalDate: Date?
    ) {
        id = draft.id
        baseline = draft.baselineFingerprint
        dirtyFields = draft.dirtyFields
        idolIDs = Array(Set(resolvedIdolIDs)).sorted {
            $0.uuidString < $1.uuidString
        }
        count = draft.count
        self.canonicalDate = canonicalDate.flatMap(ChekinanaDateOnly.canonicalized)
        eventID = draft.eventID
        size = draft.size ?? .mini
        note = draft.note
    }
}

@MainActor
enum ChekinanaCalendarGroupRecordWriter {
    typealias SaveContext = (ModelContext) throws -> Void

    private struct PropagationGroup: Hashable {
        let idolID: UUID
        let canonicalDate: Date
    }

    private struct MutationPlan {
        let target: ChekiRecord
        let final: ChekinanaCalendarRecordFingerprint
        let dirtyFields: Set<ChekinanaCalendarRecordDraftField>
    }

    static func commit(
        _ edits: [ChekinanaCalendarRecordPendingEdit],
        in sourceContext: ModelContext,
        saveContext: SaveContext = { try $0.save() }
    ) throws {
        try ChekinanaChekiRecordStore.withMutationLock {
            let modelContext = ModelContext(sourceContext.container)
            modelContext.autosaveEnabled = false

            let requestedRecordIDs = edits.map(\.id)
            guard Set(requestedRecordIDs).count == requestedRecordIDs.count else {
                throw ChekinanaCalendarGroupEditorError.changedRecord
            }
            let allRecords = try modelContext.fetch(FetchDescriptor<ChekiRecord>(
                predicate: #Predicate { requestedRecordIDs.contains($0.id) }
            ))
            let recordsByID = Dictionary(uniqueKeysWithValues: allRecords.map { ($0.id, $0) })

            let plans = try edits.map { edit -> MutationPlan in
                guard let target = recordsByID[edit.id] else {
                    throw ChekinanaCalendarGroupEditorError.changedRecord
                }
                let live = ChekinanaCalendarRecordFingerprint(target)
                let final = try mergedFingerprint(edit: edit, live: live)

                guard final.count >= 0 else {
                    throw ChekinanaChekiRecordMutationError.quantityOverflow
                }
                return MutationPlan(
                    target: target,
                    final: final,
                    dirtyFields: edit.dirtyFields
                )
            }

            let requestedIdolIDs = Array(Set(
                plans.filter { $0.final.count > 0 }.flatMap { $0.final.idolIDs }
            ))
            let requestedEventIDs = Array(Set(
                plans.filter { $0.final.count > 0 }.compactMap { $0.final.eventID }
            ))
            let existingIdolIDs = Set(try modelContext.fetch(FetchDescriptor<Idol>(
                predicate: #Predicate { requestedIdolIDs.contains($0.id) }
            )).map(\.id))
            let existingEventIDs = Set(try modelContext.fetch(FetchDescriptor<Event>(
                predicate: #Predicate { requestedEventIDs.contains($0.id) }
            )).map(\.id))
            for plan in plans where plan.final.count > 0 {
                guard Set(plan.final.idolIDs).isSubset(of: existingIdolIDs),
                      plan.final.eventID.map({ existingEventIDs.contains($0) }) ?? true else {
                    throw ChekinanaChekiRecordMutationError.missingRelationships
                }
            }

            var explicitEventsByGroup: [PropagationGroup: Set<UUID>] = [:]
            for plan in plans where
                plan.final.count > 0
                    && plan.dirtyFields.contains(.eventID) {
                guard plan.final.idolIDs.count == 1,
                      let idolID = plan.final.idolIDs.first,
                      let date = plan.final.canonicalDate,
                      let eventID = plan.final.eventID else {
                    continue
                }
                explicitEventsByGroup[
                    PropagationGroup(idolID: idolID, canonicalDate: date),
                    default: []
                ].insert(eventID)
            }
            guard explicitEventsByGroup.values.allSatisfy({ $0.count <= 1 }) else {
                throw ChekinanaCalendarGroupEditorError.conflictingEventSelection
            }

            let protectedRecordIDs = Set(
                plans.filter {
                    $0.final.count == 0 || $0.dirtyFields.contains(.eventID)
                }
                    .map { $0.final.id }
            )

            // No await occurs after this boundary. The final values,
            // propagation, and one synchronous save are one rollback-capable
            // commit segment.
            do {
                for plan in plans {
                    if plan.final.count == 0 {
                        modelContext.delete(plan.target)
                        continue
                    }
                    plan.target.idolIDs = plan.final.idolIDs
                    plan.target.eventID = plan.final.eventID
                    plan.target.date = plan.final.canonicalDate
                    plan.target.size = plan.final.size
                    plan.target.note = plan.final.note
                    plan.target.count = plan.final.count
                }
                for (group, eventIDs) in explicitEventsByGroup {
                    guard let eventID = eventIDs.first else { continue }
                    // A row can move into this propagation group in the same
                    // batch. Apply to planned targets directly as well as
                    // querying unchanged targets from the persistent store.
                    for plan in plans where
                        plan.final.count > 0
                            && !protectedRecordIDs.contains(plan.final.id)
                            && plan.target.eventID == nil
                            && plan.target.idolIDs == [group.idolID]
                            && plan.target.date.flatMap(ChekinanaDateOnly.canonicalized)
                                == group.canonicalDate {
                        plan.target.eventID = eventID
                    }
                    try ChekinanaEventAssociationPropagation.propagate(
                        idolIDs: [group.idolID],
                        eventID: eventID,
                        date: group.canonicalDate,
                        protectingRecordIDs: protectedRecordIDs,
                        in: modelContext
                    )
                }
                try saveContext(modelContext)
            } catch {
                modelContext.rollback()
                throw error
            }
        }
    }

    private static func mergedFingerprint(
        edit: ChekinanaCalendarRecordPendingEdit,
        live: ChekinanaCalendarRecordFingerprint
    ) throws -> ChekinanaCalendarRecordFingerprint {
        guard edit.baseline.id == edit.id, live.id == edit.id else {
            throw ChekinanaCalendarGroupEditorError.changedRecord
        }
        return .init(
            id: edit.id,
            idolIDs: try merged(
                field: .idolIDs,
                baseline: edit.baseline.idolIDs,
                local: edit.idolIDs,
                live: live.idolIDs,
                isDirty: edit.dirtyFields.contains(.idolIDs)
            ),
            count: try merged(
                field: .count,
                baseline: edit.baseline.count,
                local: edit.count,
                live: live.count,
                isDirty: edit.dirtyFields.contains(.count)
            ),
            canonicalDate: try merged(
                field: .date,
                baseline: edit.baseline.canonicalDate,
                local: edit.canonicalDate,
                live: live.canonicalDate,
                isDirty: edit.dirtyFields.contains(.date)
            ),
            // Event is intentionally asymmetric: a current-session explicit
            // selection or clear beats an Event that arrived after a nil
            // baseline through propagation. Cross-row explicit disagreement is
            // rejected above instead of choosing a row-order winner.
            eventID: try mergedEvent(edit: edit, live: live),
            size: try merged(
                field: .size,
                baseline: edit.baseline.size,
                local: edit.size,
                live: live.size,
                isDirty: edit.dirtyFields.contains(.size)
            ),
            note: try merged(
                field: .note,
                baseline: edit.baseline.note,
                local: edit.note,
                live: live.note,
                isDirty: edit.dirtyFields.contains(.note)
            )
        )
    }

    private static func mergedEvent(
        edit: ChekinanaCalendarRecordPendingEdit,
        live: ChekinanaCalendarRecordFingerprint
    ) throws -> UUID? {
        guard edit.dirtyFields.contains(.eventID) else { return live.eventID }
        // A local explicit clear is authoritative even when an Event arrived
        // through propagation after the editor opened.
        guard let localEventID = edit.eventID else { return nil }
        if live.eventID == edit.baseline.eventID
            || live.eventID == localEventID
            || edit.baseline.eventID == nil {
            return localEventID
        }
        throw ChekinanaCalendarGroupEditorError.changedField(.eventID)
    }

    private static func merged<Value: Equatable>(
        field: ChekinanaCalendarRecordDraftField,
        baseline: Value,
        local: Value,
        live: Value,
        isDirty: Bool
    ) throws -> Value {
        guard isDirty else { return live }
        guard live == baseline || live == local else {
            throw ChekinanaCalendarGroupEditorError.changedField(field)
        }
        return local
    }
}

private struct ChekinanaCalendarRecordIdolSelection: Identifiable {
    let id: UUID
}

// A single in-memory rendering of this editor, used only while its last
// object disappears beneath a presented media page. It holds no model objects.
@MainActor
private final class ChekinanaCalendarEditorExitRendering {
    weak var view: UIView?

    func capture() -> UIImage? {
        guard let view, let window = view.window,
              view.bounds.width > 0, view.bounds.height > 0 else { return nil }
        let rect = view.convert(view.bounds, to: window)
        guard window.bounds.contains(rect), !rect.isEmpty else { return nil }
        var didRender = false
        let image = UIGraphicsImageRenderer(size: rect.size).image { _ in
            didRender = window.drawHierarchy(
                in: CGRect(origin: CGPoint(x: -rect.minX, y: -rect.minY), size: window.bounds.size),
                afterScreenUpdates: false
            )
        }
        return didRender ? image : nil
    }
}

private struct ChekinanaCalendarEditorRenderingAnchor: UIViewRepresentable {
    let rendering: ChekinanaCalendarEditorExitRendering
    func makeUIView(context: Context) -> UIView {
        let view = UIView()
        view.isUserInteractionEnabled = false
        rendering.view = view
        return view
    }
    func updateUIView(_ view: UIView, context: Context) { rendering.view = view }
}

private struct ChekinanaCalendarGroupEditor: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @Environment(\.chekinanaIdolOrdering) private var idolOrdering
    @Query private var idols: [Idol]
    @Query(sort: \Event.date) private var events: [Event]
    @Query private var eventSchedules: [EventSchedule]
    @Query private var chekis: [MediaItem]
    @Query private var records: [ChekiRecord]
    @Query private var shames: [MediaItem]
    @Query private var dougas: [MediaItem]
    @ObservedObject private var hiddenIdols = ChekinanaHiddenIdolStore.shared
    let selection: ChekinanaCalendarGroupEditorSelection

    @State private var exitRendering = ChekinanaCalendarEditorExitRendering()
    @State private var lastVisibleRendering: UIImage?
    @State private var previewMediaItem: ChekinanaGalleryItem?
    @State private var noteDrafts: [UUID: ChekinanaRecordNoteDraft] = [:]
    @State private var recordDrafts: [ChekinanaCalendarRecordDraft] = []
    @State private var idolSelectionRecord: ChekinanaCalendarRecordIdolSelection?
    @State private var didLoadDrafts = false
    @State private var isSaving = false
    @State private var errorMessage: String?

    init(selection: ChekinanaCalendarGroupEditorSelection) {
        self.selection = selection
        let chekiIDs = selection.chekiIDs
        let recordIDs = selection.recordIDs
        let shameIDs = selection.shameIDs
        let dougaIDs = selection.dougaIDs
        let chekiKind = MediaItemKind.cheki.rawValue
        let shameKind = MediaItemKind.shame.rawValue
        let dougaKind = MediaItemKind.douga.rawValue
        _chekis = Query(filter: #Predicate<MediaItem> {
            chekiIDs.contains($0.id) && $0.kindRawValue == chekiKind
        })
        _records = Query(filter: #Predicate<ChekiRecord> {
            recordIDs.contains($0.id)
        })
        _shames = Query(filter: #Predicate<MediaItem> {
            shameIDs.contains($0.id) && $0.kindRawValue == shameKind
        })
        _dougas = Query(filter: #Predicate<MediaItem> {
            dougaIDs.contains($0.id) && $0.kindRawValue == dougaKind
        })
    }

    private var group: ChekinanaCalendarIdolGroup? {
        let chekiIDs = Set(selection.chekiIDs)
        let recordIDs = Set(selection.recordIDs)
        let shameIDs = Set(selection.shameIDs)
        let dougaIDs = Set(selection.dougaIDs)
        return .init(
            id: "stable-\(selection.id)",
            idol: nil,
            orderedIdols: visibleIdols.filter { selection.combinationKey.idolIDs.contains($0.id) },
            chekis: ChekinanaRecordOrdering.orderedChekis(chekis.filter {
                chekiIDs.contains($0.id) && $0.imageRef?.nonEmpty != nil
            }),
            records: records.filter { recordIDs.contains($0.id) }
                .sorted { $0.id.uuidString < $1.id.uuidString },
            shames: ChekinanaShotDisplayOrdering.media(shames.filter { shameIDs.contains($0.id) }
                .sorted { $0.id.uuidString < $1.id.uuidString }),
            dougas: ChekinanaShotDisplayOrdering.media(dougas.filter { dougaIDs.contains($0.id) }
                .sorted { $0.id.uuidString < $1.id.uuidString }),
            combinationKey: selection.combinationKey
        )
    }

    private var availableStableObjectIDs: [UUID] {
        group?.allObjectIDs.sorted { $0.uuidString < $1.uuidString } ?? []
    }

    private var liveRecordFingerprints: [ChekinanaCalendarRecordFingerprint] {
        let selectedIDs = Set(selection.recordIDs)
        return records.filter { selectedIDs.contains($0.id) }
            .map(ChekinanaCalendarRecordFingerprint.init)
            .sorted { $0.id.uuidString < $1.id.uuidString }
    }

    var body: some View {
        NavigationStack {
            Group {
                if let currentGroup = group, !currentGroup.chekis.isEmpty || !currentGroup.shames.isEmpty || !currentGroup.dougas.isEmpty {
                    List {
                        if didLoadDrafts {
                            if !recordDrafts.isEmpty {
                                VStack(alignment: .leading, spacing: 14) {
                                    ForEach(recordDrafts) { draft in
                                        recordEditorSection(draft)
                                    }
                                }
                                .listRowInsets(EdgeInsets(top: 16, leading: 16, bottom: 16, trailing: 16))
                                .listRowBackground(Color.clear)
                                .listRowSeparator(.hidden)
                            }
                            if let mediaGroup = group {
                                ChekinanaUnifiedChekiGroupSections(
                                    groups: [mediaGroup],
                                    selectCheki: { presentMedia(.cheki($0)) },
                                    selectRecord: { _ in },
                                    selectOtherMedia: { media in
                                        presentMedia(media.kind == .shame ? .shame(media) : .douga(media))
                                    },
                                    separatesMediaTypes: true,
                                    allowsChekiReordering: false,
                                    showsChekiRecords: false,
                                    reportReorderError: { errorMessage = $0.localizedDescription }
                                )
                            }
                            if let errorMessage {
                                ChekinanaSectionCard {
                                    ChekinanaInlineStatus(message: errorMessage, kind: .error)
                                }
                                .listRowBackground(Color.clear)
                                .listRowSeparator(.hidden)
                            }
                        } else {
                            ContentUnavailableView(
                                ChekinanaProductCopy.text("calendar.no_records", "No records"),
                                systemImage: "photo.on.rectangle.angled"
                            )
                            .frame(maxWidth: .infinity, minHeight: 320)
                        }
                    }
                    .listStyle(.plain)
                    .chekinanaGroupedPageBackground()
                } else {
                    ScrollView {
                        if didLoadDrafts {
                            VStack(alignment: .leading, spacing: 14) {
                                ForEach(recordDrafts) { draft in
                                    recordEditorSection(draft)
                                }
                                if let errorMessage {
                                    ChekinanaSectionCard {
                                        ChekinanaInlineStatus(message: errorMessage, kind: .error)
                                    }
                                }
                            }
                            .padding(16)
                        } else {
                            ContentUnavailableView(
                                ChekinanaProductCopy.text("calendar.no_records", "No records"),
                                systemImage: "photo.on.rectangle.angled"
                            )
                            .frame(maxWidth: .infinity, minHeight: 320)
                        }
                    }
                    .background(ChekinanaProductTheme.pageBackground)
                }
            }
            .navigationTitle("")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        dismiss()
                    }
                    .disabled(isSaving)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(
                        ChekinanaProductCopy.text("common.save", "Save"),
                        action: saveAll
                    )
                    .disabled(isSaving || !didLoadDrafts)
                    .accessibilityIdentifier("chekinana.calendar.group-editor.save")
                }
            }
        }
        .disabled(lastVisibleRendering != nil && availableStableObjectIDs.isEmpty)
        .background(ChekinanaCalendarEditorRenderingAnchor(rendering: exitRendering))
        .overlay {
            if availableStableObjectIDs.isEmpty, let lastVisibleRendering {
                Image(uiImage: lastVisibleRendering)
                    .resizable()
                    .allowsHitTesting(false)
                    .accessibilityHidden(true)
            }
        }
        .fullScreenCover(
            item: $previewMediaItem,
            onDismiss: {
                refreshDraftsFromPersistedState()
                if !availableStableObjectIDs.isEmpty { lastVisibleRendering = nil }
            }
        ) { item in
            switch item {
            case .cheki(let cheki):
                ChekinanaGalleryDetailView(
                    chekis: group?.chekis ?? [cheki],
                    initialID: cheki.id
                )
            case .shame(let shame):
                ChekinanaGalleryMediaPagerView(
                    items: group?.shames ?? [shame],
                    kind: .shame,
                    initialID: shame.id
                )
            case .douga(let douga):
                ChekinanaGalleryMediaPagerView(
                    items: group?.dougas ?? [douga],
                    kind: .douga,
                    initialID: douga.id
                )
            }
        }
        .sheet(item: $idolSelectionRecord) { selection in
            if let selectionBinding = idolSelectionBinding(for: selection.id) {
                ChekinanaIdolAvatarCheckSelectionView(
                    idols: visibleIdols,
                    selectedIDs: selectionBinding,
                    identifierPrefix: "chekinana.calendar.group-editor.idol-selection",
                    commitsOnDone: true
                )
            }
        }
        .interactiveDismissDisabled(isSaving)
        .task(id: selection.id) { loadDraftsIfNeeded() }
        .onChange(of: liveRecordFingerprints) { _, fingerprints in
            mergeLiveFingerprints(fingerprints)
        }
        .onChange(of: availableStableObjectIDs) { oldIDs, newIDs in
            guard didLoadDrafts, !oldIDs.isEmpty, newIDs.isEmpty else { return }
            // Dismiss this presentation with its child, rather than first
            // revealing the now-empty editor beneath the media preview.
            dismiss()
        }
        .accessibilityIdentifier("chekinana.calendar.group-editor")
        .chekinanaSheetDraftDismiss(
            ready: didLoadDrafts || group == nil,
            isBusy: { isSaving },
            snapshot: { [] },
            hasUnsavedChanges: {
                recordDrafts.contains { draft in
                    let baseline = draft.baselineFingerprint
                    return draft.idolIDs != Set(baseline.idolIDs)
                        || draft.count != max(1, baseline.count)
                        || draft.hasDate != (baseline.canonicalDate != nil)
                        || (draft.hasDate && (try? normalizedDate(
                            hasDate: true, displayedDate: draft.date
                        )) != baseline.canonicalDate)
                        || draft.eventID != baseline.eventID
                        || (draft.size ?? .mini) != baseline.size
                        || (noteDrafts[draft.id]?.text ?? draft.note) != baseline.note
                }
            }
        )
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    @ViewBuilder
    private func mediaStripSection(
        title: String,
        items: [ChekinanaGalleryItem],
        identifier: String
    ) -> some View {
        if !items.isEmpty {
            ChekinanaSectionCard {
                VStack(alignment: .leading, spacing: 10) {
                    Text(title)
                        .font(.headline)
                    ScrollView(.horizontal) {
                        LazyHStack(spacing: 10) {
                            ForEach(items) { item in
                                Button {
                                    previewMediaItem = item
                                } label: {
                                    ChekinanaCalendarGroupMediaThumbnail(item: item)
                                }
                                .buttonStyle(.plain)
                                .accessibilityIdentifier(
                                    "chekinana.calendar.group-editor.\(identifier)-media.\(item.modelID.uuidString.lowercased())"
                                )
                            }
                        }
                        .padding(.vertical, 2)
                    }
                    .scrollIndicators(.hidden)
                    .accessibilityIdentifier(
                        "chekinana.calendar.group-editor.\(identifier)-media-strip"
                    )
                }
            }
        }
    }

    @ViewBuilder
    private func recordEditorSection(
        _ original: ChekinanaCalendarRecordDraft
    ) -> some View {
        if let noteDraft = noteDrafts[original.id] {
            let draft = Binding(
                get: { recordDrafts.first { $0.id == original.id } ?? original },
                set: { value in
                    guard let index = recordDrafts.firstIndex(where: { $0.id == original.id }) else { return }
                    recordDrafts[index] = value
                }
            )
            ChekinanaSectionCard {
                VStack(alignment: .leading, spacing: 10) {
                    Text(ChekinanaRecordKind.cheki.title)
                        .font(.headline)
                    ChekinanaChekiRecordEditorFields(
                        visibleIdols: visibleIdols,
                        events: events,
                        schedules: eventSchedules,
                        dateCalendar: .current,
                        identifierPrefix: "chekinana.calendar.group-editor.record.\(draft.wrappedValue.id.uuidString.lowercased())",
                        chooseIdols: {
                            idolSelectionRecord = .init(id: draft.wrappedValue.id)
                        },
                        idolIDs: dirtyBinding(
                            draft,
                            field: .idolIDs,
                            keyPath: \.idolIDs
                        ),
                        count: dirtyBinding(
                            draft,
                            field: .count,
                            keyPath: \.count
                        ),
                        hasDate: dirtyBinding(
                            draft,
                            field: .date,
                            keyPath: \.hasDate
                        ),
                        date: dirtyBinding(
                            draft,
                            field: .date,
                            keyPath: \.date
                        ),
                        eventID: dirtyBinding(
                            draft,
                            field: .eventID,
                            keyPath: \.eventID
                        ),
                        size: dirtyBinding(
                            draft,
                            field: .size,
                            keyPath: \.size
                        ),
                        noteDraft: noteDraft,
                        onNoteEdit: { if errorMessage != nil { errorMessage = nil } }
                    )
                    Button(
                        ChekinanaProductCopy.text("common.delete", "Delete"),
                        role: .destructive
                    ) {
                        deleteRecord(id: draft.wrappedValue.id)
                    }
                    .accessibilityIdentifier(
                        "chekinana.calendar.group-editor.record.\(draft.wrappedValue.id.uuidString.lowercased()).delete"
                    )
                }
            }
        }
    }

    private func loadDraftsIfNeeded() {
        guard !didLoadDrafts, let group else { return }
        recordDrafts = group.records.map(ChekinanaCalendarRecordDraft.init)
        noteDrafts = Dictionary(uniqueKeysWithValues: recordDrafts.map { ($0.id, ChekinanaRecordNoteDraft($0.note)) })
        didLoadDrafts = true
    }

    private func dirtyBinding<Value: Equatable>(
        _ draft: Binding<ChekinanaCalendarRecordDraft>,
        field: ChekinanaCalendarRecordDraftField,
        keyPath: WritableKeyPath<ChekinanaCalendarRecordDraft, Value>
    ) -> Binding<Value> {
        Binding(
            get: { draft.wrappedValue[keyPath: keyPath] },
            set: { newValue in
                var value = draft.wrappedValue
                guard field == .eventID
                        || value[keyPath: keyPath] != newValue else { return }
                value.set(newValue, for: field, at: keyPath)
                draft.wrappedValue = value
                errorMessage = nil
            }
        )
    }

    private func idolSelectionBinding(
        for id: UUID
    ) -> Binding<Set<UUID>>? {
        guard let original = recordDrafts.first(where: { $0.id == id }) else {
            return nil
        }
        return Binding(
            get: { (recordDrafts.first { $0.id == id } ?? original).idolIDs.subtracting(hiddenIdols.hiddenIDs) },
            set: { selectedIDs in
                guard let index = recordDrafts.firstIndex(where: { $0.id == id }) else { return }
                let selectedIDs = selectedIDs.union(recordDrafts[index].idolIDs.intersection(hiddenIdols.hiddenIDs))
                guard recordDrafts[index].idolIDs != selectedIDs else { return }
                recordDrafts[index].set(
                    selectedIDs,
                    for: .idolIDs,
                    at: \.idolIDs
                )
                errorMessage = nil
            }
        )
    }

    private func saveAll() {
        guard !isSaving else { return }
        isSaving = true
        defer { isSaving = false }
        do {
            try ChekinanaCalendarGroupRecordWriter.commit(
                try pendingRecordEdits(),
                in: modelContext
            )
            dismiss()
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private func pendingRecordEdits() throws -> [ChekinanaCalendarRecordPendingEdit] {
        try recordDrafts.map { storedDraft in
            let draft = draftWithCurrentNote(storedDraft)
            let selectedIDs: [UUID]
            if draft.dirtyFields.contains(.idolIDs) {
                selectedIDs = ChekinanaRequiredIdolSelectionPolicy.resolvedIDs(
                    selectedIDs: draft.idolIDs,
                    visibleIDs: idols.map(\.id)
                )
            } else {
                selectedIDs = Array(draft.idolIDs)
            }
            guard draft.count == 0 || Set(selectedIDs) == draft.idolIDs else {
                throw ChekinanaChekiRecordMutationError.missingRelationships
            }
            let date = try normalizedDate(
                hasDate: draft.hasDate,
                displayedDate: draft.date
            )
            return ChekinanaCalendarRecordPendingEdit(
                draft: draft,
                resolvedIdolIDs: selectedIDs,
                canonicalDate: date
            )
        }
    }

    private func draftWithCurrentNote(_ original: ChekinanaCalendarRecordDraft) -> ChekinanaCalendarRecordDraft {
        var draft = original
        if let note = noteDrafts[draft.id], note.wasEdited {
            draft.set(note.text, for: .note, at: \.note)
        }
        return draft
    }

    private func mergeLiveFingerprints(
        _ fingerprints: [ChekinanaCalendarRecordFingerprint]
    ) {
        guard didLoadDrafts else { return }
        let liveByID = Dictionary(uniqueKeysWithValues: fingerprints.map { ($0.id, $0) })
        for index in recordDrafts.indices {
            guard let live = liveByID[recordDrafts[index].id] else { continue }
            recordDrafts[index] = draftWithCurrentNote(recordDrafts[index])
            recordDrafts[index].mergeUnmodifiedFields(from: live)
            noteDrafts[recordDrafts[index].id]?.refreshUnedited(recordDrafts[index].note)
        }
    }

    private func refreshDraftsFromPersistedState() {
        guard didLoadDrafts else { return }
        do {
            let context = ModelContext(modelContext.container)
            context.autosaveEnabled = false
            let selectedIDs = Set(selection.recordIDs)
            let fingerprints = try context.fetch(FetchDescriptor<ChekiRecord>())
                .filter { selectedIDs.contains($0.id) }
                .map(ChekinanaCalendarRecordFingerprint.init)
            mergeLiveFingerprints(fingerprints)
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private func normalizedDate(
        hasDate: Bool,
        displayedDate: Date
    ) throws -> Date? {
        guard hasDate else { return nil }
        guard let date = ChekinanaPersistedContentDatePolicy
            .canonicalDate(from: displayedDate) else {
            throw ChekinanaCalendarGroupEditorError.invalidDate
        }
        return date
    }

    private func presentMedia(_ item: ChekinanaGalleryItem) {
        lastVisibleRendering = exitRendering.capture()
        previewMediaItem = item
    }

    private func deleteRecord(id: UUID) {
        // Keep the last editor's draft alive through dismissal. Waiting for the
        // Query update after clearing it briefly presents an empty sheet.
        let removesLastContent = !availableStableObjectIDs.contains { $0 != id }
        do {
            let target = try ChekinanaModelContextResolver.chekiRecord(
                id: id,
                in: modelContext
            )
            try ChekinanaChekiRecordStore.delete(
                target,
                expected: nil,
                in: modelContext
            )
            if removesLastContent {
                dismiss()
                return
            }
            recordDrafts.removeAll { $0.id == id }
            noteDrafts.removeValue(forKey: id)
        } catch {
            modelContext.rollback()
            errorMessage = error.localizedDescription
        }
    }

}

private struct ChekinanaCalendarGroupMediaThumbnail: View {
    let item: ChekinanaGalleryItem
    var width: CGFloat = 104
    var height: CGFloat = 136
    @ObservedObject private var thumbnailRevisions =
        ChekinanaThumbnailRevisionStore.shared
    @State private var image: ChekinanaRenderedImage?

    private var imageReference: String? {
        switch item {
        case .cheki(let cheki):
            cheki.imageRef
        case .shame(let shame):
            shame.imageRef
        case .douga(let douga):
            ChekinanaGalleryMediaStore.thumbnailReference(id: douga.mediaOwnerID)
        }
    }

    private var imageLoadIdentity: ChekinanaThumbnailLoadIdentity {
        thumbnailRevisions.identity(
            imageRef: imageReference,
            sourceKey: "calendar-group-editor-\(item.id)"
        )
    }

    var body: some View {
        ZStack {
            Color(uiColor: .tertiarySystemGroupedBackground)
            if let image {
                if item.kind == .cheki {
                    ChekinanaFixedChekiThumbnailImage(image: image)
                } else {
                    Image(decorative: image.cgImage, scale: 1)
                        .resizable()
                        .scaledToFit()
                        .padding(3)
                }
            } else {
                Image(systemName: item.kind == .douga ? "video" : "photo")
                    .font(.title2)
                    .foregroundStyle(.tertiary)
            }
            if item.kind == .douga {
                Image(systemName: "play.circle.fill")
                    .font(.title)
                    .symbolRenderingMode(.palette)
                    .foregroundStyle(.white, .black.opacity(0.55))
            }
        }
        .frame(width: width, height: height)
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(ChekinanaProductTheme.border, lineWidth: 0.5)
        }
        .task(id: imageLoadIdentity) {
            image = nil
            image = await ChekinanaThumbnailCache.shared.thumbnailImage(
                forManagedImageRef: imageReference,
                key: "calendar-group-editor-\(item.id)",
                maxDimension: 480
            )
        }
    }
}

private struct ChekinanaCalendarGroupSummary: View {
