    let idolPatternState: Int
    let idolAvatarState: Int
    let event: Int
    let eventSchedule: Int
    let eventImage: Int
    let calendarGroupOrder: Int
    let travelSegment: Int
    let mediaItem: Int
    let chekiRecord: Int
    let memory: Int
    let memoryAttachment: Int
    let customChekiSize: Int

    static let zero = Self(
        idol: 0,
        idolPatternState: 0,
        idolAvatarState: 0,
        event: 0,
        eventSchedule: 0,
        eventImage: 0,
        calendarGroupOrder: 0,
        travelSegment: 0,
        mediaItem: 0,
        chekiRecord: 0,
        memory: 0,
