    )
}

struct ChekinanaLocalDataClearResult: Equatable, Sendable {
    let chekiCount: Int
    let shameCount: Int
    let dougaCount: Int
    let eventCount: Int
    let idolCount: Int
    let removedFileCount: Int
    let deletedEntityCounts: ChekinanaLocalDataEntityCounts

    init(
        chekiCount: Int,
        shameCount: Int,
        dougaCount: Int,
        eventCount: Int,
        idolCount: Int,
        removedFileCount: Int,
        deletedEntityCounts: ChekinanaLocalDataEntityCounts = .zero
    ) {
        self.chekiCount = chekiCount
        self.shameCount = shameCount
        self.dougaCount = dougaCount
        self.eventCount = eventCount
        self.idolCount = idolCount
        self.removedFileCount = removedFileCount
        self.deletedEntityCounts = deletedEntityCounts
    }
}

enum ChekinanaLocalDataClearError: LocalizedError {
    case notCommitted(String)
    case database(String)
    case commitIndeterminate(String)
    case fileCleanup(
        ChekinanaLocalDataClearResult,
        pendingActionCount: Int,
        details: [String]
    )

    var errorDescription: String? {
        switch self {
        case .notCommitted(let detail):
            return ChekinanaProductCopy.format(
                "settings.clear_error.not_committed",
                "No data was cleared because safe cleanup could not be prepared: %@",
                detail
            )
        case .database(let detail):
            return ChekinanaProductCopy.format(
                "settings.clear_error.database",
                "No data was cleared because the local database could not be saved: %@",
                detail
            )
        case .commitIndeterminate(let detail):
            return ChekinanaProductCopy.format(
                "settings.clear_error.indeterminate",
                "No managed files were removed because the database commit could not be confirmed. Recovery will retry safely: %@",
                detail
            )
        case .fileCleanup(let result, let pendingActionCount, let details):
            return ChekinanaProductCopy.format(
                "settings.clear_error.files",
                "All local records were cleared, but %1$lld managed media cleanup action(s) remain. Removed %2$lld file(s). They will be retried safely. %3$@",
                Int64(max(1, pendingActionCount)),
                Int64(result.removedFileCount),
                details.joined(separator: "; ")
            )
        }
    }
}

struct ChekinanaLocalDataClearJournal: Codable, Equatable, Sendable {
    struct FileEntry: Codable, Equatable, Sendable {
        let filename: String
        let identity: ChekinanaImportFileIdentity
    }

    let formatVersion: Int
    let operationID: UUID
    let oldGeneration: UUID
    let newGeneration: UUID
    var files: [FileEntry]
    var protectedFilenames: [String]

    var isValid: Bool {
        guard formatVersion == 1,
              oldGeneration != newGeneration,
              Set(files.map(\.filename)).count == files.count,
              Set(protectedFilenames).count == protectedFilenames.count else {
            return false
        }
        let fileNames = Set(files.map(\.filename))
        let protectedNames = Set(protectedFilenames)
        guard fileNames.isDisjoint(with: protectedNames) else { return false }
        return files.allSatisfy {
            Self.isSafeFilename($0.filename) && $0.identity.isValid
        } && protectedFilenames.allSatisfy(Self.isSafeFilename)
    }

    private static func isSafeFilename(_ value: String) -> Bool {
        value != ChekinanaLocalDataClearJournalStore.journalFilename
            && value == URL(fileURLWithPath: value).lastPathComponent
            && value != "."
            && value != ".."
            && !value.isEmpty
    }
}

enum ChekinanaLocalDataClearJournalStore {
    static let journalFilename = ".library-clear-intent-v1.json"

    static func journalURL(in directory: URL) -> URL {
        directory.standardizedFileURL.appendingPathComponent(journalFilename)
    }

    static func load(
        in directory: URL,
        fileManager: FileManager = .default
    ) throws -> ChekinanaLocalDataClearJournal? {
        let url = journalURL(in: directory)
        guard fileManager.fileExists(atPath: url.path) else { return nil }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true, values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let journal = try JSONDecoder().decode(
            ChekinanaLocalDataClearJournal.self,
            from: Data(contentsOf: url)
        )
        guard journal.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        return journal
    }

    static func persist(
        _ journal: ChekinanaLocalDataClearJournal,
        in directory: URL,
        fileManager: FileManager = .default
    ) throws {
        guard journal.isValid else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let canonicalDirectory = directory.standardizedFileURL
        try fileManager.createDirectory(
            at: canonicalDirectory,
            withIntermediateDirectories: true
        )
        let directoryValues = try canonicalDirectory.resourceValues(
            forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        )
        guard directoryValues.isDirectory == true,
              directoryValues.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let url = journalURL(in: canonicalDirectory)
        if fileManager.fileExists(atPath: url.path) {
            let values = try url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            guard values.isRegularFile == true,
                  values.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
        }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        try encoder.encode(journal).write(to: url, options: [.atomic])
        let handle = try FileHandle(forWritingTo: url)
        do {
            try handle.synchronize()
            try handle.close()
        } catch {
            try? handle.close()
            throw error
        }
    }

    static func discard(
        in directory: URL,
        fileManager: FileManager = .default
    ) throws {
        let url = journalURL(in: directory)
        guard fileManager.fileExists(atPath: url.path) else { return }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true, values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        try fileManager.removeItem(at: url)
    }
}

struct ChekinanaLocalDataClearRecoveryReport: Equatable, Sendable {
    var foundIntent = false
    var databaseCommitted = false
    var removedFileCount = 0
    var deferredActionCount = 0
    var protectedFileCount = 0
    var blockedByImportTransaction = false
    var databaseStateIndeterminate = false

    var needsRetry: Bool {
        deferredActionCount > 0
            || blockedByImportTransaction
            || databaseStateIndeterminate
    }
}

@MainActor
enum ChekinanaLocalDataClearer {
    typealias SaveContext = (ModelContext) throws -> Void
    typealias RemoveFile = (URL) throws -> Void
    typealias DirectoryContents = (
        URL,
        [URLResourceKey],
        FileManager.DirectoryEnumerationOptions
    ) throws -> [URL]

    private enum CandidateResult {
        case completed(removed: Bool)
        case deferred
        case protected
    }

    @discardableResult
    static func clear(
        modelContext: ModelContext,
        managedImagesDirectory: URL? = nil,
        defaults: UserDefaults = .standard,
        fileManager: FileManager = .default,
        saveContext: SaveContext = { try $0.save() },
        contentsOfDirectory: DirectoryContents = {
            try FileManager.default.contentsOfDirectory(
                at: $0,
                includingPropertiesForKeys: $1,
                options: $2
            )
        },
        removeFile: @escaping RemoveFile = {
            try FileManager.default.removeItem(at: $0)
        },
        afterDatabaseCommit: () throws -> Void = {},
        beforeCandidateValidation: () -> Void = {}
    ) async throws -> ChekinanaLocalDataClearResult {
        try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            try clearExclusively(
                modelContext: modelContext,
                managedImagesDirectory: managedImagesDirectory,
                defaults: defaults,
                fileManager: fileManager,
                saveContext: saveContext,
                contentsOfDirectory: contentsOfDirectory,
                removeFile: removeFile,
                afterDatabaseCommit: afterDatabaseCommit,
                beforeCandidateValidation: beforeCandidateValidation
            )
        }
    }

    static func recoverUnfinishedClear(
        modelContext: ModelContext,
        managedImagesDirectory: URL? = nil,
        defaults: UserDefaults = .standard,
        fileManager: FileManager = .default,
        removeFile: @escaping RemoveFile = {
            try FileManager.default.removeItem(at: $0)
        },
        beforeCandidateValidation: () -> Void = {}
    ) async -> ChekinanaLocalDataClearRecoveryReport {
        await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            let directory: URL
            do {
                directory = try resolvedDirectory(
                    managedImagesDirectory,
                    fileManager: fileManager
                )
            } catch {
                return ChekinanaLocalDataClearRecoveryReport(
                    deferredActionCount: 1
                )
            }
            do {
                try ChekinanaPersistenceMutationCoordinator.withLock {
                    try ChekinanaChekiEditRecovery.requireConvergedExclusively(
                        in: modelContext,
                        directory: directory,
                        fileManager: fileManager
                    )
                }
            } catch {
                return ChekinanaLocalDataClearRecoveryReport(
                    deferredActionCount: 1,
                    databaseStateIndeterminate: true
                )
            }
            return recoverUnfinishedClearExclusively(
                modelContext: modelContext,
                directory: directory,
                defaults: defaults,
                fileManager: fileManager,
                removeFile: removeFile,
                beforeCandidateValidation: beforeCandidateValidation
            )
        }
    }

    /// Caller owns the library gate. This invokes only the non-recursive
    /// clear recovery core and cannot advance the library generation.
    static func requireClearConvergedExclusively(
        in modelContext: ModelContext,
        directory suppliedDirectory: URL? = nil,
        defaults: UserDefaults = .standard,
        fileManager: FileManager = .default
    ) throws {
        let directory = try resolvedDirectory(
            suppliedDirectory, fileManager: fileManager
        )
        let report = recoverUnfinishedClearExclusively(
            modelContext: modelContext,
            directory: directory,
            defaults: defaults,
            fileManager: fileManager,
            removeFile: { try fileManager.removeItem(at: $0) },
            beforeCandidateValidation: {}
        )
        if report.databaseStateIndeterminate {
            throw ChekinanaDataImportError.recoveryIndeterminate
        }
        guard !report.needsRetry else {
            throw ChekinanaDataImportError.recoveryIncomplete
        }
    }

    private static func clearExclusively(
        modelContext: ModelContext,
        managedImagesDirectory: URL?,
        defaults: UserDefaults,
        fileManager: FileManager,
        saveContext: SaveContext,
        contentsOfDirectory: DirectoryContents,
        removeFile: @escaping RemoveFile,
        afterDatabaseCommit: () throws -> Void,
        beforeCandidateValidation: () -> Void
    ) throws -> ChekinanaLocalDataClearResult {
        let directory: URL
        do {
            directory = try resolvedDirectory(
                managedImagesDirectory,
                fileManager: fileManager
            )
        } catch {
            throw ChekinanaLocalDataClearError.notCommitted(
                error.localizedDescription
            )
        }

        do {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: directory
            )
        } catch {
            throw ChekinanaLocalDataClearError.notCommitted(
                ChekinanaL10n.message("Pending library media recovery must finish first. \(error.localizedDescription)")
            )
        }

        let priorRecovery = recoverUnfinishedClearExclusively(
            modelContext: modelContext,
            directory: directory,
            defaults: defaults,
            fileManager: fileManager,
            removeFile: removeFile,
            beforeCandidateValidation: beforeCandidateValidation
        )
        if priorRecovery.needsRetry {
            if priorRecovery.databaseCommitted {
                throw ChekinanaLocalDataClearError.fileCleanup(
                    emptyResult(removedFileCount: priorRecovery.removedFileCount),
                    pendingActionCount: priorRecovery.deferredActionCount,
                    details: cleanupDetails(priorRecovery)
                )
            }
            if priorRecovery.databaseStateIndeterminate {
                throw ChekinanaLocalDataClearError.commitIndeterminate(
                    cleanupDetails(priorRecovery).joined(separator: "; ")
                )
            }
            throw ChekinanaLocalDataClearError.notCommitted(
                ChekinanaL10n.message("A previous uncommitted cleanup intent could not be retired.")
            )
        }

        do {
            guard try ChekinanaImportTransactionHandle.discover(
                in: directory,
                fileManager: fileManager
            ).isEmpty else {
                throw ChekinanaImportTransactionError.incomplete
            }
        } catch {
            throw ChekinanaLocalDataClearError.notCommitted(
                ChekinanaL10n.message("An unfinished backup import must recover first. \(error.localizedDescription)")
            )
        }

        let oldGeneration: UUID
        let oldReferences: ChekinanaLibraryFileReferenceSnapshot
        do {
            oldGeneration = try ChekinanaPersistenceMutationCoordinator.withLock {
                let generation = try ChekinanaLibraryGenerationStore.ensureCurrent(
                    in: modelContext
                )
                guard ChekinanaGalleryDeletionRecoveryCoordinator
                    .recoverExclusively(
                        in: modelContext,
                        directory: directory,
                        fileManager: fileManager,
                        removeItem: removeFile
                    ) == 0 else {
                    throw ChekinanaImportTransactionError.incomplete
                }
                return generation
            }
            oldReferences = try ChekinanaLibraryFileReferenceSnapshot.capture(
                in: ModelContext(modelContext.container),
                directory: directory
            )
            guard oldReferences.generation == oldGeneration else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        } catch {
            throw ChekinanaLocalDataClearError.notCommitted(
                error.localizedDescription
            )
        }

        let prepared: (
            files: [ChekinanaLocalDataClearJournal.FileEntry],
            protectedFilenames: [String]
        )
        do {
            prepared = try prepareFiles(
                in: directory,
                referencedFilenames: oldReferences.referencedFilenames,
                fileManager: fileManager,
                contentsOfDirectory: contentsOfDirectory
            )
        } catch {
            throw ChekinanaLocalDataClearError.notCommitted(
                error.localizedDescription
            )
        }

        let newGeneration = UUID()
        let journal = ChekinanaLocalDataClearJournal(
            formatVersion: 1,
            operationID: UUID(),
            oldGeneration: oldGeneration,
            newGeneration: newGeneration,
            files: prepared.files,
            protectedFilenames: prepared.protectedFilenames
        )
        do {
            try ChekinanaLocalDataClearJournalStore.persist(
                journal,
                in: directory,
                fileManager: fileManager
            )
        } catch {
            throw ChekinanaLocalDataClearError.notCommitted(
                error.localizedDescription
            )
        }

        var mediaItems: [MediaItem] = []
        var chekiRecords: [ChekiRecord] = []
        var events: [Event] = []
        var eventSchedules: [EventSchedule] = []
        var eventImages: [EventImage] = []
        var calendarGroupOrders: [CalendarGroupOrder] = []
        var travelSegments: [TravelSegment] = []
        var idols: [Idol] = []
        var patternStates: [IdolPatternState] = []
        var avatarStates: [IdolAvatarState] = []
        var memories: [Memory] = []
        var memoryAttachments: [MemoryAttachment] = []
        var customChekiSizes: [CustomChekiSize] = []
        var entityCounts = ChekinanaLocalDataEntityCounts.zero
        var chekiCount = 0
        var shameCount = 0
        var dougaCount = 0
        var commitError: Error?

        do {
            try ChekinanaPersistenceMutationCoordinator.withLock {
                try Task.checkCancellation()
                guard try ChekinanaImportTransactionHandle.discover(
                    in: directory,
                    fileManager: fileManager
                ).isEmpty,
                      try ChekinanaLibraryGenerationStore.current(
                        in: modelContext
                      ) == oldGeneration else {
                    throw ChekinanaImportTransactionError.indeterminate
                }

                // Current schema has exactly these 13 business entity types.
                // MediaItem is fetched and deleted once for all three kinds.
                idols = try modelContext.fetch(FetchDescriptor<Idol>())
                patternStates = try modelContext.fetch(
                    FetchDescriptor<IdolPatternState>()
                )
                avatarStates = try modelContext.fetch(
                    FetchDescriptor<IdolAvatarState>()
                )
                events = try modelContext.fetch(FetchDescriptor<Event>())
                eventSchedules = try modelContext.fetch(
                    FetchDescriptor<EventSchedule>()
                )
                eventImages = try modelContext.fetch(
                    FetchDescriptor<EventImage>()
                )
                calendarGroupOrders = try modelContext.fetch(
                    FetchDescriptor<CalendarGroupOrder>()
                )
                travelSegments = try modelContext.fetch(
                    FetchDescriptor<TravelSegment>()
                )
                mediaItems = try modelContext.fetch(FetchDescriptor<MediaItem>())
                chekiRecords = try modelContext.fetch(
                    FetchDescriptor<ChekiRecord>()
                )
                memories = try modelContext.fetch(FetchDescriptor<Memory>())
                memoryAttachments = try modelContext.fetch(
                    FetchDescriptor<MemoryAttachment>()
                )
                customChekiSizes = try modelContext.fetch(
                    FetchDescriptor<CustomChekiSize>()
                )

                entityCounts = ChekinanaLocalDataEntityCounts(
                    idol: idols.count,
                    idolPatternState: patternStates.count,
                    idolAvatarState: avatarStates.count,
                    event: events.count,
                    eventSchedule: eventSchedules.count,
                    eventImage: eventImages.count,
                    calendarGroupOrder: calendarGroupOrders.filter {
                        !ChekinanaLibraryGenerationStore.isMarker($0)
                    }.count,
                    travelSegment: travelSegments.count,
                    mediaItem: mediaItems.count,
                    chekiRecord: chekiRecords.count,
                    memory: memories.count,
                    memoryAttachment: memoryAttachments.count,
                    customChekiSize: customChekiSizes.count
                )
                chekiCount = ChekinanaDisplayCount.adding(
                    mediaItems.filter { $0.kind == .cheki }.count,
                    ChekinanaChekiRecordStore.totalCount(chekiRecords)
                )
                shameCount = mediaItems.filter { $0.kind == .shame }.count
                dougaCount = mediaItems.filter { $0.kind == .douga }.count

                memoryAttachments.forEach(modelContext.delete)
                memories.forEach(modelContext.delete)
                mediaItems.forEach(modelContext.delete)
                chekiRecords.forEach(modelContext.delete)
                eventImages.forEach(modelContext.delete)
                eventSchedules.forEach(modelContext.delete)
                calendarGroupOrders
                    .filter { !ChekinanaLibraryGenerationStore.isMarker($0) }
                    .forEach(modelContext.delete)
                events.forEach(modelContext.delete)
                travelSegments.forEach(modelContext.delete)
                patternStates.forEach(modelContext.delete)
                avatarStates.forEach(modelContext.delete)
                customChekiSizes.forEach(modelContext.delete)
                idols.forEach(modelContext.delete)
                try ChekinanaLibraryGenerationStore.publish(
                    newGeneration,
                    in: modelContext
                )
                try saveContext(modelContext)
            }
        } catch {
            commitError = error
        }

        let persistedGeneration: UUID?
        do {
            persistedGeneration = try ChekinanaLibraryGenerationStore.current(
                in: ModelContext(modelContext.container)
            )
        } catch {
            modelContext.rollback()
            throw ChekinanaLocalDataClearError.commitIndeterminate(
                error.localizedDescription
            )
        }

        guard persistedGeneration == newGeneration else {
            modelContext.rollback()
            if persistedGeneration == oldGeneration {
                try? ChekinanaLocalDataClearJournalStore.discard(
                    in: directory,
                    fileManager: fileManager
                )
                throw ChekinanaLocalDataClearError.database(
                    commitError?.localizedDescription
                        ?? ChekinanaL10n.message("The committed library generation was unchanged.")
                )
            }
            throw ChekinanaLocalDataClearError.commitIndeterminate(
                commitError?.localizedDescription
                    ?? ChekinanaL10n.message("The committed library generation is unknown.")
            )
        }

        let baseResult = ChekinanaLocalDataClearResult(
            chekiCount: chekiCount,
            shameCount: shameCount,
            dougaCount: dougaCount,
            eventCount: events.count,
            idolCount: idols.count,
            removedFileCount: 0,
            deletedEntityCounts: entityCounts
        )

        do {
            try afterDatabaseCommit()
            try Task.checkCancellation()
        } catch {
            throw ChekinanaLocalDataClearError.fileCleanup(
                baseResult,
                pendingActionCount: max(1, journal.files.count),
                details: [
                    ChekinanaL10n.message("The database is clear; managed file cleanup is queued for recovery.")
                ]
            )
        }

        ChekinanaHiddenIdolPersistence.save([], defaults: defaults)
        if defaults === UserDefaults.standard {
            ChekinanaHiddenIdolStore.shared.clear()
        }
        ChekinanaCapturedPhotoStore.cleanupStaleFiles()

        let recovery = recoverUnfinishedClearExclusively(
            modelContext: modelContext,
            directory: directory,
            defaults: defaults,
            fileManager: fileManager,
            removeFile: removeFile,
            beforeCandidateValidation: beforeCandidateValidation
        )
        let result = ChekinanaLocalDataClearResult(
            chekiCount: baseResult.chekiCount,
            shameCount: baseResult.shameCount,
            dougaCount: baseResult.dougaCount,
            eventCount: baseResult.eventCount,
            idolCount: baseResult.idolCount,
            removedFileCount: recovery.removedFileCount,
            deletedEntityCounts: entityCounts
        )
        guard !recovery.needsRetry else {
            throw ChekinanaLocalDataClearError.fileCleanup(
                result,
                pendingActionCount: recovery.deferredActionCount,
                details: cleanupDetails(recovery)
            )
        }
        return result
    }

    private static func recoverUnfinishedClearExclusively(
        modelContext: ModelContext,
        directory: URL,
        defaults: UserDefaults,
        fileManager: FileManager,
        removeFile: @escaping RemoveFile,
        beforeCandidateValidation: () -> Void
    ) -> ChekinanaLocalDataClearRecoveryReport {
        var report = ChekinanaLocalDataClearRecoveryReport()
        let journal: ChekinanaLocalDataClearJournal
        do {
            guard let loaded = try ChekinanaLocalDataClearJournalStore.load(
                in: directory,
                fileManager: fileManager
            ) else { return report }
            journal = loaded
            report.foundIntent = true
        } catch {
            report.foundIntent = true
            report.databaseStateIndeterminate = true
            report.deferredActionCount = 1
            return report
        }

        let currentGeneration: UUID?
        do {
            currentGeneration = try ChekinanaLibraryGenerationStore.current(
                in: ModelContext(modelContext.container)
            )
        } catch {
            report.databaseStateIndeterminate = true
            report.deferredActionCount = 1
            return report
        }
        if currentGeneration == journal.oldGeneration {
            do {
                try ChekinanaLocalDataClearJournalStore.discard(
                    in: directory,
                    fileManager: fileManager
                )
            } catch {
                report.deferredActionCount = 1
            }
            return report
        }
        guard currentGeneration == journal.newGeneration else {
            report.databaseStateIndeterminate = true
            report.deferredActionCount = 1
            return report
        }
        report.databaseCommitted = true

        do {
            guard try ChekinanaImportTransactionHandle.discover(
                in: directory,
                fileManager: fileManager
            ).isEmpty else {
                report.blockedByImportTransaction = true
                return report
            }
        } catch {
            report.blockedByImportTransaction = true
            return report
        }

        var queueReport = ChekinanaLibraryQueueCleanupReport()
        do {
            queueReport = try ChekinanaLibraryQueueReconciler
                .reconcileCommittedImportExclusively(
                    expectedGeneration: journal.newGeneration,
                    in: modelContext,
                    directory: directory,
                    defaults: defaults
                )
        } catch {
            queueReport.deferredActionCount += 1
        }

        var remaining: [ChekinanaLocalDataClearJournal.FileEntry] = []
        var protected = Set(journal.protectedFilenames)
        for candidate in journal.files {
            switch cleanupCandidate(
                candidate,
                expectedGeneration: journal.newGeneration,
                modelContext: modelContext,
                directory: directory,
                fileManager: fileManager,
                removeFile: removeFile,
                beforeCandidateValidation: beforeCandidateValidation
            ) {
            case .completed(let removed):
                if removed { report.removedFileCount += 1 }
            case .deferred:
                remaining.append(candidate)
                report.deferredActionCount += 1
            case .protected:
                protected.insert(candidate.filename)
            }
        }
        report.protectedFileCount = protected.count

        let ordinary = ChekinanaLibraryQueueReconciler
            .cleanupOrdinaryQueuesExclusively(
                in: modelContext,
                directory: directory,
                defaults: defaults,
                additionalProtectedFilenames: protected,
                beforeCandidateValidation: beforeCandidateValidation,
                removeItem: removeFile
            )
        queueReport.deferredActionCount += ordinary.deferredActionCount
        queueReport.blockedByImportTransaction =
            queueReport.blockedByImportTransaction
                || ordinary.blockedByImportTransaction
        report.deferredActionCount += queueReport.deferredActionCount
        report.blockedByImportTransaction =
            report.blockedByImportTransaction
                || queueReport.blockedByImportTransaction

        if report.needsRetry {
            var retryJournal = journal
            retryJournal.files = remaining
            retryJournal.protectedFilenames = protected.sorted()
            do {
                try ChekinanaLocalDataClearJournalStore.persist(
                    retryJournal,
                    in: directory,
                    fileManager: fileManager
                )
            } catch {
                report.deferredActionCount += 1
            }
        } else {
            do {
                try ChekinanaLocalDataClearJournalStore.discard(
                    in: directory,
                    fileManager: fileManager
                )
            } catch {
                report.deferredActionCount += 1
            }
        }
        return report
    }

    private static func cleanupCandidate(
        _ candidate: ChekinanaLocalDataClearJournal.FileEntry,
        expectedGeneration: UUID,
        modelContext: ModelContext,
        directory: URL,
        fileManager: FileManager,
        removeFile: RemoveFile,
        beforeCandidateValidation: () -> Void
    ) -> CandidateResult {
        let url = directory.appendingPathComponent(candidate.filename)
        guard fileManager.fileExists(atPath: url.path) else {
            return .completed(removed: false)
        }
        do {
            return try ChekinanaPersistenceMutationCoordinator.withLock {
                beforeCandidateValidation()
                guard fileManager.fileExists(atPath: url.path) else {
                    return .completed(removed: false)
                }
                let values = try url.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                )
                guard url.standardizedFileURL.deletingLastPathComponent()
                        == directory.standardizedFileURL,
                      values.isRegularFile == true,
                      values.isSymbolicLink != true else {
                    return .protected
                }
                let latest = try ChekinanaLibraryFileReferenceSnapshot.capture(
                    in: ModelContext(modelContext.container),
                    directory: directory
                )
                guard latest.generation == expectedGeneration else {
                    return .deferred
                }
                guard !latest.referencedFilenames.contains(candidate.filename),
                      try ChekinanaImportFileIdentity.inspect(url)
                        == candidate.identity else {
                    return .protected
                }
                try removeFile(url)
                return fileManager.fileExists(atPath: url.path)
                    ? .deferred
                    : .completed(removed: true)
            }
        } catch {
            return .deferred
        }
    }

    private static func prepareFiles(
        in directory: URL,
        referencedFilenames: Set<String>,
        fileManager: FileManager,
        contentsOfDirectory: DirectoryContents
    ) throws -> (
        files: [ChekinanaLocalDataClearJournal.FileEntry],
        protectedFilenames: [String]
    ) {
        let entries = try contentsOfDirectory(
            directory,
            [.isRegularFileKey, .isSymbolicLinkKey, .isDirectoryKey],
            []
        )
        var files: [ChekinanaLocalDataClearJournal.FileEntry] = []
        var protected = Set<String>()
        for entry in entries {
            let candidate = entry.standardizedFileURL
            let filename = candidate.lastPathComponent
            guard candidate.deletingLastPathComponent()
                    == directory.standardizedFileURL,
                  filename == URL(fileURLWithPath: filename).lastPathComponent,
                  filename != ChekinanaLocalDataClearJournalStore.journalFilename else {
                continue
            }
            let values: URLResourceValues
            do {
                values = try candidate.resourceValues(
                    forKeys: [
                        .isRegularFileKey,
                        .isSymbolicLinkKey,
                        .isDirectoryKey,
                    ]
                )
            } catch {
                // An unreadable candidate has not been safely classified.
                // Abort preparation before changing the database or its generation.
                throw error
            }
            guard values.isRegularFile == true,
                  values.isSymbolicLink != true,
                  values.isDirectory != true else {
                protected.insert(filename)
                continue
            }
            let isOrdinaryManagedFile = !filename.hasPrefix(".")
            let isReferenced = referencedFilenames.contains(filename)
            let isRecognizedQuarantine = ChekinanaGalleryMediaStore
                .isRecognizedDeletionQuarantineFilename(filename)
            guard isOrdinaryManagedFile || isReferenced || isRecognizedQuarantine else {
                protected.insert(filename)
                continue
            }
            do {
                files.append(.init(
                    filename: filename,
                    identity: try ChekinanaImportFileIdentity.inspect(candidate)
                ))
            } catch {
                // Byte identity is required before committing the deletion intent.
                throw error
            }
        }
        files.sort { $0.filename < $1.filename }
        return (files, protected.sorted())
    }

    private static func resolvedDirectory(
        _ directory: URL?,
        fileManager: FileManager
    ) throws -> URL {
        let resolved = try directory ?? ChekiImageRefResolver.chekiImagesDirectory()
        let canonical = resolved.standardizedFileURL
        try fileManager.createDirectory(
            at: canonical,
            withIntermediateDirectories: true
        )
        let values = try canonical.resourceValues(
            forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        )
        guard values.isDirectory == true, values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return canonical
    }

    private static func emptyResult(
        removedFileCount: Int
    ) -> ChekinanaLocalDataClearResult {
        ChekinanaLocalDataClearResult(
            chekiCount: 0,
            shameCount: 0,
            dougaCount: 0,
            eventCount: 0,
            idolCount: 0,
            removedFileCount: removedFileCount
        )
    }

    private static func cleanupDetails(
        _ report: ChekinanaLocalDataClearRecoveryReport
    ) -> [String] {
        var values: [String] = []
        if report.blockedByImportTransaction {
            values.append(ChekinanaL10n.message("An unfinished backup import still owns recovery files."))
        }
        if report.databaseStateIndeterminate {
            values.append(ChekinanaL10n.message("The committed library generation could not be verified."))
        }
        if report.deferredActionCount > 0 {
            values.append(
                ChekinanaL10n.message("\(report.deferredActionCount) file cleanup action(s) remain queued.")
            )
        }
        return values.isEmpty
            ? [ChekinanaL10n.message("Managed file cleanup remains queued.")]
            : values
    }
}

private final class ChekinanaDataExportPackage {
    enum Phase { case prepared, presented, ended, finished }
    let id = UUID()
    let url: URL
    private(set) var phase: Phase = .prepared
    private let cleanup: (URL) -> Void

    init(url: URL, cleanup: @escaping (URL) -> Void = {
        ChekinanaExportTemporaryFiles.cleanupArchive(at: $0)
    }) throws {
        guard ChekinanaExportTemporaryFiles.ownedDirectory(for: url) != nil,
              ChekiImageRefResolver.isRegularReadableFile(url) else {
            throw ChekinanaDataExportError.invalidArchive
        }
        self.url = url
        self.cleanup = cleanup
    }

    func markPresented() {
        if phase == .prepared { phase = .presented }
    }

    func pickerDidEnd() {
        if phase == .presented { phase = .ended }
    }

    func finishAfterDismissal() {
        guard phase != .finished else { return }
        phase = .finished
        cleanup(url)
    }

    deinit {
        // A live picker can still be copying. Losing a SwiftUI owner alone is
        // not permission to remove its source; normal cleanup is onDismiss.
        if phase == .prepared || phase == .ended { cleanup(url) }
    }
}

private struct ChekinanaBackupExportPicker: UIViewControllerRepresentable {
    let package: ChekinanaDataExportPackage
    let onEnd: (UUID) -> Void

    func makeCoordinator() -> Coordinator {
        Coordinator(package: package, onEnd: onEnd)
    }

    func makeUIViewController(context: Context) -> UIDocumentPickerViewController {
        package.markPresented()
        let picker = UIDocumentPickerViewController(forExporting: [package.url], asCopy: false)
        picker.delegate = context.coordinator
        return picker
    }

    func updateUIViewController(_ picker: UIDocumentPickerViewController, context: Context) {}

    final class Coordinator: NSObject, UIDocumentPickerDelegate {
        let package: ChekinanaDataExportPackage
        let onEnd: (UUID) -> Void

        init(package: ChekinanaDataExportPackage, onEnd: @escaping (UUID) -> Void) {
            self.package = package
            self.onEnd = onEnd
        }

        func documentPicker(_ controller: UIDocumentPickerViewController, didPickDocumentsAt urls: [URL]) {
            end()
        }

        func documentPickerWasCancelled(_ controller: UIDocumentPickerViewController) {
            end()
        }

        private func end() {
            guard package.phase == .presented else { return }
            package.pickerDidEnd()
            onEnd(package.id)
        }
    }
}

private extension UTType {
    static let chekinanaBackup = UTType(
        exportedAs: "app.chekinana.backup",
        conformingTo: .zip
    )
}

private enum ChekinanaDataExportError: LocalizedError {
    case missingMedia(String)
    case invalidArchive
    case insufficientSpace(required: UInt64?, available: UInt64?)
    case writeRejected(ChekinanaExportWriteFailure)

    var errorDescription: String? {
        switch self {
        case .missingMedia(let reference):
            ChekinanaProductCopy.format(
                "settings.export.error.missing_media",
                "A referenced media file is missing or unreadable: %@",
                reference
            )
        case .invalidArchive:
            ChekinanaProductCopy.text(
                "settings.export.error.archive",
                "The backup archive could not be created."
            )
        case .writeRejected(let failure):
            if let written = failure.writtenBytes, let available = failure.immediatelyAvailableBytes {
                ChekinanaProductCopy.format(
                    "settings.export.error.write_rejected_details",
                    "The system rejected a storage write while creating the backup. %@ had been written; immediately available space at the failure was %@. The backup was not completed.",
                    ChekinanaExportSpacePolicy.displayBytes(written),
                    ChekinanaExportSpacePolicy.displayBytes(available)
                )
            } else {
                ChekinanaProductCopy.text(
                    "settings.export.error.write_rejected",
                    "The system rejected a storage write while creating the backup. The backup was not completed."
                )
            }
        case .insufficientSpace(let required, let available):
            if let required, let available {
                ChekinanaProductCopy.format(
                    "settings.export.error.space_details",
                    "Not enough storage for this backup. About %@ is needed, including working space; %@ is available. Free up space and try again.",
                    ChekinanaExportSpacePolicy.displayBytes(required),
                    ChekinanaExportSpacePolicy.displayBytes(available)
                )
            } else {
                ChekinanaProductCopy.text(
                    "settings.export.error.space",
                    "Not enough storage to finish this backup. Free up space and try again."
                )
            }
        }
    }
}

/// A bounded, in-memory snapshot taken before closing/removing a failed archive.
/// The underlying error remains available to the debugger; no paths or payloads
/// are copied into the diagnostic fields or written to logs/files.
struct ChekinanaExportWriteFailure: Error {
    enum Stage: String, Sendable {
        case preparingArchive, openingFile, localHeader, entryContents
        case localHeaderChecksum, centralDirectory, archiveEnd, synchronizing, closing
    }
    struct ErrorCode: Sendable { let domain: String; let code: Int }
    let underlyingError: NSError
    let errorCodes: [ErrorCode]
    let stage: Stage
    let fileOffset: UInt64?
    let writtenBytes: UInt64?
    let immediatelyAvailableBytes: UInt64?
    let importantAvailableBytes: UInt64?

    static func capture(
        _ error: Error,
        stage: Stage,
        descriptor: Int32?,
        directory: URL
    ) -> Self {
        let original = error as NSError
        var pending = [original]
        var visited = Set<ObjectIdentifier>()
        var codes: [ErrorCode] = []
        let knownDomains = [NSPOSIXErrorDomain, NSCocoaErrorDomain, NSURLErrorDomain, NSOSStatusErrorDomain]
        while !pending.isEmpty, codes.count < 8 {
            let current = pending.removeFirst()
            guard visited.insert(ObjectIdentifier(current)).inserted else { continue }
            codes.append(.init(domain: knownDomains.contains(current.domain) ? current.domain : "other", code: current.code))
            if let nested = current.userInfo[NSUnderlyingErrorKey] as? NSError { pending.append(nested) }
            if let multiple = current.userInfo["NSMultipleUnderlyingErrors"] as? [NSError] {
                pending.append(contentsOf: multiple.prefix(8))
            }
        }
        var writtenBytes: UInt64?
        var fileOffset: UInt64?
        if let descriptor {
            var metadata = stat()
            if Darwin.fstat(descriptor, &metadata) == 0, metadata.st_size >= 0 {
                writtenBytes = UInt64(metadata.st_size)
            }
            let position = Darwin.lseek(descriptor, 0, SEEK_CUR)
            if position >= 0 { fileOffset = UInt64(position) }
        }
        let capacity = ChekinanaExportSpacePolicy.capacitySnapshot(at: directory)
        return Self(underlyingError: original, errorCodes: codes, stage: stage,
            fileOffset: fileOffset, writtenBytes: writtenBytes,
            immediatelyAvailableBytes: capacity.immediate,
            importantAvailableBytes: capacity.important)
    }
}

enum ChekinanaExportSpacePolicy {
    struct EntrySize { let name: String; let size: UInt64 }

    /// The ZIP writer stores bytes without compression; account for every local
    /// header, central entry and ZIP64 record without reading media contents.
    static func archiveBytes(_ entries: [EntrySize]) throws -> UInt64 {
        var offset: UInt64 = 0
        var central: UInt64 = 0
        var containsLarge = false
        for entry in entries {
            guard ChekinanaStreamingZIP.safe(entry.name) else { throw ChekinanaDataExportError.invalidArchive }
            let name = UInt64(entry.name.utf8.count)
            let largeSize = entry.size >= UInt64(UInt32.max)
            let largeEntry = largeSize || offset >= UInt64(UInt32.max)
            containsLarge = containsLarge || largeEntry
            central = try add(central, add(46 + (largeEntry ? 28 : 0), name))
            offset = try add(offset, add(entry.size, add(30 + (largeSize ? 20 : 0), name)))
        }
        let zip64 = ChekinanaStreamingZIP.requiresZip64(
            entryCount: entries.count, centralOffset: offset,
            centralSize: central, containsLargeEntry: containsLarge
        )
        return try add(add(offset, central), zip64 ? 98 : 22)
    }

    /// Keep max(64 MiB, rounded-up 5%) available for filesystem working space.
    /// This is a proportional reservation, never a maximum backup size.
    static func requiredBytes(archiveBytes: UInt64) throws -> UInt64 {
        let fivePercent = archiveBytes / 20 + (archiveBytes % 20 == 0 ? 0 : 1)
        return try add(archiveBytes, max(64 * 1_048_576, fivePercent))
    }

    static func requireCapacity(required: UInt64, available: UInt64?) throws {
        guard let available, available < required else { return }
        throw ChekinanaDataExportError.insufficientSpace(required: required, available: available)
    }

    static func availableCapacity(at directory: URL) -> UInt64? {
        var refreshedURL = directory
        refreshedURL.removeCachedResourceValue(forKey: .volumeAvailableCapacityForImportantUsageKey)
        guard let values = try? refreshedURL.resourceValues(forKeys: [.volumeAvailableCapacityForImportantUsageKey]),
              let bytes = values.volumeAvailableCapacityForImportantUsage,
              bytes >= 0 else { return nil }
        return UInt64(bytes)
    }

    static func capacitySnapshot(at directory: URL) -> (immediate: UInt64?, important: UInt64?) {
        var refreshedURL = directory
        let keys: Set<URLResourceKey> = [.volumeAvailableCapacityKey, .volumeAvailableCapacityForImportantUsageKey]
        for key in keys { refreshedURL.removeCachedResourceValue(forKey: key) }
        guard let values = try? refreshedURL.resourceValues(forKeys: keys) else { return (nil, nil) }
        let immediate = values.volumeAvailableCapacity.flatMap { $0 >= 0 ? UInt64($0) : nil }
        let important = values.volumeAvailableCapacityForImportantUsage.flatMap { $0 >= 0 ? UInt64($0) : nil }
        return (immediate, important)
    }

    static func isOutOfSpace(_ error: Error) -> Bool {
        var pending = [error as NSError]
        var visited = Set<ObjectIdentifier>()
        while let current = pending.popLast() {
            guard visited.insert(ObjectIdentifier(current)).inserted else { continue }
            if (current.domain == NSPOSIXErrorDomain && current.code == Int(ENOSPC))
                || (current.domain == NSCocoaErrorDomain && current.code == CocoaError.fileWriteOutOfSpace.rawValue) {
                return true
            }
            if let underlying = current.userInfo[NSUnderlyingErrorKey] as? NSError { pending.append(underlying) }
            if let multiple = current.userInfo["NSMultipleUnderlyingErrors"] as? [NSError] { pending.append(contentsOf: multiple) }
        }
        return false
    }

    static func displayBytes(_ bytes: UInt64) -> String {
        ByteCountFormatter.string(fromByteCount: Int64(clamping: bytes), countStyle: .file)
    }

    private static func add(_ left: UInt64, _ right: UInt64) throws -> UInt64 {
        let result = left.addingReportingOverflow(right)
        guard !result.overflow else { throw ChekinanaDataExportError.invalidArchive }
        return result.partialValue
    }
}

struct ChekinanaDataExportSnapshot: @unchecked Sendable {
    struct Media: Sendable {
        let ownerType: String
        let ownerID: String
        let reference: String
        let url: URL
    }

    let data: [String: Any]
    let entityCounts: [String: Int]
    let media: [Media]
    let settings: [String: Any]

    @MainActor
    static func capture(
        in context: ModelContext,
        fetchAvatarStates: (ModelContext) throws -> [IdolAvatarState] = {
            try $0.fetch(FetchDescriptor<IdolAvatarState>())
        }
    ) throws -> Self {
        let idols = try context.fetch(FetchDescriptor<Idol>())
        let patternStates = try context.fetch(FetchDescriptor<IdolPatternState>())
        let avatarStates = try fetchAvatarStates(context)
        let avatarStatesByIdolID = Dictionary(
            avatarStates.map { ($0.idolID, $0.snapshot) },
            uniquingKeysWith: { first, _ in first }
        )
        let events = try context.fetch(FetchDescriptor<Event>())
        let customChekiSizes = try context.fetch(FetchDescriptor<CustomChekiSize>())
        let schedules = try context.fetch(FetchDescriptor<EventSchedule>())
        let eventImages = try context.fetch(FetchDescriptor<EventImage>())
        let groupOrders = try context.fetch(FetchDescriptor<CalendarGroupOrder>())
            .filter { !ChekinanaLibraryGenerationStore.isMarker($0) }
        let travels = try context.fetch(FetchDescriptor<TravelSegment>())
        let mediaItems = try context.fetch(FetchDescriptor<MediaItem>())
        let records = try context.fetch(FetchDescriptor<ChekiRecord>())
        let memories = try context.fetch(FetchDescriptor<Memory>())
        let memoryAttachments = try context.fetch(FetchDescriptor<MemoryAttachment>())
        let iso = ISO8601DateFormatter()
        func date(_ value: Date?) -> Any { value.map(iso.string(from:)) ?? NSNull() }
        func text(_ value: String?) -> Any { value ?? NSNull() }
        func uuid(_ value: UUID?) -> Any { value?.uuidString.lowercased() ?? NSNull() }

        let entities: [String: [[String: Any]]] = [
            "Idol": idols.map { value in
                let avatarState = avatarStatesByIdolID[value.id]
                    ?? .compatibilityDefault
                return [
                    "id": value.id.uuidString.lowercased(), "sourceId": text(value.sourceId),
                    "name": value.name, "group": text(value.group), "color": text(value.color),
                    "birthday": text(value.birthday), "avatarImageRef": text(value.avatarImageRef),
                    "avatarSource": avatarState.source.rawValue,
                    "avatarIntent": avatarState.intent.rawValue,
                    "isFavorite": value.isFavorite, "sortOrder": value.sortOrder ?? NSNull(),
                    "note": value.note, "createdAt": date(value.createdAt), "updatedAt": date(value.updatedAt),
                    "verification": text(value.verification), "bio": text(value.bio),
                    "pattern": value.pattern ?? NSNull(), "patterns": value.patterns,
                ]
            },
            "IdolPatternState": patternStates.map { value in [
                "idolID": value.idolID.uuidString.lowercased(), "encoderVersion": value.encoderVersion,
                "cataloguePatternIDs": value.cataloguePatternIDs,
                "cataloguePatternCount": value.cataloguePatternCount,
            ] },
            "Event": events.map { value in [
                "id": value.id.uuidString.lowercased(), "name": value.name, "date": date(value.date),
                "city": text(value.city), "livehouse": text(value.livehouse),
                "legacyVenue": text(value.legacyVenue), "avatarImageRef": text(value.avatarImageRef),
                "price": text(value.price), "weiboURL": value.weiboURL?.absoluteString ?? NSNull(),
                "source": text(value.source?.rawValue),
                "ticketURL": value.ticketURL?.absoluteString ?? NSNull(), "note": value.note,
                "createdAt": date(value.createdAt), "updatedAt": date(value.updatedAt),
            ] },
            "EventSchedule": schedules.map { [
                "eventID": $0.eventID.uuidString.lowercased(),
                "openTime": text($0.openTime), "startTime": text($0.startTime),
            ] },
            "EventImage": eventImages.map { [
                "id": $0.id.uuidString.lowercased(), "eventID": $0.eventID.uuidString.lowercased(),
                "imageRef": $0.imageRef, "sortOrder": $0.sortOrder,
            ] },
            "CalendarGroupOrder": groupOrders.map { [
                "id": $0.id, "dateKey": $0.dateKey, "groupKey": $0.groupKey, "sortOrder": $0.sortOrder,
            ] },
            "TravelSegment": travels.map { value in [
                "id": value.id.uuidString.lowercased(), "mode": value.modeRawValue,
                "operatorName": value.operatorName, "operatorIconRef": text(value.operatorIconRef),
                "serviceNumber": value.serviceNumber, "departureCity": value.departureCity,
                "departureLocation": value.departureLocation, "arrivalCity": value.arrivalCity,
                "arrivalLocation": value.arrivalLocation, "departureTime": date(value.departureTime),
                "arrivalTime": date(value.arrivalTime), "seatNumber": value.seatNumber,
                "carriageNumber": text(value.carriageNumber), "note": value.note,
                "createdAt": date(value.createdAt), "updatedAt": date(value.updatedAt),
            ] },
            "MediaItem": mediaItems.map { value in [
                "id": value.id.uuidString.lowercased(), "mediaOwnerID": value.mediaOwnerID.uuidString.lowercased(),
                "kind": value.kind.rawValue, "idolIDs": value.idolIDs.map { $0.uuidString.lowercased() },
                "eventID": uuid(value.eventID), "date": date(value.date), "userAppears": value.userAppears,
                "isFavorite": value.isFavorite, "hasPostedToSNS": value.hasPostedToSNS,
                "note": value.note, "mediaRef": value.imageRef ?? value.videoRef ?? "",
                "size": text(value.sizeRawValue), "idx": value.idx ?? NSNull(),
                "createdAt": date(value.createdAt), "updatedAt": date(value.updatedAt),
            ] },
            "ChekiRecord": records.map { value in [
                "id": value.id.uuidString.lowercased(),
                "idolIDs": value.idolIDs.map { $0.uuidString.lowercased() },
                "eventID": uuid(value.eventID), "date": date(value.date),
                "size": text(value.sizeRawValue), "note": value.note, "count": value.count,
            ] },
            "Memory": memories.map { value in [
                "id": value.id.uuidString.lowercased(),
                "title": text(value.title), "bodyText": text(value.bodyText),
                "date": date(value.date), "eventID": uuid(value.eventID),
                "idolIDs": value.idolIDs.map { $0.uuidString.lowercased() },
                "createdAt": date(value.createdAt), "updatedAt": date(value.updatedAt),
            ] },
            "MemoryAttachment": memoryAttachments.map { value in [
                "id": value.id.uuidString.lowercased(),
                "memoryID": value.memoryID.uuidString.lowercased(),
                "kind": value.kind.rawValue, "managedRef": value.managedRef,
                "sortOrder": value.sortOrder,
                "createdAt": date(value.createdAt), "updatedAt": date(value.updatedAt),
            ] },
            "CustomChekiSize": customChekiSizes.map { value in [
                "id": value.id.uuidString.lowercased(), "name": value.name,
                "widthRatio": value.widthRatio, "heightRatio": value.heightRatio,
                "pixelWidth": value.pixelWidth, "pixelHeight": value.pixelHeight,
                "createdAt": date(value.createdAt),
            ] },
        ]

        var sources: [Media] = []
        func add(_ ref: String?, ownerType: String, ownerID: UUID, url: URL?) throws {
            guard let ref = ref?.trimmingCharacters(in: .whitespacesAndNewlines), !ref.isEmpty else { return }
            guard let url, ChekiImageRefResolver.isRegularReadableFile(url) else {
                throw ChekinanaDataExportError.missingMedia(ref)
            }
            sources.append(Media(ownerType: ownerType, ownerID: ownerID.uuidString.lowercased(), reference: ref, url: url))
        }
        for idol in idols {
            try add(idol.avatarImageRef, ownerType: "Idol", ownerID: idol.id,
                    url: try ChekinanaIdolReferenceStore.managedAvatarURL(for: idol.avatarImageRef, idolID: idol.id))
        }
        for event in events {
            let url = event.avatarImageRef.flatMap(ChekiImageRefResolver.managedLocalFileURL(for:))
            try add(event.avatarImageRef, ownerType: "Event", ownerID: event.id, url: url)
        }
        for image in eventImages {
            try add(image.imageRef, ownerType: "EventImage", ownerID: image.id,
                    url: ChekiImageRefResolver.managedLocalFileURL(for: image.imageRef))
        }
        for travel in travels where ChekinanaTravelOperatorIcon.assetName(from: travel.operatorIconRef) == nil {
            let url = travel.operatorIconRef.flatMap(ChekiImageRefResolver.managedLocalFileURL(for:))
            try add(travel.operatorIconRef, ownerType: "TravelSegment", ownerID: travel.id, url: url)
        }
        for item in mediaItems {
            let ref = item.imageRef ?? item.videoRef
            let url: URL?
            switch item.kind {
            case .cheki:
                url = ref.flatMap(ChekiImageRefResolver.localFileURL(for:))
            case .shame:
                url = ChekinanaGalleryMediaStore.managedURL(
                    for: ref, id: item.mediaOwnerID, kind: .shame
                )
            case .douga:
                url = ChekinanaGalleryMediaStore.managedURL(
                    for: ref, id: item.mediaOwnerID, kind: .douga
                )
            }
            try add(ref, ownerType: "MediaItem", ownerID: item.id,
                    url: url)
        }
        for attachment in memoryAttachments {
            let galleryKind: ChekinanaGalleryMediaKind = attachment.kind == .image
                ? .shame : .douga
            try add(
                attachment.managedRef,
                ownerType: "MemoryAttachment",
                ownerID: attachment.id,
                url: ChekinanaGalleryMediaStore.managedURL(
                    for: attachment.managedRef,
                    id: attachment.id,
                    kind: galleryKind
                )
            )
        }

        let counts = entities.mapValues(\.count)
        let defaults = UserDefaults.standard
        let settings: [String: Any] = [
            ChekinanaLanguagePreference.defaultsKey: defaults.string(forKey: ChekinanaLanguagePreference.defaultsKey) ?? ChekinanaAppLanguage.system.rawValue,
            ChekinanaThemePreference.defaultsKey: defaults.string(forKey: ChekinanaThemePreference.defaultsKey) ?? ChekinanaThemeOption.purple.rawValue,
            ChekinanaHiddenIdolPersistence.defaultsKey: defaults.array(forKey: ChekinanaHiddenIdolPersistence.defaultsKey) as? [String] ?? [],
        ]
        return Self(data: ["schemaVersion": "17.0.0", "entities": entities], entityCounts: counts, media: sources, settings: settings)
    }
}

private struct ChekinanaExportCleanupFailure: LocalizedError {
    let archiveURL: URL
    var errorDescription: String? {
        ChekinanaProductCopy.text(
            "settings.export.cleanup_failed",
            "Temporary backup files could not be removed. Retry cleanup before exporting again."
        )
    }
}

enum ChekinanaDataExporter {
    static func archiveURL(
        for snapshot: ChekinanaDataExportSnapshot,
        filename: String = "backup.chekinana",
        progress: @escaping @Sendable (Int, Int) -> Void = { _, _ in }
    ) async throws -> URL {
        let worker = Task.detached(priority: .userInitiated) {
            guard !filename.isEmpty, filename != ".", filename != "..",
                  !filename.contains("/"), !filename.contains("\\"), !filename.contains("\0"),
                  URL(fileURLWithPath: filename).lastPathComponent == filename else {
                throw ChekinanaDataExportError.invalidArchive
            }
            guard JSONSerialization.isValidJSONObject(snapshot.data),
                  let dataJSON = try? JSONSerialization.data(withJSONObject: snapshot.data, options: [.prettyPrinted, .sortedKeys]) else {
                throw ChekinanaDataExportError.invalidArchive
            }
            guard JSONSerialization.isValidJSONObject(snapshot.settings) else {
                throw ChekinanaDataExportError.invalidArchive
            }
            let settingsJSON = try JSONSerialization.data(
                withJSONObject: snapshot.settings,
                options: [.prettyPrinted, .sortedKeys]
            )
            let temporaryRoot = FileManager.default.temporaryDirectory
            let exportedAt = ISO8601DateFormatter().string(from: Date())
            let appVersion = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "unknown"
            func manifestJSON(_ media: [[String: Any]]) throws -> Data {
                try JSONSerialization.data(withJSONObject: [
                    "format": "chekinana-backup", "exportVersion": 1, "schemaVersion": "17.0.0",
                    "appVersion": appVersion, "exportedAt": exportedAt,
                    "entityCounts": snapshot.entityCounts, "media": media,
                ], options: [.prettyPrinted, .sortedKeys])
            }
            var plannedSizes: [ChekinanaExportSpacePolicy.EntrySize] = []
            var mediaEntries: [ChekinanaStreamingZIP.Entry] = []
            var estimatedMediaIndex: [[String: Any]] = []
            for (index, source) in snapshot.media.enumerated() {
                try Task.checkCancellation()
                let identity = try ChekinanaStreamingZIP.fileIdentity(at: source.url)
                let bytes = identity.size
                guard bytes > 0 else { throw ChekinanaDataExportError.missingMedia(source.reference) }
                let ext = ChekinanaGalleryMediaStore.safeMediaExtension(source.url.pathExtension, fallback: "bin")
                let path = String(format: "media/%06d.%@", index + 1, ext)
                plannedSizes.append(.init(name: path, size: bytes))
                mediaEntries.append(.streamingFile(path, source.url, identity))
                estimatedMediaIndex.append([
                    "archivePath": path, "ownerType": source.ownerType, "ownerID": source.ownerID,
                    "originalReference": source.reference, "byteCount": UInt64(bytes),
                    "sha256": String(repeating: "f", count: 64), "crc32": Int64(UInt32.max),
                ])
            }
            let jsonSizes: [ChekinanaExportSpacePolicy.EntrySize] = [
                .init(name: "data.json", size: UInt64(dataJSON.count)),
                .init(name: "settings.json", size: UInt64(settingsJSON.count)),
            ]
            let requiredBytes = try ChekinanaExportSpacePolicy.requiredBytes(archiveBytes:
                ChekinanaExportSpacePolicy.archiveBytes(jsonSizes + plannedSizes + [
                    .init(name: "manifest.json", size: UInt64(try manifestJSON(estimatedMediaIndex).count)),
                ])
            )
            try ChekinanaExportSpacePolicy.requireCapacity(
                required: requiredBytes,
                available: ChekinanaExportSpacePolicy.availableCapacity(at: temporaryRoot)
            )
            let directory = temporaryRoot.appendingPathComponent(
                "chekinana-export-\(UUID().uuidString.lowercased())",
                isDirectory: true
            )
            let destination = directory.appendingPathComponent(filename)
            do {
                try FileManager.default.createDirectory(
                    at: directory,
                    withIntermediateDirectories: true
                )
                let entries: [ChekinanaStreamingZIP.Entry] = [
                    .data("data.json", dataJSON),
                    .data("settings.json", settingsJSON),
                ] + mediaEntries
                let totalFiles = entries.count + 1 // final manifest.json
                progress(0, totalFiles)
                try ChekinanaStreamingZIP.write(entries, to: destination, didCompleteEntry: { completed in
                    // The final count is withheld until ZIP sync/close succeeds.
                    if completed < totalFiles { progress(completed, totalFiles) }
                }) { inspections in
                    let mediaIndex: [[String: Any]] = zip(
                        snapshot.media.indices,
                        inspections.dropFirst(2)
                    ).map { index, inspection in
                        let source = snapshot.media[index]
                        return [
                            "archivePath": plannedSizes[index].name,
                            "ownerType": source.ownerType, "ownerID": source.ownerID,
                            "originalReference": source.reference, "byteCount": inspection.size,
                            "sha256": inspection.sha256, "crc32": Int64(inspection.crc32),
                        ]
                    }
                    return [.data("manifest.json", try manifestJSON(mediaIndex))]
                }
                try Task.checkCancellation()
                progress(totalFiles, totalFiles)
                return destination
            } catch {
                let failure: ChekinanaExportWriteFailure?
                if let captured = error as? ChekinanaExportWriteFailure {
                    failure = captured
                } else if ChekinanaExportSpacePolicy.isOutOfSpace(error) {
                    failure = ChekinanaExportWriteFailure.capture(
                        error, stage: .preparingArchive, descriptor: nil, directory: temporaryRoot
                    )
                } else {
                    failure = nil
                }
                if FileManager.default.fileExists(atPath: directory.path) {
                    do { try FileManager.default.removeItem(at: directory) }
                    catch { throw ChekinanaExportCleanupFailure(archiveURL: destination) }
                }
                if let failure { throw ChekinanaDataExportError.writeRejected(failure) }
                throw error
            }
        }
        return try await withTaskCancellationHandler {
            try await worker.value
        } onCancel: {
            worker.cancel()
        }
    }
}

enum ChekinanaDataImportError: LocalizedError, Equatable {
    case invalidArchive
    case unsupportedVersion
    case invalidRelationships
    case mediaIntegrity
    case replacementFailed
    case recoveryIncomplete
    case recoveryIndeterminate

    var errorDescription: String? {
        switch self {
        case .invalidArchive:
            ChekinanaProductCopy.text(
                "settings.import.error.archive",
                "The selected file is not a valid Chekinana backup."
            )
        case .unsupportedVersion:
            ChekinanaProductCopy.text(
                "settings.import.error.version",
                "This backup version is not supported."
            )
        case .invalidRelationships:
            ChekinanaProductCopy.text(
                "settings.import.error.relationships",
                "The backup contains incomplete or inconsistent data."
            )
        case .mediaIntegrity:
            ChekinanaProductCopy.text(
                "settings.import.error.media",
                "A media file in the backup is missing or damaged."
            )
        case .replacementFailed:
            ChekinanaProductCopy.text(
                "settings.import.error.replace",
                "The backup could not replace the local library. Existing data was kept."
            )
        case .recoveryIncomplete:
            ChekinanaProductCopy.text(
                "settings.import.error.recovery_incomplete",
                "The library generation is known, but its media recovery could not finish. Retry before making other library changes."
            )
        case .recoveryIndeterminate:
            ChekinanaProductCopy.text(
                "settings.import.error.recovery_indeterminate",
                "The app cannot safely determine which media copy belongs to the active library. Both copies were kept; retry after resolving the file conflict."
            )
        }
    }
}

struct ChekinanaDataImportPayload: Decodable, Sendable {
    struct IdolValue: Decodable, Sendable {
        let id: String
        let sourceId: String?
        let name: String
        let group: String?
        let color: String?
        let birthday: String?
        let avatarImageRef: String?
        let avatarSource: String?
        let avatarIntent: String?
        let isFavorite: Bool
        let sortOrder: Double?
        let note: String
        let createdAt: String
        let updatedAt: String
        let verification: String?
        let bio: String?
        let pattern: [Float]?
        let patterns: [[Float]]

        func resolvedAvatarState(
            allowingMissingFields: Bool
        ) throws -> ChekinanaIdolAvatarStateSnapshot {
            if avatarSource == nil, avatarIntent == nil {
                guard allowingMissingFields else {
                    throw ChekinanaDataImportError.invalidArchive
                }
                return .compatibilityDefault
            }
            guard let avatarSource,
                  let source = ChekinanaIdolAvatarSource(rawValue: avatarSource),
                  let avatarIntent,
                  let intent = ChekinanaIdolAvatarIntent(rawValue: avatarIntent) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let result = ChekinanaIdolAvatarStateSnapshot(
                source: source,
                intent: intent,
                revision: nil
            )
            guard result.isValid(avatarImageRef: avatarImageRef) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            return result
        }
    }

    struct IdolPatternStateValue: Decodable, Sendable {
        let idolID: String
        let encoderVersion: String
        let cataloguePatternIDs: [String]
        let cataloguePatternCount: Int
    }

    struct EventValue: Decodable, Sendable {
        let id: String
        let name: String
        let date: String?
        let city: String?
        let livehouse: String?
        let legacyVenue: String?
        let avatarImageRef: String?
        let price: String?
        let weiboURL: String?
        let source: String?
        let ticketURL: String?
        let note: String
        let createdAt: String
        let updatedAt: String
    }

    struct EventScheduleValue: Decodable, Sendable {
        let eventID: String
        let openTime: String?
        let startTime: String?
    }

    struct EventImageValue: Decodable, Sendable {
        let id: String
        let eventID: String
        let imageRef: String
        let sortOrder: Int
    }

    struct CalendarGroupOrderValue: Decodable, Sendable {
        let id: String
        let dateKey: String
        let groupKey: String
        let sortOrder: Int
    }

    struct TravelSegmentValue: Decodable, Sendable {
        let id: String
        let mode: String
        let operatorName: String
        let operatorIconRef: String?
        let serviceNumber: String
        let departureCity: String
        let departureLocation: String
        let arrivalCity: String
        let arrivalLocation: String
        let departureTime: String
        let arrivalTime: String
        let seatNumber: String
        let carriageNumber: String?
        let note: String
        let createdAt: String
        let updatedAt: String
    }

    struct MediaItemValue: Decodable, Sendable {
        let id: String
        let mediaOwnerID: String
        let kind: String
        let idolIDs: [String]
        let eventID: String?
        let date: String?
        let userAppears: Bool
        let isFavorite: Bool
        let hasPostedToSNS: Bool
        let note: String
        let mediaRef: String
        let size: String?
        let idx: Int?
        let createdAt: String
        let updatedAt: String
    }

    struct ChekiRecordValue: Decodable, Sendable {
        let id: String
        let idolIDs: [String]
        let eventID: String?
        let date: String?
        let size: String?
        let note: String
        let count: Int
    }

    struct MemoryValue: Decodable, Sendable {
        let id: String
        let title: String?
        let bodyText: String?
        let date: String?
        let eventID: String?
        let idolIDs: [String]
        let createdAt: String
        let updatedAt: String
    }

    struct MemoryAttachmentValue: Decodable, Sendable {
        let id: String
        let memoryID: String
        let kind: String
        let managedRef: String
        let sortOrder: Int
        let createdAt: String
        let updatedAt: String
    }

    struct CustomChekiSizeValue: Decodable, Sendable {
        let id: String
        let name: String
        let widthRatio: Double
        let heightRatio: Double
        let pixelWidth: Int
        let pixelHeight: Int
        let createdAt: String
    }

    struct Entities: Decodable, Sendable {
        let idols: [IdolValue]
        let idolPatternStates: [IdolPatternStateValue]
        let events: [EventValue]
        let eventSchedules: [EventScheduleValue]
        let eventImages: [EventImageValue]
        let calendarGroupOrders: [CalendarGroupOrderValue]
        let travelSegments: [TravelSegmentValue]
        let mediaItems: [MediaItemValue]
        let chekiRecords: [ChekiRecordValue]
        let memories: [MemoryValue]
        let memoryAttachments: [MemoryAttachmentValue]
        let customChekiSizes: [CustomChekiSizeValue]

        enum CodingKeys: String, CodingKey {
            case idols = "Idol"
            case idolPatternStates = "IdolPatternState"
            case events = "Event"
            case eventSchedules = "EventSchedule"
            case eventImages = "EventImage"
            case calendarGroupOrders = "CalendarGroupOrder"
            case travelSegments = "TravelSegment"
            case mediaItems = "MediaItem"
            case chekiRecords = "ChekiRecord"
            case memories = "Memory"
            case memoryAttachments = "MemoryAttachment"
            case customChekiSizes = "CustomChekiSize"
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            idols = try container.decode([IdolValue].self, forKey: .idols)
            idolPatternStates = try container.decode([IdolPatternStateValue].self, forKey: .idolPatternStates)
            events = try container.decode([EventValue].self, forKey: .events)
            eventSchedules = try container.decode([EventScheduleValue].self, forKey: .eventSchedules)
            eventImages = try container.decode([EventImageValue].self, forKey: .eventImages)
            calendarGroupOrders = try container.decode([CalendarGroupOrderValue].self, forKey: .calendarGroupOrders)
            travelSegments = try container.decode([TravelSegmentValue].self, forKey: .travelSegments)
            mediaItems = try container.decode([MediaItemValue].self, forKey: .mediaItems)
            chekiRecords = try container.decode([ChekiRecordValue].self, forKey: .chekiRecords)
            memories = try container.decode([MemoryValue].self, forKey: .memories)
            memoryAttachments = try container.decode([MemoryAttachmentValue].self, forKey: .memoryAttachments)
            customChekiSizes = try container.decodeIfPresent(
                [CustomChekiSizeValue].self,
                forKey: .customChekiSizes
            ) ?? []
        }

        var counts: [String: Int] {
            [
                "Idol": idols.count,
                "IdolPatternState": idolPatternStates.count,
                "Event": events.count,
                "EventSchedule": eventSchedules.count,
                "EventImage": eventImages.count,
                "CalendarGroupOrder": calendarGroupOrders.count,
                "TravelSegment": travelSegments.count,
                "MediaItem": mediaItems.count,
                "ChekiRecord": chekiRecords.count,
                "Memory": memories.count,
                "MemoryAttachment": memoryAttachments.count,
                "CustomChekiSize": customChekiSizes.count,
            ]
        }
    }

    let schemaVersion: String
    let entities: Entities
}

struct ChekinanaDataImportManifest: Decodable, Sendable {
    struct MediaValue: Decodable, Sendable {
        let archivePath: String
        let ownerType: String
        let ownerID: String
        let originalReference: String
        let byteCount: UInt64
        let sha256: String
        let crc32: UInt32
    }

    let format: String
    let exportVersion: Int
    let schemaVersion: String
    let entityCounts: [String: Int]
    let media: [MediaValue]
}

struct ChekinanaPreparedDataImport: @unchecked Sendable {
    struct MediaFile: Sendable {
        let url: URL
        let byteCount: UInt64
        let sha256: String
        let crc32: UInt32
    }

    struct OwnerKey: Hashable, Sendable {
        let type: String
        let id: UUID
    }

    let temporaryDirectory: URL
    let payload: ChekinanaDataImportPayload
    let language: ChekinanaAppLanguage
    let theme: ChekinanaThemeOption
    let hiddenIdolIDs: Set<UUID>
    let mediaByOwner: [OwnerKey: MediaFile]
    var identityCache: ChekinanaImportIdentityCache? = nil
}

enum ChekinanaDataImportTemporaryFiles {
    static func cleanup(_ prepared: ChekinanaPreparedDataImport?) {
        guard let prepared else { return }
        try? FileManager.default.removeItem(at: prepared.temporaryDirectory)
    }
}

enum ChekinanaStoredBackupReader {
    private static let maximumEntryCount = 200_000
    private static let maximumJSONBytes: UInt64 = 64 * 1_024 * 1_024
    private static let chunkSize = 1_048_576

    private struct EndRecord {
        let centralOffset: UInt64
        let centralSize: UInt64
        let entryCount: UInt64
        let endOffset: UInt64
    }

    private struct CentralEntry {
        let name: String
        let flags: UInt16
        let method: UInt16
        let crc32: UInt32
        let compressedSize: UInt64
        let uncompressedSize: UInt64
        let localOffset: UInt64
    }

    static func extract(
        _ sourceURL: URL,
        reusing managedDirectory: URL? = nil,
        identityCache: ChekinanaImportIdentityCache? = nil
    ) throws -> [String: ChekinanaPreparedDataImport.MediaFile] {
        let values = try sourceURL.resourceValues(forKeys: [.fileSizeKey, .isRegularFileKey])
        let archiveSize = UInt64(max(0, values.fileSize ?? 0))
        guard values.isRegularFile == true,
              archiveSize >= 22 else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let expectedEntries = try validateArchiveStructure(
            sourceURL,
            archiveSize: archiveSize
        )
        let root = FileManager.default.temporaryDirectory.appendingPathComponent(
            "ChekinanaBackupImport-\(UUID().uuidString.lowercased())",
            isDirectory: true
        )
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: false)
        var transferred = false
        defer { if !transferred { try? FileManager.default.removeItem(at: root) } }
        let input = try FileHandle(forReadingFrom: sourceURL)
        defer { try? input.close() }
        var result: [String: ChekinanaPreparedDataImport.MediaFile] = [:]
        var mediaOffsets: [String: UInt64] = [:]
        var entryCount = 0
        while true {
            try Task.checkCancellation()
            let signatureData = try readExactly(input, count: 4)
            let signature = signatureData.u32(at: 0)
            if signature == 0x02014b50 || signature == 0x06054b50 || signature == 0x06064b50 {
                break
            }
            guard signature == 0x04034b50 else {
                throw ChekinanaDataImportError.invalidArchive
            }
            entryCount += 1
            guard entryCount <= maximumEntryCount else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let header = try readExactly(input, count: 26)
            let flags = header.u16(at: 2)
            let method = header.u16(at: 4)
            let expectedCRC = header.u32(at: 10)
            let legacyCompressedSize = header.u32(at: 14)
            let legacyUncompressedSize = header.u32(at: 18)
            let nameLength = Int(header.u16(at: 22))
            let extraLength = Int(header.u16(at: 24))
            guard flags & 0x0009 == 0,
                  method == 0,
                  nameLength > 0,
                  nameLength <= 1_024 else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let nameData = try readExactly(input, count: nameLength)
            let extra = try readExactly(input, count: extraLength)
            let sizes = try storedSizes(
                legacyCompressed: legacyCompressedSize,
                legacyUncompressed: legacyUncompressedSize,
                extra: extra
            )
            let compressedSize = sizes.compressed
            let uncompressedSize = sizes.uncompressed
            guard compressedSize == uncompressedSize else {
                throw ChekinanaDataImportError.invalidArchive
            }
            guard let name = String(data: nameData, encoding: .utf8),
                  ChekinanaStreamingZIP.safe(name),
                  result[name] == nil,
                  allowedEntry(name, byteCount: uncompressedSize, archiveSize: archiveSize) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let destination = root.appendingPathComponent(name, isDirectory: false)
            try FileManager.default.createDirectory(
                at: destination.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            let offset = input.offsetInFile
            let isMedia = name.hasPrefix("media/")
            // Validate every archive byte before deciding whether local bytes can
            // be reused. Only JSON is materialized during this first pass.
            let inspection = try inspectRange(
                input, byteCount: uncompressedSize,
                destination: isMedia ? nil : destination
            )
            guard inspection.crc32 == expectedCRC else {
                throw ChekinanaDataImportError.mediaIntegrity
            }
            if isMedia { mediaOffsets[name] = offset }
            result[name] = .init(
                url: destination, byteCount: inspection.size,
                sha256: inspection.sha256, crc32: inspection.crc32
            )
        }
        guard result["manifest.json"] != nil,
              result["data.json"] != nil,
              result["settings.json"] != nil,
              Set(result.keys) == expectedEntries else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let candidates = try reusableFiles(
            in: managedDirectory,
            sizes: Set(mediaOffsets.keys.compactMap { result[$0]?.byteCount }),
            identityCache: identityCache
        )
        for name in mediaOffsets.keys.sorted() {
            try Task.checkCancellation()
            guard let file = result[name], let offset = mediaOffsets[name] else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let key = contentKey(size: file.byteCount, sha256: file.sha256)
            var reused = false
            if let candidate = candidates[key] {
                do {
                    // This alias belongs to this import only; never open it for
                    // writing. Removing the owned tree only unlinks the alias.
                    try FileManager.default.linkItem(at: candidate, to: file.url)
                    let values = try file.url.resourceValues(forKeys: [.isRegularFileKey, .isSymbolicLinkKey])
                    guard values.isRegularFile == true, values.isSymbolicLink != true else {
                        throw ChekinanaDataImportError.mediaIntegrity
                    }
                    let linked = try identityCache?.inspection(file.url, checkingCancellation: true)
                        ?? ChekinanaStreamingZIP.inspect(file.url)
                    reused = linked.size == file.byteCount
                        && linked.sha256 == file.sha256 && linked.crc32 == file.crc32
                } catch is CancellationError {
                    throw CancellationError()
                } catch {
                    reused = false
                }
                if !reused { try? FileManager.default.removeItem(at: file.url) }
            }
            if !reused {
                try input.seek(toOffset: offset)
                let written = try inspectRange(
                    input, byteCount: file.byteCount, destination: file.url
                )
                guard written.size == file.byteCount,
                      written.sha256 == file.sha256, written.crc32 == file.crc32 else {
                    throw ChekinanaDataImportError.mediaIntegrity
                }
            }
        }
        transferred = true
        return result
    }

    private static func contentKey(size: UInt64, sha256: String) -> String {
        "\(size):\(sha256)"
    }

    private static func reusableFiles(
        in directory: URL?, sizes: Set<UInt64>, identityCache: ChekinanaImportIdentityCache?
    ) throws -> [String: URL] {
        guard let directory,
              let urls = try? FileManager.default.contentsOfDirectory(
                at: directory,
                includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey],
                options: [.skipsHiddenFiles]
              ) else { return [:] }
        var result: [String: URL] = [:]
        for url in urls {
            try Task.checkCancellation()
            guard let values = try? url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey]
            ), values.isRegularFile == true, values.isSymbolicLink != true,
               let size = values.fileSize, size >= 0, sizes.contains(UInt64(size)) else { continue }
            do {
                let value = try identityCache?.inspection(url, checkingCancellation: true) ?? ChekinanaStreamingZIP.inspect(url)
                result[contentKey(size: value.size, sha256: value.sha256)] = url
            } catch is CancellationError {
                throw CancellationError()
            } catch {
                // An unreadable or changing local candidate never invalidates
                // the backup; materialize its verified archive entry instead.
                continue
            }
        }
        return result
    }

    private static func inspectRange(
        _ input: FileHandle,
        byteCount: UInt64,
        destination: URL?
    ) throws -> ChekinanaStreamingZIP.Inspection {
        let output: FileHandle?
        if let destination {
            // Exclusive creation prevents accidentally truncating a reused inode.
            let descriptor = Darwin.open(destination.path, O_WRONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR)
            guard descriptor >= 0 else {
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
            }
            output = FileHandle(fileDescriptor: descriptor, closeOnDealloc: true)
        } else { output = nil }
        defer { try? output?.close() }
        let buffer = UnsafeMutableRawBufferPointer.allocate(
            byteCount: chunkSize, alignment: MemoryLayout<UInt64>.alignment
        )
        defer { buffer.deallocate() }
        var remaining = byteCount
        var crc = zlib.crc32(0, nil, 0)
        var sha = SHA256()
        while remaining > 0 {
            try Task.checkCancellation()
            let length = Darwin.read(input.fileDescriptor, buffer.baseAddress!, Int(min(UInt64(chunkSize), remaining)))
            if length < 0 {
                let code = errno
                if code == EINTR { continue }
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(code))
            }
            guard length > 0 else { throw ChekinanaDataImportError.invalidArchive }
            let bytes = UnsafeRawBufferPointer(start: buffer.baseAddress, count: length)
            if let output { try ChekinanaStreamingZIP.writeAll(bytes, to: output.fileDescriptor) }
            crc = zlib.crc32(crc, bytes.bindMemory(to: Bytef.self).baseAddress, uInt(length))
            sha.update(bufferPointer: bytes)
            remaining -= UInt64(length)
        }
        try output?.synchronize()
        return .init(
            size: byteCount, crc32: UInt32(truncatingIfNeeded: crc),
            sha256: sha.finalize().map { String(format: "%02x", $0) }.joined()
        )
    }

    private static func storedSizes(
        legacyCompressed: UInt32,
        legacyUncompressed: UInt32,
        extra: Data
    ) throws -> (compressed: UInt64, uncompressed: UInt64) {
        let needsCompressed = legacyCompressed == UInt32.max
        let needsUncompressed = legacyUncompressed == UInt32.max
        guard needsCompressed || needsUncompressed else {
            return (UInt64(legacyCompressed), UInt64(legacyUncompressed))
        }
        var cursor = 0
        while cursor + 4 <= extra.count {
            let identifier = extra.u16(at: cursor)
            let length = Int(extra.u16(at: cursor + 2))
            cursor += 4
            guard cursor + length <= extra.count else {
                throw ChekinanaDataImportError.invalidArchive
            }
            if identifier == 0x0001 {
                var valueCursor = cursor
                let uncompressed: UInt64
                let compressed: UInt64
                if needsUncompressed {
                    guard valueCursor + 8 <= cursor + length else {
                        throw ChekinanaDataImportError.invalidArchive
                    }
                    uncompressed = extra.u64(at: valueCursor)
                    valueCursor += 8
                } else {
                    uncompressed = UInt64(legacyUncompressed)
                }
                if needsCompressed {
                    guard valueCursor + 8 <= cursor + length else {
                        throw ChekinanaDataImportError.invalidArchive
                    }
                    compressed = extra.u64(at: valueCursor)
                } else {
                    compressed = UInt64(legacyCompressed)
                }
                return (compressed, uncompressed)
            }
            cursor += length
        }
        throw ChekinanaDataImportError.invalidArchive
    }

    private static func allowedEntry(
        _ name: String,
        byteCount: UInt64,
        archiveSize: UInt64
    ) -> Bool {
        if ["manifest.json", "data.json", "settings.json"].contains(name) {
            return byteCount > 0 && byteCount <= maximumJSONBytes
        }
        return name.hasPrefix("media/")
            && name.split(separator: "/").count == 2
            && byteCount > 0
            && byteCount <= archiveSize
    }

    private static func readExactly(_ handle: FileHandle, count: Int) throws -> Data {
        guard count >= 0 else { throw ChekinanaDataImportError.invalidArchive }
        if count == 0 { return Data() }
        let data = try handle.read(upToCount: count) ?? Data()
        guard data.count == count else { throw ChekinanaDataImportError.invalidArchive }
        return data
    }

    private static func validateArchiveStructure(
        _ url: URL,
        archiveSize: UInt64
    ) throws -> Set<String> {
        let handle = try FileHandle(forReadingFrom: url)
        defer { try? handle.close() }
        let end = try validatedEndRecord(handle, archiveSize: archiveSize)
        guard end.entryCount <= UInt64(maximumEntryCount),
              let entryCount = Int(exactly: end.entryCount) else {
            throw ChekinanaDataImportError.invalidArchive
        }
        try handle.seek(toOffset: end.centralOffset)
        var entries: [CentralEntry] = []
        var names = Set<String>()
        for _ in 0..<entryCount {
            let header = try readExactly(handle, count: 46)
            guard header.u32(at: 0) == 0x02014b50 else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let flags = header.u16(at: 8)
            let method = header.u16(at: 10)
            let crc32 = header.u32(at: 16)
            let legacyCompressed = header.u32(at: 20)
            let legacyUncompressed = header.u32(at: 24)
            let nameLength = Int(header.u16(at: 28))
            let extraLength = Int(header.u16(at: 30))
            let commentLength = Int(header.u16(at: 32))
            let diskStart = header.u16(at: 34)
            let legacyLocalOffset = header.u32(at: 42)
            guard flags & 0x0009 == 0,
                  method == 0,
                  diskStart == 0,
                  nameLength > 0,
                  nameLength <= 1_024 else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let nameData = try readExactly(handle, count: nameLength)
            let extra = try readExactly(handle, count: extraLength)
            _ = try readExactly(handle, count: commentLength)
            guard let name = String(data: nameData, encoding: .utf8),
                  ChekinanaStreamingZIP.safe(name),
                  names.insert(name).inserted else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let values = try centralValues(
                legacyCompressed: legacyCompressed,
                legacyUncompressed: legacyUncompressed,
                legacyLocalOffset: legacyLocalOffset,
                extra: extra
            )
            guard values.compressed == values.uncompressed,
                  values.localOffset < end.centralOffset,
                  allowedEntry(
                    name,
                    byteCount: values.uncompressed,
                    archiveSize: archiveSize
                  ) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            entries.append(CentralEntry(
                name: name,
                flags: flags,
                method: method,
                crc32: crc32,
                compressedSize: values.compressed,
                uncompressedSize: values.uncompressed,
                localOffset: values.localOffset
            ))
        }
        let centralEnd = try checkedAdd(end.centralOffset, end.centralSize)
        guard handle.offsetInFile == centralEnd else {
            throw ChekinanaDataImportError.invalidArchive
        }

        let ordered = entries.sorted { $0.localOffset < $1.localOffset }
        guard ordered.first?.localOffset == 0 else {
            throw ChekinanaDataImportError.invalidArchive
        }
        for (index, entry) in ordered.enumerated() {
            try handle.seek(toOffset: entry.localOffset)
            let header = try readExactly(handle, count: 30)
            guard header.u32(at: 0) == 0x04034b50 else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let flags = header.u16(at: 6)
            let method = header.u16(at: 8)
            let crc32 = header.u32(at: 14)
            let legacyCompressed = header.u32(at: 18)
            let legacyUncompressed = header.u32(at: 22)
            let nameLength = Int(header.u16(at: 26))
            let extraLength = Int(header.u16(at: 28))
            let nameData = try readExactly(handle, count: nameLength)
            let extra = try readExactly(handle, count: extraLength)
            let sizes = try storedSizes(
                legacyCompressed: legacyCompressed,
                legacyUncompressed: legacyUncompressed,
                extra: extra
            )
            guard String(data: nameData, encoding: .utf8) == entry.name,
                  flags == entry.flags,
                  method == entry.method,
                  crc32 == entry.crc32,
                  sizes.compressed == entry.compressedSize,
                  sizes.uncompressed == entry.uncompressedSize else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let dataEnd = try checkedAdd(handle.offsetInFile, entry.compressedSize)
            let expectedEnd = index + 1 < ordered.count
                ? ordered[index + 1].localOffset
                : end.centralOffset
            guard dataEnd == expectedEnd else {
                throw ChekinanaDataImportError.invalidArchive
            }
        }
        return names
    }

    private static func validatedEndRecord(
        _ handle: FileHandle,
        archiveSize: UInt64
    ) throws -> EndRecord {
        let tailCount = Int(min(archiveSize, 65_557))
        let tailOffset = archiveSize - UInt64(tailCount)
        try handle.seek(toOffset: tailOffset)
        let tail = try readExactly(handle, count: tailCount)
        guard tail.count >= 22 else {
            throw ChekinanaDataImportError.invalidArchive
        }
        var candidates: [(offset: UInt64, dataIndex: Int)] = []
        for index in stride(from: tail.count - 22, through: 0, by: -1) {
            guard tail.u32(at: index) == 0x06054b50 else { continue }
            let commentLength = Int(tail.u16(at: index + 20))
            guard index + 22 + commentLength == tail.count else { continue }
            candidates.append((tailOffset + UInt64(index), index))
        }
        guard candidates.count == 1, let candidate = candidates.first else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let index = candidate.dataIndex
        let disk = tail.u16(at: index + 4)
        let centralDisk = tail.u16(at: index + 6)
        let entriesOnDisk = tail.u16(at: index + 8)
        let entriesTotal = tail.u16(at: index + 10)
        let legacyCentralSize = tail.u32(at: index + 12)
        let legacyCentralOffset = tail.u32(at: index + 16)
        guard disk == 0, centralDisk == 0 else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let usesZip64 = entriesOnDisk == UInt16.max
            || entriesTotal == UInt16.max
            || legacyCentralSize == UInt32.max
            || legacyCentralOffset == UInt32.max
        let result: EndRecord
        if usesZip64 {
            guard entriesOnDisk == UInt16.max,
                  entriesTotal == UInt16.max,
                  legacyCentralSize == UInt32.max,
                  legacyCentralOffset == UInt32.max else {
                throw ChekinanaDataImportError.invalidArchive
            }
            result = try zip64EndRecord(handle, eocdOffset: candidate.offset)
        } else {
            guard entriesOnDisk == entriesTotal else {
                throw ChekinanaDataImportError.invalidArchive
            }
            result = EndRecord(
                centralOffset: UInt64(legacyCentralOffset),
                centralSize: UInt64(legacyCentralSize),
                entryCount: UInt64(entriesTotal),
                endOffset: candidate.offset
            )
        }
        guard try checkedAdd(result.centralOffset, result.centralSize) == result.endOffset,
              result.endOffset <= candidate.offset else {
            throw ChekinanaDataImportError.invalidArchive
        }
        return result
    }

    private static func zip64EndRecord(
        _ handle: FileHandle,
        eocdOffset: UInt64
    ) throws -> EndRecord {
        guard eocdOffset >= 20 else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let locatorOffset = eocdOffset - 20
        try handle.seek(toOffset: locatorOffset)
        let locator = try readExactly(handle, count: 20)
        guard locator.u32(at: 0) == 0x07064b50,
              locator.u32(at: 4) == 0,
              locator.u32(at: 16) == 1 else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let recordOffset = locator.u64(at: 8)
        guard recordOffset < locatorOffset else {
            throw ChekinanaDataImportError.invalidArchive
        }
        try handle.seek(toOffset: recordOffset)
        let header = try readExactly(handle, count: 56)
        guard header.u32(at: 0) == 0x06064b50,
              header.u64(at: 4) >= 44,
              header.u16(at: 14) >= 45,
              header.u32(at: 16) == 0,
              header.u32(at: 20) == 0,
              header.u64(at: 24) == header.u64(at: 32) else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let recordEnd = try checkedAdd(recordOffset, try checkedAdd(12, header.u64(at: 4)))
        guard recordEnd == locatorOffset else {
            throw ChekinanaDataImportError.invalidArchive
        }
        return EndRecord(
            centralOffset: header.u64(at: 48),
            centralSize: header.u64(at: 40),
            entryCount: header.u64(at: 32),
            endOffset: recordOffset
        )
    }

    private static func centralValues(
        legacyCompressed: UInt32,
        legacyUncompressed: UInt32,
        legacyLocalOffset: UInt32,
        extra: Data
    ) throws -> (compressed: UInt64, uncompressed: UInt64, localOffset: UInt64) {
        let needsCompressed = legacyCompressed == UInt32.max
        let needsUncompressed = legacyUncompressed == UInt32.max
        let needsOffset = legacyLocalOffset == UInt32.max
        guard needsCompressed || needsUncompressed || needsOffset else {
            return (
                UInt64(legacyCompressed),
                UInt64(legacyUncompressed),
                UInt64(legacyLocalOffset)
            )
        }
        let payload = try zip64Extra(extra)
        var cursor = 0
        func next(_ required: Bool, legacy: UInt32) throws -> UInt64 {
            guard required else { return UInt64(legacy) }
            guard cursor + 8 <= payload.count else {
                throw ChekinanaDataImportError.invalidArchive
            }
            defer { cursor += 8 }
            return payload.u64(at: cursor)
        }
        let uncompressed = try next(needsUncompressed, legacy: legacyUncompressed)
        let compressed = try next(needsCompressed, legacy: legacyCompressed)
        let offset = try next(needsOffset, legacy: legacyLocalOffset)
        return (compressed, uncompressed, offset)
    }

    private static func zip64Extra(_ extra: Data) throws -> Data {
        var cursor = 0
        while cursor + 4 <= extra.count {
            let identifier = extra.u16(at: cursor)
            let length = Int(extra.u16(at: cursor + 2))
            cursor += 4
            guard cursor + length <= extra.count else {
                throw ChekinanaDataImportError.invalidArchive
            }
            if identifier == 0x0001 {
                return Data(extra[cursor..<(cursor + length)])
            }
            cursor += length
        }
        throw ChekinanaDataImportError.invalidArchive
    }

    private static func checkedAdd(_ lhs: UInt64, _ rhs: UInt64) throws -> UInt64 {
        let result = lhs.addingReportingOverflow(rhs)
        guard !result.overflow else {
            throw ChekinanaDataImportError.invalidArchive
        }
        return result.partialValue
    }
}

private extension Data {
    func u16(at index: Int) -> UInt16 {
        UInt16(self[index]) | UInt16(self[index + 1]) << 8
    }

    func u32(at index: Int) -> UInt32 {
        UInt32(u16(at: index)) | UInt32(u16(at: index + 2)) << 16
    }

    func u64(at index: Int) -> UInt64 {
        UInt64(u32(at: index)) | UInt64(u32(at: index + 4)) << 32
    }
}

struct ChekinanaImportFileIdentity: Codable, Equatable, Sendable {
    let byteCount: UInt64
    let sha256: String

    init(byteCount: UInt64, sha256: String) {
        self.byteCount = byteCount
        self.sha256 = sha256.lowercased()
    }

    init(_ data: Data) {
        byteCount = UInt64(data.count)
        sha256 = SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    static func inspect(_ url: URL) throws -> Self {
        guard ChekiImageRefResolver.isRegularReadableFile(url) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let handle = try FileHandle(forReadingFrom: url)
        defer { try? handle.close() }
        let buffer = UnsafeMutableRawBufferPointer.allocate(
            byteCount: 1_048_576, alignment: MemoryLayout<UInt64>.alignment
        )
        defer { buffer.deallocate() }
        var hash = SHA256()
        var count: UInt64 = 0
        // Recovery calls this primitive from an already-cancelled task. Keep
        // identity checks non-cancellable so rollback can verify original bytes.
        while true {
            let length = Darwin.read(handle.fileDescriptor, buffer.baseAddress!, buffer.count)
            if length < 0 {
                let code = errno
                if code == EINTR { continue }
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(code))
            }
            if length == 0 { break }
            let addition = count.addingReportingOverflow(UInt64(length))
            guard !addition.overflow else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            count = addition.partialValue
            hash.update(bufferPointer: UnsafeRawBufferPointer(start: buffer.baseAddress, count: length))
        }
        return Self(
            byteCount: count,
            sha256: hash.finalize().map { String(format: "%02x", $0) }.joined()
        )
    }

    var isValid: Bool {
        sha256.count == 64 && sha256.utf8.allSatisfy { byte in
            (byte >= 48 && byte <= 57) || (byte >= 97 && byte <= 102)
        }
    }
}

enum ChekinanaImportTransactionError: Error, Equatable {
    case invalidJournal
    case incomplete
    case indeterminate

    var importError: ChekinanaDataImportError {
        switch self {
        case .invalidJournal, .indeterminate: .recoveryIndeterminate
        case .incomplete: .recoveryIncomplete
        }
    }
}

/// Operation-local evidence only; never persisted or attached to discovered
/// recovery handles. Every reuse reopens and verifies the complete file stamp.
final class ChekinanaImportIdentityCache: @unchecked Sendable {
    private struct Stamp: Hashable {
        let device: Int64
        let inode: UInt64
        let generation: UInt32
        let mode: UInt32
        let links: UInt64
        let size: Int64
        let modifiedSeconds: Int64
        let modifiedNanoseconds: Int64
        let changedSeconds: Int64
        let changedNanoseconds: Int64

        init(_ value: stat) {
            device = Int64(value.st_dev); inode = UInt64(value.st_ino)
            generation = UInt32(value.st_gen); mode = UInt32(value.st_mode)
            links = UInt64(value.st_nlink); size = Int64(value.st_size)
            modifiedSeconds = Int64(value.st_mtimespec.tv_sec)
            modifiedNanoseconds = Int64(value.st_mtimespec.tv_nsec)
            changedSeconds = Int64(value.st_ctimespec.tv_sec)
            changedNanoseconds = Int64(value.st_ctimespec.tv_nsec)
        }
    }

    private let lock = NSLock()
    private var entries: [Stamp: ChekinanaStreamingZIP.Inspection] = [:]
    private static let maximumEntries = 4_096

    func identity(_ url: URL) throws -> ChekinanaImportFileIdentity {
        let value = try inspection(url)
        return .init(byteCount: value.size, sha256: value.sha256)
    }

    func inspection(
        _ url: URL, checkingCancellation: Bool = false
    ) throws -> ChekinanaStreamingZIP.Inspection {
        if checkingCancellation { try Task.checkCancellation() }
        let descriptor = Darwin.open(url.path, O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
        guard descriptor >= 0 else { throw ChekinanaImportTransactionError.indeterminate }
        defer { Darwin.close(descriptor) }
        let before = try Self.stamp(descriptor)
        lock.lock()
        let cached = entries[before]
        lock.unlock()
        if let cached {
            try Self.requireUnchanged(url, descriptor: descriptor, expected: before)
            return cached
        }
        let buffer = UnsafeMutableRawBufferPointer.allocate(
            byteCount: 1_048_576, alignment: MemoryLayout<UInt64>.alignment
        )
        defer { buffer.deallocate() }
        var hash = SHA256()
        var crc = zlib.crc32(0, nil, 0)
        var count: UInt64 = 0
        // Like the uncached identity primitive, this must finish in an already
        // cancelled task so same-operation rollback can validate original bytes.
        while true {
            if checkingCancellation { try Task.checkCancellation() }
            let length = Darwin.read(descriptor, buffer.baseAddress!, buffer.count)
            if length < 0 {
                let code = errno
                if code == EINTR { continue }
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(code))
            }
            if length == 0 { break }
            let addition = count.addingReportingOverflow(UInt64(length))
            guard !addition.overflow else { throw ChekinanaImportTransactionError.invalidJournal }
            count = addition.partialValue
            let bytes = UnsafeRawBufferPointer(start: buffer.baseAddress, count: length)
            hash.update(bufferPointer: bytes)
            crc = zlib.crc32(crc, bytes.bindMemory(to: Bytef.self).baseAddress, uInt(length))
        }
        try Self.requireUnchanged(url, descriptor: descriptor, expected: before)
        guard count == UInt64(before.size) else { throw ChekinanaImportTransactionError.indeterminate }
        let value = ChekinanaStreamingZIP.Inspection(
            size: count, crc32: UInt32(truncatingIfNeeded: crc),
            sha256: hash.finalize().map { String(format: "%02x", $0) }.joined()
        )
        lock.lock()
        if entries.count >= Self.maximumEntries { entries.removeAll(keepingCapacity: true) }
        entries[before] = value
        lock.unlock()
        return value
    }

    private static func stamp(_ descriptor: Int32) throws -> Stamp {
        var value = stat()
        guard Darwin.fstat(descriptor, &value) == 0,
              value.st_mode & S_IFMT == S_IFREG, value.st_size >= 0 else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return Stamp(value)
    }

    private static func requireUnchanged(_ url: URL, descriptor: Int32, expected: Stamp) throws {
        var path = stat()
        guard try stamp(descriptor) == expected,
              Darwin.lstat(url.path, &path) == 0, Stamp(path) == expected else {
            throw ChekinanaImportTransactionError.indeterminate
        }
    }
}

struct ChekinanaImportTransactionJournal: Codable, Equatable, Sendable {
    enum Phase: String, Codable, Sendable {
        case stagingOld
        case materializingNew
        case databaseCommitPending
        case finishingNew
    }

    struct StoredSettings: Codable, Equatable, Sendable {
        let language: String
        let theme: String
        let hiddenIdolIDs: [String]
    }

    struct OldFile: Codable, Equatable, Sendable {
        let originalName: String
        let rollbackName: String
        let identity: ChekinanaImportFileIdentity
    }

    struct CreatedFile: Codable, Equatable, Sendable {
        let filename: String
        let identity: ChekinanaImportFileIdentity
    }

    let formatVersion: Int
    let transactionID: UUID
    let oldGeneration: UUID
    let newGeneration: UUID
    var phase: Phase
    let settings: StoredSettings
    let oldFiles: [OldFile]
    var createdFiles: [CreatedFile]
}

enum ChekinanaImportRecoveryDirection: Equatable, Sendable {
    case restoreOld
    case completeNew

    static func resolve(
        oldGeneration: UUID,
        newGeneration: UUID,
        currentGeneration: UUID?
    ) throws -> Self {
        guard let currentGeneration else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        if currentGeneration == oldGeneration { return .restoreOld }
        if currentGeneration == newGeneration { return .completeNew }
        throw ChekinanaImportTransactionError.indeterminate
    }
}

/// A reserved CalendarGroupOrder row is the library-generation witness. It is
/// inserted with the entity replacement and saved by the same SwiftData save,
/// so an external file journal never has to guess whether that save committed.
/// The reserved row is excluded from backup payloads and cannot match a real
/// calendar date key.
@MainActor
enum ChekinanaLibraryGenerationStore {
    nonisolated static let markerDateKey = "__chekinana_library_generation_v1__"

    static func isMarker(_ value: CalendarGroupOrder) -> Bool {
        value.dateKey == markerDateKey
    }

    nonisolated static func isReserved(dateKey: String) -> Bool {
        dateKey == markerDateKey
    }

    static func current(in modelContext: ModelContext) throws -> UUID? {
        let markers = try modelContext.fetch(FetchDescriptor<CalendarGroupOrder>())
            .filter { isMarker($0) }
        guard markers.count <= 1 else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        guard let marker = markers.first else { return nil }
        guard marker.id == CalendarGroupOrder.key(
                dateKey: markerDateKey,
                groupKey: marker.groupKey
              ),
              marker.sortOrder == 0,
              let generation = UUID(uuidString: marker.groupKey) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return generation
    }

    static func ensureCurrent(in modelContext: ModelContext) throws -> UUID {
        if let generation = try current(in: modelContext) { return generation }
        let generation = UUID()
        modelContext.insert(CalendarGroupOrder(
            dateKey: markerDateKey,
            groupKey: generation.uuidString.lowercased(),
            sortOrder: 0
        ))
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
            throw error
        }
        return generation
    }

    /// Call immediately before the entity replacement's single save. The old
    /// witness is deleted and the new witness is inserted in that same commit.
    static func publish(_ generation: UUID, in modelContext: ModelContext) throws {
        for marker in try modelContext.fetch(FetchDescriptor<CalendarGroupOrder>())
        where isMarker(marker) {
            modelContext.delete(marker)
        }
        modelContext.insert(CalendarGroupOrder(
            dateKey: markerDateKey,
            groupKey: generation.uuidString.lowercased(),
            sortOrder: 0
        ))
    }
}

private final class ChekinanaLibraryExclusiveOperationGate: @unchecked Sendable {
    private enum Holder: Equatable {
        case asynchronous
        case synchronous
    }

    private let lock = NSLock()
    private var holder: Holder?
    private var waiters: [CheckedContinuation<Void, Never>] = []

    func acquireAsynchronously() async {
        await withCheckedContinuation { continuation in
            enqueue(continuation)
        }
    }

    func releaseAsynchronously() {
        release(.asynchronous)
    }

    func tryAcquireSynchronously() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        guard holder == nil else { return false }
        holder = .synchronous
        return true
    }

    func releaseSynchronously() {
        release(.synchronous)
    }

    private func enqueue(_ continuation: CheckedContinuation<Void, Never>) {
        lock.lock()
        guard holder != nil else {
            holder = .asynchronous
            lock.unlock()
            continuation.resume()
            return
        }
        waiters.append(continuation)
        lock.unlock()
    }

    private func release(_ expectedHolder: Holder) {
        let continuation: CheckedContinuation<Void, Never>?
        lock.lock()
        guard holder == expectedHolder else {
            lock.unlock()
            return
        }
        if waiters.isEmpty {
            holder = nil
            continuation = nil
        } else {
            holder = .asynchronous
            continuation = waiters.removeFirst()
        }
        lock.unlock()
        continuation?.resume()
    }
}

/// Shared opt-in boundary for import and the follow-up clear/delete/journal
/// repairs. Later file-owning operations can reuse this gate plus the same
/// generation witness without changing their existing data contracts.
enum ChekinanaLibraryMutationProtocol {
    private static let gate = ChekinanaLibraryExclusiveOperationGate()

    enum SynchronousOperationError: LocalizedError, Equatable {
        case busy

        var errorDescription: String? {
            switch self {
            case .busy:
                ChekinanaL10n.message("The library is changing. Try saving again after recovery finishes.")
            }
        }
    }

    @MainActor
    static func withExclusiveOperation<Value>(
        _ operation: @MainActor () async throws -> Value
    ) async rethrows -> Value {
        await gate.acquireAsynchronously()
        defer { gate.releaseAsynchronously() }
        return try await operation()
    }

    /// Synchronous SwiftData saves use the same exclusion boundary as the
    /// async import/clear protocol. A save never waits on an in-flight async
    /// library mutation; it fails closed so an editor from the old generation
    /// cannot commit into a changing library. The gate records ownership under
    /// a short, non-awaiting lock; no thread lock is held by an asynchronous
    /// operation while its body is suspended.
    @MainActor
    static func withExclusiveOperationSync<Value>(
        _ operation: () throws -> Value
    ) throws -> Value {
        guard gate.tryAcquireSynchronously() else {
            throw SynchronousOperationError.busy
        }
        defer { gate.releaseSynchronously() }
        return try operation()
    }
}

/// Normal file-owning mutations call this after acquiring the library gate,
/// before changing any model or managed byte. Recovery uses its own internal
/// paths and never reacquires the library gate through this preflight.
@MainActor
enum ChekinanaLibraryMutationPreflight {
    static func requireImportConvergedExclusively(
        in modelContext: ModelContext,
        directory: URL? = nil,
        includingChekiDeletions: Bool = true
    ) throws {
        try ChekinanaPersistenceMutationCoordinator.withLock {
            try ChekinanaDataImporter.recoverUnfinishedImport(
                in: modelContext,
                directory: directory
            )
            if includingChekiDeletions {
                try ChekinanaChekiEditRecovery.requireConvergedExclusively(
                    in: modelContext, directory: directory
                )
                _ = try ChekinanaChekiDeletionRecovery.recoverExclusively(
                    in: modelContext, directory: directory
                )
            }
        }
    }

    /// Only entrances that replace the library use this stronger preflight.
    /// Recovery cores never call it, so clear/import cannot recurse into a gate.
    static func requireLibraryReplacementReadyExclusively(
        in modelContext: ModelContext,
        directory: URL? = nil
    ) throws {
        try requireImportConvergedExclusively(in: modelContext, directory: directory)
        try ChekinanaLocalDataClearer.requireClearConvergedExclusively(
            in: modelContext, directory: directory
        )
    }
}

/// One authoritative view of every filename owned by the current SwiftData
/// library. Video thumbnails are derived from their stable owners because no
/// model field stores those references directly.
struct ChekinanaLibraryFileReferenceSnapshot: Equatable, Sendable {
    let generation: UUID
    let referencedFilenames: Set<String>
    let identitiesByFilename: [String: ChekinanaImportFileIdentity]

    @MainActor
    static func capture(
        in modelContext: ModelContext,
        directory: URL,
        requireEveryReferencedFile: Bool = false,
        excludingMediaItemID: UUID? = nil,
        excludingMediaItemIDs: Set<UUID> = [],
        excludingIdolIDs: Set<UUID> = [],
        excludingMemoryAttachmentIDs: Set<UUID> = []
    ) throws -> Self {
        guard let generation = try ChekinanaLibraryGenerationStore.current(
            in: modelContext
        ) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let canonicalDirectory = directory.standardizedFileURL
        var filenames = Set<String>()
        func add(_ reference: String?) {
            guard let filename = normalizedManagedFilename(
                reference,
                directory: canonicalDirectory
            ) else { return }
            filenames.insert(filename)
        }

        for idol in try modelContext.fetch(FetchDescriptor<Idol>()) where !excludingIdolIDs.contains(idol.id) {
            add(idol.avatarImageRef)
        }
        for event in try modelContext.fetch(FetchDescriptor<Event>()) {
            add(event.avatarImageRef)
        }
        for image in try modelContext.fetch(FetchDescriptor<EventImage>()) {
            add(image.imageRef)
        }
        for travel in try modelContext.fetch(FetchDescriptor<TravelSegment>())
        where ChekinanaTravelOperatorIcon.assetName(from: travel.operatorIconRef) == nil {
            add(travel.operatorIconRef)
        }
        for item in try modelContext.fetch(FetchDescriptor<MediaItem>())
        where item.id != excludingMediaItemID && !excludingMediaItemIDs.contains(item.id) {
            // `mediaRef` covers cheki, shame, and douga. The switch is kept
            // explicit so adding a future kind cannot silently skip policy.
            switch item.kind {
            case .cheki, .shame, .douga:
                add(item.mediaRef)
            }
            if item.kind == .douga {
                add(ChekinanaGalleryMediaStore.thumbnailURL(
                    id: item.mediaOwnerID,
                    directory: canonicalDirectory
                ).lastPathComponent)
            }
        }
        for attachment in try modelContext.fetch(FetchDescriptor<MemoryAttachment>())
        where !excludingMemoryAttachmentIDs.contains(attachment.id) {
            add(attachment.managedRef)
            if attachment.kind == .video {
                add(ChekinanaGalleryMediaStore.thumbnailURL(
                    id: attachment.id,
                    directory: canonicalDirectory
                ).lastPathComponent)
            }
        }

        var identities: [String: ChekinanaImportFileIdentity] = [:]
        if requireEveryReferencedFile {
            identities.reserveCapacity(filenames.count)
            for filename in filenames {
                let url = canonicalDirectory.appendingPathComponent(filename)
                do {
                    identities[filename] = try ChekinanaImportFileIdentity.inspect(url)
                } catch {
                    throw ChekinanaImportTransactionError.incomplete
                }
            }
        }
        return Self(
            generation: generation,
            referencedFilenames: filenames,
            identitiesByFilename: identities
        )
    }

    private static func normalizedManagedFilename(
        _ rawValue: String?,
        directory: URL
    ) -> String? {
        guard let value = rawValue?.trimmingCharacters(in: .whitespacesAndNewlines),
              !value.isEmpty else { return nil }
        let directName = URL(fileURLWithPath: value).lastPathComponent
        if value == directName, directName != ".", directName != ".." {
            return directName
        }
        let localURL: URL?
        if let parsed = URL(string: value), parsed.isFileURL {
            localURL = parsed
        } else if value.hasPrefix("/") {
            localURL = URL(fileURLWithPath: value)
        } else {
            localURL = nil
        }
        guard let localURL = localURL?.standardizedFileURL,
              localURL.deletingLastPathComponent() == directory,
              localURL.lastPathComponent != ".",
              localURL.lastPathComponent != ".." else { return nil }
        return localURL.lastPathComponent
    }
}

struct ChekinanaLibraryQueueCleanupReport: Equatable, Sendable {
    var deferredActionCount = 0
    var blockedByImportTransaction = false

    var needsRetry: Bool {
        blockedByImportTransaction || deferredActionCount > 0
    }
}

/// Replays fsync-backed Gallery delete intents. The durable library witness and
/// complete reference snapshot decide the direction; the journal phase is
/// diagnostic only, because a process may stop immediately after DB commit.
@MainActor
enum ChekinanaGalleryDeletionRecoveryCoordinator {
    private static let logger = Logger(
        subsystem: Bundle.main.bundleIdentifier ?? "Chekinana",
        category: "GalleryDeletionRecovery"
    )

    static func recoverExclusively(
        in modelContext: ModelContext,
        directory: URL,
        fileManager: FileManager = .default,
        moveItem: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        },
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        }
    ) -> Int {
        let canonicalDirectory = directory.standardizedFileURL
        let journals: [ChekinanaGalleryDeletionJournal]
        do {
            journals = try ChekinanaGalleryDeletionJournalStore.discover(
                in: canonicalDirectory,
                fileManager: fileManager
            )
        } catch {
            logger.error("Gallery delete journal discovery failed")
            return 1
        }
        var deferred = 0
        for originalJournal in journals {
            var journal = originalJournal
            let referenced: [Bool]
            do {
                let snapshot = try ChekinanaLibraryFileReferenceSnapshot.capture(
                    in: ModelContext(modelContext.container),
                    directory: canonicalDirectory
                )
                guard snapshot.generation == journal.libraryGeneration else {
                    logger.error("Gallery delete generation conflict retained")
                    deferred += 1
                    continue
                }
                referenced = journal.entries.map {
                    snapshot.referencedFilenames.contains($0.originalName)
                }
            } catch {
                deferred += 1
                continue
            }
            // Once the post-save phase reached disk, a later record reusing
            // the same public filename must not turn this operation back into
            // a restore. That collision is retained for explicit resolution.
            let restoresOldSide = journal.phase != .databaseCommitted
                && referenced.allSatisfy { $0 }
            let completesCommittedDelete = referenced.allSatisfy { !$0 }
            guard restoresOldSide || completesCommittedDelete else {
                logger.error("Gallery delete DB reference state is mixed; both sides retained")
                deferred += 1
                continue
            }

            var operationDeferred = false
            for index in journal.entries.indices {
                let entry = journal.entries[index]
                let completed = restoresOldSide
                    ? restore(
                        entry,
                        journal: journal,
                        modelContext: modelContext,
                        directory: canonicalDirectory,
                        fileManager: fileManager,
                        moveItem: moveItem,
                        removeItem: removeItem
                    )
                    : removeCommitted(
                        entry,
                        journal: journal,
                        modelContext: modelContext,
                        directory: canonicalDirectory,
                        fileManager: fileManager,
                        removeItem: removeItem
                    )
                guard completed else {
                    operationDeferred = true
                    deferred += 1
                    continue
                }
                journal.entries[index].stage = restoresOldSide ? .restored : .removed
                do {
                    try ChekinanaGalleryDeletionJournalStore.persist(
                        journal,
                        in: canonicalDirectory,
                        fileManager: fileManager
                    )
                } catch {
                    operationDeferred = true
                    deferred += 1
                }
            }
            guard !operationDeferred else {
                logger.error("Gallery delete recovery retained for retry")
                continue
            }
            do {
                try ChekinanaGalleryDeletionJournalStore.discard(
                    operationID: journal.operationID,
                    in: canonicalDirectory,
                    fileManager: fileManager
                )
            } catch {
                deferred += 1
            }
        }
        return deferred
    }

    private static func restore(
        _ entry: ChekinanaGalleryDeletionJournal.Entry,
        journal: ChekinanaGalleryDeletionJournal,
        modelContext: ModelContext,
        directory: URL,
        fileManager: FileManager,
        moveItem: (URL, URL) throws -> Void,
        removeItem: (URL) throws -> Void
    ) -> Bool {
        do {
            return try ChekinanaPersistenceMutationCoordinator.withLock {
                let latest = try currentSnapshot(
                    journal: journal,
                    modelContext: modelContext,
                    directory: directory
                )
                guard latest.referencedFilenames.contains(entry.originalName) else {
                    return false
                }
                let original = directory.appendingPathComponent(entry.originalName)
                let quarantine = directory.appendingPathComponent(entry.quarantineName)
                let originalIdentity = try identityIfPresent(
                    original,
                    directory: directory,
                    fileManager: fileManager
                )
                let quarantineIdentity = try identityIfPresent(
                    quarantine,
                    directory: directory,
                    fileManager: fileManager
                )
                guard originalIdentity == nil || originalIdentity == entry.identity,
                      quarantineIdentity == nil || quarantineIdentity == entry.identity,
                      originalIdentity != nil || quarantineIdentity != nil else {
                    logger.error("Gallery restore byte conflict retained")
                    return false
                }
                if originalIdentity == entry.identity {
                    if quarantineIdentity == entry.identity {
                        try removeItem(quarantine)
                        return !fileManager.fileExists(atPath: quarantine.path)
                    }
                    return true
                }
                guard quarantineIdentity == entry.identity else { return false }
                try moveItem(quarantine, original)
                guard !fileManager.fileExists(atPath: quarantine.path) else {
                    return false
                }
                let restoredIdentity = try identityIfPresent(
                    original,
                    directory: directory,
                    fileManager: fileManager
                )
                return restoredIdentity == entry.identity
            }
        } catch {
            return false
        }
    }

    private static func removeCommitted(
        _ entry: ChekinanaGalleryDeletionJournal.Entry,
        journal: ChekinanaGalleryDeletionJournal,
        modelContext: ModelContext,
        directory: URL,
        fileManager: FileManager,
        removeItem: (URL) throws -> Void
    ) -> Bool {
        do {
            return try ChekinanaPersistenceMutationCoordinator.withLock {
                let latest = try currentSnapshot(
                    journal: journal,
                    modelContext: modelContext,
                    directory: directory
                )
                guard !latest.referencedFilenames.contains(entry.originalName) else {
                    return false
                }
                let original = directory.appendingPathComponent(entry.originalName)
                let quarantine = directory.appendingPathComponent(entry.quarantineName)
                let originalIdentity = try identityIfPresent(
                    original,
                    directory: directory,
                    fileManager: fileManager
                )
                let quarantineIdentity = try identityIfPresent(
                    quarantine,
                    directory: directory,
                    fileManager: fileManager
                )
                // A new, different file at the old public name is not owned by
                // this operation. Keep it and the journal as a visible conflict.
                guard originalIdentity == nil || originalIdentity == entry.identity,
                      quarantineIdentity == nil || quarantineIdentity == entry.identity else {
                    logger.error("Gallery committed-delete byte conflict retained")
                    return false
                }
                for candidate in [quarantine, original]
                where fileManager.fileExists(atPath: candidate.path) {
                    // Re-read immediately before each unlink so a replacement
                    // between candidates cannot inherit stale authorization.
                    let refreshed = try currentSnapshot(
                        journal: journal,
                        modelContext: modelContext,
                        directory: directory
                    )
                    guard !refreshed.referencedFilenames.contains(entry.originalName),
                          try identityIfPresent(
                            candidate,
                            directory: directory,
                            fileManager: fileManager
                          ) == entry.identity else {
                        return false
                    }
                    try removeItem(candidate)
                    guard !fileManager.fileExists(atPath: candidate.path) else {
                        return false
                    }
                }
                return true
            }
        } catch {
            return false
        }
    }

    private static func currentSnapshot(
        journal: ChekinanaGalleryDeletionJournal,
        modelContext: ModelContext,
        directory: URL
    ) throws -> ChekinanaLibraryFileReferenceSnapshot {
        let snapshot = try ChekinanaLibraryFileReferenceSnapshot.capture(
            in: ModelContext(modelContext.container),
            directory: directory
        )
        guard snapshot.generation == journal.libraryGeneration else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return snapshot
    }

    private static func identityIfPresent(
        _ url: URL,
        directory: URL,
        fileManager: FileManager
    ) throws -> ChekinanaImportFileIdentity? {
        guard url.standardizedFileURL.deletingLastPathComponent()
                == directory.standardizedFileURL else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        guard fileManager.fileExists(atPath: url.path) else { return nil }
        let values = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard values.isRegularFile == true,
              values.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return try ChekinanaImportFileIdentity.inspect(url)
    }
}

/// The only production entry point that may move Gallery media into deletion
/// quarantine. It keeps authorization, durable intent, the model delete, and
/// post-commit convergence inside the library gate and persistence lock.
@MainActor
enum ChekinanaGalleryDeletionCoordinator {
    typealias DeleteModel = () throws -> Void
    typealias SaveContext = (ModelContext) throws -> Void

    static func delete(
        kind: ChekinanaGalleryMediaKind,
        mediaOwnerID: UUID,
        reference: String?,
        in modelContext: ModelContext,
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        fileManager: FileManager = .default,
        saveContext: SaveContext = { try $0.save() },
        validateModel: @escaping () throws -> Void = {},
        deleteModel: @escaping DeleteModel
    ) async throws {
        try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            let managedDirectory = try directory
                ?? ChekiImageRefResolver.chekiImagesDirectory()
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: managedDirectory
            )
            try ChekinanaPersistenceMutationCoordinator.withLock {
                try Task.checkCancellation()
                try ChekinanaChekiEditRecovery.requireConvergedExclusively(
                    in: modelContext,
                    directory: managedDirectory,
                    fileManager: fileManager
                )
                let generation = try ChekinanaLibraryGenerationStore.ensureCurrent(
                    in: modelContext
                )
                guard ChekinanaGalleryDeletionRecoveryCoordinator
                    .recoverExclusively(
                        in: modelContext,
                        directory: managedDirectory,
                        fileManager: fileManager
                    ) == 0 else {
                    throw ChekinanaImportTransactionError.incomplete
                }
                try validateModel()

                let staged = try ChekinanaGalleryMediaStore.stageFilesForDeletion(
                    kind: kind,
                    id: mediaOwnerID,
                    reference: reference,
                    directory: managedDirectory,
                    libraryGeneration: generation,
                    fileManager: fileManager,
                    defaults: defaults,
                    beforeMove: { original, identity in
                        let latest = try ChekinanaLibraryFileReferenceSnapshot.capture(
                            in: ModelContext(modelContext.container),
                            directory: managedDirectory
                        )
                        guard latest.generation == generation,
                              latest.referencedFilenames.contains(
                                original.lastPathComponent
                              ),
                              try ChekinanaImportFileIdentity.inspect(original)
                                == identity else {
                            throw ChekinanaImportTransactionError.indeterminate
                        }
                    }
                )
                do {
                    try Task.checkCancellation()
                    try deleteModel()
                    try saveContext(modelContext)
                } catch let databaseError {
                    modelContext.rollback()
                    ChekinanaGalleryMediaStore.recordRestoreRecovery(
                        staged,
                        directory: managedDirectory,
                        defaults: defaults
                    )
                    let deferred = ChekinanaGalleryDeletionRecoveryCoordinator
                        .recoverExclusively(
                            in: modelContext,
                            directory: managedDirectory,
                            fileManager: fileManager
                        )
                    guard deferred == 0 else {
                        throw ChekinanaGalleryMediaStoreError.fileOperation(
                            ChekinanaL10n.message("\(databaseError.localizedDescription) Media recovery is pending.")
                        )
                    }
                    ChekinanaGalleryMediaStore.removeRestoreRecovery(
                        staged,
                        defaults: defaults
                    )
                    throw databaseError
                }

                ChekinanaGalleryMediaStore.recordCommittedDeletion(
                    staged,
                    directory: managedDirectory,
                    defaults: defaults
                )
                // A committed model delete is success even if filesystem
                // cleanup must resume on the next launch. Its journal and
                // legacy queue remain durable until convergence.
                _ = ChekinanaGalleryDeletionRecoveryCoordinator
                    .recoverExclusively(
                        in: modelContext,
                        directory: managedDirectory,
                        fileManager: fileManager
                    )
            }
        }
    }

    static func recoverPending(
        _ files: [(original: URL, quarantine: URL)],
        in modelContext: ModelContext,
        defaults: UserDefaults = .standard,
        fileManager: FileManager = .default
    ) async throws {
        guard let directory = files.first?.original.deletingLastPathComponent()
                .standardizedFileURL else { return }
        try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                in: modelContext, directory: directory
            )
            try ChekinanaPersistenceMutationCoordinator.withLock {
                try ChekinanaChekiEditRecovery.requireConvergedExclusively(
                    in: modelContext,
                    directory: directory,
                    fileManager: fileManager
                )
                let generation = try ChekinanaLibraryGenerationStore.ensureCurrent(
                    in: modelContext
                )
                let operationIDs = Set(files.compactMap {
                    ChekinanaGalleryDeletionJournalStore.operationID(
                        fromQuarantineFilename: $0.quarantine.lastPathComponent
                    )
                })
                let hasDurableJournal = try operationIDs.contains { operationID in
                    try ChekinanaGalleryDeletionJournalStore.load(
                        operationID: operationID,
                        in: directory,
                        fileManager: fileManager
                    ) != nil
                }
                if hasDurableJournal {
                    guard ChekinanaGalleryDeletionRecoveryCoordinator
                        .recoverExclusively(
                            in: modelContext,
                            directory: directory,
                            fileManager: fileManager
                        ) == 0 else {
                        throw ChekinanaImportTransactionError.incomplete
                    }
                } else {
                    let snapshot = try ChekinanaLibraryFileReferenceSnapshot.capture(
                        in: ModelContext(modelContext.container),
                        directory: directory
                    )
                    guard snapshot.generation == generation,
                          files.allSatisfy({ pair in
                              pair.original.deletingLastPathComponent()
                                .standardizedFileURL == directory
                                  && pair.quarantine.deletingLastPathComponent()
                                    .standardizedFileURL == directory
                                  && snapshot.referencedFilenames.contains(
                                    pair.original.lastPathComponent
                                  )
                          }) else {
                        throw ChekinanaImportTransactionError.indeterminate
                    }
                    try ChekinanaGalleryMediaStore.restoreStagedFiles(
                        files,
                        fileManager: fileManager
                    )
                }
                ChekinanaGalleryMediaStore.removeRestoreRecovery(
                    files,
                    defaults: defaults
                )
            }
        }
    }
}

/// Coordinates import reconciliation and ordinary journal cleanup. Every
/// filesystem deletion is performed under the shared mutation gate and the
/// persistence mutation lock, after a fresh generation/reference/identity
/// check. A failed check leaves both the file and its queue entry for retry.
@MainActor
enum ChekinanaLibraryQueueReconciler {
    private static let logger = Logger(
        subsystem: Bundle.main.bundleIdentifier ?? "Chekinana",
        category: "LibraryQueueReconciliation"
    )

    static func reconcileImportRecoveryExclusively(
        direction: ChekinanaImportRecoveryDirection,
        expectedGeneration: UUID,
        in modelContext: ModelContext,
        directory: URL,
        defaults: UserDefaults = .standard
    ) throws -> ChekinanaLibraryQueueCleanupReport {
        guard direction == .completeNew else {
            // A failed import restored the old generation, whose pending
            // restore work is still authoritative.
            return ChekinanaLibraryQueueCleanupReport()
        }
        return try reconcileCommittedImportExclusively(
            expectedGeneration: expectedGeneration,
            in: modelContext,
            directory: directory,
            defaults: defaults
        )
    }

    static func reconcileCommittedImportExclusively(
        expectedGeneration: UUID,
        in modelContext: ModelContext,
        directory: URL,
        defaults: UserDefaults = .standard
    ) throws -> ChekinanaLibraryQueueCleanupReport {
        let snapshot = try ChekinanaLibraryFileReferenceSnapshot.capture(
            in: ModelContext(modelContext.container),
            directory: directory,
            requireEveryReferencedFile: true
        )
        guard snapshot.generation == expectedGeneration else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        var report = ChekinanaLibraryQueueCleanupReport()
        report.deferredActionCount += ChekinanaGalleryMediaStore
            .reconcileAfterCommittedImport(
                referencedFilenames: snapshot.referencedFilenames,
                defaults: defaults
            )
        report.deferredActionCount += ChekinanaEventMediaJournal
            .reconcileAfterCommittedImport(
                referencedRefs: snapshot.referencedFilenames,
                defaults: defaults
            )
        reportIfNeeded(report)
        return report
    }

    static func cleanupOrdinaryQueues(
        in modelContext: ModelContext,
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        recoverEventPending: Bool = true
    ) async -> ChekinanaLibraryQueueCleanupReport {
        let report = await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            cleanupOrdinaryQueuesExclusively(
                in: modelContext,
                directory: directory,
                defaults: defaults,
                recoverEventPending: recoverEventPending
            )
        }
        return report
    }

    /// Exposed internally for the import path (which already owns the shared
    /// gate) and focused fault-injection tests.
    static func cleanupOrdinaryQueuesExclusively(
        in modelContext: ModelContext,
        directory: URL? = nil,
        defaults: UserDefaults = .standard,
        recoverEventPending: Bool = true,
        additionalProtectedFilenames: Set<String> = [],
        beforeCandidateValidation: () -> Void = {},
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        },
        moveItem: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        }
    ) -> ChekinanaLibraryQueueCleanupReport {
        var report = ChekinanaLibraryQueueCleanupReport()
        defer { reportIfNeeded(report) }
        let resolvedDirectory: URL
        do {
            resolvedDirectory = try directory
                ?? ChekiImageRefResolver.chekiImagesDirectory()
            do {
                try ChekinanaLibraryMutationPreflight.requireImportConvergedExclusively(
                    in: modelContext, directory: resolvedDirectory
                )
            } catch {
                report.blockedByImportTransaction = true
                report.deferredActionCount = 1
                return report
            }
            let unfinished = try ChekinanaImportTransactionHandle.discover(
                in: resolvedDirectory
            )
            guard unfinished.isEmpty else {
                report.blockedByImportTransaction = true
                return report
            }
            _ = try ChekinanaPersistenceMutationCoordinator.withLock {
                try ChekinanaLibraryGenerationStore.ensureCurrent(in: modelContext)
            }
        } catch {
            report.deferredActionCount = 1
            return report
        }

        let memoryDeletionRecovery =
            ChekinanaMemoryAttachmentDeletionCoordinator.recoverExclusively(
                in: modelContext,
                directory: resolvedDirectory,
                beforeCandidateValidation: { _ in beforeCandidateValidation() },
                removeItem: removeItem
            )
        guard memoryDeletionRecovery == 0 else {
            // A legacy orphan queue may name the same public file. Do not let
            // it bypass the Memory journal's generation/lease/identity checks.
            report.deferredActionCount += memoryDeletionRecovery
            return report
        }

        let deletionRecovery = ChekinanaGalleryDeletionRecoveryCoordinator
            .recoverExclusively(
                in: modelContext,
                directory: resolvedDirectory,
                moveItem: moveItem,
                removeItem: removeItem
            )
        guard deletionRecovery == 0 else {
            // Do not let legacy orphan/committed cleanup steal either side of
            // a deletion conflict that still owns a durable journal.
            report.deferredActionCount += deletionRecovery
            return report
        }

        let initial: ChekinanaLibraryFileReferenceSnapshot
        do {
            initial = try ChekinanaLibraryFileReferenceSnapshot.capture(
                in: ModelContext(modelContext.container),
                directory: resolvedDirectory
            )
        } catch {
            report.deferredActionCount = 1
            return report
        }

        func latestSnapshot() throws -> ChekinanaLibraryFileReferenceSnapshot {
            try ChekinanaLibraryFileReferenceSnapshot.capture(
                in: ModelContext(modelContext.container),
                directory: resolvedDirectory
            )
        }
        func removeCandidate(
            _ url: URL,
            protectedReference: String?,
            expectedIdentity: ChekinanaImportFileIdentity
        ) -> Bool {
            // A full-clear journal may have observed a symlink, directory, or
            // changed-identity conflict at this name. Preserve the object but
            // retire the stale legacy queue intent so retries can converge.
            if additionalProtectedFilenames.contains(url.lastPathComponent) {
                return true
            }
            do {
                return try ChekinanaPersistenceMutationCoordinator.withLock {
                    beforeCandidateValidation()
                    let latest = try latestSnapshot()
                    let values = try url.resourceValues(
                        forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                    )
                    guard url.standardizedFileURL.deletingLastPathComponent()
                            == resolvedDirectory.standardizedFileURL,
                          values.isRegularFile == true,
                          values.isSymbolicLink != true,
                          latest.generation == initial.generation,
                          !latest.referencedFilenames.contains(url.lastPathComponent),
                          !ChekinanaMemoryAttachmentLeaseRegistry.isLeased(
                            filename: url.lastPathComponent,
                            generation: latest.generation
                          ),
                          protectedReference.map({
                            !latest.referencedFilenames.contains($0)
                          }) ?? true,
                          try ChekinanaImportFileIdentity.inspect(url)
                            == expectedIdentity else {
                        return false
                    }
                    try removeItem(url)
                    return !FileManager.default.fileExists(atPath: url.path)
                }
            } catch {
                return false
            }
        }
        func restoreCandidate(
            _ source: URL,
            destination: URL,
            requiredReference: String,
            expectedIdentity: ChekinanaImportFileIdentity
        ) -> Bool {
            do {
                return try ChekinanaPersistenceMutationCoordinator.withLock {
                    beforeCandidateValidation()
                    let latest = try latestSnapshot()
                    let values = try source.resourceValues(
                        forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                    )
                    guard source.standardizedFileURL.deletingLastPathComponent()
                            == resolvedDirectory.standardizedFileURL,
                          destination.standardizedFileURL.deletingLastPathComponent()
                            == resolvedDirectory.standardizedFileURL,
                          values.isRegularFile == true,
                          values.isSymbolicLink != true,
                          latest.generation == initial.generation,
                          latest.referencedFilenames.contains(requiredReference),
                          !latest.referencedFilenames.contains(source.lastPathComponent),
                          !FileManager.default.fileExists(atPath: destination.path),
                          try ChekinanaImportFileIdentity.inspect(source)
                            == expectedIdentity else {
                        return false
                    }
                    try moveItem(source, destination)
                    guard !FileManager.default.fileExists(atPath: source.path) else {
                        return false
                    }
                    return try ChekinanaImportFileIdentity.inspect(destination)
                        == expectedIdentity
                }
            } catch {
                return false
            }
        }

        report.deferredActionCount += ChekinanaGalleryMediaStore.cleanupSafely(
            referencedFilenames: initial.referencedFilenames,
            directory: resolvedDirectory,
            defaults: defaults,
            removeCandidate: { url, protectedReference, identity in
                removeCandidate(
                    url,
                    protectedReference: protectedReference,
                    expectedIdentity: identity
                )
            },
            restoreCandidate: { source, destination, reference, identity in
                restoreCandidate(
                    source,
                    destination: destination,
                    requiredReference: reference,
                    expectedIdentity: identity
                )
            }
        )
        report.deferredActionCount += ChekinanaEventMediaJournal.cleanupSafely(
            referencedRefs: initial.referencedFilenames,
            directory: resolvedDirectory,
            defaults: defaults,
            includePending: recoverEventPending,
            removeCandidate: { url, reference, identity in
                removeCandidate(
                    url,
                    protectedReference: reference,
                    expectedIdentity: identity
                )
            }
        )
        report.deferredActionCount += ChekinanaIdolAvatarCleanupQueue.cleanupSafely(
            referencedFilenames: initial.referencedFilenames,
            currentGeneration: initial.generation,
            directory: resolvedDirectory,
            defaults: defaults,
            removeCandidate: { url, entry in
                guard !additionalProtectedFilenames.contains(
                    url.lastPathComponent
                ) else { return false }
                return removeCandidate(
                    url,
                    protectedReference: entry.imageRef,
                    expectedIdentity: entry.identity
                )
            }
        )
        return report
    }

    private static func reportIfNeeded(
        _ report: ChekinanaLibraryQueueCleanupReport
    ) {
        guard report.needsRetry else { return }
        if report.blockedByImportTransaction {
            logger.error("Media queue cleanup deferred for unfinished import recovery")
        } else {
            logger.error(
                "Media queue cleanup deferred actions: \(report.deferredActionCount, privacy: .public)"
            )
        }
    }
}

struct ChekinanaImportTransactionHandle: Sendable {
    static let directoryPrefix = ".backup-import-transaction-"
    static let initializationDirectoryPrefix = ".backup-import-initializing-"
    static let journalFilename = "journal.json"
    static let rollbackDirectoryName = "rollback"
    static let scratchDirectoryName = "scratch"

    enum InitializationCheckpoint: CaseIterable, Sendable {
        case rootCreated
        case rollbackCreated
        case scratchCreated
        case beforeJournalWrite
        case journalWritten
        case beforePublication
        case published
    }

    struct InitializationCleanupReport: Equatable, Sendable {
        var retired = 0
        var retained = 0
        var enumerationFailed = false
    }

    let managedDirectory: URL
    let rootDirectory: URL
    var identityCache: ChekinanaImportIdentityCache? = nil

    var journalURL: URL {
        rootDirectory.appendingPathComponent(Self.journalFilename)
    }

    var rollbackDirectory: URL {
        rootDirectory.appendingPathComponent(Self.rollbackDirectoryName, isDirectory: true)
    }

    var scratchDirectory: URL {
        rootDirectory.appendingPathComponent(Self.scratchDirectoryName, isDirectory: true)
    }

    static func create(
        in managedDirectory: URL,
        oldGeneration: UUID,
        newGeneration: UUID,
        language: ChekinanaAppLanguage,
        theme: ChekinanaThemeOption,
        hiddenIdolIDs: Set<UUID>,
        preexistingFiles: Set<URL>,
        identityCache: ChekinanaImportIdentityCache? = nil,
        fileManager: FileManager = .default,
        createDirectory: ((URL) throws -> Void)? = nil,
        initializationCheckpoint: ((InitializationCheckpoint, URL) throws -> Void)? = nil,
        publishDirectory: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        }
    ) throws -> Self {
        _ = retireUnpublishedInitializations(in: managedDirectory, fileManager: fileManager)
        guard oldGeneration != newGeneration,
              try discover(in: managedDirectory, fileManager: fileManager).isEmpty else {
            throw ChekinanaImportTransactionError.incomplete
        }
        let transactionID = UUID()
        let root = managedDirectory.appendingPathComponent(
            "\(directoryPrefix)\(transactionID.uuidString.lowercased())",
            isDirectory: true
        )
        let initializationRoot = managedDirectory.appendingPathComponent(
            "\(initializationDirectoryPrefix)\(transactionID.uuidString.lowercased())",
            isDirectory: true
        )
        let preparing = Self(
            managedDirectory: managedDirectory,
            rootDirectory: initializationRoot,
            identityCache: identityCache
        )
        let makeDirectory = createDirectory ?? { url in
            try fileManager.createDirectory(at: url, withIntermediateDirectories: false)
        }
        do {
            try makeDirectory(initializationRoot)
            try initializationCheckpoint?(.rootCreated, initializationRoot)
            try makeDirectory(preparing.rollbackDirectory)
            try initializationCheckpoint?(.rollbackCreated, initializationRoot)
            try makeDirectory(preparing.scratchDirectory)
            try initializationCheckpoint?(.scratchCreated, initializationRoot)
            let sorted = preexistingFiles.sorted {
                $0.lastPathComponent < $1.lastPathComponent
            }
            var oldFiles: [ChekinanaImportTransactionJournal.OldFile] = []
            oldFiles.reserveCapacity(sorted.count)
            for (index, original) in sorted.enumerated() {
                try Task.checkCancellation()
                guard original.deletingLastPathComponent().standardizedFileURL
                        == managedDirectory.standardizedFileURL,
                      validFilename(original.lastPathComponent) else {
                    throw ChekinanaImportTransactionError.indeterminate
                }
                oldFiles.append(.init(
                    originalName: original.lastPathComponent,
                    rollbackName: "\(String(format: "%08d", index))-\(original.lastPathComponent)",
                    identity: try identityCache?.identity(original) ?? ChekinanaImportFileIdentity.inspect(original)
                ))
            }
            let journal = ChekinanaImportTransactionJournal(
                formatVersion: 1,
                transactionID: transactionID,
                oldGeneration: oldGeneration,
                newGeneration: newGeneration,
                phase: .stagingOld,
                settings: .init(
                    language: language.rawValue,
                    theme: theme.rawValue,
                    hiddenIdolIDs: hiddenIdolIDs.map(\.uuidString).map {
                        $0.lowercased()
                    }.sorted()
                ),
                oldFiles: oldFiles,
                createdFiles: []
            )
            try initializationCheckpoint?(.beforeJournalWrite, initializationRoot)
            try preparing.write(journal)
            guard try JSONDecoder().decode(
                ChekinanaImportTransactionJournal.self,
                from: Data(contentsOf: preparing.journalURL)
            ) == journal else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            try preparing.validateOwnedTree(journal, fileManager: fileManager)
            try initializationCheckpoint?(.journalWritten, initializationRoot)
            try initializationCheckpoint?(.beforePublication, initializationRoot)
            // Both paths are siblings. The transaction becomes discoverable
            // only after its complete, synchronized v1 journal exists.
            try publishDirectory(initializationRoot, root)
            let handle = Self(managedDirectory: managedDirectory, rootDirectory: root, identityCache: identityCache)
            guard try handle.load() == journal else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            try initializationCheckpoint?(.published, root)
            return handle
        } catch {
            // No source byte is ever moved into an unpublished directory.
            // Retire only verified preparation metadata and empty directories.
            // Unknown entries are retained and never recursively deleted.
            _ = try? preparing.retireUnpublishedInitialization(fileManager: fileManager)
            throw error
        }
    }

    /// Unpublished roots cannot have received managed source bytes from this
    /// protocol. A cleanup failure retains the evidence but must not prevent
    /// the current, usable library from opening.
    static func retireUnpublishedInitializations(
        in managedDirectory: URL,
        fileManager: FileManager = .default
    ) -> InitializationCleanupReport {
        var report = InitializationCleanupReport()
        let entries: [URL]
        do {
            entries = try fileManager.contentsOfDirectory(
                at: managedDirectory,
                includingPropertiesForKeys: [.isDirectoryKey, .isSymbolicLinkKey]
            )
        } catch {
            report.enumerationFailed = true
            return report
        }
        for entry in entries
        where entry.lastPathComponent.hasPrefix(initializationDirectoryPrefix) {
            let handle = Self(managedDirectory: managedDirectory, rootDirectory: entry)
            do {
                if try handle.retireUnpublishedInitialization(fileManager: fileManager) {
                    report.retired += 1
                } else {
                    report.retained += 1
                }
            } catch {
                report.retained += 1
            }
        }
        return report
    }

    @discardableResult
    func retireUnpublishedInitialization(
        fileManager: FileManager = .default,
        listDirectory: ((URL) throws -> [URL])? = nil
    ) throws -> Bool {
        try retireUnstartedRoot(
            allowingInitializationJournal: true,
            fileManager: fileManager,
            listDirectory: listDirectory
        )
    }

    /// Older builds could expose this directory before writing any journal.
    /// An absent journal alone proves nothing: retire only known empty child
    /// directories. rmdir also refuses a new entry that appears after checking.
    @discardableResult
    func retireUnjournalledEmptyRoot(
        fileManager: FileManager = .default,
        listDirectory: ((URL) throws -> [URL])? = nil
    ) throws -> Bool {
        try retireUnstartedRoot(
            allowingInitializationJournal: false,
            fileManager: fileManager,
            listDirectory: listDirectory
        )
    }

    private func retireUnstartedRoot(
        allowingInitializationJournal: Bool,
        fileManager: FileManager,
        listDirectory: ((URL) throws -> [URL])?
    ) throws -> Bool {
        let expectedPrefix = allowingInitializationJournal
            ? Self.initializationDirectoryPrefix : Self.directoryPrefix
        guard rootDirectory.deletingLastPathComponent().standardizedFileURL
                == managedDirectory.standardizedFileURL,
              rootDirectory.lastPathComponent.hasPrefix(expectedPrefix),
              UUID(uuidString: String(
                rootDirectory.lastPathComponent.dropFirst(expectedPrefix.count)
              )) != nil else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let list = listDirectory ?? { url in
            try fileManager.contentsOfDirectory(
                at: url,
                includingPropertiesForKeys: [.isDirectoryKey, .isSymbolicLinkKey]
            )
        }
        let rootValues = try rootDirectory.resourceValues(
            forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        )
        guard rootValues.isDirectory == true, rootValues.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let entries = try list(rootDirectory)
        let hasJournal = entries.contains(where: { $0.lastPathComponent == Self.journalFilename })
        if hasJournal && !allowingInitializationJournal {
            return false
        }
        let allowed = Set([Self.rollbackDirectoryName, Self.scratchDirectoryName])
        var emptyDirectories: [URL] = []
        for entry in entries {
            guard entry.deletingLastPathComponent().standardizedFileURL
                    == rootDirectory.standardizedFileURL else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            if allowingInitializationJournal && entry.lastPathComponent == Self.journalFilename {
                continue
            }
            guard allowed.contains(entry.lastPathComponent) else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            let values = try entry.resourceValues(
                forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
            )
            guard values.isDirectory == true, values.isSymbolicLink != true,
                  try list(entry).isEmpty else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            emptyDirectories.append(entry)
        }
        if hasJournal {
            guard Set(emptyDirectories.map(\.lastPathComponent)) == allowed else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            let journal = try load(directoryPrefix: Self.initializationDirectoryPrefix)
            guard journal.phase == .stagingOld, journal.createdFiles.isEmpty else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            guard journalURL.withUnsafeFileSystemRepresentation({ path in
                path.map { Darwin.unlink($0) } == 0
            }) else {
                throw ChekinanaImportTransactionError.incomplete
            }
        }
        for entry in emptyDirectories {
            guard entry.withUnsafeFileSystemRepresentation({ path in
                path.map { Darwin.rmdir($0) } == 0
            }) else {
                throw ChekinanaImportTransactionError.incomplete
            }
        }
        guard rootDirectory.withUnsafeFileSystemRepresentation({ path in
            path.map { Darwin.rmdir($0) } == 0
        }) else {
            throw ChekinanaImportTransactionError.incomplete
        }
        return true
    }

    static func discover(
        in managedDirectory: URL,
        fileManager: FileManager = .default
    ) throws -> [Self] {
        guard fileManager.fileExists(atPath: managedDirectory.path) else { return [] }
        let values = try fileManager.contentsOfDirectory(
            at: managedDirectory,
            includingPropertiesForKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        )
        return try values.compactMap { value in
            guard value.lastPathComponent.hasPrefix(directoryPrefix) else { return nil }
            let suffix = String(value.lastPathComponent.dropFirst(directoryPrefix.count))
            guard UUID(uuidString: suffix) != nil else { return nil }
            let attributes = try value.resourceValues(
                forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
            )
            guard attributes.isDirectory == true, attributes.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            return Self(
                managedDirectory: managedDirectory.standardizedFileURL,
                rootDirectory: value.standardizedFileURL
            )
        }.sorted { $0.rootDirectory.lastPathComponent < $1.rootDirectory.lastPathComponent }
    }

    func load() throws -> ChekinanaImportTransactionJournal {
        try load(directoryPrefix: Self.directoryPrefix)
    }

    private func load(directoryPrefix: String) throws -> ChekinanaImportTransactionJournal {
        let journal: ChekinanaImportTransactionJournal
        do {
            let values = try journalURL.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            )
            guard values.isRegularFile == true, values.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            journal = try JSONDecoder().decode(
                ChekinanaImportTransactionJournal.self,
                from: Data(contentsOf: journalURL, options: [.mappedIfSafe])
            )
        } catch {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let suffix = String(rootDirectory.lastPathComponent.dropFirst(directoryPrefix.count))
        guard rootDirectory.lastPathComponent.hasPrefix(directoryPrefix),
              journal.formatVersion == 1,
              journal.transactionID == UUID(uuidString: suffix),
              journal.oldGeneration != journal.newGeneration,
              Set(journal.oldFiles.map(\.originalName)).count == journal.oldFiles.count,
              Set(journal.oldFiles.map(\.rollbackName)).count == journal.oldFiles.count,
              Set(journal.createdFiles.map(\.filename)).count == journal.createdFiles.count,
              journal.oldFiles.allSatisfy({
                  Self.validFilename($0.originalName)
                    && Self.validFilename($0.rollbackName)
                    && $0.identity.isValid
              }),
              journal.createdFiles.allSatisfy({
                  Self.validFilename($0.filename) && $0.identity.isValid
              }) else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        return journal
    }

    func stageOldFiles(
        fileManager: FileManager = .default,
        moveItem: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        }
    ) throws {
        let journal = try load()
        for file in journal.oldFiles {
            try Task.checkCancellation()
            let original = managedDirectory.appendingPathComponent(file.originalName)
            let rollback = rollbackDirectory.appendingPathComponent(file.rollbackName)
            guard try existingIdentity(at: original, fileManager: fileManager)
                    == file.identity,
                  try existingIdentity(at: rollback, fileManager: fileManager) == nil else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            do {
                try moveItem(original, rollback)
            } catch {
                throw ChekinanaImportTransactionError.incomplete
            }
            guard try existingIdentity(at: rollback, fileManager: fileManager)
                    == file.identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }
        try updatePhase(.materializingNew)
    }

    func reserveCreatedFiles(
        _ files: [ChekinanaImportTransactionJournal.CreatedFile],
        fileManager: FileManager = .default
    ) throws {
        guard !files.isEmpty,
              files.allSatisfy({ Self.validFilename($0.filename) && $0.identity.isValid }),
              Set(files.map(\.filename)).count == files.count else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        var journal = try load()
        let existing = Set(journal.createdFiles.map(\.filename))
        guard files.allSatisfy({ !existing.contains($0.filename) }) else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        for file in files {
            let destination = managedDirectory.appendingPathComponent(file.filename)
            guard try existingIdentity(at: destination, fileManager: fileManager) == nil else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }
        journal.createdFiles.append(contentsOf: files)
        try write(journal)
    }

    func materialize(
        from source: URL,
        as filename: String,
        fileManager: FileManager = .default
    ) throws {
        let journal = try load()
        guard let record = journal.createdFiles.first(where: { $0.filename == filename }),
              try inspectIdentity(source) == record.identity else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let scratch = scratchDirectory.appendingPathComponent(UUID().uuidString.lowercased())
        let destination = managedDirectory.appendingPathComponent(filename)
        guard try existingIdentity(at: destination, fileManager: fileManager) == nil else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        do {
            do {
                try fileManager.linkItem(at: source, to: scratch)
            } catch {
                try fileManager.copyItem(at: source, to: scratch)
            }
            guard try inspectIdentity(scratch) == record.identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            try fileManager.moveItem(at: scratch, to: destination)
            guard try existingIdentity(at: destination, fileManager: fileManager)
                    == record.identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        } catch let error as ChekinanaImportTransactionError {
            try? fileManager.removeItem(at: scratch)
            throw error
        } catch {
            try? fileManager.removeItem(at: scratch)
            throw ChekinanaImportTransactionError.incomplete
        }
    }

    func materialize(
        _ data: Data,
        as filename: String,
        fileManager: FileManager = .default
    ) throws {
        let journal = try load()
        let identity = ChekinanaImportFileIdentity(data)
        guard journal.createdFiles.contains(where: {
            $0.filename == filename && $0.identity == identity
        }) else {
            throw ChekinanaImportTransactionError.invalidJournal
        }
        let scratch = scratchDirectory.appendingPathComponent(UUID().uuidString.lowercased())
        let destination = managedDirectory.appendingPathComponent(filename)
        guard try existingIdentity(at: destination, fileManager: fileManager) == nil else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        do {
            try data.write(to: scratch)
            guard try inspectIdentity(scratch) == identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            try fileManager.moveItem(at: scratch, to: destination)
            guard try existingIdentity(at: destination, fileManager: fileManager)
                    == identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        } catch let error as ChekinanaImportTransactionError {
            try? fileManager.removeItem(at: scratch)
            throw error
        } catch {
            try? fileManager.removeItem(at: scratch)
            throw ChekinanaImportTransactionError.incomplete
        }
    }

    func updatePhase(_ phase: ChekinanaImportTransactionJournal.Phase) throws {
        var journal = try load()
        journal.phase = phase
        try write(journal)
    }

    @discardableResult
    func recover(
        currentGeneration: UUID?,
        fileManager: FileManager = .default,
        moveItem: (URL, URL) throws -> Void = {
            try FileManager.default.moveItem(at: $0, to: $1)
        },
        removeItem: (URL) throws -> Void = {
            try FileManager.default.removeItem(at: $0)
        }
    ) throws -> ChekinanaImportRecoveryDirection {
        let journal = try load()
        let direction = try ChekinanaImportRecoveryDirection.resolve(
            oldGeneration: journal.oldGeneration,
            newGeneration: journal.newGeneration,
            currentGeneration: currentGeneration
        )
        switch direction {
        case .restoreOld:
            try restoreOld(
                journal,
                fileManager: fileManager,
                moveItem: moveItem,
                removeItem: removeItem
            )
        case .completeNew:
            try completeNew(
                journal,
                fileManager: fileManager,
                removeItem: removeItem
            )
        }
        try validateOwnedTree(journal, fileManager: fileManager)
        try Self.removeAndVerify(
            rootDirectory,
            fileManager: fileManager,
            removeItem: removeItem
        )
        return direction
    }

    private func restoreOld(
        _ journal: ChekinanaImportTransactionJournal,
        fileManager: FileManager,
        moveItem: (URL, URL) throws -> Void,
        removeItem: (URL) throws -> Void
    ) throws {
        let createdByName = Dictionary(
            uniqueKeysWithValues: journal.createdFiles.map { ($0.filename, $0.identity) }
        )
        let oldNames = Set(journal.oldFiles.map(\.originalName))

        // Validate the whole old-side plan before deleting or moving a byte.
        for old in journal.oldFiles {
            let original = managedDirectory.appendingPathComponent(old.originalName)
            let rollback = rollbackDirectory.appendingPathComponent(old.rollbackName)
            let originalIdentity = try existingIdentity(
                at: original,
                fileManager: fileManager
            )
            let rollbackIdentity = try existingIdentity(
                at: rollback,
                fileManager: fileManager
            )
            guard originalIdentity == old.identity || rollbackIdentity == old.identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            if let rollbackIdentity, rollbackIdentity != old.identity {
                throw ChekinanaImportTransactionError.indeterminate
            }
            if let originalIdentity, originalIdentity != old.identity,
               createdByName[old.originalName] != originalIdentity {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }
        for created in journal.createdFiles where !oldNames.contains(created.filename) {
            let url = managedDirectory.appendingPathComponent(created.filename)
            if let identity = try existingIdentity(at: url, fileManager: fileManager),
               identity != created.identity {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }

        for old in journal.oldFiles.reversed() {
            let original = managedDirectory.appendingPathComponent(old.originalName)
            let rollback = rollbackDirectory.appendingPathComponent(old.rollbackName)
            let originalIdentity = try existingIdentity(
                at: original,
                fileManager: fileManager
            )
            let rollbackIdentity = try existingIdentity(
                at: rollback,
                fileManager: fileManager
            )
            if originalIdentity == old.identity {
                if rollbackIdentity == old.identity {
                    try Self.removeAndVerify(
                        rollback,
                        fileManager: fileManager,
                        removeItem: removeItem
                    )
                }
                continue
            }
            if originalIdentity != nil {
                try Self.removeAndVerify(
                    original,
                    fileManager: fileManager,
                    removeItem: removeItem
                )
            }
            guard rollbackIdentity == old.identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
            do { try moveItem(rollback, original) } catch {
                throw ChekinanaImportTransactionError.incomplete
            }
            guard try existingIdentity(at: original, fileManager: fileManager)
                    == old.identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }
        for created in journal.createdFiles where !oldNames.contains(created.filename) {
            let url = managedDirectory.appendingPathComponent(created.filename)
            if try existingIdentity(at: url, fileManager: fileManager) == created.identity {
                try Self.removeAndVerify(
                    url,
                    fileManager: fileManager,
                    removeItem: removeItem
                )
            }
        }
    }

    private func completeNew(
        _ journal: ChekinanaImportTransactionJournal,
        fileManager: FileManager,
        removeItem: (URL) throws -> Void
    ) throws {
        let createdNames = Set(journal.createdFiles.map(\.filename))

        // A committed DB generation may discard old bytes only after every
        // journalled new byte is present with the pre-commit hash.
        for created in journal.createdFiles {
            let url = managedDirectory.appendingPathComponent(created.filename)
            guard try existingIdentity(at: url, fileManager: fileManager)
                    == created.identity else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }
        for old in journal.oldFiles {
            let rollback = rollbackDirectory.appendingPathComponent(old.rollbackName)
            if let identity = try existingIdentity(at: rollback, fileManager: fileManager),
               identity != old.identity {
                throw ChekinanaImportTransactionError.indeterminate
            }
            guard !createdNames.contains(old.originalName) else { continue }
            let original = managedDirectory.appendingPathComponent(old.originalName)
            if let identity = try existingIdentity(at: original, fileManager: fileManager),
               identity != old.identity {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }

        for old in journal.oldFiles {
            let rollback = rollbackDirectory.appendingPathComponent(old.rollbackName)
            if try existingIdentity(at: rollback, fileManager: fileManager) == old.identity {
                try Self.removeAndVerify(
                    rollback,
                    fileManager: fileManager,
                    removeItem: removeItem
                )
            }
            guard !createdNames.contains(old.originalName) else { continue }
            let original = managedDirectory.appendingPathComponent(old.originalName)
            if try existingIdentity(at: original, fileManager: fileManager) == old.identity {
                try Self.removeAndVerify(
                    original,
                    fileManager: fileManager,
                    removeItem: removeItem
                )
            }
        }
    }

    private func validateOwnedTree(
        _ journal: ChekinanaImportTransactionJournal,
        fileManager: FileManager
    ) throws {
        let rootEntries = try fileManager.contentsOfDirectory(
            at: rootDirectory,
            includingPropertiesForKeys: [.isDirectoryKey, .isRegularFileKey, .isSymbolicLinkKey]
        )
        guard Set(rootEntries.map(\.lastPathComponent)) == Set([
            Self.journalFilename,
            Self.rollbackDirectoryName,
            Self.scratchDirectoryName,
        ]) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        for directory in [rollbackDirectory, scratchDirectory] {
            let values = try directory.resourceValues(
                forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
            )
            guard values.isDirectory == true, values.isSymbolicLink != true else {
                throw ChekinanaImportTransactionError.indeterminate
            }
        }
        let journalValues = try journalURL.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard journalValues.isRegularFile == true,
              journalValues.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let expectedRollbackNames = Set(journal.oldFiles.map(\.rollbackName))
        let rollbackEntries = try fileManager.contentsOfDirectory(
            at: rollbackDirectory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard rollbackEntries.allSatisfy({ entry in
            expectedRollbackNames.contains(entry.lastPathComponent)
                && ((try? entry.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                ))?.isRegularFile == true)
                && ((try? entry.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                ))?.isSymbolicLink != true)
        }) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        let scratchEntries = try fileManager.contentsOfDirectory(
            at: scratchDirectory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard scratchEntries.allSatisfy({ entry in
            UUID(uuidString: entry.lastPathComponent) != nil
                && ((try? entry.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                ))?.isRegularFile == true)
                && ((try? entry.resourceValues(
                    forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
                ))?.isSymbolicLink != true)
        }) else {
            throw ChekinanaImportTransactionError.indeterminate
        }
    }

    private func write(_ journal: ChekinanaImportTransactionJournal) throws {
        let data: Data
        do {
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.sortedKeys]
            data = try encoder.encode(journal)
            try data.write(to: journalURL, options: [.atomic])
            let handle = try FileHandle(forWritingTo: journalURL)
            try handle.synchronize()
            try handle.close()
        } catch {
            throw ChekinanaImportTransactionError.incomplete
        }
    }

    private func inspectIdentity(_ url: URL) throws -> ChekinanaImportFileIdentity {
        try identityCache?.identity(url) ?? ChekinanaImportFileIdentity.inspect(url)
    }

    private func existingIdentity(at url: URL, fileManager: FileManager) throws -> ChekinanaImportFileIdentity? {
        guard fileManager.fileExists(atPath: url.path) else { return nil }
        guard let identityCache else { return try Self.existingIdentity(at: url, fileManager: fileManager) }
        return try identityCache.identity(url)
    }

    private static func existingIdentity(
        at url: URL,
        fileManager: FileManager
    ) throws -> ChekinanaImportFileIdentity? {
        guard fileManager.fileExists(atPath: url.path) else { return nil }
        let attributes = try url.resourceValues(
            forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
        )
        guard attributes.isRegularFile == true, attributes.isSymbolicLink != true else {
            throw ChekinanaImportTransactionError.indeterminate
        }
        return try ChekinanaImportFileIdentity.inspect(url)
    }

    private static func removeAndVerify(
        _ url: URL,
        fileManager: FileManager,
        removeItem: (URL) throws -> Void
    ) throws {
        do { try removeItem(url) } catch {
            throw ChekinanaImportTransactionError.incomplete
        }
        guard !fileManager.fileExists(atPath: url.path) else {
            throw ChekinanaImportTransactionError.incomplete
        }
    }

    private static func validFilename(_ value: String) -> Bool {
        value == URL(fileURLWithPath: value).lastPathComponent
            && value != "." && value != ".." && !value.isEmpty
    }
}

enum ChekinanaDataImporter {
    typealias SaveContext = (ModelContext) throws -> Void

    private struct ParsedSettings {
        let language: ChekinanaAppLanguage
        let theme: ChekinanaThemeOption
        let hiddenIdolIDs: Set<UUID>
    }

    static func prepare(from sourceURL: URL) async throws -> ChekinanaPreparedDataImport {
        let worker = Task.detached(priority: .userInitiated) {
            let identityCache = ChekinanaImportIdentityCache()
            let extracted = try ChekinanaStoredBackupReader.extract(
                sourceURL, reusing: try? ChekiImageRefResolver.chekiImagesDirectory(),
                identityCache: identityCache
            )
            guard let manifestFile = extracted["manifest.json"],
                  let dataFile = extracted["data.json"],
                  let settingsFile = extracted["settings.json"] else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let temporaryDirectory = manifestFile.url.deletingLastPathComponent()
            var transferred = false
            defer {
                if !transferred {
                    try? FileManager.default.removeItem(at: temporaryDirectory)
                }
            }
            let decoder = JSONDecoder()
            let manifest: ChekinanaDataImportManifest
            let payload: ChekinanaDataImportPayload
            do {
                manifest = try decoder.decode(
                    ChekinanaDataImportManifest.self,
                    from: try Data(contentsOf: manifestFile.url, options: [.mappedIfSafe])
                )
                payload = try decoder.decode(
                    ChekinanaDataImportPayload.self,
                    from: try Data(contentsOf: dataFile.url, options: [.mappedIfSafe])
                )
            } catch {
                throw ChekinanaDataImportError.invalidArchive
            }
            guard manifest.format == "chekinana-backup",
                  manifest.exportVersion == 1,
                  ["15.0.0", "16.0.0", "17.0.0"].contains(manifest.schemaVersion),
                  payload.schemaVersion == manifest.schemaVersion else {
                throw ChekinanaDataImportError.unsupportedVersion
            }
            let expectedCounts = manifest.schemaVersion == "15.0.0"
                ? payload.entities.counts.filter { $0.key != "CustomChekiSize" }
                : payload.entities.counts
            guard manifest.entityCounts == expectedCounts else {
                throw ChekinanaDataImportError.invalidArchive
            }
            if manifest.schemaVersion != "15.0.0",
               payload.entities.chekiRecords.contains(where: { $0.size == nil }) {
                throw ChekinanaDataImportError.invalidArchive
            }
            let settings = try parseSettings(settingsFile.url)
            try validateEntities(
                payload.entities,
                schemaVersion: payload.schemaVersion
            )
            let mediaByOwner = try validatedMedia(
                manifest.media,
                extracted: extracted,
                entities: payload.entities
            )
            guard settings.hiddenIdolIDs.isSubset(of: Set(payload.entities.idols.compactMap {
                UUID(uuidString: $0.id)
            })) else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            transferred = true
            return ChekinanaPreparedDataImport(
                temporaryDirectory: temporaryDirectory,
                payload: payload,
                language: settings.language,
                theme: settings.theme,
                hiddenIdolIDs: settings.hiddenIdolIDs,
                mediaByOwner: mediaByOwner,
                identityCache: identityCache
            )
        }
        return try await withTaskCancellationHandler {
            try await worker.value
        } onCancel: {
            worker.cancel()
        }
    }

    private static func parseSettings(_ url: URL) throws -> ParsedSettings {
        guard let object = try JSONSerialization.jsonObject(
            with: Data(contentsOf: url, options: [.mappedIfSafe])
        ) as? [String: Any],
        let languageRaw = object[ChekinanaLanguagePreference.defaultsKey] as? String,
        let language = ChekinanaAppLanguage(rawValue: languageRaw),
        let themeRaw = object[ChekinanaThemePreference.defaultsKey] as? String,
        let theme = ChekinanaThemeOption(rawValue: themeRaw),
        let hiddenRaw = object[ChekinanaHiddenIdolPersistence.defaultsKey] as? [String] else {
            throw ChekinanaDataImportError.invalidArchive
        }
        let hiddenIDs = hiddenRaw.compactMap(UUID.init(uuidString:))
        guard hiddenIDs.count == hiddenRaw.count,
              Set(hiddenIDs).count == hiddenIDs.count else {
            throw ChekinanaDataImportError.invalidArchive
        }
        return ParsedSettings(
            language: language,
            theme: theme,
            hiddenIdolIDs: Set(hiddenIDs)
        )
    }

    private static func validateEntities(
        _ entities: ChekinanaDataImportPayload.Entities,
        schemaVersion: String
    ) throws {
        let idolIDs = try uniqueUUIDs(entities.idols.map(\.id))
        let eventIDs = try uniqueUUIDs(entities.events.map(\.id))
        _ = try uniqueUUIDs(entities.eventImages.map(\.id))
        _ = try uniqueUUIDs(entities.travelSegments.map(\.id))
        _ = try uniqueUUIDs(entities.mediaItems.map(\.id))
        _ = try uniqueUUIDs(entities.mediaItems.map(\.mediaOwnerID))
        _ = try uniqueUUIDs(entities.chekiRecords.map(\.id))
        let memoryIDs = try uniqueUUIDs(entities.memories.map(\.id))
        _ = try uniqueUUIDs(entities.memoryAttachments.map(\.id))
        let customSizeIDs = try uniqueUUIDs(entities.customChekiSizes.map(\.id))
        guard Set(entities.idolPatternStates.compactMap { UUID(uuidString: $0.idolID) }).count
                == entities.idolPatternStates.count,
              Set(entities.eventSchedules.compactMap { UUID(uuidString: $0.eventID) }).count
                == entities.eventSchedules.count,
              Set(entities.calendarGroupOrders.map(\.id)).count
                == entities.calendarGroupOrders.count else {
            throw ChekinanaDataImportError.invalidRelationships
        }
        for value in entities.idols {
            _ = try requiredDate(value.createdAt)
            _ = try requiredDate(value.updatedAt)
            _ = try value.resolvedAvatarState(
                allowingMissingFields: schemaVersion != "17.0.0"
            )
        }
        for value in entities.idolPatternStates {
            guard let idolID = UUID(uuidString: value.idolID),
                  idolIDs.contains(idolID),
                  value.cataloguePatternCount >= 0,
                  value.cataloguePatternCount <= value.cataloguePatternIDs.count else {
                throw ChekinanaDataImportError.invalidRelationships
            }
        }
        for value in entities.events {
            _ = try contentDate(value.date)
            _ = try requiredDate(value.createdAt)
            _ = try requiredDate(value.updatedAt)
            if let url = value.weiboURL, URL(string: url) == nil {
                throw ChekinanaDataImportError.invalidArchive
            }
            if let source = value.source {
                guard let parsedSource = ChekinanaEventSource(rawValue: source),
                      parsedSource == ChekinanaEventSource.infer(
                        from: value.weiboURL.flatMap(URL.init(string:))
                      ) else {
                    throw ChekinanaDataImportError.invalidArchive
                }
            }
            if let url = value.ticketURL, URL(string: url) == nil {
                throw ChekinanaDataImportError.invalidArchive
            }
        }
        for value in entities.eventSchedules {
            guard let eventID = UUID(uuidString: value.eventID), eventIDs.contains(eventID),
                  value.openTime == nil || ChekinanaEventTime.normalized(value.openTime) != nil,
                  value.startTime == nil || ChekinanaEventTime.normalized(value.startTime) != nil else {
                throw ChekinanaDataImportError.invalidRelationships
            }
        }
        for value in entities.eventImages {
            guard let eventID = UUID(uuidString: value.eventID), eventIDs.contains(eventID),
                  value.imageRef.nonEmpty != nil,
                  value.sortOrder >= 0 else {
                throw ChekinanaDataImportError.invalidRelationships
            }
        }
        for value in entities.calendarGroupOrders {
            let componentIDs = value.groupKey == "unassigned"
                ? [] : value.groupKey.split(separator: "+").map(String.init)
            let groupIDs = componentIDs.compactMap(UUID.init(uuidString:))
            guard !ChekinanaLibraryGenerationStore.isReserved(dateKey: value.dateKey),
                  groupIDs.count == componentIDs.count,
                  groupIDs.allSatisfy(idolIDs.contains),
                  value.id == CalendarGroupOrder.key(
                    dateKey: value.dateKey,
                    groupKey: value.groupKey
                  ) else {
                throw ChekinanaDataImportError.invalidRelationships
            }
        }
        for value in entities.travelSegments {
            guard ChekinanaTravelMode(rawValue: value.mode) != nil else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let departure = try requiredDate(value.departureTime)
            let arrival = try requiredDate(value.arrivalTime)
            guard arrival >= departure else { throw ChekinanaDataImportError.invalidArchive }
            _ = try requiredDate(value.createdAt)
            _ = try requiredDate(value.updatedAt)
        }
        for value in entities.mediaItems {
            guard let kind = MediaItemKind(rawValue: value.kind),
                  value.mediaRef.nonEmpty != nil,
                  try relationships(value.idolIDs, value.eventID, idolIDs, eventIDs) else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            _ = try contentDate(value.date)
            _ = try requiredDate(value.createdAt)
            _ = try requiredDate(value.updatedAt)
            switch kind {
            case .cheki:
                guard let size = value.size.flatMap(ChekiSize.init(rawValue:)),
                      size.customID.map(customSizeIDs.contains) ?? true else {
                    throw ChekinanaDataImportError.invalidArchive
                }
            case .shame, .douga:
                guard value.size == nil, value.idx == nil else {
                    throw ChekinanaDataImportError.invalidArchive
                }
            }
        }
        for value in entities.chekiRecords {
            guard value.count > 0,
                  try relationships(value.idolIDs, value.eventID, idolIDs, eventIDs),
                  value.size == nil || value.size.flatMap(ChekiSize.init(rawValue:)).map({
                    $0.customID.map(customSizeIDs.contains) ?? true
                  }) == true else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            _ = try contentDate(value.date)
        }
        var attachmentCounts: [UUID: Int] = [:]
        for attachment in entities.memoryAttachments {
            attachmentCounts[try uuid(attachment.memoryID), default: 0] += 1
        }
        for value in entities.memories {
            guard try relationships(value.idolIDs, value.eventID, idolIDs, eventIDs),
                  let id = UUID(uuidString: value.id) else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            let date = try contentDate(value.date)
            guard ChekinanaMemoryPolicy.isValid(
                title: value.title,
                bodyText: value.bodyText,
                date: date,
                eventID: value.eventID.flatMap(UUID.init(uuidString:)),
                idolIDs: value.idolIDs.compactMap(UUID.init(uuidString:)),
                attachmentCount: attachmentCounts[id, default: 0]
            ) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            _ = try requiredDate(value.createdAt)
            _ = try requiredDate(value.updatedAt)
        }
        for value in entities.memoryAttachments {
            guard let memoryID = UUID(uuidString: value.memoryID),
                  memoryIDs.contains(memoryID),
                  MemoryAttachmentKind(rawValue: value.kind) != nil,
                  value.managedRef.nonEmpty != nil,
                  value.sortOrder >= 0 else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            _ = try requiredDate(value.createdAt)
            _ = try requiredDate(value.updatedAt)
        }
        for value in entities.customChekiSizes {
            guard let id = UUID(uuidString: value.id),
                  customSizeIDs.contains(id),
                  !value.name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                  let expected = ChekinanaCustomChekiSizePolicy.pixelDimensions(
                    widthRatio: value.widthRatio,
                    heightRatio: value.heightRatio
                  ),
                  expected.width == value.pixelWidth,
                  expected.height == value.pixelHeight else {
                throw ChekinanaDataImportError.invalidArchive
            }
            _ = try requiredDate(value.createdAt)
        }
    }

    private static func validatedMedia(
        _ media: [ChekinanaDataImportManifest.MediaValue],
        extracted: [String: ChekinanaPreparedDataImport.MediaFile],
        entities: ChekinanaDataImportPayload.Entities
    ) throws -> [ChekinanaPreparedDataImport.OwnerKey: ChekinanaPreparedDataImport.MediaFile] {
        let idols = Dictionary(uniqueKeysWithValues: try entities.idols.map {
            (try uuid($0.id), $0.avatarImageRef)
        })
        let events = Dictionary(uniqueKeysWithValues: try entities.events.map {
            (try uuid($0.id), $0.avatarImageRef)
        })
        let eventImages = Dictionary(uniqueKeysWithValues: try entities.eventImages.map {
            (try uuid($0.id), Optional($0.imageRef))
        })
        let travels = Dictionary(uniqueKeysWithValues: try entities.travelSegments.map {
            (try uuid($0.id), $0.operatorIconRef)
        })
        let mediaItems = Dictionary(uniqueKeysWithValues: try entities.mediaItems.map {
            (try uuid($0.id), Optional($0.mediaRef))
        })
        let attachments = Dictionary(uniqueKeysWithValues: try entities.memoryAttachments.map {
            (try uuid($0.id), Optional($0.managedRef))
        })
        var result: [ChekinanaPreparedDataImport.OwnerKey: ChekinanaPreparedDataImport.MediaFile] = [:]
        var archivePaths = Set<String>()
        for value in media {
            guard value.archivePath.hasPrefix("media/"),
                  archivePaths.insert(value.archivePath).inserted,
                  let file = extracted[value.archivePath],
                  file.byteCount == value.byteCount,
                  file.crc32 == value.crc32,
                  file.sha256 == value.sha256.lowercased(),
                  value.originalReference.nonEmpty != nil else {
                throw ChekinanaDataImportError.mediaIntegrity
            }
            let ownerID = try uuid(value.ownerID)
            let expectedReference: String?
            switch value.ownerType {
            case "Idol": expectedReference = idols[ownerID] ?? nil
            case "Event": expectedReference = events[ownerID] ?? nil
            case "EventImage": expectedReference = eventImages[ownerID] ?? nil
            case "TravelSegment": expectedReference = travels[ownerID] ?? nil
            case "MediaItem": expectedReference = mediaItems[ownerID] ?? nil
            case "MemoryAttachment": expectedReference = attachments[ownerID] ?? nil
            default: throw ChekinanaDataImportError.invalidArchive
            }
            guard expectedReference == value.originalReference else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            let key = ChekinanaPreparedDataImport.OwnerKey(type: value.ownerType, id: ownerID)
            guard result.updateValue(file, forKey: key) == nil else {
                throw ChekinanaDataImportError.invalidArchive
            }
        }
        let extractedMediaPaths = Set(extracted.keys.filter { $0.hasPrefix("media/") })
        guard extractedMediaPaths == archivePaths else {
            throw ChekinanaDataImportError.invalidArchive
        }
        func require(_ type: String, _ id: String, _ reference: String?) throws {
            guard reference?.nonEmpty != nil else { return }
            let key = ChekinanaPreparedDataImport.OwnerKey(type: type, id: try uuid(id))
            guard result[key] != nil else { throw ChekinanaDataImportError.mediaIntegrity }
        }
        for value in entities.idols { try require("Idol", value.id, value.avatarImageRef) }
        for value in entities.events { try require("Event", value.id, value.avatarImageRef) }
        for value in entities.eventImages { try require("EventImage", value.id, value.imageRef) }
        for value in entities.travelSegments {
            if ChekinanaTravelOperatorIcon.assetName(from: value.operatorIconRef) == nil {
                try require("TravelSegment", value.id, value.operatorIconRef)
            }
        }
        for value in entities.mediaItems { try require("MediaItem", value.id, value.mediaRef) }
        for value in entities.memoryAttachments {
            try require("MemoryAttachment", value.id, value.managedRef)
        }
        return result
    }

    private static func relationships(
        _ idolValues: [String],
        _ eventValue: String?,
        _ idolIDs: Set<UUID>,
        _ eventIDs: Set<UUID>
    ) throws -> Bool {
        let ids = idolValues.compactMap(UUID.init(uuidString:))
        guard ids.count == idolValues.count,
              Set(ids).count == ids.count,
              ids.allSatisfy(idolIDs.contains) else { return false }
        guard let eventValue else { return true }
        guard let eventID = UUID(uuidString: eventValue) else { return false }
        return eventIDs.contains(eventID)
    }

    private static func uniqueUUIDs(_ values: [String]) throws -> Set<UUID> {
        let ids = values.compactMap(UUID.init(uuidString:))
        guard ids.count == values.count, Set(ids).count == ids.count else {
            throw ChekinanaDataImportError.invalidRelationships
        }
        return Set(ids)
    }

    private static func uuid(_ value: String) throws -> UUID {
        guard let result = UUID(uuidString: value) else {
            throw ChekinanaDataImportError.invalidArchive
        }
        return result
    }

    private static func requiredDate(_ value: String) throws -> Date {
        guard let result = ISO8601DateFormatter().date(from: value) else {
            throw ChekinanaDataImportError.invalidArchive
        }
        return result
    }

    private static func contentDate(_ value: String?) throws -> Date? {
        guard let value else { return nil }
        return try ChekinanaPersistedContentDatePolicy.validatedCanonical(
            requiredDate(value)
        )
    }

    @MainActor
    static func replaceLocalLibrary(
        with prepared: ChekinanaPreparedDataImport,
        in modelContext: ModelContext,
        saveContext: SaveContext = { try $0.save() }
    ) async throws {
        try await ChekinanaLibraryMutationProtocol.withExclusiveOperation {
            try ChekinanaLibraryMutationPreflight
                .requireLibraryReplacementReadyExclusively(in: modelContext)
            try await replaceLocalLibraryExclusively(
                with: prepared,
                in: modelContext,
                saveContext: saveContext
            )
            _ = ChekinanaLibraryQueueReconciler.cleanupOrdinaryQueuesExclusively(
                in: modelContext
            )
        }
    }

    /// This must run before Gallery/Event/orphan/staging cleanup on launch.
    /// A failure intentionally blocks ordinary cleanup so neither generation is
    /// mistaken for an orphan while the import journal remains authoritative.
    @MainActor
    static func recoverUnfinishedImport(
        in modelContext: ModelContext,
        directory suppliedDirectory: URL? = nil
    ) throws {
        let managedDirectory: URL
        do {
            managedDirectory = try suppliedDirectory
                ?? ChekiImageRefResolver.chekiImagesDirectory()
        } catch {
            throw ChekinanaDataImportError.recoveryIncomplete
        }
        let handles: [ChekinanaImportTransactionHandle]
        do {
            _ = ChekinanaImportTransactionHandle.retireUnpublishedInitializations(
                in: managedDirectory
            )
            handles = try ChekinanaImportTransactionHandle.discover(
                in: managedDirectory
            ).filter { try !$0.retireUnjournalledEmptyRoot() }
        } catch let error as ChekinanaImportTransactionError {
            throw error.importError
        } catch {
            throw ChekinanaDataImportError.recoveryIncomplete
        }
        guard handles.count <= 1 else {
            throw ChekinanaDataImportError.recoveryIndeterminate
        }
        guard let handle = handles.first else { return }
        do {
            _ = try recover(handle, in: modelContext)
        } catch let error as ChekinanaImportTransactionError {
            throw error.importError
        } catch let error as ChekinanaDataImportError {
            throw error
        } catch {
            throw ChekinanaDataImportError.recoveryIncomplete
        }
    }

    @MainActor
    private static func replaceLocalLibraryExclusively(
        with prepared: ChekinanaPreparedDataImport,
        in modelContext: ModelContext,
        saveContext: SaveContext
    ) async throws {
        let entityIDs = try ImportEntityIDs(prepared.payload.entities)
        let managedDirectory: URL
        do {
            managedDirectory = try ChekiImageRefResolver.chekiImagesDirectory()
        } catch {
            throw ChekinanaDataImportError.replacementFailed
        }
        let oldGeneration: UUID
        do {
            oldGeneration = try ChekinanaPersistenceMutationCoordinator.withLock {
                // The public entrance must retire clear before a third generation.
                guard try ChekinanaLocalDataClearJournalStore.load(
                    in: managedDirectory
                ) == nil else {
                    throw ChekinanaImportTransactionError.incomplete
                }
                let generation = try ChekinanaLibraryGenerationStore.ensureCurrent(
                    in: modelContext
                )
                guard ChekinanaGalleryDeletionRecoveryCoordinator
                    .recoverExclusively(
                        in: modelContext,
                        directory: managedDirectory
                    ) == 0 else {
                    throw ChekinanaImportTransactionError.incomplete
                }
                return generation
            }
        } catch {
            throw ChekinanaDataImportError.recoveryIncomplete
        }
        let newGeneration = UUID()
        let preexistingFiles = managedFiles(in: managedDirectory)
        var transaction: ChekinanaImportTransactionHandle?
        do {
            let createdTransaction = try await ChekinanaGalleryMediaStore.performFileIO {
                try ChekinanaImportTransactionHandle.create(
                    in: managedDirectory,
                    oldGeneration: oldGeneration,
                    newGeneration: newGeneration,
                    language: prepared.language,
                    theme: prepared.theme,
                    hiddenIdolIDs: prepared.hiddenIdolIDs,
                    preexistingFiles: preexistingFiles,
                    identityCache: prepared.identityCache
                )
            }
            transaction = createdTransaction
            try await ChekinanaGalleryMediaStore.performFileIO {
                try createdTransaction.stageOldFiles()
            }
            let materializer = ImportMediaMaterializer(
                prepared: prepared,
                entityIDs: entityIDs,
                directory: managedDirectory,
                transaction: createdTransaction
            )
            let mediaReferences = try await materializer.materialize()
            try Task.checkCancellation()
            try createdTransaction.updatePhase(.databaseCommitPending)
            try ChekinanaPersistenceMutationCoordinator.withLock {
                do {
                    try modelContext.transaction {
                        try replaceEntities(
                            prepared.payload.entities,
                            schemaVersion: prepared.payload.schemaVersion,
                            ids: entityIDs,
                            media: mediaReferences,
                            in: modelContext
                        )
                        _ = try ChekinanaChekiIndexing
                            .repairPersistedMediaItems(in: modelContext)
                        try ChekinanaLibraryGenerationStore.publish(
                            newGeneration,
                            in: modelContext
                        )
                        try saveContext(modelContext)
                    }
                } catch {
                    modelContext.rollback()
                    throw error
                }
            }
            try createdTransaction.updatePhase(.finishingNew)
            let direction = try recover(createdTransaction, in: modelContext)
            guard direction == .completeNew else {
                throw ChekinanaDataImportError.recoveryIndeterminate
            }
        } catch {
            if let transaction {
                do {
                    let direction = try recover(transaction, in: modelContext)
                    if direction == .completeNew {
                        // The DB commit witness wins even when the process lost
                        // the subsequent external-journal phase update.
                        return
                    }
                } catch let recovery as ChekinanaImportTransactionError {
                    throw recovery.importError
                } catch let recovery as ChekinanaDataImportError {
                    throw recovery
                } catch {
                    throw ChekinanaDataImportError.recoveryIncomplete
                }
            }
            if error is CancellationError { throw CancellationError() }
            if let error = error as? ChekinanaDataImportError {
                throw error
            }
            throw ChekinanaDataImportError.replacementFailed
        }
    }

    @MainActor
    @discardableResult
    private static func recover(
        _ transaction: ChekinanaImportTransactionHandle,
        in modelContext: ModelContext
    ) throws -> ChekinanaImportRecoveryDirection {
        let journal = try transaction.load()
        let witnessContext = ModelContext(modelContext.container)
        let direction = try ChekinanaImportRecoveryDirection.resolve(
            oldGeneration: journal.oldGeneration,
            newGeneration: journal.newGeneration,
            currentGeneration: try ChekinanaLibraryGenerationStore.current(
                in: witnessContext
            )
        )
        if direction == .restoreOld {
            // A custom/injected save callback may return without committing.
            // The durable witness, not the writer context's pending objects,
            // decides the outcome, and the pending entity graph is discarded.
            modelContext.rollback()
        } else {
            guard let language = ChekinanaAppLanguage(rawValue: journal.settings.language),
                  let theme = ChekinanaThemeOption(rawValue: journal.settings.theme) else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            let hiddenIDs = journal.settings.hiddenIdolIDs.compactMap(UUID.init(uuidString:))
            guard hiddenIDs.count == journal.settings.hiddenIdolIDs.count,
                  Set(hiddenIDs).count == hiddenIDs.count else {
                throw ChekinanaImportTransactionError.invalidJournal
            }
            // Applying settings before removing the journal makes a crash at
            // any point replay the same idempotent settings update.
            languageStoreApply(language)
            themeStoreApply(theme)
            hiddenIdolStoreApply(Set(hiddenIDs))
        }
        // Rebind legacy queues before removing the import journal. A crash on
        // either side replays this idempotently against the same durable
        // generation witness. Restore-old is deliberately a no-op so a failed
        // import cannot cancel the old library's recovery work.
        _ = try ChekinanaLibraryQueueReconciler
            .reconcileImportRecoveryExclusively(
                direction: direction,
                expectedGeneration: direction == .completeNew
                    ? journal.newGeneration : journal.oldGeneration,
                in: witnessContext,
                directory: transaction.managedDirectory
            )
        return try transaction.recover(
            currentGeneration: direction == .restoreOld
                ? journal.oldGeneration : journal.newGeneration
        )
    }

    private struct ImportEntityIDs {
        let idols: [UUID: UUID]
        let events: [UUID: UUID]
        let eventImages: [UUID: UUID]
        let travels: [UUID: UUID]
        let mediaItems: [UUID: UUID]
        let mediaOwners: [UUID: UUID]
        let records: [UUID: UUID]
        let memories: [UUID: UUID]
        let memoryAttachments: [UUID: UUID]
        let customChekiSizes: [UUID: UUID]

        init(_ entities: ChekinanaDataImportPayload.Entities) throws {
            func map(_ values: [String]) throws -> [UUID: UUID] {
                try Dictionary(uniqueKeysWithValues: values.map { value in
                    guard let source = UUID(uuidString: value) else {
                        throw ChekinanaDataImportError.invalidArchive
                    }
                    return (source, source)
                })
            }
            idols = try map(entities.idols.map(\.id))
            events = try map(entities.events.map(\.id))
            eventImages = try map(entities.eventImages.map(\.id))
            travels = try map(entities.travelSegments.map(\.id))
            mediaItems = try map(entities.mediaItems.map(\.id))
            mediaOwners = try map(entities.mediaItems.map(\.mediaOwnerID))
            records = try map(entities.chekiRecords.map(\.id))
            memories = try map(entities.memories.map(\.id))
            memoryAttachments = try map(entities.memoryAttachments.map(\.id))
            customChekiSizes = try map(entities.customChekiSizes.map(\.id))
        }
    }

    private struct ImportMediaReferences {
        var idols: [UUID: String] = [:]
        var events: [UUID: String] = [:]
        var eventImages: [UUID: String] = [:]
        var travels: [UUID: String] = [:]
        var mediaItems: [UUID: String] = [:]
        var memoryAttachments: [UUID: String] = [:]
    }

    @MainActor
    private final class ImportMediaMaterializer {
        let prepared: ChekinanaPreparedDataImport
        let entityIDs: ImportEntityIDs
        let directory: URL
        let transaction: ChekinanaImportTransactionHandle
        private var pendingFiles: [(source: URL, record: ChekinanaImportTransactionJournal.CreatedFile)] = []
        private static let maximumBatchCount = 256

        init(
            prepared: ChekinanaPreparedDataImport,
            entityIDs: ImportEntityIDs,
            directory: URL,
            transaction: ChekinanaImportTransactionHandle
        ) {
            self.prepared = prepared
            self.entityIDs = entityIDs
            self.directory = directory
            self.transaction = transaction
        }

        func materialize() async throws -> ImportMediaReferences {
            let entities = prepared.payload.entities
            var result = ImportMediaReferences()
            for value in entities.idols where value.avatarImageRef?.nonEmpty != nil {
                try Task.checkCancellation()
                let oldID = try ChekinanaDataImporter.uuid(value.id)
                let newID = try mapped(oldID, in: entityIDs.idols)
                let filename = ChekinanaIdolReferenceStore.managedFilename(idolID: newID)
                try copy(ownerType: "Idol", ownerID: oldID, filename: filename)
                result.idols[oldID] = filename
            }
            for value in entities.events where value.avatarImageRef?.nonEmpty != nil {
                try Task.checkCancellation()
                let oldID = try ChekinanaDataImporter.uuid(value.id)
                let newID = try mapped(oldID, in: entityIDs.events)
                let filename = try ChekinanaEventMediaReference.importedFilename(
                    kind: .avatar, ownerID: newID,
                    originalReference: value.avatarImageRef ?? ""
                )
                try copy(ownerType: "Event", ownerID: oldID, filename: filename)
                result.events[oldID] = filename
            }
            for value in entities.eventImages {
                try Task.checkCancellation()
                let oldID = try ChekinanaDataImporter.uuid(value.id)
                let eventID = try ChekinanaDataImporter.uuid(value.eventID)
                let newEventID = try mapped(eventID, in: entityIDs.events)
                let filename = try ChekinanaEventMediaReference.importedFilename(
                    kind: .image, ownerID: newEventID,
                    originalReference: value.imageRef
                )
                try copy(ownerType: "EventImage", ownerID: oldID, filename: filename)
                result.eventImages[oldID] = filename
            }
            for value in entities.travelSegments
                where ChekinanaTravelOperatorIcon.assetName(from: value.operatorIconRef) == nil
                    && value.operatorIconRef?.nonEmpty != nil {
                try Task.checkCancellation()
                let oldID = try ChekinanaDataImporter.uuid(value.id)
                let newID = try mapped(oldID, in: entityIDs.travels)
                let filename = try ChekinanaEventMediaReference.importedFilename(
                    kind: .avatar, ownerID: newID,
                    originalReference: value.operatorIconRef ?? ""
                )
                try copy(ownerType: "TravelSegment", ownerID: oldID, filename: filename)
                result.travels[oldID] = filename
            }
            for value in entities.mediaItems {
                try Task.checkCancellation()
                let oldID = try ChekinanaDataImporter.uuid(value.id)
                let oldOwnerID = try ChekinanaDataImporter.uuid(value.mediaOwnerID)
                let newOwnerID = try mapped(oldOwnerID, in: entityIDs.mediaOwners)
                let kind = try mediaItemKind(value.kind)
                switch kind {
                case .cheki:
                    let ext = fileExtension(value.mediaRef)
                    let filename = "\(newOwnerID.uuidString.lowercased()).\(ext)"
                    try copy(ownerType: "MediaItem", ownerID: oldID, filename: filename)
                    result.mediaItems[oldID] = filename
                case .shame:
                    let ext = fileExtension(value.mediaRef)
                    let filename = "shame-\(newOwnerID.uuidString.lowercased()).\(ext)"
                    try copy(ownerType: "MediaItem", ownerID: oldID, filename: filename)
                    result.mediaItems[oldID] = filename
                case .douga:
                    let filename = try await materializeVideo(
                        ownerType: "MediaItem",
                        ownerID: oldID,
                        destinationID: newOwnerID
                    )
                    result.mediaItems[oldID] = filename
                }
            }
            for value in entities.memoryAttachments {
                try Task.checkCancellation()
                let oldID = try ChekinanaDataImporter.uuid(value.id)
                let newID = try mapped(oldID, in: entityIDs.memoryAttachments)
                let kind = try memoryAttachmentKind(value.kind)
                switch kind {
                case .image:
                    let ext = fileExtension(value.managedRef)
                    let filename = "shame-\(newID.uuidString.lowercased()).\(ext)"
                    try copy(
                        ownerType: "MemoryAttachment",
                        ownerID: oldID,
                        filename: filename
                    )
                    result.memoryAttachments[oldID] = filename
                case .video:
                    let filename = try await materializeVideo(
                        ownerType: "MemoryAttachment",
                        ownerID: oldID,
                        destinationID: newID
                    )
                    result.memoryAttachments[oldID] = filename
                }
            }
            try flushPendingFiles()
            return result
        }

        private func sourceFile(
            ownerType: String,
            ownerID: UUID
        ) throws -> ChekinanaPreparedDataImport.MediaFile {
            guard let file = prepared.mediaByOwner[
                .init(type: ownerType, id: ownerID)
            ], ChekiImageRefResolver.isRegularReadableFile(file.url) else {
                throw ChekinanaDataImportError.mediaIntegrity
            }
            return file
        }

        private func copy(ownerType: String, ownerID: UUID, filename: String) throws {
            let file = try sourceFile(ownerType: ownerType, ownerID: ownerID)
            let record = ChekinanaImportTransactionJournal.CreatedFile(
                filename: filename,
                identity: .init(byteCount: file.byteCount, sha256: file.sha256)
            )
            pendingFiles.append((file.url, record))
            if pendingFiles.count >= Self.maximumBatchCount { try flushPendingFiles() }
        }

        private func flushPendingFiles() throws {
            guard !pendingFiles.isEmpty else { return }
            try Task.checkCancellation()
            // Persist and synchronize the entire batch before its first file
            // can appear. The unchanged journal recovers any partial batch.
            try transaction.reserveCreatedFiles(pendingFiles.map(\.record))
            for file in pendingFiles {
                try Task.checkCancellation()
                try transaction.materialize(from: file.source, as: file.record.filename)
            }
            pendingFiles.removeAll(keepingCapacity: true)
        }

        private func materializeVideo(
            ownerType: String,
            ownerID: UUID,
            destinationID: UUID
        ) async throws -> String {
            try flushPendingFiles()
            let file = try sourceFile(ownerType: ownerType, ownerID: ownerID)
            let staged = try ChekinanaGalleryMediaStore.makeStagedVideoCopy(
                from: file.url,
                fileSize: { Int64(try $0.resourceValues(forKeys: [.fileSizeKey]).fileSize ?? 0) },
                copyItem: { source, destination in
                    do { try FileManager.default.linkItem(at: source, to: destination) }
                    catch { try FileManager.default.copyItem(at: source, to: destination) }
                }
            )
            defer { ChekinanaGalleryMediaStore.discardStagedVideo(at: staged) }
            let thumbnailData = try await ChekinanaGalleryMediaStore
                .preparedVideoThumbnailData(at: staged)
            let filename = "douga-\(destinationID.uuidString.lowercased()).\(fileExtension(staged.lastPathComponent))"
            let thumbnailFilename = ChekinanaGalleryMediaStore.thumbnailURL(
                id: destinationID,
                directory: directory
            ).lastPathComponent
            try transaction.reserveCreatedFiles([
                .init(
                    filename: filename,
                    identity: .init(byteCount: file.byteCount, sha256: file.sha256)
                ),
                .init(
                    filename: thumbnailFilename,
                    identity: ChekinanaImportFileIdentity(thumbnailData)
                ),
            ])
            try await ChekinanaGalleryMediaStore.performFileIO {
                try self.transaction.materialize(from: staged, as: filename)
                try self.transaction.materialize(thumbnailData, as: thumbnailFilename)
            }
            return filename
        }

        private func fileExtension(_ reference: String) -> String {
            ChekinanaGalleryMediaStore.safeMediaExtension(
                URL(fileURLWithPath: reference).pathExtension,
                fallback: "bin"
            )
        }

        private func mapped(_ source: UUID, in values: [UUID: UUID]) throws -> UUID {
            guard let result = values[source] else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            return result
        }

        private func mediaItemKind(_ rawValue: String) throws -> MediaItemKind {
            guard let value = MediaItemKind(rawValue: rawValue) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            return value
        }

        private func memoryAttachmentKind(_ rawValue: String) throws -> MemoryAttachmentKind {
            guard let value = MemoryAttachmentKind(rawValue: rawValue) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            return value
        }
    }

    @MainActor
    private static func replaceEntities(
        _ entities: ChekinanaDataImportPayload.Entities,
        schemaVersion: String,
        ids: ImportEntityIDs,
        media: ImportMediaReferences,
        in modelContext: ModelContext
    ) throws {
        func oldUUID(_ value: String) throws -> UUID { try uuid(value) }
        func mapped(_ value: String, in values: [UUID: UUID]) throws -> UUID {
            let old = try oldUUID(value)
            guard let new = values[old] else {
                throw ChekinanaDataImportError.invalidRelationships
            }
            return new
        }
        func mappedOptional(_ value: String?, in values: [UUID: UUID]) throws -> UUID? {
            guard let value else { return nil }
            return try mapped(value, in: values)
        }
        func mappedMany(_ values: [String], in mapping: [UUID: UUID]) throws -> [UUID] {
            try values.map { try mapped($0, in: mapping) }
        }

        let existingIdols = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<Idol>()).map { ($0.id, $0) }
        )
        for value in entities.idols {
            let oldID = try oldUUID(value.id)
            let stableID = try mapped(value.id, in: ids.idols)
            let idol = existingIdols[stableID] ?? Idol(id: stableID, name: value.name)
            if existingIdols[stableID] == nil { modelContext.insert(idol) }
            idol.sourceId = value.sourceId
            idol.name = value.name
            idol.group = value.group
            idol.color = value.color
            idol.birthday = value.birthday
            idol.avatarImageRef = media.idols[oldID]
            idol.isFavorite = value.isFavorite
            idol.sortOrder = value.sortOrder
            idol.note = value.note
            idol.createdAt = try requiredDate(value.createdAt)
            idol.updatedAt = try requiredDate(value.updatedAt)
            idol.verification = value.verification
            idol.bio = value.bio
            idol.pattern = value.pattern
            idol.patterns = value.patterns
        }
        let wantedIdolIDs = Set(ids.idols.values)
        existingIdols.values.filter { !wantedIdolIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingAvatarStates = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<IdolAvatarState>()).map {
                ($0.idolID, $0)
            }
        )
        for value in entities.idols {
            let stableID = try mapped(value.id, in: ids.idols)
            let avatarState = try value.resolvedAvatarState(
                allowingMissingFields: schemaVersion != "17.0.0"
            )
            if let existing = existingAvatarStates[stableID] {
                existing.sourceRawValue = avatarState.source.rawValue
                existing.intentRawValue = avatarState.intent.rawValue
                existing.revision = UUID()
            } else {
                modelContext.insert(IdolAvatarState(
                    idolID: stableID,
                    source: avatarState.source,
                    intent: avatarState.intent
                ))
            }
        }
        existingAvatarStates.values
            .filter { !wantedIdolIDs.contains($0.idolID) }
            .forEach(modelContext.delete)

        let existingPatternStates = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<IdolPatternState>()).map { ($0.idolID, $0) }
        )
        for value in entities.idolPatternStates {
            let stableID = try mapped(value.idolID, in: ids.idols)
            let state = existingPatternStates[stableID] ?? IdolPatternState(
                idolID: stableID,
                encoderVersion: value.encoderVersion
            )
            if existingPatternStates[stableID] == nil { modelContext.insert(state) }
            state.encoderVersion = value.encoderVersion
            state.cataloguePatternIDs = value.cataloguePatternIDs
            state.cataloguePatternCount = value.cataloguePatternCount
        }
        let wantedPatternIDs = Set(try entities.idolPatternStates.map {
            try mapped($0.idolID, in: ids.idols)
        })
        existingPatternStates.values.filter { !wantedPatternIDs.contains($0.idolID) }
            .forEach(modelContext.delete)

        let existingEvents = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<Event>()).map { ($0.id, $0) }
        )
        for value in entities.events {
            let oldID = try oldUUID(value.id)
            let stableID = try mapped(value.id, in: ids.events)
            let event = existingEvents[stableID] ?? Event(id: stableID, name: value.name)
            if existingEvents[stableID] == nil { modelContext.insert(event) }
            event.name = value.name
            event.date = try contentDate(value.date)
            event.city = value.city
            event.livehouse = value.livehouse
            event.legacyVenue = value.legacyVenue
            event.avatarImageRef = media.events[oldID]
            event.price = value.price
            event.weiboURL = value.weiboURL.flatMap(URL.init(string:))
            event.source = value.source.flatMap(ChekinanaEventSource.init(rawValue:))
            if schemaVersion == "15.0.0", event.source == nil {
                event.source = ChekinanaEventSource.infer(from: event.weiboURL)
            }
            event.ticketURL = value.ticketURL.flatMap(URL.init(string:))
            event.note = value.note
            event.createdAt = try requiredDate(value.createdAt)
            event.updatedAt = try requiredDate(value.updatedAt)
        }
        let wantedEventIDs = Set(ids.events.values)
        existingEvents.values.filter { !wantedEventIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingCustomSizes = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<CustomChekiSize>()).map { ($0.id, $0) }
        )
        for value in entities.customChekiSizes {
            let stableID = try mapped(value.id, in: ids.customChekiSizes)
            let createdAt = try requiredDate(value.createdAt)
            let custom: CustomChekiSize
            if let existing = existingCustomSizes[stableID] {
                custom = existing
            } else {
                custom = CustomChekiSize(
                    id: stableID,
                    name: value.name,
                    widthRatio: value.widthRatio,
                    heightRatio: value.heightRatio,
                    createdAt: createdAt
                )
                modelContext.insert(custom)
            }
            custom.name = value.name
            custom.widthRatio = value.widthRatio
            custom.heightRatio = value.heightRatio
            custom.pixelWidth = value.pixelWidth
            custom.pixelHeight = value.pixelHeight
            custom.createdAt = createdAt
        }
        let wantedCustomSizeIDs = Set(ids.customChekiSizes.values)
        existingCustomSizes.values.filter { !wantedCustomSizeIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingSchedules = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<EventSchedule>()).map { ($0.eventID, $0) }
