            image.imageRef = ref
            image.sortOrder = value.sortOrder
        }
        let wantedEventImageIDs = Set(ids.eventImages.values)
        existingEventImages.values.filter { !wantedEventImageIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingOrders = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<CalendarGroupOrder>()).map { ($0.id, $0) }
        )
        for value in entities.calendarGroupOrders {
            let order = existingOrders[value.id] ?? CalendarGroupOrder(
                dateKey: value.dateKey,
                groupKey: value.groupKey,
                sortOrder: value.sortOrder
            )
            if existingOrders[value.id] == nil { modelContext.insert(order) }
            order.dateKey = value.dateKey
            order.groupKey = value.groupKey
            order.sortOrder = value.sortOrder
        }
        let wantedOrderIDs = Set(entities.calendarGroupOrders.map(\.id))
        existingOrders.values.filter { !wantedOrderIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingTravels = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<TravelSegment>()).map { ($0.id, $0) }
        )
        for value in entities.travelSegments {
            let oldID = try oldUUID(value.id)
            guard let mode = ChekinanaTravelMode(rawValue: value.mode) else {
                throw ChekinanaDataImportError.invalidArchive
            }
            let stableID = try mapped(value.id, in: ids.travels)
            let departureTime = try requiredDate(value.departureTime)
            let arrivalTime = try requiredDate(value.arrivalTime)
            let travel = existingTravels[stableID] ?? TravelSegment(
                id: stableID,
                mode: mode,
                serviceNumber: value.serviceNumber,
                departureCity: value.departureCity,
                departureLocation: value.departureLocation,
                arrivalCity: value.arrivalCity,
                arrivalLocation: value.arrivalLocation,
                departureTime: departureTime,
                arrivalTime: arrivalTime
            )
            if existingTravels[stableID] == nil { modelContext.insert(travel) }
            travel.modeRawValue = mode.rawValue
            travel.operatorName = value.operatorName
            travel.operatorIconRef = media.travels[oldID] ?? value.operatorIconRef
            travel.serviceNumber = value.serviceNumber
            travel.departureCity = value.departureCity
            travel.departureLocation = value.departureLocation
            travel.arrivalCity = value.arrivalCity
            travel.arrivalLocation = value.arrivalLocation
            travel.departureTime = departureTime
            travel.arrivalTime = arrivalTime
            travel.seatNumber = value.seatNumber
            travel.carriageNumber = value.carriageNumber
            travel.note = value.note
            travel.createdAt = try requiredDate(value.createdAt)
            travel.updatedAt = try requiredDate(value.updatedAt)
        }
        let wantedTravelIDs = Set(ids.travels.values)
        existingTravels.values.filter { !wantedTravelIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingMedia = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<MediaItem>()).map { ($0.id, $0) }
        )
        for value in entities.mediaItems {
            let oldID = try oldUUID(value.id)
            guard let kind = MediaItemKind(rawValue: value.kind),
