            }
            let stableID = try mapped(value.id, in: ids.mediaItems)
            let mediaOwnerID = try mapped(value.mediaOwnerID, in: ids.mediaOwners)
            let createdAt = try requiredDate(value.createdAt)
            let updatedAt = try requiredDate(value.updatedAt)
            let item = existingMedia[stableID] ?? MediaItem(
                id: stableID,
                mediaOwnerID: mediaOwnerID,
                kind: kind,
                idolIDs: [],
                eventID: nil,
                date: nil,
                userAppears: value.userAppears,
                isFavorite: value.isFavorite,
                hasPostedToSNS: value.hasPostedToSNS,
                note: value.note,
                mediaRef: ref,
                sizeRawValue: value.size,
                idx: value.idx,
                createdAt: createdAt,
                updatedAt: updatedAt
            )
            if existingMedia[stableID] == nil { modelContext.insert(item) }
            try item.replaceFromBackup(
                mediaOwnerID: mediaOwnerID,
                kind: kind,
                idolIDs: try mappedMany(value.idolIDs, in: ids.idols),
                eventID: try mappedOptional(value.eventID, in: ids.events),
                date: try contentDate(value.date),
                userAppears: value.userAppears,
                isFavorite: value.isFavorite,
                hasPostedToSNS: value.hasPostedToSNS,
                note: value.note,
                mediaRef: ref,
                sizeRawValue: value.size,
                idx: value.idx,
                createdAt: createdAt,
                updatedAt: updatedAt
            )
        }
        let wantedMediaIDs = Set(ids.mediaItems.values)
        existingMedia.values.filter { !wantedMediaIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingRecords = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<ChekiRecord>()).map { ($0.id, $0) }
        )
        for value in entities.chekiRecords {
            let stableID = try mapped(value.id, in: ids.records)
            let record = existingRecords[stableID] ?? ChekiRecord(id: stableID)
            if existingRecords[stableID] == nil { modelContext.insert(record) }
            record.idolIDs = try mappedMany(value.idolIDs, in: ids.idols)
            record.eventID = try mappedOptional(value.eventID, in: ids.events)
            record.date = try contentDate(value.date)
            record.sizeRawValue = value.size ?? ChekiSize.mini.rawValue
            record.note = value.note
            record.count = value.count
        }
        let wantedRecordIDs = Set(ids.records.values)
        existingRecords.values.filter { !wantedRecordIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingMemories = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<Memory>()).map { ($0.id, $0) }
        )
        for value in entities.memories {
            let stableID = try mapped(value.id, in: ids.memories)
            let memory = existingMemories[stableID] ?? Memory(id: stableID)
            if existingMemories[stableID] == nil { modelContext.insert(memory) }
            memory.title = value.title
            memory.bodyText = value.bodyText
            memory.date = try contentDate(value.date)
            memory.eventID = try mappedOptional(value.eventID, in: ids.events)
            memory.idolIDs = try mappedMany(value.idolIDs, in: ids.idols)
            memory.createdAt = try requiredDate(value.createdAt)
            memory.updatedAt = try requiredDate(value.updatedAt)
        }
        let wantedMemoryIDs = Set(ids.memories.values)
        existingMemories.values.filter { !wantedMemoryIDs.contains($0.id) }
            .forEach(modelContext.delete)

        let existingAttachments = Dictionary(uniqueKeysWithValues:
            try modelContext.fetch(FetchDescriptor<MemoryAttachment>()).map { ($0.id, $0) }
        )
        for value in entities.memoryAttachments {
            let oldID = try oldUUID(value.id)
            guard let kind = MemoryAttachmentKind(rawValue: value.kind),
                  let ref = media.memoryAttachments[oldID] else {
                throw ChekinanaDataImportError.mediaIntegrity
            }
            let stableID = try mapped(value.id, in: ids.memoryAttachments)
            let memoryID = try mapped(value.memoryID, in: ids.memories)
            let attachment = existingAttachments[stableID] ?? MemoryAttachment(
                id: stableID,
                memoryID: memoryID,
                kind: kind,
                managedRef: ref,
                sortOrder: value.sortOrder
            )
            if existingAttachments[stableID] == nil { modelContext.insert(attachment) }
            attachment.replaceFromBackup(
                memoryID: memoryID,
                kind: kind,
                managedRef: ref,
                sortOrder: value.sortOrder,
                createdAt: try requiredDate(value.createdAt),
                updatedAt: try requiredDate(value.updatedAt)
            )
        }
        let wantedAttachmentIDs = Set(ids.memoryAttachments.values)
        existingAttachments.values.filter { !wantedAttachmentIDs.contains($0.id) }
            .forEach(modelContext.delete)
    }

    private static func managedFiles(in directory: URL) -> Set<URL> {
        let values = (try? FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey],
            options: [.skipsHiddenFiles]
        )) ?? []
        return Set(values.filter { url in
            guard let attributes = try? url.resourceValues(
                forKeys: [.isRegularFileKey, .isSymbolicLinkKey]
            ) else { return false }
            return attributes.isRegularFile == true && attributes.isSymbolicLink != true
        })
    }

    @MainActor
    private static func languageStoreApply(_ language: ChekinanaAppLanguage) {
        ChekinanaLanguageStore.shared.language = language
    }

    @MainActor
    private static func themeStoreApply(_ theme: ChekinanaThemeOption) {
        ChekinanaThemeStore.shared.theme = theme
    }

    @MainActor
    private static func hiddenIdolStoreApply(_ ids: Set<UUID>) {
        let store = ChekinanaHiddenIdolStore.shared
        store.clear()
        ids.forEach(store.hide)
    }
}

enum ChekinanaExportTemporaryFiles {
    private static let cleanupQueue = DispatchQueue(
        label: "app.chekinana.export-cleanup", qos: .utility
    )

    // Callers supply only this export's freshly generated URL, never a URL
    // returned by the picker. Validate the original directory even after move.
    static func ownedDirectory(for archiveURL: URL) -> URL? {
        guard archiveURL.isFileURL, archiveURL.pathExtension == "chekinana" else { return nil }
        let directory = archiveURL.deletingLastPathComponent().standardizedFileURL
        let name = directory.lastPathComponent
        let prefix = "chekinana-export-"
        guard name.hasPrefix(prefix), UUID(uuidString: String(name.dropFirst(prefix.count))) != nil else { return nil }
        let root = FileManager.default.temporaryDirectory.resolvingSymlinksInPath()
        let expectedDirectory = root.appendingPathComponent(name, isDirectory: true)
        guard directory.deletingLastPathComponent().resolvingSymlinksInPath() == root,
              directory.resolvingSymlinksInPath() == expectedDirectory,
              archiveURL.resolvingSymlinksInPath() == expectedDirectory.appendingPathComponent(archiveURL.lastPathComponent),
              let values = try? directory.resourceValues(forKeys: [.isDirectoryKey, .isSymbolicLinkKey]),
              values.isDirectory == true, values.isSymbolicLink != true else { return nil }
        return directory
    }

    static func cleanupArchiveAndWait(at archiveURL: URL?) async throws {
        guard let archiveURL else { return }
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            cleanupQueue.async {
                do {
                    guard FileManager.default.fileExists(atPath: archiveURL.deletingLastPathComponent().path) else {
                        continuation.resume(); return
                    }
                    guard let directory = ownedDirectory(for: archiveURL) else {
                        throw CocoaError(.fileWriteUnknown)
                    }
                    try FileManager.default.removeItem(at: directory)
                    continuation.resume()
                } catch { continuation.resume(throwing: error) }
            }
        }
    }

    static func cleanupArchive(at archiveURL: URL?) {
        guard let archiveURL else { return }
        // Capture this export's original URL only. File validation and deletion
        // can block on storage, so neither belongs in a dismissal/UI callback.
        cleanupQueue.async {
            guard let directory = ownedDirectory(for: archiveURL) else { return }
            try? FileManager.default.removeItem(at: directory)
        }
    }
}

enum ChekinanaStreamingZIP {
    struct Inspection: Sendable {
        let size: UInt64
        let crc32: UInt32
        let sha256: String
    }

    struct FileIdentity: Equatable, Sendable {
        let device: dev_t
        let inode: ino_t
        let size: UInt64
        let modifiedSeconds: Int
        let modifiedNanoseconds: Int
        let changedSeconds: Int
        let changedNanoseconds: Int

        fileprivate init(_ value: stat) throws {
            guard value.st_mode & S_IFMT == S_IFREG, value.st_size >= 0 else {
                throw ChekinanaDataExportError.invalidArchive
            }
            device = value.st_dev; inode = value.st_ino; size = UInt64(value.st_size)
            modifiedSeconds = value.st_mtimespec.tv_sec
            modifiedNanoseconds = value.st_mtimespec.tv_nsec
            changedSeconds = value.st_ctimespec.tv_sec
            changedNanoseconds = value.st_ctimespec.tv_nsec
        }
    }

    static func fileIdentity(at url: URL) throws -> FileIdentity {
        guard url.isFileURL else { throw ChekinanaDataExportError.invalidArchive }
        var value = stat()
        let result = url.withUnsafeFileSystemRepresentation { path in
            guard let path else { return Int32(-1) }
            return Darwin.lstat(path, &value)
        }
        guard result == 0 else {
            throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
        }
        return try FileIdentity(value)
    }

    private static func fileIdentity(descriptor: Int32) throws -> FileIdentity {
        var value = stat()
        guard Darwin.fstat(descriptor, &value) == 0 else {
            throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
        }
        return try FileIdentity(value)
    }

    enum Source: Sendable { case data(Data); case file(URL) }
    struct Entry: Sendable {
        let name: String
        let source: Source
        let size: UInt64
        let inspection: Inspection?
        let fileIdentity: FileIdentity?
        static func data(_ name: String, _ data: Data) -> Self {
            Self(name: name, source: .data(data), size: UInt64(data.count),
                 inspection: inspect(data), fileIdentity: nil)
        }
        static func file(_ name: String, _ url: URL, _ inspection: Inspection) -> Self {
            Self(name: name, source: .file(url), size: inspection.size,
                 inspection: inspection, fileIdentity: nil)
        }
        static func streamingFile(_ name: String, _ url: URL, _ identity: FileIdentity) -> Self {
            Self(name: name, source: .file(url), size: identity.size,
                 inspection: nil, fileIdentity: identity)
        }
    }

    private struct Central {
        let name: Data
        let inspection: Inspection
        let offset: UInt64
    }
    private static let chunkSize = 1_048_576

    static func inspect(_ url: URL) throws -> Inspection {
        guard ChekiImageRefResolver.isRegularReadableFile(url) else {
            throw ChekinanaDataExportError.missingMedia(url.lastPathComponent)
        }
        let handle = try FileHandle(forReadingFrom: url)
        defer { try? handle.close() }
        var crc = CRC32(); var sha = SHA256(); var size: UInt64 = 0
        try readChunks(from: handle.fileDescriptor) { bytes in
            size = try checkedAdd(size, UInt64(bytes.count))
            crc.update(bytes); sha.update(bufferPointer: bytes)
        }
        return Inspection(
            size: size,
            crc32: crc.finalized,
            sha256: sha.finalize().map { String(format: "%02x", $0) }.joined()
        )
    }

    static func inspect(_ data: Data) -> Inspection {
        var crc = CRC32(); crc.update(data)
        return Inspection(
            size: UInt64(data.count), crc32: crc.finalized,
            sha256: SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
        )
    }

    static func write(
        _ entries: [Entry],
        to url: URL,
        didCompleteEntry: (Int) -> Void = { _ in },
        finalEntries: ([Inspection]) throws -> [Entry] = { _ in [] }
    ) throws {
        var names = Set<String>()
        var openedHandle: FileHandle?
        var outputDescriptor: Int32?
        var stage = ChekinanaExportWriteFailure.Stage.openingFile
        do {
            FileManager.default.createFile(atPath: url.path, contents: nil)
            let handle = try FileHandle(forWritingTo: url)
            openedHandle = handle
            outputDescriptor = handle.fileDescriptor
            var offset: UInt64 = 0; var central: [Central] = []
            func append(_ entry: Entry) throws -> Inspection {
                try Task.checkCancellation()
                guard safe(entry.name), names.insert(entry.name).inserted else {
                    throw ChekinanaDataExportError.invalidArchive
                }
                let entryOffset = offset
                let name = Data(entry.name.utf8)
                let usesZip64 = entry.size >= UInt64(UInt32.max)
                var extra = Data()
                if usesZip64 {
                    extra.appendLE(UInt16(0x0001)); extra.appendLE(UInt16(16))
                    extra.appendLE(entry.size); extra.appendLE(entry.size)
                }
                var header = Data()
                header.appendLE(UInt32(0x04034b50)); header.appendLE(UInt16(usesZip64 ? 45 : 20))
                header.appendLE(UInt16(0)); header.appendLE(UInt16(0)); header.appendLE(UInt16(0)); header.appendLE(UInt16(0))
                header.appendLE(entry.inspection?.crc32 ?? 0)
                header.appendLE(usesZip64 ? UInt32.max : UInt32(entry.size))
                header.appendLE(usesZip64 ? UInt32.max : UInt32(entry.size))
                header.appendLE(UInt16(name.count)); header.appendLE(UInt16(extra.count)); header.append(name); header.append(extra)
                stage = .localHeader
                try handle.write(contentsOf: header)
                offset = try checkedAdd(offset, UInt64(header.count))
                stage = .entryContents
                let written = try copy(
                    entry.source, to: handle, expectedIdentity: entry.fileIdentity
                ) { count in
                    offset = try checkedAdd(offset, UInt64(count))
                }
                guard written.size == entry.size else {
                    throw ChekinanaDataExportError.invalidArchive
                }
                if let expected = entry.inspection {
                    guard written.crc32 == expected.crc32, written.sha256 == expected.sha256 else {
                        throw ChekinanaDataExportError.invalidArchive
                    }
                } else {
                    // Size (including ZIP64 width) is fixed by the metadata plan.
                    // The only unknown local-header field is the streamed CRC.
                    var crc = Data(); crc.appendLE(written.crc32)
                    stage = .localHeaderChecksum
                    try handle.seek(toOffset: try checkedAdd(entryOffset, 14))
                    try handle.write(contentsOf: crc)
                    try handle.seek(toOffset: offset)
                }
                central.append(Central(name: name, inspection: written, offset: entryOffset))
                didCompleteEntry(central.count)
                return written
            }
            var inspections: [Inspection] = []
            for entry in entries { inspections.append(try append(entry)) }
            for entry in try finalEntries(inspections) { _ = try append(entry) }
            let centralOffset = offset
            stage = .centralDirectory
            for entry in central {
                try Task.checkCancellation()
                let zip64 = entry.inspection.size >= UInt64(UInt32.max) || entry.offset >= UInt64(UInt32.max)
                var extra = Data()
                if zip64 {
                    extra.appendLE(UInt16(0x0001)); extra.appendLE(UInt16(24))
                    extra.appendLE(entry.inspection.size); extra.appendLE(entry.inspection.size); extra.appendLE(entry.offset)
                }
                var header = Data()
                header.appendLE(UInt32(0x02014b50)); header.appendLE(UInt16(zip64 ? 45 : 20)); header.appendLE(UInt16(zip64 ? 45 : 20))
                header.appendLE(UInt16(0)); header.appendLE(UInt16(0)); header.appendLE(UInt16(0)); header.appendLE(UInt16(0))
                header.appendLE(entry.inspection.crc32)
                header.appendLE(zip64 ? UInt32.max : UInt32(entry.inspection.size)); header.appendLE(zip64 ? UInt32.max : UInt32(entry.inspection.size))
                header.appendLE(UInt16(entry.name.count)); header.appendLE(UInt16(extra.count)); header.appendLE(UInt16(0))
                header.appendLE(UInt16(0)); header.appendLE(UInt16(0)); header.appendLE(UInt32(0))
                header.appendLE(zip64 ? UInt32.max : UInt32(entry.offset)); header.append(entry.name); header.append(extra)
                try handle.write(contentsOf: header); offset = try checkedAdd(offset, UInt64(header.count))
            }
            let centralSize = offset - centralOffset
            let needsZip64 = requiresZip64(
                entryCount: central.count,
                centralOffset: centralOffset,
                centralSize: centralSize,
                containsLargeEntry: central.contains {
                    $0.inspection.size >= UInt64(UInt32.max)
                        || $0.offset >= UInt64(UInt32.max)
                }
            )
            stage = .archiveEnd
            if needsZip64 {
                let zip64Offset = offset
                let record = zip64EndRecord(
                    entryCount: UInt64(central.count),
                    centralSize: centralSize,
                    centralOffset: centralOffset
                )
                try handle.write(contentsOf: record); offset = try checkedAdd(offset, UInt64(record.count))
                var locator = Data(); locator.appendLE(UInt32(0x07064b50)); locator.appendLE(UInt32(0)); locator.appendLE(zip64Offset); locator.appendLE(UInt32(1))
                try handle.write(contentsOf: locator); offset = try checkedAdd(offset, UInt64(locator.count))
            }
            var end = Data(); end.appendLE(UInt32(0x06054b50)); end.appendLE(UInt16(0)); end.appendLE(UInt16(0))
            end.appendLE(needsZip64 ? UInt16.max : UInt16(central.count)); end.appendLE(needsZip64 ? UInt16.max : UInt16(central.count))
            end.appendLE(needsZip64 ? UInt32.max : UInt32(centralSize)); end.appendLE(needsZip64 ? UInt32.max : UInt32(centralOffset)); end.appendLE(UInt16(0))
            try handle.write(contentsOf: end)
            try Task.checkCancellation()
            stage = .synchronizing
            try handle.synchronize()
            stage = .closing
            try handle.close()
        } catch {
            let captured = ChekinanaExportSpacePolicy.isOutOfSpace(error)
                ? ChekinanaExportWriteFailure.capture(
                    error, stage: stage, descriptor: stage == .closing ? nil : outputDescriptor,
                    directory: url.deletingLastPathComponent()
                )
                : nil
            try? openedHandle?.close()
            try? FileManager.default.removeItem(at: url)
            if let captured { throw captured }
            throw error
        }
    }

    private static func copy(
        _ source: Source,
        to handle: FileHandle,
        expectedIdentity: FileIdentity?,
        count: (Int) throws -> Void
    ) throws -> Inspection {
        var crc = CRC32(); var sha = SHA256(); var total: UInt64 = 0
        func write(_ data: Data) throws {
            try handle.write(contentsOf: data); try count(data.count)
            total = try checkedAdd(total, UInt64(data.count)); crc.update(data); sha.update(data: data)
        }
        switch source {
        case .data(let data): try write(data)
        case .file(let url):
            let descriptor = url.withUnsafeFileSystemRepresentation { path in
                guard let path else { return Int32(-1) }
                return Darwin.open(path, O_RDONLY | O_NOFOLLOW | O_NONBLOCK | O_CLOEXEC)
            }
            guard descriptor >= 0 else {
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(errno))
            }
            defer { Darwin.close(descriptor) }
            let before = try fileIdentity(descriptor: descriptor)
            guard expectedIdentity.map({ $0 == before }) ?? true,
                  try fileIdentity(at: url) == before else {
                throw ChekinanaDataExportError.invalidArchive
            }
            try readChunks(from: descriptor) { bytes in
                guard total <= before.size,
                      UInt64(bytes.count) <= before.size - total else {
                    throw ChekinanaDataExportError.invalidArchive
                }
                try writeAll(bytes, to: handle.fileDescriptor)
                try count(bytes.count)
                total = try checkedAdd(total, UInt64(bytes.count))
                crc.update(bytes); sha.update(bufferPointer: bytes)
            }
            guard total == before.size,
                  try fileIdentity(descriptor: descriptor) == before,
                  try fileIdentity(at: url) == before else {
                throw ChekinanaDataExportError.invalidArchive
            }
        }
        return Inspection(
            size: total, crc32: crc.finalized,
            sha256: sha.finalize().map { String(format: "%02x", $0) }.joined()
        )
    }

    // Reuse one buffer for the entire file. FileHandle/Data bridging must not
    // retain a separate allocation for every chunk during a large export.
    private static func readChunks(
        from descriptor: Int32,
        consume: (UnsafeRawBufferPointer) throws -> Void
    ) throws {
        let buffer = UnsafeMutableRawBufferPointer.allocate(
            byteCount: chunkSize, alignment: MemoryLayout<UInt64>.alignment
        )
        defer { buffer.deallocate() }
        while true {
            try Task.checkCancellation()
            let length = Darwin.read(descriptor, buffer.baseAddress!, buffer.count)
            if length < 0 {
                let code = errno
                if code == EINTR { continue }
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(code))
            }
            if length == 0 { return }
            try consume(UnsafeRawBufferPointer(start: buffer.baseAddress, count: length))
        }
    }

    fileprivate static func writeAll(_ bytes: UnsafeRawBufferPointer, to descriptor: Int32) throws {
        var offset = 0
        while offset < bytes.count {
            try Task.checkCancellation()
            let length = Darwin.write(
                descriptor, bytes.baseAddress!.advanced(by: offset), bytes.count - offset
            )
            if length < 0 {
                let code = errno
                if code == EINTR { continue }
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(code))
            }
            guard length > 0 else {
                throw NSError(domain: NSPOSIXErrorDomain, code: Int(EIO))
            }
            offset += length
        }
    }

    static func requiresZip64(
        entryCount: Int,
        centralOffset: UInt64,
        centralSize: UInt64,
        containsLargeEntry: Bool
    ) -> Bool {
        entryCount >= Int(UInt16.max) || centralOffset >= UInt64(UInt32.max)
            || centralSize >= UInt64(UInt32.max) || containsLargeEntry
    }

    static func zip64EndRecord(
        entryCount: UInt64,
        centralSize: UInt64,
        centralOffset: UInt64
    ) -> Data {
        var record = Data()
        record.appendLE(UInt32(0x06064b50)); record.appendLE(UInt64(44))
        record.appendLE(UInt16(45)); record.appendLE(UInt16(45))
        record.appendLE(UInt32(0)); record.appendLE(UInt32(0))
        record.appendLE(entryCount); record.appendLE(entryCount)
        record.appendLE(centralSize); record.appendLE(centralOffset)
        return record
    }

    static func safe(_ name: String) -> Bool {
        !name.isEmpty && !name.hasPrefix("/") && !name.contains("\\")
            && !name.contains("\0") && !name.split(separator: "/").contains("..")
            && name.utf8.count <= Int(UInt16.max)
    }

    private static func checkedAdd(_ lhs: UInt64, _ rhs: UInt64) throws -> UInt64 {
        let result = lhs.addingReportingOverflow(rhs)
        guard !result.overflow else { throw ChekinanaDataExportError.invalidArchive }
        return result.partialValue
    }

    private struct CRC32 {
        var value: uLong = zlib.crc32(0, nil, 0)
        mutating func update(_ data: Data) {
            data.withUnsafeBytes { update($0) }
        }
        mutating func update(_ bytes: UnsafeRawBufferPointer) {
            guard let base = bytes.bindMemory(to: Bytef.self).baseAddress else { return }
            value = zlib.crc32(value, base, uInt(bytes.count))
        }
        var finalized: UInt32 { UInt32(truncatingIfNeeded: value) }
    }
}

private extension Data {
    mutating func appendLE<T: FixedWidthInteger>(_ value: T) {
        var little = value.littleEndian
        Swift.withUnsafeBytes(of: &little) { append(contentsOf: $0) }
    }
}

// Provisioning metadata is informational: it does not verify the code signature.
struct ChekinanaSigningProfileInfo {
    enum Kind: String {
        case development, adHoc, enterprise, distribution, unknown
    }

    let teamName: String?
    let kind: Kind
    let expiration: Date?
    static let maximumBytes = 2 * 1_024 * 1_024

    static func load(bundle: Bundle = .main) -> Self? {
        guard let url = bundle.url(forResource: "embedded", withExtension: "mobileprovision"),
              let handle = try? FileHandle(forReadingFrom: url) else { return nil }
        defer { try? handle.close() }
        guard let data = try? handle.read(upToCount: maximumBytes + 1) else { return nil }
        return parse(data)
    }

    static func parse(_ data: Data) -> Self? {
        // CMS decoding is not a public iOS API. Read only the bounded, unique
        // XML payload used by current profiles; unknown encodings stay unknown.
        guard data.count <= maximumBytes,
              let start = data.range(of: Data("<?xml".utf8)),
              let end = data.range(of: Data("</plist>".utf8), in: start.lowerBound..<data.endIndex),
              data.range(of: Data("<?xml".utf8), in: start.upperBound..<data.endIndex) == nil,
              data.range(of: Data("</plist>".utf8), in: end.upperBound..<data.endIndex) == nil,
              let value = try? PropertyListSerialization.propertyList(
                from: data.subdata(in: start.lowerBound..<end.upperBound),
                options: [], format: nil
              ),
              let profile = value as? [String: Any],
              let entitlements = profile["Entitlements"] as? [String: Any] else { return nil }
        let team = (profile["TeamName"] as? String)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let rawExpiration = profile["ExpirationDate"] as? Date
        let expiration = rawExpiration.flatMap {
            $0.timeIntervalSinceReferenceDate.isFinite ? $0 : nil
        }
        let kind: Kind
        if entitlements["get-task-allow"] as? Bool == true {
            kind = .development
        } else if profile["ProvisionsAllDevices"] as? Bool == true {
            kind = .enterprise
        } else if let devices = profile["ProvisionedDevices"] as? [String], !devices.isEmpty {
            kind = .adHoc
        } else if entitlements["get-task-allow"] as? Bool == false {
            kind = .distribution
        } else {
            kind = .unknown
        }
        return Self(teamName: team.flatMap { $0.isEmpty ? nil : String($0.prefix(256)) },
                    kind: kind, expiration: expiration)
    }

    static func remaining(expiration: Date, now: Date, locale: Locale) -> String? {
        let interval = expiration.timeIntervalSince(now)
        guard interval.isFinite, interval >= 60 else { return nil }
        let formatter = DateComponentsFormatter()
        var calendar = Calendar(identifier: .gregorian)
        calendar.locale = locale
        formatter.calendar = calendar
        formatter.allowedUnits = [.day, .hour, .minute]
        formatter.unitsStyle = .full
        formatter.maximumUnitCount = 2
        return formatter.string(from: interval)
    }
}

private struct ChekinanaSigningInfoSection: View {
    @Environment(\.chekinanaLanguageRevision) private var languageRevision
    @Environment(\.scenePhase) private var scenePhase
    @State private var profile: ChekinanaSigningProfileInfo?
    @State private var now = Date()

    private var unavailable: String {
        ChekinanaProductCopy.text("settings.signing.unavailable", "Unavailable")
    }

    var body: some View {
        let _ = languageRevision
        Section {
            LabeledContent(ChekinanaProductCopy.text("settings.signing.type", "Profile type"),
                           value: kindTitle)
            LabeledContent(ChekinanaProductCopy.text("settings.signing.expiration", "Profile expires"),
                           value: expirationTitle)
            LabeledContent(ChekinanaProductCopy.text("settings.signing.remaining", "Time remaining"),
                           value: remainingTitle)
        } header: {
            Text(ChekinanaProductCopy.text("settings.signing.title", "App signing"))
        } footer: {
            Text(ChekinanaProductCopy.text(
                "settings.signing.explanation",
                "Based on the embedded provisioning profile. Certificate validity and revocation cannot be verified here. Missing or unreadable profile details are shown as unavailable."
            ))
        }
        .accessibilityIdentifier("chekinana.settings.signing")
        .onAppear(perform: refresh)
        .onChange(of: scenePhase) { _, phase in
            if phase == .active { refresh() }
        }
    }

    private var kindTitle: String {
        switch profile?.kind {
        case .development: ChekinanaProductCopy.text("settings.signing.development", "Development")
        case .adHoc: ChekinanaProductCopy.text("settings.signing.ad_hoc", "Ad Hoc")
        case .enterprise: ChekinanaProductCopy.text("settings.signing.enterprise", "Enterprise")
        case .distribution: ChekinanaProductCopy.text("settings.signing.distribution", "Distribution")
        case .unknown, .none: unavailable
        }
    }

    private var expirationTitle: String {
        guard let expiration = profile?.expiration else { return unavailable }
        let formatter = DateFormatter()
        formatter.locale = ChekinanaLanguagePreference.displayLocale()
        formatter.dateStyle = .medium
        formatter.timeStyle = .short
        return formatter.string(from: expiration)
    }

    private var remainingTitle: String {
        guard let expiration = profile?.expiration else { return unavailable }
        if expiration <= now {
            return ChekinanaProductCopy.text("settings.signing.expired", "Expired")
        }
        if expiration.timeIntervalSince(now) < 60 {
            return ChekinanaProductCopy.text("settings.signing.less_than_minute", "Less than a minute")
        }
        return ChekinanaSigningProfileInfo.remaining(
            expiration: expiration, now: now,
            locale: ChekinanaLanguagePreference.displayLocale()
        ) ?? unavailable
    }

    private func refresh() {
        profile = ChekinanaSigningProfileInfo.load()
        now = Date()
    }
}

