            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.done", "Done")) { dismiss() }
                        .disabled(isPreparingExport || isPreparingImport || isImporting)
                        .accessibilityIdentifier("chekinana.settings.done")
                }
            }
        }
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("chekinana.settings.page")
        .chekinanaScreenMarker("chekinana.settings.page")
        .alert(
            ChekinanaProductCopy.text("idols.unhide", "Unhide"),
            isPresented: Binding(
                get: { pendingUnhideIdol != nil },
                set: { if !$0 { pendingUnhideIdol = nil } }
            ),
            presenting: pendingUnhideIdol
        ) { idol in
            Button(ChekinanaProductCopy.text("idols.unhide", "Unhide")) {
                confirmUnhide(idol)
            }
            .accessibilityIdentifier("chekinana.settings.hidden-idols.unhide.confirm")
            Button(ChekinanaProductCopy.text("common.cancel", "Cancel"), role: .cancel) {
                pendingUnhideIdol = nil
            }
            .accessibilityIdentifier("chekinana.settings.hidden-idols.unhide.cancel")
        } message: { idol in
            Text(ChekinanaProductCopy.format(
                "idols.unhide.confirm.message",
                "Show %@ in visible lists again?",
                idol.name
            ))
        }
        .onAppear {
            hiddenIdols.prune(knownIdolIDs: Set(idols.map(\.id)))
        }
        .confirmationDialog(
            ChekinanaProductCopy.text(
                "settings.clear_confirm.title",
                "Clear all local data?"
            ),
            isPresented: $isClearConfirmationPresented,
            titleVisibility: .visible
        ) {
            Button(
                ChekinanaProductCopy.text("settings.clear_all", "Clear all data"),
                role: .destructive
            ) { clearAllData() }
                .accessibilityIdentifier("chekinana.settings.clear-data.confirm")
            Button(ChekinanaProductCopy.text("common.cancel", "Cancel"), role: .cancel) {}
        } message: {
            Text(
                ChekinanaProductCopy.text(
                    "settings.clear_confirm.message",
                    "This permanently removes every local record and app-managed media file. It does not affect Photos or remote services."
                )
            )
        }
        .alert(ChekinanaProductCopy.text("settings.local_data", "Local data"), isPresented: Binding(
            get: { clearMessage != nil },
            set: { if !$0 { clearMessage = nil } }
        )) {
            Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
        } message: {
            Text(clearMessage ?? "")
        }
        .alert(
            ChekinanaProductCopy.text("settings.export.error.title", "Export failed"),
            isPresented: Binding(
                get: { exportError != nil },
                set: { if !$0 { exportError = nil } }
            )
        ) {
            Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
        } message: {
            Text(exportError ?? "")
        }
        .alert(
            ChekinanaProductCopy.text(
                "settings.import.confirm.title",
                "Import will replace all local data"
            ),
            isPresented: $isImportConfirmationPresented
        ) {
            Button(ChekinanaProductCopy.text("common.cancel", "Cancel"), role: .cancel) {
                cancelPreparedImport()
            }
            Button(ChekinanaProductCopy.text("settings.import.continue", "Continue")) {
                guard let url = pendingImportURL else { return }
                pendingImportURL = nil
                prepareImport(from: url)
            }
        } message: {
            Text(
                ChekinanaProductCopy.text(
                    "settings.import.confirm.message",
                    "Continuing will validate the selected backup and, if validation succeeds, automatically replace every local record, setting, and app-managed media file. Cancel to keep the current library."
                )
            )
        }
        .alert(
            importSucceeded
                ? ChekinanaProductCopy.text("settings.import.success.title", "Import complete")
                : ChekinanaProductCopy.text("settings.import.error.title", "Import failed"),
            isPresented: Binding(
                get: { importFeedback != nil },
                set: { if !$0 { importFeedback = nil } }
            )
        ) {
            Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
        } message: {
            Text(importFeedback ?? "")
        }
        .onChange(of: singleOshiEnabled) { _, _ in ensureSingleOshiSelection() }
        .onChange(of: idols.map(\.id), initial: true) { _, _ in ensureSingleOshiSelection() }
        .sheet(isPresented: $choosingSingleOshi) {
            ChekinanaIdolAvatarCheckSelectionView(
                idols: idols,
                selectedIDs: Binding(
                    get: { UUID(uuidString: singleOshiID).map { Set([$0]) } ?? [] },
                    set: { ids in
                        guard let id = ids.first, idols.contains(where: { $0.id == id }) else { return }
                        singleOshiID = id.uuidString
                    }
                ),
                identifierPrefix: "chekinana.settings.single-oshi",
                allowsMultipleSelection: false,
                allowsEmptySelection: false,
                commitsOnDone: true
            )
        }
        .sheet(isPresented: $isExportPresented, onDismiss: cleanupExportPackage) {
            if let package = exportPackage {
                ChekinanaBackupExportPicker(package: package) { id in
                    guard exportPackage?.id == id else { return }
                    isExportPresented = false
                }
            }
        }
        .fileImporter(
            isPresented: $isImportPickerPresented,
            // Providers may retain a generic ZIP/data type for older backups.
            // The importer validates the archive contents before offering replacement.
            allowedContentTypes: [.chekinanaBackup, .data],
            allowsMultipleSelection: false
        ) { [pickerGeneration = importPickerGeneration] result in
            guard let pickerGeneration,
                  importPickerGeneration == pickerGeneration else { return }
            importPickerGeneration = nil
            switch result {
            case .success(let urls):
                guard let url = urls.first else { return }
                pendingImportURL = url
                isImportConfirmationPresented = true
            case .failure(let error):
                importSucceeded = false
                importFeedback = error.localizedDescription
            }
        }
        .sheet(isPresented: $isCustomChekiSizeEditorPresented) {
            ChekinanaCustomChekiSizeEditor()
        }
        .interactiveDismissDisabled(isPreparingExport || isPreparingImport || isImporting)
        .onDisappear {
            cancelExportPreparation()
            if !isExportPresented, exportPackage?.phase != .presented {
                cleanupExportPackage()
            }
            // The system file picker may cover this view without ending its flow.
            if !isImportPickerPresented {
                importPickerGeneration = nil
                cancelImportPreparation()
                cancelPreparedImport()
            }
        }
    }

    private func chekiSizeDimensionsText(_ size: ChekiSize) -> String {
        let dimensions = ChekinanaImportedChekiCanvasPolicy.dimensions(
            inferredSize: size,
            isLandscape: false
        )
        return "\(dimensions.width) × \(dimensions.height) px"
    }

    private var visibleIdols: [Idol] {
        idolOrdering.ordered(
            ChekinanaVisibilityPolicy.visibleIdols(
                idols,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        )
    }

    private func confirmUnhide(_ idol: Idol) {
        defer { pendingUnhideIdol = nil }
        guard idols.contains(where: { $0.id == idol.id }),
              hiddenIdols.hiddenIDs.contains(idol.id) else { return }
        hiddenIdols.unhide(idol.id)
    }

    private var hiddenIdolModels: [Idol] {
        idolOrdering.ordered(
            idols.filter { hiddenIdols.hiddenIDs.contains($0.id) }
        )
    }

    private var visibleChekis: [MediaItem] {
        chekis.filter { ChekinanaVisibilityPolicy.includesRecord(idols: $0.idols, hiddenIDs: hiddenIdols.hiddenIDs) }
    }

    private var visibleShames: [MediaItem] {
        shames.filter { ChekinanaVisibilityPolicy.includesRecord(idols: $0.idols, hiddenIDs: hiddenIdols.hiddenIDs) }
    }

    private var visibleDougas: [MediaItem] {
        dougas.filter { ChekinanaVisibilityPolicy.includesRecord(idols: $0.idols, hiddenIDs: hiddenIdols.hiddenIDs) }
    }

    private var visibleMemories: [Memory] {
        memories.filter {
            ChekinanaVisibilityPolicy.includesRecord(
                idolIDs: $0.idolIDs,
                hiddenIDs: hiddenIdols.hiddenIDs
            )
        }
    }

    private func settingsRow(_ title: String, value: String, image: String) -> some View {
        settingsRow(title, value: value) {
            if image == "text.book.closed" {
                ChekinanaMemoryCategoryIcon()
            } else {
                Image(systemName: image)
            }
        }
    }

    private func settingsRow<Icon: View>(
        _ title: String,
        value: String,
        @ViewBuilder icon: () -> Icon
    ) -> some View {
        HStack(spacing: 12) {
            icon().foregroundStyle(ChekinanaProductTheme.accent).frame(width: 26).accessibilityHidden(true)
            Text(title)
            Spacer()
            Text(value).foregroundStyle(.secondary).multilineTextAlignment(.trailing)
        }
        .font(.subheadline)
        .listRowInsets(
            EdgeInsets(top: 4, leading: 20, bottom: 4, trailing: 20)
        )
    }

    private func clearAllData() {
        guard !isClearing else { return }
        isClearing = true
        Task { @MainActor in
            defer { isClearing = false }
            do {
                let result = try await ChekinanaLocalDataClearer.clear(
                    modelContext: modelContext
                )
                clearMessage = ChekinanaProductCopy.format(
                    "settings.clear_result",
                    "Cleared %1$lld Cheki, %2$lld phone photos, %3$lld videos, %4$lld Events, %5$lld Idols, and %6$lld managed media files.",
                    Int64(result.chekiCount),
                    Int64(result.shameCount),
                    Int64(result.dougaCount),
                    Int64(result.eventCount),
                    Int64(result.idolCount),
                    Int64(result.removedFileCount)
                )
            } catch {
                clearMessage = error.localizedDescription
            }
        }
    }

    private var exportFilename: String {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        return "Chekinana-\(formatter.string(from: Date())).chekinana"
    }

    private func ensureSingleOshiSelection() {
        guard singleOshiEnabled else { return }
        if let id = UUID(uuidString: singleOshiID), idols.contains(where: { $0.id == id }) { return }
        let first = ChekinanaIdolSelectionOrdering.ordered(
            idols, mediaChekis: chekis, simpleRecords: singleOshiRecords,
            hiddenIDs: hiddenIdols.hiddenIDs, preferredID: nil
        ).first
        singleOshiID = first?.id.uuidString ?? ""
        if first == nil { singleOshiEnabled = false }
    }

    private func prepareExport() {
        guard !isPreparingExport, !isExportPresented, exportPackage == nil else { return }
        exportWriteFailure = nil
        exportPreparationTask?.cancel()
        let generation = UUID()
        let filename = exportFilename
        exportPreparationGeneration = generation
        do {
            let snapshot = try ChekinanaDataExportSnapshot.capture(in: modelContext)
            isPreparingExport = true
            isCancellingExport = false
            exportCompletedFiles = 0
            exportTotalFiles = snapshot.media.count + 3
            exportPreparationTask = Task { @MainActor in
                var preparedURL: URL?
                do {
                    let archiveURL = try await ChekinanaDataExporter.archiveURL(for: snapshot, filename: filename) { completed, total in
                        Task { @MainActor in
                            guard exportPreparationGeneration == generation,
                                  !isCancellingExport, isPreparingExport else { return }
                            exportCompletedFiles = max(exportCompletedFiles, completed)
                            exportTotalFiles = total
                        }
                    }
                    preparedURL = archiveURL
                    try Task.checkCancellation()
                    guard exportPreparationGeneration == generation else {
                        try await ChekinanaExportTemporaryFiles.cleanupArchiveAndWait(at: preparedURL)
                        return
                    }
                    exportPackage = try ChekinanaDataExportPackage(url: archiveURL)
                    preparedURL = nil
                    isExportPresented = true
                } catch is CancellationError {
                    await cleanupCancelledExport(preparedURL, generation: generation)
                } catch {
                    if let cleanupFailure = error as? ChekinanaExportCleanupFailure,
                       exportPreparationGeneration == generation {
                        exportCleanupURL = cleanupFailure.archiveURL
                        exportError = cleanupFailure.localizedDescription
                    } else {
                        await cleanupCancelledExport(preparedURL, generation: generation)
                    }
                    if exportPreparationGeneration == generation,
                       exportCleanupURL == nil, !Task.isCancelled {
                        if let exportFailure = error as? ChekinanaDataExportError,
                           case .writeRejected(let failure) = exportFailure {
                            exportWriteFailure = failure
                        }
                        exportError = error.localizedDescription
                    }
                }
                if exportPreparationGeneration == generation {
                    exportPreparationTask = nil
                    isCancellingExport = false
                    if exportCleanupURL == nil {
                        exportPreparationGeneration = nil
                        isPreparingExport = false
                    }
                }
            }
        } catch {
            if exportPreparationGeneration == generation {
                exportPreparationGeneration = nil
                isPreparingExport = false
                exportError = error.localizedDescription
            }
        }
    }

    private func cleanupCancelledExport(_ url: URL?, generation: UUID) async {
        do { try await ChekinanaExportTemporaryFiles.cleanupArchiveAndWait(at: url) }
        catch {
            guard exportPreparationGeneration == generation, let url else { return }
            exportCleanupURL = url
            exportError = ChekinanaExportCleanupFailure(archiveURL: url).localizedDescription
        }
    }

    private func cancelExportPreparation() {
        guard isPreparingExport, !isCancellingExport else { return }
        isCancellingExport = true
        if let url = exportCleanupURL, let generation = exportPreparationGeneration {
            exportPreparationTask = Task { @MainActor in
                do {
                    try await ChekinanaExportTemporaryFiles.cleanupArchiveAndWait(at: url)
                    guard exportPreparationGeneration == generation else { return }
                    exportCleanupURL = nil
                    exportPreparationGeneration = nil
                    isPreparingExport = false
                } catch {
                    guard exportPreparationGeneration == generation else { return }
                    exportError = ChekinanaExportCleanupFailure(archiveURL: url).localizedDescription
                }
                isCancellingExport = false
                exportPreparationTask = nil
            }
        } else {
            exportPreparationTask?.cancel()
            // Busy remains until worker closure and owned cleanup both finish.
        }
    }

    private func cleanupExportPackage() {
        guard !isExportPresented else { return }
        let package = exportPackage
        exportPackage = nil
        package?.finishAfterDismissal()
    }

    private func prepareImport(from url: URL) {
        guard !isImporting else { return }
        cancelImportPreparation()
        cancelPreparedImport()
        let generation = UUID()
        importPreparationGeneration = generation
        isPreparingImport = true
        importPreparationTask = Task { @MainActor in
            let didAccess = url.startAccessingSecurityScopedResource()
            defer { if didAccess { url.stopAccessingSecurityScopedResource() } }
            do {
                let candidate = try await ChekinanaDataImporter.prepare(from: url)
                var transferred = false
                defer {
                    if !transferred {
                        ChekinanaDataImportTemporaryFiles.cleanup(candidate)
                    }
                }
                try Task.checkCancellation()
                guard importPreparationGeneration == generation, !isImporting else { return }
                preparedImport = candidate
                performImport()
                transferred = true
            } catch is CancellationError {
                // A replacement selection or dismissal intentionally cancels preparation.
            } catch {
                if importPreparationGeneration == generation {
                    importSucceeded = false
                    importFeedback = error.localizedDescription
                }
            }
            if importPreparationGeneration == generation {
                importPreparationGeneration = nil
                importPreparationTask = nil
                isPreparingImport = false
            }
        }
    }

    private func performImport() {
        guard !isImporting, let candidate = preparedImport else { return }
        isImporting = true
        Task { @MainActor in
            defer {
                ChekinanaDataImportTemporaryFiles.cleanup(candidate)
                preparedImport = nil
                isImporting = false
            }
            do {
                try await ChekinanaDataImporter.replaceLocalLibrary(
                    with: candidate,
                    in: modelContext
                )
                importSucceeded = true
                importFeedback = ChekinanaProductCopy.text(
                    "settings.import.success",
                    "Backup imported successfully."
                )
            } catch {
                importSucceeded = false
                importFeedback = error.localizedDescription
            }
        }
    }

    private func cancelImportPreparation() {
        importPreparationGeneration = nil
        importPreparationTask?.cancel()
        importPreparationTask = nil
        isPreparingImport = false
    }

    private func cancelPreparedImport() {
        pendingImportURL = nil
        isImportConfirmationPresented = false
        guard !isImporting else { return }
        ChekinanaDataImportTemporaryFiles.cleanup(preparedImport)
        preparedImport = nil
    }
}

private struct ChekinanaCustomChekiSizeEditor: View {
    @Environment(\.dismiss) private var dismiss
    @Environment(\.modelContext) private var modelContext
    @State private var name = ""
    @State private var widthRatio = ""
    @State private var heightRatio = ""
    @State private var errorMessage: String?

    private var parsedRatios: (width: Double, height: Double)? {
        func parse(_ value: String) -> Double? {
            Double(value.trimmingCharacters(in: .whitespacesAndNewlines)
                .replacingOccurrences(of: ",", with: "."))
        }
        guard let width = parse(widthRatio),
              let height = parse(heightRatio),
              width.isFinite, height.isFinite,
              width > 0, height > 0 else { return nil }
        return (width, height)
    }

    private var pixelDimensions: (width: Int, height: Int)? {
        guard let ratios = parsedRatios else { return nil }
        return ChekinanaCustomChekiSizePolicy.pixelDimensions(
            widthRatio: ratios.width,
            heightRatio: ratios.height
        )
    }

    private var canSave: Bool {
        !name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && parsedRatios != nil && pixelDimensions != nil
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField(
                        ChekinanaProductCopy.text(
                            "settings.cheki_sizes.name",
                            "Name"
                        ),
                        text: $name
                    )
                    .accessibilityIdentifier("chekinana.settings.cheki-sizes.name")
                    HStack(spacing: 10) {
                        TextField(
                            ChekinanaProductCopy.text(
                                "settings.cheki_sizes.width",
                                "Width"
                            ),
                            text: $widthRatio
                        )
                        .keyboardType(.decimalPad)
                        .multilineTextAlignment(.trailing)
                        Text(":")
                        TextField(
                            ChekinanaProductCopy.text(
                                "settings.cheki_sizes.height",
                                "Height"
                            ),
                            text: $heightRatio
                        )
                        .keyboardType(.decimalPad)
                        .multilineTextAlignment(.leading)
                    }
                    .accessibilityElement(children: .contain)
                    .accessibilityIdentifier("chekinana.settings.cheki-sizes.ratio")
                } header: {
                    Text(
                        ChekinanaProductCopy.text(
                            "settings.cheki_sizes.details",
                            "Size details"
                        )
                    )
                } footer: {
                    Text(
                        ChekinanaProductCopy.text(
                            "settings.cheki_sizes.rule",
                            "The shorter edge is fixed at 1200 px, and the longest edge may not exceed 8192 px."
                        )
                    )
                }

                Section(
                    ChekinanaProductCopy.text(
                        "settings.cheki_sizes.preview",
                        "Preview"
                    )
                ) {
                    preview
                        .frame(maxWidth: .infinity, minHeight: 190)
                        .accessibilityIdentifier("chekinana.settings.cheki-sizes.preview")
                }
            }
            .navigationTitle(
                ChekinanaProductCopy.text(
                    "settings.cheki_sizes.add",
                    "Add new size"
                )
            )
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button(ChekinanaProductCopy.text("common.cancel", "Cancel")) {
                        dismiss()
                    }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button(ChekinanaProductCopy.text("common.save", "Save"), action: save)
                        .disabled(!canSave)
                        .accessibilityIdentifier("chekinana.settings.cheki-sizes.save")
                }
            }
            .alert(
                ChekinanaProductCopy.text("common.error", "Error"),
                isPresented: Binding(
                    get: { errorMessage != nil },
                    set: { if !$0 { errorMessage = nil } }
                )
            ) {
                Button(ChekinanaProductCopy.text("common.ok", "OK"), role: .cancel) {}
            } message: {
                Text(errorMessage ?? "")
            }
        }
        .chekinanaSheetDraftDismiss(
            snapshot: { [AnyHashable(name), AnyHashable(widthRatio), AnyHashable(heightRatio)] }
        )
    }

    @ViewBuilder
    private var preview: some View {
        if let dimensions = pixelDimensions {
            GeometryReader { proxy in
                let availableWidth = max(1, proxy.size.width - 64)
                let availableHeight = max(1, proxy.size.height - 50)
                let scale = min(
                    availableWidth / CGFloat(dimensions.width),
                    availableHeight / CGFloat(dimensions.height)
                )
                let width = CGFloat(dimensions.width) * scale
                let height = CGFloat(dimensions.height) * scale
                ZStack {
                    RoundedRectangle(cornerRadius: 6)
                        .fill(ChekinanaProductTheme.softAccent)
                        .overlay {
                            RoundedRectangle(cornerRadius: 6)
                                .stroke(ChekinanaProductTheme.accent, lineWidth: 2)
                        }
                        .frame(width: width, height: height)
                    Text(ChekinanaL10n.message("\(dimensions.width) px"))
                        .font(.caption.monospacedDigit())
                        .offset(y: -(height / 2 + 17))
                    Text(ChekinanaL10n.message("\(dimensions.height) px"))
                        .font(.caption.monospacedDigit())
                        .rotationEffect(.degrees(-90))
                        .offset(x: width / 2 + 24)
                }
                .frame(maxWidth: .infinity, maxHeight: .infinity)
            }
        } else if parsedRatios != nil {
            Text(
                ChekinanaProductCopy.text(
                    "settings.cheki_sizes.too_large",
                    "The longest edge may not exceed 8192 px."
                )
            )
            .foregroundStyle(.red)
            .frame(maxWidth: .infinity, minHeight: 190)
        } else {
            Text(
                ChekinanaProductCopy.text(
                    "settings.cheki_sizes.preview_hint",
                    "Enter two positive numbers to preview the size."
                )
            )
            .foregroundStyle(.secondary)
            .frame(maxWidth: .infinity, minHeight: 190)
        }
    }

    private func save() {
        guard let ratios = parsedRatios,
              pixelDimensions != nil,
              let normalizedName = name.nonEmpty else { return }
        modelContext.insert(CustomChekiSize(
            name: normalizedName,
            widthRatio: ratios.width,
            heightRatio: ratios.height
        ))
        do {
            try modelContext.save()
            dismiss()
        } catch {
            modelContext.rollback()
            errorMessage = error.localizedDescription
        }
    }
}

struct ChekinanaCalendarCell: Identifiable {
    let date: Date
    let isInDisplayedMonth: Bool
    var id: String { ChekinanaProductDate.key(date) }
}

enum ChekinanaProductDate {
    static let calendar: Calendar = {
        var value = Calendar(identifier: .gregorian)
        value.locale = Locale(identifier: "en_US_POSIX")
        value.timeZone = TimeZone(secondsFromGMT: 0)!
        value.firstWeekday = 1
        return value
    }()

    static var weekdaySymbols: [String] {
        let formatter = DateFormatter()
        formatter.locale = ChekinanaLanguagePreference.displayLocale()
        formatter.calendar = Calendar(identifier: .gregorian)
        return formatter.shortStandaloneWeekdaySymbols
    }

    static var fixtureAwareToday: Date {
#if DEBUG
        if ["data", "mixed-media", "calendar-groups"].contains(
            ProcessInfo.processInfo.environment["CHEKINANA_PRODUCT_UI_FIXTURE"]
        ) {
            return date(year: 2026, month: 8, day: 2)
        }
#endif
        return today
    }

    static var today: Date {
        ChekinanaDateOnly.canonicalDate(from: Date(), displayedIn: .current) ?? Date()
    }

    static func normalized(_ date: Date) -> Date {
        ChekinanaDateOnly.canonicalized(date) ?? date
    }

    static func date(year: Int, month: Int, day: Int) -> Date {
        ChekinanaDateOnly.canonicalDate(year: year, month: month, day: day)!
    }

    static func startOfMonth(containing date: Date) -> Date {
        let components = calendar.dateComponents([.year, .month], from: date)
        return calendar.date(from: components) ?? normalized(date)
    }

    static func monthCells(for month: Date) -> [ChekinanaCalendarCell] {
        let first = startOfMonth(containing: month)
        let weekday = calendar.component(.weekday, from: first)
        let leadingDays = (weekday - calendar.firstWeekday + 7) % 7
        let start = calendar.date(byAdding: .day, value: -leadingDays, to: first) ?? first
        let daysInMonth = calendar.range(of: .day, in: .month, for: first)?.count ?? 31
        let weekCount = max(4, (leadingDays + daysInMonth + 6) / 7)
        return (0..<(weekCount * 7)).compactMap { offset in
            guard let date = calendar.date(byAdding: .day, value: offset, to: start) else { return nil }
            return ChekinanaCalendarCell(
                date: date,
                isInDisplayedMonth: calendar.isDate(date, equalTo: first, toGranularity: .month)
            )
        }
    }

    static func isSameDay(_ lhs: Date?, _ rhs: Date) -> Bool {
        guard let lhs else { return false }
        return calendar.isDate(lhs, inSameDayAs: rhs)
    }

    static func key(_ date: Date) -> String {
        ChekinanaDateOnly.string(date)
    }

    static func string(_ date: Date?) -> String {
        guard let date else { return "" }
        return ChekinanaDateOnly.string(date)
    }

    static func displayString(_ date: Date?) -> String {
        guard let date else {
            return ChekinanaProductCopy.text("common.no_date", "No date")
        }
        return formatted(date, template: "yMMMd")
    }

    static func monthTitle(_ date: Date) -> String { formatted(date, template: "yMMMM") }
    static func longTitle(_ date: Date) -> String { formatted(date, template: "MMMMdEEEE") }
    static func accessibilityDate(_ date: Date) -> String { formatted(date, template: "yMMMMd") }

    /// DatePicker wheels render in the current system time zone. Keep the row
    /// summary and VoiceOver value on the same UI boundary without changing
    /// the UTC date-only carrier used for persistence.
    static func wheelDisplayString(
        _ date: Date,
        timeZone: TimeZone = .current
    ) -> String {
        formatted(date, template: "yMMMd", timeZone: timeZone)
    }

    static func wheelWeekdayString(
        _ date: Date,
        calendar: Calendar = .current,
        locale: Locale? = nil
    ) -> String {
        let formatter = DateFormatter()
        formatter.locale = locale ?? ChekinanaLanguagePreference.displayLocale()
        formatter.calendar = calendar
        formatter.timeZone = calendar.timeZone
        formatter.dateFormat = "EEEE"
        return formatter.string(from: date)
    }

    static func wheelAccessibilityDate(
        _ date: Date,
        timeZone: TimeZone = .current
    ) -> String {
        formatted(date, template: "yMMMMd", timeZone: timeZone)
    }
    static func dayNumber(
        _ date: Date,
        locale: Locale? = nil
    ) -> String {
        calendar.component(.day, from: date).formatted(
            .number
                .locale(locale ?? ChekinanaLanguagePreference.displayLocale())
                .grouping(.never)
        )
    }

    private static func formatted(_ date: Date, template: String) -> String {
        formatted(date, template: template, timeZone: calendar.timeZone)
    }

    private static func formatted(
        _ date: Date,
        template: String,
        timeZone: TimeZone
    ) -> String {
        let formatter = DateFormatter()
        formatter.locale = ChekinanaLanguagePreference.displayLocale()
        var displayCalendar = Calendar(identifier: .gregorian)
        displayCalendar.locale = ChekinanaLanguagePreference.displayLocale()
        displayCalendar.timeZone = timeZone
        formatter.calendar = displayCalendar
        formatter.timeZone = timeZone
        formatter.setLocalizedDateFormatFromTemplate(template)
        return formatter.string(from: date)
    }
}

private enum ChekinanaProductColor {
    static func color(for value: String?) -> Color {
        guard let normalized = ChekinanaIdolEditorColorPolicy.recognizedValue(value),
              let rgb = ChekinanaIdolPalette.rgb(for: normalized) else {
            return Color(uiColor: .systemGray3)
        }
        return Color(
            red: Double(rgb.red) / 255,
            green: Double(rgb.green) / 255,
            blue: Double(rgb.blue) / 255
        )
    }
}

extension String {
    var nonEmpty: String? {
        let value = trimmingCharacters(in: .whitespacesAndNewlines)
        return value.isEmpty ? nil : value
    }
}

